		[SuspendCriticalValidation]
		public virtual void TestInvoicingBaseTaxRecordParent_RunOnSavingOperations_IsCalledOnSaving()
		{
			SetupForSave();

			var taxParent = TaxFrameworkObjectFactory.GetInvoicingBaseTaxRecordParent(InvoicingBase);

			var recoveryLine1 = ((ITaxRecordParent)taxParent).AddTaxRecoveryLine(InvoicingBase.Lines[0].AL_AC, ZGuid.Empty, InvoicingBase.Lines[0].AL_GB, InvoicingBase.Lines[0].AL_GE, InvoicingBase.Lines[0].AL_RX_NKTransactionCurrency, 10, ZDate.Today, ZGuid.Empty, ZString.Empty);
			var recoveryLine2 = ((ITaxRecordParent)taxParent).AddTaxRecoveryLine(InvoicingBase.Lines[1].AL_AC, ZGuid.Empty, InvoicingBase.Lines[1].AL_GB, InvoicingBase.Lines[1].AL_GE, InvoicingBase.Lines[1].AL_RX_NKTransactionCurrency, 10, ZDate.Today, ZGuid.Empty, ZString.Empty);

			var chargeCreatorMock = new Mock<IChargeCreator>();
			var passedLines = new HashSet<InvoicingLineBase>();
			var passedInvoices = new HashSet<InvoicingBase>();
			chargeCreatorMock.Setup(x => x.CreateChargeFromJobRelatedRevenueLine(It.IsAny<InvoicingLineBase>(), It.IsAny<InvoicingBase>(), It.IsAny<bool>())).Callback((InvoicingLineBase line, InvoicingBase invoice, bool isTaxRecoveryLine) =>
			{
				passedLines.Add(line);
				passedInvoices.Add(invoice);
			});
			taxParent.SubstituteChargeCreator_ForTestOnly(chargeCreatorMock.Object);

			Factory.Save();

			chargeCreatorMock.Verify(x => x.CreateChargeFromJobRelatedRevenueLine(It.IsAny<InvoicingLineBase>(), It.IsAny<InvoicingBase>(), It.IsAny<bool>()), Times.Exactly(2));
			AssertContainsExactElementsInAnyOrder(nameof(passedLines), new[] { recoveryLine1, recoveryLine2 }, passedLines.Select(x => TaxFrameworkObjectFactory.GetInvoicingLineBaseTaxable(x)));
			AssertContainsExactElementsInAnyOrder(nameof(passedInvoices), new[] { InvoicingBase }, passedInvoices);
		}

		public void TestAH_DescSetsTempContextMakingChangesNotAffectingTaxRecordParent()
		{
			InvoicingBase.HasChangesChanged += HasChangesChangeHandler;
			Assert(!Factory.HasContext(BusinessContext.MakingChangesNotAffectingTaxRecordParent));
			var eventHandlerCalled = false;
			InvoicingBase.AH_Desc = "desc";
			Assert(!Factory.HasContext(BusinessContext.MakingChangesNotAffectingTaxRecordParent));
			Assert(eventHandlerCalled);

			void HasChangesChangeHandler(object sender, HasChangesChangedEventArgs e)
			{
				Assert(Factory.HasContext(BusinessContext.MakingChangesNotAffectingTaxRecordParent));
				eventHandlerCalled = true;
			}
		}

		public virtual void TestCopiedFromPK()
		{
			AssertEquals("Precondition: Lines.Count", 2, InvoicingBase.Lines.Count);
			InvoicingBase.Lines[0].AL_OSExTaxAmount = 100;
			InvoicingBase.Lines[1].AL_OSExTaxAmount = 200;
			InvoicingBase.GenerateReverseTransaction(false);
			var reverseInvoice = InvoicingBase.ReverseInvoice;
			reverseInvoice.AH_PostDate = InvoicingBase.AH_PostDate.AddDays(1);
			reverseInvoice.AH_TransactionNum = "Test43254";
			Factory.Save();
			var originalLines = InvoicingBase.Lines.Cast<InvoicingLineBase>().OrderBy(x => Math.Abs(x.AL_OSExTaxAmount)).ToArray();
			var reversalLines = reverseInvoice.Lines.Cast<InvoicingLineBase>().OrderBy(x => Math.Abs(x.AL_OSExTaxAmount)).ToArray();
			CombineAssertions(() =>
			{
				AssertEquals(originalLines[0].PK, reversalLines[0].CopiedFromPK);
				AssertEquals(originalLines[1].PK, reversalLines[1].CopiedFromPK);
			});
		}

		public void TestExistLineWhichRelatedJobIsReadyForFinancialClosureWithoutPostSecurity()
		{
			var cacheValue = Env.Security.AllowPostingChargesforFinancialClosureJob.IsAllowed;

			var shipment = TestObjectCreator.CreateShipment("S0001", true);
			var job = TestObjectCreator.CreateJob(shipment, false);
			job.JH_Status = JobHeaderStatus.Working.Code;
			var shipment1 = TestObjectCreator.CreateShipment("S0002", true);
			var job1 = TestObjectCreator.CreateJob(shipment1, false);
			job1.JH_Status = JobHeaderStatus.Working.Code;
			var shipment2 = TestObjectCreator.CreateShipment("S0003", true);
			var job2 = TestObjectCreator.CreateJob(shipment2, false);
			job2.JH_Status = JobHeaderStatus.JobReadyForFinancialClosure.Code;

			var invoice = (InvoicingBase)Factory.New(typeof(APInvoice));
			var line = (InvoicingLineBase)invoice.Lines.AddNew();
			var line1 = (InvoicingLineBase)invoice.Lines.AddNew();
			var line2 = (InvoicingLineBase)invoice.Lines.AddNew();

			line.AL_JH = job.PK;
			line1.AL_JH = job1.PK;
			line2.AL_JH = Guid.Empty;
			using (new DisposableAction(() => Env.Security.AllowPostingChargesforFinancialClosureJob.IsAllowed = false, () => Env.Security.AllowPostingChargesforFinancialClosureJob.IsAllowed = cacheValue))
			{
				Assert("ExistLineWhichRelatedJobIsReadyForFinancialClosureWithoutPostSecurity Should be false as not exist line which related job's Status is JFC", !invoice.ExistLineWhichRelatedJobIsReadyForFinancialClosureWithoutPostSecurity);
			}

			using (new DisposableAction(() => Env.Security.AllowPostingChargesforFinancialClosureJob.IsAllowed = true, () => Env.Security.AllowPostingChargesforFinancialClosureJob.IsAllowed = cacheValue))
			{
				Assert("ExistLineWhichRelatedJobIsReadyForFinancialClosureWithoutPostSecurity Should be false as not exist line which related job's Status is JFC", !invoice.ExistLineWhichRelatedJobIsReadyForFinancialClosureWithoutPostSecurity);
			}

			line2.AL_JH = job2.PK;
			using (new DisposableAction(() => Env.Security.AllowPostingChargesforFinancialClosureJob.IsAllowed = false, () => Env.Security.AllowPostingChargesforFinancialClosureJob.IsAllowed = cacheValue))
			{
				Assert("ExistLineWhichRelatedJobIsReadyForFinancialClosureWithoutPostSecurity Should be true as related job status of line 3 is JFC and user didn't have security right", invoice.ExistLineWhichRelatedJobIsReadyForFinancialClosureWithoutPostSecurity);
			}

			using (new DisposableAction(() => Env.Security.AllowPostingChargesforFinancialClosureJob.IsAllowed = true, () => Env.Security.AllowPostingChargesforFinancialClosureJob.IsAllowed = cacheValue))
			{
				Assert("ExistLineWhichRelatedJobIsReadyForFinancialClosureWithoutPostSecurity Should be false as related job status of line 3 is JFC but user have security right", !invoice.ExistLineWhichRelatedJobIsReadyForFinancialClosureWithoutPostSecurity);
			}
		}

		public void TestSubTotalAmountsWithGSTOnly()
		{
			InvoicingBase.AH_RX_NKTransactionCurrency = TestObjectCreator.USD.Code;
			InvoicingBase.AH_ExchangeRate = 2M;
			InvoicingBase.AH_OSExTaxAmount = 998M;
			InvoicingBase.AH_OSTaxAmount = 99.80M;
			if (CanSetOtherTaxes)
			{
				InvoicingBase.AH_OSTaxAmountOtherTaxes = 49.90M;
				InvoicingBase.AH_LocalTaxAmountOtherTaxes = 24.95M;
			}
			AssertEquals(1097.8M, InvoicingBase.AH_OSSubTotalAmountWithGSTOnly);
			AssertEquals(548.9M, InvoicingBase.AH_LocalSubTotalAmountWithGSTOnly);
		}

		protected virtual bool CanSetOtherTaxes => true;

		protected override void TestBizObjectField(ZPropertyInfo info)
		{
			//AH_ConsolidatedInvoiceRef value can be set in AH_JobNumber
			//AH_ConsolidatedInvoiceRef is composed of the jobnumber and an additional suffix separated by a slash (S0001020/A)
			//AH_ConsolidatedInvoiceRef max length equals JH_JobNum max length + slash + job number suffix max length = 35 + 1 + 2 = 38
			//AH_JobNumber maxlength is 35 because it contains only the JH_JobNum
			//Here we don't want to throw MaxLength error in unit test when we set 38 chars in AH_JobNumber
			//because it should never happen if the data is good
			if (info.Name == AccTransactionHeaderSchema.AH_ConsolidatedInvoiceRef.Name)
			{
				var invoice = info.BizObj as InvoicingBase;
				var oldLedger = invoice.AH_Ledger;
				invoice.AH_Ledger = LedgerTypes.AccountsPayable;
				base.TestBizObjectField(info);
				invoice.AH_Ledger = oldLedger;
			}
			else
			{
				base.TestBizObjectField(info);
			}
		}

		protected override void AssertRelatedFieldsCountOnOSAndLocalTaxAmountOtherTaxes(bool isEnableNewOSOutstandingAmountFeature)
		{
			base.AssertRelatedFieldsCountOnOSAndLocalTaxAmountOtherTaxes(isEnableNewOSOutstandingAmountFeature);

			InvoicingBase.Lines[1].Delete();
			AssertEquals("Precondition: Ledger", 1, InvoicingBase.Lines.Count);

			InvoicingBase.AH_OSTaxAmountOtherTaxes = 0;
			InvoicingBase.AH_LocalTaxAmountOtherTaxes = 0;

			var jobExchangeRate = 2m;
			var osCurrency = TestObjectCreator.USD;
			var shipment = TestObjectCreator.CreateShipment("S00001100");
			var job = TestObjectCreator.CreateJob(shipment, false);
			TestObjectCreator.SetExchangeRate(job, osCurrency, jobExchangeRate);
			InvoicingBase.AH_RX_NKTransactionCurrency = osCurrency.Code;
			InvoicingBase.Lines[0].AL_JH = job.PK;
			InvoicingBase.Lines[0].AL_OSExTaxAmount = 80;

			InvoicingBase.UseJobExchangeRate = false;
			InvoicingBase.AH_ExchangeRate = 0.8;
			AssertEquals("AH_Calc_OSOutstandingAmount", 80m, InvoicingBase.AH_Calc_OSOutstandingAmount);
			AssertEquals("AH_LocalOutstandingAmount", 100m, InvoicingBase.AH_LocalOutstandingAmount);
			AssertEquals("AH_ExchangeRate", 0.8m, InvoicingBase.AH_ExchangeRate);
			AssertEquals("AL_ExchangeRate", 0.8m, InvoicingBase.Lines[0].AL_ExchangeRate);
			AssertEquals("AL_OSExTaxAmount", 80m, InvoicingBase.Lines[0].AL_OSExTaxAmount);
			AssertEquals("AL_LocalExTaxAmount", 100m, InvoicingBase.Lines[0].AL_LocalExTaxAmount);

			InvoicingBase.AH_OSTaxAmountOtherTaxes = 100 * InvoicingBase.Multiplier_ForTestOnly; //
			InvoicingBase.AH_LocalTaxAmountOtherTaxes = 100 * InvoicingBase.Multiplier_ForTestOnly;
			AssertEquals("AH_Calc_OSOutstandingAmount", 180m, InvoicingBase.AH_Calc_OSOutstandingAmount);
			AssertEquals("AH_LocalOutstandingAmount", 200m, InvoicingBase.AH_LocalOutstandingAmount);
			AssertEquals("Tax Transactions calculated and so these fields are set only after invoice is fully populated and they just update AH_ExchangeRate", 0.9m, InvoicingBase.AH_ExchangeRate);
			AssertEquals("Setting of other tax amounts does not have effect on line AL_ExchangeRate", 0.8m, InvoicingBase.Lines[0].AL_ExchangeRate);
			AssertEquals("AL_OSExTaxAmount", 80m, InvoicingBase.Lines[0].AL_OSExTaxAmount);
			AssertEquals("AL_LocalExTaxAmount", 100m, InvoicingBase.Lines[0].AL_LocalExTaxAmount);

			InvoicingBase.AH_LocalTaxAmountOtherTaxes = 77 * InvoicingBase.Multiplier_ForTestOnly;
			AssertEquals("AH_Calc_OSOutstandingAmount", 180m, InvoicingBase.AH_Calc_OSOutstandingAmount);
			AssertEquals("AH_LocalOutstandingAmount", 177m, InvoicingBase.AH_LocalOutstandingAmount);
			AssertEquals("Tax Transactions calculated and so these fields are set only after invoice is fully populated and they just update AH_ExchangeRate", 1.016949m, InvoicingBase.AH_ExchangeRate);
			AssertEquals("Setting of other tax amounts does not have effect on line AL_ExchangeRate", 0.8m, InvoicingBase.Lines[0].AL_ExchangeRate);
			AssertEquals("AL_OSExTaxAmount", 80m, InvoicingBase.Lines[0].AL_OSExTaxAmount);
			AssertEquals("AL_LocalExTaxAmount", 100m, InvoicingBase.Lines[0].AL_LocalExTaxAmount);

			InvoicingBase.AH_OSTaxAmountOtherTaxes = 77 * InvoicingBase.Multiplier_ForTestOnly;
			AssertEquals("AH_Calc_OSOutstandingAmount", 157m, InvoicingBase.AH_Calc_OSOutstandingAmount);
			AssertEquals("AH_LocalOutstandingAmount", 177m, InvoicingBase.AH_LocalOutstandingAmount);
			AssertEquals("Tax Transactions calculated and so these fields are set only after invoice is fully populated and they just update AH_ExchangeRate", 0.887006m, InvoicingBase.AH_ExchangeRate);
			AssertEquals("Setting of other tax amounts does not have effect on line AL_ExchangeRate", 0.8m, InvoicingBase.Lines[0].AL_ExchangeRate);
			AssertEquals("AL_OSExTaxAmount", 80m, InvoicingBase.Lines[0].AL_OSExTaxAmount);
			AssertEquals("AL_LocalExTaxAmount", 100m, InvoicingBase.Lines[0].AL_LocalExTaxAmount);

			InvoicingBase.AH_LocalTaxAmountOtherTaxes = 100 * InvoicingBase.Multiplier_ForTestOnly;
			AssertEquals("AH_Calc_OSOutstandingAmount", 157m, InvoicingBase.AH_Calc_OSOutstandingAmount);
			AssertEquals("AH_LocalOutstandingAmount", 200m, InvoicingBase.AH_LocalOutstandingAmount);
			AssertEquals("Tax Transactions calculated and so these fields are set only after invoice is fully populated and they just update AH_ExchangeRate", 0.785m, InvoicingBase.AH_ExchangeRate);
			AssertEquals("Setting of other tax amounts does not have effect on line AL_ExchangeRate", 0.8m, InvoicingBase.Lines[0].AL_ExchangeRate);
			AssertEquals("AL_OSExTaxAmount", 80m, InvoicingBase.Lines[0].AL_OSExTaxAmount);
			AssertEquals("AL_LocalExTaxAmount", 100m, InvoicingBase.Lines[0].AL_LocalExTaxAmount);

			if (InvoicingBase.AH_Ledger == LedgerTypes.AccountsPayable && InvoicingBase.IsInvoiceOrCreditNote_ForTestOnly)
			{
				InvoicingBase.UseJobExchangeRate = true;

				AssertEquals("AH_Calc_OSOutstandingAmount", 157m, InvoicingBase.AH_Calc_OSOutstandingAmount);
				AssertEquals("AH_LocalOutstandingAmount", 140m, InvoicingBase.AH_LocalOutstandingAmount);
				AssertEquals("AH_ExchangeRate", 1.121429m, InvoicingBase.AH_ExchangeRate);
				AssertEquals("AL_ExchangeRate", jobExchangeRate, InvoicingBase.Lines[0].AL_ExchangeRate);
				AssertEquals("AL_OSExTaxAmount", 80m, InvoicingBase.Lines[0].AL_OSExTaxAmount);
				AssertEquals("AL_LocalExTaxAmount", 40m, InvoicingBase.Lines[0].AL_LocalExTaxAmount);

				InvoicingBase.AH_OSTaxAmountOtherTaxes = 100 * InvoicingBase.Multiplier_ForTestOnly;
				AssertEquals("AH_Calc_OSOutstandingAmount", 180m, InvoicingBase.AH_Calc_OSOutstandingAmount);
				AssertEquals("AH_LocalOutstandingAmount", 140m, InvoicingBase.AH_LocalOutstandingAmount);
				AssertEquals("Tax Transactions calculated and so these fields are set only after invoice is fully populated and they just update AH_ExchangeRate", 1.285714m, InvoicingBase.AH_ExchangeRate);
				AssertEquals("Setting of other tax amounts does not have effect on line AL_ExchangeRate", jobExchangeRate, InvoicingBase.Lines[0].AL_ExchangeRate);
				AssertEquals("AL_OSExTaxAmount", 80m, InvoicingBase.Lines[0].AL_OSExTaxAmount);
				AssertEquals("AL_LocalExTaxAmount", 40m, InvoicingBase.Lines[0].AL_LocalExTaxAmount);
			}
		}

		public virtual void TestReleaseAllMutexOnInvoiceShouldDisposeLineJobsWithMutex()
		{
			var job1 = TestObjectCreator.CreateJobHeader();
			var job2 = TestObjectCreator.CreateJobHeader();

			//This is to simulate creating a job for the invoice line by importing a consol cost with a shipment without job.
			InvoicingBase.Lines[0].AL_JH = job1.PK;
			InvoicingBase.Lines[0].AL_JH = job2.PK;
			AssertEquals(2, InvoicingBase.LineJobsWithMutex.Count);

			InvoicingBase.ReleaseAllMutexOnInvoice();

			var lineJobsWithMutexList = InvoicingBase.LineJobsWithMutex.ToList();
			AssertEquals("ReleaseAllMutexOnInvoice should also dispose LineJobsWithMutex.", true, lineJobsWithMutexList[0].IsDisposed);
			AssertEquals(true, lineJobsWithMutexList[1].IsDisposed);
		}

		public void TestInvoiceCurrencyType()
		{
			var newInvoice = Factory.NewWithValidTestData(GetExpectedBusinessObjectType()) as InvoicingBase;

			using (AccountingMasterFilesRegistry.Instance.EnableInvoiceCurrencyType.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, false))
			{
				AssertEquals(InvoiceCurrencyType.NotApplicable, newInvoice.InvoiceCurrencyType);
			}

			using (AccountingMasterFilesRegistry.Instance.EnableInvoiceCurrencyType.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				Assert(newInvoice.IsLocalCurrencyTransaction);
				AssertInvoiceCurrencyType(InvoiceCurrencyType.Local);

				newInvoice.AH_RX_NKTransactionCurrency = TestObjectCreator.USD.RX_Code;
				Assert(!newInvoice.IsLocalCurrencyTransaction);
				AssertInvoiceCurrencyType(InvoiceCurrencyType.Foreign);

				void AssertInvoiceCurrencyType(InvoiceCurrencyType value)
				{
					if (newInvoice.AH_Ledger == LedgerTypes.AccountsReceivable)
					{
						AssertEquals(value, newInvoice.InvoiceCurrencyType);
					}
					else
					{
						AssertEquals(InvoiceCurrencyType.NotApplicable, newInvoice.InvoiceCurrencyType);
					}
				}
			}
		}

		public void TestAH_OSTotalAmount_ReadOnly()
		{
			Assert("Source Reference should be enabled only for Portugal", !InvoicingBase.IsSourceReferenceEnabled);
			Assert(InvoicingBase.AH_OSTotalAmountInfo.ReadOnly);

			using (GlbCompany.CurrentCompany.TemporarilySetCountry(Constants.CountryCodes.Portugal))
			{
				InvoicingBase.AH_ComplianceSubType = PortugalComplianceInfo.ComplianceSubTypeCodes.TXM;

				if (InvoicingBase.AH_Ledger == LedgerTypes.AccountsReceivable && new[] { TransactionTypes.Invoice, TransactionTypes.CreditNote }.Contains<string>(InvoicingBase.AH_TransactionType))
				{
					Assert(!InvoicingBase.AH_OSTotalAmountInfo.ReadOnly);
				}
				else
				{
					Assert(InvoicingBase.AH_OSTotalAmountInfo.ReadOnly);
				}
			}
		}

		public void TestGetTransactionNumWhereSourceReferenceIsAlreadyUsed()
		{
			if (InvoicingBase is TransactionPendingAllocation)
			{
				Assert("Test not applicable", true);
			}
			else
			{
				var invoice1 = TestObjectCreator.CreateInvoice(typeof(ARInvoice), "ARINV001", organisation: TestObjectCreator.AALSHI);
				invoice1.AH_ComplianceSubType = PortugalComplianceInfo.ComplianceSubTypeCodes.LCD;
				invoice1.SourceReference = "newRef1";
				Factory.Save();

				var invoice2 = TestObjectCreator.CreateInvoice(typeof(ARInvoice), "ARINV002", organisation: TestObjectCreator.AALSHI);
				invoice2.AH_ComplianceSubType = PortugalComplianceInfo.ComplianceSubTypeCodes.LCD;
				AssertEquals(string.Empty, invoice2.SourceReference);

				var invoice3 = TestObjectCreator.CreateInvoice(typeof(ARInvoice), "ARINV003", organisation: TestObjectCreator.AALSHI);
				invoice3.AH_GC = TestObjectCreator.NonCurrentCompany.PK;
				invoice3.AH_GB = TestObjectCreator.NonCurrentCompany.FirstActiveBranch.PK;
				invoice3.AH_ComplianceSubType = PortugalComplianceInfo.ComplianceSubTypeCodes.LCD;
				invoice3.SourceReference = "newRef2";
				AssertNotEquals(invoice1.AH_GC, invoice3.AH_GC);
				Factory.Save();

				var newInvoice = GetInvoicingBaseBusinessObject(1m);

				Assert("Source Reference should be enabled only for Portugal", !newInvoice.IsSourceReferenceEnabled);
				Assert(!newInvoice.IsInDatabase);

				using (GlbCompany.CurrentCompany.TemporarilySetCountry(CountryCodes.Portugal))
				{
					if (newInvoice.AH_Ledger == LedgerTypes.AccountsReceivable && new[] { TransactionTypes.Invoice, TransactionTypes.CreditNote }.Contains<string>(newInvoice.AH_TransactionType))
					{
						newInvoice.AH_ComplianceSubType = PortugalComplianceInfo.ComplianceSubTypeCodes.TXM;
						Assert(newInvoice.IsSourceReferenceUsed);

						newInvoice.SourceReference = "newRef1";
						AssertEquals(invoice1.AH_TransactionNum, newInvoice.GetTransactionNumWhereSourceReferenceIsAlreadyUsed());

						newInvoice.SourceReference = "newRef2";
						AssertEquals(string.Empty, newInvoice.GetTransactionNumWhereSourceReferenceIsAlreadyUsed());

						newInvoice.SourceReference = string.Empty;
						AssertEquals(string.Empty, newInvoice.GetTransactionNumWhereSourceReferenceIsAlreadyUsed());
					}
					else
					{
						AssertEquals(string.Empty, newInvoice.GetTransactionNumWhereSourceReferenceIsAlreadyUsed());
					}
				}
			}
		}

