		public void TestAH_GB_TaxBranch_ReadOnly()
		{
			using (TestObjectCreator.SetUpTaxBranchRegistry(true))
			{
				TestObjectCreator.ResetSecurityCore();

				AssertTaxBranchReadOnly(true);
				AssertTaxBranchReadOnly(false);

				void AssertTaxBranchReadOnly(bool isTaxApplicable)
				{
					InvoicingBase.AH_OH = ZGuid.Empty;
					InvoicingBase.AH_GB_TaxBranch = GlbBranch.CurrentBranch.PK;
					if (InvoicingBase.AH_Ledger == LedgerTypes.AccountsReceivable)
					{
						TestObjectCreator.TestOrganisation.CompanyData.SetARTaxApplicable(isTaxApplicable);
					}
					else
					{
						TestObjectCreator.TestOrganisation.CompanyData.SetAPTaxApplicable(isTaxApplicable);
					}
					InvoicingBase.AH_OH = TestObjectCreator.TestOrganisation.PK;

					AssertEquals(isTaxApplicable, !InvoicingBase.AH_GB_TaxBranchInfo.ReadOnly);
				}
			}
		}

		public void TestCanApplyTaxBranch()
		{
			InvoicingBase.AH_OH = TestObjectCreator.TestOrganisation.PK;
			TestObjectCreator.TestOrganisation.CompanyData.SetARTaxApplicable(false);
			TestObjectCreator.TestOrganisation.CompanyData.SetAPTaxApplicable(false);
			if (InvoicingBase.AH_Ledger == LedgerTypes.AccountsReceivable)
			{
				TestObjectCreator.TestOrganisation.CompanyData.SetARTaxApplicable(true);
			}
			else
			{
				TestObjectCreator.TestOrganisation.CompanyData.SetAPTaxApplicable(true);
			}

			GlbCompany.CurrentCompany.GC_IsGSTRegistered = false;

			AccountingMasterFilesRegistry.Instance.EnableTaxBranchReporting.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, false);
			AssertEquals(false, InvoicingBase.CanApplyTaxBranch);

			AccountingMasterFilesRegistry.Instance.EnableTaxBranchReporting.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);
			AssertEquals(false, InvoicingBase.CanApplyTaxBranch);

			GlbCompany.CurrentCompany.GC_IsGSTRegistered = true;

			AccountingMasterFilesRegistry.Instance.EnableTaxBranchReporting.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, false);
			AssertEquals(false, InvoicingBase.CanApplyTaxBranch);

			AccountingMasterFilesRegistry.Instance.EnableTaxBranchReporting.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);
			AssertEquals(true, InvoicingBase.CanApplyTaxBranch);

			TestObjectCreator.TestOrganisation.CompanyData.SetARTaxApplicable(false);
			TestObjectCreator.TestOrganisation.CompanyData.SetAPTaxApplicable(false);
			AssertEquals(false, InvoicingBase.CanApplyTaxBranch);
		}

		public void TestAH_TransactionReference_ComplianceDocumentNumberProvider()
		{
			var mockIComplianceDocumentNumberProvider = new Mock<IComplianceDocumentNumberProvider>();
			mockIComplianceDocumentNumberProvider.Setup(x => x.GetComplianceDocumentNumbers(It.IsAny<InvoicingLineBaseCollection>())).Returns(new List<ZString> { "aaa", "bbb" });

			var mockIAccountingCountryFactory = new Mock<IAccountingCountryFactory>();
			mockIAccountingCountryFactory.As<IInstanceProvider<IComplianceDocumentNumberProvider>>().Setup(x => x.Get()).Returns(mockIComplianceDocumentNumberProvider.Object);

			var mockIGlobalAccountingCountryFactory = new Mock<IGlobalAccountingCountryFactory>();
			mockIGlobalAccountingCountryFactory.Setup(x => x.GetCountryFactory(It.IsAny<ZString>())).Returns(mockIAccountingCountryFactory.Object);

			using (ObjectFactory.Substitute(mockIGlobalAccountingCountryFactory.Object))
			{
				var header = TestObjectCreator.CreateARInvoice<ARInvoice>("INV001", TestObjectCreator.AUD, 1m, TestObjectCreator.Debtor);
				var complianceDocumentNumber = header.AH_TransactionReference;
				AssertEquals(2,complianceDocumentNumber.Split(',').Length);
				AssertContains("aaa,bbb", complianceDocumentNumber);
			}
		}

		public override void TestAH_RX_NKTransactionCurrency()
		{
			Header.AH_RX_NKTransactionCurrency = ZString.Empty;
			AssertEquals("LocalExTaxAmount should be ReadOnly", true, Header.AH_LocalExTaxAmountInfo.ReadOnly);

			Header.AH_RX_NKTransactionCurrency = "NNN";
			AssertEquals("LocalExTaxAmount should be ReadOnly", true, Header.AH_LocalExTaxAmountInfo.ReadOnly);

			Header.AH_RX_NKTransactionCurrency = GlbCompany.CurrentCompany.GC_RX_NKLocalCurrency;
			AssertEquals("LocalExTaxAmount should be ReadOnly", true, Header.AH_LocalExTaxAmountInfo.ReadOnly);

			//not equal to local currency
			Header.AH_RX_NKTransactionCurrency = Factory.LoadTop1<RefCurrency>(new ZQuery(RefCurrencySchema.RX_Code, SQLComparisonOperator.NotEqual, GlbCompany.CurrentCompany.GC_RX_NKLocalCurrency)).RX_Code;
			AssertEquals("LocalExTaxAmount should not be ReadOnly", true, Header.AH_LocalExTaxAmountInfo.ReadOnly);

			Header.IsReverseTransaction = true;
			AssertEquals("LocalExTaxAmount should be ReadOnly", true, Header.AH_LocalExTaxAmountInfo.ReadOnly);

			Header.IsReverseTransaction = false;
			AssertEquals("LocalExTaxAmount should not be ReadOnly", true, Header.AH_LocalExTaxAmountInfo.ReadOnly);

			Header.AH_ExchangeRate = 1m;
			Factory.Save();
			AssertEquals("LocalExTaxAmount should be ReadOnly", true, Header.AH_LocalExTaxAmountInfo.ReadOnly);
		}

		public void TestExpectedInvoiceTotalValidationIsSuspendedUsingSuspender()
		{
			var newInvoice = (InvoicingBase)GetNewBusinessObject();

			AssertEquals(false, newInvoice.IsSuspendingExpectedInvoiceTotalValidation);

			using (newInvoice.SuspendExpectedInvoiceTotalValidation)
			{
				AssertEquals(true, newInvoice.IsSuspendingExpectedInvoiceTotalValidation);
			}

			AssertEquals(false, newInvoice.IsSuspendingExpectedInvoiceTotalValidation);
		}

