		void SetUpSubAccountsForAccGLHeader(AccGLHeader glheader)
		{
			TestObjectCreator.CreateGLHeaderSubAccount(glheader, OrgHeaderSchema.Constants.Prefix, true);
			TestObjectCreator.CreateGLHeaderSubAccount(glheader, AccGroupsSchema.Constants.Prefix, true);
			TestObjectCreator.CreateGLHeaderSubAccount(glheader, GlbGroupSchema.Constants.Prefix, true);
			TestObjectCreator.CreateGLHeaderSubAccount(glheader, GlbStaffSchema.Constants.Prefix, true);
			TestObjectCreator.CreateGLHeaderSubAccount(TestObjectCreator.GLJournalClearingAccount, GlbStaffSchema.Constants.Prefix, true);
		}

		void SetUpSubAccountsForInvoicingLine(InvoicingLineBase line)
		{
			line.SubAccounts.Cast<AccTransactionLineSubAccount>().First(x => x.AL1_SubClassParentTableCode == OrgHeaderSchema.Constants.Prefix).AL1_SubClassParentId = TestObjectCreator.ABIGAS.PK;
			line.SubAccounts.Cast<AccTransactionLineSubAccount>().First(x => x.AL1_SubClassParentTableCode == AccGroupsSchema.Constants.Prefix).AL1_SubClassParentId = TestObjectCreator.AR1.PK;
			line.SubAccounts.Cast<AccTransactionLineSubAccount>().First(x => x.AL1_SubClassParentTableCode == GlbGroupSchema.Constants.Prefix).AL1_SubClassParentId = TestObjectCreator.GG1.PK;
		}

		void AssertSubAccountsForGLJournal(GLJournal journal, AccGLHeader glheader)
		{
			var subAccounts = journal.GLJournalLines.Cast<GLJournalLine>().First(x => x.AL_AG == glheader.PK).SubAccounts.Cast<AccTransactionLineSubAccount>();
			Assert(subAccounts.Any(x => x.AL1_SubClassParentTableCode == OrgHeaderSchema.Constants.Prefix && x.AL1_SubClassParentId == TestObjectCreator.ABIGAS.PK));
			Assert(subAccounts.Any(x => x.AL1_SubClassParentTableCode == AccGroupsSchema.Constants.Prefix && x.AL1_SubClassParentId == TestObjectCreator.AR1.PK));
			Assert(subAccounts.Any(x => x.AL1_SubClassParentTableCode == GlbGroupSchema.Constants.Prefix && x.AL1_SubClassParentId == TestObjectCreator.GG1.PK));
			Assert(!subAccounts.Any(x => x.AL1_SubClassParentTableCode == GlbStaffSchema.Constants.Prefix));
		}

