		public void TestCorrectDescriptionsForAPInvoiceMultiPeriodApportionmentJournals()
		{
			TestObjectCreator.CreateTestPeriodsForEntireYear(2020);
			TestObjectCreator.GLHeader1.AG_Description = "GL Header 1";
			Factory.Save();

			var invoice = TestObjectCreator.CreateInvoice(typeof(APInvoice), "001", organisation: TestObjectCreator.Creditor1);

			var line = TestObjectCreator.CreateInvoiceLine(invoice, TestObjectCreator.AUD, 0m, 0m);
			line.AL_AG = TestObjectCreator.GLHeader1.PK;
			line.GenericChargeBizO.VC_Code = "TEST1234";
			line.PeriodApportionmentMethod = PeriodApportionmentMethods.Codes.EquallyOverPeriods;
			line.PeriodClearingGLAccountPK = TestObjectCreator.GLJournalClearingAccount.PK;
			line.PeriodStartDate = new ZDate(2020, 2, 15);
			line.PeriodEndDate = new ZDate(2020, 3, 1);

			var journals = invoice.MultiPeriodApportionmentJournals;
			invoice.UpdateJournalDescriptions();
			var masterJournal = journals[0];

			var expectedMasterJournalHeaderDesc = "MASTER JOURNAL FOR AP INV 001";
			var expectedMasterJournalLineDesc = "MASTER JOURNAL FOR AP INV 001";

			AssertEquals(expectedMasterJournalHeaderDesc, journals[0].AH_Desc);

			foreach (GLJournalLine journalLine in journals[0].GLJournalLines)
			{
				AssertEquals(expectedMasterJournalLineDesc, journalLine.AL_Desc);
			}

			var subJournalOne = journals[1];
			var subJournalOneLineOne = subJournalOne.GLJournalLines[0];
			var subJournalOneLineTwo = subJournalOne.GLJournalLines[1];

			var expectedSubJournalOneHeaderDesc = "Sub Journal For AP INV 001 Period 202002";
			var expectedSubJournalOneLineOneDesc = string.Format(@"GL Header 1
AP INV 001, Organization: ZCreditor1
Charge: TEST1234 GL Account: {0} for period 202002
Amount Cleared To Date: AUD 0 AUD 0
Amount Yet to be Cleared: AUD 0 AUD 0", line.GLHeader.AccountNum);

			var expectedSubJournalOneLineTwoDesc = @"GL CLEARING ACCOUNT
AP INV 001, Organization: ZCreditor1
Charge: TEST1234 GL Account: 6820.00.00 for period 202002
Amount Cleared To Date: AUD 0 AUD 0
Amount Yet to be Cleared: AUD 0 AUD 0";

			AssertEquals(expectedSubJournalOneHeaderDesc, subJournalOne.AH_Desc);
			AssertEquals(expectedSubJournalOneLineOneDesc, subJournalOneLineOne.AL_Desc);
			AssertEquals(expectedSubJournalOneLineTwoDesc, subJournalOneLineTwo.AL_Desc);

			var subjournalTwo = journals[2];
			var subJournalTwoLineOne = subjournalTwo.GLJournalLines[0];
			var subJournalTwoLineTwo = subjournalTwo.GLJournalLines[1];

			var expectedSubJournalTwoHeaderDesc = "Sub Journal For AP INV 001 Period 202003";
			var expectedSubJournalTwoLineOneDesc = string.Format(@"GL Header 1
AP INV 001, Organization: ZCreditor1
Charge: TEST1234 GL Account: {0} for period 202003
Amount Cleared To Date: AUD 0 AUD 0
Amount Yet to be Cleared: AUD 0 AUD 0", line.GLHeader.AccountNum);

			var expectedSubJournalTwoLineTwoDesc = @"GL CLEARING ACCOUNT
AP INV 001, Organization: ZCreditor1
Charge: TEST1234 GL Account: 6820.00.00 for period 202003
Amount Cleared To Date: AUD 0 AUD 0
Amount Yet to be Cleared: AUD 0 AUD 0";

			AssertEquals(expectedSubJournalTwoHeaderDesc, subjournalTwo.AH_Desc);
			AssertEquals(expectedSubJournalTwoLineOneDesc, subJournalTwoLineOne.AL_Desc);
			AssertEquals(expectedSubJournalTwoLineTwoDesc, subJournalTwoLineTwo.AL_Desc);
		}

