		[TestDate(2020, 12, 21)]
		public void TestCreatePeriodApportionmentJournalWithSubAccounts()
		{
			TestCaseHelper.ClearTable(AccPeriodManagementSchema.Constants.TableName);
			var periodManagementTestHelper = new AccountingPeriodTestHelper();
			periodManagementTestHelper.PostPeriodsForEntireYear(2020, GlbCompany.CurrentCompany.PK, AccountingPeriodTestHelper.CalendarType.CalendarYear);
			SetUpSubAccountsForAccGLHeader(TestObjectCreator.GLHeader1);
			Factory.Save();

			var type = GetExpectedBusinessObjectType();
			var invoice = TestObjectCreator.CreateInvoice(type, organisation: TestObjectCreator.Creditor1);
			if (invoice.SupportMultiPeriodApportionment)
			{
				var line = TestObjectCreator.CreateInvoiceLine(invoice, TestObjectCreator.AUD, 1M, 200M);
				line.AL_AG = TestObjectCreator.GLHeader1.PK;
				line.PeriodApportionmentMethod = PeriodApportionmentMethods.Codes.EquallyOverPeriods;

				line.PeriodClearingGLAccountPK = TestObjectCreator.GLJournalClearingAccount.PK;
				AssertHasWarning(line.PeriodClearingGLAccountPKInfo, "This Clearing Account has 1 sub account type(s). You can specify the sub accounts value by editing the GL Journals in Manage > General Ledger > Journals module on posting of the Expense/Revenue Apportionment.");

				line.PeriodStartDate = new ZDate(2020, 2, 15);
				line.PeriodEndDate = new ZDate(2020, 4, 29);
				SetUpSubAccountsForInvoicingLine(line);
				AssertEquals(4, invoice.MultiPeriodApportionmentJournals.Count);
				Factory.Save();

				var journals = Factory.Load<GLJournal>(new ZQuery(AccTransactionHeaderSchema.AH_TransactionBelongsToGroup, invoice.PK));
				var masterJournal = journals.First(x => x.AH_Desc.StartsWith("MASTER JOURNAL"));
				var subJournal1 = journals.First(x => x.AH_Desc.EndsWith("202002"));
				var subJournal2 = journals.First(x => x.AH_Desc.EndsWith("202003"));
				var subJournal3 = journals.First(x => x.AH_Desc.EndsWith("202004"));

				AssertSubAccountsForGLJournal(masterJournal, TestObjectCreator.GLHeader1);
				AssertSubAccountsForGLJournal(subJournal1, TestObjectCreator.GLHeader1);
				AssertSubAccountsForGLJournal(subJournal2, TestObjectCreator.GLHeader1);
				AssertSubAccountsForGLJournal(subJournal3, TestObjectCreator.GLHeader1);
			}
			else
			{
				Assert(string.Format("Expect no support for transaction type {0}", invoice.TransactionType_ForTestOnly), !invoice.SupportMultiPeriodApportionment);
			}
		}

