		void AssertMultiplePeriodApportionmentJournals(InvoicingBase invoice,
							ZGuid masterJournalBranchPK, ZGuid masterJournalDepartmentPK, ZDecimal masterCRLineLocalAmount, ZDecimal masterCRLineOSAmount, ZDecimal masterDRLineLocalAmount, ZDecimal masterDRLineOSAmount, ZGuid masterCRLineAccount, ZGuid masterDRLineAccount,
							string subJournal1Period, ZGuid subJournal1BranchPK, ZGuid subJournal1DepartmentPK, ZDecimal sub1CRLineLocalAmount, ZDecimal sub1CRLineOSAmount, ZDecimal sub1DRLineLocalAmount, ZDecimal sub1DRLineOSAmount, ZGuid sub1CRLineAccount, ZGuid sub1DRLineAccount, ZString sub1CRLineDescription, ZString sub1DRLineDescription,
							string subJournal2Period, ZGuid subJournal2BranchPK, ZGuid subJournal2DepartmentPK, ZDecimal sub2CRLineLocalAmount, ZDecimal sub2CRLineOSAmount, ZDecimal sub2DRLineLocalAmount, ZDecimal sub2DRLineOSAmount, ZGuid sub2CRLineAccount, ZGuid sub2DRLineAccount, ZString sub2CRLineDescription, ZString sub2DRLineDescription,
							string subJournal3Period, ZGuid subJournal3BranchPK, ZGuid subJournal3DepartmentPK, ZDecimal sub3CRLineLocalAmount, ZDecimal sub3CRLineOSAmount, ZDecimal sub3DRLineLocalAmount, ZDecimal sub3DRLineOSAmount, ZGuid sub3CRLineAccount, ZGuid sub3DRLineAccount, ZString sub3CRLineDescription, ZString sub3DRLineDescription)
		{
			var journals = Factory.Load<GLJournal>(new ZQuery(AccTransactionHeaderSchema.AH_TransactionBelongsToGroup, invoice.PK));
			AssertEquals(4, journals.Length);
			var masterJournal = journals.First(x => x.AH_Desc.StartsWith("MASTER JOURNAL"));
			AssertEquals(invoice.PK, masterJournal.AH_TransactionBelongsToGroup);
			AssertEquals(masterJournalBranchPK, masterJournal.AH_GB);
			AssertEquals(masterJournalDepartmentPK, masterJournal.AH_GE);
			AssertEquals(2, masterJournal.GLJournalLines.Count);
			var crLine = masterJournal.GLJournalLines.Cast<GLJournalLine>().First(x => x.DebitCreditSign == "CR");
			var drLine = masterJournal.GLJournalLines.Cast<GLJournalLine>().First(x => x.DebitCreditSign == "DR");
			AssertEquals(masterCRLineLocalAmount, crLine.AL_LineAmount);
			AssertEquals(masterDRLineLocalAmount, drLine.AL_LineAmount);
			AssertEquals(masterCRLineOSAmount, crLine.AL_OSAmount);
			AssertEquals(masterDRLineOSAmount, drLine.AL_OSAmount);
			AssertEquals(masterCRLineAccount, crLine.AL_AG);
			AssertEquals(masterDRLineAccount, drLine.AL_AG);

			var subJournal1 = journals.First(x => x.AH_Desc.EndsWith(subJournal1Period));
			AssertEquals(invoice.PK, subJournal1.AH_TransactionBelongsToGroup);
			AssertEquals(subJournal1BranchPK, subJournal1.AH_GB);
			AssertEquals(subJournal1DepartmentPK, subJournal1.AH_GE);
			AssertEquals(2, subJournal1.GLJournalLines.Count);
			crLine = subJournal1.GLJournalLines.Cast<GLJournalLine>().First(x => x.DebitCreditSign == "CR");
			drLine = subJournal1.GLJournalLines.Cast<GLJournalLine>().First(x => x.DebitCreditSign == "DR");
			AssertEquals(sub1CRLineLocalAmount, crLine.AL_LineAmount);
			AssertEquals(sub1CRLineOSAmount, crLine.AL_OSAmount);
			AssertEquals(sub1DRLineLocalAmount, drLine.AL_LineAmount);
			AssertEquals(sub1DRLineOSAmount, drLine.AL_OSAmount);
			AssertEquals(sub1CRLineAccount, crLine.AL_AG);
			AssertEquals(sub1DRLineAccount, drLine.AL_AG);
			AssertEquals(sub1CRLineDescription, crLine.AL_Desc);
			AssertEquals(sub1DRLineDescription, drLine.AL_Desc);

			var subJournal2 = journals.First(x => x.AH_Desc.EndsWith(subJournal2Period));
			AssertEquals(invoice.PK, subJournal2.AH_TransactionBelongsToGroup);
			AssertEquals(subJournal2BranchPK, subJournal2.AH_GB);
			AssertEquals(subJournal2DepartmentPK, subJournal2.AH_GE);
			AssertEquals(2, subJournal2.GLJournalLines.Count);
			crLine = subJournal2.GLJournalLines.Cast<GLJournalLine>().First(x => x.DebitCreditSign == "CR");
			drLine = subJournal2.GLJournalLines.Cast<GLJournalLine>().First(x => x.DebitCreditSign == "DR");
			AssertEquals(sub2CRLineLocalAmount, crLine.AL_LineAmount);
			AssertEquals(sub2CRLineOSAmount, crLine.AL_OSAmount);
			AssertEquals(sub2DRLineLocalAmount, drLine.AL_LineAmount);
			AssertEquals(sub2DRLineOSAmount, drLine.AL_OSAmount);
			AssertEquals(sub2CRLineAccount, crLine.AL_AG);
			AssertEquals(sub2DRLineAccount, drLine.AL_AG);
			AssertEquals(sub2CRLineDescription, crLine.AL_Desc);
			AssertEquals(sub2DRLineDescription, drLine.AL_Desc);

			var subJournal3 = journals.First(x => x.AH_Desc.EndsWith(subJournal3Period));
			AssertEquals(invoice.PK, subJournal3.AH_TransactionBelongsToGroup);
			AssertEquals(subJournal3BranchPK, subJournal3.AH_GB);
			AssertEquals(subJournal3DepartmentPK, subJournal3.AH_GE);
			AssertEquals(2, subJournal3.GLJournalLines.Count);
			crLine = subJournal3.GLJournalLines.Cast<GLJournalLine>().First(x => x.DebitCreditSign == "CR");
			drLine = subJournal3.GLJournalLines.Cast<GLJournalLine>().First(x => x.DebitCreditSign == "DR");
			AssertEquals(sub3CRLineLocalAmount, crLine.AL_LineAmount);
			AssertEquals(sub3CRLineOSAmount, crLine.AL_OSAmount);
			AssertEquals(sub3DRLineLocalAmount, drLine.AL_LineAmount);
			AssertEquals(sub3DRLineOSAmount, drLine.AL_OSAmount);
			AssertEquals(sub3CRLineAccount, crLine.AL_AG);
			AssertEquals(sub3DRLineAccount, drLine.AL_AG);
			AssertEquals(sub3CRLineDescription, crLine.AL_Desc);
			AssertEquals(sub3DRLineDescription, drLine.AL_Desc);
		}

		public void TestSupportMultiPeriodApportionment()
		{
			var type = GetExpectedBusinessObjectType();
			var invoice = TestObjectCreator.CreateInvoice(type, organisation: TestObjectCreator.Creditor1);

			if (invoice.SupportHeaderReference_ForTestOnly)
			{
				Assert(string.Format("Expect has support for transaction type {0}", invoice.TransactionType_ForTestOnly), invoice.SupportMultiPeriodApportionment);
			}
			else
			{
				Assert(string.Format("Expect no support for transaction type {0}", invoice.TransactionType_ForTestOnly), !invoice.SupportMultiPeriodApportionment);
			}
		}

		#endregion

		public virtual void TestIsBeingCreatedPostedAllocatedApprovedOrIncomplete()
		{
			Assert(!InvoicingBase.IsInDatabase);
			Assert("Is being created", InvoicingBase.IsBeingCreatedPostedAllocatedApprovedOrIncomplete);

			Factory.Save();
			Assert("Is not being created", !InvoicingBase.IsBeingCreatedPostedAllocatedApprovedOrIncomplete);

			var type = GetExpectedBusinessObjectType();
			if (type == typeof(APInvoice) || type == typeof(APCreditNote) || type == typeof(APAdjustmentNote))
			{
				var invoice = TestObjectCreator.CreateInvoice(type, organisation: TestObjectCreator.Creditor1);
				TestObjectCreator.CreateInvoiceLine(invoice, 100);

				invoice.SaveAsIncomplete();
				invoice.Factory.Save();
				Assert("Is incomplete", invoice.IsBeingCreatedPostedAllocatedApprovedOrIncomplete);
			}
			else if (type == typeof(TransactionPendingAllocation))
			{
				var transaction = TestObjectCreator.CreateTransactionPendingAllocation("INV", TestObjectCreator.Creditor1, 100);
				Factory.Save();

				var invoiceTransaction = TransactionAllocationConverter.ConvertUnallocatedToAP(transaction).Invoice;
				Assert("Is being allocated", invoiceTransaction.IsBeingCreatedPostedAllocatedApprovedOrIncomplete);
			}
		}

		public virtual void TestRemoveJobsCreatedButNotRequiredForPostingDisposeJobProperly()
		{
			var shipment = TestObjectCreator.CreateShipment("S0001", true);
			var job = new JobHeader.Loader(shipment).TryCreateWithMutex(GlbBranch.CurrentBranch);
			AssertNotNull(job);
			var jobMutex = JobHeader.GetMutex_ForTestOnly(shipment.PK);
			AssertNotNull(jobMutex);

			var invoice = (InvoicingBase)Factory.New(InvoicingBase.GetType());
			var line = (InvoicingLineBase)invoice.Lines.AddNew();
			line.AL_JH = job.PK;
			line.AL_JH = ZGuid.Empty;

			Assert(!job.IsDeleted);
			Assert(jobMutex.IsLocked);

			invoice.RemoveNotRequiredJobsAndChargesFromCostsAndLines();

			Assert(job.IsDeleted);
			Assert(!jobMutex.IsLocked);
		}

