		void AssertCostManuallyEntered(bool isregistryDefault, bool isUseJobExRateFlagTicked, bool isHeaderForeign)
		{
			var postingExRateRegistry = PostingExRateRegistryAP;
			GlbCompany.CurrentCompany.AccExchangeRateConfigurations.SetExRate(LedgerTypes.AccountsPayable, JobInvoicingConsumerTypes.ForwardingConsol.Code, Constants.TransportModes.All, Constants.FreightShipmentDirection.Code.All, Constants.ExchangeRateTypes.Code.SellRate, Constants.JobBillingExchangeRatePreference.Code.TodaysRate, 0, true);
			GlbCompany.CurrentCompany.Factory.Save();

			var invoiceDate = ZDateTime.Today.AddDays(2);
			var usdSellRate = 0.78m;
			var usdBuyRate = 1.23m;
			var usdSellRateForInvoiceDate = 2.34m;
			var usdBuyRateForInvoiceDate = 1.87m;
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, Constants.ExchangeRateTypes.Code.SellRate, usdSellRate, ZDateTime.Today.AddDays(-1), ZDateTime.Today.AddDays(1));
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, Constants.ExchangeRateTypes.Code.BuyRate, usdBuyRate, ZDateTime.Today.AddDays(-1), ZDateTime.Today.AddDays(1));
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, Constants.ExchangeRateTypes.Code.BuyRate, usdBuyRateForInvoiceDate, invoiceDate, invoiceDate);
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, Constants.ExchangeRateTypes.Code.SellRate, usdSellRateForInvoiceDate, invoiceDate, invoiceDate);
			var consol = TestObjectCreator.CreateConsol();
			var shipment = TestObjectCreator.CreateShipment("S00002000", consol);
			var job = TestObjectCreator.CreateJob(shipment, createWithMutex: false);
			Factory.Save();

			var registryValue = isregistryDefault ? AccountingConstants.InvoicePostingExchangeRateOption.Default.Code : AccountingConstants.InvoicePostingExchangeRateOption.ExchangeRateBasedOnInvoiceDate.Code;
			var invoiceCurrency = isHeaderForeign ? TestObjectCreator.USD : TestObjectCreator.AUD;
			var expectedHeaderExRate = isHeaderForeign ? (isUseJobExRateFlagTicked ? 1m : (isregistryDefault ? usdBuyRate : usdBuyRateForInvoiceDate)) : 1m;
			var expectedConsolCostExRate = isregistryDefault ?
				(isUseJobExRateFlagTicked ? usdSellRate : (isHeaderForeign ? expectedHeaderExRate : usdBuyRate)) :
				(isUseJobExRateFlagTicked ? usdSellRateForInvoiceDate : (isHeaderForeign ? expectedHeaderExRate : usdBuyRateForInvoiceDate));

			using (AccountingConfigurationRegistry.Instance.AllowForwardDatingofAPInvoiceDate.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true))
			using (postingExRateRegistry.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, registryValue))
			{
				var invoice = TestObjectCreator.CreateInvoice(typeof(APInvoice), invoiceCurrency, organisation: TestObjectCreator.Creditor1, invoiceDate: invoiceDate);
				invoice.AH_PostedToEFT = isUseJobExRateFlagTicked;
				AssertEquals(expectedHeaderExRate, invoice.AH_ExchangeRate);

				ExchangeRateReader.GetReaderInstance().ClearCache();
				var manuallyEnteredCost = invoice.ConsolCosting.ConsolCosts.AddNew();
				if (!isHeaderForeign)
				{
					manuallyEnteredCost.E6_RX_NKCurrency = TestObjectCreator.USD.RX_Code;
				}
				manuallyEnteredCost.E6_AC_ChargeCode = TestObjectCreator.CC1.PK;
				manuallyEnteredCost.E6_ParentID = consol.PK;
				manuallyEnteredCost.E6_OSCostAmount = 100m;

				/**
				*INV, ticked, header USD, consol cost USD - todays BUY rate - change - rate for date
				*INV, not ticked, header AUD, consol cost USD - todays BUY rate  - change - BUY rate for date
				*DEF, ticked, header USD, consol cost USD - todays BUY rate - change - rate for date

				*INV, not ticked, header USD, consol cost USD - rate for date/header rate - no change
				*DEF, not ticked, header USD, consol cost USD - today's BUY rate - no change
				*DEF, not ticked, header AUD, consol cost USD - today's BUY rate - no change

				*INV, ticked, header USD, consol cost EUR - not possible
				*INV, ticked, header USD, consol cost AUD - not possible
				*INV, not ticked, header USD, consol cost EUR - not possible
				*INV, not ticked, header USD, consol cost AUD - not possible
				*DEF, ticked, header USD, consol cost EUR - not possible
				*DEF, ticked, header USD, consol cost AUD - not possible
				*DEF, not ticked, header USD, consol cost EUR - not possible
				*DEF, not ticked, header USD, consol cost AUD - not possible
				 * */
				AssertEquals(expectedConsolCostExRate, manuallyEnteredCost.E6_ExchangeRate);

				invoice.SubmittedFromInvoicingForm = true;
				invoice.ImportAllApportionmentsFromCosting();

				AssertEquals(1, invoice.Lines.Count);
				AssertEquals(expectedConsolCostExRate, invoice.Lines[0].AL_ExchangeRate);
			}
		}

		void AssertCostImported(bool isregistryDefault, bool isUseJobExRateFlagTicked, bool isHeaderForeign, bool isConsolCostForeign, bool isHeaderAndConsolCostSameCurrency, bool doesConsolCostHaveCreditor)
		{
			var postingExRateRegistry = PostingExRateRegistryAP;
			GlbCompany.CurrentCompany.AccExchangeRateConfigurations.SetExRate(LedgerTypes.AccountsPayable, JobInvoicingConsumerTypes.ForwardingConsol.Code, Constants.TransportModes.All, Constants.FreightShipmentDirection.Code.All, Constants.ExchangeRateTypes.Code.SellRate, Constants.JobBillingExchangeRatePreference.Code.TodaysRate, 0, true);
			GlbCompany.CurrentCompany.Factory.Save();

			TestObjectCreator.Creditor1.CompanyData.AccAPExchangeRateConfigurations.SetExRate(LedgerTypes.AccountsPayable, JobInvoicingConsumerTypes.ForwardingConsol.Code, Constants.TransportModes.All, Constants.FreightShipmentDirection.Code.All, Constants.ExchangeRateTypes.Code.CustomsRate, Constants.JobBillingExchangeRatePreference.Code.TodaysRate, 0, true);

			var invoiceDate = ZDateTime.Today.AddDays(2);
			var usdSellRate = 0.78m;
			var usdBuyRate = 1.23m;
			var usdCustomRate = 3.11m;
			var usdSellRateForInvoiceDate = 2.34m;
			var usdBuyRateForInvoiceDate = 1.87m;
			var usdCustomRateForInvoiceDate = 3.22m;
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, Constants.ExchangeRateTypes.Code.SellRate, usdSellRate, ZDateTime.Today.AddDays(-1), ZDateTime.Today.AddDays(1));
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, Constants.ExchangeRateTypes.Code.BuyRate, usdBuyRate, ZDateTime.Today.AddDays(-1), ZDateTime.Today.AddDays(1));
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, Constants.ExchangeRateTypes.Code.CustomsRate, usdCustomRate, ZDateTime.Today.AddDays(-1), ZDateTime.Today.AddDays(1));
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, Constants.ExchangeRateTypes.Code.SellRate, usdSellRateForInvoiceDate, invoiceDate, invoiceDate);
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, Constants.ExchangeRateTypes.Code.BuyRate, usdBuyRateForInvoiceDate, invoiceDate, invoiceDate);
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, Constants.ExchangeRateTypes.Code.CustomsRate, usdCustomRateForInvoiceDate, invoiceDate, invoiceDate);

			var eurSellRate = 0.56m;
			var eurBuyRate = 1.99m;
			var eurCustomRate = 3.55m;
			var eurSellRateForInvoiceDate = 2.68m;
			var eurBuyRateForInvoiceDate = 2.99m;
			var eurCustomRateForInvoiceDate = 3.77m;
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.EUR, Constants.ExchangeRateTypes.Code.SellRate, eurSellRate, ZDateTime.Today.AddDays(-1), ZDateTime.Today.AddDays(1));
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.EUR, Constants.ExchangeRateTypes.Code.BuyRate, eurBuyRate, ZDateTime.Today.AddDays(-1), ZDateTime.Today.AddDays(1));
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.EUR, Constants.ExchangeRateTypes.Code.CustomsRate, eurCustomRate, ZDateTime.Today.AddDays(-1), ZDateTime.Today.AddDays(1));
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.EUR, Constants.ExchangeRateTypes.Code.SellRate, eurSellRateForInvoiceDate, invoiceDate, invoiceDate);
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.EUR, Constants.ExchangeRateTypes.Code.BuyRate, eurBuyRateForInvoiceDate, invoiceDate, invoiceDate);
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.EUR, Constants.ExchangeRateTypes.Code.CustomsRate, eurCustomRateForInvoiceDate, invoiceDate, invoiceDate);
			Factory.Save();

			var existingRate = isConsolCostForeign ? 3.498m : 1m;
			var registryValue = isregistryDefault ? AccountingConstants.InvoicePostingExchangeRateOption.Default.Code : AccountingConstants.InvoicePostingExchangeRateOption.ExchangeRateBasedOnInvoiceDate.Code;
			var invoiceCurrency = isHeaderForeign ? TestObjectCreator.USD : TestObjectCreator.AUD;
			var expectedHeaderExRate = isHeaderForeign ? (isUseJobExRateFlagTicked ? 1m : (isregistryDefault ? usdBuyRate : usdBuyRateForInvoiceDate)) : 1m;
			var expectedConsolCostExRate = isConsolCostForeign ?
				(isregistryDefault ? (isUseJobExRateFlagTicked ? ((isHeaderForeign && isHeaderAndConsolCostSameCurrency) ? existingRate : usdCustomRate) : (isHeaderForeign ? expectedHeaderExRate : existingRate)) : (isUseJobExRateFlagTicked ? usdCustomRateForInvoiceDate : (isHeaderForeign ? expectedHeaderExRate : existingRate))) :
				(isregistryDefault ? (isUseJobExRateFlagTicked ? usdCustomRate : (isHeaderForeign ? expectedHeaderExRate : existingRate)) : (isUseJobExRateFlagTicked ? usdCustomRateForInvoiceDate : (isHeaderForeign ? expectedHeaderExRate : existingRate)));
			var consol = TestObjectCreator.CreateConsol();
			TestObjectCreator.CreateShipment("S00002000", consol);
			var consolCostToImport = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC1, 100m, doesConsolCostHaveCreditor ? TestObjectCreator.Creditor1 : null);
			consolCostToImport.E6_RX_NKCurrency = isConsolCostForeign ? (isHeaderForeign ? (isHeaderAndConsolCostSameCurrency ? invoiceCurrency.RX_Code : TestObjectCreator.EUR.RX_Code) : TestObjectCreator.USD.RX_Code) : TestObjectCreator.AUD.RX_Code;
			consolCostToImport.E6_ExchangeRate = existingRate;
			Factory.Save();

			using (AccountingConfigurationRegistry.Instance.AllowForwardDatingofAPInvoiceDate.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true))
			using (postingExRateRegistry.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, registryValue))
			{
				var invoice = TestObjectCreator.CreateInvoice(typeof(APInvoice), invoiceCurrency, organisation: TestObjectCreator.Creditor1, invoiceDate: invoiceDate);
				invoice.AH_PostedToEFT = isUseJobExRateFlagTicked;
				AssertEquals(expectedHeaderExRate, invoice.AH_ExchangeRate);

				var originatingCost = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
				var newFactory = new BusinessObjectFactory();
				var importer = new InvoicingBaseConsolCostImporter(newFactory, originatingCost, invoice);
				ExchangeRateReader.GetReaderInstance().ClearCache();
				importer.ImportCostsIntoCosting(new BusinessObject[] { consolCostToImport });
				AssertEquals(1, invoice.ConsolCosting.ConsolCosts.Count);

				/**
				*INV, ticked, header USD, consol cost USD - copy existing rate - change - rate for date
				*INV, ticked, header USD, consol cost EUR - today's BUY rate - change - rate for date
				*INV, ticked, header USD, consol cost AUD - today's BUY rate - change - rate for date

				*INV, not ticked, header USD, consol cost USD - rate for date/header rate - no change -
				*INV, not ticked, header USD, consol cost EUR - rate for date/header rate - no change
				*INV, not ticked, header USD, consol cost AUD - rate for date/header rate - no change
				*INV, not ticked, header AUD, consol cost USD - copy existing rate - no change
				*DEF, ticked, header USD, consol cost USD - today's rate - no change
				*DEF, ticked, header USD, consol cost EUR - today's rate - no change - still today's rate but accordgin to job billing config rate type
				*DEF, ticked, header USD, consol cost AUD - today's rate - no change - still today's rate but accordgin to job billing config rate type
				*DEF, not ticked, header USD, consol cost USD - header rate - no change
				*DEF, not ticked, header USD, consol cost EUR - header rate - no change
				*DEF, not ticked, header USD, consol cost AUD - header rate - no change
				*DEF, not ticked, header AUD, consol cost USD - copy existing rate  - no change
				* */
				AssertEquals(expectedConsolCostExRate, invoice.ConsolCosting.ConsolCosts[0].E6_ExchangeRate);

				invoice.SubmittedFromInvoicingForm = true;
				invoice.ImportAllApportionmentsFromCosting();

				AssertEquals(1, invoice.Lines.Count);
				AssertEquals(expectedConsolCostExRate, invoice.Lines[0].AL_ExchangeRate);
			}
		}

