		InvoicingBase GetInvoicingBaseBusinessObject(decimal initialExchangeRate, string registryValue)
		{
			PostingExRateRegistryAP.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, registryValue);
			PostingExRateRegistryAR.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, registryValue);

			var invoice = GetInvoicingBaseBusinessObject(initialExchangeRate);

			return invoice;
		}

		InvoicingBase GetInvoicingBaseBusinessObject(decimal initialExchangeRate)
		{
			var currency = TestObjectCreator.USD;
			TestObjectCreator.CreateExchangeRate(currency, Constants.ExchangeRateTypes.Code.BuyRate, initialExchangeRate, ZDateTime.Today, ZDateTime.Today);
			TestObjectCreator.CreateExchangeRate(currency, Constants.ExchangeRateTypes.Code.SellRate, initialExchangeRate, ZDateTime.Today, ZDateTime.Today);

			var objectType = GetExpectedBusinessObjectType();
			var invoice = TestObjectCreator.CreateInvoice(objectType, currency, initialExchangeRate, organisation: TestObjectCreator.Creditor1);
			TestObjectCreator.CreateInvoiceLine(invoice, TestObjectCreator.CC1.PK, 200M, currency, initialExchangeRate);
			AssertEquals("Initial Exchange Rate", initialExchangeRate, invoice.AH_ExchangeRate);
			Assert("Precondition: AH_PostedToEFT", !invoice.AH_PostedToEFT);

			return invoice;
		}

