		public void TestJobDirectionForSingleJob()
		{
			var expectObject = GetExpectedBusinessObjectType();
			if (expectObject == typeof(ARInvoice) || expectObject == typeof(APInvoice) || expectObject == typeof(ARCreditNote) || expectObject == typeof(APCreditNote))
			{
				var shipment = TestObjectCreator.CreateShipment("S00001001");
				var jobForShipment = TestObjectCreator.CreateJob(shipment);
				Factory.Save();

				var invoice = TestObjectCreator.CreateInvoice(expectObject, TestObjectCreator.AUD, 1);
				invoice.AH_JH = jobForShipment.PK;

				shipment.JS_RL_NKOrigin = "AUSYD";
				shipment.JS_RL_NKDestination = "USLAX";
				AssertEquals(Directions.Export, invoice.JobDirection);

				shipment.JS_RL_NKOrigin = "USLAX";
				shipment.JS_RL_NKDestination = "AUSYD";
				AssertEquals(Directions.Import, invoice.JobDirection);

				shipment.JS_RL_NKOrigin = "USLAX";
				shipment.JS_RL_NKDestination = "USLAX";
				AssertEquals(Directions.Domestic, invoice.JobDirection);

				shipment.JS_RL_NKOrigin = "INBOM";
				shipment.JS_RL_NKDestination = "USLAX";
				AssertEquals(Directions.CrossTrade, invoice.JobDirection);
			}
			else
			{
				Assert(true);
			}
		}

		public void TestJobDirectionForMultipleJob()
		{
			var expectObject = GetExpectedBusinessObjectType();
			if (expectObject == typeof(ARInvoice) || expectObject == typeof(APInvoice) || expectObject == typeof(ARCreditNote) || expectObject == typeof(APCreditNote))
			{
				var consol = TestObjectCreator.CreateConsol("C001");
				Factory.Save();
				var invoice = TestObjectCreator.CreateInvoice(expectObject, TestObjectCreator.AUD, 1);
				invoice.AH_JH = ZGuid.Empty;
				invoice.AH_ConsolidatedInvoiceRef = consol.JK_UniqueConsignRef;
				Factory.Save();
				Assert("Should be true", invoice.IsConsolInvoice);

				consol.JK_RL_NKLoadPort = "AUSYD";
				consol.JK_RL_NKDischargePort = "USLAX";
				AssertEquals(invoice.AH_Ledger == LedgerTypes.AccountsReceivable ? Directions.Export : Directions.Unknown, invoice.JobDirection);

				consol.JK_RL_NKLoadPort = "USLAX";
				consol.JK_RL_NKDischargePort = "AUSYD";
				AssertEquals(invoice.AH_Ledger == LedgerTypes.AccountsReceivable ? Directions.Import : Directions.Unknown, invoice.JobDirection);

				consol.JK_RL_NKLoadPort = "USLAX";
				consol.JK_RL_NKDischargePort = "USLAX";
				AssertEquals(invoice.AH_Ledger == LedgerTypes.AccountsReceivable ? Directions.Domestic : Directions.Unknown, invoice.JobDirection);

				consol.JK_RL_NKLoadPort = "INBOM";
				consol.JK_RL_NKDischargePort = "USLAX";
				AssertEquals(invoice.AH_Ledger == LedgerTypes.AccountsReceivable ? Directions.CrossTrade : Directions.Unknown, invoice.JobDirection);
			}
			else
			{
				Assert(true);
			}
		}

