		public void TestSettingOrgHeaderDefaultsPlaceOfSupplyOnNonJobRelatedLines()
		{
			using (GlbCompany.CurrentCompany.TemporarilySetCountry(Constants.CountryCodes.India))
			using (PlaceOfSupplyHelper.SetPOSTypesEnabled_ForTestOnly(PlaceOfSupplyTypes.State.Code))
			using (TestObjectCreator.TemporarilyCustomiseTransactionNumberGenerator(GlbCompany.CurrentCompany, TestObjectCreator.CreateTestPrefixAndSequenceNumberCustomisation()))
			{
				var invoice = (InvoicingBase)GetNewBusinessObject();
				if (!invoice.IsARAP_ForTestOnly)
				{
					Assert("PA Ledger cannot have Lines", true);
					return;
				}

				SetUpOrgForPOS(TestObjectCreator.AALSHI);
				SetUpOrgForPOS(TestObjectCreator.ABIGAS);
				invoice.AH_OH = TestObjectCreator.AALSHI.PK;
				var invoiceLine = (InvoicingLineBase)invoice.Lines.AddNew();
				invoiceLine.AL_AC = TestObjectCreator.CC1.PK;
				invoiceLine.AL_GB = Env.CurrentBranchPK;
				invoiceLine.Branch.OrgProxy.MainAddress.OA_RN_NKCountryCode = Constants.CountryCodes.India;

				Assert(invoice.NeedPlaceOfSupplyAtLineLevel);
				Assert(invoiceLine.IsGSTMandatory);
				Assert(invoiceLine.AL_JH.IsEmpty);
				Assert(invoiceLine.AL_PlaceOfSupply.IsEmpty);

				var costSell = invoice.AH_Ledger == LedgerTypes.AccountsReceivable ? CostSell.Revenue : CostSell.Cost;
				var posList = PlaceOfSupplyListProvider.GetPlaceOfSupplyList(GlbCompany.CurrentCompany);
				var posCode1 = posList[0].Code;
				var posCode2 = posList[1].Code;
				var posCode3 = posList[2].Code;

				AccPlaceOfSupplyTestHelper.SetUpPOSConfigurationToReturn_ForTestOnly(null, costSell, PlaceOfSupplyTypes.State.Code, posCode1, TestObjectCreator.ABIGAS, invoiceLine.Branch);

				invoice.AH_OH = TestObjectCreator.ABIGAS.PK;
				AssertEquals(posCode1, invoiceLine.AL_PlaceOfSupply);

				invoiceLine.AL_PlaceOfSupply = posCode2;
				invoice.AH_OH = invoice.AH_OH;
				AssertEquals(posCode2, invoiceLine.AL_PlaceOfSupply);

				AccPlaceOfSupplyTestHelper.SetUpPOSConfigurationToReturn_ForTestOnly(null, costSell, PlaceOfSupplyTypes.State.Code, posCode3, TestObjectCreator.AALSHI, invoiceLine.Branch);

				invoice.AH_OH = TestObjectCreator.AALSHI.PK;
				AssertEquals(posCode3, invoiceLine.AL_PlaceOfSupply);

				AccPlaceOfSupplyTestHelper.SetUpPOSConfigurationToReturn_ForTestOnly(null, costSell, PlaceOfSupplyTypes.State.Code, "StateNotExisted", TestObjectCreator.ABIGAS, invoiceLine.Branch);
				invoice.AH_OH = TestObjectCreator.ABIGAS.PK;
				AssertEquals("Should be empty when matching result empty, when state is not existed", ZString.Empty, invoiceLine.AL_PlaceOfSupply);
			}
		}

