		public void TestGetLineLevelTransactionsGroupedByBranchAndDeptWithSingleTransaction()
		{
			var branchBNE = Factory.LoadTop1<GlbBranch>(new ZQuery(GlbBranchSchema.GB_Code, "BNE"));
			var branchSYD = Factory.LoadTop1<GlbBranch>(new ZQuery(GlbBranchSchema.GB_Code, "SYD"));

			var shipment = TestObjectCreator.CreateShipment("S001");
			using (var job = TestObjectCreator.CreateJob(shipment))
			{
				var creditNote1 = TestObjectCreator.CreateARCreditNote(50m, TestObjectCreator.LocalClient.PK, ZGuid.Empty, ZGuid.Empty);
				TestObjectCreator.AddLineToCreditNote(creditNote1, job.PK, branchBNE.PK, TestObjectCreator.FIADepartment.PK, 5m);
				TestObjectCreator.AddLineToCreditNote(creditNote1, job.PK, branchBNE.PK, TestObjectCreator.FIADepartment.PK, 1m);
				TestObjectCreator.AddLineToCreditNote(creditNote1, job.PK, branchBNE.PK, TestObjectCreator.FISDepartment.PK, 10m);
				TestObjectCreator.AddLineToCreditNote(creditNote1, job.PK, branchSYD.PK, TestObjectCreator.FIADepartment.PK, 15m);
				TestObjectCreator.AddLineToCreditNote(creditNote1, job.PK, branchSYD.PK, TestObjectCreator.FISDepartment.PK, 20m);
				TestObjectCreator.AddLineToCreditNote(creditNote1, job.PK, branchSYD.PK, TestObjectCreator.FISDepartment.PK, 2m);

				var lineLevelTransactions = creditNote1.GetLineLevelTransactionsGroupedByBranchAndDept();
				AssertEquals(4, lineLevelTransactions.Count);
				AssertEquals(6m, lineLevelTransactions.First(x => x.AH_GB == branchBNE.PK && x.AH_GE == TestObjectCreator.FIADepartment.PK).AH_LocalTotalAmount);
				AssertEquals(10m, lineLevelTransactions.First(x => x.AH_GB == branchBNE.PK && x.AH_GE == TestObjectCreator.FISDepartment.PK).AH_LocalTotalAmount);
				AssertEquals(15m, lineLevelTransactions.First(x => x.AH_GB == branchSYD.PK && x.AH_GE == TestObjectCreator.FIADepartment.PK).AH_LocalTotalAmount);
				AssertEquals(22m, lineLevelTransactions.First(x => x.AH_GB == branchSYD.PK && x.AH_GE == TestObjectCreator.FISDepartment.PK).AH_LocalTotalAmount);
			}
		}

		public void TestGetLineLevelTransactionsGroupedByBranchAndDeptWithAdjustmentNote()
		{
			var branchBNE = Factory.LoadTop1<GlbBranch>(new ZQuery(GlbBranchSchema.GB_Code, "BNE"));
			var branchSYD = Factory.LoadTop1<GlbBranch>(new ZQuery(GlbBranchSchema.GB_Code, "SYD"));

			var shipment = TestObjectCreator.CreateShipment("S001");
			using (var job = TestObjectCreator.CreateJob(shipment))
			{
				var adjustmentNote1 = createARAdjustmentNote(-50m, TestObjectCreator.LocalClient.PK);
				AddLineToAdjustmentNote(adjustmentNote1, job.PK, branchBNE.PK, TestObjectCreator.FIADepartment.PK, -5m);
				AddLineToAdjustmentNote(adjustmentNote1, job.PK, branchBNE.PK, TestObjectCreator.FIADepartment.PK, -1m);
				AddLineToAdjustmentNote(adjustmentNote1, job.PK, branchBNE.PK, TestObjectCreator.FISDepartment.PK, -10m);
				AddLineToAdjustmentNote(adjustmentNote1, job.PK, branchSYD.PK, TestObjectCreator.FIADepartment.PK, -15m);
				AddLineToAdjustmentNote(adjustmentNote1, job.PK, branchSYD.PK, TestObjectCreator.FISDepartment.PK, -20m);
				AddLineToAdjustmentNote(adjustmentNote1, job.PK, branchSYD.PK, TestObjectCreator.FISDepartment.PK, -2m);
				var lineLevelTransactions = adjustmentNote1.GetLineLevelTransactionsGroupedByBranchAndDept();
				AssertEquals(4, lineLevelTransactions.Count);
				AssertEquals(-6m, lineLevelTransactions.First(x => x.AH_GB == branchBNE.PK && x.AH_GE == TestObjectCreator.FIADepartment.PK).AH_LocalTotalAmount);
				AssertEquals(-10m, lineLevelTransactions.First(x => x.AH_GB == branchBNE.PK && x.AH_GE == TestObjectCreator.FISDepartment.PK).AH_LocalTotalAmount);
				AssertEquals(-15m, lineLevelTransactions.First(x => x.AH_GB == branchSYD.PK && x.AH_GE == TestObjectCreator.FIADepartment.PK).AH_LocalTotalAmount);
				AssertEquals(-22m, lineLevelTransactions.First(x => x.AH_GB == branchSYD.PK && x.AH_GE == TestObjectCreator.FISDepartment.PK).AH_LocalTotalAmount);
				Assert(!adjustmentNote1.IsCreatingCreditNoteForReversal);
				foreach (var line in lineLevelTransactions)
				{
					Assert(!line.IsCreatingCreditNoteForReversal);
				}

				var adjustmentNote2 = createARAdjustmentNote(50m, TestObjectCreator.LocalClient.PK);
				adjustmentNote2.IsCreatingCreditNoteForReversal = true;
				AddLineToAdjustmentNote(adjustmentNote2, job.PK, branchBNE.PK, TestObjectCreator.FIADepartment.PK, 5m);
				AddLineToAdjustmentNote(adjustmentNote2, job.PK, branchBNE.PK, TestObjectCreator.FIADepartment.PK, 1m);
				AddLineToAdjustmentNote(adjustmentNote2, job.PK, branchBNE.PK, TestObjectCreator.FISDepartment.PK, 10m);
				AddLineToAdjustmentNote(adjustmentNote2, job.PK, branchSYD.PK, TestObjectCreator.FIADepartment.PK, 15m);
				AddLineToAdjustmentNote(adjustmentNote2, job.PK, branchSYD.PK, TestObjectCreator.FISDepartment.PK, 20m);
				AddLineToAdjustmentNote(adjustmentNote2, job.PK, branchSYD.PK, TestObjectCreator.FISDepartment.PK, 2m);
				lineLevelTransactions = adjustmentNote2.GetLineLevelTransactionsGroupedByBranchAndDept();
				AssertEquals(4, lineLevelTransactions.Count);
				AssertEquals(6m, lineLevelTransactions.First(x => x.AH_GB == branchBNE.PK && x.AH_GE == TestObjectCreator.FIADepartment.PK).AH_LocalTotalAmount);
				AssertEquals(10m, lineLevelTransactions.First(x => x.AH_GB == branchBNE.PK && x.AH_GE == TestObjectCreator.FISDepartment.PK).AH_LocalTotalAmount);
				AssertEquals(15m, lineLevelTransactions.First(x => x.AH_GB == branchSYD.PK && x.AH_GE == TestObjectCreator.FIADepartment.PK).AH_LocalTotalAmount);
				AssertEquals(22m, lineLevelTransactions.First(x => x.AH_GB == branchSYD.PK && x.AH_GE == TestObjectCreator.FISDepartment.PK).AH_LocalTotalAmount);
				Assert(adjustmentNote2.IsCreatingCreditNoteForReversal);
				foreach (var line in lineLevelTransactions)
				{
					Assert(line.IsCreatingCreditNoteForReversal);
				}
			}
		}

		ARAdjustmentNote createARAdjustmentNote(decimal amount, ZGuid headerPK)
		{
			var adjustmentNote = Factory.New<ARAdjustmentNote>();
			adjustmentNote.AH_TransactionCategory = InvoiceTypesList.Codes.FinalInvoice;
			adjustmentNote.AH_OH = headerPK;
			adjustmentNote.AH_LocalExTaxAmount = amount;
			return adjustmentNote;
		}

		void AddLineToAdjustmentNote(ARAdjustmentNote adjustmentNote, ZGuid jobPK, ZGuid branchPK, ZGuid departmentPK, decimal amount)
		{
			var adjustmentNoteLine = (InvoicingLineBase)adjustmentNote.Lines.AddNew();
			adjustmentNoteLine.AL_JH = jobPK;
			adjustmentNoteLine.AL_AC = TestObjectCreator.FRT.PK;
			adjustmentNoteLine.AL_GB = branchPK;
			adjustmentNoteLine.AL_GE = departmentPK;
			adjustmentNoteLine.AL_RX_NKTransactionCurrency = TestObjectCreator.AUD.RX_Code;
			adjustmentNoteLine.AL_OSAmount = amount;
			adjustmentNoteLine.AL_LineAmount = amount;
		}

		public void TestApprovingUserPK()
		{
			var user1 = new ZGuid();
			var user2 = new ZGuid();
			var user3 = new ZGuid();
			var type = GetExpectedBusinessObjectType();
			var invoice = TestObjectCreator.CreateInvoice(type);
			Assert(invoice.ApprovingUserPKList.IsNullOrEmpty());
			Assert(invoice.ApprovingUserPK.IsEmpty);

			invoice.ApprovingUserPK = user1;
			AssertEquals("Setting ApprovingUserPK should set ApprovingUserPKList", user1, invoice.ApprovingUserPK);
			AssertEquals("Setting ApprovingUserPK should set ApprovingUserPKList", user1, invoice.ApprovingUserPKList[0]);

			invoice.ApprovingUserPKList = new List<ZGuid> { user2, user3 };
			AssertEquals("Setting ApprovingUserPKList should have AprovingUserPK return first value", user2, invoice.ApprovingUserPK);
			AssertEquals("Setting ApprovingUserPKList should have AprovingUserPK return first value", user2, invoice.ApprovingUserPKList[0]);
			AssertEquals("Setting ApprovingUserPKList should have AprovingUserPK return first value", user3, invoice.ApprovingUserPKList[1]);

			invoice.ApprovingUserPK = user1;
			AssertEquals("Setting ApprovingUserPK should reset ApprovingUserPKList", user1, invoice.ApprovingUserPK);
			AssertEquals("Setting ApprovingUserPK should reset ApprovingUserPKList", user1, invoice.ApprovingUserPKList[0]);
			AssertEquals("Setting ApprovingUserPK should reset ApprovingUserPKList", 1, invoice.ApprovingUserPKList.Count);
		}

