		public void TestSavedAsPendingApprovalLogCreated_ThenCancelled()
		{
			var type = GetExpectedBusinessObjectType();
			if (type == typeof(APInvoice) || type == typeof(APCreditNote))
			{
				var invoice = TestObjectCreator.CreateInvoice(type, organisation: TestObjectCreator.Creditor1);
				TestObjectCreator.CreateInvoiceLine(invoice, 100);

				var approvalRequestInOtherFactory = TestObjectCreator.CreateAndSaveApprovalRequestForInvoiceInNewFactoryAsInProduction(invoice);
				approvalRequestInOtherFactory.Factory.Save();

				AssertNotNull("Approval Request is created in the other factory", approvalRequestInOtherFactory);
				AssertEquals(Constants.GenApprovalRequestApprovalStatus.Requested, approvalRequestInOtherFactory.XP_ApprovalStatus);

				var expectedReference = "Saved as Pending Approval";
				var query = new ZQuery(StmALogSchema.SL_SE_NKEvent, Events.AddedARecordToTheSystem.Code);
				query.AddToFilter(StmALogSchema.SL_Reference, SQLComparisonOperator.Contains, expectedReference);

				Assert("Saved as Pending Approval log added when invoice created", invoice.Logs.HasLogWith(query));

				approvalRequestInOtherFactory.XP_ApprovalStatus = Constants.GenApprovalRequestApprovalStatus.Cancelled;
				approvalRequestInOtherFactory.SetContext(BusinessContext.CancelApprovalRequestByUser);
				approvalRequestInOtherFactory.FinalizeCancelling();
				BusinessObjectFactory.SaveTogether(approvalRequestInOtherFactory.Factory, invoice.Factory);

				query = new ZQuery(StmALogSchema.SL_SE_NKEvent, Events.EditedARecord.Code);
				query.AddToFilter(StmALogSchema.SL_Reference, SQLComparisonOperator.Contains, expectedReference);

				Assert("Saved as Pending Approval log is not added because of cancelling the approval request", !invoice.Logs.HasLogWith(query));
			}
			else if (type == typeof(TransactionPendingAllocation))
			{
				var header = TestObjectCreator.CreateTransactionPendingAllocation("1", TestObjectCreator.Creditor1, 100M);
				header.Factory.Save();

				Assert("IPA: log added", header.Logs.HasLogWith(StmALogSchema.SL_Reference, "PA|IPA|Created"));
				Assert("Approval request created", header.HasApprovalRequest);

				header.AH_Desc = "description updated";

				var otherFactory = new BusinessObjectFactory();
				var approvalRequest = otherFactory.Load<TransactionPendingAllocationApprovalRequest>(header.TransactionRelatedApprovalRequest.PK);
				approvalRequest.XP_ApprovalStatus = Constants.GenApprovalRequestApprovalStatus.Cancelled;
				approvalRequest.SetContext(BusinessContext.CancelApprovalRequestByUser);
				var approvalRequestInOtherFactory = otherFactory.New<TransactionPendingAllocationApprovalRequest>();
				approvalRequestInOtherFactory.Initialize(header);
				approvalRequestInOtherFactory.XP_ReasonDescription = "Desc";

				BusinessObjectFactory.SaveTogether(approvalRequestInOtherFactory.Factory, header.Factory);

				var expectedReference = "Saved as Pending Approval";
				AssertEquals("Saved as Pending Approval log is added when updating transaction with new approval request", 1, header.Logs.GetAllLogs().Cast<StmALog>()
																																.Count(x => x.SL_SE_NKEvent == Events.EditedARecord.Code && x.SL_Reference.Contains(expectedReference)));

				approvalRequestInOtherFactory = otherFactory.Load<TransactionPendingAllocationApprovalRequest>(header.TransactionRelatedApprovalRequest.PK);
				approvalRequestInOtherFactory.XP_ApprovalStatus = Constants.GenApprovalRequestApprovalStatus.Cancelled;
				approvalRequestInOtherFactory.SetContext(BusinessContext.CancelApprovalRequestByUser);
				approvalRequestInOtherFactory.FinalizeCancelling();
				BusinessObjectFactory.SaveTogether(approvalRequestInOtherFactory.Factory, header.Factory);

				AssertEquals("No new log added with reference 'Saved as Pending Approval' log is not added because of cancelling the approval request", 1, header.Logs.GetAllLogs().Cast<StmALog>()
																																.Count(x => x.SL_SE_NKEvent == Events.EditedARecord.Code && x.SL_Reference.Contains(expectedReference)));
			}
			else
			{
				Assert("Not applicable", true);
			}
		}

		public void TestSavedAsPendingApprovalLogCreated_ThenPosted()
		{
			var type = GetExpectedBusinessObjectType();
			if (type == typeof(APInvoice) || type == typeof(APCreditNote))
			{
				var invoice = TestObjectCreator.CreateInvoice(type, organisation: TestObjectCreator.Creditor1);
				TestObjectCreator.CreateInvoiceLine(invoice, 100);

				var approvalRequestInOtherFactory = TestObjectCreator.CreateAndSaveApprovalRequestForInvoiceInNewFactoryAsInProduction(invoice);

				AssertNotNull("Approval Request is created in the other factory", approvalRequestInOtherFactory);
				AssertEquals(Constants.GenApprovalRequestApprovalStatus.Requested, approvalRequestInOtherFactory.XP_ApprovalStatus);

				var expectedReference = "Saved as Pending Approval";
				var query = new ZQuery(StmALogSchema.SL_SE_NKEvent, Events.AddedARecordToTheSystem.Code);
				query.AddToFilter(StmALogSchema.SL_Reference, SQLComparisonOperator.Contains, expectedReference);

				Assert("Saved as Pending Approval log added when invoice created", invoice.Logs.HasLogWith(query));

				approvalRequestInOtherFactory.XP_ApprovalStatus = Constants.GenApprovalRequestApprovalStatus.Approved;
				invoice.MoveFromIncompleteToPayableLedger();
				BusinessObjectFactory.SaveTogether(approvalRequestInOtherFactory.Factory, invoice.Factory);

				query = new ZQuery(StmALogSchema.SL_SE_NKEvent, Events.EditedARecord.Code);
				query.AddToFilter(StmALogSchema.SL_Reference, SQLComparisonOperator.Contains, expectedReference);

				Assert("Saved as Pending Approval log is not added because of Posting this invoice", !invoice.Logs.HasLogWith(query));

				query = new ZQuery(StmALogSchema.SL_SE_NKEvent, Events.EditedARecord.Code);
				query.AddToFilter(StmALogSchema.SL_Reference, SQLComparisonOperator.Contains, "Posted");
				Assert("But 'Posted' log added when invoice posted", invoice.Logs.HasLogWith(query));
			}
			else if (type == typeof(TransactionPendingAllocation))
			{
				var header = TestObjectCreator.CreateTransactionPendingAllocation("1", TestObjectCreator.Creditor1, 100M);
				header.Factory.Save();

				Assert("IPA: log added", header.Logs.HasLogWith(StmALogSchema.SL_Reference, "PA|IPA|Created"));
				Assert("Approval request created", header.HasApprovalRequest);

				header.AH_Desc = "description updated";

				var otherFactory = new BusinessObjectFactory { RefreshEnabled = false };
				var approvalRequest = otherFactory.Load<TransactionPendingAllocationApprovalRequest>(header.TransactionRelatedApprovalRequest.PK);
				approvalRequest.XP_ApprovalStatus = Constants.GenApprovalRequestApprovalStatus.Cancelled;
				approvalRequest.SetContext(BusinessContext.CancelApprovalRequestByUser);
				var approvalRequestInOtherFactory = otherFactory.New<TransactionPendingAllocationApprovalRequest>();
				approvalRequestInOtherFactory.Initialize(header);
				approvalRequestInOtherFactory.XP_ReasonDescription = "Desc";

				BusinessObjectFactory.SaveTogether(approvalRequestInOtherFactory.Factory, header.Factory);

				var expectedReference = "Saved as Pending Approval";
				AssertEquals("Saved as Pending Approval log is added when updating transaction with new approval request", 1, header.Logs.GetAllLogs().Cast<StmALog>()
																															.Count(x => x.SL_SE_NKEvent == Events.EditedARecord.Code && x.SL_Reference.Contains(expectedReference)));

				otherFactory.Load<TransactionPendingAllocationApprovalRequest>(header.TransactionRelatedApprovalRequest.PK).XP_ApprovalStatus = Constants.GenApprovalRequestApprovalStatus.Approved;

				var invoice = TransactionAllocationConverter.ConvertUnallocatedToAP(header).Invoice;
				TestObjectCreator.CreateInvoiceLine(invoice, invoice.TransactionCurrency, 1M, 100M);

				BusinessObjectFactory.SaveTogether(approvalRequestInOtherFactory.Factory, invoice.Factory);

				AssertEquals("No new log added with reference Saved as Pending Approval log is not added because of Posting TPA", 1, header.Logs.GetAllLogs().Cast<StmALog>()
																															.Count(x => x.SL_SE_NKEvent == Events.EditedARecord.Code && x.SL_Reference.Contains(expectedReference)));

				var query = new ZQuery(StmALogSchema.SL_SE_NKEvent, Events.EditedARecord.Code);
				query.AddToFilter(StmALogSchema.SL_Reference, SQLComparisonOperator.Contains, "Posted");
				Assert("But 'Posted' log added when invoice posted", invoice.Logs.HasLogWith(query));
			}
			else
			{
				Assert("Not applicable", true);
			}
		}

		public void TestLogAddedForIncompleteTransaction()
		{
