				invoice.SaveAsIncomplete();
				invoice.Factory.Save();

				var expectedReference = "Saved as Incomplete";
				var query = new ZQuery(StmALogSchema.SL_SE_NKEvent, Events.AddedARecordToTheSystem.Code);
				query.AddToFilter(StmALogSchema.SL_Reference, string.Format(CultureInfo.InvariantCulture, "{0}|{1}|{2}", LedgerTypes.IncompleteTransactions, invoice.AH_TransactionType, expectedReference));
				Assert("Saved as Incomplete log added", invoice.Logs.HasLogWith(query));

				var newFactory = new BusinessObjectFactory();
