		[TestDate(2017, 12, 31)]
		public void TestLogReferenceCreatedWhenFullyMatch()
		{
			var invoice = TestObjectCreator.CreateInvoice(GetExpectedBusinessObjectType(), "10001", TestObjectCreator.AUD, 1M, TestObjectCreator.ABIGAS);

			if (invoice.IsReceivableOrPayable_ForTestOnly
				&& invoice.IsInvoiceOrCreditNoteOrAdjustmentNote_ForTestOnly)
			{
				var invoiceAmount = 200M;
				TestObjectCreator.CreateInvoiceLine(invoice, TestObjectCreator.AUD, 1M, invoiceAmount, 0M, TestObjectCreator.GLHeader1.PK);

				invoice.AH_OutstandingAmount = invoice.Multiplier_ForTestOnly * invoiceAmount;
				invoice.Factory.Save();

				var prefix = ZString.Format("{0}|{1}|", invoice.AH_Ledger, invoice.AH_TransactionType);
				var expectedPostedReference = "Posted";

				Assert(invoice.Logs.HasLogWith(StmALogSchema.SL_Reference, prefix + expectedPostedReference));

				if (invoice.AH_Ledger == LedgerTypes.AccountsPayable)
				{
					TestObjectCreator.CreateAndMatchAPPaymentForAPInvoice(invoice, ZDateTime.Today);
				}
				else
				{
					TestObjectCreator.CreateAndMatchARReceiptForARInvoice(invoice, ZDateTime.Today);
				}

				var expectedFullyMatchedReference = "Fully Matched";
				AssertEquals("0 log present for Fully Matched", 0, invoice.Logs.GetAllLogs().Cast<StmALog>()
											.Count(x => x.SL_SE_NKEvent == Events.EditedARecord.Code && x.SL_Reference.Contains(expectedFullyMatchedReference)));

				invoice.Factory.Save();

				AssertEquals("Fully Paid date on Invoice", ZDateTime.Today, invoice.AH_FullyPaidDate);
				AssertEquals("Outstanding Amount on Invoice", 0m, invoice.AH_OutstandingAmount);
				Assert(invoice.Logs.HasLogWith(StmALogSchema.SL_Reference, prefix + expectedFullyMatchedReference));

				AssertEquals("1 log created for Fully Matched", 1, invoice.Logs.GetAllLogs().Cast<StmALog>()
											.Count(x => x.SL_SE_NKEvent == Events.EditedARecord.Code && x.SL_Reference.Contains(expectedFullyMatchedReference)));

				var expectedUndoFullyMatchedReference = "Undo Fully Matched";

				TestObjectCreator.UnmatchTransaction(((IMatching)invoice).CurrentMatchGroup[0].AP_MatchGroupNum);

				AssertEquals("0 log present for Undo Fully Matched", 0, invoice.Logs.GetAllLogs().Cast<StmALog>()
											.Count(x => x.SL_SE_NKEvent == Events.EditedARecord.Code && x.SL_Reference.Contains(expectedUndoFullyMatchedReference)));

				invoice.Factory.Save();

				Assert(invoice.Logs.HasLogWith(StmALogSchema.SL_Reference, prefix + expectedUndoFullyMatchedReference));

				AssertEquals("1 log created for Undo Fully Matched", 1, invoice.Logs.GetAllLogs().Cast<StmALog>()
											.Count(x => x.SL_SE_NKEvent == Events.EditedARecord.Code && x.SL_Reference.Contains(expectedUndoFullyMatchedReference)));

				var reverseError = string.Empty;
				TestObjectCreator.ReverseTransaction(invoice, out reverseError);

				invoice.Factory.Save();

				AssertEquals("No new log created for Posted", 1, invoice.Logs.GetAllLogs().Cast<StmALog>()
											.Count(x => x.SL_Reference.Contains(expectedPostedReference)));

				AssertEquals("No new log created for Fully Matched", 1, invoice.Logs.GetAllLogs().Cast<StmALog>()
											.Count(x => x.SL_SE_NKEvent == Events.EditedARecord.Code && (x.SL_Reference.Contains(expectedFullyMatchedReference) && !x.SL_Reference.Contains(expectedUndoFullyMatchedReference))));

				AssertEquals("No new log created for undo Fully Matched", 1, invoice.Logs.GetAllLogs().Cast<StmALog>()
											.Count(x => x.SL_SE_NKEvent == Events.EditedARecord.Code && x.SL_Reference.Contains(expectedUndoFullyMatchedReference)));
			}
			else
			{
				Assert(true);
			}
		}

		public void TestLogReferenceCreatedWhenTransactionReversed()
		{
			var invoice = TestObjectCreator.CreateInvoice(GetExpectedBusinessObjectType(), "10001", TestObjectCreator.AUD, 1M, TestObjectCreator.AALSHI);

			if (invoice.IsReceivableOrPayable_ForTestOnly
				&& invoice.IsInvoiceOrCreditNoteOrAdjustmentNote_ForTestOnly)
			{
				TestObjectCreator.CreateInvoiceLine(invoice, TestObjectCreator.AUD, 1M, 100M, 0M, TestObjectCreator.GLHeader1.PK);

				invoice.Factory.Save();

				var newFactory = new BusinessObjectFactory();
				InvoicingBase invoiceInNewFactory = newFactory.Load<InvoicingBase>(invoice.PK); //load invoice in new factory, otherwise cached log is returned rather than new log added

				var errorMessage = string.Empty;
				var reversedTransaction = TestObjectCreator.ReverseTransaction(invoiceInNewFactory, out errorMessage);
				reversedTransaction.TransactionNumber = "10002";

				invoiceInNewFactory.Factory.Save();

				var prefix = ZString.Format("{0}|{1}|", invoice.AH_Ledger, invoice.AH_TransactionType);
				var expectedPostedReference = "Reversed";

				Assert("Original transaction should have reference set as Reversed", invoice.Logs.HasLogWith(StmALogSchema.SL_Reference, prefix + expectedPostedReference));

				var reversedTransactionCasted = (InvoicingBase)reversedTransaction;
				prefix = ZString.Format("{0}|{1}|", reversedTransactionCasted.AH_Ledger, reversedTransactionCasted.AH_TransactionType);
				Assert("The new transaction should have reference set as Reversed", reversedTransactionCasted.Logs.HasLogWith(StmALogSchema.SL_Reference, prefix + expectedPostedReference));

				Assert("Original transaction should have event REV", invoice.Logs.HasLogWith(StmALogSchema.SL_SE_NKEvent, "REV"));
			}
			else
			{
				Assert(true);
			}
		}

