		public void TestChangingAH_RX_NKTransactionCurrencyDoesNotUnnecessarilyRecalculatesLineAmounts()
		{
			var type = GetExpectedBusinessObjectType();
			if (type == typeof(APInvoice) || type == typeof(APCreditNote))
			{
				AccountingConfigurationRegistry.Instance.UseJobExchangeRateDefault.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);

				var consol = TestObjectCreator.CreateConsol();
				var shipment1 = TestObjectCreator.CreateShipment("S001001", consol);
				var shipment2 = TestObjectCreator.CreateShipment("S001002", consol);

				var job1 = TestObjectCreator.CreateJob(shipment1, false);
				var job2 = TestObjectCreator.CreateJob(shipment2, false);

				Factory.Save();

				ReleaseFactory();

				var creditor = TestObjectCreator.Creditor1;
				var invoice = TestObjectCreator.CreateInvoice(type, organisation: creditor);
				AssertEquals("Precondition", "AUD", invoice.AH_RX_NKTransactionCurrency);

				var correctLocalTotalAmount = 131.41M;
				var consolCost = TestObjectCreator.CreateConsolCost(invoice, consol, TestObjectCreator.CC3, 100M, creditor);
				consolCost.E6_OSCostAmount = 100M;
				consolCost.E6_RX_NKCurrency = TestObjectCreator.USD.RX_Code;
				consolCost.E6_ExchangeRate = 0.761M;
				AssertEquals(correctLocalTotalAmount, consolCost.E6_LocalCostAmount);

				AssertEquals(2, consolCost.ApportionmentCharges.Count);
				foreach (ApportionSplitCharge appCharge in consolCost.ApportionmentCharges)
				{
					AssertEquals(50M, appCharge.JR_OSCostAmt);
				}

				var higherAmountAfterAdjustment = consolCost.ApportionmentCharges.Cast<ApportionSplitCharge>().Max(x => x.JR_LocalCostAmt);
				AssertEquals(65.71M, higherAmountAfterAdjustment);

				invoice.SubmittedFromInvoicingForm = true;
				invoice.ImportAllApportionmentsFromCosting();
				AssertEquals(2, invoice.Lines.Count);
				foreach (InvoicingLineBase line in invoice.Lines)
				{
					AssertEquals(50M, line.AL_OSAmount * invoice.Multiplier_ForTestOnly);
				}
				AssertNotNull(invoice.Lines.Cast<InvoicingLineBase>().FirstOrDefault(x => x.AL_LocalExTaxAmount == higherAmountAfterAdjustment));

				AssertEquals(correctLocalTotalAmount, invoice.AH_LocalTotalAmount);
				AssertEquals("Precondition", "AUD", invoice.AH_RX_NKTransactionCurrency);

				invoice.AH_RX_NKTransactionCurrency = TestObjectCreator.USD.RX_Code;

				AssertNoExceptionThrown(() => invoice.Factory.Save());

				AssertEquals(correctLocalTotalAmount, invoice.AH_LocalTotalAmount);
				AssertNotNull(invoice.Lines.Cast<InvoicingLineBase>().FirstOrDefault(x => x.AL_LocalExTaxAmount == higherAmountAfterAdjustment));
			}
			else
			{
				Assert("Not applicable", true);
			}
		}

		[SuspendGLAccountAndChargeCodeCriticalValidation]
		[TestDate(2018, 02, 10)]
		public void TestConcurrentPostingOfInvoiceIsPreventedByValidation()
		{
			var type = GetExpectedBusinessObjectType();
			if (type == typeof(APInvoice) || type == typeof(APCreditNote))
			{
				var factory1 = new BusinessObjectFactory();
				var testObjectCreator = new TestObjectCreator(factory1);
				var shipment = testObjectCreator.CreateShipment("S001001", false);
				var job = testObjectCreator.CreateJob(shipment, false);
				var jobChargeInFactory1 = testObjectCreator.CreateCharge(job, TestObjectCreator.CC1, 100M, 0M);
				factory1.Save();

				var factory2 = new BusinessObjectFactory();
				var invoice = (InvoicingBase)factory2.New(typeof(APInvoice));
				invoice.SubmittedFromInvoicingForm = true;
				invoice.AH_TransactionNum = "23433";
				var line = (InvoicingLineBase)invoice.Lines.AddNew();
				line.AL_JH = job.PK;
				line.AL_AG = TestObjectCreator.GLHeader1.PK;
				var jobCharge = factory2.Load<JobCharge>(jobChargeInFactory1.PK);
				invoice.ImportJobChargesIntoInvoice(new[] { jobCharge }.ToList<Charge>(), line);

				var invoiceInFactory1 = testObjectCreator.CreateAPInvoice<APInvoice>("111", testObjectCreator.AUD, 1M, 100M, 0M, 0M, 100M, 0M, 0M, testObjectCreator.AALSHI, false);
				var invoiceLineInFactory1 = invoiceInFactory1.Lines[0];
				jobChargeInFactory1.ReverseAccrual(ZDateTime.Today);
				jobChargeInFactory1.JR_AL_APLine = invoiceLineInFactory1.PK;
				jobChargeInFactory1.JR_APInvoiceNum = "111";
				jobChargeInFactory1.JR_APInvoiceDate = ZDateTime.Today;
				jobChargeInFactory1.APLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate;

				Assert("It should be possible to post in Factory1", !invoiceInFactory1.HasErrors);
				factory1.Save();

				invoice.RunPreSaveValidation();
				Assert("Invoice line should have error", line.HasErrors);
				var expectedError = "The associated charge is already posted by another user. Please delete this row and try to post again.";
				AssertHasError("Line should show error indicating charge is already posted", line.OriginalJobChargePKInfo, expectedError);

				line.Delete();

				using (new DisposableAction(() => factory2.SuspendValidation(), () => factory2.ResumeValidation()))
				{
					line = (InvoicingLineBase)invoice.Lines.AddNew();
					line.AL_JH = job.PK;
					invoice.ImportJobChargesIntoInvoice(new[] { jobCharge }.ToList<Charge>(), line);

					invoice.RunPreSaveValidation();
					Assert("No error found anymore since validation is suspended", !line.HasErrors);

					try
					{
						factory2.Save();
						Assert("Exception should be thrown while attempting to post the invoice", false);
					}
					catch (ZSaveConcurrencyException ex)
					{
						var expectedException = "Another user has already posted at least one Charge in this invoice. Please close the form and retry.";
						AssertEquals(expectedException, ex.InnerException.InnerException.Message);
					}
				}
			}
			else
			{
				Assert("Not applicable", true);
			}
		}

