		public void TestNotRemoveEDocsFactoryWhenMainFactorySaveFailed()
		{
			var invoice = (InvoicingBase)GetNewBusinessObject();
			invoice.AH_TransactionNum = "INV001";
			Factory.Save();

			var info = ((IDocManagerSupport)invoice).DocManagerInfo;
			info.AddFileOrDocument(new ZBlob(new byte[] { 1, 2, 3 }), "TestInvoiceFile1", "INV");
			invoice.DocManagerInfo.SetupEDocsFactoryToBeSavedWithMainFactory(false);
			var eDocFacory = (BusinessObjectFactory)info.MasterFactory;

			var newFactory = new BusinessObjectFactory();
			newFactory.RefreshEnabled = false;
			var reloadedInvoice = newFactory.Load<InvoicingBase>(invoice.PK);
			var newInfo = ((IDocManagerSupport)reloadedInvoice).DocManagerInfo;
			newInfo.AddFileOrDocument(new ZBlob(new byte[] { 4, 5, 6 }), "TestInvoiceFile2", "INV");
			reloadedInvoice.DocManagerInfo.SetupEDocsFactoryToBeSavedWithMainFactory(false);
			newFactory.Save();

			AssertEquals("Pre-condition: File count of info should be 1.", 1, info.Files.Count);
			AssertEquals("Pre-condition: File count of newInfo should be 1.", 1, newInfo.Files.Count);
			AssertExceptionThrown<ZSaveException>("Should throw exception as new factory has saved a storageMain record.", () => Factory.Save());
			AssertEquals("eDocFactory should not be removed from Main factory when save failed.", true, Factory.ChildFactories.Contains(eDocFacory));
		}

