		public void TestSetupEDocsFactoryToBeSavedWithMainFactory()
		{
			var invoice = (InvoicingBase)GetNewBusinessObject();
			invoice.AH_TransactionNum = "INV001";
			Factory.Save();
			AssertEquals(true, ((IDocManagerSupport)invoice).DocManagerInfo.UseBusinessEntityFactoryAsInternal);

			var invoiceeDoc = ((IDocManagerSupport)invoice).DocManagerInfo.AddFileOrDocument(new ZBlob(new byte[] { 1, 2, 3 }), "TestInvoiceFile1", "INV");
			Factory.Save();
			var reloadedInvoice = new BusinessObjectFactory().Load<InvoicingBase>(invoice.PK);
			AssertEquals("eDoc is not saved as it in different factory.", 0, ((IDocManagerSupport)reloadedInvoice).DocManagerInfo.AllEDocs.Count);

			invoice.DocManagerInfo.SetupEDocsFactoryToBeSavedWithMainFactory(false);
			Factory.Save();
			Action<string> assertEDoc = message =>
			{
				reloadedInvoice = new BusinessObjectFactory().Load<InvoicingBase>(invoice.PK);
				AssertEquals(message, 1, ((IDocManagerSupport)reloadedInvoice).DocManagerInfo.AllEDocs.Count);
				var eDoc = ((IDocManagerSupport)reloadedInvoice).DocManagerInfo.AllEDocs[0];
				AssertEquals("FileName", "TestInvoiceFile1", eDoc.FileName);
				AssertEquals("ImageData", new byte[] { 1, 2, 3 }, eDoc.ImageData);
				AssertEquals("DocType", "INV", eDoc.DocType);
			};
			assertEDoc("eDoc should be saved");

			var invoiceeDoc2 = ((IDocManagerSupport)invoice).DocManagerInfo.AddFileOrDocument(new ZBlob(new byte[] { 1, 2, 4 }), "TestInvoiceFile2", "INV");
			Factory.Save();
			assertEDoc("new eDoc should not be saved. Only previous eDoc should be here. SetupEDocsFactoryToBeSavedWithMainFactory is working for one save only.");

			invoice.DocManagerInfo.SetupEDocsFactoryToBeSavedWithMainFactory(false);
			Factory.Save();
			reloadedInvoice = new BusinessObjectFactory().Load<InvoicingBase>(invoice.PK);
			AssertEquals("Both eDocs should be saved now.", 2, ((IDocManagerSupport)reloadedInvoice).DocManagerInfo.AllEDocs.Count);
		}

		public virtual void TestApprovalRequestStatus()
		{
			var invoice = TestObjectCreator.CreateInvoice(typeof(APInvoice), organisation: TestObjectCreator.Creditor1);
			TestObjectCreator.CreateInvoiceLine(invoice, 100);

			var request1 = new BusinessObjectFactory().New<APInvoiceChargesApprovalRequest>();
			request1.InitializeInvoiceRelated(invoice);
			var expectedCreateTime1 = ZDateTime.Today.AddDays(-2);
			request1.XP_SystemCreateTimeUtc = expectedCreateTime1;
			request1.XP_ApprovalStatus = Constants.GenApprovalRequestApprovalStatus.Cancelled;
			AssertEquals("Show status only for saved requests", "", invoice.ApprovalRequestStatus);
			AssertNull("ApprovalRequest", invoice.TransactionRelatedApprovalRequest);
			request1.Factory.Save();
			AssertEquals(Constants.GenApprovalRequestApprovalStatus.Cancelled, invoice.ApprovalRequestStatus);
			AssertEquals("ApprovalRequest", request1.PK, invoice.TransactionRelatedApprovalRequest.PK);

			var request2 = new BusinessObjectFactory().New<APInvoiceChargesApprovalRequest>();
			request2.InitializeInvoiceRelated(invoice);
			request2.XP_ApprovalStatus = Constants.GenApprovalRequestApprovalStatus.Rejected;
			var expectedCreateTime2 = ZDateTime.Today.AddDays(-5);
			request2.XP_SystemCreateTimeUtc = expectedCreateTime2;
			request2.Factory.Save();
			AssertEquals("Precondition: request1.XP_SystemCreateTimeUtc", expectedCreateTime1, request1.XP_SystemCreateTimeUtc);
			AssertEquals("Precondition: request2.XP_SystemCreateTimeUtc", expectedCreateTime2, request2.XP_SystemCreateTimeUtc);
			AssertEquals("Show status only for saved requests", Constants.GenApprovalRequestApprovalStatus.Cancelled, invoice.ApprovalRequestStatus);
			AssertEquals("ApprovalRequest", request1.PK, invoice.TransactionRelatedApprovalRequest.PK);

			expectedCreateTime2 = ZDateTime.Today.AddDays(-1);
			request2.XP_SystemCreateTimeUtc = expectedCreateTime2;
			request2.Factory.Save();
			AssertEquals("Precondition: request1.XP_SystemCreateTimeUtc", expectedCreateTime1, request1.XP_SystemCreateTimeUtc);
			AssertEquals("Precondition: request2.XP_SystemCreateTimeUtc", expectedCreateTime2, request2.XP_SystemCreateTimeUtc);
			AssertEquals(Constants.GenApprovalRequestApprovalStatus.Rejected, invoice.ApprovalRequestStatus);
			AssertEquals("ApprovalRequest", request2.PK, invoice.TransactionRelatedApprovalRequest.PK);
		}

