		public void TestDbHitsForApprovalRequest()
		{
			Factory.Save();
			Factory.ClearQueryCache();
			int hitCountBeforeApprovalLoaded = Factory.GetTableHitCount(GenApprovalRequestSchema.Constants.TableName);
			var hasApprovalRequest = InvoicingBase.HasApprovalRequest;
			int hitCountAfterApprovalLoaded = Factory.GetTableHitCount(GenApprovalRequestSchema.Constants.TableName);
			if (InvoicingBase is UAInvoice || InvoicingBase is UACreditNote)
			{
				AssertEquals("No DB Hits", 0, hitCountAfterApprovalLoaded - hitCountBeforeApprovalLoaded);
			}
			else if (InvoicingBase is APInvoice || InvoicingBase is APCreditNote || InvoicingBase is TransactionPendingAllocation)
			{
				AssertEquals("One DB Hits", 1, hitCountAfterApprovalLoaded - hitCountBeforeApprovalLoaded);
			}
			else
			{
				AssertEquals("No DB Hits", 0, hitCountAfterApprovalLoaded - hitCountBeforeApprovalLoaded);
			}
		}

