		public void TestInitializeDuplicateLinesSequenceLookup()
		{
			InvoicingBase.Lines.RemoveAll();
			InvoicingLineBase line1 = (InvoicingLineBase)InvoicingBase.Lines.AddNew();
			var job1 = Factory.NewJobWithValidTestDataForTesting<JobHeader>();
			line1.AL_Sequence = 1;
			line1.AL_JH = job1.PK;

			InvoicingLineBase line2 = (InvoicingLineBase)InvoicingBase.Lines.AddNew();
			var job2 = Factory.NewJobWithValidTestDataForTesting<JobHeader>();
			line2.AL_Sequence = 2;
			line2.AL_JH = job2.PK;

			InvoicingBase.InitializeDuplicateLinesSequenceLookup();

			var duplicateLineSequenceLookup = InvoicingBase.GetDuplicateLineSequenceLookup_ForTestOnly();
			Assert(duplicateLineSequenceLookup.ContainsKey(new Tuple<ZGuid, ZShort>(job1.PK, 1)));
			Assert(duplicateLineSequenceLookup.ContainsKey(new Tuple<ZGuid, ZShort>(job2.PK, 2)));

			AssertEquals(1, duplicateLineSequenceLookup[new Tuple<ZGuid, ZShort>(job1.PK, 1)].Count);
			Assert(duplicateLineSequenceLookup[new Tuple<ZGuid, ZShort>(job1.PK, 1)].Contains(line1.PK));

			AssertEquals(1, duplicateLineSequenceLookup[new Tuple<ZGuid, ZShort>(job2.PK, 2)].Count);
			Assert(duplicateLineSequenceLookup[new Tuple<ZGuid, ZShort>(job2.PK, 2)].Contains(line2.PK));
		}

