		public void TestOverrideBranchPreserved()
		{
			var objectCreator = new TestObjectCreator(Factory);

			var invoice = (InvoicingBase)Header;
			GlbBranch newBranch1 = Factory.NewWithValidTestData<GlbBranch>();
			newBranch1.GB_GC = GlbCompany.CurrentCompany.PK;

			foreach (InvoicingLineBase line in invoice.Lines)
			{
				line.AL_GB = GlbBranch.CurrentBranch.PK;
			}

			var branchLevelPostingConfiguration = new BranchLevelPostingConfiguration() { EnableBranchLevelPosting = true };
			AccountingConfigurationRegistry.Instance.ReceivableEnforceBranchLevelPosting.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, branchLevelPostingConfiguration);
			AccountingConfigurationRegistry.Instance.PayableEnforceBranchLevelPosting.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, branchLevelPostingConfiguration);

			var overrideInvoiceHeader = new TransactionWithOverriddenBranchAndDepartment(invoice);
			var adaptor = new TransactionWithOverriddenBranchAndDepartmentAdaptor(invoice);
			var newBranch = objectCreator.NonCurrentBranch.PK;

			overrideInvoiceHeader.AH_GB = newBranch;
			overrideInvoiceHeader.AppendChange();
			adaptor.ApplyOrCancelChanges(true);
			Assert("context is set", invoice.HasContext(BusinessContext.OverrideTransactionBranchAndDepartment));

			Factory.Save();
			if (invoice.IsReceivableOrPayable_ForTestOnly &&
				(!invoice.IsInDatabase || invoice.IsAllocatingInvoice || invoice.IsCompletingInvoice || invoice.IsApprovingInvoice))
			{
				AssertEquals("invoice branch remains overridden", invoice.AH_GB, newBranch);
			}
		}

