			if (invoice.IsARInvoiceOrCreditNote)
			{
				invoice.AH_OH = TestObjectCreator.ABIGAS.PK;
				invoice.AH_OSTotalAmount = 100M;
				invoice.AH_TransactionNum = "INV001";

				var shipment = TestObjectCreator.CreateShipment("S0034322");
				var job = TestObjectCreator.CreateJob(shipment, false, false);

				invoice.AH_JH = job.PK;
				var line1 = TestObjectCreator.CreateInvoiceLine(invoice, TestObjectCreator.AUD, 1M, 100M, 0M, 0M, 100M, 0M, 0M, TestObjectCreator.FRT.PK);
				line1.AL_JH = job.PK;
				var jobCharge1 = TestObjectCreator.CreateJobCharge(line1, job, TestObjectCreator.FRT, TestObjectCreator.AUD);

				var overrideAddress = TestObjectCreator.CreateAddress(TestObjectCreator.ABIGAS);
				var overrideContact = TestObjectCreator.CreateContact(TestObjectCreator.ABIGAS);

				Factory.Save();

				invoice.SetContext(BusinessContext.OverrideInvoiceAddressContact);

				invoice.AH_OA_InvoiceAddressOverride = overrideAddress.PK;
				invoice.AH_OC_InvoiceContactOverride = overrideContact.PK;

				Factory.Save();

				AssertEquals(overrideAddress.PK, jobCharge1.JR_OA_SellInvoiceAddress);
				AssertEquals(overrideContact.PK, jobCharge1.JR_OC_SellInvoiceContact);

				invoice.AH_OA_InvoiceAddressOverride = ZGuid.Empty;
				invoice.AH_OC_InvoiceContactOverride = ZGuid.Empty;

				Factory.Save();

				AssertEquals(ZGuid.Empty, jobCharge1.JR_OA_SellInvoiceAddress);
				AssertEquals(ZGuid.Empty, jobCharge1.JR_OC_SellInvoiceContact);

				var invoice2 = (InvoicingBase)Factory.NewWithValidTestData(GetExpectedBusinessObjectType());
				invoice2.AH_OH = TestObjectCreator.ABIGAS.PK;
				invoice2.AH_OSTotalAmount = 100M;
				invoice2.AH_TransactionNum = "INV002";

				var shipment2 = TestObjectCreator.CreateShipment("S0034323");
				var job2 = TestObjectCreator.CreateJob(shipment2, false, false);

				invoice2.AH_JH = job2.PK;
				var line2 = TestObjectCreator.CreateInvoiceLine(invoice2, TestObjectCreator.AUD, 1M, 100M, 0M, 0M, 100M, 0M, 0M, TestObjectCreator.FRT.PK);
				line2.AL_JH = job2.PK;
				var jobCharge2 = TestObjectCreator.CreateJobCharge(line2, job2, TestObjectCreator.FRT, TestObjectCreator.AUD);

				var line3 = TestObjectCreator.CreateInvoiceLine(invoice2, TestObjectCreator.AUD, 1M, 100M, 0M, 0M, 100M, 0M, 0M, TestObjectCreator.FRT.PK);
				line3.AL_JH = job2.PK;
				var jobCharge3 = TestObjectCreator.CreateJobCharge(line3, job2, TestObjectCreator.FRT, TestObjectCreator.AUD);

				var line4 = TestObjectCreator.CreateInvoiceLine(invoice2, TestObjectCreator.AUD, 1M, 100M, 0M, 0M, 100M, 0M, 0M, TestObjectCreator.FRT.PK);
				line4.AL_JH = job2.PK;
				var jobCharge4 = TestObjectCreator.CreateJobCharge(line4, job2, TestObjectCreator.FRT, TestObjectCreator.AUD);

				Factory.Save();

				AssertEquals(3, invoice2.Lines.Count);

				invoice2.SetContext(BusinessContext.OverrideInvoiceAddressContact);

				invoice.AH_OA_InvoiceAddressOverride = overrideAddress.PK;
				invoice.AH_OC_InvoiceContactOverride = overrideContact.PK;
				invoice2.AH_OA_InvoiceAddressOverride = overrideAddress.PK;
				invoice2.AH_OC_InvoiceContactOverride = overrideContact.PK;

				Factory.Save();

				AssertEquals(overrideAddress.PK, jobCharge1.JR_OA_SellInvoiceAddress);
				AssertEquals(overrideContact.PK, jobCharge1.JR_OC_SellInvoiceContact);

				AssertEquals(overrideAddress.PK, jobCharge2.JR_OA_SellInvoiceAddress);
				AssertEquals(overrideContact.PK, jobCharge2.JR_OC_SellInvoiceContact);

				AssertEquals(overrideAddress.PK, jobCharge3.JR_OA_SellInvoiceAddress);
				AssertEquals(overrideContact.PK, jobCharge3.JR_OC_SellInvoiceContact);

				AssertEquals(overrideAddress.PK, jobCharge4.JR_OA_SellInvoiceAddress);
				AssertEquals(overrideContact.PK, jobCharge4.JR_OC_SellInvoiceContact);
			}
			else
			{
				Assert(true);
			}
		}

