		public void TestSavingOfAnExisitngIncompleteInvoiceUpdatesINVJobChargeAttribute()
		{
			var shipment = TestObjectCreator.CreateShipment("S0001");
			var job = TestObjectCreator.CreateJob(shipment);
			var charge1 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, 200M, 200M);
			var charge2 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC2, 200M, 200M);
			var charge3 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC3, 200M, 200M);
			var charge4 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC4, 200M, 200M);
			Factory.Save();

			var incompleteInvoice = TestObjectCreator.CreateInvoice(typeof(APInvoice), "00001");
			var line = incompleteInvoice.Lines.AddNew() as InvoicingLineBase;
			incompleteInvoice.ImportJobChargesIntoInvoice(new[] { charge1, charge2 }, line, false);
			incompleteInvoice.SaveAsIncomplete();

			var newFactory = new BusinessObjectFactory();
			var apInvoice = newFactory.Load<APInvoice>(incompleteInvoice.PK);
			apInvoice.RestoreSavedData();
