			apInvoice.RestoreSavedData();
			lines = apInvoice.Lines.OfType<InvoicingLineBase>().ToList();
			AssertEquals("Invoice Line Count", 3, lines.Count);
			AssertINVAttribute(lines[0]);
			AssertINVAttribute(lines[1]);
			AssertINVAttribute(lines[2]);

			var reloadedChargeImportedToTheRemovedInvoiceLine = newFactory.Load<Charge>(chargeImportedToTheRemovedInvoiceLine.PK);
			var invAttribs = reloadedChargeImportedToTheRemovedInvoiceLine.JobChargeAttributes.OfType<JobChargeAttrib>()
