				AssertNotNull(invLine.OriginalJobCharge);
				invAttribs = invLine.OriginalJobCharge.JobChargeAttributes.OfType<JobChargeAttrib>()
																			.Where(a => a.EC_Name == (ZString)JobChargeAttribTypeList.Codes.LinkedToIncompleteInvoice)
																			.ToList();
				AssertEquals("INV attribute", 1, invAttribs.Count);
				var attr = invAttribs[0];
				AssertEquals("Invoice PK", (ZString)incompleteInvoice.PK.ToString(), attr.EC_Value);
			}
		}

