		public void TestSavingOfAnExisitngIncompleteInvoiceUpdatesINVJobConsolCostAttribute()
		{
			var consol = TestObjectCreator.CreateConsol();
			var shipment1 = TestObjectCreator.CreateShipment("S0001", consol);
			var shipment2 = TestObjectCreator.CreateShipment("S0002", consol);
			var job1 = TestObjectCreator.CreateJob(shipment1);
			var job2 = TestObjectCreator.CreateJob(shipment2);
			var cost1 = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC1, 250M);
			Factory.Save();

			var newFactory = new BusinessObjectFactory();
			var incompleteInvoice = new TestObjectCreator(newFactory).CreateInvoice(typeof(APInvoice), "00001");
			var importer = new InvoicingBaseBulkConsolCostImporter(incompleteInvoice.ConsolCosting);
			importer.LoadConsolsCollection();
			importer.Import();
			incompleteInvoice.SaveAsIncomplete();

			var cost2 = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC2, 250M);
			cost2.ApportionmentCharges[0].JR_GE = TestObjectCreator.FEADepartment.PK;
			cost2.ApportionmentCharges[1].JR_GE = TestObjectCreator.FEADepartment.PK;
			Factory.Save();

			newFactory = new BusinessObjectFactory();
			var apInvoice = newFactory.Load<APInvoice>(incompleteInvoice.PK);
			apInvoice.RestoreSavedData();
			AssertEquals("Imported Cost Count", 1, apInvoice.ConsolCosting.ConsolCosts.Count);
			AssertEquals("Invoice Line Count", 2, apInvoice.Lines.Count);
			AssertINVAttribute(apInvoice.ConsolCosting.ConsolCosts[0]);

			importer = new InvoicingBaseBulkConsolCostImporter(apInvoice.ConsolCosting);
			importer.LoadConsolsCollection();
			importer.Import();
			apInvoice.ImportAllApportionmentsFromCosting();
			AssertEquals("Imported Cost Count", 3, apInvoice.ConsolCosting.ConsolCosts.Count);
			AssertEquals("Invoice Line Count", 6, apInvoice.Lines.Count);

			using (apInvoice.GetReportingDeletedApportionmentChargesSuspender())
			{
				var linesToRemove = apInvoice.Lines.OfType<InvoicingLineBase>()
												.Where(l => l.AL_AC == TestObjectCreator.CC1.PK)
												.ToList();
				linesToRemove.ForEach(l => apInvoice.Lines.Remove(l));
			}
			apInvoice.SaveAsIncomplete();

			newFactory = new BusinessObjectFactory();
			apInvoice = newFactory.Load<APInvoice>(incompleteInvoice.PK);
			apInvoice.RestoreSavedData();

			AssertEquals("Imported Cost Count", 1, apInvoice.ConsolCosting.ConsolCosts.Count);
			AssertEquals("Invoice Line Count", 2, apInvoice.Lines.Count);
			AssertINVAttribute(apInvoice.ConsolCosting.ConsolCosts[0]);

			var reloadedCOstImportedToTheRemovedInvoiceLine = newFactory.Load<JobConsolCost>(cost1.PK);
			var invAttribs = reloadedCOstImportedToTheRemovedInvoiceLine.Attributes.OfType<JobConsolCostAttrib>()
																			.Where(a => a.E6A_Name == (ZString)JobChargeAttribTypeList.Codes.LinkedToIncompleteInvoice)
																			.ToList();
			AssertEquals("INV attribute", 0, invAttribs.Count);

			void AssertINVAttribute(JobConsolCost cost)
			{
				var existinigCostInDB = cost.RelatedConsolCostFromDatabase;
				AssertNotNull(existinigCostInDB);

				invAttribs = existinigCostInDB.Attributes.OfType<JobConsolCostAttrib>()
														.Where(a => a.E6A_Name == (ZString)JobChargeAttribTypeList.Codes.LinkedToIncompleteInvoice)
														.ToList();
				AssertEquals("INV attribute", 1, invAttribs.Count);

				var attr = invAttribs[0];
				AssertEquals("Invoice PK", (ZString)incompleteInvoice.PK.ToString(), attr.E6A_Value);
			}
		}

