																		.Where(a => a.EC_Name == (ZString)JobChargeAttribTypeList.Codes.LinkedToIncompleteInvoice)
																		.ToList();
			AssertEquals("INV attribute is deleted when the Incomplete Invoice is deleted or cancelled", 0, invAttribs.Count);
		}

