		public void TestIsTransitioningTransaction()
		{
			var anotherLedgerType = LedgerTypes.CashBook;
			var anotherTransactionType = TransactionTypes.DirectPayment;

			var invoicingBase = (InvoicingBase)Factory.NewWithValidTestData(GetExpectedBusinessObjectType());

			string[] transitioningLedgerTypes = new string[] { LedgerTypes.AccountsReceivable, LedgerTypes.AccountsPayable };
			foreach (var ledger in transitioningLedgerTypes)
			{
				invoicingBase.AcceptDataRowChangesToTestOriginalValueWhenWeCantSave_ForTestOnly();

				invoicingBase.AH_Ledger = anotherLedgerType;
				invoicingBase.AH_TransactionType = anotherTransactionType;
				Assert(string.Format("'{0}' transaction should not be transitioning", anotherLedgerType), !invoicingBase.IsTransitioningTransaction);
				invoicingBase.AcceptDataRowChangesToTestOriginalValueWhenWeCantSave_ForTestOnly();

				invoicingBase.AH_Ledger = ledger;
				invoicingBase.AH_TransactionType = TransactionTypes.Invoice;
				Assert(string.Format("'{0}' transaction should be transitioning", ledger), invoicingBase.IsTransitioningTransaction);
				invoicingBase.AcceptDataRowChangesToTestOriginalValueWhenWeCantSave_ForTestOnly();

				invoicingBase.AH_Ledger = ledger;
				Assert(string.Format("'{0}' transaction should not be transitioning because the ledger hasn't changed", ledger), !invoicingBase.IsTransitioningTransaction);
			}

			string[] transitioningTransactionTypes = new string[] { TransactionTypes.Invoice, TransactionTypes.CreditNote, TransactionTypes.AdjustmentNote };
			foreach (var transactionType in transitioningTransactionTypes)
			{
				invoicingBase.AcceptDataRowChangesToTestOriginalValueWhenWeCantSave_ForTestOnly();

				invoicingBase.AH_Ledger = anotherLedgerType;
				invoicingBase.AH_TransactionType = anotherTransactionType;
				Assert(string.Format("'{0}' transaction should not be transitioning", anotherTransactionType), !invoicingBase.IsTransitioningTransaction);
				invoicingBase.AcceptDataRowChangesToTestOriginalValueWhenWeCantSave_ForTestOnly();

				invoicingBase.AH_Ledger = LedgerTypes.AccountsReceivable;
				invoicingBase.AH_TransactionType = transactionType;
				Assert(string.Format("'{0}' transaction should be transitioning", transactionType), invoicingBase.IsTransitioningTransaction);
				invoicingBase.AcceptDataRowChangesToTestOriginalValueWhenWeCantSave_ForTestOnly();

				invoicingBase.AH_TransactionType = transactionType;
				Assert(string.Format("'{0}' transaction should not be transitioning because the transaction type hasn't changed", transactionType), !invoicingBase.IsTransitioningTransaction);
			}
		}

		public void TestRaiseNegativeCompliancesFailedToCreate()
		{
			var invoice = (InvoicingBase)Factory.NewWithValidTestData(GetExpectedBusinessObjectType());
			invoice.AH_OH = TestObjectCreator.Debtor.PK;

			if (invoice.IsReceivableOrPayable_ForTestOnly
				&& invoice.IsInvoiceOrCreditNote_ForTestOnly)
			{
				using (GlbCompany.CurrentCompany.TemporarilySetCountry(CountryCodes.Taiwan))
				using (AccountingMasterFilesRegistry.Instance.EnableComplianceDocumentModule.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true))
				using (AccountingMasterFilesRegistry.Instance.AllowNegativeComplianceDocumentLines.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, false))
				using (AccountingMasterFilesRegistry.Instance.ComplianceDocumentNumberAllocation_Receivables.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, AccComplianceSequenceLookups.ComplianceDocumentNumberAllocationSettingCodes.Post))
				using (AccountingMasterFilesRegistry.Instance.ComplianceDocumentNumberAllocation_Payables.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, AccComplianceSequenceLookups.ComplianceDocumentNumberAllocationSettingCodes.Post))
				{
					NegativeComplianceFailedToCreate = false;
					invoice.OnNegativeCompliancesFailedToCreate += new EventHandler(InvoicingBaseTest_NegativeComplianceFailedToCreate);

					if (invoice is ARInvoice || invoice is ARCreditNote)
					{
						invoice.Header.CompanyData.OB_ARCreateVATComplianceDocumentOnPosting = "RCC";

						var line = invoice.Lines.AddNew() as InvoicingLineBase;
						line.AL_AG = TestObjectCreator.GLHeader1.PK;
						line.AL_OSExTaxAmount = -100m;
						line.AL_AT = TestObjectCreator.GST1.PK;
					}

					if (invoice is APInvoice || invoice is APCreditNote)
					{
						invoice.Header.CompanyData.OB_APCreateVATComplianceDocumentOnPosting = "PCD";

						var line = invoice.Lines.AddNew() as InvoicingLineBase;
						line.AL_AG = TestObjectCreator.GLHeader1.PK;
						line.AL_OSExTaxAmount = -100m;
						line.AL_AT = TestObjectCreator.GST1.PK;
						line.CreateComplianceDocumentRecordOnPosting = true;
						line.ComplianceDocumentNumber = "AA00000001";
					}

					Factory.Save();
					AssertEquals(true, NegativeComplianceFailedToCreate);
				}
			}
			else
			{
				AssertEquals(false, NegativeComplianceFailedToCreate);
			}
		}

		bool NegativeComplianceFailedToCreate;
		void InvoicingBaseTest_NegativeComplianceFailedToCreate(object sender, EventArgs e)
		{
			NegativeComplianceFailedToCreate = true;
		}

