				org1.CustomsCodes.AddNew(OrgCusCode.CodeTypes.VATCode, Core.Constants.CountryCodes.China);
				org1.CustomsCodes.AddNew(OrgCusCode.ChinaCodeTypes.VAG, Core.Constants.CountryCodes.China);

				OrgHeader org2 = Factory.NewWithValidTestData<OrgHeader>();
				org2.OH_RL_NKClosestPort = "CNSHA";
				org2.CustomsCodes.AddNew(OrgCusCode.CodeTypes.VATCode, Core.Constants.CountryCodes.China);

				var invoice1 = TestObjectCreator.CreateInvoice(typeof(ARInvoice), "INV001", TestObjectCreator.CNY, 1M, org1);
				TestObjectCreator.CreateInvoiceLine(invoice1, 100M, TestObjectCreator.CNY, 1M, setTaxes: true);
