		public void TestUpdateComplianceSubTypeForVNOrganizationLocation()
		{
			using (GlbCompany.CurrentCompany.TemporarilySetCountry(Core.Constants.CountryCodes.VietNam))
			{
				var collection = AccountingMasterFilesRegistry.Instance.ComplianceSubTypeAttributionRuleConfiguration.Value;
				var item = collection.AddNew();
				item.Country = Core.Constants.CountryCodes.VietNam;
				item.SubType = "TXI";
				item.LedgerType = "AR";
				item.InvoiceType = "INV";
				item.TaxInvoiceRule = TaxInvoiceRuleCodes.ContainsAtLeastOneTaxID; // "TID";
				item.DisbursementRule = DisbursementRuleCodes.AllTransactions; // "ALL";
				item.OriginalRule = OriginalRuleCodes.OriginalTransactionOnly; //"OTO";
				item.OrganisationLocation = "SG";
				AccountingMasterFilesRegistry.Instance.ComplianceSubTypeAttributionRuleConfiguration.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, collection);

				BusinessObjectFactory newFactory = new BusinessObjectFactory();
				TestObjectCreator testObjectCreator = new TestObjectCreator(newFactory);
				ZGuid menuPK = newFactory.LoadTop1<StmMenuItem>(new ZQuery(StmMenuItemSchema.SU_MenuName, "VN Govt Tax Invoice")).PK;
				AccComplianceSequence sequence = testObjectCreator.CreateNewComplianceSequence(menuPK, "TXI", 1, 100, 25);
				sequence.XD_Prefix = "01.02-";
				sequence.XD_GB_BranchOwner = GlbBranch.CurrentBranch.PK;
				sequence.XD_GC_Company = GlbCompany.CurrentCompany.PK;

				newFactory.Save();

				ARInvoice invoice1 = Factory.NewWithValidTestData<ARInvoice>();
				invoice1.AH_TransactionReference = "";
				invoice1.AH_ComplianceSubType = "";

				OrgHeader vnOrg = Factory.NewWithValidTestData<OrgHeader>();
				vnOrg.OH_RL_NKClosestPort = "VNBDH";

				invoice1.AH_OH = vnOrg.PK;
				InvoicingLineBase line = (InvoicingLineBase)invoice1.Lines.AddNew();
				line.AL_AT = TaxRate.PK;
				line.AL_AG = TestObjectCreator.GLHeader1.PK;
				AssertEquals(ZString.Empty, invoice1.AH_ComplianceSubType);
				Factory.Save();
				AssertEquals("should find a subtype because in VN and has a tax Id", "TXI", invoice1.AH_ComplianceSubType);

				ARInvoice invoice2 = Factory.NewWithValidTestData<ARInvoice>();
				invoice2.AH_OH = vnOrg.PK;
				InvoicingLineBase line2 = (InvoicingLineBase)invoice2.Lines.AddNew();
				line2.AL_AG = TestObjectCreator.GLHeader1.PK;
				line2.AL_AT = ZGuid.Empty;
				AssertEquals(ZString.Empty, invoice2.AH_ComplianceSubType);
				Factory.Save();
				AssertEquals("should NOT find a subtype because in VN and but no tax Id", "", invoice2.AH_ComplianceSubType);

				OrgHeader cnOrg = Factory.NewWithValidTestData<OrgHeader>();
				cnOrg.OH_RL_NKClosestPort = "CNSHA";

