		public void TestSetComplianceSubTypeBasedOnSelfBilling()
		{
			GlbCompany.CurrentCompany.SetCountry(Constants.CountryCodes.Mexico);
			SetupComplianceRuleRegistry();

			APInvoice aPInvoice = Factory.New<APInvoice>();
			aPInvoice.AH_Desc = "TEST AP Invoice";
			aPInvoice.AH_OH = InvoicingBase.AH_OH;
			aPInvoice.AH_TransactionNum = "ABC123";
			APInvoiceLine aPLine = (APInvoiceLine)aPInvoice.Lines.AddNew();
			aPLine.AL_AG = TestObjectCreator.GLHeader1.PK;
			aPLine.AL_AT = TaxRate.PK;
			aPInvoice.IsSelfBillingInvoice = false; // based on compliance setup, this transaction should get the normal sub-type

			APCreditNote aPCreditNote = Factory.New<APCreditNote>();
			aPCreditNote.AH_Desc = "TEST AP Credit Note";
			aPCreditNote.AH_OH = InvoicingBase.AH_OH;
			APCreditNoteLine creditNoteLine = (APCreditNoteLine)aPCreditNote.Lines.AddNew();
			creditNoteLine.AL_AT = TaxRate.PK;
			creditNoteLine.AL_AG = TestObjectCreator.GLHeader1.PK;
			aPCreditNote.IsSelfBillingInvoice = true;
			Factory.Save();

			AssertEquals("Should be 'normal' sub-type on AP Invoice", MexicoComplianceInfo.ComplianceSubTypeCodes.TXI, aPInvoice.AH_ComplianceSubType);
			AssertEquals("Should be 'different' sub-type on AP Self Billing Credit Note", MexicoComplianceInfo.ComplianceSubTypeCodes.TCR, aPCreditNote.AH_ComplianceSubType);
		}

