		public T CreateTwoLineAdjustmentNote<T>(string transactionNumber, decimal invoiceAmount, decimal taxAmount, ZDateTime postDate) where T : AdjustmentNote
		{
			T adjustmentNote = TestObjectCreator.CreateAdjustmentNote<T>(transactionNumber, invoiceAmount, taxAmount, postDate, InvoicingBase.AH_OH);
			TestObjectCreator.CreateAdjusmentNoteLine(adjustmentNote, TestObjectCreator.NonAccrualChargeCode.PK, invoiceAmount * 2, taxAmount * 2);
			TestObjectCreator.CreateAdjusmentNoteLine(adjustmentNote, TestObjectCreator.NonAccrualChargeCode.PK, -invoiceAmount, -taxAmount);
			Factory.Save();
			return adjustmentNote;
		}

		public void AdjustmentNoteQueuedCorrect(ZGuid adjustmentNotePK, int headerCount, int lineCount)
		{
			var loadReportQueuedHeaders = LoadReportQueuedHeaders(Factory, adjustmentNotePK);
			var loadReportQueuedLines = LoadReportQueuedLines(Factory, adjustmentNotePK);

			AssertEquals("Incorrect number of Adjustment Note Headers queued", headerCount, loadReportQueuedHeaders.Count);
			Assert($"Queued Adjustment Note Headers Report Types should all be '{ReportCodeHeader}'", loadReportQueuedHeaders.All(reportHeader => string.CompareOrdinal(reportHeader["ACQ_ReportType"].ToString(), ReportCodeHeader) == 0));

			AssertEquals("Incorrect number of Adjustment Note Lines queued", lineCount, loadReportQueuedLines.Count);
			Assert($"Queued Adjustment Note Lines Report Types should all be '{ReportCodeLine}'", loadReportQueuedLines.All(reportHeader => string.CompareOrdinal(reportHeader["ACQ_ReportType"].ToString(), ReportCodeLine) == 0));
		}

		public void CreateAdjustmentNoteAndAssertAdjustmentNotesQueued<T>(string transactionNumber, decimal invoiceAmount, decimal taxAmount, ZDateTime postDate) where T : AdjustmentNote
		{
			AdjustmentNoteQueuedCorrect(CreateTwoLineAdjustmentNote<T>(transactionNumber, invoiceAmount, taxAmount, postDate).PK, 1, 2);
		}

