		void AssertQueueForComplianceReport(bool withExcemption)
		{
			GlbCompany.CurrentCompany.SetCountry(Constants.CountryCodes.Mexico);
			InvoicingBase.AH_OH = TestObjectCreator.ABIGAS.PK;
			SetupComplianceRuleRegistry();

			var isComplianceReportApplicable = IsComplianceReportApplicable;

			var isComplianceSequenceApplicable = IsComplianceSequenceApplicable;

			var taxRegistrationCodes = new OrgCodeLists().CustomsCodes_List(RefCountry.LoadFromCountryCode(Factory, Core.Constants.CountryCodes.Mexico));
			var taxRegistration = taxRegistrationCodes.ToArray().FirstOrDefault(x => !string.IsNullOrEmpty(x.Code));
			AssertNotNull("There should be a Tax Registration", taxRegistration);

			var collection = new ComplianceReportConfigurationCollection(Factory);
			// By Compliance Sub Type only
			var report = collection.AddNew();
			report.Country = Core.Constants.CountryCodes.Mexico;
			report.ReportCode = "ABC";
			report.ReportBaseTablePrefix = AccTransactionHeaderSchema.Constants.Prefix;
			report.ReportPeriodicity = "RNG";
			report.TaxRegistrationType = taxRegistration.Code;
			var item = report.Settings.AddNew();
			item.ComplianceSubType = "TXI";
			item.LedgerType = "";
			item.InvoiceType = "";
			item.TaxInvoiceRule = "";
			item.DisbursementRule = "";
			item.OriginalRule = "";
			item.OrganisationLocation = "";

			// By Compliance Sub Type and other rules
			report = collection.AddNew();
			report.Country = Core.Constants.CountryCodes.Mexico;
			report.ReportCode = "SBS";
			report.ReportBaseTablePrefix = AccTransactionHeaderSchema.Constants.Prefix;
			report.ReportPeriodicity = "RNG";
			report.TaxRegistrationType = taxRegistration.Code;
			item = report.Settings.AddNew();
			item.ComplianceSubType = "TXI";
			item.LedgerType = "";
			item.InvoiceType = "";
			item.TaxInvoiceRule = TaxInvoiceRuleCodes.ContainsAtLeastOneTaxID; // "TID";
			item.DisbursementRule = DisbursementRuleCodes.NonDisbursementOnly; // "NDB";
			item.OriginalRule = OriginalRuleCodes.OriginalTransactionOnly; //"OTO";
			item.OrganisationLocation = "";

			if (isComplianceReportApplicable)
			{
				// By rules only with queueing Lines
				report = collection.AddNew();
				report.Country = Core.Constants.CountryCodes.Mexico;
				report.ReportCode = "MTV";
				report.ReportBaseTablePrefix = AccTransactionLinesSchema.Constants.Prefix;
				report.ReportPeriodicity = "RNG";
				report.TaxRegistrationType = taxRegistration.Code;
				AddDefaultSettingToComplianceReportConfiguration(report, InvoicingBase.AH_Ledger, InvoicingBase.AH_TransactionType);
			}

			AccountingMasterFilesRegistry.Instance.ComplianceReportConfiguration.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, collection);

			BusinessObjectFactory newFactory = new BusinessObjectFactory();
			TestObjectCreator testObjectCreator = new TestObjectCreator(newFactory);
			ZGuid menuPK = newFactory.LoadTop1<StmMenuItem>(new ZQuery(StmMenuItemSchema.SU_MenuName, "VN Govt Tax Invoice")).PK;
			AccComplianceSequence sequence = testObjectCreator.CreateNewComplianceSequence(menuPK, "TXI", 1, 100, 25);
			sequence.XD_Prefix = "01.02-";
			sequence.XD_GB_BranchOwner = GlbBranch.CurrentBranch.PK;
			sequence.XD_GC_Company = GlbCompany.CurrentCompany.PK;

			if (isComplianceReportApplicable)
			{
				var org = newFactory.Load<OrgHeader>(InvoicingBase.AH_OH);
				AssertNotNull("InvoicngBase Org in a newFactory", org);

				var exemptReport = org.RequiredDocuments.AddNew();
				exemptReport.EQ_DocCategory = Constants.ReferenceTypes.ComplianceReport;
				exemptReport.EQ_DocType = "ABC";
				exemptReport.EQ_RN_NKRelatedCountry = Constants.CountryCodes.Mexico;
				exemptReport.EQ_DocPeriod = Constants.JobRequiredDocuments.DocumentPeriods.Periodic;
				exemptReport.EQ_DocUsage = InvoicingBase.AH_Ledger == LedgerTypes.AccountsPayable ? JobRequiredDocument.DocUsage.Creditor : JobRequiredDocument.DocUsage.Debtor;
				exemptReport.EQ_DateReceived = ZDateTimeOffset.Today.AddDays(-7);

				exemptReport.EQ_ValidToDate = ZDateTime.Today.AddDays(withExcemption ? 1 : -1);
				exemptReport.RunPreSaveValidation();
				Assert("Is a valid JobRequiredDocument record", !exemptReport.HasErrors);
			}

			newFactory.Save();

			InvoicingBase.AH_Desc = "test";
			InvoicingBase.AH_TransactionReference = "";
			InvoicingBase.AH_ComplianceSubType = "";
			InvoicingLineBase line = (InvoicingLineBase)InvoicingBase.Lines.AddNew();
			line.AL_AT = TaxRate.PK;
			line.AL_AG = TestObjectCreator.GLHeader1.PK;
			AssertEquals(25m, sequence.XD_NextNumber);
			AssertEquals(ZString.Empty, InvoicingBase.AH_ComplianceSubType);
			AssertEquals(ZString.Empty, InvoicingBase.AH_TransactionReference);
			Factory.Save();

			var reportQueuedHeaders = LoadReportQueuedHeaders(Factory, InvoicingBase.PK);
			var reportQueuedLines = LoadReportQueuedLines(Factory, InvoicingBase.PK);

			if (isComplianceSequenceApplicable)
			{
				AssertEquals("should find a subtype", "TXI", InvoicingBase.AH_ComplianceSubType);

				var expectedHeaderRepors = withExcemption ? 1 : 2;

				AssertEquals("Queue records added", expectedHeaderRepors, reportQueuedHeaders.Count);

				var abcReport = reportQueuedHeaders.Cast<DynamicBusinessObject>().FirstOrDefault(x => x[AccTransactionComplianceReportQueueSchema.ACQ_ReportType].ToString() == "ABC");
				if (withExcemption)
				{
					AssertNull(abcReport);
				}
				else
				{
					AssertNotNull(abcReport);
					AssertEquals("ACQ_GC_Company", GlbCompany.CurrentCompany.PK.ToString(), abcReport[AccTransactionComplianceReportQueueSchema.ACQ_GC_Company].ToString());
					AssertEquals("ACQ_GB_Branch", GlbBranch.CurrentBranch.PK.ToString(), abcReport[AccTransactionComplianceReportQueueSchema.ACQ_GB_Branch].ToString());
					AssertEquals("ACQ_ParentTableCode", AccTransactionHeaderSchema.Constants.Prefix, abcReport[AccTransactionComplianceReportQueueSchema.ACQ_ParentTableCode].ToString());
				}

				var sbsReport = reportQueuedHeaders.Cast<DynamicBusinessObject>().FirstOrDefault(x => x[AccTransactionComplianceReportQueueSchema.ACQ_ReportType].ToString() == "SBS");
				AssertNotNull(sbsReport);
				AssertEquals("ACQ_GC_Company", GlbCompany.CurrentCompany.PK.ToString(), sbsReport[AccTransactionComplianceReportQueueSchema.ACQ_GC_Company].ToString());
				AssertEquals("ACQ_GB_Branch", GlbBranch.CurrentBranch.PK.ToString(), sbsReport[AccTransactionComplianceReportQueueSchema.ACQ_GB_Branch].ToString());
				AssertEquals("ACQ_ParentTableCode", AccTransactionHeaderSchema.Constants.Prefix, sbsReport[AccTransactionComplianceReportQueueSchema.ACQ_ParentTableCode].ToString());

				AssertEquals("Queue records added for every Line", InvoicingBase.Lines.Count, reportQueuedLines.Count);
				foreach (var mtvReport in reportQueuedLines.Cast<DynamicBusinessObject>().Where(x => x[AccTransactionComplianceReportQueueSchema.ACQ_ReportType].ToString() == "MTV"))
				{
					AssertEquals("ACQ_GC_Company", GlbCompany.CurrentCompany.PK.ToString(), mtvReport[AccTransactionComplianceReportQueueSchema.ACQ_GC_Company].ToString());
					AssertEquals("ACQ_GB_Branch", GlbBranch.CurrentBranch.PK.ToString(), mtvReport[AccTransactionComplianceReportQueueSchema.ACQ_GB_Branch].ToString());
					AssertEquals("ACQ_ParentTableCode", AccTransactionLinesSchema.Constants.Prefix, mtvReport[AccTransactionComplianceReportQueueSchema.ACQ_ParentTableCode].ToString());
				}
			}
			else
			{
				AssertEquals("nothing will happen to subtype if other than AR INV/CRD", "", InvoicingBase.AH_ComplianceSubType);
				AssertEquals("nothing will happen to transaction reference if other than AR INV/CRD", "", InvoicingBase.AH_TransactionReference);
				AssertEquals("No queue records added for Headers", 0, reportQueuedHeaders.Count);
			}

			if (!isComplianceReportApplicable)
			{
				AssertEquals("No queue records added for Lines", 0, reportQueuedLines.Count);
			}
		}

