		void AssertChangeOfComplianceSubtypeReQueueComplianceReport(bool generateReports)
		{
			GlbCompany.CurrentCompany.SetCountry(Constants.CountryCodes.Mexico);
			SetupComplianceRuleRegistry();

			var isComplianceReportApplicable = IsComplianceSequenceApplicable; //TODO: wrong?

			var isComplianceSequenceApplicable = IsComplianceSequenceApplicable;

			var taxRegistrationCodes = new OrgCodeLists().CustomsCodes_List(RefCountry.LoadFromCountryCode(Factory, Core.Constants.CountryCodes.Mexico));
			var taxRegistration = taxRegistrationCodes.ToArray().FirstOrDefault(x => !string.IsNullOrEmpty(x.Code));
			AssertNotNull("There should be a Tax Registration", taxRegistration);

			#region Compliance Reports Configuration

			var collection = new ComplianceReportConfigurationCollection(Factory);
			// By Compliance Sub Type only
			var report = collection.AddNew();
			report.Country = Core.Constants.CountryCodes.Mexico;
			report.ReportCode = "ABC";
			report.ReportBaseTablePrefix = AccTransactionHeaderSchema.Constants.Prefix;
			report.ReportPeriodicity = "RNG";
			report.TaxRegistrationType = taxRegistration.Code;
			var item = report.Settings.AddNew();
			item.ComplianceSubType = "TXI";
			item.LedgerType = "";
			item.InvoiceType = "";
			item.TaxInvoiceRule = "";
			item.DisbursementRule = "";
			item.OriginalRule = "";
			item.OrganisationLocation = "";

			if (isComplianceReportApplicable)
			{
				// By rules with queueing Header
				report = collection.AddNew();
				report.Country = Core.Constants.CountryCodes.Mexico;
				report.ReportCode = "SBS";
				report.ReportBaseTablePrefix = AccTransactionHeaderSchema.Constants.Prefix;
				report.ReportPeriodicity = "RNG";
				report.TaxRegistrationType = taxRegistration.Code;
				AddDefaultSettingToComplianceReportConfiguration(report, InvoicingBase.AH_Ledger, InvoicingBase.AH_TransactionType);

				// By rules only with queueing Lines
				report = collection.AddNew();
				report.Country = Core.Constants.CountryCodes.Mexico;
				report.ReportCode = "MTV";
				report.ReportBaseTablePrefix = AccTransactionLinesSchema.Constants.Prefix;
				report.ReportPeriodicity = "RNG";
				report.TaxRegistrationType = taxRegistration.Code;
				AddDefaultSettingToComplianceReportConfiguration(report, InvoicingBase.AH_Ledger, InvoicingBase.AH_TransactionType);
			}

			AccountingMasterFilesRegistry.Instance.ComplianceReportConfiguration.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, collection);

			#endregion

			BusinessObjectFactory newFactory = new BusinessObjectFactory();
			TestObjectCreator testObjectCreator = new TestObjectCreator(newFactory);

			#region Create Reports if necessary

			AccComplianceReport abcReport = null;
			AccComplianceReport sbsReport = null;
			AccComplianceReport mtvReport = null;

			if (generateReports)
			{
				abcReport = Factory.NewWithValidTestData<AccComplianceReport>();
				abcReport.ACR_ReportType = "ABC";
				sbsReport = Factory.NewWithValidTestData<AccComplianceReport>();
				sbsReport.ACR_ReportType = "SBS";
				mtvReport = Factory.NewWithValidTestData<AccComplianceReport>();
				mtvReport.ACR_ReportType = "MTV";
			}

			#endregion

			#region Compliance Sequence Setup

			ZGuid menuPK = newFactory.LoadTop1<StmMenuItem>(new ZQuery(StmMenuItemSchema.SU_MenuName, "ARInvoice PE Factura")).PK;
			AccComplianceSequence sequence = testObjectCreator.CreateNewComplianceSequence(menuPK, "TXI", 1, 100, 25);
			sequence.XD_Prefix = "01.02-";
			sequence.XD_GB_BranchOwner = GlbBranch.CurrentBranch.PK;
			sequence.XD_GC_Company = GlbCompany.CurrentCompany.PK;

			#endregion

			newFactory.Save();

			InvoicingBase.AH_Desc = "test";
			InvoicingBase.AH_TransactionReference = "";
			InvoicingBase.AH_ComplianceSubType = "";
			InvoicingLineBase line = (InvoicingLineBase)InvoicingBase.Lines.AddNew();
			line.AL_AT = TaxRate.PK;
			line.AL_AG = TestObjectCreator.GLHeader1.PK;
			AssertEquals(25m, sequence.XD_NextNumber);
			AssertEquals(ZString.Empty, InvoicingBase.AH_ComplianceSubType);
			AssertEquals(ZString.Empty, InvoicingBase.AH_TransactionReference);
			Factory.Save();

			var reportQueuedHeaders = LoadReportQueuedHeaders(Factory, InvoicingBase.PK);
			var reportQueuedLines = LoadReportQueuedLines(Factory, InvoicingBase.PK);

			if (isComplianceSequenceApplicable)
			{
				AssertEquals("should find a subtype", "TXI", InvoicingBase.AH_ComplianceSubType);

				AssertEquals("Two queue records added", 2, reportQueuedHeaders.Count);

				var abcReportQueue = reportQueuedHeaders.Cast<DynamicBusinessObject>().FirstOrDefault(x => x[AccTransactionComplianceReportQueueSchema.ACQ_ReportType].ToString() == "ABC");
				AssertNotNull(abcReportQueue);
				AssertEquals("ACQ_GC_Company", GlbCompany.CurrentCompany.PK.ToString(), abcReportQueue[AccTransactionComplianceReportQueueSchema.ACQ_GC_Company].ToString());
				AssertEquals("ACQ_GB_Branch", GlbBranch.CurrentBranch.PK.ToString(), abcReportQueue[AccTransactionComplianceReportQueueSchema.ACQ_GB_Branch].ToString());
				AssertEquals("ACQ_ParentTableCode", AccTransactionHeaderSchema.Constants.Prefix, abcReportQueue[AccTransactionComplianceReportQueueSchema.ACQ_ParentTableCode].ToString());

				var sbsReportQueue = reportQueuedHeaders.Cast<DynamicBusinessObject>().FirstOrDefault(x => x[AccTransactionComplianceReportQueueSchema.ACQ_ReportType].ToString() == "SBS");
				AssertNotNull(sbsReportQueue);
				AssertEquals("ACQ_GC_Company", GlbCompany.CurrentCompany.PK.ToString(), sbsReportQueue[AccTransactionComplianceReportQueueSchema.ACQ_GC_Company].ToString());
				AssertEquals("ACQ_GB_Branch", GlbBranch.CurrentBranch.PK.ToString(), sbsReportQueue[AccTransactionComplianceReportQueueSchema.ACQ_GB_Branch].ToString());
				AssertEquals("ACQ_ParentTableCode", AccTransactionHeaderSchema.Constants.Prefix, sbsReportQueue[AccTransactionComplianceReportQueueSchema.ACQ_ParentTableCode].ToString());
				var sbsPK = (ZGuid)sbsReportQueue[AccTransactionComplianceReportQueueSchema.PK];

				AssertEquals("Queue records added for every Line", InvoicingBase.Lines.Count, reportQueuedLines.Count);
				var lineQueuePKs = new List<ZGuid>();

				foreach (var mtvReportQueue in reportQueuedLines.Cast<DynamicBusinessObject>().Where(x => x[AccTransactionComplianceReportQueueSchema.ACQ_ReportType].ToString() == "MTV"))
				{
					AssertEquals("ACQ_GC_Company", GlbCompany.CurrentCompany.PK.ToString(), mtvReportQueue[AccTransactionComplianceReportQueueSchema.ACQ_GC_Company].ToString());
					AssertEquals("ACQ_GB_Branch", GlbBranch.CurrentBranch.PK.ToString(), mtvReportQueue[AccTransactionComplianceReportQueueSchema.ACQ_GB_Branch].ToString());
					AssertEquals("ACQ_ParentTableCode", AccTransactionLinesSchema.Constants.Prefix, mtvReportQueue[AccTransactionComplianceReportQueueSchema.ACQ_ParentTableCode].ToString());
					lineQueuePKs.Add((ZGuid)mtvReportQueue[AccTransactionComplianceReportQueueSchema.PK]);
				}

				if (generateReports)
				{
					testObjectCreator.CreateComplianceReportTransactionPivot(abcReport, InvoicingBase);
					testObjectCreator.CreateComplianceReportTransactionPivot(sbsReport, InvoicingBase);
					foreach (InvoicingLineBase invLine in InvoicingBase.Lines)
					{
						testObjectCreator.CreateComplianceReportTransactionPivot(mtvReport, invLine);
					}
				}

				// Reset or change Compliance Sub Type on Invoice in Database
				InvoicingBase.AH_ComplianceSubType = "";
				var clusteredIndexFieldsForAcq = ComplianceReportTransactionQueuerTest.Helpers.GetClusteredIndexFieldsForAcqTable();
				using (Db.Connection.TrackExecutedCommands())
				{
					Factory.Save();

					var deleteCommands = ComplianceReportTransactionQueuerTest.Helpers.GetDeleteCommandsCoveredByIndexFields(
											Db.Connection.ExecutedCommands,
											clusteredIndexFieldsForAcq
										);
					Assert("DELETE from dbo.AccTransactionComplianceReportQueue must run", deleteCommands.Any());
					var nonCoveredCommands = deleteCommands.Where(x => !x.isCovered);
					Assert("DELETE from dbo.AccTransactionComplianceReportQueue must cover clustered index fields to minimise locking", !nonCoveredCommands.Any());
				}

				reportQueuedHeaders = LoadReportQueuedHeaders(Factory, InvoicingBase.PK);
				reportQueuedLines = LoadReportQueuedLines(Factory, InvoicingBase.PK);

				AssertEquals("One queue record added", 1, reportQueuedHeaders.Count);

				abcReportQueue = reportQueuedHeaders.Cast<DynamicBusinessObject>().FirstOrDefault(x => x[AccTransactionComplianceReportQueueSchema.ACQ_ReportType].ToString() == "ABC");
				AssertNull(abcReportQueue);

				sbsReportQueue = reportQueuedHeaders.Cast<DynamicBusinessObject>().FirstOrDefault(x => x[AccTransactionComplianceReportQueueSchema.ACQ_ReportType].ToString() == "SBS");
				AssertNotNull(sbsReportQueue);
				AssertEquals("ACQ_GC_Company", GlbCompany.CurrentCompany.PK.ToString(), sbsReportQueue[AccTransactionComplianceReportQueueSchema.ACQ_GC_Company].ToString());
				AssertEquals("ACQ_GB_Branch", GlbBranch.CurrentBranch.PK.ToString(), sbsReportQueue[AccTransactionComplianceReportQueueSchema.ACQ_GB_Branch].ToString());
				AssertEquals("ACQ_ParentTableCode", AccTransactionHeaderSchema.Constants.Prefix, sbsReportQueue[AccTransactionComplianceReportQueueSchema.ACQ_ParentTableCode].ToString());
				AssertNotEquals("New Queue entry", sbsPK, (ZGuid)sbsReportQueue[AccTransactionComplianceReportQueueSchema.PK]);

				AssertEquals("Queue records added for every Line", InvoicingBase.Lines.Count, reportQueuedLines.Count);
				foreach (var mtvReportQueue in reportQueuedLines.Cast<DynamicBusinessObject>().Where(x => x[AccTransactionComplianceReportQueueSchema.ACQ_ReportType].ToString() == "MTV"))
				{
					AssertEquals("ACQ_GC_Company", GlbCompany.CurrentCompany.PK.ToString(), mtvReportQueue[AccTransactionComplianceReportQueueSchema.ACQ_GC_Company].ToString());
					AssertEquals("ACQ_GB_Branch", GlbBranch.CurrentBranch.PK.ToString(), mtvReportQueue[AccTransactionComplianceReportQueueSchema.ACQ_GB_Branch].ToString());
					AssertEquals("ACQ_ParentTableCode", AccTransactionLinesSchema.Constants.Prefix, mtvReportQueue[AccTransactionComplianceReportQueueSchema.ACQ_ParentTableCode].ToString());
					var pk = (ZGuid)mtvReportQueue[AccTransactionComplianceReportQueueSchema.PK];
					Assert("New Queue entries", lineQueuePKs.All(x => x != pk));
				}
			}
			else
			{
				AssertEquals("nothing will happen to subtype if other than AR INV/CRD", "", InvoicingBase.AH_ComplianceSubType);
				AssertEquals("nothing will happen to transaction reference if other than AR INV/CRD", "", InvoicingBase.AH_TransactionReference);
			}

			if (!isComplianceReportApplicable)
			{
				AssertEquals("No queue records added for Headers", 0, reportQueuedHeaders.Count);
				AssertEquals("No queue records added for Lines", 0, reportQueuedLines.Count);
			}
		}

