				AssertEquals("ACQ_GC_Company", GlbCompany.CurrentCompany.PK.ToString(), abcReportQueue[AccTransactionComplianceReportQueueSchema.ACQ_GC_Company].ToString());
				AssertEquals("ACQ_GB_Branch", GlbBranch.CurrentBranch.PK.ToString(), abcReportQueue[AccTransactionComplianceReportQueueSchema.ACQ_GB_Branch].ToString());
				AssertEquals("ACQ_ParentTableCode", AccTransactionHeaderSchema.Constants.Prefix, abcReportQueue[AccTransactionComplianceReportQueueSchema.ACQ_ParentTableCode].ToString());
				var abcPK = (ZGuid)abcReportQueue[AccTransactionComplianceReportQueueSchema.PK];

				var sbsReportQueue = reportQueuedHeaders.Cast<DynamicBusinessObject>().FirstOrDefault(x => x[AccTransactionComplianceReportQueueSchema.ACQ_ReportType].ToString() == "SBS");
				AssertNotNull(sbsReportQueue);
				AssertEquals("ACQ_GC_Company", GlbCompany.CurrentCompany.PK.ToString(), sbsReportQueue[AccTransactionComplianceReportQueueSchema.ACQ_GC_Company].ToString());
				AssertEquals("ACQ_GB_Branch", GlbBranch.CurrentBranch.PK.ToString(), sbsReportQueue[AccTransactionComplianceReportQueueSchema.ACQ_GB_Branch].ToString());
				AssertEquals("ACQ_ParentTableCode", AccTransactionHeaderSchema.Constants.Prefix, sbsReportQueue[AccTransactionComplianceReportQueueSchema.ACQ_ParentTableCode].ToString());
				var sbsPK = (ZGuid)sbsReportQueue[AccTransactionComplianceReportQueueSchema.PK];

				AssertEquals("No Lines queued", 0, reportQueuedLines.Count);

				// Finalise one Report
				testObjectCreator.CreateComplianceReportTransactionPivot(sbsReport, InvoicingBase);
				sbsReport.Logs.AddNew(Events.StatusUpdated, "TYP=" + AccComplianceReport.Status.ReportFinalised);

				var sql = string.Format(@"DELETE {0} WHERE {1} = @QueuePK",
					AccTransactionComplianceReportQueueSchema.Constants.TableName,
					AccTransactionComplianceReportQueueSchema.Constants.PK);
				var command = ((IDbConnected)Factory).Connection.Command(sql);  // No BizO generated for this table. There is no sense to generate business objects for queue entry and pivot as they are not bound to GUI
				command.AddParameterBasedOnDbColumn("@QueuePK", sbsPK.ToGuid(), AccComplianceReportTransactionPivotSchema.PK);
				command.ExecuteNonQuery();

				reportQueuedHeaders = LoadReportQueuedHeaders(Factory, InvoicingBase.PK);
				reportQueuedLines = LoadReportQueuedLines(Factory, InvoicingBase.PK);
				var reportPivots = LoadReportPivots(Factory, sbsReport.PK);

				AssertEquals("One queue record", 1, reportQueuedHeaders.Count);
				AssertEquals("ABC queue entry", abcPK, (ZGuid)reportQueuedHeaders[0][AccTransactionComplianceReportQueueSchema.PK]);

				AssertEquals("One report line(pivot to transaction)", 1, reportPivots.Count);
				var pivotPK = (ZGuid)reportPivots[0][AccComplianceReportTransactionPivotSchema.PK];

				// Reset or change Compliance Sub Type on Invoice in Database
				InvoicingBase.AH_ComplianceSubType = "";
				Factory.Save();

				reportQueuedHeaders = LoadReportQueuedHeaders(Factory, InvoicingBase.PK);
				reportQueuedLines = LoadReportQueuedLines(Factory, InvoicingBase.PK);
				reportPivots = LoadReportPivots(Factory, sbsReport.PK);

				AssertEquals("One queue record", 1, reportQueuedHeaders.Count);
				AssertEquals("Same ABC queue entry", abcPK, (ZGuid)reportQueuedHeaders[0][AccTransactionComplianceReportQueueSchema.PK]);

				AssertEquals("No Lines queued", 0, reportQueuedLines.Count);

				AssertEquals("One report line(pivot to transaction)", 1, reportPivots.Count);
				AssertEquals("Same report pivot", pivotPK, (ZGuid)reportPivots[0][AccComplianceReportTransactionPivotSchema.PK]);
			}
			else
			{
				AssertEquals("nothing will happen to subtype if other than AR INV/CRD", "", InvoicingBase.AH_ComplianceSubType);
				AssertEquals("nothing will happen to transaction reference if other than AR INV/CRD", "", InvoicingBase.AH_TransactionReference);
			}

			if (!isComplianceReportApplicable)
			{
				AssertEquals("No queue records added for Headers", 0, reportQueuedHeaders.Count);
				AssertEquals("No queue records added for Lines", 0, reportQueuedLines.Count);
			}
		}

		public void TestChangeOfComplianceSubtype_DoesNotDeleteComplianceReportQueueRecords_WhenNoReportConfigured()
		{
			// Arrange
			var isComplianceReportApplicable = IsComplianceReportApplicable;
			if (!isComplianceReportApplicable)
			{
				Assert("Test is not applicable", true);
				return;
			}

			GlbCompany.CurrentCompany.SetCountry(Constants.CountryCodes.Mexico);
			SetupComplianceRuleRegistry();

			var taxRegistrationCodes = new OrgCodeLists().CustomsCodes_List(RefCountry.LoadFromCountryCode(Factory, Core.Constants.CountryCodes.Mexico));
			var taxRegistration = taxRegistrationCodes.ToArray().FirstOrDefault(x => !string.IsNullOrEmpty(x.Code));
			AssertNotNull("There should be a Tax Registration", taxRegistration);

			var complianceReports = AccountingMasterFilesRegistry.Instance.ComplianceReportConfiguration.GetValueWithoutFallback(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty);
			AssertEquals("Precondition: no compliance reports configured for this company", 0, complianceReports.Count);

			var newTestObjectCreator = new TestObjectCreator(new BusinessObjectFactory());
			var sbsReport = Factory.NewWithValidTestData<AccComplianceReport>();
			sbsReport.ACR_ReportType = "SBS";
			newTestObjectCreator.Factory.Save();

			InvoicingBase.AH_Desc = "test";
			InvoicingBase.AH_TransactionReference = "";
			InvoicingBase.AH_ComplianceSubType = "";
			InvoicingLineBase line = (InvoicingLineBase)InvoicingBase.Lines.AddNew();
			line.AL_AT = TaxRate.PK;
			line.AL_AG = TestObjectCreator.GLHeader1.PK;
			AssertEquals(ZString.Empty, InvoicingBase.AH_ComplianceSubType);
			AssertEquals(ZString.Empty, InvoicingBase.AH_TransactionReference);
			Factory.Save();
			if (InvoicingBase.AH_ComplianceSubType.IsEmpty)
			{
				Assert("Compliance rules do not apply - no queue records will be created.", true);
				return;
			}

			TestObjectCreator.CreateComplianceReportQueueEntry(sbsReport, InvoicingBase);
			var reportQueuedHeaderCountBefore = LoadReportQueuedHeaders(Factory, InvoicingBase.PK).Count;
			AssertEquals("Precondition: a compliance report queue record is present for this transaction", 1, reportQueuedHeaderCountBefore);

			// Act
			InvoicingBase.AH_ComplianceSubType = MexicoComplianceInfo.ComplianceSubTypeCodes.OTR;
			var clusteredIndexFieldsForAcq = ComplianceReportTransactionQueuerTest.Helpers.GetClusteredIndexFieldsForAcqTable();
			using (Db.Connection.TrackExecutedCommands())
			{
				Factory.Save();

				// Assert
				var deleteCommands = Db.Connection.ExecutedCommands
										.Where(sql => sql.Contains($"DELETE {AccTransactionComplianceReportQueueSchema.Constants.SqlSchemaName}.{AccTransactionComplianceReportQueueSchema.Constants.TableName}", StringComparison.OrdinalIgnoreCase));
				AssertEquals("DELETE from dbo.AccTransactionComplianceReportQueue should not run as no compliance reports are configured", 0, deleteCommands.Count());
			}

			var reportQueuedHeaderCountAfter = LoadReportQueuedHeaders(Factory, InvoicingBase.PK).Count;
			AssertEquals("A compliance report queue record remains present for this transaction after modifying AH_ComplianceSubType as no compliance reports are configured", 1, reportQueuedHeaderCountAfter);
		}

