		public void TestIEvaluateComplianceRuleTaxTransactions()
		{
			var supporter = InvoicingBase as IEvaluateComplianceRule;
			AssertNotNull(supporter.TaxTransactions);
			Assert(!supporter.TaxTransactions.Any());

			var creator = new TaxFrameworkTestObjectCreator(Factory);
			creator.CreateTaxSystem("TS");
			var taxTransaction1 = creator.CreateTaxTransaction(new CreateTaxTransactionParameters() { TransactionHeader = InvoicingBase });
			var taxTransaction2 = creator.CreateTaxTransaction(new CreateTaxTransactionParameters() { TransactionHeader = InvoicingBase });

			AssertContainsExactElementsInAnyOrder(new AccTaxTransaction[] { taxTransaction1, taxTransaction2 }, supporter.TaxTransactions);
		}

		bool IsComplianceReportApplicable =>
			InvoicingBase.IsReceivableOrPayable_ForTestOnly &&
			InvoicingBase.IsInvoiceOrCreditNoteOrAdjustmentNote_ForTestOnly;
		bool IsComplianceSequenceApplicable =>
			InvoicingBase.IsReceivableOrPayable_ForTestOnly &&
			InvoicingBase.IsInvoiceOrCreditNote_ForTestOnly;

		DynamicBusinessObjectCollection LoadReportQueuedHeaders(BusinessObjectFactory factory, ZGuid headerPK)
		{
			var result = new DynamicBusinessObjectCollection(factory);
			result.Load(string.Format(@"select Q.*, ACQ_ReportSubCode as ReportSubCode
from dbo.AccTransactionComplianceReportQueue Q
where ACQ_ParentID = '{0}'", headerPK));
			return result;
		}

		DynamicBusinessObjectCollection LoadReportQueuedLines(BusinessObjectFactory factory, ZGuid headerPK)
		{
			var result = new DynamicBusinessObjectCollection(factory);
			result.Load(string.Format(@"select Q.*, ACQ_ReportSubCode as ReportSubCode
from dbo.AccTransactionComplianceReportQueue Q
join dbo.AccTransactionLines L on AL_PK = ACQ_ParentID
where AL_AH = '{0}'", headerPK));
			return result;
		}

		DynamicBusinessObjectCollection LoadReportPivots(BusinessObjectFactory factory, ZGuid reportPK)
		{
			var result = new DynamicBusinessObjectCollection(factory);
			result.Load(string.Format(@"select P.*, ACL_ReportSubCode as ReportSubCode
from dbo.AccComplianceReportTransactionPivot P
where ACL_ACR_Report = '{0}'", reportPK));
			return result;
		}

		public void TestQueueForComplianceReportWithItalyBLSubCode()
		{
			GlbCompany.CurrentCompany.SetCountry(Constants.CountryCodes.Italy);
			GlbCompany.CurrentCompany.SetCurrency(Constants.CurrencyCodes.EuropeanUnion);
			InvoicingBase.AH_RX_NKTransactionCurrency = Constants.CurrencyCodes.EuropeanUnion;

			var isComplianceReportApplicable = IsComplianceSequenceApplicable; //TODO: wrong?

			var taxRegistrationCodes = new OrgCodeLists().CustomsCodes_List(RefCountry.LoadFromCountryCode(Factory, Core.Constants.CountryCodes.Mexico));
			var taxRegistration = taxRegistrationCodes.ToArray().FirstOrDefault(x => !string.IsNullOrEmpty(x.Code));
			AssertNotNull("There should be a Tax Registration", taxRegistration);

			#region Compliance Reports Configuration

			var collection = new ComplianceReportConfigurationCollection(Factory);
			// By Organisation, Ledger and Sub Code
			var report = collection.AddNew();
			report.Country = Env.CurrentCompany.Country.Code;
			report.ReportCode = "ABC";
			report.ReportBaseTablePrefix = AccTransactionLinesSchema.Constants.Prefix;
			report.ReportPeriodicity = "RNG";
			report.TaxRegistrationType = "COD"; // Codice Fiscale
			report.ReportLineGrouping = "OBL";
			AddDefaultSettingToComplianceReportConfiguration(report, LedgerTypes.AccountsReceivable, TransactionTypes.Invoice).OrganisationLocation = "ITBL";
			AddDefaultSettingToComplianceReportConfiguration(report, LedgerTypes.AccountsReceivable, TransactionTypes.CreditNote).OrganisationLocation = "ITBL";
			AddDefaultSettingToComplianceReportConfiguration(report, LedgerTypes.AccountsPayable, TransactionTypes.Invoice).OrganisationLocation = "ITBL";
			AddDefaultSettingToComplianceReportConfiguration(report, LedgerTypes.AccountsPayable, TransactionTypes.CreditNote).OrganisationLocation = "ITBL";

			AccountingMasterFilesRegistry.Instance.ComplianceReportConfiguration.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, collection);

			#endregion

			var orgHeader = Factory.NewWithValidTestData<OrgHeader>();
			orgHeader.OH_RL_NKClosestPort = "HKHKG";    // Country must be in the Italy Black List of Countries
			AssertNotNull(orgHeader.UNLOCO);
			InvoicingBase.AH_OH = orgHeader.PK;

			TaxRate.AT_Type = AccTaxRate.Types.Rated;
			TaxRate2.AT_Type = AccTaxRate.Types.Exempt;
			TaxRate3.AT_Type = AccTaxRate.Types.ReverseRated;

			InvoicingLineBase line1 = null, line2 = null, line3 = null, line4 = null;

			if (InvoicingBase.Ledger_ForTestOnly != LedgerTypes.TransactionsPendingAllocation) // Cannot add lines to Transaction Pending Allocation
			{
				line1 = TestObjectCreator.CreateInvoiceLine(InvoicingBase, TestObjectCreator.CC1.PK, 100m);
				line1.AL_JH = Job.PK;
				line1.AL_AT = TaxRate.PK;
				TestObjectCreator.CreateCharge(line1);
				line2 = TestObjectCreator.CreateInvoiceLine(InvoicingBase, TestObjectCreator.CC2.PK, 200m);
				line2.AL_JH = Job.PK;
				line2.AL_AT = TaxRate2.PK;
				TestObjectCreator.CreateCharge(line2);
				line3 = TestObjectCreator.CreateInvoiceLine(InvoicingBase, TestObjectCreator.CC3.PK, 300m);
				line3.AL_JH = Job.PK;
				line3.AL_AT = TaxRate3.PK;
				TestObjectCreator.CreateCharge(line3);
				line4 = TestObjectCreator.CreateInvoiceLine(InvoicingBase, TestObjectCreator.CC4.PK, 400m);
				line4.AL_JH = Job.PK;
				line4.AL_AT = ZGuid.Empty;
				TestObjectCreator.CreateCharge(line4);
			}

			Factory.Save();

			var reportQueuedHeaders = LoadReportQueuedHeaders(Factory, InvoicingBase.PK);
			var reportQueuedLines = LoadReportQueuedLines(Factory, InvoicingBase.PK);

			if (isComplianceReportApplicable)
			{
				AssertEquals("No Header queue records added", 0, reportQueuedHeaders.Count);
				AssertEquals("Four Line queue records added", 4, reportQueuedLines.Count);

				var expectedTaxableSubCode = InvoicingBase.AH_Ledger == LedgerTypes.AccountsReceivable ? "BL003" : "BL006";
				var expectedNonTaxableSubCode = InvoicingBase.AH_Ledger == LedgerTypes.AccountsReceivable ? "BL004" : "BL007";

				var lineQueue = reportQueuedLines.Cast<DynamicBusinessObject>().FirstOrDefault(x => x[AccTransactionComplianceReportQueueSchema.ACQ_ReportType].ToString() == "ABC" &&
					((ZGuid)x[AccTransactionComplianceReportQueueSchema.ACQ_ParentID]) == line1.PK);
				AssertNotNull("line1Queue", lineQueue);
				AssertQueueRecord(lineQueue, AccTransactionLinesSchema.Constants.Prefix, line1.PK, InvoicingBase.AH_PostDate.Date, expectedTaxableSubCode);

				var line2Queue = reportQueuedLines.Cast<DynamicBusinessObject>().FirstOrDefault(x => x[AccTransactionComplianceReportQueueSchema.ACQ_ReportType].ToString() == "ABC" &&
					((ZGuid)x[AccTransactionComplianceReportQueueSchema.ACQ_ParentID]) == line2.PK);
				AssertNotNull("line2Queue", line2Queue);
				AssertQueueRecord(line2Queue, AccTransactionLinesSchema.Constants.Prefix, line2.PK, InvoicingBase.AH_PostDate.Date, expectedTaxableSubCode);

				var line3Queue = reportQueuedLines.Cast<DynamicBusinessObject>().FirstOrDefault(x => x[AccTransactionComplianceReportQueueSchema.ACQ_ReportType].ToString() == "ABC" &&
					((ZGuid)x[AccTransactionComplianceReportQueueSchema.ACQ_ParentID]) == line3.PK);
				AssertNotNull("line3Queue", line3Queue);
				AssertQueueRecord(line3Queue, AccTransactionLinesSchema.Constants.Prefix, line3.PK, InvoicingBase.AH_PostDate.Date, expectedNonTaxableSubCode);

				var line4Queue = reportQueuedLines.Cast<DynamicBusinessObject>().FirstOrDefault(x => x[AccTransactionComplianceReportQueueSchema.ACQ_ReportType].ToString() == "ABC" &&
					((ZGuid)x[AccTransactionComplianceReportQueueSchema.ACQ_ParentID]) == line4.PK);
				AssertNotNull("line4Queue", line4Queue);
				AssertQueueRecord(line4Queue, AccTransactionLinesSchema.Constants.Prefix, line4.PK, InvoicingBase.AH_PostDate.Date, expectedNonTaxableSubCode);
			}
			else
			{
				AssertEquals("No Header queue records added", 0, reportQueuedHeaders.Count);
				AssertEquals("No Line queue records added", 0, reportQueuedLines.Count);
			}
		}

