			AddDefaultSettingToComplianceReportConfiguration(report, LedgerTypes.AccountsReceivable, TransactionTypes.CreditNote);
			AddDefaultSettingToComplianceReportConfiguration(report, LedgerTypes.AccountsPayable, TransactionTypes.Invoice);
			AddDefaultSettingToComplianceReportConfiguration(report, LedgerTypes.AccountsPayable, TransactionTypes.CreditNote);

			AccountingMasterFilesRegistry.Instance.ComplianceReportConfiguration.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, collection);

			#endregion

			InvoicingLineBase line = null, anotherline = null;

			if (InvoicingBase.Lines.AllowNew)
			{
				line = TestObjectCreator.CreateInvoiceLine(InvoicingBase, TestObjectCreator.CC1.PK, 100m);
				line.AL_JH = Job.PK;
				line.AL_AT = TaxRate.PK;
				TestObjectCreator.CreateCharge(line);
				anotherline = TestObjectCreator.CreateInvoiceLine(InvoicingBase, TestObjectCreator.CC2.PK, 200m);
				anotherline.AL_JH = Job.PK;
				anotherline.AL_AT = TaxRate.PK;
				TestObjectCreator.CreateCharge(anotherline);
			}

			Factory.Save();

			var reportQueuedHeaders = LoadReportQueuedHeaders(Factory, InvoicingBase.PK);
			var reportQueuedLines = LoadReportQueuedLines(Factory, InvoicingBase.PK);

			if (isComplianceReportApplicable)
			{
				AssertEquals("No Header queue records added", 0, reportQueuedHeaders.Count);
				AssertEquals("Two Line queue records added", 2, reportQueuedLines.Count);

				var abcReportQueue = reportQueuedLines.Cast<DynamicBusinessObject>().FirstOrDefault(x => x[AccTransactionComplianceReportQueueSchema.ACQ_ReportType].ToString() == "ABC");
				AssertQueueRecord(abcReportQueue, AccTransactionLinesSchema.Constants.Prefix, line.PK, InvoicingBase.AH_PostDate.Date, "ABC12345");

				var bbcReportQueue = reportQueuedLines.Cast<DynamicBusinessObject>().FirstOrDefault(x => x[AccTransactionComplianceReportQueueSchema.ACQ_ReportType].ToString() == "BBC");
				AssertQueueRecord(bbcReportQueue, AccTransactionLinesSchema.Constants.Prefix, line.PK, InvoicingBase.AH_PostDate.Date, "BBC23456");
			}
			else
			{
				AssertEquals("No Header queue records added", 0, reportQueuedHeaders.Count);
				AssertEquals("No Line queue records added", 0, reportQueuedLines.Count);
			}
		}

