		{
			AssertQueueForComplianceReportWithReportingDate(ReportingDateCodes.EarliestTaxDate);
		}

		public void TestQueueForComplianceReport_LatestTaxDate()
		{
			AssertQueueForComplianceReportWithReportingDate(ReportingDateCodes.LatestTaxDate);
		}

		void AssertQueueForComplianceReportWithReportingDate(ZString reportingDate)
		{
			var isComplianceReportApplicable = IsComplianceSequenceApplicable; // It is a misuse of this property, but we are after only AR/AP INV/CRD

			var taxRegistrationCodes = new OrgCodeLists().CustomsCodes_List(GlbCompany.CurrentCompany.Country);
			var taxRegistration = taxRegistrationCodes.ToArray().FirstOrDefault(x => !string.IsNullOrEmpty(x.Code));
			AssertNotNull("There should be a Tax Registration", taxRegistration);

			var postDate = ZDateTime.Now;
			var invoiceDate = postDate.AddDays(1);
			var receivedDate = postDate.AddDays(-1);
			var earliestTaxDate = postDate.AddDays(-2).Date;
			var latestTaxDate = postDate.AddDays(2).Date;

			var expectedQueueDate = getExpectedDate();

			ZDate getExpectedDate()
			{
				switch (reportingDate)
				{
					case ReportingDateCodes.PostDate:
						return postDate.Date;
					case ReportingDateCodes.InvoiceDate:
						return invoiceDate.Date;
					case ReportingDateCodes.DocumentReceivedDate:
						return receivedDate.Date;
					case ReportingDateCodes.EarliestTaxDate:
						return earliestTaxDate;
					case ReportingDateCodes.LatestTaxDate:
						return latestTaxDate;
					default:
						return ZDate.Invalid;
				}
			}

			#region Compliance Reports Configuration

			var collection = new ComplianceReportConfigurationCollection(Factory);
			// By Organisation, Ledger and Sub Code
			var report = collection.AddNew();
			report.Country = Env.CurrentCompany.Country.Code;
			report.ReportCode = "ABC";
			report.ReportBaseTablePrefix = AccTransactionLinesSchema.Constants.Prefix;
			report.ReportPeriodicity = "RNG";
			report.TaxRegistrationType = taxRegistration.Code;
			report.ReportLineGrouping = "";
			if (InvoicingBase.AH_Ledger == LedgerTypes.AccountsReceivable)
			{
				AddDefaultSettingToComplianceReportConfiguration(report, LedgerTypes.AccountsReceivable, TransactionTypes.Invoice, reportingDate);
				AddDefaultSettingToComplianceReportConfiguration(report, LedgerTypes.AccountsReceivable, TransactionTypes.CreditNote, reportingDate);
			}
			if (InvoicingBase.AH_Ledger == LedgerTypes.AccountsPayable)
			{
				AddDefaultSettingToComplianceReportConfiguration(report, LedgerTypes.AccountsPayable, TransactionTypes.Invoice, reportingDate);
				AddDefaultSettingToComplianceReportConfiguration(report, LedgerTypes.AccountsPayable, TransactionTypes.CreditNote, reportingDate);
			}

			AccountingMasterFilesRegistry.Instance.ComplianceReportConfiguration.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, collection);

			#endregion

			InvoicingBase.AH_PostDate = postDate;
			InvoicingBase.AH_InvoiceDate = invoiceDate;
			InvoicingBase.AH_DocumentReceivedDate = receivedDate;

			TaxRate.AT_Type = AccTaxRate.Types.Rated;
			TaxRate2.AT_Type = AccTaxRate.Types.Exempt;
			TaxRate3.AT_Type = AccTaxRate.Types.ReverseRated;

			InvoicingLineBase line1 = null, line2 = null, line3 = null;

			if (InvoicingBase.Ledger_ForTestOnly != LedgerTypes.TransactionsPendingAllocation) // Cannot add lines to Transaction Pending Allocation
			{
				InvoicingBase.Lines.RemoveAndDeleteAll();
				line1 = TestObjectCreator.CreateInvoiceLine(InvoicingBase, TestObjectCreator.CC1.PK, 100m);
				line1.AL_JH = Job.PK;
				line1.AL_AT = TaxRate.PK;
				line1.AL_TaxDate = latestTaxDate;
				TestObjectCreator.CreateCharge(line1);
				line2 = TestObjectCreator.CreateInvoiceLine(InvoicingBase, TestObjectCreator.CC2.PK, 200m);
				line2.AL_JH = Job.PK;
				line2.AL_AT = TaxRate2.PK;
				TestObjectCreator.CreateCharge(line2);
				line3 = TestObjectCreator.CreateInvoiceLine(InvoicingBase, TestObjectCreator.CC3.PK, 300m);
				line3.AL_JH = Job.PK;
				line3.AL_AT = TaxRate3.PK;
				line3.AL_TaxDate = earliestTaxDate;
				TestObjectCreator.CreateCharge(line3);
			}

			Factory.Save();

			var reportQueuedHeaders = LoadReportQueuedHeaders(Factory, InvoicingBase.PK);
			var reportQueuedLines = LoadReportQueuedLines(Factory, InvoicingBase.PK);

			if (isComplianceReportApplicable)
			{
				AssertEquals("No Header queue records added", 0, reportQueuedHeaders.Count);
				AssertEquals("Three Line queue records added", 3, reportQueuedLines.Count);

				var lineQueue = reportQueuedLines.Cast<DynamicBusinessObject>().FirstOrDefault(x => x[AccTransactionComplianceReportQueueSchema.ACQ_ReportType].ToString() == "ABC" &&
					((ZGuid)x[AccTransactionComplianceReportQueueSchema.ACQ_ParentID]) == line1.PK);
				AssertNotNull("line1Queue", lineQueue);
				AssertQueueRecord(lineQueue, AccTransactionLinesSchema.Constants.Prefix, line1.PK, expectedQueueDate);

				var line2Queue = reportQueuedLines.Cast<DynamicBusinessObject>().FirstOrDefault(x => x[AccTransactionComplianceReportQueueSchema.ACQ_ReportType].ToString() == "ABC" &&
					((ZGuid)x[AccTransactionComplianceReportQueueSchema.ACQ_ParentID]) == line2.PK);
				AssertNotNull("line2Queue", line2Queue);
				AssertQueueRecord(line2Queue, AccTransactionLinesSchema.Constants.Prefix, line2.PK, expectedQueueDate);

				var line3Queue = reportQueuedLines.Cast<DynamicBusinessObject>().FirstOrDefault(x => x[AccTransactionComplianceReportQueueSchema.ACQ_ReportType].ToString() == "ABC" &&
					((ZGuid)x[AccTransactionComplianceReportQueueSchema.ACQ_ParentID]) == line3.PK);
				AssertNotNull("line3Queue", line3Queue);
				AssertQueueRecord(line3Queue, AccTransactionLinesSchema.Constants.Prefix, line3.PK, expectedQueueDate);
			}
			else
			{
				AssertEquals("No Header queue records added", 0, reportQueuedHeaders.Count);
				AssertEquals("No Line queue records added", 0, reportQueuedLines.Count);
			}
		}

		#endregion

		void AssertQueueRecord(DynamicBusinessObject queueRecord, string parentTablePrefix, ZGuid parentPK, ZDate queueDate, string reportSubCode = "")
		{
			AssertNotNull(queueRecord);
			AssertEquals("ACQ_GC_Company", GlbCompany.CurrentCompany.PK.ToString(), queueRecord[AccTransactionComplianceReportQueueSchema.ACQ_GC_Company].ToString());
			AssertEquals("ACQ_GB_Branch", GlbBranch.CurrentBranch.PK.ToString(), queueRecord[AccTransactionComplianceReportQueueSchema.ACQ_GB_Branch].ToString());
			AssertEquals("ACQ_ParentTableCode", parentTablePrefix, queueRecord[AccTransactionComplianceReportQueueSchema.ACQ_ParentTableCode].ToString());
			AssertEquals("ACQ_ParentID", parentPK, (ZGuid)queueRecord[AccTransactionComplianceReportQueueSchema.ACQ_ParentID]);
			AssertEquals("ACQ_Date", queueDate, new ZDate(queueRecord[AccTransactionComplianceReportQueueSchema.ACQ_Date]));
			AssertEquals("ReportSubCode", reportSubCode, queueRecord["ReportSubCode"]);
			AssertNotEquals("Has unique PK", parentPK, (ZGuid)queueRecord[AccTransactionComplianceReportQueueSchema.PK]);
		}

