		public void TestReCalculateAndAdjustLineTaxAmountsToCorrectHeadersTaxAmountForWarehousePeriodicBilling()
		{
			if (InvoicingBase.AH_Ledger == LedgerTypes.AccountsReceivable)
			{
				CreateDummyPlugIn(true);
				Factory.Save();

				AssertEquals("Tax on charge 3", 30.00m, Job.Charges[2].JR_OSSellGSTAmt_Calc);
				AssertEquals("Tax on charge 4", 40.00m, Job.Charges[3].JR_OSSellGSTAmt_Calc);

				InvoicingPostManager postManager = new InvoicingPostManager(Job);
				postManager.CreateTransactions(JobInvoicingPostingOption.Revenue);

				AssertEquals("One invoice was posted", 1, postManager.Poster.PostedInvoices.Count);
				InvoicingLineBaseCollection invoiceLines = postManager.Poster.PostedInvoices[0].Lines;
				AssertEquals("Four lines were posted", 4, invoiceLines.Count);
				AssertEquals("Tax on line 3 was adjusted using the 'AdjustAgainstAllCharges' method because it is a warehouse periodic billing invoice",
					30.01m, invoiceLines[2].AL_GSTVAT);
				AssertEquals("Tax on line 4 was adjusted using the 'AdjustAgainstAllCharges' method because it is a warehouse periodic billing invoice",
					40.01m, invoiceLines[3].AL_GSTVAT);
			}
			else
			{
				Assert(true);
			}
		}

		public void TestReCalculateAndAdjustLineTaxAmountsToCorrectHeadersTaxAmountForNonWarehousePeriodicBilling()
		{
			if (InvoicingBase.AH_Ledger == LedgerTypes.AccountsReceivable)
			{
				bool oldRegistryValue = AccountingConfigurationRegistry.Instance.CalculateTaxAtHeaderLevel.Value;

				try
				{
					AccountingConfigurationRegistry.Instance.CalculateTaxAtHeaderLevel.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, true);
					CreateDummyPlugIn(false);
					Factory.Save();

					AssertEquals("Tax on charge 3", 30.00m, Job.Charges[2].JR_OSSellGSTAmt_Calc);
					AssertEquals("Tax on charge 4 not adjusted, since we don't adjust for charge anymore",
						40.00m, Job.Charges[3].JR_OSSellGSTAmt_Calc);

					InvoicingPostManager postManager = new InvoicingPostManager(Job);
					postManager.CreateTransactions(JobInvoicingPostingOption.Revenue);

					AssertEquals("One invoice was posted", 1, postManager.Poster.PostedInvoices.Count);
					InvoicingLineBaseCollection invoiceLines = postManager.Poster.PostedInvoices[0].Lines;
					AssertEquals("Four lines were posted", 4, invoiceLines.Count);
					AssertEquals("Tax on line 3 was not adjusted because it is not a warehouse periodic billing invoice and tax is adjusted against the largest charge",
						30.00m, invoiceLines[2].AL_GSTVAT);
					AssertEquals("Tax on line 4 only adjusted because it is not a warehouse periodic billing invoice and tax is adjusted against the largest charge",
						40.02m, invoiceLines[3].AL_GSTVAT);
				}
				finally
				{
					AccountingConfigurationRegistry.Instance.CalculateTaxAtHeaderLevel.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, oldRegistryValue);
				}
			}
			else
			{
				Assert(true);
			}
		}

