		ComplianceReportConfigurationSetting AddDefaultSettingToComplianceReportConfiguration(ComplianceReportConfiguration report, ZString ledger, ZString transactionType, ZString? reportingDate = null)
		{
			var result = report.Settings.AddNew();

			result.ComplianceSubType = "";
			result.LedgerType = ledger;
			result.InvoiceType = transactionType;
			result.TaxInvoiceRule = TaxInvoiceRuleCodes.ContainsAtLeastOneTaxID; // "TID";
			result.DisbursementRule = DisbursementRuleCodes.NonDisbursementOnly; // "NDB";
			result.OriginalRule = OriginalRuleCodes.OriginalTransactionOnly; //"OTO";
			result.OrganisationLocation = "";
			result.ReportingDate = reportingDate ?? ReportingDateCodes.PostDate;

			return result;
		}

		void CreateDummyPlugIn(bool setWhsConsumerType)
		{
			IJobInvoicingPlugIn plugIn;
			if (setWhsConsumerType)
			{
				plugIn = (JobStorage)Factory.NewWithValidTestData(ObjectFactory.GetType(typeof(Enterprise.Integration.Warehouse.IWhsInvoice)));
			}
			else
			{
				plugIn = Factory.NewWithValidTestData<ForwardingShipment>();
			}
			Job.PlugInData = plugIn;
			TestObjectCreator.CreateCharge(Job, TestObjectCreator.CC1, "Test", TestObjectCreator.AUD, 0m, TestObjectCreator.Creditor1, TestObjectCreator.AUD, 100.04m, TestObjectCreator.LocalClient);
			TestObjectCreator.CreateCharge(Job, TestObjectCreator.CC1, "Test", TestObjectCreator.AUD, 0m, TestObjectCreator.Creditor1, TestObjectCreator.AUD, 200.04m, TestObjectCreator.LocalClient);
			TestObjectCreator.CreateCharge(Job, TestObjectCreator.CC1, "Test", TestObjectCreator.AUD, 0m, TestObjectCreator.Creditor1, TestObjectCreator.AUD, 300.04m, TestObjectCreator.LocalClient);
			TestObjectCreator.CreateCharge(Job, TestObjectCreator.CC1, "Test", TestObjectCreator.AUD, 0m, TestObjectCreator.Creditor1, TestObjectCreator.AUD, 400.04m, TestObjectCreator.LocalClient);
		}

		public void TestExpectedInvoiceTotal_Validation()
		{
			var invoice = TestObjectCreator.CreateAPInvoice<APInvoice>("1", TestObjectCreator.AUD, 1m, 1000m, 100m, 0m, 1000m, 100m, 0m);
			invoice.SubmittedFromInvoicingForm = true;
			invoice.AH_OH = TestObjectCreator.AALSHI.PK;
			Assert(invoice.Lines.Count > 0);
			invoice.ValidateExpectedInvoiceTotal = true;

			invoice.ExpectedInvoiceTotal = 1100m;
			invoice.ExpectedInvoiceTaxTotal = 100m;
			AssertEquals(1100m, invoice.ExpectedInvoiceTotal);
			AssertEquals(100m, invoice.ExpectedInvoiceTaxTotal);
			AssertEquals(1000m, invoice.ExpectedInvoiceExclTaxTotal);
			AssertNoErrors(invoice.ExpectedInvoiceTotalInfo);
			AssertNoErrors(invoice.ExpectedInvoiceTaxTotalInfo);
			AssertNoErrors(invoice.ExpectedInvoiceExclTaxTotalInfo);

			//Test a setter of ExpectedInvoiceTotal
			invoice.ExpectedInvoiceExclTaxTotal = 900m;
			invoice.ExpectedInvoiceTaxTotal = 200m;
			invoice.ExpectedInvoiceTotal = 2000m;
			AssertEquals(2000m, invoice.ExpectedInvoiceTotal);
			AssertEquals(200m, invoice.ExpectedInvoiceTaxTotal);
			AssertEquals(900m, invoice.ExpectedInvoiceExclTaxTotal);
			AssertNoWarnings(invoice.ExpectedInvoiceTotalInfo);
			var oSCurrencyDecimals = invoice.OSCurrencyDecimals;
			var expectedInvoiceTaxAmountMessage = string.Format(@"The total invoice tax amount of {0} {1} does not equal to the expected amount of {2} {1}.
The difference is {3} {1}.", invoice.AH_OSTaxAmount.ToString(oSCurrencyDecimals), invoice.AH_RX_NKTransactionCurrency, invoice.ExpectedInvoiceTaxTotal.ToString(oSCurrencyDecimals), invoice.UnallocatedInvoiceTaxTotal.ToString(oSCurrencyDecimals));
			var expectedInvoiceExclTaxMessage = string.Format(@"The total invoice excluding tax amount of {0} {1} does not equal to the expected amount of {2} {1}.
The difference is {3} {1}.", invoice.AH_OSExTaxAmount.ToString(oSCurrencyDecimals), invoice.AH_RX_NKTransactionCurrency, invoice.ExpectedInvoiceExclTaxTotal.ToString(oSCurrencyDecimals), invoice.UnallocatedInvoiceExclTaxTotal.ToString(oSCurrencyDecimals));
			AssertHasWarning(invoice.ExpectedInvoiceTaxTotalInfo, expectedInvoiceTaxAmountMessage);
			AssertHasWarning(invoice.ExpectedInvoiceExclTaxTotalInfo, expectedInvoiceExclTaxMessage);

			AccountingConfigurationRegistry.Instance.EnforceExpectedTotalTaxAndExcludingTaxAmountValidation.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);
			invoice.Validation.ValidateAll();

			AssertHasError(invoice.ExpectedInvoiceTaxTotalInfo, expectedInvoiceTaxAmountMessage);
			AssertHasError(invoice.ExpectedInvoiceExclTaxTotalInfo, expectedInvoiceExclTaxMessage);

			AccountingConfigurationRegistry.Instance.EnforceExpectedTotalTaxAndExcludingTaxAmountValidation.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, false);
			invoice.ExpectedInvoiceTotal = 1100m;
			invoice.ExpectedInvoiceTaxTotal = 100m;
			invoice.ExpectedInvoiceExclTaxTotal = 1000m;
			invoice.Validation.ValidateAll();
			AssertNoWarnings(invoice.ExpectedInvoiceTotalInfo);
			AssertNoWarnings(invoice.ExpectedInvoiceTaxTotalInfo);
			AssertNoWarnings(invoice.ExpectedInvoiceExclTaxTotalInfo);

			//Test a setter of ExpectedInvoiceTaxTotal
			invoice.ExpectedInvoiceExclTaxTotal = 900m;
			invoice.ExpectedInvoiceTotal = 1500m;
			invoice.ExpectedInvoiceTaxTotal = 300m;
			var expectedInvoiceTotalMessage = string.Format(@"The invoice total of {0} {1} does not equal to the expected amount of {2} {1}.
The difference is {3} {1}.", invoice.AH_OSTotalAmount.ToString(oSCurrencyDecimals), invoice.AH_RX_NKTransactionCurrency, invoice.ExpectedInvoiceTotal.ToString(oSCurrencyDecimals), invoice.UnallocatedInvoiceTotal.ToString(oSCurrencyDecimals));

			AssertEquals(1500m, invoice.ExpectedInvoiceTotal);
			AssertEquals(300m, invoice.ExpectedInvoiceTaxTotal);
			AssertEquals(900m, invoice.ExpectedInvoiceExclTaxTotal);
			AssertHasError(invoice.ExpectedInvoiceTotalInfo, expectedInvoiceTotalMessage);
			AssertNoWarnings(invoice.ExpectedInvoiceTaxTotalInfo);
			AssertHasWarning(invoice.ExpectedInvoiceExclTaxTotalInfo, expectedInvoiceExclTaxMessage);

			invoice.ExpectedInvoiceTotal = 1100m;
			invoice.ExpectedInvoiceTaxTotal = 100m;
			invoice.ExpectedInvoiceExclTaxTotal = 1000m;
			invoice.Validation.ValidateAll();
			AssertNoWarnings(invoice.ExpectedInvoiceTotalInfo);
			AssertNoWarnings(invoice.ExpectedInvoiceTaxTotalInfo);
			AssertNoWarnings(invoice.ExpectedInvoiceExclTaxTotalInfo);

			//Test a setter of ExpectedInvoiceExclTaxTotal
			invoice.ExpectedInvoiceTotal = 1500m;
			invoice.ExpectedInvoiceTaxTotal = 300m;
			invoice.ExpectedInvoiceExclTaxTotal = 900m;
			expectedInvoiceTaxAmountMessage = string.Format(@"The total invoice tax amount of {0} {1} does not equal to the expected amount of {2} {1}.
The difference is {3} {1}.", invoice.AH_OSTaxAmount.ToString(oSCurrencyDecimals), invoice.AH_RX_NKTransactionCurrency, invoice.ExpectedInvoiceTaxTotal.ToString(oSCurrencyDecimals), invoice.UnallocatedInvoiceTaxTotal.ToString(oSCurrencyDecimals));

			AssertEquals(1500m, invoice.ExpectedInvoiceTotal);
			AssertEquals(300m, invoice.ExpectedInvoiceTaxTotal);
			AssertEquals(900m, invoice.ExpectedInvoiceExclTaxTotal);
			AssertHasError(invoice.ExpectedInvoiceTotalInfo, expectedInvoiceTotalMessage);
			AssertHasWarning(invoice.ExpectedInvoiceTaxTotalInfo, expectedInvoiceTaxAmountMessage);
			AssertNoWarnings(invoice.ExpectedInvoiceExclTaxTotalInfo);
		}

		public void TestExpectedTaxAndExclTaxTotalValidation_SuspendExpectedInvoiceTotalValidation()
		{
			var invoice = TestObjectCreator.CreateAPInvoice<APInvoice>("2", TestObjectCreator.AUD, 1m, 1000m, 100m, 0m, 1000m, 100m, 0m);
			invoice.SubmittedFromInvoicingForm = true;
			invoice.AH_OH = TestObjectCreator.AALSHI.PK;
			invoice.ValidateExpectedInvoiceTotal = true;

			invoice.ExpectedInvoiceExclTaxTotal = 1800m;
			invoice.ExpectedInvoiceTaxTotal = 180;
			invoice.ExpectedInvoiceTotal = 5500m;

			var oSCurrencyDecimals = invoice.OSCurrencyDecimals;
			var expectedInvoiceTaxAmountMessage = string.Format(@"The total invoice tax amount of {0} {1} does not equal to the expected amount of {2} {1}.
The difference is {3} {1}.", invoice.AH_OSTaxAmount.ToString(oSCurrencyDecimals), invoice.AH_RX_NKTransactionCurrency, invoice.ExpectedInvoiceTaxTotal.ToString(oSCurrencyDecimals), invoice.UnallocatedInvoiceTaxTotal.ToString(oSCurrencyDecimals));
			var expectedInvoiceExclTaxMessage = string.Format(@"The total invoice excluding tax amount of {0} {1} does not equal to the expected amount of {2} {1}.
The difference is {3} {1}.", invoice.AH_OSExTaxAmount.ToString(oSCurrencyDecimals), invoice.AH_RX_NKTransactionCurrency, invoice.ExpectedInvoiceExclTaxTotal.ToString(oSCurrencyDecimals), invoice.UnallocatedInvoiceExclTaxTotal.ToString(oSCurrencyDecimals));

			using (invoice.SuspendExpectedInvoiceTotalValidation)
			{
				AssertEquals(true, invoice.IsSuspendingExpectedInvoiceTotalValidation);

				AccountingConfigurationRegistry.Instance.EnforceExpectedTotalTaxAndExcludingTaxAmountValidation.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);
				invoice.Validation.ValidateAll();
				AssertHasWarning("A warning message is expected", invoice.ExpectedInvoiceTaxTotalInfo, expectedInvoiceTaxAmountMessage);
				AssertHasWarning("A warning message is expected", invoice.ExpectedInvoiceExclTaxTotalInfo, expectedInvoiceExclTaxMessage);
				AssertNoErrors("No error message is expected", invoice.ExpectedInvoiceTaxTotalInfo);
				AssertNoErrors("No error message is expected", invoice.ExpectedInvoiceExclTaxTotalInfo);

				AccountingConfigurationRegistry.Instance.EnforceExpectedTotalTaxAndExcludingTaxAmountValidation.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, false);
				invoice.Validation.ValidateAll();
				AssertHasWarning("A warning message is expected", invoice.ExpectedInvoiceTaxTotalInfo, expectedInvoiceTaxAmountMessage);
				AssertHasWarning("A warning message is expected", invoice.ExpectedInvoiceExclTaxTotalInfo, expectedInvoiceExclTaxMessage);
				AssertNoErrors("No error message is expected", invoice.ExpectedInvoiceTaxTotalInfo);
				AssertNoErrors("No error message is expected", invoice.ExpectedInvoiceExclTaxTotalInfo);
			}

			AssertEquals(false, invoice.IsSuspendingExpectedInvoiceTotalValidation);

			AccountingConfigurationRegistry.Instance.EnforceExpectedTotalTaxAndExcludingTaxAmountValidation.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);
			invoice.Validation.ValidateAll();
			AssertNoWarnings(invoice.ExpectedInvoiceTaxTotalInfo);
			AssertNoWarnings(invoice.ExpectedInvoiceExclTaxTotalInfo);
			AssertHasError("A error message is expected", invoice.ExpectedInvoiceTaxTotalInfo, expectedInvoiceTaxAmountMessage);
			AssertHasError("A error message is expected", invoice.ExpectedInvoiceExclTaxTotalInfo, expectedInvoiceExclTaxMessage);

			AccountingConfigurationRegistry.Instance.EnforceExpectedTotalTaxAndExcludingTaxAmountValidation.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, false);
			invoice.Validation.ValidateAll();
			AssertHasWarning("A warning message is expected", invoice.ExpectedInvoiceTaxTotalInfo, expectedInvoiceTaxAmountMessage);
			AssertHasWarning("A warning message is expected", invoice.ExpectedInvoiceExclTaxTotalInfo, expectedInvoiceExclTaxMessage);
			AssertNoErrors("No error message is expected", invoice.ExpectedInvoiceTaxTotalInfo);
			AssertNoErrors("No error message is expected", invoice.ExpectedInvoiceExclTaxTotalInfo);
		}

		public void TestValidateExpectedInvoiceTotalSecurityIsAllowed()
		{
			bool originalAPInvSecurity = Env.Security.AllowAPInvoiceChangeDefaultExpectedTotalValue.IsAllowed;
			bool originalAPACrdecurity = Env.Security.AllowAPCreditNoteChangeDefaultExpectedTotalValue.IsAllowed;
			bool originalAPAdjSecurity = Env.Security.AllowAPAdjustNoteChangeDefaultExpectedTotalValue.IsAllowed;

			try
			{
				Env.Security.AllowAPInvoiceChangeDefaultExpectedTotalValue.IsAllowed = false;
				Env.Security.AllowAPCreditNoteChangeDefaultExpectedTotalValue.IsAllowed = false;
				Env.Security.AllowAPAdjustNoteChangeDefaultExpectedTotalValue.IsAllowed = false;

				if (InvoicingBase is APInvoice || InvoicingBase is APCreditNote || InvoicingBase is APAdjustmentNote)
				{
					AssertEquals("Readonly", false, InvoicingBase.ValidateExpectedInvoiceTotalSecurityIsAllowed_ForTestOnly);
				}
				else
				{
					AssertEquals("Not Readonly", true, InvoicingBase.ValidateExpectedInvoiceTotalSecurityIsAllowed_ForTestOnly);
				}
			}
			finally
			{
				Env.Security.AllowAPInvoiceChangeDefaultExpectedTotalValue.IsAllowed = originalAPInvSecurity;
				Env.Security.AllowAPCreditNoteChangeDefaultExpectedTotalValue.IsAllowed = originalAPACrdecurity;
				Env.Security.AllowAPAdjustNoteChangeDefaultExpectedTotalValue.IsAllowed = originalAPAdjSecurity;
			}
		}

		public void TestValidateExpectedInvoiceTotal_ReadOnly()
		{
			bool originalAPInvSecurity = Env.Security.AllowAPInvoiceChangeDefaultExpectedTotalValue.IsAllowed;
			bool originalAPACrdecurity = Env.Security.AllowAPCreditNoteChangeDefaultExpectedTotalValue.IsAllowed;
			bool originalAPAdjSecurity = Env.Security.AllowAPAdjustNoteChangeDefaultExpectedTotalValue.IsAllowed;

			try
			{
				Env.Security.AllowAPInvoiceChangeDefaultExpectedTotalValue.IsAllowed = true;
				APInvoice invInDB = TestObjectCreator.CreateAPInvoice<APInvoice>("1", TestObjectCreator.AUD, 1m, 100m, 0m, 0m, 100m, 0m, 0m);
				Factory.Save();
				APInvoice invNotInDB = TestObjectCreator.CreateAPInvoice<APInvoice>("2", TestObjectCreator.AUD, 1m, 100m, 0m, 0m, 100m, 0m, 0m);
				AssertEquals("Not ReadOnly", false, invInDB.ValidateExpectedInvoiceTotal_ReadOnly_ForTestOnly);
				AssertEquals("Not ReadOnly", false, invNotInDB.ValidateExpectedInvoiceTotal_ReadOnly_ForTestOnly);

				Env.Security.AllowAPInvoiceChangeDefaultExpectedTotalValue.IsAllowed = false;
				AssertEquals("ReadOnly", true, invInDB.ValidateExpectedInvoiceTotal_ReadOnly_ForTestOnly);
				AssertEquals("Not ReadOnly", false, invNotInDB.ValidateExpectedInvoiceTotal_ReadOnly_ForTestOnly);

				Env.Security.AllowAPAdjustNoteChangeDefaultExpectedTotalValue.IsAllowed = true;
				APAdjustmentNote adjInDB = TestObjectCreator.CreateAdjustmentNote<APAdjustmentNote>("3", 100m, 0m, ZDateTime.Today, TestObjectCreator.AALSHI.PK);
				Factory.Save();
				APAdjustmentNote adjNotInDB = TestObjectCreator.CreateAdjustmentNote<APAdjustmentNote>("4", 100m, 0m, ZDateTime.Today, TestObjectCreator.AALSHI.PK);
				AssertEquals("Not ReadOnly", false, adjInDB.ValidateExpectedInvoiceTotal_ReadOnly_ForTestOnly);
				AssertEquals("Not ReadOnly", false, adjNotInDB.ValidateExpectedInvoiceTotal_ReadOnly_ForTestOnly);

				Env.Security.AllowAPAdjustNoteChangeDefaultExpectedTotalValue.IsAllowed = false;
				AssertEquals("ReadOnly", true, adjInDB.ValidateExpectedInvoiceTotal_ReadOnly_ForTestOnly);
				AssertEquals("Not ReadOnly", false, adjNotInDB.ValidateExpectedInvoiceTotal_ReadOnly_ForTestOnly);

				Env.Security.AllowAPCreditNoteChangeDefaultExpectedTotalValue.IsAllowed = true;
				APCreditNote crdInDB = TestObjectCreator.CreateAPCreditNote("5", TestObjectCreator.AALSHI, TestObjectCreator.AUD, 1m, "desc");
				Factory.Save();
				APCreditNote crdNotInDB = TestObjectCreator.CreateAPCreditNote("6", TestObjectCreator.AALSHI, TestObjectCreator.AUD, 1m, "desc");
				AssertEquals("Not ReadOnly", false, crdInDB.ValidateExpectedInvoiceTotal_ReadOnly_ForTestOnly);
				AssertEquals("Not ReadOnly", false, crdNotInDB.ValidateExpectedInvoiceTotal_ReadOnly_ForTestOnly);

				Env.Security.AllowAPCreditNoteChangeDefaultExpectedTotalValue.IsAllowed = false;
				AssertEquals("ReadOnly", true, crdInDB.ValidateExpectedInvoiceTotal_ReadOnly_ForTestOnly);
				AssertEquals("Not ReadOnly", false, crdNotInDB.ValidateExpectedInvoiceTotal_ReadOnly_ForTestOnly);
			}
			finally
			{
				Env.Security.AllowAPInvoiceChangeDefaultExpectedTotalValue.IsAllowed = originalAPInvSecurity;
				Env.Security.AllowAPCreditNoteChangeDefaultExpectedTotalValue.IsAllowed = originalAPACrdecurity;
				Env.Security.AllowAPAdjustNoteChangeDefaultExpectedTotalValue.IsAllowed = originalAPAdjSecurity;
			}
		}

