		{
			if (InvoicingBase is APInvoice || InvoicingBase is APCreditNote)
			{
				var shipment = TestObjectCreator.CreateShipment("S00001");
				var job = TestObjectCreator.CreateJob(shipment);
				var invoicingBase = TestObjectCreator.CreateInvoice(InvoicingBase.GetType(), "INV1", TestObjectCreator.AUD, 1M);
				invoicingBase.AH_ExchangeRate = 0.131506272m;
				invoicingBase.AH_RX_NKTransactionCurrency = "USD";
				invoicingBase.AH_JH = job.PK;

				var departureDate = new ZDateTime(2011, 11, 20);
				shipment.JS_RL_NKOrigin = "AUBNE";
				shipment.JS_RL_NKDestination = "JPTYO";
				shipment.JS_E_DEP = departureDate;
				Factory.Save();

				ExchangeRateReader.GetReaderInstance().ClearCache();

				AssertNull("Current setup - no Creditor", invoicingBase.Header);
				AssertEquals("Falls back to AH_ExchangeRate", 0.131506m, invoicingBase.GetExchangeRateFromInvoicingPlugIn(job.ExchangeRateConfigurationRateConsumer));

				invoicingBase.AH_OH = TestObjectCreator.Creditor1.PK;
				Factory.Save();
				AssertEquals("Falls back to AH_ExchangeRate", 0.131506m, invoicingBase.GetExchangeRateFromInvoicingPlugIn(job.ExchangeRateConfigurationRateConsumer));

				RefExchangeRate rate = TestObjectCreator.USD.ExchangeRates.AddNew();
				rate.RE_StartDate = ZDateTime.Today;
				rate.RE_ExpiryDate = ZDateTime.Today;
				rate.RE_ExRateType = nameof(ExchangeRateType.Buy);
				rate.RE_SellRate = 2.0m;

				rate = TestObjectCreator.USD.ExchangeRates.AddNew();
				rate.RE_StartDate = departureDate;
				rate.RE_ExpiryDate = departureDate;
				rate.RE_ExRateType = nameof(ExchangeRateType.Buy);
				rate.RE_SellRate = 1.0m;
				Factory.Save();

				ExchangeRateReader.GetReaderInstance().ClearCache();
				AssertEquals("Falls back to today's exchange rate", 2.0m, invoicingBase.GetExchangeRateFromInvoicingPlugIn(job.ExchangeRateConfigurationRateConsumer));

				var currentCompany = Factory.Load<GlbCompany>(Env.CurrentCompanyPK);
				currentCompany.AccExchangeRateConfigurations.SetExRate("SHP", "IMP", "ALL", preference: "HAR");
				currentCompany.AccExchangeRateConfigurations.SetExRate("SHP", "EXP", "ALL", preference: "HDR");
				invoicingBase.Header.CompanyData.AccAPExchangeRateConfigurations.Reload(reLoadExistingRows: false); // Have to reload collection to pick up the Company level settings
				Factory.Save();

				using (AccountingConfigurationRegistry.Instance.FallBackToPreviousExchangeRate.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, false))
				{
					ExchangeRateReader.GetReaderInstance().ClearCache();
					var reloadFactory = new BusinessObjectFactory();
					var reloadedJob = reloadFactory.Load<Job>(job.PK);
					reloadedJob.InitializeParentFromGenericJobWithoutSettingDefaults();
					AssertEquals("Falls back to the exchange rate from ATA", 1.0m, invoicingBase.GetExchangeRateFromInvoicingPlugIn(reloadedJob.ExchangeRateConfigurationRateConsumer));
				}
			}
			else
			{
				Assert(true);
			}
		}

