		public void TestAdjustAmountsForConsolCostBeforeImporting()
		{
			if (InvoicingBase is APInvoice || InvoicingBase is APCreditNote)
			{
				BusinessObjectFactory factory = new BusinessObjectFactory();
				TestObjectCreator creator = new TestObjectCreator(factory);
				var consol = creator.CreateConsol("AUSYD", "NZAKL", "C0001");
				var shipment1 = creator.CreateShipment("S00001001", "AUSYD", "NZAKL", consol);
				var shipment2 = creator.CreateShipment("S00001002", "AUSYD", "NZAKL", consol);
				var shipment3 = creator.CreateShipment("S00001003", "AUSYD", "NZAKL", consol);

				using (Job job1 = creator.CreateJob(shipment1))
				using (Job job2 = creator.CreateJob(shipment2))
				using (Job job3 = creator.CreateJob(shipment3))
				{
					var invoicingBase = creator.CreateInvoice(InvoicingBase.GetType(), "INV1", creator.USD, 1.2966M);
					var cost = creator.CreateConsolCost(invoicingBase, consol, creator.CC1, 2050m);
					cost.E6_ApportionmentMethod = ZArchitecture.Core.AllocationMethod.Manual;
					cost.E6_RX_NKCurrency = "USD";
					cost.E6_ExchangeRate = 1.2966m;
					cost.E6_OSCostAmount = 2050m;

					AssertEquals(3, cost.ApportionmentCharges.Count);

					cost.ApportionmentCharges[0].JR_OSCostAmt = 288.34m;
					cost.ApportionmentCharges[1].JR_OSCostAmt = 651.19m;
					cost.ApportionmentCharges[2].JR_OSCostAmt = 1110.47m;

					//Local cost amounts are manually modified because the following amounts have been entered on the client's system.
					var charge1 = factory.Load<JobCharge>(cost.ApportionmentCharges[0].PK);
					charge1.JR_LocalCostAmt = 222.00m;
					var charge2 = factory.Load<JobCharge>(cost.ApportionmentCharges[1].PK);
					charge2.JR_LocalCostAmt = 501.38m;
					var charge3 = factory.Load<JobCharge>(cost.ApportionmentCharges[2].PK);
					charge3.JR_LocalCostAmt = 855.00m;

					AssertEquals(222.00m, cost.ApportionmentCharges[0].JR_LocalCostAmt);
					AssertEquals(501.38m, cost.ApportionmentCharges[1].JR_LocalCostAmt);
					AssertEquals(855.00m, cost.ApportionmentCharges[2].JR_LocalCostAmt);

					ZDecimal totalLocal = cost.ApportionmentCharges[0].JR_LocalCostAmt + cost.ApportionmentCharges[1].JR_LocalCostAmt + cost.ApportionmentCharges[2].JR_LocalCostAmt;
					AssertNotEquals("Not adjusted before importing", totalLocal, cost.E6_LocalCostAmount);
					invoicingBase.ImportAllApportionmentsFromCosting();
					totalLocal = cost.ApportionmentCharges[0].JR_LocalCostAmt + cost.ApportionmentCharges[1].JR_LocalCostAmt + cost.ApportionmentCharges[2].JR_LocalCostAmt;
					AssertEquals("Max charge adjusted", 857.68m, cost.ApportionmentCharges[2].JR_LocalCostAmt);
					AssertEquals("Adjusted after importing", totalLocal, cost.E6_LocalCostAmount);

					AssertEquals(3, invoicingBase.Lines.Count);
					AssertEquals(222.00m, invoicingBase.Lines[0].AL_LocalExTaxAmount);
					AssertEquals(501.38m, invoicingBase.Lines[1].AL_LocalExTaxAmount);
					AssertEquals(857.68m, invoicingBase.Lines[2].AL_LocalExTaxAmount);
				}
			}
			else
			{
				Assert(true);
			}
		}

		public void TestInvoiceLineErrorWhenConsolCostHasErrors()
		{
			if (InvoicingBase is APInvoice || InvoicingBase is APCreditNote)
			{
				TestObjectCreator creator = new TestObjectCreator(Factory);
				var consol = creator.CreateConsol("AUSYD", "NZAKL", "C0001");
				var shipment1 = creator.CreateShipment("S00001001", "AUSYD", "NZAKL", consol);
				var shipment2 = creator.CreateShipment("S00001002", "AUSYD", "NZAKL", consol);
				var job1 = creator.CreateJob(shipment1, false);
				var job2 = creator.CreateJob(shipment2, false);

				var invoicingBase = creator.CreateInvoice(InvoicingBase.GetType(), "INV1", creator.USD, 1.2966M);
				var cost = creator.CreateConsolCost(invoicingBase, consol, creator.CC12, 100m);

				AssertEquals(" Precondition: ApportionmentCharges.Count ", 2, cost.ApportionmentCharges.Count);
				invoicingBase.ImportAllApportionmentsFromCosting();
				AssertEquals(" Precondition: invoicingBase.Lines.Count ", 2, invoicingBase.Lines.Count);

				var errorMessage = "The related consol cost is invalid, please fix the following errors in the consol cost from which this line was apportioned:\r\nBranch: Enter a valid Branch.\r\n";

				invoicingBase.CheckConsolIDFromApportionedChargeCallCount_ForTestOnly = 0;
				invoicingBase.RunPreSaveValidation();
				var line = invoicingBase.Lines[0];

				AssertEquals(" CheckConsolIDFromApportionedChargeCallCount_ForTestOnly should be called once: ", 1, invoicingBase.CheckConsolIDFromApportionedChargeCallCount_ForTestOnly);
				AssertNoRowError(line, errorMessage);

				var tempJR_GB = cost.ApportionmentCharges[0].JR_GB;
				cost.ApportionmentCharges[0].JR_GB = ZGuid.NewZGuid();
				invoicingBase.CheckConsolIDFromApportionedChargeCallCount_ForTestOnly = 0;
				invoicingBase.RunPreSaveValidation();
				AssertEquals(" CheckConsolIDFromApportionedChargeCallCount_ForTestOnly should be called once: ", 1, invoicingBase.CheckConsolIDFromApportionedChargeCallCount_ForTestOnly);
				AssertHasRowError("Invalid consol cost makes line invalid", line, errorMessage);

				cost.ApportionmentCharges[0].JR_GB = ZGuid.NewZGuid();
				invoicingBase.CheckConsolIDFromApportionedChargeCallCount_ForTestOnly = 0;
				invoicingBase.RunPreSaveValidation();
				AssertEquals(" CheckConsolIDFromApportionedChargeCallCount_ForTestOnly should be called once: ", 1, invoicingBase.CheckConsolIDFromApportionedChargeCallCount_ForTestOnly);
				AssertHasRowError("Calling RunPresaveValidation 2 times still generates error", line, errorMessage);

				cost.ApportionmentCharges[0].JR_GB = tempJR_GB;
				invoicingBase.CheckConsolIDFromApportionedChargeCallCount_ForTestOnly = 0;
				invoicingBase.RunPreSaveValidation();
				AssertEquals(" CheckConsolIDFromApportionedChargeCallCount_ForTestOnly should be called once: ", 1, invoicingBase.CheckConsolIDFromApportionedChargeCallCount_ForTestOnly);
				AssertNoRowError(line, errorMessage);
			}
			else
			{
				Assert(true);
			}
		}

		public void TestPreSaveValidationChecksINVeDocsWhenTransactionCannotBeReprinted()
		{
			var isApplicableInvocingBase = InvoicingBase is ARInvoice || InvoicingBase is ARCreditNote;

			if (isApplicableInvocingBase)
			{
				using (AccountingMasterFilesRegistry.Instance.AllowRePrintingOfInvoicesAndCreditNotes.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, false))
				{
					Assert("CanChangeINVDocTypeOnPostedTransaction shoulkd be false", !AccountingCountrySpecificValidationHelper.CanChangeINVDocTypeOnPostedTransaction(InvoicingBase));
					Factory.Save();

					var notification = new NotificationBuffer();
					AssertEquals("AR Invoice should not have any document in EDocs", 0, InvoicingBase.DocManagerInfo.AllEDocs.Count);

					var eDoc = (StorageDocsBase)InvoicingBase.DocManagerInfo.AddFileOrDocument(contents: new byte[] { 0 }, filenameOnly: "Invoice", documentType: "INV", description: "Printed Invoice");
					eDoc.SC_IsSystemGenerated = true;
					InvoicingBase.DocManagerInfo.SetupEDocsFactoryToBeSavedWithMainFactory(false);
					Factory.Save();

					var docStorage = ((InvoicingDocManagerInfo)InvoicingBase.DocManagerInfo).InvoiceDocStorageMain;

					InvoicingBase.RunPreSaveValidation();
					AssertNoErrors(InvoicingBase);
					Assert(!docStorage.HasRowErrors);
					Assert(!eDoc.HasRowErrors);

					eDoc.SC_DocType = "CRF";
					InvoicingBase.RunPreSaveValidation();
					Assert(!docStorage.HasRowErrors);
					Assert(eDoc.HasRowErrors);
					AssertHasRowError(eDoc, "Updating the Document Type for system generated AR documents of document type INV is not allowed. Please close the form without saving to discard your changes.");

					eDoc.SC_DocType = "INV";
					InvoicingBase.RunPreSaveValidation();
					AssertNoErrors(InvoicingBase);
					Assert(!docStorage.HasRowErrors);
					Assert(!eDoc.HasRowErrors);

					eDoc.SC_IsDeleted = true;
					InvoicingBase.RunPreSaveValidation();
					Assert(!docStorage.HasRowErrors);
					Assert(eDoc.HasRowErrors);
					AssertHasRowError(eDoc, @"Deleting system generated AR documents of document type INV is not allowed. These documents must remain on file to allow re-printing if required.
To restore the document, tick on the ‘Show Deleted Documents’ option. Then right click on the deleted document and click the ‘Restore’ action.");

					eDoc.SC_IsDeleted = false;
					InvoicingBase.RunPreSaveValidation();
					AssertNoErrors(InvoicingBase);
					Assert(!docStorage.HasRowErrors);
					Assert(!eDoc.HasRowErrors);

					eDoc.Delete();
					InvoicingBase.RunPreSaveValidation();
					Assert(docStorage.HasRowErrors);
					AssertHasRowError(docStorage, @"One or more INV type document(s) have been changed in the eDocs tab.
Possible causes:
- Permanently deleting system generated AR documents of document type INV is not allowed. These documents must remain on file to allow re-printing if required.
- Another user has modified the INV type documents on another form while you were working on it.
Please close the form without saving to discard your changes.");
				}
			}
			else
			{
				Assert(true);
			}
		}

		public void TestLocalTaxAmountWhenIsTransactionTrue()
		{
			if (InvoicingBase is ARInvoice)
			{
				using (GlbCompany.CurrentCompany.TemporarilySetCountry(Constants.CountryCodes.Taiwan))
