					line2.AL_ExchangeRate = 1M / 28.59M;
					line2.AL_OSExTaxAmount = 7.14M;
					line2.AL_AT = TaxRate3.PK;
					line2.AL_OSTaxAmount = 0.36M;
					line2.AL_LocalExTaxAmount = 204M;
					line2.AL_LocalTaxAmount = 10M;
					line2.AL_AG = TestObjectCreator.GLHeader1.PK;

					InvoicingLineBase line3 = (InvoicingLineBase)InvoicingBase.Lines.AddNew();
					line3.AL_ExchangeRate = 1M / 28.59M;
					line3.AL_OSExTaxAmount = 45M;
					line3.AL_AT = TaxRate3.PK;
					line3.AL_OSTaxAmount = 2.25M;
					line3.AL_LocalExTaxAmount = 1287M;
					line3.AL_LocalTaxAmount = 64M;
					line3.AL_AG = TestObjectCreator.GLHeader1.PK;

					InvoicingLineBase line4 = (InvoicingLineBase)InvoicingBase.Lines.AddNew();
					line4.AL_ExchangeRate = 1M / 28.59M;
					line4.AL_OSExTaxAmount = 59.10M;
					line4.AL_AT = TaxRate3.PK;
					line4.AL_OSTaxAmount = 2.96M;
					line4.AL_LocalExTaxAmount = 1690M;
					line4.AL_LocalTaxAmount = 85M;
					line4.AL_AG = TestObjectCreator.GLHeader1.PK;

					InvoicingLineBase line5 = (InvoicingLineBase)InvoicingBase.Lines.AddNew();
					line5.AL_ExchangeRate = 1M / 28.59M;
					line5.AL_OSExTaxAmount = 82.15M;
					line5.AL_AT = TaxRate3.PK;
					line5.AL_OSTaxAmount = 4.11M;
					line5.AL_LocalExTaxAmount = 2349M;
					line5.AL_LocalTaxAmount = 118M;
					line5.AL_AG = TestObjectCreator.GLHeader1.PK;

					InvoicingLineBase line6 = (InvoicingLineBase)InvoicingBase.Lines.AddNew();
					line6.AL_ExchangeRate = 1M / 28.59M;
					line6.AL_OSExTaxAmount = 675.36M;
					line6.AL_AT = TaxRate3.PK;
					line6.AL_OSTaxAmount = 33.77M;
					line6.AL_LocalExTaxAmount = 19309M;
					line6.AL_LocalTaxAmount = 965M;
					line6.AL_AG = TestObjectCreator.GLHeader1.PK;

					InvoicingLineBase line7 = (InvoicingLineBase)InvoicingBase.Lines.AddNew();
					line7.AL_ExchangeRate = 1M / 28.59M;
					line7.AL_OSExTaxAmount = 1752.72M;
					line7.AL_AT = TaxRate3.PK;
					line7.AL_OSTaxAmount = 87.62M;
					line7.AL_LocalExTaxAmount = 50110M;
					line7.AL_LocalTaxAmount = 2505M;
					line7.AL_AG = TestObjectCreator.GLHeader1.PK;

					Factory.Save();

					AssertEquals("OS Tax Amount", 131.30M, InvoicingBase.AH_OSTaxAmount);
					AssertEquals("OS Invoice Amount", 2757.30M * reverseTransactionMultiplier, InvoicingBase.AH_OSTotalAmount);
					AssertEquals("Local Tax Amount", 3753M, InvoicingBase.AH_LocalTaxAmount);
					AssertEquals("Local Invoice Amount", 75102M * reverseTransactionMultiplier, InvoicingBase.AH_InvoiceAmount);

					InvoicingBase.GenerateReverseTransaction(true);
					AssertEquals("[Line1] Tax Amount of the Invoice = Tax Amount of the Reverse Invoice", InvoicingBase.Lines[0].AL_LocalTaxAmount, InvoicingBase.ReverseInvoice.Lines[0].AL_LocalTaxAmount);
					AssertEquals("[Line2] Tax Amount of the Invoice = Tax Amount of the Reverse Invoice", InvoicingBase.Lines[1].AL_LocalTaxAmount, InvoicingBase.ReverseInvoice.Lines[1].AL_LocalTaxAmount);
					AssertEquals("[Line1] Local Amount of the Invoice = Local Amount of the Reverse Invoice", InvoicingBase.Lines[0].AL_LineAmount, InvoicingBase.ReverseInvoice.Lines[0].AL_LineAmount);
					AssertEquals("[Line2] Local Amount of the Invoice = Local Amount of the Reverse Invoice", InvoicingBase.Lines[1].AL_LineAmount, InvoicingBase.ReverseInvoice.Lines[1].AL_LineAmount);
					AssertEquals("Local Tax Amount of the Invoice and the Reverse Invoice should be the same", InvoicingBase.AH_LocalTaxAmount, InvoicingBase.ReverseInvoice.AH_LocalTaxAmount);
					AssertEquals("Invoice Amount of the Invoice and the Reverse Invoice should be the same", -InvoicingBase.AH_InvoiceAmount, InvoicingBase.ReverseInvoice.AH_InvoiceAmount);
				}
			}
			else
			{
				Assert(true);
			}
		}

