		[TestDate(2011, 1, 11)]
		public void TestSendEmailWhenCreditLimitExceeded()
		{
			GlbStaff currentUserInCurrentFactory = Factory.Load<GlbStaff>(Env.CurrentUser.PK);
			currentUserInCurrentFactory.GS_EmailAddress = "A@B.COM";
			Factory.Save();

			GlbGroup group = Factory.New<GlbGroup>();
			group.Staff.Add(currentUserInCurrentFactory);

			AccountingConfigurationRegistry.Instance.DebtorCreditLimitNotifyGroup.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, group.PK.ToGuid());
			AccountingConfigurationRegistry.Instance.IncludeUnpostedRevenueInCreditLimitCalculation.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, Constants.CreditLimitChecking.PostedRecognizedAndUnrecognized);

			TestObjectCreator.AALSHI.CompanyData.LoadARTermForAllInvoiceTypes().PY_InvoiceTerm = "INV";
			TestObjectCreator.AALSHI.CompanyData.OB_ARCreditLimit = 500m;

			// Credit Limit is already over
			ARInvoice existingOutstandingInvoice = Factory.New<ARInvoice>();
			existingOutstandingInvoice.AH_OH = TestObjectCreator.AALSHI.PK;
			existingOutstandingInvoice.AH_InvoiceTerm = "INV";
			existingOutstandingInvoice.SubmittedFromInvoicingForm = true;

			InvoicingLineBase existingLine = (InvoicingLineBase)existingOutstandingInvoice.Lines.AddNew();
			existingLine.AL_AG = TestObjectCreator.GLHeader1.PK;
			existingLine.AL_OSExTaxAmount = 5000m;
			existingOutstandingInvoice.Lines.Add(existingLine);
			existingOutstandingInvoice.SubmittedFromInvoicingForm = true;
			Factory.Save();

			CreateUnPostedRecognisedRevenue(150m);
			CreateUnPostedUnRecognisedRevenue(50m);

			InvoicingBase invoice = (InvoicingBase)GetNewBusinessObject();
			if (invoice.IsARInvoiceOrCreditNoteOrAdjustmentNote)
			{
				invoice.AH_OH = TestObjectCreator.AALSHI.PK;
				InvoicingLineBase line = (InvoicingLineBase)invoice.Lines.AddNew();
				line.AL_OSExTaxAmount = 2000m;
				line.AL_AG = TestObjectCreator.GLHeader1.PK;
				invoice.Lines.Add(line);
				invoice.SubmittedFromInvoicingForm = true;
				Factory.Save();

				AssertEquals("Should be 2 emails sent for credit limit exceeded", 2, Env.OutgoingMailManager.EmailsCreated.Count);

				EmailDef email = Env.OutgoingMailManager.EmailsCreated[1];
				AssertNotNull("email", email);
				if (invoice.AH_TransactionType == TransactionTypes.CreditNote)
				{
					AssertContains("Credit Limit Exceeded by AUD $2,700.00", email.Subject);
					AssertContains(string.Format("<p>A.A.L. SHIPPING AGENCIES P/L / AALSHI credit limit of AUD $500.00 has been exceeded by AUD $2,700.00 with the creation of AR {0} {1}", invoice.AH_TransactionType, invoice.AH_TransactionNum), email.Body);
				}
				else
				{
					AssertContains("Credit Limit Exceeded by AUD $6,700.00", email.Subject);
					AssertContains(string.Format("AALSHI credit limit of AUD $500.00 has been exceeded by AUD $6,700.00 with the creation of AR {0} {1}", invoice.AH_TransactionType, invoice.AH_TransactionNum), email.Body);
				}
			}
			else
			{
				Assert(true);
			}
		}

		[TestDate(2011, 3, 11)]
		public void TestSendEmailWhenGlobalCreditLimitExceeded()
		{
			SetupGlobalCreditLimitGroups();
			var orgHeaderWithGlobalCreditLimit = TestObjectCreator.CreateOrgHeaderWithGlobalCreditLimitParent("GlobalOrg1", TestObjectCreator.AUD.RX_Code, 500m);

			CreateInvoiceForCreditLimitEmail(LedgerTypes.AccountsReceivable, "INV001", orgHeaderWithGlobalCreditLimit, 5000m);
			Assert("invoice amount is over the global credit limit", 5000m > orgHeaderWithGlobalCreditLimit.MiscServ.OM_ARGlobalCreditLimit);
			CreateUnPostedRecognisedRevenue(150m);
			CreateUnPostedUnRecognisedRevenue(50m);

			var invoice = (InvoicingBase)GetNewBusinessObject();
			if (invoice.IsARInvoiceOrCreditNoteOrAdjustmentNote)
			{
				invoice.AH_OH = orgHeaderWithGlobalCreditLimit.PK;
				var line = (InvoicingLineBase)invoice.Lines.AddNew();
				line.AL_OSExTaxAmount = 2000m;
				line.AL_AG = TestObjectCreator.GLHeader1.PK;
				invoice.Lines.Add(line);
				invoice.SubmittedFromInvoicingForm = true;
				Factory.Save();

				AssertEquals("Should be 2 emails sent for credit limit exceeded", 2, Env.OutgoingMailManager.EmailsCreated.Count);

				var email = Env.OutgoingMailManager.EmailsCreated[1];
				AssertNotNull("email", email);
				AssertContainsExactElementsInAnyOrder("Each email should have 2 recipients", new string[] { "globalEmailAddress@B.COM", "localEmailAddress@B.COM" }, email.Recipients.ToStringCollection());

				if (invoice.AH_TransactionType == TransactionTypes.CreditNote)
				{
					AssertEmailIsGlobalCreditLimitExceedEmailForASingleInvoice(email, orgHeaderWithGlobalCreditLimit, invoice, 500m, 2500m, TestObjectCreator.AUD);
				}
				else
				{
					AssertEmailIsGlobalCreditLimitExceedEmailForASingleInvoice(email, orgHeaderWithGlobalCreditLimit, invoice, 500m, 6500m, TestObjectCreator.AUD);
				}
			}
			else
			{
				Assert(true);
			}
		}

