		[TestDate(2011, 3, 11)]
		public void TestSendMultipleEmailsGlobalCreditLimitExceeded()
		{
			Factory.SetContext(BusinessContext.BulkTransactionSaving);
			SetupGlobalCreditLimitGroups();
			var orgHeaderWithGlobalCreditLimit1 = TestObjectCreator.CreateOrgHeaderWithGlobalCreditLimitParent("GlobalOrg1", TestObjectCreator.AUD.RX_Code, 500m);
			var orgHeaderWithGlobalCreditLimit2 = TestObjectCreator.CreateOrgHeaderWithGlobalCreditLimitParent("GlobalOrg2", TestObjectCreator.AUD.RX_Code, 500m);

			var invoice1 = CreateInvoiceForCreditLimitEmail(LedgerTypes.AccountsReceivable, "INV001", orgHeaderWithGlobalCreditLimit1, 1000m);
			var invoice2 = CreateInvoiceForCreditLimitEmail(LedgerTypes.AccountsReceivable, "INV002", orgHeaderWithGlobalCreditLimit1, 500m);
			var invoice3 = CreateInvoiceForCreditLimitEmail(LedgerTypes.AccountsReceivable, "INV003", orgHeaderWithGlobalCreditLimit2, 2000m);
			var invoice4 = CreateInvoiceForCreditLimitEmail(LedgerTypes.AccountsReceivable, "INV004", orgHeaderWithGlobalCreditLimit2, 3000m);
			Factory.Save();

			Env.OutgoingMailManager.EmailsCreated.Clear();
			var invoices = new InvoicingBase[] { invoice1, invoice2, invoice3, invoice4 };
			InvoicingBase.CheckCreditLimitExceeded(invoices);
			AssertEquals("Should be 2 emails sent for global credit limit exceeded, 1 email per Organisation/Ledger combination", 2, Env.OutgoingMailManager.EmailsCreated.Count);
			var email = Env.OutgoingMailManager.EmailsCreated[0];

			AssertEquals("Global Credit Limit Exceed Email Subject", "Global Credit Limit Exceeded by AUD $1,000.00 (Test Company Name / ZGlobalOrg1)", email.Subject);

			AssertContains("Global Credit Limit Exceed Email Body header", "Test Company Name / ZGlobalOrg1 Global credit limit of AUD $500.00 has been exceeded by AUD $1,000.00 with the creation of 2 Invoices posted on 11-Mar-11 by CargoWise Support. The invoices are:", email.Body);
			AssertContains("Global Credit Limit Exceed Email Body invoice1 details", string.Format("<li>AR INV {0} created 11-Mar-11</li>", invoice1.AH_TransactionNum), email.Body);
			AssertContains("Global Credit Limit Exceed Email Body invoice2 details", string.Format("<li>AR INV {0} created 11-Mar-11</li>", invoice2.AH_TransactionNum), email.Body);
		}

		void AssertEmailIsGlobalCreditLimitExceedEmailForASingleInvoice(EmailDef email, OrgHeader org, InvoicingBase invoice, decimal globalCreditLimit, decimal exceededAmount, RefCurrency currency)
		{
			AssertEquals("Global Credit Limit Exceed Email Subject", string.Format("Global Credit Limit Exceeded by {0} {1}{2} ({3} / {4})", currency.RX_Code, currency.RX_Symbol, Utilities.FormatNumberWithGroupSeparators(exceededAmount, currency.Decimals), org.OH_FullName, org.OH_Code), email.Subject);

			AssertContains("Global Credit Limit Exceed Email Body", string.Format("{0} / {1} Global credit limit of {2} {3}{4} has been exceeded by {2} {3}{5} with the creation of {6} {7} {8} dated 11-Mar-11 for {2} {3}{9} posted 11-Mar-11 by CargoWise Support.",
				org.OH_FullName, org.OH_Code, currency.RX_Code, currency.RX_Symbol, Utilities.FormatNumberWithGroupSeparators(globalCreditLimit, currency.Decimals), Utilities.FormatNumberWithGroupSeparators(exceededAmount,
				currency.Decimals), invoice.AH_Ledger, invoice.AH_TransactionType, invoice.AH_TransactionNum, Utilities.FormatNumberWithGroupSeparators(Math.Abs(invoice.AH_OSTotal), currency.Decimals)), email.Body);
		}

		void SetupGlobalCreditLimitGroups()
		{
			var userForLocalNotification = Factory.Load<GlbStaff>(Env.CurrentUser.PK);
			userForLocalNotification.GS_EmailAddress = "localEmailAddress@B.COM";
			var userForGlobalNotification = Factory.LoadTop1<GlbStaff>(new ZQuery(GlbStaffSchema.PK, SQLComparisonOperator.NotEqual, Env.CurrentUser.PK));
			AssertNotNull(userForGlobalNotification);
			userForGlobalNotification.GS_EmailAddress = "globalEmailAddress@B.COM";

			var localGroup = TestObjectCreator.CreateStaffGroup("LOCAL");
			localGroup.Staff.Add(userForLocalNotification);
			var globalGroup = TestObjectCreator.CreateStaffGroup("GLOBAL");
			globalGroup.Staff.Add(userForGlobalNotification);

			AccountingConfigurationRegistry.Instance.DebtorCreditLimitNotifyGroup.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, localGroup.PK.ToGuid());
			AccountingMasterFilesRegistry.Instance.DebtorGlobalCreditLimitNotifyGroup.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, globalGroup.PK.ToGuid());
			AccountingConfigurationRegistry.Instance.IncludeUnpostedRevenueInCreditLimitCalculation.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, Constants.CreditLimitChecking.PostedRecognizedAndUnrecognized);

			Factory.Save();
		}

