		InvoicingBase CreateInvoiceForCreditLimitEmail(string ledger, string transNum, OrgHeader org, decimal lineAmount = 2000m, string transactionCategory = "FIN")
		{
			InvoicingBase invoice;
			if (ledger.Equals("AP"))
			{
				invoice = TestObjectCreator.CreateAPInvoice<APInvoice>(transNum, TestObjectCreator.AUD, 1.0m, 5000m, 500m, 0m, 5000m, 500m, 0m);
			}
			else
			{
				invoice = TestObjectCreator.CreateARInvoice<ARInvoice>(transNum, TestObjectCreator.AUD, 1.0m, org);
			}
			invoice.AH_TransactionCategory = transactionCategory;
			invoice.AH_OH = org.PK;
			InvoicingLineBase line = (InvoicingLineBase)invoice.Lines.AddNew();
			line.AL_AG = TestObjectCreator.GLHeader1.PK;
			line.AL_OSExTaxAmount = lineAmount;
			invoice.Lines.Add(line);
			invoice.SubmittedFromInvoicingForm = true;
			Factory.Save();
			return invoice;
		}

		void CreateUnPostedRecognisedRevenue(decimal amount)
		{
			Job job = TestObjectCreator.CreateJob("S00001000", TestObjectCreator.AALSHI, 0m, TestObjectCreator.Agent, 0m);

			BaseCharge charge = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "Desc", TestObjectCreator.AUD, amount, TestObjectCreator.Creditor1, TestObjectCreator.AUD, amount, TestObjectCreator.AALSHI);

			WIP wip = TestObjectCreator.CreateWIP(charge);
			wip.AL_PostDate = ZDateTime.Now;
			wip.AL_OSAmount = amount;
			wip.AL_ReverseDate = ZDateTime.Empty;
			wip.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate;
		}

