		public void TestAL_SequenceIsCorrectWhenImportingOriginalTransaction()
		{
			ARInvoice invoice = Factory.New<ARInvoice>();
			invoice.AH_OH = TestObjectCreator.AALSHI.PK;
			InvoicingLineBase line1 = (InvoicingLineBase)invoice.Lines.AddNew();
			line1.AL_AC = TestObjectCreator.CC1.PK;
			line1.AL_OSExTaxAmount = 500m;
			InvoicingLineBase line2 = (InvoicingLineBase)invoice.Lines.AddNew();
			line2.AL_AC = TestObjectCreator.CC2.PK;
			line2.AL_OSExTaxAmount = 600m;
			InvoicingLineBase line3 = (InvoicingLineBase)invoice.Lines.AddNew();
			line3.AL_AC = TestObjectCreator.CC3.PK;
			line3.AL_OSExTaxAmount = 700m;

			Factory.Save();

			ARCreditNote creditNote = Factory.New<ARCreditNote>();
			creditNote.AH_OH = TestObjectCreator.AALSHI.PK;
			creditNote.OriginalTransactionReference = invoice.PK;

			AssertEquals("Should be 3 lines now", 3, creditNote.Lines.Count);
			AssertEquals(1, (int)((InvoicingLineBase)creditNote.Lines.Find(new ZQuery(AccTransactionLinesSchema.AL_AC, TestObjectCreator.CC1.PK))[0]).AL_Sequence);
			AssertEquals(2, (int)((InvoicingLineBase)creditNote.Lines.Find(new ZQuery(AccTransactionLinesSchema.AL_AC, TestObjectCreator.CC2.PK))[0]).AL_Sequence);
			AssertEquals(3, (int)((InvoicingLineBase)creditNote.Lines.Find(new ZQuery(AccTransactionLinesSchema.AL_AC, TestObjectCreator.CC3.PK))[0]).AL_Sequence);
		}

