		public virtual void TestCreditLimitExceededEmailWillBeSentOnlyOnce()
		{
			GlbStaff currentUserInCurrentFactory = Factory.Load<GlbStaff>(Env.CurrentUser.PK);
			currentUserInCurrentFactory.GS_EmailAddress = "A@B.COM";
			Factory.Save();
			GlbGroup group = Factory.New<GlbGroup>();
			group.Staff.Add(currentUserInCurrentFactory);
			AccountingConfigurationRegistry.Instance.DebtorCreditLimitNotifyGroup.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, group.PK.ToGuid());

			Header = (InvoicingBase)Factory.NewWithValidTestData(GetExpectedBusinessObjectType());
			TestObjectCreator.AALSHI.CompanyData.LoadARTermForAllInvoiceTypes().PY_InvoiceTerm = "COD";
			TestObjectCreator.AALSHI.CompanyData.OB_AROnCreditHold = ZBool.True;
			TestObjectCreator.AALSHI.CompanyData.OB_ARCreditLimit = 200m;
			InvoicingBase.AH_OH = TestObjectCreator.AALSHI.PK;
			InvoicingLineBase firstline = (InvoicingLineBase)Factory.NewWithValidTestData(GetExpectedBusinessObjectLineType());
			firstline.AL_OSExTaxAmount = 400m;
			InvoicingBase.Lines.Add(firstline);
			Factory.Save();

			var expectedNumberOfEmailsToBeSent = (Header is ARInvoice || Header is ARAdjustmentNote) ? 1 : 0;

			InvoicingBase.AH_InvoicePrinted = true;
			Factory.Save();
			AssertEquals("There should not be any additional emails sent for credit limit exceeded", expectedNumberOfEmailsToBeSent, Env.OutgoingMailManager.EmailsCreated.Count);

			BusinessObjectFactory newFactory = new BusinessObjectFactory();
			Header = (InvoicingBase)newFactory.Load(GetExpectedBusinessObjectType(), Header.PK);

			var secondLine = (InvoicingLineBase)Factory.NewWithValidTestData(GetExpectedBusinessObjectLineType());
			secondLine.AL_OSExTaxAmount = 500m;
			InvoicingBase.Lines.Add(secondLine);
			Factory.Save();
			AssertEquals("There should not be any additional emails sent for credit limit exceeded", expectedNumberOfEmailsToBeSent, Env.OutgoingMailManager.EmailsCreated.Count);
		}

