		#region ReversingExchangeRate

		[TestDate(2016, 04, 01)]
		public void TestReversingExchangeRate()
		{
			ExchangeRateReader.GetReaderInstance().ClearCache();
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, "BUY", 1.4m, ZDateTime.Today, ZDateTime.Today.AddDays(1));
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, "SEL", 1.4m, ZDateTime.Today, ZDateTime.Today.AddDays(1));

			var postingExRateRegistry = PostingExRateRegistryAR;
			postingExRateRegistry.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, "DEF");

			var invoice = Factory.NewWithValidTestData<ARInvoice>();
			invoice.AH_OH = TestObjectCreator.AALSHI.PK;
			invoice.AH_InvoiceTerm = "INV";
			invoice.AH_RX_NKTransactionCurrency = "USD";
			invoice.AH_ExchangeRate = 1.2m;
			invoice.SubmittedFromInvoicingForm = true;
			invoice.AH_InvoiceDate = new ZDateTime(2016, 03, 01);

			var line = (InvoicingLineBase)invoice.Lines.AddNew();
			line.AL_AC = TestObjectCreator.CC1.PK;
			line.AL_LineAmount = 200;
			line.AL_AG = TestObjectCreator.GLHeader1.PK;

			Factory.Save();

			postingExRateRegistry.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, "INV");
			AccountingConfigurationRegistry.Instance.AllowARInvoiceDateToDefaultToTheOriginalTransactionInvoiceDate.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, "TOD");

			var reversingFactory = new ReversingFactory();
			var reversing = reversingFactory.NewReversing(invoice);
			reversing.Reverse();

			var reversedTransaction = invoice.ReverseInvoice;
			AssertEquals("Reversed transaction's Invoice date should be today's date", ZDateTime.Today, reversedTransaction.AH_InvoiceDate);
			AssertEquals("Reversed transaction's exchange rate should default to the original transaction's exchange rate", invoice.AH_ExchangeRate, reversedTransaction.AH_ExchangeRate);
			AssertNoExceptionThrown("Reversing invoice should not throw any exception", () => Factory.Save());

			ExchangeRateReader.GetReaderInstance().ClearCache();
		}

