		#region Reverse transaction with branch level tax defaulting

		public void TestReverseTransactionWhenBranchLevelTaxDefaultingEnabled()
		{
			using (AccountingMasterFilesRegistry.Instance.EnableBranchLevelTaxOverrideRuleConfigurations.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true))
			{
				var shipment = TestObjectCreator.CreateShipment("S001001");
				var job = TestObjectCreator.CreateJob(shipment, TestObjectCreator.LocalClient, 0M, TestObjectCreator.Agent, 0M);

				var defaultTaxRate = TestObjectCreator.GST1;
				var defaultTaxMsg = TestObjectCreator.TaxMsg1;

				var overriddenTaxRate = TestObjectCreator.GSTFREE1;
				var overriddenTaxMsg = TestObjectCreator.TaxMsg2;

				var chargeCode = TestObjectCreator.CC1;

				var taxOverride1 = chargeCode.TaxOverrides.AddNew();
				taxOverride1.AO_CostSellAll = "ALL";
				taxOverride1.AO_Direction = "ALL";
				taxOverride1.AO_IncoTerm = "ALL";
				taxOverride1.AO_JobType = "ALL";
				taxOverride1.AO_Origin = "ALL";
				taxOverride1.AO_Destination = "ALL";
				taxOverride1.AO_TaxRegCntryOrGroup = "ALL";
				taxOverride1.AO_GB = GlbBranch.CurrentBranch.PK;
				taxOverride1.AO_AT = defaultTaxRate.PK;
				taxOverride1.AO_A9_DefaultVATClass = defaultTaxMsg.PK;

				Factory.Save();

				var invoice = TestObjectCreator.CreateInvoice(typeof(APInvoice), "001001", TestObjectCreator.AUD, 1M, TestObjectCreator.AALSHI);

				var line = (InvoicingLineBase)invoice.Lines.AddNew();
				line.AL_AC = chargeCode.PK;
				line.AL_RX_NKTransactionCurrency = TestObjectCreator.AUD.RX_Code;
				line.AL_ExchangeRate = 1M;
				line.AL_OSExTaxAmount = 200M;
				line.AL_JH = job.PK;
				line.AL_AG = TestObjectCreator.GLHeader1.PK;

				var jobCharge = TestObjectCreator.CreateCharge(line, job, chargeCode, TestObjectCreator.AUD);
				jobCharge.JR_AT_CostGSTRate = overriddenTaxRate.PK;
				jobCharge.JR_A9_CostVATClass = overriddenTaxMsg.PK;

				AssertEquals("PreCondition: tax rate defaulted from tax defaulting", defaultTaxRate.PK, line.AL_AT);
				AssertEquals("PreCondition: tax msg defaulted from tax defaulting", defaultTaxMsg.PK, line.AL_A9_VATClass);

				line.AL_AT = overriddenTaxRate.PK;
				line.AL_A9_VATClass = overriddenTaxMsg.PK;

				Factory.Save();

				var reversingFactory = new ReversingFactory();
				var reversing = reversingFactory.NewReversing(invoice);
				reversing.Reverse();

				var reversedTransaction = invoice.ReverseInvoice;

				AssertEquals(1, reversedTransaction.Lines.Count);
				InvoicingLineBase reversedLine = (InvoicingLineBase)reversedTransaction.Lines.First();
				AssertEquals("Tax rate is set from original transaction", overriddenTaxRate.PK, reversedLine.AL_AT);
				AssertEquals("Tax msg is set from original transaction", overriddenTaxMsg.PK, reversedLine.AL_A9_VATClass);
			}
		}

