		void DoSingleTestForMultipleInstalments(bool assignComplNum, bool isForeign = false, bool isNegative = false, bool isBackPosted = false)
		{
			var currCompany = GlbCompany.CurrentCompany;
			using (AccountingConfigurationRegistry.Instance.AllowBackPostingSubLedgerTransaction.SetTemporaryValue(currCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, isBackPosted))
			{
				#region Setup Debtor for Multiple Instalments

				var arTerms = TestObjectCreator.AALSHI.CompanyData.ARTerms;
				AssertNotNull(arTerms);

				var arTermMLI = arTerms.AddNew();
				arTermMLI.PY_JobType = "ALL";
				arTermMLI.PY_GB_Branch = InvoicingBase.AH_GB;
				arTermMLI.PY_GE_Department = InvoicingBase.AH_GE;
				arTermMLI.PY_Direction = "ALL";
				arTermMLI.PY_TransportMode = "ALL";
				arTermMLI.PY_InvoiceClass = isForeign ? InvoiceTypesList.Codes.ForeignCurrencyInvoice : InvoiceTypesList.Codes.FinalInvoice;
				arTermMLI.PY_InvoiceTerm = InvoiceTerms.FromInvoiceDate;
				var arTermMLInstalments = arTermMLI.ARTermsInstallments;
				AssertNotNull(arTermMLInstalments);

				var installment1 = arTermMLInstalments.AddNew();
				installment1.ML_SequenceNumber = 1;
				installment1.ML_SplitPercentage = 33.33;
				installment1.ML_DaysFromInvoiceDate = 30;
				installment1.ML_AgreedPaymentMethod = OrgConstants.CreditAgreedPaymentMethods.Code.CollectionRequest;

				var installment2 = arTermMLInstalments.AddNew();
				installment2.ML_SequenceNumber = 2;
				installment2.ML_SplitPercentage = 33.33;
				installment2.ML_DaysFromInvoiceDate = 60;
				installment2.ML_AgreedPaymentMethod = OrgConstants.CreditAgreedPaymentMethods.Code.CollectionRequest;

				var installment3 = arTermMLInstalments.AddNew();
				installment3.ML_SequenceNumber = 3;
				installment3.ML_SplitPercentage = 33.34;
				installment3.ML_DaysFromInvoiceDate = 90;
				installment3.ML_AgreedPaymentMethod = OrgConstants.CreditAgreedPaymentMethods.Code.BankTransfer;

				var arTermMLIwrong = arTerms.AddNew();
				arTermMLIwrong.PY_JobType = "ALL";
				arTermMLIwrong.PY_GB_Branch = InvoicingBase.AH_GB;
				arTermMLIwrong.PY_GE_Department = InvoicingBase.AH_GE;
				arTermMLIwrong.PY_Direction = "ALL";
				arTermMLIwrong.PY_TransportMode = "ALL";
				arTermMLIwrong.PY_InvoiceClass = InvoiceTypesList.Codes.SelfBillingInvoice;
				arTermMLIwrong.PY_InvoiceTerm = InvoiceTerms.FromInvoiceDate;
				var arTermMLInstals = arTermMLIwrong.ARTermsInstallments;
				AssertNotNull(arTermMLInstals);

				var instal1 = arTermMLInstals.AddNew();
				instal1.ML_SequenceNumber = 1;
				instal1.ML_SplitPercentage = 30;
				instal1.ML_DaysFromInvoiceDate = 30;
				instal1.ML_AgreedPaymentMethod = OrgConstants.CreditAgreedPaymentMethods.Code.CollectionRequest;

				var instal2 = arTermMLInstals.AddNew();
				instal2.ML_SequenceNumber = 2;
				instal2.ML_SplitPercentage = 70;
				instal2.ML_DaysFromInvoiceDate = 60;
				instal2.ML_AgreedPaymentMethod = OrgConstants.CreditAgreedPaymentMethods.Code.BankTransfer;

				#endregion

				InvoicingBase.AH_OH = TestObjectCreator.AALSHI.PK;
				InvoicingBase.AH_TransactionNum = "00001000";
				const string subType = "TXI";
				InvoicingBase.AH_ComplianceSubType = assignComplNum ? subType : string.Empty;
				InvoicingBase.AH_TransactionReference = assignComplNum ? $"{subType}001" : string.Empty;
				var currency = isForeign ? TestObjectCreator.EUR : TestObjectCreator.AUD;
				InvoicingBase.AH_RX_NKTransactionCurrency = currency.RX_Code;
				InvoicingBase.AH_ExchangeRate = isForeign ? 0.7 : 1;
				InvoicingBase.AH_InvoiceTerm = InvoiceTerms.FromInvoiceDate;
				InvoicingBase.AH_AgreedPaymentMethodOverride = OrgConstants.CreditAgreedPaymentMethods.Code.CollectionRequest;

				var today = ZDateTime.Today;
				InvoicingBase.AH_InvoiceDate = new ZDateTime(today.Year + (isBackPosted ? 1 : 0), today.Month, 1);
				InvoicingBase.AH_PostDate = today.AddDays(isBackPosted ? -1 : 0);
				InvoicingBase.AH_DueDate = InvoicingBase.AH_InvoiceDate.AddMonths(1);

				InvoicingBase.Lines.DeleteAll();
				var line = InvoicingBase.Lines.AddNew();
				line.AL_GB = GlbBranch.CurrentBranch.PK;
				line.AL_GE = GlbDepartment.CurrentDepartment.PK;
				line.AL_AG = TestObjectCreator.GLHeader1.PK;
				int realSign = isNegative ? -1 : 1;
				line.AL_OSExTaxAmount = realSign * 111.10;
				line.AL_OSTaxAmount = realSign * 11.11;

				Factory.Save();

				var savedInvoicingBase = Factory.Load<InvoicingBase>(InvoicingBase.PK);
				var invoiceDate = InvoicingBase.AH_InvoiceDate;
				var postDate = InvoicingBase.AH_PostDate;
				AssertEquals(0m, savedInvoicingBase.AH_OutstandingAmount);
				AssertEquals(isBackPosted ? invoiceDate : postDate, savedInvoicingBase.AH_DueDate);
				AssertEquals(postDate, savedInvoicingBase.AH_FullyPaidDate);
				AssertEquals(InvoiceTerms.MultipleInstallments, savedInvoicingBase.AH_InvoiceTerm);

				var expectedComplianceNumDesc = InvoicingBase.AH_TransactionReference.IsEmpty ? string.Empty : $" / {InvoicingBase.AH_TransactionReference}";
				AssertEquals(assignComplNum, !expectedComplianceNumDesc.IsNullOrEmpty());

				var arJournalAccount = AccountingConfigurationRegistry.Instance.ARJournalAccount.GetValueWithoutFallback(Guid.Empty, Guid.Empty, Guid.Empty);

				var journals = InvoicingBase.GetMultipleInstallmentsJournals(TransactionCategory.Codes.ClearingJournal);
				Assert(!journals.IsNullOrEmpty());
				Assert(journals.Length == 1);
				var clearJournal = journals[0];

				AssertEquals(InvoicingBase.AH_GC, clearJournal.AH_GC);
				AssertEquals(InvoicingBase.AH_GB, clearJournal.AH_GB);
				AssertEquals(InvoicingBase.AH_GE, clearJournal.AH_GE);
				AssertEquals(InvoicingBase.AH_OH, clearJournal.AH_OH);
				AssertEquals(arJournalAccount, clearJournal.AH_AG);
				AssertEquals(InvoicingBase.InvertSigns_ForTestOnly || isNegative ? "CR" : "DR", clearJournal.DebitCreditSign);
				AssertEquals(InvoicingBase.AH_AgreedPaymentMethodOverride, clearJournal.AH_AgreedPaymentMethodOverride);
				AssertEquals(InvoicingBase.AH_DueDate, clearJournal.AH_DueDate);
				AssertEquals(invoiceDate, clearJournal.AH_InvoiceDate);
				AssertEquals(postDate, clearJournal.AH_PostDate);
				AssertEquals(realSign * savedInvoicingBase.AH_OSTotalAmount, clearJournal.AH_OSExTaxAmount);
				AssertEquals(-savedInvoicingBase.AH_OSTotal, clearJournal.AH_OSTotal);
				AssertEquals(InvoicingBase.AH_RX_NKTransactionCurrency, clearJournal.AH_RX_NKTransactionCurrency);
				//AssertEquals(InvoicingBase.AH_ExchangeRate, clearJournal.AH_ExchangeRate); NO: ExchangeRate may adapt to keep consistency of LocalAmount with original Invoice
				AssertEquals(realSign * savedInvoicingBase.AH_LocalTotalAmount, clearJournal.AH_LocalExTaxAmount);
				AssertEquals(-savedInvoicingBase.AH_LocalTotal, clearJournal.AH_LocalTotal);
				AssertEquals($"Multi-installment clearing Journal for {InvoicingBase.AH_Ledger} {InvoicingBase.AH_TransactionType} {InvoicingBase.AH_TransactionNum}{expectedComplianceNumDesc} - {InvoicingBase.AH_Desc}", clearJournal.AH_Desc);
				AssertEquals(InvoicingBase.AH_TransactionNum, clearJournal.AH_ChequeOrReference);
				AssertEquals(0m, clearJournal.AH_OutstandingAmount);
				AssertEquals(postDate, clearJournal.AH_FullyPaidDate);

				journals = InvoicingBase.GetMultipleInstallmentsJournals(TransactionCategory.Codes.InstalmentJournal);
				Assert(!journals.IsNullOrEmpty());
				Assert(journals.Length == 3);

				var roundingScale = InvoicingBase.TransactionCurrency?.Decimals ?? currCompany.LocalCurrency.Decimals;
				int i = 0;
				ZDecimal subtotAmount = 0, subtotLocalAmount = 0;
				foreach (var instalment in journals.OrderBy(x => x.AH_DueDate))
				{
					var termInst = arTermMLInstalments[i++];
					AssertEquals(termInst.ML_SequenceNumber, i);
					var splitPerc = termInst.ML_SplitPercentage / 100;

					AssertEquals(InvoicingBase.AH_GC, instalment.AH_GC);
					AssertEquals(InvoicingBase.AH_GB, instalment.AH_GB);
					AssertEquals(InvoicingBase.AH_GE, instalment.AH_GE);
					AssertEquals(InvoicingBase.AH_OH, instalment.AH_OH);
					AssertEquals(arJournalAccount, instalment.AH_AG);
					AssertEquals(InvoicingBase.InvertSigns_ForTestOnly || isNegative ? "DR" : "CR", instalment.DebitCreditSign);
					AssertEquals(invoiceDate.AddDays(termInst.ML_DaysFromInvoiceDate), instalment.AH_DueDate);
					AssertEquals(termInst.ML_AgreedPaymentMethod, instalment.AH_AgreedPaymentMethodOverride);
					AssertEquals(invoiceDate, instalment.AH_InvoiceDate);
					AssertEquals(postDate, instalment.AH_PostDate);
					AssertEquals(InvoicingBase.AH_RX_NKTransactionCurrency, instalment.AH_RX_NKTransactionCurrency);
					//AssertEquals(InvoicingBase.AH_ExchangeRate, instalment.AH_ExchangeRate); NO: ExchangeRate may adapt to keep consistency of LocalAmount with original Invoice
					if (i < journals.Length)
					{
						var totalRounded = Utilities.Round(savedInvoicingBase.AH_OSTotal * splitPerc, roundingScale);
						AssertEquals(realSign * savedInvoicingBase.Multiplier_ForTestOnly * totalRounded, instalment.AH_OSExTaxAmount);
						AssertEquals(totalRounded, instalment.AH_OSTotal);
						subtotAmount += totalRounded;
						var localRounded = Utilities.Round(savedInvoicingBase.AH_LocalTotal * splitPerc, roundingScale);
						AssertEquals(realSign * savedInvoicingBase.Multiplier_ForTestOnly * localRounded, instalment.AH_LocalExTaxAmount);
						AssertEquals(localRounded, instalment.AH_LocalTotal);
						subtotLocalAmount += localRounded;
					}
					else
					{
						var totalRemaining = savedInvoicingBase.AH_OSTotal - subtotAmount;
						AssertEquals(realSign * savedInvoicingBase.Multiplier_ForTestOnly * totalRemaining, instalment.AH_OSExTaxAmount);
						AssertEquals(totalRemaining, instalment.AH_OSTotal);
						var localRemaining = savedInvoicingBase.AH_LocalTotal - subtotLocalAmount;
						AssertEquals(realSign * savedInvoicingBase.Multiplier_ForTestOnly * localRemaining, instalment.AH_LocalExTaxAmount);
						AssertEquals(localRemaining, instalment.AH_LocalTotal);
					}
					AssertEquals($"Instalment #{termInst.ML_SequenceNumber} for {InvoicingBase.AH_Ledger} {InvoicingBase.AH_TransactionType} {InvoicingBase.AH_TransactionNum}{expectedComplianceNumDesc} - {InvoicingBase.AH_Desc}", instalment.AH_Desc);
				}
			}
		}

