		[SuspendGLAccountAndChargeCodeCriticalValidation]
		[TestDate(2009, 01, 15)]
		public void TestMatchWithJournalOnFactorySave()
		{
			InvoicingBase invoice = (InvoicingBase)GetNewBusinessObject();

			if (invoice.IsReceivableOrPayable_ForTestOnly)
			{
				var otherFactory = new BusinessObjectFactory();
