		#region Implementation

		Journal.Journal CreateJournal(BusinessObjectFactory otherFactory, ZString ledger, ZGuid orgHeaderPK, ZString currency, ZDecimal exRate, ZDecimal oSTotal, int multiplier, ZString transactionCategory, ZString chequeOrReference)
		{
			Journal.Journal journal;
			if (ledger == LedgerTypes.AccountsPayable)
			{
				journal = otherFactory.NewWithValidTestData<APJournal>();
			}
			else
			{
				journal = otherFactory.NewWithValidTestData<ARJournal>();
			}

			journal.AH_TransactionCategory = transactionCategory;
			journal.AH_OH = orgHeaderPK;
			journal.AH_RX_NKTransactionCurrency = currency;
			journal.AH_ExchangeRate = exRate;
			journal.AH_OSExTaxAmount = oSTotal * multiplier;
			journal.AH_LocalExTaxAmount = journal.AH_OSExTaxAmount / exRate;
			journal.AH_ChequeOrReference = chequeOrReference;
			journal.AH_OutstandingAmount = journal.AH_InvoiceAmount;

			return journal;
		}

		void PopulateInvoice(InvoicingBase invoice, ZGuid orgHeaderPK, ZString currency, ZDecimal exRate, ZDecimal oSTotal, ZString tranNum)
		{
			invoice.AH_OH = orgHeaderPK;
			invoice.AH_RX_NKTransactionCurrency = currency;
			invoice.AH_ExchangeRate = exRate;
			invoice.AH_TransactionNum = tranNum;
			TransactionLine line = invoice.Lines.AddNew();
			line.AL_OSExTaxAmount = oSTotal;
			invoice.AH_OutstandingAmount = invoice.AH_InvoiceAmount;
		}

		void AssertMatchingGroup(InvoicingBase invoice, Journal.Journal journal, ZDecimal journalOutstandingAmt, ZDecimal invoiceOutstandingAmt, ZDateTime journalFullyPaidDate, ZDateTime invoiceFullyPaidDate)
		{
			AssertEquals(journalOutstandingAmt, journal.AH_OutstandingAmount);
			AssertEquals(invoiceOutstandingAmt, invoice.AH_OutstandingAmount);
			AssertEquals(journalFullyPaidDate, journal.AH_FullyPaidDate);
			AssertEquals(invoiceFullyPaidDate, invoice.AH_FullyPaidDate);
			((IMatching)journal).Matchlinks.Load();
			AssertEquals(1, ((IMatching)journal).Matchlinks.Count);
			AssertEquals(ZDateTime.Now, ((IMatching)journal).Matchlinks[0].AP_MatchDate);
			((IMatching)invoice).Matchlinks.Load();
			AssertEquals(1, ((IMatching)invoice).Matchlinks.Count);
			AssertEquals(ZDateTime.Now, ((IMatching)invoice).Matchlinks[0].AP_MatchDate);
		}

		#endregion

		#endregion

