		public void TestJobHeaderReloaderWhenTransactionIsInMatchingContext()
		{
			if ((InvoicingBase.IsCreatingAPInvoiceOrCRD_ForTestOnly || InvoicingBase.IsCreatingUAInvoiceOrCRD_ForTestOnly)
										 && (!InvoicingBase.IsInDatabase || InvoicingBase.IsConvertedUAInvoiceOrCRD || InvoicingBase.IsAllocatingInvoice || InvoicingBase.IsCompletingInvoice)
										 && !(InvoicingBase.IsCreatedByENett && InvoicingBase.IsUAInvoiceOrCreditNote))
			{
				BusinessObjectFactory jobFactory = new BusinessObjectFactory();
				jobFactory.RefreshEnabled = false;
				BusinessObject shipment = jobFactory.NewWithValidTestData(ObjectFactory.GetType(typeof(Enterprise.Integration.Freight.ICommonShipment)));
				Job job = new Job.Loader((IJobHeaderParent)shipment).TryCreateWithoutMutexForTestOnly();
				job.JH_GB = GlbBranch.CurrentBranch.PK;
				job.JH_GE = GlbDepartment.CurrentDepartment.PK;
				jobFactory.Save();
				job.JH_Status = JobHeaderStatus.Working.Code;
				jobFactory.Save();
				AssertEquals("Job Status should be Working", JobHeaderStatus.Working.Code, job.JH_Status);

				InvoicingBase.Factory.RefreshEnabled = false;
				InvoicingBase.AH_JH = job.PK;
				foreach (TransactionLine line in InvoicingBase.Lines)
				{
					line.AL_JH = job.PK;
					line.AL_AC = TestObjectCreator.CC1.PK;
				}

				AssertNotNull("There is a job on the Header", InvoicingBase.Job);
				AssertEquals("Job Status should be Working", JobHeaderStatus.Working.Code, InvoicingBase.Job.JH_Status);

				job.JH_Status = JobHeaderStatus.Complete.Code;
				jobFactory.Save();

				IMatchingCollection matchingCollection = new IMatchingCollection(Factory);
				matchingCollection.Add(InvoicingBase);

				AssertEquals("Precondition: IsInMatchingContext", true, InvoicingBase.IsInMatchingContext);

				InvoicingBase.SubmittedFromInvoicingForm = true;
				InvoicingBase.Factory.Save();

				AssertEquals("Job Status should still be Working (proving that the job has NOT been reloaded", JobHeaderStatus.Working.Code, InvoicingBase.Job.JH_Status);
			}
			else
			{
				Assert("Not applicable to such transaction type", true);
			}
		}

		public void TestJobHeaderReloaderPreventsConcurrencyErrors()
		{
			if ((InvoicingBase.IsCreatingAPInvoiceOrCRD_ForTestOnly || InvoicingBase.IsCreatingUAInvoiceOrCRD_ForTestOnly)
										 && (!InvoicingBase.IsInDatabase || InvoicingBase.IsConvertedUAInvoiceOrCRD || InvoicingBase.IsAllocatingInvoice || InvoicingBase.IsCompletingInvoice)
										 && !(InvoicingBase.IsCreatedByENett && InvoicingBase.IsUAInvoiceOrCreditNote))
			{
				BusinessObjectFactory jobFactory = new BusinessObjectFactory();
				jobFactory.RefreshEnabled = false;
				BusinessObject shipment = jobFactory.NewWithValidTestData(ObjectFactory.GetType(typeof(Enterprise.Integration.Freight.ICommonShipment)));
				Job job = new Job.Loader((IJobHeaderParent)shipment).TryCreateWithoutMutexForTestOnly();
				job.JH_GB = GlbBranch.CurrentBranch.PK;
				job.JH_GE = GlbDepartment.CurrentDepartment.PK;
				jobFactory.Save();
				job.JH_Status = JobHeaderStatus.Closed.Code;
				jobFactory.Save();
				AssertEquals("Job Status should be Closed", JobHeaderStatus.Closed.Code, job.JH_Status);

				InvoicingBase.Factory.RefreshEnabled = false;

				InvoicingBase.AH_JH = job.PK;
				foreach (TransactionLine line in InvoicingBase.Lines)
				{
					line.AL_JH = job.PK;
					line.AL_AC = TestObjectCreator.CC1.PK;
				}
				AssertNotNull("There is a job on the Header", InvoicingBase.Job);
				AssertEquals("Job Status should be Closed", JobHeaderStatus.Closed.Code, InvoicingBase.Job.JH_Status);

				job.JH_Status = JobHeaderStatus.Working.Code;
				jobFactory.Save();

				AssertEquals("Job Status should still be Closed", JobHeaderStatus.Closed.Code, InvoicingBase.Job.JH_Status);

				try
				{
					InvoicingBase.SubmittedFromInvoicingForm = true;
					AssertEquals("Has No Closed Jobs because property getter reloads Jobs", false, InvoicingBase.HasClosedJob);
					InvoicingBase.Factory.Save();
				}
				catch (Exception e)
				{
					Fail(string.Format("Expect No Exceptions but was {0} with Message : {1}", e.GetType(), e.Message));
				}

				int hitsAfter = HeaderWithLines.Factory.GetTableHitCount(JobHeaderSchema.Constants.TableName);

				AssertEquals("Expected 3 hits", 3, hitsAfter);
				AssertEquals("Job Status should be Closed", JobHeaderStatus.Working.Code, HeaderWithLines.Job.JH_Status);
			}
			else
			{
				Assert("Not applicable to such transaction type", true);
			}
		}

