		void AssertBatchLoad(int jobsToReload, int expectedDbHits)
		{
			// Remove existing Jobs
			ZQuery cacheOnlyFilter = new ZQuery();
			cacheOnlyFilter.FetchOnlyFromLocalCache = true;
			JobHeader[] jobsInFactory = Factory.Load<JobHeader>(cacheOnlyFilter);
			foreach (JobHeader job in jobsInFactory)
			{
				job.Delete();
			}

			List<Job> jobs = new List<Job>();
			for (int i = 0; i < jobsToReload; i++)
			{
				jobs.Add(Factory.NewJobWithValidTestDataForTesting<Job>());
			}
			Factory.Save();

			int hitsBefore = Factory.GetTableHitCount(JobHeaderSchema.Constants.TableName);
			var reloader = new InvoicingBase.JobHeaderReloader(Factory);

			int hitsAfter = Factory.GetTableHitCount(JobHeaderSchema.Constants.TableName);
			AssertEquals(string.Format("Expected {0} hit(s) with batch size 5 for testing", expectedDbHits), expectedDbHits, hitsAfter - hitsBefore);
		}

		public void TestLineTotalPaidAmountPostedCalculator()
		{
			TransactionMatchLinkGroup matchlinks = new TransactionMatchLinkGroup(Factory);
			AccTransactionMatchLink link1 = Factory.NewWithValidTestData<AccTransactionMatchLink>();
			AccTransactionMatchLink link2 = Factory.NewWithValidTestData<AccTransactionMatchLink>();
			link1.AP_MatchGroupNum = link2.AP_MatchGroupNum = "001";
			matchlinks.Add(link1);
			matchlinks.Add(link2);

			List<APInvoice> inv = new List<APInvoice>();

			for (int i = 0; i < 4; i++)
			{
				APInvoice invoice = Factory.NewWithValidTestData<APInvoice>();
				link1.AP_AH = link2.AP_AH = invoice.PK;

				APInvoiceLine line1 = (APInvoiceLine)invoice.Lines.AddNew();
				line1.AL_AG = TestObjectCreator.GLHeader1.PK;
				AccTransLinePay accline1 = line1.TransLinePays.AddNew();
				accline1.A7_Amount = 700 + i;
				accline1.A7_AP = link1.PK;

				APInvoiceLine line2 = (APInvoiceLine)invoice.Lines.AddNew();
				line2.AL_AG = TestObjectCreator.GLHeader1.PK;
				AccTransLinePay accline2 = line2.TransLinePays.AddNew();
				accline2.A7_Amount = 300 + i;
				accline2.A7_AP = link2.PK;

				inv.Add(invoice);
			}

			Factory.Save();

			List<ZGuid> pks = new List<ZGuid>();
			for (int i = 0; i < 3; i++)
			{
				pks.Add(inv[i].PK);
			}

			int hitsBefore = Db.Connection.ExecutedCommandCount;
			var calc = new InvoicingBase.LineTotalPaidAmountPostedCalculator();
			calc.AddNewElements(pks);
			int hitsAfter = Db.Connection.ExecutedCommandCount;
			AssertEquals("Db Hit Count", 1, hitsAfter - hitsBefore);

			hitsBefore = Db.Connection.ExecutedCommandCount;
			AssertEquals("Should have 1000 Total", 1000M, calc.GetValueFromElement(inv[0].PK));
			AssertEquals("Should have 1002 Total", 1002M, calc.GetValueFromElement(inv[1].PK));
			AssertEquals("Should have 1004 Total", 1004M, calc.GetValueFromElement(inv[2].PK));
			hitsAfter = Db.Connection.ExecutedCommandCount;
			AssertEquals("Should be 0 DB Hit", 0, hitsAfter - hitsBefore);

			hitsBefore = Db.Connection.ExecutedCommandCount;
			AssertEquals("Should have 1006 Total", 1006M, calc.GetValueFromElement(inv[3].PK));
			hitsAfter = Db.Connection.ExecutedCommandCount;
			AssertEquals("Should be 1 DB Hit", 1, hitsAfter - hitsBefore);
		}

