			Assert("AH_TransactionReference shouldn't be set yet", invoice.AH_TransactionReference.IsEmpty);
			Assert("AH_ConsolidatedInvoiceRef shouldn't be set yet", invoice.AH_ConsolidatedInvoiceRef.IsEmpty);

			invoice = new BusinessObjectFactory().Load<APInvoice>(invoice.PK);
