			incompleteInvoice.MoveFromIncompleteToPayableLedger();
			newFactory.Save();
			AssertNull("Job is empty", incompleteInvoice.Job);
			AssertEquals("invoice.AH_JH should not be set", ZGuid.Empty, incompleteInvoice.AH_JH);
			AssertEquals("invoice.JobNumber should not be set", ZString.Empty, incompleteInvoice.JobNumber);
		}

