		public void TestIsAwaitingApprovalFromGovt()
		{
			var invoice = (InvoicingBase)GetNewBusinessObject();
			Assert(!invoice.IsAwaitingApprovalFromGovt);

			var arInvoice = Factory.NewWithValidTestData<ARInvoice>();
			var aRCreditNote = Factory.NewWithValidTestData<ARCreditNote>();
			var aRAdjustmentNote = Factory.NewWithValidTestData<ARAdjustmentNote>();

			Assert(!arInvoice.IsAwaitingApprovalFromGovt);
			Assert(!aRCreditNote.IsAwaitingApprovalFromGovt);
			Assert(!aRAdjustmentNote.IsAwaitingApprovalFromGovt);

			var batch = TestObjectCreator.CreateEInvoicingBatch(100, Core.Constants.EInvoicingBatchState.Ready, GlbCompany.CurrentCompany);
			var pivot1 = TestObjectCreator.CreateEInvoicingTransactionPivot(batch, arInvoice, Core.Constants.EInvoicingPivotState.Succeed);
			var pivot2 = TestObjectCreator.CreateEInvoicingTransactionPivot(batch, aRCreditNote, Core.Constants.EInvoicingPivotState.Succeed);
			var pivot3 = TestObjectCreator.CreateEInvoicingTransactionPivot(batch, aRAdjustmentNote, Core.Constants.EInvoicingPivotState.Succeed);

			Assert(!arInvoice.IsAwaitingApprovalFromGovt);
			Assert(!aRCreditNote.IsAwaitingApprovalFromGovt);
			Assert(!aRAdjustmentNote.IsAwaitingApprovalFromGovt);

			pivot1.AIP_Status = Core.Constants.EInvoicingPivotState.Failed;
			pivot2.AIP_Status = Core.Constants.EInvoicingPivotState.Queued;
			pivot3.AIP_Status = Core.Constants.EInvoicingPivotState.BatchedWithError;

			Assert(arInvoice.IsAwaitingApprovalFromGovt);
			Assert(aRCreditNote.IsAwaitingApprovalFromGovt);
			Assert(aRAdjustmentNote.IsAwaitingApprovalFromGovt);

			pivot3.AIP_Status = Core.Constants.EInvoicingPivotState.Discarded;
			Assert(aRAdjustmentNote.IsAwaitingApprovalFromGovt);
		}

