		public void TestIsApprovedByGovt()
		{
			var invoice = (InvoicingBase)GetNewBusinessObject();
			Assert(!invoice.IsApprovedByGovt);

			var arInvoice = Factory.NewWithValidTestData<ARInvoice>();
			var aRCreditNote = Factory.NewWithValidTestData<ARCreditNote>();
			var aRAdjustmentNote = Factory.NewWithValidTestData<ARAdjustmentNote>();

			Assert(!arInvoice.IsApprovedByGovt);
			Assert(!aRCreditNote.IsApprovedByGovt);
			Assert(!aRAdjustmentNote.IsApprovedByGovt);

			var batch = TestObjectCreator.CreateEInvoicingBatch(100, Core.Constants.EInvoicingBatchState.Ready, GlbCompany.CurrentCompany);
			var pivot1 = TestObjectCreator.CreateEInvoicingTransactionPivot(batch, arInvoice, Core.Constants.EInvoicingPivotState.Discarded);
			var pivot2 = TestObjectCreator.CreateEInvoicingTransactionPivot(batch, aRCreditNote, Core.Constants.EInvoicingPivotState.Queued);
			var pivot3 = TestObjectCreator.CreateEInvoicingTransactionPivot(batch, aRAdjustmentNote, Core.Constants.EInvoicingPivotState.Failed);

			Assert(!arInvoice.IsApprovedByGovt);
			Assert(!aRCreditNote.IsApprovedByGovt);
			Assert(!aRAdjustmentNote.IsApprovedByGovt);

			pivot1.AIP_Status = Core.Constants.EInvoicingPivotState.Succeed;
			pivot2.AIP_Status = Core.Constants.EInvoicingPivotState.Succeed;
			pivot3.AIP_Status = Core.Constants.EInvoicingPivotState.Succeed;

