		public void TestAH_GB_BranchLevelPostingEnabled_Reversed()
		{
			InvoicingBase invoice = TestObjectCreator.CreateInvoice(GetExpectedBusinessObjectType(), "INV1", organisation: TestObjectCreator.Creditor1);
			invoice.AH_GB = GlbBranch.CurrentBranch.PK;

			if (invoice.EnforceBranchLevelPostingRegistryItem != null)
			{
				var branchLevelPostingConfiguration = new BranchLevelPostingConfiguration() { EnableBranchLevelPosting = false };
				invoice.EnforceBranchLevelPostingRegistryItem.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, branchLevelPostingConfiguration);

				var line = (InvoicingLineBase)invoice.Lines.AddNew();
				line.AL_AG = TestObjectCreator.GLHeader1.PK;
				line.AL_GB = TestObjectCreator.NonCurrentBranch.PK;

				Factory.Save();

				AssertNotEquals("Header and Line branch is not the same, since Branch level posting is not enabled yet", invoice.AH_GB, line.AL_GB);

				branchLevelPostingConfiguration = new BranchLevelPostingConfiguration() { EnableBranchLevelPosting = true };
				invoice.EnforceBranchLevelPostingRegistryItem.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, branchLevelPostingConfiguration);

				invoice.GenerateReverseTransaction(true);

				var reversedInvoice = invoice.ReverseInvoice;

				AssertNotEquals("Header and Line branch is not the same, though branch level posting is enabled now. This is because reversed transaction should follow the original invoice"
					, reversedInvoice.AH_GB, reversedInvoice.Lines[0].AL_GB);
			}
			else
			{
				Assert("This test is not applicable to this transaction", true);
			}
		}

