			TestObjectCreator.CreateJob(shipment2, createWithMutex: false);
			Factory.Save();

			Assert("Precondition: applicable to AP Invoice or Credit Note only", GetExpectedBusinessObjectType() == typeof(APInvoice) || GetExpectedBusinessObjectType() == typeof(APCreditNote));

			InvoicingBase invoice = TestObjectCreator.CreateInvoice(GetExpectedBusinessObjectType(), "INV1", organisation: TestObjectCreator.Creditor1);

			var cost1 = TestObjectCreator.CreateConsolCost(invoice, consol, TestObjectCreator.CC1, 20);
			var cost2 = TestObjectCreator.CreateConsolCost(invoice, consol, TestObjectCreator.CC1, 100);

			var nonApportionedLine = TestObjectCreator.CreateInvoiceLine(invoice, job, TestObjectCreator.CC1, 5);
			nonApportionedLine.IndexOfImportedUniversalTransactionLine = 11;

			Action<ZDecimal, ZDecimal> asserApportionmendLines = (cost1lineAmount, cost2lineAmount) =>
			{
				AssertEquals("Postcondition: line count", 5, invoice.Lines.Count);

				var apportionedLine = invoice.Lines[1];
				Assert("Postcondition: Should be an apportioned charge", apportionedLine.IsPopulatedFromImportedApportionment);
				AssertEquals("Postcondition: line amount", cost1lineAmount, apportionedLine.AL_LocalExTaxAmount);

				apportionedLine = invoice.Lines[2];
				Assert("Postcondition: Should be an apportioned charge", apportionedLine.IsPopulatedFromImportedApportionment);
				AssertEquals("Postcondition: line amount", cost1lineAmount, apportionedLine.AL_LocalExTaxAmount);

				apportionedLine = invoice.Lines[3];
				Assert("Postcondition: Should be an apportioned charge", apportionedLine.IsPopulatedFromImportedApportionment);
				AssertEquals("Postcondition: line amount", cost2lineAmount, apportionedLine.AL_LocalExTaxAmount);

				apportionedLine = invoice.Lines[4];
				Assert("Postcondition: Should be an apportioned charge", apportionedLine.IsPopulatedFromImportedApportionment);
				AssertEquals("Postcondition: line amount", cost2lineAmount, apportionedLine.AL_LocalExTaxAmount);
			};

			Action assertIndexOfImportedUniversalTransactionLine = () =>
			{
				AssertEquals("line 1 IndexOfImportedUniversalTransactionLine", 11, invoice.Lines[0].IndexOfImportedUniversalTransactionLine);
				AssertEquals("line 2 IndexOfImportedUniversalTransactionLine", 22, invoice.Lines[1].IndexOfImportedUniversalTransactionLine);
				AssertEquals("line 3 IndexOfImportedUniversalTransactionLine", 33, invoice.Lines[2].IndexOfImportedUniversalTransactionLine);
				AssertEquals("line 4 IndexOfImportedUniversalTransactionLine", 44, invoice.Lines[3].IndexOfImportedUniversalTransactionLine);
				AssertEquals("line 5 IndexOfImportedUniversalTransactionLine", 55, invoice.Lines[4].IndexOfImportedUniversalTransactionLine);
			};

			invoice.ImportAllApportionmentsFromCosting();
			asserApportionmendLines(10, 50);
			var line = invoice.Lines[1];
			line.IndexOfImportedUniversalTransactionLine = 22;
			line = invoice.Lines[2];
			line.IndexOfImportedUniversalTransactionLine = 33;
			line = invoice.Lines[3];
			line.IndexOfImportedUniversalTransactionLine = 44;
			line = invoice.Lines[4];
			line.IndexOfImportedUniversalTransactionLine = 55;
			assertIndexOfImportedUniversalTransactionLine();

			cost1.E6_OSCostAmount = 30;
			cost2.E6_OSCostAmount = 120;
			invoice.ImportAllApportionmentsFromCosting();
			asserApportionmendLines(15, 60);
			assertIndexOfImportedUniversalTransactionLine();
		}

		public void TestChangingCreditor_DoesNotTriggerCriticalValidation_WhenWithDifferentTaxMsgSetup_ForConsolAndShipment()
		{
			ForwardingConsol consol = TestObjectCreator.CreateConsol("AUSYD", "NZAKL", "C001001");
			Factory.Save();
			consol.Shipments.AddNew();

			var chargeCode = TestObjectCreator.CC1;
			var taxRate = TestObjectCreator.GSTFREE1;
			var consolTaxMsgPK = TestObjectCreator.TaxMsg1.PK;

			TestObjectCreator.CreateTaxOverride(chargeCode, taxRate.PK, ZGuid.Empty, "ALL", "ALL", "ALL", "SHP", "ALL", "ALL");
			TestObjectCreator.CreateTaxOverride(chargeCode, taxRate.PK, consolTaxMsgPK, "ALL", "ALL", "ALL", "FCN", "ALL", "ALL");

			Factory.Save();

			InvoicingBase invoice = (InvoicingBase)Factory.New(GetExpectedBusinessObjectType());
			invoice.AH_TransactionNum = "0000001";
			invoice.AH_OH = TestObjectCreator.Creditor1.PK;
			invoice.SubmittedFromInvoicingForm = true;

			if (!(invoice.AH_Ledger == LedgerTypes.AccountsPayable && invoice.IsInvoiceOrCreditNote_ForTestOnly
				|| invoice.AH_Ledger == LedgerTypes.UnapprovedPayableTransactions))
			{
				Assert(true);
			}
			else
			{
				try
				{
					JobConsolCost cost = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
					cost.E6_AC_ChargeCode = chargeCode.PK;
					cost.E6_OSCostAmount = 20m;
					cost.E6_AT_TaxRate = taxRate.PK;
					cost.E6_ApportionmentMethod = "SHP";
					cost.SetIsUsedForApportionment();

					AssertEquals("Precondition", consolTaxMsgPK, cost.E6_A9_VATClass);

					invoice.ImportSingleCost(cost, null);

					AssertEquals("1 line should be added to the invoice", 1, invoice.Lines.Count);

					AssertEquals("Precondition", consolTaxMsgPK, invoice.Lines[0].AL_A9_VATClass);

					invoice.AH_OH = TestObjectCreator.Creditor2.PK;

					CombineAssertions(() =>
					{
						AssertEquals("Tax msg should remain the same", consolTaxMsgPK, invoice.Lines[0].AL_A9_VATClass);
						AssertNoExceptionThrown("Should not get criticial validation error: Cost, Revenue or Unapproved Cost transaction tax class that does not equal related job charge tax class.", () => Factory.Save());
					});
				}
				finally
				{
					invoice.ClearApportionmentJobMutexes();
				}
			}
		}

