		public void TestChangingCreditor_ReCreatesLinesLinkedToConsolCosts()
		{
			var sydneyUnloco = "AUSYD";
			var aucklandUnloco = "NZAKL";

			ForwardingConsol importConsol = TestObjectCreator.CreateConsol(aucklandUnloco, sydneyUnloco, "C001001");
			ForwardingConsol exportConsol = TestObjectCreator.CreateConsol(sydneyUnloco, aucklandUnloco, "C001002");

			var importShipment = importConsol.Shipments.AddNew();
			importShipment.JS_RL_NKOrigin = aucklandUnloco;
			importShipment.JS_RL_NKDestination = sydneyUnloco;

			var importJob = TestObjectCreator.CreateJob(importShipment);

			var exportShipment = exportConsol.Shipments.AddNew();
			exportShipment.JS_RL_NKOrigin = sydneyUnloco;
			exportShipment.JS_RL_NKDestination = aucklandUnloco;

			var exportJob = TestObjectCreator.CreateJob(exportShipment);

			var chargeCode = TestObjectCreator.CC3;
			var originalCreditor = TestObjectCreator.Creditor1;

			var importConsolExportShipmentTaxRatePK = TestObjectCreator.GSTFREE1.PK;
			var exportConsolImportShipmentTaxRatePK = TestObjectCreator.FREECAPGST.PK;

			var importConsolExportShipmentTaxClassPK = TestObjectCreator.TaxMsg1.PK;
			var exportConsolImportShipmentTaxClassPK = TestObjectCreator.TaxMsg2.PK;

			TestObjectCreator.CreateTaxOverride(chargeCode, importConsolExportShipmentTaxRatePK, importConsolExportShipmentTaxClassPK, "IMP", "ALL", "ALL", "FCN", "ALL", "ALL");
			TestObjectCreator.CreateTaxOverride(chargeCode, exportConsolImportShipmentTaxRatePK, exportConsolImportShipmentTaxClassPK, "EXP", "ALL", "ALL", "FCN", "ALL", "ALL");

			TestObjectCreator.CreateTaxOverride(chargeCode, exportConsolImportShipmentTaxRatePK, exportConsolImportShipmentTaxClassPK, "IMP", "ALL", "ALL", "SHP", "ALL", "ALL");
			TestObjectCreator.CreateTaxOverride(chargeCode, importConsolExportShipmentTaxRatePK, importConsolExportShipmentTaxClassPK, "EXP", "ALL", "ALL", "SHP", "ALL", "ALL");

			Factory.Save();

			InvoicingBase invoice = (InvoicingBase)Factory.New(GetExpectedBusinessObjectType());
			invoice.AH_OH = originalCreditor.PK;
			invoice.SubmittedFromInvoicingForm = true;
			invoice.AH_TransactionNum = "0000001";

			invoice.Lines.RemoveAndDeleteAll();

			if (!(invoice.AH_Ledger == LedgerTypes.AccountsPayable && invoice.IsInvoiceOrCreditNote_ForTestOnly
				|| invoice.AH_Ledger == LedgerTypes.UnapprovedPayableTransactions))
			{
				Assert(true);
			}
			else
			{
				try
				{
					var importConsolCost = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(importConsol);
					importConsolCost.E6_AC_ChargeCode = chargeCode.PK;
					importConsolCost.E6_OSCostAmount = 10m;
					importConsolCost.E6_ApportionmentMethod = "SHP";
					importConsolCost.SetIsUsedForApportionment();

					AssertEquals("Precondition: tax rate defaulted correctly for import consol cost", importConsolExportShipmentTaxRatePK, importConsolCost.E6_AT_TaxRate);
					AssertEquals("Precondition: tax class defaulted correctly for import consol cost", importConsolExportShipmentTaxClassPK, importConsolCost.E6_A9_VATClass);

					var exportConsolCost = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(exportConsol);
					exportConsolCost.E6_AC_ChargeCode = chargeCode.PK;
					exportConsolCost.E6_OSCostAmount = 20m;
					exportConsolCost.E6_ApportionmentMethod = "SHP";
					exportConsolCost.SetIsUsedForApportionment();

					AssertEquals("Precondition: tax rate defaulted correctly for export consol cost", exportConsolImportShipmentTaxRatePK, exportConsolCost.E6_AT_TaxRate);
					AssertEquals("Precondition: tax class defaulted correctly for export consol cost", exportConsolImportShipmentTaxClassPK, exportConsolCost.E6_A9_VATClass);

					var importJobCharge = TestObjectCreator.CreateCharge(importJob, chargeCode, "charge1", TestObjectCreator.AUD, 30M, originalCreditor, null, 0M, null);

					AssertEquals("Precondition: tax rate defaulted correctly for import shipment charge", exportConsolImportShipmentTaxRatePK, importJobCharge.JR_AT_CostGSTRate);
					AssertEquals("Precondition: tax class defaulted correctly for import shipment charge", exportConsolImportShipmentTaxClassPK, importJobCharge.JR_A9_CostVATClass);

					var exportJobCharge = TestObjectCreator.CreateCharge(exportJob, chargeCode, "charge2", TestObjectCreator.AUD, 40M, originalCreditor, null, 0M, null);

					AssertEquals("Precondition: tax rate defaulted correctly for export shipment charge", importConsolExportShipmentTaxRatePK, exportJobCharge.JR_AT_CostGSTRate);
					AssertEquals("Precondition: tax class defaulted correctly for export shipment charge", importConsolExportShipmentTaxClassPK, exportJobCharge.JR_A9_CostVATClass);

					//import cost from import consol
					invoice.ImportSingleCost(importConsolCost, null);
					AssertEquals("1 line should be added to the invoice", 1, invoice.Lines.Count);
					var lineFromImportConsol = invoice.Lines[0];
					AssertEquals("Precondition: tax rate defaulted correctly to line linked to import consol cost", importConsolExportShipmentTaxRatePK, lineFromImportConsol.AL_AT);
					AssertEquals("Precondition: tax class defaulted correctly to line linked to import consol cost", importConsolExportShipmentTaxClassPK, lineFromImportConsol.AL_A9_VATClass);

					//import cost from export consol
					invoice.ImportSingleCost(exportConsolCost, null);
					AssertEquals("1 more line should be added to the invoice", 2, invoice.Lines.Count);
					var lineFromExportConsol = invoice.Lines[1];
					AssertEquals("Precondition: tax rate defaulted correctly to line linked to export consol cost", exportConsolImportShipmentTaxRatePK, lineFromExportConsol.AL_AT);
					AssertEquals("Precondition: tax class defaulted correctly to line linked to export consol cost", exportConsolImportShipmentTaxClassPK, lineFromExportConsol.AL_A9_VATClass);

					//import charge from import shipment
					var jobCharges = new List<Charge>();
					jobCharges.Add(importJobCharge);
					var lineFromImportShipment = (InvoicingLineBase)invoice.Lines.AddNew();
					invoice.ImportJobChargesIntoInvoice(jobCharges, lineFromImportShipment);
					lineFromImportShipment.AL_JH = importJob.PK;
					AssertEquals("Precondition: tax rate defaulted correctly to line linked to import shipment", exportConsolImportShipmentTaxRatePK, lineFromImportShipment.AL_AT);
					AssertEquals("Precondition: tax class defaulted correctly to line linked to import shipment", exportConsolImportShipmentTaxClassPK, lineFromImportShipment.AL_A9_VATClass);

					//import charge from export shipment
					jobCharges = new List<Charge>();
					jobCharges.Add(exportJobCharge);
					var lineFromExportShipment = (InvoicingLineBase)invoice.Lines.AddNew();
					invoice.ImportJobChargesIntoInvoice(jobCharges, lineFromExportShipment);
					lineFromExportShipment.AL_JH = exportJob.PK;
					AssertEquals("Precondition: tax rate defaulted correctly to line linked to export shipment", importConsolExportShipmentTaxRatePK, lineFromExportShipment.AL_AT);
					AssertEquals("Precondition: tax class defaulted correctly to line linked to export shipment", importConsolExportShipmentTaxClassPK, lineFromExportShipment.AL_A9_VATClass);

					//change creditor
					invoice.AH_OH = TestObjectCreator.Creditor2.PK;

					CombineAssertions(() =>
					{
						AssertNull("Previous apportionedCharge linked line is no longer linked to invoice", invoice.Lines.FirstOrDefault(x => x.PK == lineFromImportConsol.PK));
						AssertNull("Previous apportionedCharge linked line is no longer linked to invoice", invoice.Lines.FirstOrDefault(x => x.PK == lineFromExportConsol.PK));
						AssertNotNull("Charges linked to shipment is still linked", invoice.Lines.FirstOrDefault(x => x.PK == lineFromImportShipment.PK));
						AssertNotNull("Charges linked to shipment is still linked", invoice.Lines.FirstOrDefault(x => x.PK == lineFromExportShipment.PK));
					});

					AssertNoExceptionThrown(() => Factory.Save());

					var newFactory = NewFactory();
					var invoiceInNewFactory = newFactory.Load<InvoicingBase>(invoice.PK);

					CombineAssertions(() =>
					{
						var lineLinkedToImportApportionmentCharge = invoiceInNewFactory.Lines.Cast<InvoicingLineBase>().First(x => x.ApportionmentChargeImportedFrom != null && x.ApportionmentChargeImportedFrom.JR_E6 == importConsolCost.PK);
						AssertNotEquals("Line linked to consol cost is recreated", lineLinkedToImportApportionmentCharge.PK, lineFromImportConsol.PK);

						InvoicingLineBase lineFromImportConsol2 = (InvoicingLineBase)invoiceInNewFactory.Lines.First(x => x.PK == lineLinkedToImportApportionmentCharge.PK);
						AssertEquals("Tax rate remains same", importConsolExportShipmentTaxRatePK, lineFromImportConsol2.AL_AT);
						AssertEquals("Tax class remains same", importConsolExportShipmentTaxClassPK, lineFromImportConsol2.AL_A9_VATClass);

						var lineLinkedToExportApportionmentCharge = invoiceInNewFactory.Lines.Cast<InvoicingLineBase>().First(x => x.ApportionmentChargeImportedFrom != null && x.ApportionmentChargeImportedFrom.JR_E6 == exportConsolCost.PK);
						AssertNotEquals("Line linked to consol cost is recreated", lineLinkedToExportApportionmentCharge.PK, lineFromExportConsol.PK);

						InvoicingLineBase lineFromExportConsol2 = (InvoicingLineBase)invoiceInNewFactory.Lines.First(x => x.PK == lineLinkedToExportApportionmentCharge.PK);
						AssertEquals("Tax rate remains same", exportConsolImportShipmentTaxRatePK, lineFromExportConsol2.AL_AT);
						AssertEquals("Tax class remains same", exportConsolImportShipmentTaxClassPK, lineFromExportConsol2.AL_A9_VATClass);

						InvoicingLineBase lineFromImportShipment2 = (InvoicingLineBase)invoiceInNewFactory.Lines.First(x => x.PK == lineFromImportShipment.PK);
						AssertEquals("Tax rate remains same", exportConsolImportShipmentTaxRatePK, lineFromImportShipment2.AL_AT);
						AssertEquals("Tax class remains same", exportConsolImportShipmentTaxClassPK, lineFromImportShipment2.AL_A9_VATClass);

						InvoicingLineBase lineFromExportShipment2 = (InvoicingLineBase)invoiceInNewFactory.Lines.First(x => x.PK == lineFromExportShipment.PK);
						AssertEquals("Tax rate remains same", importConsolExportShipmentTaxRatePK, lineFromExportShipment2.AL_AT);
						AssertEquals("Tax class remains same", importConsolExportShipmentTaxClassPK, lineFromExportShipment2.AL_A9_VATClass);
					});
				}
				finally
				{
					invoice.ClearApportionmentJobMutexes();
				}
			}
		}

		public void TestRaiseApportionedLineModified()
		{
			var creator = new TestObjectCreator(Factory);
			var consol = Factory.NewWithValidTestData<ForwardingConsol>();
			consol.JK_RL_NKLoadPort = "AUMEL";
			consol.JK_RL_NKDischargePort = "SGSIN";

			Factory.Save();
			consol.Shipments.AddNew();
			consol.Shipments.AddNew();

			var invoice = (InvoicingBase)Factory.New(GetExpectedBusinessObjectType());
			var testLineCollection = invoice.Lines;
			testLineCollection.ApportionedInvoiceLineModified += new ApportionedInvoiceLineModifiedEventHandler(InvoicingBaseTest_ApportionedInvoiceLineModified);

			try
			{
				var cost = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
				cost.E6_AC_ChargeCode = creator.CC1.PK;
				cost.E6_OSCostAmount = 20m;
				cost.E6_ApportionmentMethod = "SHP";
				cost.SetIsUsedForApportionment();

				var nonApportionedLine = (InvoicingLineBase)invoice.Lines.AddNew();
				invoice.ImportSingleCost(cost, (InvoicingLineBase)testLineCollection.AddNew());
				var apportionedLine1 = testLineCollection[1];
				Assert("Should be an apportioned charge", apportionedLine1.IsPopulatedFromImportedApportionment);
				var apportionedLine2 = testLineCollection[2];
				Assert("Should be an apportioned charge", apportionedLine2.IsPopulatedFromImportedApportionment);

				AssertEquals("Current Exchange Rate is AUD", "AUD", invoice.ExchangeRate.Currency);
				AssertEquals("Shouldn't try to modify apportioned line when importing charges", false, LineModified);

				invoice.AH_PostedToEFT = true;
				AssertEquals(true, invoice.AH_PostedToEFT);
				invoice.ExchangeRate.Currency = Constants.CurrencyCodes.UnitedStates;
				AssertEquals("Current Exchange Rate is USD", "USD", invoice.ExchangeRate.Currency);
				AssertEquals("Shouldn't try to modify apportioned line when importing charges", false, LineModified);
			}
			finally
			{
				invoice.ClearApportionmentJobMutexes();
			}
		}

		public void TestRaiseApportionedLineModifiedWhenPosting()
		{
			TestObjectCreator creator = new TestObjectCreator(Factory);
			ForwardingConsol consol = creator.CreateConsol("AUBNE", "USLAX", "C0001");// (ForwardingConsol)Factory.NewWithValidTestData(typeof(ForwardingConsol));
