			APInvoice invoice = creator.CreateAPInvoice<APInvoice>("00001", TestObjectCreator.AUD, 1m, 94m, 0m, 0m, 94m, 0m, 0m);
			InvoicingLineBaseCollection testLineCollection = invoice.Lines;
