		public void TestExchangeRateReadOnlyDependsOnAH_PostedToEFT()
		{
			InvoicingBase invoice = (InvoicingBase)Factory.New(GetExpectedBusinessObjectType());
			invoice.AH_RX_NKTransactionCurrency = TestObjectCreator.USD.RX_Code;

			foreach (bool value in new[] { true, false })
			{
				invoice.AH_PostedToEFT = value;
				if (invoice.AH_Ledger == LedgerTypes.TransactionsPendingAllocation)
				{
					Assert(string.Format("Dependency is broken when AH_PostedToEFT = {0}", value), !invoice.ExchangeRate.RateInfo.ReadOnly);
				}
				else
				{
					Assert(string.Format("Dependency is broken when AH_PostedToEFT = {0}", value), invoice.ExchangeRate.RateInfo.ReadOnly == value);
				}
			}
		}

