		public void TestAH_OHReadOnlyOnAmendingTransaction()
		{
			var original = Factory.New(GetExpectedBusinessObjectType()) as IAmending;
			if (original != null && ((InvoicingBase)original).HasImplementedGenerateAmendingTransaction)
			{
				AssertEquals("IsAmendingTransaction", false, original.IsAmendingTransaction);
				AssertEquals("AH_OH ReadOnly", false, ((InvoicingBase)original).AH_OHInfo.ReadOnly);

				var amending = original.GenerateAmendingTransaction(GetExpectedBusinessObjectType());
				var invoice = amending;

				AssertEquals("IsAmendingTransaction", true, amending.IsAmendingTransaction);
				AssertEquals("AH_OH ReadOnly", true, invoice.AH_OHInfo.ReadOnly);
			}
			else
			{
				Assert("Not applicable for this class because it does not implement IAmending", true);
			}
		}

		public void TestChangingAH_ExchangeRateReapportionCharges()
		{
			ForwardingConsol consol = Factory.NewWithValidTestData(typeof(ForwardingConsol)) as ForwardingConsol;

			ForwardingShipment shipment1 = consol.Shipments.AddNew();
			shipment1.JS_ActualWeight = 351.73m;
			shipment1.JS_ActualChargeable = 40m;

			ForwardingShipment shipment2 = consol.Shipments.AddNew();
