			AssertEquals("No Exchange Rate for this currency", 0m, InvoicingBase.AH_ExchangeRate);

			AssertEquals("Zero Local Amount", 0m, InvoicingBase.AH_LocalExTaxAmount);
			AssertEquals("Invoice.Lines.Count", 2, InvoicingBase.Lines.Count);
			AssertEquals("Invoice.Lines[0].AL_LocalExTaxAmount", 0M, InvoicingBase.Lines[0].AL_LocalExTaxAmount);
			AssertEquals("Invoice.Lines[1].AL_LocalExTaxAmount", 0M, InvoicingBase.Lines[1].AL_LocalExTaxAmount);

			AssertEquals("OS Amount", 56.8m, InvoicingBase.AH_OSExTaxAmount);
			AssertEquals("Invoice.Lines[0].AL_OSExTaxAmount", 28.4M, InvoicingBase.Lines[0].AL_OSExTaxAmount);
			AssertEquals("Invoice.Lines[1].AL_OSExTaxAmount", 28.4M, InvoicingBase.Lines[1].AL_OSExTaxAmount);

			AssertEquals("Consol OS Cost Amount", 56.8m, consolCost.E6_OSCostAmount);
			AssertEquals("ConsolCost.ApportionmentCharges.Count", 2, consolCost.ApportionmentCharges.Count);
			AssertEquals("ConsolCost.ApportionmentCharges[0].JR_OSCostAmt", 28.4M, consolCost.ApportionmentCharges[0].JR_OSCostAmt);
			AssertEquals("ConsolCost.ApportionmentCharges[1].JR_OSCostAmt", 28.4M, consolCost.ApportionmentCharges[1].JR_OSCostAmt);
			AssertEquals("ConsolCost.ApportionmentCharges[0].JR_LocalCostAmt", 0M, consolCost.ApportionmentCharges[0].JR_LocalCostAmt);
			AssertEquals("ConsolCost.ApportionmentCharges[1].JR_LocalCostAmt", 0M, consolCost.ApportionmentCharges[1].JR_LocalCostAmt);

			consolCost.ApportionmentCharges[0].JR_LocalCostAmt = 28.4M;
			consolCost.ApportionmentCharges[1].JR_LocalCostAmt = -28.4M;

			InvoicingBase.AH_RX_NKTransactionCurrency = "USD";
			AssertEquals("No Exchange Rate for this currency", 0m, InvoicingBase.AH_ExchangeRate);
			AssertEquals("Zero Local Amount", 0m, InvoicingBase.AH_LocalExTaxAmount);
			AssertEquals("OS Amount should not be cleared to 0", 56.8m, InvoicingBase.AH_OSExTaxAmount);
			AssertEquals("Consol OS Cost Amount should not be cleared to 0", 56.8m, consolCost.E6_OSCostAmount);
			AssertEquals("ConsolCost.ApportionmentCharges.Count", 2, consolCost.ApportionmentCharges.Count);
			AssertEquals("ConsolCost.ApportionmentCharges[0].JR_OSCostAmt", 28.4M, consolCost.ApportionmentCharges[0].JR_OSCostAmt);
			AssertEquals("ConsolCost.ApportionmentCharges[1].JR_OSCostAmt", 28.4M, consolCost.ApportionmentCharges[1].JR_OSCostAmt);
			AssertEquals("ConsolCost.ApportionmentCharges[0].JR_LocalCostAmt", 0M, consolCost.ApportionmentCharges[0].JR_LocalCostAmt);
			AssertEquals("ConsolCost.ApportionmentCharges[1].JR_LocalCostAmt", 0M, consolCost.ApportionmentCharges[1].JR_LocalCostAmt);

			InvoicingBase.ReleaseAllMutexOnInvoice();
		}

