		public void TestApportionedLineValidationNotSuspended()
		{
			if (!(InvoicingBase is APInvoice || InvoicingBase is APCreditNote))
			{
				Assert("The test is not suitable for other invoices.", true);
				return;
			}

			RevenueRecognitionCollection valuesForTest = new RevenueRecognitionCollection();
			RevenueRecognition setting = valuesForTest.AddNew();
			setting.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			setting.DirectionCode = Constants.FreightShipmentDirection.Code.All;
			setting.Mode = Core.Constants.TransportModes.All;
			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.CustomsClearanceDate;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);

			ForwardingConsol consol = new BusinessObjectFactory().NewWithValidTestData(typeof(ForwardingConsol)) as ForwardingConsol;

			ForwardingShipment shipment1 = consol.Shipments.AddNew();
			shipment1.JS_ActualWeight = 351.73m;
			shipment1.JS_ActualChargeable = 40m;

			consol.Factory.Save();

			InvoicingBase.AH_OH = TestObjectCreator.AALSHI.PK;
			InvoicingBase.AH_RX_NKTransactionCurrency = "AUD";
			var transactionType = InvoicingBase.AH_Ledger == LedgerTypes.AccountsPayable ? TransactionTypes.Invoice : TransactionTypes.UAInvoice;
			InvoicingBase.AH_TransactionType = transactionType;

			JobConsolCost consolCost = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC1, InvoicingBase.Header);
			consolCost.E6_RX_NKCurrency = TestObjectCreator.AUD.RX_Code;
			consolCost.E6_OSCostAmount = 10M;

			InvoicingBase.Lines.RemoveAndDeleteAll();
			InvoicingBase.ImportSingleCost(consolCost, null);
			InvoicingBase.ConsolCosting.ConsolCosts.Add(consolCost);

			AssertEquals("Precondition: InvoicingBase.Lines.Count", 1, InvoicingBase.Lines.Count);

			InvoicingBase.RunPreSaveValidation();
			AssertHasErrors("Invoice line must has at least revenue recognition date error.", InvoicingBase.Lines[0].AL_JHInfo);

			consol.GetApportionments().ReleaseMutexes();
		}

