		public void TestAH_PostDateWritableForIncompleteTransactionsReopened()
		{
			InvoicingBase invoice = (InvoicingBase)new BusinessObjectFactory().NewWithValidTestData(GetExpectedBusinessObjectType());

			if (invoice.IsAPInvoiceOrCreditNoteOrAdjustmentNote)
			{
				invoice.SaveAsIncomplete();

				BusinessObjectFactory newFactory = new BusinessObjectFactory();
				APInvoice loadedInvoice = newFactory.Load<APInvoice>(invoice.PK);
				loadedInvoice.RestoreSavedData();
				loadedInvoice.MoveFromIncompleteToPayableLedger();

				AssertEquals(LedgerTypes.IncompleteTransactions, invoice.AH_Ledger);
				AssertEquals(LedgerTypes.AccountsPayable, loadedInvoice.AH_Ledger);
				AssertEquals(false, invoice.IsCompletingInvoice);
				AssertEquals(true, loadedInvoice.IsCompletingInvoice);
				AssertEquals(false, invoice.AH_PostDateInfo.ReadOnly);
				AssertEquals(false, invoice.IsAH_PostDate_ReadOnly);
				AssertEquals(false, loadedInvoice.AH_PostDateInfo.ReadOnly);
				AssertEquals(false, loadedInvoice.IsAH_PostDate_ReadOnly);
			}
			else
			{
				Assert(true);
			}
		}

