		protected virtual bool ShouldCallUpdatePostDateOnParentReversing => true;

		public void TestUpdateAH_PostDateDuringReversal()
		{
			var taxProcessorMock = new Mock<ITaxProcessor>();
			ObjectFactory.Substitute(taxProcessorMock.Object);

			InvoicingBase invoice = (InvoicingBase)new BusinessObjectFactory().NewWithValidTestData(GetExpectedBusinessObjectType());
			var postDate = invoice.AH_PostDate.Date;
			Assert("Is not reverse transaction", !invoice.IsReverseTransaction);
			var newPostDate = ZDate.Today.AddDays(-2);

			invoice.AH_PostDate = newPostDate;
			taxProcessorMock.Verify(x => x.UpdatePostDateOnParentReversing(It.IsAny<ITaxRecordParent>(), It.IsAny<ITaxRecordParent>(), It.IsAny<ZDate>()), Times.Never);

			invoice.GenerateReverseTransaction(true);

			InvoicingBase reverseInvoice;

			if (invoice.IsReverseTransaction)
			{
				reverseInvoice = invoice;
			}
			else
			{
				reverseInvoice = invoice.ReverseInvoice;
			}

			reverseInvoice.AH_PostDate = ZDate.Empty;
			if (ShouldCallUpdatePostDateOnParentReversing)
			{
				taxProcessorMock.Verify(x => x.UpdatePostDateOnParentReversing(TaxFrameworkObjectFactory.GetInvoicingBaseTaxRecordParent(invoice), TaxFrameworkObjectFactory.GetInvoicingBaseTaxRecordParent(reverseInvoice), ZDate.Empty), Times.Once);
			}
			else
			{
				taxProcessorMock.Verify(x => x.UpdatePostDateOnParentReversing(TaxFrameworkObjectFactory.GetInvoicingBaseTaxRecordParent(invoice), TaxFrameworkObjectFactory.GetInvoicingBaseTaxRecordParent(reverseInvoice), ZDate.Empty), Times.Never);
			}

			newPostDate = ZDate.Today.AddDays(-5);
			reverseInvoice.AH_PostDate = newPostDate;
			if (ShouldCallUpdatePostDateOnParentReversing)
			{
				taxProcessorMock.Verify(x => x.UpdatePostDateOnParentReversing(TaxFrameworkObjectFactory.GetInvoicingBaseTaxRecordParent(invoice), TaxFrameworkObjectFactory.GetInvoicingBaseTaxRecordParent(reverseInvoice), newPostDate), Times.Once);
			}
			else
			{
				taxProcessorMock.Verify(x => x.UpdatePostDateOnParentReversing(TaxFrameworkObjectFactory.GetInvoicingBaseTaxRecordParent(invoice), TaxFrameworkObjectFactory.GetInvoicingBaseTaxRecordParent(reverseInvoice), newPostDate), Times.Never);
			}

			taxProcessorMock.Invocations.Clear();
			reverseInvoice.AH_PostDate = newPostDate;
			taxProcessorMock.Verify(x => x.UpdatePostDateOnParentReversing(TaxFrameworkObjectFactory.GetInvoicingBaseTaxRecordParent(invoice), TaxFrameworkObjectFactory.GetInvoicingBaseTaxRecordParent(reverseInvoice), newPostDate), Times.Never);
		}

		public void TestGetRelatedAmendingARTransactions()
		{
			var originalInvoice = (InvoicingBase)Factory.New(GetExpectedBusinessObjectType());

			if (originalInvoice.AH_Ledger == LedgerTypes.AccountsReceivable)
			{
				var relatedARInvoice = Factory.NewWithValidTestData<ARInvoice>();
				relatedARInvoice.AH_TransactionBelongsToGroup = originalInvoice.PK;
				var relatedARCreditNote = Factory.NewWithValidTestData<ARCreditNote>();
				relatedARCreditNote.AH_TransactionBelongsToGroup = originalInvoice.PK;
				var relatedARAdjustmentNote = Factory.NewWithValidTestData<ARAdjustmentNote>();
				relatedARAdjustmentNote.AH_TransactionBelongsToGroup = originalInvoice.PK;

				var cancelledARInvoice = Factory.NewWithValidTestData<ARInvoice>();
				cancelledARInvoice.AH_TransactionBelongsToGroup = originalInvoice.PK;
				cancelledARInvoice.AH_IsCancelled = true;
				var cancelledARCreditNote = Factory.NewWithValidTestData<ARCreditNote>();
				cancelledARCreditNote.AH_TransactionBelongsToGroup = originalInvoice.PK;
				cancelledARCreditNote.AH_IsCancelled = true;
				var cancelledARAdjustmentNote = Factory.NewWithValidTestData<ARAdjustmentNote>();
				cancelledARAdjustmentNote.AH_TransactionBelongsToGroup = originalInvoice.PK;
				cancelledARAdjustmentNote.AH_IsCancelled = true;

				var unrelatedAPInvoice = Factory.NewWithValidTestData<APInvoice>();
				var unrelatedAPCreditNote = Factory.NewWithValidTestData<APCreditNote>();
				var unrelatedAPAdjustmentNote = Factory.NewWithValidTestData<APAdjustmentNote>();

				var amendingTransactions = originalInvoice.GetRelatedAmendingTransactions();
				AssertNotNull(amendingTransactions);
				AssertEquals(2, amendingTransactions.Count);
				AssertCollectionContains(relatedARInvoice, amendingTransactions);
				AssertCollectionContains(relatedARCreditNote, amendingTransactions);
			}
			else if (originalInvoice.AH_Ledger == LedgerTypes.AccountsPayable)
			{
				var relatedAPInvoice = Factory.NewWithValidTestData<APInvoice>();
				relatedAPInvoice.AH_TransactionBelongsToGroup = originalInvoice.PK;
				var relatedAPCreditNote = Factory.NewWithValidTestData<APCreditNote>();
				relatedAPCreditNote.AH_TransactionBelongsToGroup = originalInvoice.PK;
				var relatedAPAdjustmentNote = Factory.NewWithValidTestData<APAdjustmentNote>();
				relatedAPAdjustmentNote.AH_TransactionBelongsToGroup = originalInvoice.PK;

				var cancelledAPInvoice = Factory.NewWithValidTestData<APInvoice>();
				cancelledAPInvoice.AH_TransactionBelongsToGroup = originalInvoice.PK;
				cancelledAPInvoice.AH_IsCancelled = true;
				var cancelledAPCreditNote = Factory.NewWithValidTestData<APCreditNote>();
				cancelledAPCreditNote.AH_TransactionBelongsToGroup = originalInvoice.PK;
				cancelledAPCreditNote.AH_IsCancelled = true;
				var cancelledAPAdjustmentNote = Factory.NewWithValidTestData<APAdjustmentNote>();
				cancelledAPAdjustmentNote.AH_TransactionBelongsToGroup = originalInvoice.PK;
				cancelledAPAdjustmentNote.AH_IsCancelled = true;

				var unrelatedARInvoice = Factory.NewWithValidTestData<ARInvoice>();
				var unrelatedARCreditNote = Factory.NewWithValidTestData<ARCreditNote>();
				var unrelatedARAdjustmentNote = Factory.NewWithValidTestData<ARAdjustmentNote>();

				var amendingTransactions = originalInvoice.GetRelatedAmendingTransactions();
				AssertNotNull(amendingTransactions);
