		public void TestReceivingJobPropertiesForSisterCompanyInvoices()
		{
			var invoice = (InvoicingBase)GetNewBusinessObject();
			invoice.AH_OH = TestObjectCreator.ABIGAS.PK;

			if (invoice.Ledger_ForTestOnly == LedgerTypes.AccountsReceivable && (invoice.TransactionType_ForTestOnly == TransactionTypes.Invoice || invoice.TransactionType_ForTestOnly == TransactionTypes.CreditNote))
			{
				var shipment = TestObjectCreator.CreateShipment("S001001");

				var receivingCompanyJob = CreateJobInNewFactory(TestObjectCreator.NonCurrentCompanyBranch
					, TestObjectCreator.NonCurrentDepartment
					, "S001001"
					, "RV");

				var sendingCompanyJob = CreateJobInNewFactory(GlbBranch.CurrentBranch
					, GlbDepartment.CurrentDepartment
					, "S001001"
					, "SN");

				invoice.AH_JH = sendingCompanyJob.PK;

				Factory.Save();

				AssertEquals("PreCondition", receivingCompanyJob.JH_GB, TestObjectCreator.NonCurrentCompanyBranch.PK);
				using (Env.SetTemporaryUserContext(GlbStaff.CurrentUser.PK.ToGuid(), TestObjectCreator.NonCurrentCompanyBranch.PK.ToGuid(), GlbDepartment.CurrentDepartment.PK.ToGuid()))
				{
					AssertEquals("RV", invoice.ReceivingOperator);
					AssertEquals(receivingCompanyJob.JH_GB, invoice.ReceivingBranch);
					AssertEquals(TestObjectCreator.NonCurrentDepartment.PK, invoice.ReceivingDepartment);
				}
			}
			else
			{
				AssertEquals(string.Empty, invoice.ReceivingOperator);
				AssertEquals(ZGuid.Empty, invoice.ReceivingBranch);
				AssertEquals(ZGuid.Empty, invoice.ReceivingDepartment);
			}

			Job CreateJobInNewFactory(GlbBranch branch, GlbDepartment department, string jobNum, string nKRepOps)
			{
				using (Env.SetTemporaryUserContext(GlbStaff.CurrentUser.PK.ToGuid(), branch.PK.ToGuid(), department.PK.ToGuid()))
				{
					var receivingCompanyJob = new TestObjectCreator(Factory.CreateNewFactory()).CreateJobHeader();
					receivingCompanyJob.JH_JobNum = jobNum;
					receivingCompanyJob.JH_GS_NKRepOps = nKRepOps;
					receivingCompanyJob.Factory.Save();

					return receivingCompanyJob;
				}
			}
		}

