		#region Test ReOpen Closed Job

		public void TestRelatedJobsForReversing()
		{
			Job job1 = Factory.NewJobWithValidTestDataForTesting<Job>();
			Job job2 = Factory.NewJobWithValidTestDataForTesting<Job>();

			InvoicingBase invoice = (InvoicingBase)Factory.New(InvoicingBase.GetType());
			invoice.AH_TransactionNum = "TestInvoice00998";
			invoice.Lines.AddNew();
			invoice.Lines.AddNew();
			invoice.Lines[0].AL_JH = job1.PK;
			invoice.Lines[1].AL_JH = job2.PK;
			invoice.Lines[0].AL_AG = TestObjectCreator.GLHeader1.PK;
			invoice.Lines[1].AL_AG = TestObjectCreator.GLHeader1.PK;

			if (invoice.TransactionType_ForTestOnly == TransactionTypes.Invoice || invoice.TransactionType_ForTestOnly == TransactionTypes.CreditNote
				|| invoice.TransactionType_ForTestOnly == TransactionTypes.UAInvoice || invoice.TransactionType_ForTestOnly == TransactionTypes.UACreditNote)
			{
				AssertEquals(2, invoice.RelatedJobsForReversing.Count());
				Assert(invoice.RelatedJobsForReversing.Contains(job1));
				Assert(invoice.RelatedJobsForReversing.Contains(job2));

				TestObjectCreator.CreateJobCharge(invoice.Lines[0], job1, TestObjectCreator.CC1, TestObjectCreator.AUD);
				TestObjectCreator.CreateJobCharge(invoice.Lines[1], job2, TestObjectCreator.CC1, TestObjectCreator.AUD);

				ARCreditNote creditNoteNonJobRelated = Factory.NewWithValidTestData<ARCreditNote>();
				creditNoteNonJobRelated.Lines.AddNew();
				creditNoteNonJobRelated.Lines.AddNew();
				creditNoteNonJobRelated.Lines[0].AL_AG = TestObjectCreator.GLHeader1.PK;
				creditNoteNonJobRelated.Lines[1].AL_AG = TestObjectCreator.GLHeader1.PK;

				JobConsolCost cost = Factory.NewWithValidTestData<JobConsolCost>();
				cost.E6_AH_APInvoice = invoice.PK;
				cost.E6_AH_ARInvoice = creditNoteNonJobRelated.PK;

				Factory.Save();

				ARInvoice invoiceNonJobRelated = Factory.NewWithValidTestData<ARInvoice>();
				invoiceNonJobRelated.AH_TransactionBelongsToGroup = creditNoteNonJobRelated.PK;
				invoiceNonJobRelated.Lines.AddNew();
				invoiceNonJobRelated.Lines.AddNew();

				AssertEquals(2, invoiceNonJobRelated.RelatedJobsForReversing.Count());
				Assert(invoiceNonJobRelated.RelatedJobsForReversing.Contains(job1));
				Assert(invoiceNonJobRelated.RelatedJobsForReversing.Contains(job2));
			}
			else
			{
				AssertEquals(0, invoice.RelatedJobsForReversing.Count());
			}
		}

		public void TestHasClosedJob()
		{
			Job job1 = TestObjectCreator.CreateAndSaveTestShipmentJob(JobHeaderStatus.Working.Code);
			Job job2 = TestObjectCreator.CreateAndSaveTestShipmentJob(JobHeaderStatus.Closed.Code);

			InvoicingBase invoice = (InvoicingBase)Factory.New(InvoicingBase.GetType());

			if (invoice.TransactionType_ForTestOnly == TransactionTypes.Invoice || invoice.TransactionType_ForTestOnly == TransactionTypes.CreditNote
				|| invoice.TransactionType_ForTestOnly == TransactionTypes.UAInvoice || invoice.TransactionType_ForTestOnly == TransactionTypes.UACreditNote)
			{
				AssertEquals(".HasClosedJob when the invoice has no jobs", false, invoice.HasClosedJob);

				InvoicingLineBase line1 = (InvoicingLineBase)invoice.Lines.AddNew();
				line1.AL_JH = job1.PK;
				invoice.ResetRelatedJobsForReversing();
				AssertEquals(".HasClosedJob when the invoice has one WRK job", false, invoice.HasClosedJob);

				InvoicingLineBase line2 = (InvoicingLineBase)invoice.Lines.AddNew();
				line2.AL_JH = job2.PK;
				invoice.ResetRelatedJobsForReversing();
				AssertEquals(".HasClosedJob when the invoice has one CLS job", true, invoice.HasClosedJob);

				line2.AL_JH = ZGuid.Empty;
				invoice.ResetRelatedJobsForReversing();
				AssertEquals(".HasClosedJob when CLS job is removed", false, invoice.HasClosedJob);
			}
			else
			{
				Assert(true);
			}
		}

