		public void TestReOpenClosedJobByImport()
		{
			Job job1 = TestObjectCreator.CreateAndSaveTestShipmentJob(JobHeaderStatus.Closed.Code);
			Job job2 = TestObjectCreator.CreateAndSaveTestShipmentJob(JobHeaderStatus.Working.Code);

			InvoicingBase invoice = (InvoicingBase)Factory.New(typeof(APInvoice));
			invoice.AH_Ledger = "AP";
			invoice.AH_TransactionType = "INV";
			invoice.AH_TransactionNum = "TranNum";
			invoice.AH_OH = Factory.NewWithValidTestData<OrgHeader>().PK;

			invoice.AddRelatedJobsForReversing_ForTestOnly(job1);
			invoice.AddRelatedJobsForReversing_ForTestOnly(job2);
			Factory.Save();

			invoice.ReOpenClosedJob();
			Factory.Save();

			AssertEquals(JobHeaderStatus.Working.Code, job1.JH_Status);
			AssertEquals("InvoicingBase must call Job.ReOpenByImport() method to reopen jobs. If this UT failes, a possible reason is Job.Reopen() was called instead, which is incorrect.", $"Job status changed from CLS to WRK - AP INV TranNum ({invoice.Header.OH_Code}).", job1.GetLogs().AutoCreatedLog.DisplayEventReference);
		}

		public void TestReOpenClosedJobInvalidSecurityRights()
		{
			InvoicingBase invoice = (InvoicingBase)Factory.New(InvoicingBase.GetType());
			if (invoice.TransactionType_ForTestOnly == TransactionTypes.Invoice || invoice.TransactionType_ForTestOnly == TransactionTypes.CreditNote
				|| invoice.TransactionType_ForTestOnly == TransactionTypes.UAInvoice || invoice.TransactionType_ForTestOnly == TransactionTypes.UACreditNote)
			{
				Job job = TestObjectCreator.CreateAndSaveTestShipmentJob(JobHeaderStatus.Closed.Code);
				bool oldAllowReopenJob = Env.Security.ReopenJob.IsAllowed;

				try
				{
					Env.Security.ReopenJob.IsAllowed = false;
					InvoicingLineBase invoicingLine = (InvoicingLineBase)invoice.Lines.AddNew();
					invoicingLine.AL_JH = job.PK;
					AssertEquals(true, invoice.HasClosedJob);

					invoice.ReOpenClosedJob();
					AssertEquals("Should NOT reopen", true, invoice.HasClosedJob);
					AssertEquals("Should NOT reopen", JobHeaderStatus.Closed.Code, invoicingLine.Job.JH_Status);

					invoice.Factory.SetContext(BusinessContext.AllowReopenJobWhenImporting);
					invoice.ReOpenClosedJob();
					AssertEquals("Should reopen", false, invoice.HasClosedJob);
					AssertEquals("Should reopen", JobHeaderStatus.Working.Code, invoicingLine.Job.JH_Status);
				}
				finally
				{
					Env.Security.ReopenJob.IsAllowed = oldAllowReopenJob;
				}
			}
			else
			{
				Assert(true);
			}
		}

		public void TestReOpenClosedJobValidSecurityRights()
		{
			InvoicingBase invoice = (InvoicingBase)Factory.New(InvoicingBase.GetType());
