		public void TestReopenByPostingInvoices()
		{
			InvoicingBase invoice = (InvoicingBase)Factory.New(InvoicingBase.GetType());
			if (invoice.TransactionType_ForTestOnly == TransactionTypes.Invoice || invoice.TransactionType_ForTestOnly == TransactionTypes.CreditNote
				|| invoice.TransactionType_ForTestOnly == TransactionTypes.UAInvoice || invoice.TransactionType_ForTestOnly == TransactionTypes.UACreditNote)
			{
				Job job = TestObjectCreator.CreateAndSaveTestShipmentJob(JobHeaderStatus.Closed.Code);
				OrgHeader org = Factory.NewWithValidTestData<OrgHeader>();
				org.OH_Code = "~INVTST1~";
				invoice.AH_OH = org.PK;
				invoice.AH_TransactionNum = "0000001";
				bool oldAllowReopenJob = Env.Security.ReopenJob.IsAllowed;

				try
				{
					Env.Security.ReopenJob.IsAllowed = false;
					InvoicingLineBase invoicingLine = (InvoicingLineBase)invoice.Lines.AddNew();
					invoicingLine.AL_JH = job.PK;
					invoicingLine.AL_AG = TestObjectCreator.GLHeader1.PK;
					TestObjectCreator.CreateJobCharge(invoicingLine, job, TestObjectCreator.CC1, TestObjectCreator.AUD);
					AssertEquals(true, invoice.HasClosedJob);

					SecurityCore userSecurityWithAccess = new SecurityForTest(null, Env.CurrentUser.PK, Env.CurrentBranch.PK, Env.CurrentDepartment.PK, Env.CurrentCompany.PK);
					userSecurityWithAccess.CachingEnabled = false;
					userSecurityWithAccess.ReopenJob.IsAllowed = true;
					invoice.SecurityOverrideProvider = new NonInteractiveSecurityOverrideProvider();
					(invoice.SecurityOverrideProvider as NonInteractiveSecurityOverrideProvider).OverrideLogin = User.SupportUserName;
					(invoice.SecurityOverrideProvider as NonInteractiveSecurityOverrideProvider).OverridePassword = CWSupportLoginToken.TokenForTest;
					invoice.SecurityOverrideProvider.PromptForTemporaryAccess(userSecurityWithAccess.ReopenJob);

					invoice.ReOpenClosedJob();
					Factory.Save();

					BusinessObjectFactory tempFactory = new BusinessObjectFactory();
					invoice = (InvoicingBase)tempFactory.Load(InvoicingBase.GetType(), invoice.PK);
					invoicingLine = (InvoicingLineBase)tempFactory.Load(invoice.Lines[0].GetType(), invoicingLine.PK);

					AssertEquals("Should reopen", false, invoice.HasClosedJob);
					AssertEquals("Should reopen", JobHeaderStatus.Working.Code, invoicingLine.Job.JH_Status);
				}
				finally
				{
					Env.Security.ReopenJob.IsAllowed = oldAllowReopenJob;
				}
			}
			else
			{
				Assert(true);
			}
		}

