		#region ISupportMatchingOfMyLines

		public void TestOSPartialPaymentAmountComesFromLinesAmount()
		{
			InvoicingBase.AH_LocalExTaxAmount = 100M;
			InvoicingBase.AH_OSTotalAmount = 100M;
			InvoicingBase.AH_LocalOutstandingAmount = 70M;
			InvoicingBase.AH_FullyPaidDate = ZDateTime.Empty;

			AmountWithMultiplier = 60M;

			IMatching thisIMatching = InvoicingBase;
			thisIMatching.OSPartialPaymentAmount = AmountWithMultiplier;
			thisIMatching.PartiallyPay();
			AssertEquals("OSPartialPaymentAmount - regular behaviour", AmountWithMultiplier, thisIMatching.OSPartialPaymentAmount);

			Assert(!InvoicingBase.OSPartialPaymentAmount_ReadOnly);
			((ISupportMatchingOfMyLines)InvoicingBase).LineTotalPaidAmount = 42m;
			Assert(InvoicingBase.OSPartialPaymentAmount_ReadOnly);
			AssertEquals("OSPartialPaymentAmount - coming from lines' amounts", 42m, thisIMatching.OSPartialPaymentAmount);
			((ISupportMatchingOfMyLines)InvoicingBase).LineTotalPaidAmount = 0m;
			Assert(!InvoicingBase.OSPartialPaymentAmount_ReadOnly);
			((ILineMatching)DependentLine1).PaidAmount = 20m;
			thisIMatching.PartiallyPay();
			thisIMatching.GenerateMatchLinks();
			Assert("Should writable again", !InvoicingBase.OSPartialPaymentAmount_ReadOnly);
		}

		public void TestApportionPaidAmountToLinesSetsIsFullyPayToTrue()
		{
			APMatchingBase testMatchingBase = new APMatchingBase(Factory);
			testMatchingBase.PrimaryOrganization = CreditorOrg.PK;

			APInvoice invoice = Factory.NewWithValidTestData<APInvoice>();
			invoice.AH_OH = CreditorOrg.PK;
			TestObjectCreator.CreateInvoiceLine(invoice, invoice.TransactionCurrency, invoice.AH_ExchangeRate, 80m, 0m, 0m, 80m, 0m, 0m);

			Factory.Save();

			Overpayment.Overpayment testOVP = (Overpayment.Overpayment)testMatchingBase.GetMiscellaneousTransaction(TransactionTypes.Overpayment);
			testOVP.AH_OSExTaxAmount = 50M;
			testOVP.AH_LocalOutstandingAmount = 50M;

			testMatchingBase.AddIMatching(testOVP);
			testMatchingBase.AddIMatching(invoice);
			testMatchingBase.MatchedTransactions.SetPartialPaidAmount();

			var mediator = new InvoicingBasePayLineMediator(testMatchingBase, invoice);
			var invoiceLine = mediator.Lines[0].PaidAmount = -50m;
			mediator.ConveyData();

			Assert("Transactions should be matchable", testMatchingBase.MatchAndClearTransactions());
			Assert(!mediator.Lines[0].IsFullyPay);
		}

		public void TestApportionPaidAmountToLinesSetsIsFullyToFalse()
		{
			APMatchingBase testMatchingBase = new APMatchingBase(Factory);
			testMatchingBase.PrimaryOrganization = CreditorOrg.PK;

			APInvoice invoice = Factory.NewWithValidTestData<APInvoice>();
			invoice.AH_OH = CreditorOrg.PK;
			TestObjectCreator.CreateInvoiceLine(invoice, invoice.TransactionCurrency, invoice.AH_ExchangeRate, 80m, 0m, 0m, 80m, 0m, 0m);

			Factory.Save();

			Overpayment.Overpayment testOVP = (Overpayment.Overpayment)testMatchingBase.GetMiscellaneousTransaction(TransactionTypes.Overpayment);
			testOVP.AH_OSExTaxAmount = 80M;
			testOVP.AH_LocalOutstandingAmount = 80M;

			testMatchingBase.AddIMatching(testOVP);
			testMatchingBase.AddIMatching(invoice);
			testMatchingBase.MatchedTransactions.SetPartialPaidAmount();

			var mediator = new InvoicingBasePayLineMediator(testMatchingBase, invoice);
			var invoiceLine = mediator.Lines[0].PaidAmount = -80m;
			mediator.ConveyData();

			Assert("Transactions should be matchable", testMatchingBase.MatchAndClearTransactions());
			Assert(mediator.Lines[0].IsFullyPay);
		}

