		void AssertGenerateTransLinePayRecordsWithNewOSFeature(bool isEnableNewOSOutstandingAmountFeature)
		{
			AccountingMasterFilesRegistry.Instance.EnableNewOSOutstandingAmountFeature.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, isEnableNewOSOutstandingAmountFeature);
			InvoicingBase.AH_IsOSOutstandingAmountApplicable = isEnableNewOSOutstandingAmountFeature;

			ISupportMatchingOfMyLines thisAsISupportMatchingOfMyLines = InvoicingBase;
			IMatching thisAsIMatching = InvoicingBase;
			InvoicingBase.AH_LocalOutstandingAmount = 50m;
			((ILineMatching)InvoicingBase.Lines[0]).SetDefaultValues();
			((ILineMatching)InvoicingBase.Lines[0]).PaidAmount = 42m;
			thisAsIMatching.PartiallyPay();
			thisAsIMatching.GenerateMatchLinks();
			AssertEquals("Prerequisite: no AccTransLinePay records should exist", 0, Factory.Load<AccTransLinePay>(new ZQuery()).Length);
			thisAsIMatching.Matchlinks.Load();
			thisAsISupportMatchingOfMyLines.GenerateTransLinePayRecords(thisAsIMatching.Matchlinks[0].PK);
			AccTransLinePay[] createdRecords = Factory.Load<AccTransLinePay>(new ZQuery());
			AssertEquals("1 AccTransLinePay record should be created", 1, createdRecords.Length);
			AssertEquals("Amount", 42m, createdRecords[0].A7_Amount);
			AssertEquals(
				$"OSAmount, [EnableNewOSOutstandingAmountFeature:{isEnableNewOSOutstandingAmountFeature}]",
				isEnableNewOSOutstandingAmountFeature ? 42m : 0,
				createdRecords[0].A7_OSAmount
			);
			AssertEquals("Line ref", InvoicingBase.Lines[0].PK, createdRecords[0].A7_AL);
			AssertEquals("Matchlink ref", thisAsIMatching.Matchlinks[0].PK, createdRecords[0].A7_AP);
		}

