		public void TestShipmentMasterBill()
		{
			InvoicingBase invoice = (InvoicingBase)Factory.NewWithValidTestData(InvoicingBase.GetType());
			if (invoice is APInvoice || invoice is APCreditNote || invoice is APAdjustmentNote)
			{
				Assert("The test is only applicable for AR invoices", true);
				return;
			}
			ForwardingConsol consolAIR = TestObjectCreator.CreateConsol("AUSYD", "NZAKL", "C001");
			consolAIR.JK_MasterBillNum = "TEST12345";
			invoice.AH_ConsolidatedInvoiceRef = "C001";
			Factory.Save();

			IMatching matching = invoice;
			AssertEquals("TEST12345", matching.ShipmentMasterBill);

			ForwardingConsol consolSEA = Factory.NewWithValidTestData<ForwardingConsol>();
			consolSEA.JK_MasterBillNum = "TEST54321";
			ForwardingShipment shipment2 = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment2.JS_HouseBill = "TESTSHIPMENT00012";
			shipment2.Consols.Add(consolAIR);
			shipment2.Consols.Add(consolSEA);
			Job job2 = TestObjectCreator.CreateJob(shipment2, false);
			Factory.Save();
			invoice.AH_JH = job2.PK;

			AssertContainsExactElementsInAnyOrder("Matching.ShipmentMasterBill",
				new string[] { "TEST12345", "TEST54321" },
				matching.ShipmentMasterBill.ToString().Split(new string[] { ", " }, StringSplitOptions.None));

			var plugInData = new InvoicingParam();
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fMasterBillNumber = "TESTDECLARATION00015";
			Job job3 = TestObjectCreator.CreateJob(plugInData, false);
			job3.JH_ParentTableCode = JobDeclarationSchema.Constants.Prefix;
			invoice.AH_JH = job3.PK;
			AssertEquals("TESTDECLARATION00015", matching.ShipmentMasterBill);

			invoice.AH_JH = ZGuid.Empty;
			consolAIR.JK_UniqueConsignRef = "C00001344";
			invoice.AH_ConsolidatedInvoiceRef = "C00001344/B";
			AssertEquals("TEST12345", matching.ShipmentMasterBill);
		}

