		public void TestVoyageVesselOrFlightDate()
		{
			var invoice = (InvoicingBase)Factory.NewWithValidTestData(InvoicingBase.GetType());
			var consolAIR = Factory.GetCachedReadOnlyFactory().NewWithValidTestData<ForwardingConsol>();
			var job = Factory.GetCachedReadOnlyFactory().NewJobWithValidTestDataForTesting<Job>();
			invoice.AH_JH = job.PK;
			job.JH_ParentTableCode = JobConsolSchema.Constants.Prefix;
			job.JH_ParentID = consolAIR.PK;
			job.Parent = consolAIR;
			consolAIR.JK_TransportMode = Constants.TransportModes.Air;
			consolAIR.Transports[0].JW_VoyageFlight = "TEST12345";

			var matching = invoice as IMatching;

			AssertEquals("TEST12345", matching.VoyageVesselOrFlightDate);

			var sailing = Factory.GetCachedReadOnlyFactory().NewWithValidTestData<BaseJobSailing>();
			var shipment = (CommonShipment)(Factory.GetCachedReadOnlyFactory().New<Freight.Integration.Agency.IBillOfLading>());

			var vessel = Factory.NewWithValidTestData<RefVessel>();
			vessel.RV_Name = "AVRORA";

			shipment.JS_JX = sailing.PK;
			shipment.Sailing.Voyage.JV_RV_NKVessel = vessel.RV_FK;
			shipment.Sailing.Voyage.JV_VoyageFlight = "001";
			var test = job.PlugInData.InvoicingSupporter;
			job.JH_ParentTableCode = JobShipmentSchema.Constants.Prefix;
			job.JH_ParentID = shipment.PK;
			job.Parent = shipment;
			AssertEquals("001/AVRORA", matching.VoyageVesselOrFlightDate);

			var forwardingShipment = Factory.GetCachedReadOnlyFactory().NewWithValidTestData<ForwardingShipment>();
			job.Parent = forwardingShipment;
			var consolSEA = Factory.GetCachedReadOnlyFactory().NewWithValidTestData<ForwardingConsol>();
			consolSEA.JK_TransportMode = Constants.TransportModes.Sea;
			consolSEA.Transports[0].JW_VoyageFlight = "TEST54321";
			consolSEA.Transports[0].JW_Vessel = "ENTERPRISE";

			forwardingShipment.Consols.Add(consolAIR);
			forwardingShipment.Consols.Add(consolSEA);
			AssertEquals("TEST12345, TEST54321/ENTERPRISE", matching.VoyageVesselOrFlightDate);

			forwardingShipment.JS_E_DEP = ZDateTime.BrettsBirthday;
			AssertEquals("TEST12345/18-SEP-71, TEST54321/ENTERPRISE", matching.VoyageVesselOrFlightDate);

			consolAIR.Transports[0].JW_ETD = ZDateTime.BrettsBirthday.AddDays(1);
			AssertEquals("TEST12345/19-SEP-71, TEST54321/ENTERPRISE", matching.VoyageVesselOrFlightDate);

			consolAIR.Transports[0].JW_ATD = ZDateTime.BrettsBirthday.AddDays(2);
			AssertEquals("TEST12345/20-SEP-71, TEST54321/ENTERPRISE", matching.VoyageVesselOrFlightDate);

			var declaration = Factory.GetCachedReadOnlyFactory().NewWithValidTestData<BaseJobDeclaration>();
			declaration.JE_TransportMode = Enterprise.Core.Constants.TransportModes.Sea;
			declaration.JE_VesselName = "NAUTILUS";
			declaration.JE_VoyageFlightNo = "007";

			job.JH_ParentTableCode = JobDeclarationSchema.Constants.Prefix;
			job.JH_ParentID = declaration.PK;
			job.Parent = declaration;
			AssertEquals("007/NAUTILUS", matching.VoyageVesselOrFlightDate);

			var cartage = Factory.GetCachedReadOnlyFactory().NewWithValidTestData<CommonCartage>();
			cartage.Vessel = "OTELLO";
			cartage.VoyageFlight = "009";
			job.JH_ParentTableCode = JobCartageSchema.Constants.Prefix;
			job.JH_ParentID = cartage.PK;
			job.Parent = cartage;
			AssertEquals("009/OTELLO", matching.VoyageVesselOrFlightDate);

			var vessel2 = Factory.NewWithValidTestData<RefVessel>();
			vessel2.RV_Name = "PLANET EXPRESS";

			var jobVoyage = Factory.GetCachedReadOnlyFactory().NewWithValidTestData<JobVoyage>();
			jobVoyage.JV_RV_NKVessel = vessel2.RV_FK;
			jobVoyage.JV_VoyageFlight = "001000";
			var voyage = (BusinessObject)Factory.GetCachedReadOnlyFactory().New<Freight.Integration.Agency.IVoyageAccount>();
			voyage["NA_JV"] = jobVoyage.PK;
			job.JH_ParentTableCode = JobVoyAccountSchema.Constants.Prefix;
			job.JH_ParentID = voyage.PK;
			job.PlugInData = (IJobInvoicingPlugIn)voyage;
			AssertEquals("001000/PLANET EXPRESS", matching.VoyageVesselOrFlightDate);

			if (invoice.AH_Ledger == LedgerTypes.AccountsReceivable)
			{
				invoice.AH_JH = ZGuid.Empty;
				consolAIR.JK_UniqueConsignRef = "C00001344";
				invoice.AH_ConsolidatedInvoiceRef = "C00001344/C";
				AssertEquals("TEST12345/20-SEP-71", matching.VoyageVesselOrFlightDate);
			}
		}

		public void TestVoyageVesselOrFlightDateDoesNotLoadJobInItsFactory()
		{
			InvoicingBase invoice = (InvoicingBase)Factory.NewWithValidTestData(InvoicingBase.GetType());

			Job job = Factory.NewJobWithValidTestDataForTesting<Job>();
			invoice.AH_JH = job.PK;

			var vessel = Factory.NewWithValidTestData<RefVessel>();
			vessel.RV_Name = "AVRORA";

			BaseJobSailing sailing = Factory.NewWithValidTestData<BaseJobSailing>();
			ForwardingShipment shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_JX = sailing.PK;
			shipment.Sailing.Voyage.JV_RV_NKVessel = vessel.RV_FK;
			shipment.Sailing.Voyage.JV_VoyageFlight = "001";
			job.JH_ParentTableCode = JobShipmentSchema.Constants.Prefix;
			job.JH_ParentID = shipment.PK;

			job.PlugInData = shipment;
			ForwardingConsol consolAIR = Factory.NewWithValidTestData<ForwardingConsol>();
			consolAIR.JK_TransportMode = Enterprise.Core.Constants.TransportModes.Air;
			consolAIR.Transports[0].JW_VoyageFlight = "TEST12345";

			shipment.Consols.Add(consolAIR);

			Factory.Save();

			if (invoice.Job == null && invoice.Lines.Count > 0)
			{
				// AH_JH was reset on saving because the same value was not set on all Lines
				invoice.AH_JH = job.PK;
				foreach (InvoicingLineBase line in invoice.Lines)
				{
					line.AL_JH = job.PK;
				}

				Factory.Save();
			}

			var newFactory = new BusinessObjectFactory();
			var reloadedInvoice = newFactory.Load<InvoicingBase>(invoice.PK);
			if (reloadedInvoice.AH_JH.IsEmpty)
			{
				// Need to set AH_JH back if for some reason it was reset on saving
				reloadedInvoice.AH_JH = job.PK;
			}

			IMatching matching = reloadedInvoice;

			AssertEquals("TEST12345", matching.VoyageVesselOrFlightDate);

			var jobFilter = new ZQuery();
			jobFilter.FetchOnlyFromLocalCache = true;
			AssertEquals("No jobs should be loaded in the IMatching Factory", false, newFactory.Load<Job>(jobFilter).Any());
			AssertEquals("jobs should be loaded in the IMatching Factory's ReadOnly Factory", true, newFactory.GetCachedReadOnlyFactory().Load<Job>(jobFilter).Any());
		}

