		public void TestHasInvalidPostingGroups()
		{
			if (InvoicingBase.GetType() != typeof(TransactionPendingAllocation))
			{
				var vat3 = TestObjectCreator.CreateTaxRate("VAT3", "VAT3", 3);
				vat3.AT_PostingGroupId = 0;

				var vat5 = TestObjectCreator.CreateTaxRate("VAT5", "VAT5", 5);
				vat5.AT_PostingGroupId = 1;

				var ac1 = TestObjectCreator.CreateChargeCode("AC1");
				ac1.AC_AT_GSTRate = vat3.PK;
				ac1.AC_Desc = "desc";

				var ac2 = TestObjectCreator.CreateChargeCode("AC2");
				ac2.AC_AT_GSTRate = vat5.PK;
				ac2.AC_Desc = "desc";

				Factory.Save();

				using (AccountingMasterFilesRegistry.Instance.EnableComplianceDocumentModule.SetTemporaryValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, true))
				using (GlbCompany.CurrentCompany.TemporarilySetCountry(Core.Constants.CountryCodes.Taiwan))
				{
					var invoice = TestObjectCreator.CreateInvoice(InvoicingBase.GetType());
					var invoiceLine = (InvoicingLineBase)invoice.Lines.AddNew();
					invoiceLine.AL_AT = vat3.PK;
					invoiceLine.AL_AC = ac1.PK;
					var invoiceLine1 = (InvoicingLineBase)invoice.Lines.AddNew();
					invoiceLine1.AL_AT = vat5.PK;
					invoiceLine1.AL_AC = ac2.PK;

					Assert(!invoice.HasInvalidPostingGroups);
				}

				using (AccountingMasterFilesRegistry.Instance.EnableComplianceDocumentModule.SetTemporaryValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, false))
				using (GlbCompany.CurrentCompany.TemporarilySetCountry(Core.Constants.CountryCodes.Taiwan))
				{
					var invoice = TestObjectCreator.CreateInvoice(InvoicingBase.GetType());
					var invoiceLine = (InvoicingLineBase)invoice.Lines.AddNew();
					invoiceLine.AL_AT = vat3.PK;
					invoiceLine.AL_AC = ac1.PK;
					var invoiceLine1 = (InvoicingLineBase)invoice.Lines.AddNew();
					invoiceLine1.AL_AT = vat5.PK;
					invoiceLine1.AL_AC = ac2.PK;

					Assert(invoice.HasInvalidPostingGroups);
				}
			}
			else
			{
				Assert(true);
			}
		}

