		void AssertFullyPay(bool isEnableNewOSOutstandingAmountFeature)
		{
			AccountingMasterFilesRegistry.Instance.EnableNewOSOutstandingAmountFeature.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, isEnableNewOSOutstandingAmountFeature);

			InvoicingBase.AH_OSExTaxAmount = 200m;
			InvoicingBase.AH_OSTaxAmount = 20.00m;
			InvoicingBase.AH_OutstandingAmount = 220.00m;
			InvoicingBase.AH_FullyPaidDate = ZDateTime.Empty;

			if (isEnableNewOSOutstandingAmountFeature)
			{
				InvoicingBase.MakeOSOutstandingAmountApplicable(220m);

				AssertEquals("PreCondition - AH_IsOSOutstandingAmountApplicable", true, InvoicingBase.AH_IsOSOutstandingAmountApplicable);
				AssertEquals("PreCondition - AH_OSOutstandingAmount", 220m, InvoicingBase.AH_OSOutstandingAmount);
			}

			ZDateTime expectedFullyPaidDate = ZDateTime.Now.AddDays(-3);

			((IMatching)InvoicingBase).FullyPay(expectedFullyPaidDate);

			AssertEquals("Fully Paid date on Invoice", expectedFullyPaidDate, InvoicingBase.AH_FullyPaidDate);
			AssertEquals("Outstanding Amount on Invoice", 0m, InvoicingBase.AH_OutstandingAmount);
			AssertEquals("AH_OSOutstandingAmount", 0m, InvoicingBase.AH_OSOutstandingAmount);
			AssertEquals("AH_IsOSOutstandingAmountApplicable", isEnableNewOSOutstandingAmountFeature, InvoicingBase.AH_IsOSOutstandingAmountApplicable);
			//AssertEquals("Private field should be set by calling method", 220.00m, InvoicingBase.CurrentPaidAmount);
		}

		public virtual void TestCalculatePaidOutstandingAmountInSpecificCurrencyOnly()
		{
			JobHeader job = Factory.NewJobWithValidTestDataForTesting<JobHeader>();
			Charge charge = Factory.NewWithValidTestData<Charge>();
			charge.JR_JH = job.PK;
			charge.JR_RX_NKCostCurrency = "USD";
			charge.JR_RX_NKSellCurrency = "USD";
			Header = (InvoicingBase)GetNewBusinessObject();
			Header.AH_JH = job.PK;
			IMatching thisIMatching = InvoicingBase;
			ISupportMatchingOfMyLines thisAsISupportMatchingOfMyLines = InvoicingBase;

			thisIMatching.OSPartialPaymentAmount = 100m;
			AssertEquals(100m, thisIMatching.CalculatePaidOutstandingAmountInSpecificCurrencyOnly("AUD"));
			AssertEquals(0m, thisIMatching.CalculatePaidOutstandingAmountInSpecificCurrencyOnly("USD"));

			TransactionLine line1 = InvoicingBase.Lines.AddNew();
			line1.AL_JH = job.PK;
			((ILineMatching)line1).PaidAmountInChargeCurrency = 100m;
			charge.JR_AL_APLine = line1.PK;
			thisAsISupportMatchingOfMyLines.LineTotalPaidAmount = 100m;

			AssertEquals(0m, thisIMatching.CalculatePaidOutstandingAmountInSpecificCurrencyOnly("AUD"));
			if (Header.AH_Ledger != LedgerTypes.UnapprovedPayableTransactions)
			{
				AssertEquals(100m, thisIMatching.CalculatePaidOutstandingAmountInSpecificCurrencyOnly("USD"));
			}
		}

		public virtual void TestIsAllPaidInTheSameCurrency()
		{
			JobHeader job = Factory.NewJobWithValidTestDataForTesting<JobHeader>();
			Charge charge = Factory.NewWithValidTestData<Charge>();
			charge.JR_JH = job.PK;
			charge.JR_RX_NKCostCurrency = "AUD";
			charge.JR_RX_NKSellCurrency = "AUD";
			Header = (InvoicingBase)GetNewBusinessObject();
			Header.AH_JH = job.PK;
			IMatching thisIMatching = InvoicingBase;
			ISupportMatchingOfMyLines thisAsISupportMatchingOfMyLines = InvoicingBase;
			Assert(thisIMatching.IsAllPaidInTheSameCurrency("AUD"));
			Assert(!thisIMatching.IsAllPaidInTheSameCurrency("USD"));
			TransactionLine line1 = InvoicingBase.Lines.AddNew();
			line1.AL_JH = job.PK;
			((ILineMatching)line1).PaidAmountInChargeCurrency = 100m;
			charge.JR_AL_APLine = line1.PK;
			thisAsISupportMatchingOfMyLines.LineTotalPaidAmount = 100m;
			Assert(thisIMatching.IsAllPaidInTheSameCurrency("AUD"));

			charge.JR_RX_NKCostCurrency = "USD";
			charge.JR_RX_NKSellCurrency = "USD";
			Assert(!thisIMatching.IsAllPaidInTheSameCurrency("AUD"));
		}

