		public void TestFullyPayForTransLinePay_EnableNewOSOutstandingAmountFeature()
		{
			AssertFullyPayForTransLinePay(isEnableNewOSOutstandingAmountFeature: true);
		}

		void AssertFullyPayForTransLinePay(bool isEnableNewOSOutstandingAmountFeature)
		{
			AccountingMasterFilesRegistry.Instance.EnableNewOSOutstandingAmountFeature.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, isEnableNewOSOutstandingAmountFeature);

			APMatchingBase testMatchingBase = new APMatchingBase(Factory);
			testMatchingBase.PrimaryOrganization = CreditorOrg.PK;

			APInvoice invoice = Factory.NewWithValidTestData<APInvoice>();
			ISupportMatchingOfMyLines thisAsISupportMatchingOfMyLines = invoice;

			invoice.AH_OH = CreditorOrg.PK;
			AmountWithMultiplier = 80M;
			IMatching invoiceAsIMatching = invoice;
			TestObjectCreator.CreateInvoiceLine(invoice, invoice.TransactionCurrency, invoice.AH_ExchangeRate, 100m, 0m, 0m, 100m, 0m, 0m);
			TestObjectCreator.CreateInvoiceLine(invoice, invoice.TransactionCurrency, invoice.AH_ExchangeRate, -20m, 0m, 0m, -20m, 0m, 0m);

			Factory.Save();

			var matchingCollectionToForceCorrectValidationClassForInvoice = new IMatchingCollection(Factory, MatchingCollectionTypes.MatchedTransactions);
			matchingCollectionToForceCorrectValidationClassForInvoice.Add(invoice);
			var mediator = new InvoicingBasePayLineMediator(testMatchingBase, invoice);
			var invoiceLine1 = (from ILineMatching l in mediator.Lines where l.AL_OSExTaxAmount == 100m select l).First();
			var invoiceLine2 = (from ILineMatching l in mediator.Lines where l.AL_OSExTaxAmount == -20m select l).First();
			invoiceLine1.PaidAmount = -80m;
			invoiceLine2.PaidAmount = 10m;
			mediator.ConveyData();

			Overpayment.Overpayment testOVP = (Overpayment.Overpayment)testMatchingBase.GetMiscellaneousTransaction(TransactionTypes.Overpayment);
			testOVP.AH_OSExTaxAmount = 70M;
			testOVP.AH_LocalOutstandingAmount = 70M;

			testMatchingBase.AddIMatching(invoice);
			testMatchingBase.AddIMatching(testOVP);
			testMatchingBase.MatchedTransactions.SetPartialPaidAmount();
			invoiceAsIMatching.OSPartialPaymentAmount = -70m;

			Assert("Transactions should be matchable", testMatchingBase.MatchAndClearTransactions());

			Assert("Precondition - Total should not be zero", invoice.AH_OSTotalAmount != 0m);
			Assert("Precondition - Outstanding Amount should not be zero", invoice.AH_OutstandingAmount != 0m);
			Assert("Precondition - Fully Paid Date should be empty", invoice.AH_FullyPaidDate.IsEmpty);

			if (isEnableNewOSOutstandingAmountFeature)
			{
				AssertEquals("Precondition - AH_IsOSOutstandingAmountApplicable", true, invoice.AH_IsOSOutstandingAmountApplicable);
				AssertEquals("Precondition - AH_OSOutstandingAmount should not be zero", true, invoice.AH_OSOutstandingAmount != 0m);
			}

			Assert(!((ILineMatching)DependentLine1).IsFullyPay);
			Assert(!((ILineMatching)DependentLine2).IsFullyPay);
			AssertEquals(-70m, thisAsISupportMatchingOfMyLines.LineTotalPaidAmountPosted);

			ZDateTime expectedFullyPaidDate = ZDateTime.Now.AddDays(-3);

			((IMatching)invoice).FullyPay(expectedFullyPaidDate);

			AssertEquals("Fully Paid date on Invoice", expectedFullyPaidDate, invoice.AH_FullyPaidDate);
			AssertEquals("Outstanding Amount should be zero after lines", 0M, invoice.AH_OutstandingAmount);
			AssertEquals("AH_OSOutstandingAmount", 0m, invoice.AH_OSOutstandingAmount);
			AssertEquals("AH_IsOSOutstandingAmountApplicable", isEnableNewOSOutstandingAmountFeature, invoice.AH_IsOSOutstandingAmountApplicable);

			Assert(((ILineMatching)invoice.Lines[0]).IsFullyPay);
			Assert(((ILineMatching)invoice.Lines[1]).IsFullyPay);
		}

