		void AssertPartiallyPay(bool isEnableNewOSOutstandingAmountFeature)
		{
			AccountingMasterFilesRegistry.Instance.EnableNewOSOutstandingAmountFeature.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, isEnableNewOSOutstandingAmountFeature);

			InvoicingBase.AH_LocalExTaxAmount = 100M;
			InvoicingBase.AH_OSTotalAmount = 100M;
			InvoicingBase.AH_LocalOutstandingAmount = 70M;
			InvoicingBase.AH_FullyPaidDate = ZDateTime.Empty;

			if (isEnableNewOSOutstandingAmountFeature)
			{
				var osOutstandingAmount = 70m * InvoicingBase.Multiplier_ForTestOnly;
				InvoicingBase.MakeOSOutstandingAmountApplicable(osOutstandingAmount);

				AssertEquals("PreCondition - AH_IsOSOutstandingAmountApplicable", true, InvoicingBase.AH_IsOSOutstandingAmountApplicable);
				AssertEquals("PreCondition - AH_OSOutstandingAmount", 70m, InvoicingBase.AH_OSOutstandingAmount_WithMultiplier_ForTestOnly);
			}

			AmountWithMultiplier = 60M;

			IMatching thisIMatching = InvoicingBase;
			thisIMatching.OSPartialPaymentAmount = AmountWithMultiplier;
			thisIMatching.PartiallyPay();

			AssertEquals("Local Outstanding Amount should be 10", 10M, InvoicingBase.AH_LocalOutstandingAmount);
			AssertEquals("Should not be fully paid", ZDateTime.Empty, InvoicingBase.AH_FullyPaidDate);
			AssertEquals("AH_OSOutstandingAmount", isEnableNewOSOutstandingAmountFeature ? 10m : 0m, InvoicingBase.AH_OSOutstandingAmount_WithMultiplier_ForTestOnly);
			AssertEquals("AH_IsOSOutstandingAmountApplicable", isEnableNewOSOutstandingAmountFeature, InvoicingBase.AH_IsOSOutstandingAmountApplicable);

			thisIMatching.GenerateMatchLinks();
			TransactionMatchLinkCollection matchLinks = ((IMatching)InvoicingBase).CurrentMatchGroup;

			AssertEquals("There should be 1 matchlink", 1, matchLinks.Count);
			TransactionMatchLink matchLink = matchLinks[0];
			AssertEquals("Amount should be +60/-60 depending on Invoice/CreditNote/AdjNote type", AmountWithMultiplier, matchLink.AP_Amount);
			AssertEquals("AP_OSAmount", isEnableNewOSOutstandingAmountFeature ? AmountWithMultiplier : new ZDecimal(0m), matchLink.AP_OSAmount);
		}

