		void AssertGenerateMatchLinks(bool isEnableNewOSOutstandingAmountFeature)
		{
			AccountingMasterFilesRegistry.Instance.EnableNewOSOutstandingAmountFeature.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, isEnableNewOSOutstandingAmountFeature);

			InvoicingBase.AH_OSExTaxAmount = 100m;
			InvoicingBase.AH_OSTaxAmount = 10.00m;
			InvoicingBase.AH_OutstandingAmount = 110.00m;
			InvoicingBase.AH_FullyPaidDate = ZDateTime.Empty;

			if (isEnableNewOSOutstandingAmountFeature)
			{
				InvoicingBase.MakeOSOutstandingAmountApplicable(110m);

				AssertEquals("PreCondition - AH_IsOSOutstandingAmountApplicable", true, InvoicingBase.AH_IsOSOutstandingAmountApplicable);
				AssertEquals("PreCondition - AH_OSOutstandingAmount", 110m, InvoicingBase.AH_OSOutstandingAmount);
			}

			ZDateTime expectedFullyPaidDate = ZDateTime.Now.AddDays(-2);

			((IMatching)InvoicingBase).FullyPay(expectedFullyPaidDate);
			InvoicingBase.GenerateMatchLinks();
			TransactionMatchLinkCollection matchLinks = ((IMatching)InvoicingBase).CurrentMatchGroup;

			AssertEquals("Should have one matchlink record generated", 1, matchLinks.Count);

			TransactionMatchLink singleLink = matchLinks[0];

			AssertEquals("Match Amount should be same as outstanding amount after fully paying",
				110.00m, singleLink.AP_Amount);
			AssertEquals("AP_OSAmount",
				isEnableNewOSOutstandingAmountFeature ? 110.00m : 0m, singleLink.AP_OSAmount);
			AssertEquals("Match FK should be this header", InvoicingBase.PK, singleLink.AP_AH);
		}

		public void TestWithInvoiceAmountSignDifferentfromTotalSign()
		{
			AmountWithMultiplier = 1;
			var multiplier = AmountWithMultiplier;
			InvoicingBase.AH_InvoiceAmount = 402.9M * multiplier;
			InvoicingBase.AH_GSTAmount = -491.25M * multiplier;
			AssertEquals("Invoice amount sign should be different than invoice total sign", false, Math.Sign(InvoicingBase.AH_InvoiceAmount) == Math.Sign(InvoicingBase.AH_InvoiceAmount + InvoicingBase.AH_GSTAmount));
			var matchLinkAmount = -88.35M * multiplier;
			AssertEquals(UnmatchingResult.Success, ((IMatching)InvoicingBase).CanUnmatch(matchLinkAmount));

			AmountWithMultiplier = -1;
			multiplier = AmountWithMultiplier;
			InvoicingBase.AH_InvoiceAmount = 402.9M * multiplier;
			InvoicingBase.AH_GSTAmount = -491.25M * multiplier;
			AssertEquals("Invoice amount sign should be different than invoice total sign", false, Math.Sign(InvoicingBase.AH_InvoiceAmount) == Math.Sign(InvoicingBase.AH_InvoiceAmount + InvoicingBase.AH_GSTAmount));
			matchLinkAmount = -88.35M * multiplier;
			AssertEquals(UnmatchingResult.Success, ((IMatching)InvoicingBase).CanUnmatch(matchLinkAmount));
		}

