		public void TestUnmatchWithTax()
		{
			InvoicingBase.AH_LocalExTaxAmount = 20M;
			InvoicingBase.AH_LocalTaxAmount = 3M;
			InvoicingBase.AH_LocalOutstandingAmount = 4M;

			AmountWithMultiplier = 6M;

			AssertEquals("Can unmatch 6 since less than tax amt + invoice amt - outstanding amt", UnmatchingResult.Success, ((IMatching)InvoicingBase).CanUnmatch(AmountWithMultiplier));

			AmountWithMultiplier = 20M;
			AssertEquals("Cannot unmatch 20 since greater than tax amt + invoice amt - outstanding amt", UnmatchingResult.DataErrorAddingMatchAmountExceedOriginalInvoiceAmount, ((IMatching)InvoicingBase).CanUnmatch(AmountWithMultiplier));
		}

		public void TestLocalPartialPaymentAmount()
		{
			InvoicingLineBase line = (InvoicingLineBase)InvoicingBase.Lines.AddNew();
			line.AL_OSExTaxAmount = 264.47M;
			InvoicingBase.AH_RX_NKTransactionCurrency = ForeignCurrency.RX_Code;
			InvoicingBase.AH_ExchangeRate = 0.6867M;
			//Line.AL_LocalExTaxAmount = 385.14M;
			AmountWithMultiplier = 264.47M;
			((IMatching)InvoicingBase).OSPartialPaymentAmount = AmountWithMultiplier;

			AssertEquals("LocalPartialPayment amount should be +/- 385.14 depending on AR/AP i.e. same as AH_OutstandingAmount",
				InvoicingBase.AH_InvoiceAmount + InvoicingBase.AH_GSTAmount, ((IMatching)InvoicingBase).LocalPartialPaymentAmount);
			AssertEquals("LocalPartialPayment amount should be +/- 385.14 depending on AR/AP i.e. same as AH_OutstandingAmount",
				385.13M, Math.Abs(((IMatching)InvoicingBase).LocalPartialPaymentAmount));

			AmountWithMultiplier = 100M;
			((IMatching)InvoicingBase).OSPartialPaymentAmount = AmountWithMultiplier;
			AmountWithMultiplier = 145.62M;

			AssertEquals("LocalPartialPayment amount should be 145.62", AmountWithMultiplier, ((IMatching)InvoicingBase).LocalPartialPaymentAmount);

			AssertEquals("OutStandingAmount is 385.13M", 385.13M, Math.Abs(((IMatching)InvoicingBase).OutstandingAmount));
			((IMatching)InvoicingBase).OSPartialPaymentAmount = 400M;
			AssertEquals("LocalPartialPaymentAmount is greater than OutstandingAmount", true, (ZDecimal)Env.CurrentCompany.ExchangeRate.ForeignToLocal(((IMatching)InvoicingBase).OSPartialPaymentAmount, InvoicingBase.AH_ExchangeRate) > 385.13M);
			AssertEquals("LocalPartialPayment amount should be OutstandingAmount when it is greater than OutstandingAmount.", 385.13M, Math.Abs(((IMatching)InvoicingBase).LocalPartialPaymentAmount));
		}

