		public void TestDoesAPInvoiceAndCRDHasPCDSetting()
		{
			var apInvoice = (APInvoice)TestObjectCreator.CreateInvoiceWithLine(typeof(APInvoice), "APInv001", TestObjectCreator.AUD, 1M, 100M, 10M, 100M, 10M);
			apInvoice.AH_TransactionType = TransactionTypes.AdjustmentNote;
			Assert(!apInvoice.HasPCDSettingForAP);

			apInvoice.AH_TransactionType = TransactionTypes.Invoice;
			Assert(!apInvoice.HasPCDSettingForAP);

			AccountingMasterFilesRegistry.Instance.EnableComplianceDocumentModule.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, false);
			Assert(!apInvoice.HasPCDSettingForAP);

			AccountingMasterFilesRegistry.Instance.EnableComplianceDocumentModule.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);
			Assert(!apInvoice.HasPCDSettingForAP);

			TestObjectCreator.AALSHI.CompanyData.OB_APCreateVATComplianceDocumentOnPosting = Constants.OrganisationCreateComplianceDocumentOnPostingTypes.RollupByCharge;
			apInvoice.AH_OH = TestObjectCreator.AALSHI.PK;
			Assert(!apInvoice.HasPCDSettingForAP);

			TestObjectCreator.AALSHI.CompanyData.OB_APCreateVATComplianceDocumentOnPosting = Constants.OrganisationCreateComplianceDocumentOnPostingTypes.PerComplianceDocumentNumber;
			Assert(apInvoice.HasPCDSettingForAP);

			var apCreditNote = (APCreditNote)TestObjectCreator.CreateInvoiceWithLine(typeof(APCreditNote), "APCrd001", TestObjectCreator.AUD, 1M, 100M, 10M, 100M, 10M);

			AccountingMasterFilesRegistry.Instance.EnableComplianceDocumentModule.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, false);
			Assert(!apCreditNote.HasPCDSettingForAP);

			AccountingMasterFilesRegistry.Instance.EnableComplianceDocumentModule.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);
			Assert(!apCreditNote.HasPCDSettingForAP);

			TestObjectCreator.AALSHI.CompanyData.OB_APCreateVATComplianceDocumentOnPosting = Constants.OrganisationCreateComplianceDocumentOnPostingTypes.RollupByCharge;
			apCreditNote.AH_OH = TestObjectCreator.AALSHI.PK;
			Assert(!apCreditNote.HasPCDSettingForAP);

			TestObjectCreator.AALSHI.CompanyData.OB_APCreateVATComplianceDocumentOnPosting = Constants.OrganisationCreateComplianceDocumentOnPostingTypes.PerComplianceDocumentNumber;
			Assert(apCreditNote.HasPCDSettingForAP);
		}

