		public void TestCanCreateComplianceDocument()
		{
			TestObjectCreator.AALSHI.CompanyData.OB_APCreateVATComplianceDocumentOnPosting = Constants.OrganisationCreateComplianceDocumentOnPostingTypes.RollupByCharge;
			Factory.Save();

			var invoice = (APInvoice)TestObjectCreator.CreateInvoiceWithLine(typeof(APInvoice), "Inv001", TestObjectCreator.AUD, 1M, 100M, 10M, 100M, 10M);
			invoice.AH_OH = TestObjectCreator.AALSHI.PK;
			Assert(!invoice.CanCreateComplianceDocument);

			invoice.AH_Ledger = LedgerTypes.AccountsPayable;
			AccountingMasterFilesRegistry.Instance.EnableComplianceDocumentModule.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);

			var line1 = invoice.Lines[0];
			line1.AL_AT = TestObjectCreator.GSTFREE1.PK;
			TransactionMatchLink matchLink = ((IMatching)invoice).CurrentMatchGroup.AddNew();
			matchLink.AP_AH = invoice.PK;
			TestObjectCreator.SetupMatchLinkMatchDate(matchLink);
			invoice.AH_IsCancelled = false;
			invoice.AH_TransactionType = TransactionTypes.Invoice;

			Env.Security.CreatePayablesComplianceDocuments.IsAllowed = true;
			Assert(invoice.CanCreateComplianceDocument);

			Env.Security.CreatePayablesComplianceDocuments.IsAllowed = false;
			Assert(invoice.CanCreateComplianceDocument);

			TestObjectCreator.AALSHI.CompanyData.OB_APCreateVATComplianceDocumentOnPosting = Constants.OrganisationCreateComplianceDocumentOnPostingTypes.NotApplicable;
			Assert(!invoice.CanCreateComplianceDocument);

			TestObjectCreator.AALSHI.CompanyData.OB_APCreateVATComplianceDocumentOnPosting = Constants.OrganisationCreateComplianceDocumentOnPostingTypes.PerComplianceDocumentNumber;
			line1.CreateComplianceDocumentRecordOnPosting = false;
			var line2 = (APInvoiceLine)invoice.Lines.AddNew();
			line2.AL_AT = TestObjectCreator.GSTFREE1.PK;
			line2.AL_JH = line1.AL_JH;
			line2.AL_AC = line1.AL_AC;
			line2.AL_OSExTaxAmount = 60m;

			Assert(!line1.CreateComplianceDocumentRecordOnPosting);
			Assert(line2.CreateComplianceDocumentRecordOnPosting);
			Assert(invoice.CanCreateComplianceDocument);

			line2.CreateComplianceDocumentRecordOnPosting = false;
			Assert(!invoice.CanCreateComplianceDocument);

			TestObjectCreator.AALSHI.CompanyData.OB_APCreateVATComplianceDocumentOnPosting = Constants.OrganisationCreateComplianceDocumentOnPostingTypes.RollupByCharge;
			Assert(invoice.CanCreateComplianceDocument);

			var line3 = (APInvoiceLine)invoice.Lines.AddNew();
			line3.AL_AC = TestObjectCreator.CommentChargeCode.PK;
			line3.AL_AT = ZGuid.Empty;
			Assert(!line3.AL_AT.IsValid);
			AssertEquals(line3.ChargeCode.AC_ChargeType, ChargeType.Comment);
			Assert(!invoice.LinesContainEmptyTaxID);
			Assert(invoice.CanCreateComplianceDocument);

			line3.AL_AC = TestObjectCreator.CC7.PK;
			line3.AL_AT = ZGuid.Empty;
			Assert(invoice.LinesContainEmptyTaxID);
			Assert(!invoice.CanCreateComplianceDocument);
		}

