			if (!invoicingBase.HasSupportedTransactionTypes)
			{
				Assert("Only transaction which support compliance document feature should run the UT.", true);
				return;
			}

			AccountingMasterFilesRegistry.Instance.EnableComplianceDocumentModule.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);
			var testObjectCreatorWithNewFactory = new TestObjectCreator(Factory.CreateNewFactory());
			testObjectCreatorWithNewFactory.AALSHI.CompanyData.OB_APCreateVATComplianceDocumentOnPosting = Constants.OrganisationCreateComplianceDocumentOnPostingTypes.RollupByCharge;
			testObjectCreatorWithNewFactory.AALSHI.CompanyData.OB_ARCreateVATComplianceDocumentOnPosting = Constants.OrganisationCreateComplianceDocumentOnPostingTypes.RollupByCharge;
			testObjectCreatorWithNewFactory.Factory.Save();

			TestObjectCreator.InitializeInvoicingBase(invoicingBase, "TEST001", TestObjectCreator.AALSHI, TestObjectCreator.OverheadChargeCode, TestObjectCreator.GST1);

			AssertEquals("Pre-condition", false, invoicingBase.IsInDatabase);
			AssertEquals(true, invoicingBase.Lines.Any());
			AssertEquals("Allow to create compliance document for new transaction", true, invoicingBase.CanCreateComplianceDocument);

			Factory.Save();
			var query = invoicingBase.GetComplianceDocumentByTransactionQuery_ForTestOnly(invoicingBase.PK);
