		public void TestTransformWorksForMultipleInvoicesInSameTransaction()
		{
			RevenueRecognitionCollection registryCollection = new RevenueRecognitionCollection();
			RevenueRecognition registryValue = registryCollection.AddNew();
			registryValue.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			registryValue.DirectionCode = Constants.FreightShipmentDirection.Code.All;
			registryValue.Mode = RevenueRecognitionLookups.ModeAdditionalCodes.All;
			registryValue.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction;
			registryValue.RunPreSaveValidation();

			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, registryCollection);

			AccountingConfigurationRegistry.Instance.PostIntoNextOpenPeriodWhenRecognitionPeriodClosed.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);
			AccountingConfigurationRegistry.Instance.CreateWIPOrAccrualWhenNoInvoicesPosted.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);
			AccountingConfigurationRegistry.Instance.BringForwardAgainstCreditor.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);
			AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsFinal.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, false);

			var testObjectCreator = new TestObjectCreator(Factory);

			var shipment = testObjectCreator.CreateShipment("S001001");
			var job = testObjectCreator.CreateJob(shipment, false, false);

			var jobCharge1 = testObjectCreator.CreateCharge(job, testObjectCreator.CC3, "test charge", testObjectCreator.AUD, 10, testObjectCreator.AALSHI
				, testObjectCreator.AUD, 0, testObjectCreator.ABIGAS);
			jobCharge1.JR_GE = job.JH_GE;

			var jobCharge2 = testObjectCreator.CreateCharge(job, testObjectCreator.CC3, "test charge", testObjectCreator.AUD, 20, testObjectCreator.AALSHI
				, testObjectCreator.AUD, 0, testObjectCreator.ABIGAS);
			jobCharge2.JR_GE = job.JH_GE;

			var jobCharge3 = testObjectCreator.CreateCharge(job, testObjectCreator.CC3, "test charge", testObjectCreator.AUD, 30, testObjectCreator.AALSHI
				, testObjectCreator.AUD, 0, testObjectCreator.ABIGAS);
			jobCharge3.JR_GE = job.JH_GE;

			Factory.Save();

			APInvoice invoice1 = (APInvoice)testObjectCreator.CreateInvoice(typeof(APInvoice), "001A", testObjectCreator.AUD, 1M, testObjectCreator.AALSHI);
			var invoice1Line = testObjectCreator.CreateInvoiceLine(invoice1, testObjectCreator.AUD, 1M, 10, job.JH_GB, false);
			invoice1Line.AL_AC = testObjectCreator.CC3.PK;
			invoice1Line.AL_JH = job.PK;
			invoice1Line.AL_GE = job.JH_GE;
			invoice1.SetContext(BusinessContext.ImportMultipleInvoicesWithSameTransformer);

			APInvoice invoice2 = (APInvoice)testObjectCreator.CreateInvoice(typeof(APInvoice), "001B", testObjectCreator.AUD, 1M, testObjectCreator.AALSHI);
			var invoice2Line = testObjectCreator.CreateInvoiceLine(invoice2, testObjectCreator.AUD, 1M, 20, job.JH_GB, false);
			invoice2Line.AL_AC = testObjectCreator.CC3.PK;
			invoice2Line.AL_JH = job.PK;
			invoice2Line.AL_GE = job.JH_GE;
			invoice2.SetContext(BusinessContext.ImportMultipleInvoicesWithSameTransformer);

			APInvoice invoice3 = (APInvoice)testObjectCreator.CreateInvoice(typeof(APInvoice), "001C", testObjectCreator.AUD, 1M, testObjectCreator.AALSHI);
			var invoice3Line = testObjectCreator.CreateInvoiceLine(invoice3, testObjectCreator.AUD, 1M, 30, job.JH_GB, false);
			invoice3Line.AL_AC = testObjectCreator.CC3.PK;
			invoice3Line.AL_JH = job.PK;
			invoice3Line.AL_GE = job.JH_GE;
			invoice3.SetContext(BusinessContext.ImportMultipleInvoicesWithSameTransformer);

			Factory.Save();

			AssertEquals("There should be 3 job charges, as there was no Sell amounts", 3, job.Charges.Count);
			foreach (JobCharge charge in job.Charges)
			{
				Assert("Charges linked to invoice line", charge.JR_AL_APLine != ZGuid.Empty);
				var apInvoiceLine = Factory.Load<AccTransactionLines>(charge.JR_AL_APLine);
				AssertNotEquals("Lines not accruals", TransactionLineTypes.Accrual, apInvoiceLine.AL_LineType);
				AssertEquals("Lines are costs", TransactionLineTypes.Cost, apInvoiceLine.AL_LineType);
				AssertNotEquals("Line amount not equal to 0", 0, apInvoiceLine.AL_LineAmount);
			}

			Assert("BusinessContext.ImportMultipleInvoicesWithSameTransformer should be removed after factory save", !invoice1.HasContext(BusinessContext.ImportMultipleInvoicesWithSameTransformer));
			Assert("BusinessContext.ImportMultipleInvoicesWithSameTransformer should be removed after factory save", !invoice2.HasContext(BusinessContext.ImportMultipleInvoicesWithSameTransformer));
			Assert("BusinessContext.ImportMultipleInvoicesWithSameTransformer should be removed after factory save", !invoice3.HasContext(BusinessContext.ImportMultipleInvoicesWithSameTransformer));
		}

