		public void TestTransformShouldNotCreateCurrencyExchangeRates()
		{
			//SET DEFAULT CURRENCY FOR COMPANY
			var newCompanyOrgHeader = TestObjectCreator.ABIGAS;
			newCompanyOrgHeader.CompanyData.OB_RX_NKAPDefltCurrency = "HKD";

			//CREATE SHIPMENT, JOB
			var shipment = TestObjectCreator.CreateShipment("S001001");
			var job = TestObjectCreator.CreateJob(shipment, false, false);

			Factory.Save();

			//CREATE INVOICE
			var invoice = TestObjectCreator.CreateAPInvoice<APInvoice>("10001", TestObjectCreator.AUD, 1m, 50m, 0m, 0m, 50m, 0m, 0m);
			invoice.AH_OH = newCompanyOrgHeader.PK;
			invoice.SubmittedFromInvoicingForm = true;
			invoice.SetContext(BusinessContext.ImportMultipleInvoicesWithSameTransformer);

			//CREATE INVOICE LINE
			var line = invoice.Lines[0];
			line.AL_AC = TestObjectCreator.CC3.PK;
			line.AL_JH = job.PK;

			//SET NEW COMPANY HEADER IN TRANSACTION LINE
			line.AL_OH = newCompanyOrgHeader.PK;

			//TEST WETHER THE JOB TRANSFORMER RUN YET
			AssertEquals("Should NOT have run JobChargeTransformer yet", false, invoice.HasJobChargeTransformerBeenRun);
			invoice.Factory.Save();
			AssertEquals("Should have run JobChargeTransformer", true, invoice.HasJobChargeTransformerBeenRun);

			//CURRENCY STILL SHOULD STAY THE SAME SINCE AFTER POSTING THERE SHOULD NOT BE COSTCURRENCY CHANGE WHEN ASSIGNING NEW COMPANY
			AssertNull("Assigning an Organization to the Job should NOT have created an ExchangeRate for the Company's Default Currency.", job.ExchangeRates[0]);
		}

