			chargeWithForeignCurrency.JR_OH_CostAccount = TestObjectCreator.AALSHI.PK;
			chargeWithForeignCurrency.JR_RX_NKCostCurrency = "USD";
			chargeWithForeignCurrency.JR_OSCostExRate = 1.5m;
