		public void TestImportJobChargesIntoInvoicePreservesWHTRate()
		{
			InvoicingBase testInvoicingBase = Factory.NewWithValidTestData(GetExpectedBusinessObjectType()) as InvoicingBase;
			if (testInvoicingBase.Lines.AllowNew && testInvoicingBase.AH_Ledger == LedgerTypes.AccountsPayable)
			{
				GlbCompany.CurrentCompany.GC_IsWHTRegistered = true;

				var whtRegisteredOrg = TestObjectCreator.CreateOrgHeader("WHTREG", true, false, false, true, false, false);
				var randomWhtRegisteredOrg = TestObjectCreator.CreateOrgHeader("RNDMORG", true, false, false, true, false, false);

				var wht1 = TestObjectCreator.WHT1;

				var frt = TestObjectCreator.FRT;
				frt.AC_AW_WithholdingTaxRate = wht1.PK;

				var jobCharges = new List<Charge>();
				Charge newCharge = Factory.NewWithValidTestData<Charge>();
				newCharge.JR_AC = frt.PK;
				newCharge.JR_OH_CostAccount = whtRegisteredOrg.PK;
				newCharge.JR_OSCostAmt = 100M;

				AssertEquals("Precondition: WHT rate", wht1.PK, newCharge.JR_AW_CostWHTRate);
				AssertEquals("Precondition: WHT amount", 5M, newCharge.JR_OSCostWHTAmt);

				jobCharges.Add(newCharge);

				testInvoicingBase.AH_OH = randomWhtRegisteredOrg.PK;

				InvoicingLineBase testInvoicingLineBase = (InvoicingLineBase)testInvoicingBase.Lines.AddNew();
				testInvoicingBase.ImportJobChargesIntoInvoice(jobCharges.ToArray<Charge>(), testInvoicingLineBase);
				AssertEquals("Withholding tax should not be set as invoice org is different to charge org", ZGuid.Empty, testInvoicingLineBase.AL_AW);

				testInvoicingLineBase.Delete();
				testInvoicingLineBase = (InvoicingLineBase)testInvoicingBase.Lines.AddNew();
				testInvoicingBase.AH_OH = whtRegisteredOrg.PK;
				testInvoicingBase.ImportJobChargesIntoInvoice(jobCharges.ToArray<Charge>(), testInvoicingLineBase);
				AssertEquals("Withholding tax should be set as invoice org is same as charge org", wht1.PK, testInvoicingLineBase.AL_AW);

				testInvoicingLineBase.Delete();
				testInvoicingLineBase = (InvoicingLineBase)testInvoicingBase.Lines.AddNew();
				whtRegisteredOrg.MiscServ.OM_APWHTApplicable = false;
				testInvoicingBase.ImportJobChargesIntoInvoice(jobCharges.ToArray<Charge>(), testInvoicingLineBase);
				AssertEquals("Withholding tax should not be set as invoice org is no longer AP WHT registered", ZGuid.Empty, testInvoicingLineBase.AL_AW);

				testInvoicingLineBase.Delete();
				testInvoicingLineBase = (InvoicingLineBase)testInvoicingBase.Lines.AddNew();
				whtRegisteredOrg.MiscServ.OM_APWHTApplicable = true;
				testInvoicingBase.ImportJobChargesIntoInvoice(jobCharges.ToArray<Charge>(), testInvoicingLineBase);
				AssertEquals("Setting org back to WHT registered, so withholding tax should be set again", wht1.PK, testInvoicingLineBase.AL_AW);

				testInvoicingLineBase.Delete();
				testInvoicingLineBase = (InvoicingLineBase)testInvoicingBase.Lines.AddNew();
				GlbCompany.CurrentCompany.GC_IsWHTRegistered = false;
				testInvoicingBase.ImportJobChargesIntoInvoice(jobCharges.ToArray<Charge>(), testInvoicingLineBase);
				AssertEquals("Withholding tax should not be set as company is no longer WHT registered", ZGuid.Empty, testInvoicingLineBase.AL_AW);
			}
			else
			{
				Assert(true);
			}
		}

		public void TestImportJobChargesIntoInvoiceRecalculatesGSTAmount()
		{
			OrgHeader newOrganisation = Factory.NewWithValidTestData<OrgHeader>();
			newOrganisation.CompanyData.SetAPTaxApplicable(true);
			AccTaxRate taxRate = TestObjectCreator.GST1;

			Job job1 = Factory.NewJobForTesting<Job>();
			ExchangeRate exchRate1 = job1.ExchangeRates.AddNew();
			exchRate1.JF_RX_NKRateCurrency = "SGD";
			exchRate1.JF_BaseRate = 1.2032m;

			Job job2 = Factory.NewJobForTesting<Job>();
			ExchangeRate exchRate2 = job2.ExchangeRates.AddNew();
			exchRate2.JF_RX_NKRateCurrency = "SGD";
			exchRate2.JF_BaseRate = 1.3032m;

			var jobCharges = new List<Charge>();
			Charge charge1 = Factory.NewWithValidTestData<Charge>();
			charge1.JR_JH = job1.PK;
			charge1.JR_OH_CostAccount = newOrganisation.PK;
			charge1.JR_RX_NKCostCurrency = "SGD";
			charge1.JR_OSCostExRate = 1.2032m;
			charge1.JR_LocalCostAmt = 126.75m;
			AssertEquals("charge1.JR_OSCostAmt", 152.51m, charge1.JR_OSCostAmt);
			charge1.JR_AT_CostGSTRate = taxRate.PK;
			AssertEquals("charge1.JR_OSCostGSTAmt_Calc", 15.25m, charge1.JR_OSCostGSTAmt_Calc);
			jobCharges.Add(charge1);

			Charge charge2 = Factory.NewWithValidTestData<Charge>();
			charge2.JR_JH = job2.PK;
			charge2.JR_OH_CostAccount = newOrganisation.PK;
			charge2.JR_RX_NKCostCurrency = "SGD";
			charge2.JR_OSCostExRate = 1.3032m;
			charge2.JR_LocalCostAmt = 126.75m;
			AssertEquals("charge2.JR_OSCostAmt", 165.18m, charge2.JR_OSCostAmt);
			charge2.JR_AT_CostGSTRate = taxRate.PK;
			AssertEquals("charge2.JR_OSCostGSTAmt_Calc", 16.52m, charge2.JR_OSCostGSTAmt_Calc);
			jobCharges.Add(charge2);

			InvoicingBase testInvoicingBase = Factory.NewWithValidTestData(GetExpectedBusinessObjectType()) as InvoicingBase;
			testInvoicingBase.AH_OH = newOrganisation.PK;
			testInvoicingBase.AH_Ledger = LedgerTypes.AccountsPayable;
			testInvoicingBase.AH_RX_NKTransactionCurrency = "SGD";
			testInvoicingBase.AH_PostedToEFT = ZBool.True;
			testInvoicingBase.AH_ExchangeRate = 1.2m;
			InvoicingLineBase testInvoicingLineBase = (InvoicingLineBase)testInvoicingBase.Lines.AddNew();
			testInvoicingLineBase.AL_JH = job1.PK; // To reproduce GUI-like behaviour. Otherwise Job will be unassigned on the existing InvoiceLine.
			testInvoicingBase.ImportJobChargesIntoInvoice(jobCharges.ToArray<Charge>(), testInvoicingLineBase);

			AssertEquals("Header ExchangeRate", 1.253219m, testInvoicingBase.AH_ExchangeRate);
			AssertEquals("Line ExchangeRate", 1.2032m, testInvoicingBase.Lines[0].AL_ExchangeRate);
			AssertEquals("Line ExchangeRate", 1.3032m, testInvoicingBase.Lines[1].AL_ExchangeRate);
			AssertEquals("The AL_OSTaxAmount should not be changed", 152.51m, testInvoicingBase.Lines[0].AL_OSExTaxAmount * -testInvoicingBase.Multiplier_ForTestOnly);
			AssertEquals("JR_OSCostGSTAmt_Calc should be recalculated using Line ExchangeRate assigned from Job ExchangeRate", 15.25m, testInvoicingBase.Lines[0].AL_OSTaxAmount * -testInvoicingBase.Multiplier_ForTestOnly);
			AssertEquals("The AL_OSTaxAmount should not be changed", 165.18m, testInvoicingBase.Lines[1].AL_OSExTaxAmount * -testInvoicingBase.Multiplier_ForTestOnly);
			AssertEquals("JR_OSCostGSTAmt_Calc should be recalculated using Line ExchangeRate assigned from Job ExchangeRate", 16.52m, testInvoicingBase.Lines[1].AL_OSTaxAmount * -testInvoicingBase.Multiplier_ForTestOnly);
		}

		public void TestGSTInclusiveAmountAfterImportJobChargesIntoInvoice()
		{
			OrgHeader newOrganisation = Factory.NewWithValidTestData<OrgHeader>();
			newOrganisation.CompanyData.SetARTaxApplicable(true);
			newOrganisation.CompanyData.SetAPTaxApplicable(true);

			AccTaxRate newTaxRate = Factory.NewWithValidTestData<AccTaxRate>();
			newTaxRate.SetRateNumerator_ForTestOnly(12);

			var jobCharges = new List<Charge>();
			Charge jobCharge1 = Factory.NewWithValidTestData<Charge>();
			jobCharge1.FillWithValidTestData();
			jobCharge1.JR_AT_CostGSTRate = newTaxRate.PK;
			jobCharge1.JR_OSCostAmt = 125;
			Charge jobCharge2 = Factory.NewWithValidTestData<Charge>();
			jobCharge2.FillWithValidTestData();
			jobCharge2.JR_AT_CostGSTRate = newTaxRate.PK;
			jobCharge2.JR_OSCostAmt = 325;
			jobCharges.Add(jobCharge1);
			jobCharges.Add(jobCharge2);

			GlbCompany.CurrentCompany.GC_IsGSTRegistered = true;
			AccountingConfigurationRegistry.Instance.ReceivableAllowUserToModifyGSTId.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, true);

			InvoicingBase testInvoicingBase = Factory.NewWithValidTestData(GetExpectedBusinessObjectType()) as InvoicingBase;
			testInvoicingBase.AH_OH = newOrganisation.PK;
			testInvoicingBase.AH_Ledger = LedgerTypes.AccountsPayable;
			testInvoicingBase.GSTInclusiveAmounts = false;
			InvoicingLineBase testInvoicingLineBase = (InvoicingLineBase)testInvoicingBase.Lines.AddNew();
			testInvoicingBase.ImportJobChargesIntoInvoice(jobCharges.ToArray<Charge>(), testInvoicingLineBase);
			Assert(!testInvoicingBase.GSTInclusiveAmountNeedUpdate);

			AssertEquals("The GSTInclusiveAmount should be the same as AL_OverseasTotal", testInvoicingBase.Lines[0].AL_OverseasTotal, testInvoicingBase.Lines[0].GSTInclusiveAmount);
			AssertEquals("The GSTInclusiveAmount should be the same as AL_OverseasTotal", testInvoicingBase.Lines[1].AL_OverseasTotal, testInvoicingBase.Lines[1].GSTInclusiveAmount);

			testInvoicingBase.Lines.RemoveAndDeleteAll();
			jobCharges.Clear();
			jobCharges.Add(jobCharge1);
			jobCharges.Add(jobCharge2);
			testInvoicingBase.GSTInclusiveAmounts = true;
			testInvoicingLineBase = (InvoicingLineBase)testInvoicingBase.Lines.AddNew();
			testInvoicingBase.ImportJobChargesIntoInvoice(jobCharges.ToArray<Charge>(), testInvoicingLineBase);
			Assert(!testInvoicingBase.GSTInclusiveAmountNeedUpdate);

			AssertEquals("The GSTInclusiveAmount should be the same as AL_OverseasTotal", testInvoicingBase.Lines[0].AL_OverseasTotal, testInvoicingBase.Lines[0].GSTInclusiveAmount);
			AssertEquals("The GSTInclusiveAmount should be the same as AL_OverseasTotal", testInvoicingBase.Lines[1].AL_OverseasTotal, testInvoicingBase.Lines[1].GSTInclusiveAmount);
		}

