		public void TestAccrualTaxDateMaintainedAfterImportAccrualsIntoInvoice()
		{
			var shipment = TestObjectCreator.CreateShipment("S001");

			var job = TestObjectCreator.CreateJob(shipment, false);

			var charge1 = TestObjectCreator.CreateCharge(job, osCostAmt: 1, creditor: TestObjectCreator.Creditor1);
			charge1.JR_AT_CostGSTRate = TestObjectCreator.GST1.PK;
			var charge2 = TestObjectCreator.CreateCharge(job, osCostAmt: 2, creditor: TestObjectCreator.Creditor1);
			charge2.JR_AT_CostGSTRate = TestObjectCreator.GST1.PK;
			var expectedDate = ZDate.Today.AddDays(-2);
			charge2.JR_CostTaxDate = expectedDate;
			Factory.Save();

			var invoice = TestObjectCreator.CreateInvoice(GetExpectedBusinessObjectType(), organisation: charge1.CostAccount);
			var line = TestObjectCreator.CreateInvoiceLine(invoice, 0);
			var accruals = new WIPAccrualCollection(Factory, new ZQuery(AccTransactionLinesSchema.PK, new ZGuid[] { charge1.JR_AL_APLine, charge2.JR_AL_APLine }) { OrderBy = AccTransactionLines.Schema.AL_LineAmount });
			accruals.Load();
			AssertEquals("Precondition: accruals.Count", 2, accruals.Count);
			AssertEquals("Precondition: charge1.JR_CostTaxDate", ZDate.Empty, charge1.JR_CostTaxDate);

			invoice.ImportAccrualsIntoInvoice(accruals.ToArray<BaseWIPAccrual>(), line);

			var index = 0;
			AssertEquals("AL_AT", TestObjectCreator.GST1.PK, invoice.Lines[index].AL_AT);
			AssertEquals("AL_TaxDate", ZDate.Today, invoice.Lines[index].AL_TaxDate);

			index++;
			AssertEquals("AL_AT", TestObjectCreator.GST1.PK, invoice.Lines[index].AL_AT);
			AssertEquals("AL_TaxDate", expectedDate, invoice.Lines[index].AL_TaxDate);
		}

		public void TestValidateAH_OSTotalAmountAfterImportJobChargesIntoInvoice()
		{
			var jobCharges = new List<Charge>();
			var shipment = TestObjectCreator.CreateShipment("S1");
			var job = TestObjectCreator.CreateJob(shipment);

			int multiplier;
			if (InvoicingBase is ARInvoice || InvoicingBase is APCreditNote)
			{
				multiplier = -1;
			}
			else
			{
				multiplier = 1;
			}
			var jobCharge = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, 100m * multiplier, 100m * multiplier);

			jobCharges.Add(jobCharge);
			Factory.Save();

			var invoice = GetNewBusinessObject() as InvoicingBase;
			invoice.AH_OH = TestObjectCreator.AALSHI.PK;
			var invoiceLine = (InvoicingLineBase)invoice.Lines.AddNew();
			invoice.ImportJobChargesIntoInvoice(jobCharges.ToArray<Charge>(), invoiceLine);

			AssertNotEquals("AH_OSTotalAmount is set after importing job charges into invoice", 0m, invoice.AH_OSTotal);
			AssertNoErrors("Validation runs after importing job charges into invoice (after header amount update suspension)", invoice.AH_OSTotalAmountInfo);
		}

		public void TestInvoiceTermsAndDaysNotReadOnlyWhenRegistryAllows()
		{
			if (InvoicingBase.AH_Ledger == LedgerTypes.AccountsReceivable)
			{
				SetupOrganisations();
				bool preTestAllowModifyInvoiceTerms = AccountingConfigurationRegistry.Instance.AllowModifyInvoiceTerm.GetFallBackValueAtAllLevels(EnvProxy.Instance.CurrentCompany.PK, EnvProxy.Instance.CurrentBranch.PK, EnvProxy.Instance.CurrentDepartment.PK);
				try
				{
					AccountingConfigurationRegistry.Instance.AllowModifyInvoiceTerm.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, true);
					Organisation.CompanyData.LoadARTermForAllInvoiceTypes().PY_InvoiceTerm = Constants.InvoiceTerms.FromInvoiceDate;
					Organisation.CompanyData.LoadARTermForAllInvoiceTypes().PY_InvoiceDays = (ZByte)7;
					Organisation.CompanyData.CreateOrLoadDisbursementARTerm().PY_InvoiceTerm = Constants.InvoiceTerms.CashOnDelivery;
					Organisation.CompanyData.CreateOrLoadDisbursementARTerm().PY_InvoiceDays = ZByte.Zero;
					InvoicingBase.AH_OH = base.Organisation.PK;
					Assert("Terms should not be readonly as registry is flagged to allow", !InvoicingBase.AH_InvoiceTermInfo.ReadOnly);
					Assert("Days should not be readonly as terms are not COD", !InvoicingBase.AH_InvoiceTermDaysInfo.ReadOnly);

					InvoicingBase.AH_InvoiceTerm = Constants.InvoiceTerms.CashOnDelivery;

					Assert("Terms should not be readonly as registry is flagged to allow", !InvoicingBase.AH_InvoiceTermInfo.ReadOnly);
					Assert("Days should be readonly as terms are COD", InvoicingBase.AH_InvoiceTermDaysInfo.ReadOnly);

					if (InvoicingBase.TransactionType_ForTestOnly == ZArchitecture.Core.TransactionTypes.Invoice)
					{
						InvoicingBase.AH_InvoiceTerm = Constants.InvoiceTerms.PaymentInAdvance;

						Assert("Terms should not be readonly as registry is flagged to allow", !InvoicingBase.AH_InvoiceTermInfo.ReadOnly);
						Assert("Days should be readonly as terms are PIA", InvoicingBase.AH_InvoiceTermDaysInfo.ReadOnly);
					}

					AccountingConfigurationRegistry.Instance.AllowModifyInvoiceTerm.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, false);

					InvoicingBase.AH_OH = ZGuid.Empty;
					InvoicingBase.AH_OH = Organisation.PK;

					Assert("Terms should be readonly as registry is not flagged to allow", InvoicingBase.AH_InvoiceTermInfo.ReadOnly);
					Assert("Days should be readonly as registry flags as not allowed", InvoicingBase.AH_InvoiceTermDaysInfo.ReadOnly);

					InvoicingBase.AH_TransactionCategory = InvoiceTypesList.Codes.DisbursementInvoice;

					Assert("Terms should still be readonly as registry is not flagged to allow", InvoicingBase.AH_InvoiceTermInfo.ReadOnly);
					Assert("Days should be readonly as registry flags as not allowed and terms are COD", InvoicingBase.AH_InvoiceTermDaysInfo.ReadOnly);
				}
				finally
				{
					AccountingConfigurationRegistry.Instance.AllowModifyInvoiceTerm.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, preTestAllowModifyInvoiceTerms);
				}
			}
			else
			{
				Assert(true);
			}
		}

		public void TestSetInvoiceDaysToZeroWhenOverriddenForCODAndPIA()
		{
			if (InvoicingBase.AH_Ledger == LedgerTypes.AccountsReceivable)
			{
				SetupOrganisations();
				bool preTestAllowModifyInvoiceTerms = AccountingConfigurationRegistry.Instance.AllowModifyInvoiceTerm.GetFallBackValueAtAllLevels(EnvProxy.Instance.CurrentCompany.PK, EnvProxy.Instance.CurrentBranch.PK, EnvProxy.Instance.CurrentDepartment.PK);
				try
				{
					AccountingConfigurationRegistry.Instance.AllowModifyInvoiceTerm.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, true);
					Organisation.CompanyData.LoadARTermForAllInvoiceTypes().PY_InvoiceTerm = Constants.InvoiceTerms.FromInvoiceDate;
					Organisation.CompanyData.LoadARTermForAllInvoiceTypes().PY_InvoiceDays = (ZByte)7;
					Organisation.CompanyData.CreateOrLoadDisbursementARTerm().PY_InvoiceTerm = Constants.InvoiceTerms.CashOnDelivery;
					Organisation.CompanyData.CreateOrLoadDisbursementARTerm().PY_InvoiceDays = ZByte.Zero;

					InvoicingBase.AH_OH = base.Organisation.PK;

					InvoicingBase.AH_InvoiceTerm = Constants.InvoiceTerms.CashOnDelivery;
					AssertEquals("Invoicingbase Term Days not zeroed on COD override", ZByte.Zero, InvoicingBase.AH_InvoiceTermDays);
					Assert("Term Days should also be readonly", InvoicingBase.AH_InvoiceTermDaysInfo.ReadOnly);

					if (InvoicingBase.TransactionType_ForTestOnly == ZArchitecture.Core.TransactionTypes.Invoice)
					{
						InvoicingBase.AH_InvoiceTermDays = (ZByte)7;
						InvoicingBase.AH_InvoiceTerm = Constants.InvoiceTerms.PaymentInAdvance;

						AssertEquals("Invoicingbase Term Days not zeroed on PIA override", ZByte.Zero, InvoicingBase.AH_InvoiceTermDays);
						Assert("Term Days should also be readonly", InvoicingBase.AH_InvoiceTermDaysInfo.ReadOnly);
					}
				}
				finally
				{
					AccountingConfigurationRegistry.Instance.AllowModifyInvoiceTerm.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, preTestAllowModifyInvoiceTerms);
				}
			}
			else
			{
				Assert(true);
			}
		}

