		public void TestDueDateReadOnlyStateWithSourceReference()
		{
			if (Header.AH_Ledger == LedgerTypes.AccountsReceivable
				&& (Header.AH_TransactionType == TransactionTypes.Invoice || Header.AH_TransactionType == TransactionTypes.CreditNote))
			{
				using (GlbCompany.CurrentCompany.TemporarilySetCountry(Constants.CountryCodes.Portugal))
				{
					Assert("PreCondition", Header.IsSourceReferenceEnabled);

					Header.AH_ComplianceSubType = string.Empty;
					Assert(!Header.IsSourceReferenceUsed);
					Assert(Header.AH_DueDateInfo.ReadOnly);

					Header.AH_ComplianceSubType = PortugalComplianceInfo.ComplianceSubTypeCodes.SBC;
					Assert(!Header.IsSourceReferenceUsed);
					Assert(Header.AH_DueDateInfo.ReadOnly);

					Header.AH_ComplianceSubType = PortugalComplianceInfo.ComplianceSubTypeCodes.LTX;
					Assert(Header.IsSourceReferenceUsed);
					Assert(!Header.AH_DueDateInfo.ReadOnly);

					Header.AH_ComplianceSubType = PortugalComplianceInfo.ComplianceSubTypeCodes.LCR;
					Assert(Header.IsSourceReferenceUsed);
					Assert(!Header.AH_DueDateInfo.ReadOnly);

					Header.AH_ComplianceSubType = PortugalComplianceInfo.ComplianceSubTypeCodes.TXM;
					Assert(Header.IsSourceReferenceUsed);
					Assert(!Header.AH_DueDateInfo.ReadOnly);

					Header.AH_ComplianceSubType = PortugalComplianceInfo.ComplianceSubTypeCodes.TCM;
					Assert(Header.IsSourceReferenceUsed);
					Assert(!Header.AH_DueDateInfo.ReadOnly);

					var newDueDate = ZDateTime.Today.AddDays(2);
					Header.AH_DueDate = newDueDate;
					Header.SourceReference = "FTM a";
					Factory.Save();

					AssertEquals(newDueDate, Header.AH_DueDate);

					var reloadedHeader = new BusinessObjectFactory().Load<InvoicingBase>(Header.PK);
					AssertEquals(newDueDate, reloadedHeader.AH_DueDate);
				}
			}
			else
			{
				Assert("test not applicable", true);
			}
		}

		public void TestValidateAL_OSTaxAmountWhenAH_ComplianceSubTypeChanged()
		{
			using (GlbCompany.CurrentCompany.TemporarilySetCountry(CountryCodes.Portugal))
			{
				InvoicingBase invoice = (InvoicingBase)Factory.New(typeof(ARInvoice));
				invoice.AH_OH = TestObjectCreator.AALSHI.PK;

				InvoicingLineBase line = (InvoicingLineBase)invoice.Lines.AddNew();
				line.AL_AC = TestObjectCreator.CC1.PK;
				line.AL_AT = TestObjectCreator.GST1.PK;
				line.AL_OSExTaxAmount = 10m;
				line.AL_OSTaxAmount = 10m;
				line.TransactionHeader.AH_TransactionType = TransactionTypes.AdjustmentNote;
				invoice.AH_ComplianceSubType = PortugalComplianceInfo.ComplianceSubTypeCodes.TCR;
				invoice.AH_Ledger = LedgerTypes.AccountsReceivable;

				InvoicingLineBaseValidation validation = new InvoicingLineBaseValidation(invoice.Lines[0]);
				validation.ValidateAL_OSTaxAmount();
				AssertNoError(line.AL_OSTaxAmountInfo, InvoicingLineBaseValidation.TaxAmountRangeWarning_ForTestOnly);
				AssertHasWarning(line.AL_OSTaxAmountInfo, InvoicingLineBaseValidation.TaxAmountRangeWarning_ForTestOnly);

				line.TransactionHeader.AH_TransactionType = TransactionTypes.Invoice;
				validation.ValidateAL_OSTaxAmount();
				AssertHasError(line.AL_OSTaxAmountInfo, InvoicingLineBaseValidation.TaxAmountRangeWarning_ForTestOnly);
				AssertNoWarning(line.AL_OSTaxAmountInfo, InvoicingLineBaseValidation.TaxAmountRangeWarning_ForTestOnly);

				invoice.AH_ComplianceSubType = PortugalComplianceInfo.ComplianceSubTypeCodes.LCD;
				AssertNoError(line.AL_OSTaxAmountInfo, InvoicingLineBaseValidation.TaxAmountRangeWarning_ForTestOnly);
				AssertHasWarning(line.AL_OSTaxAmountInfo, InvoicingLineBaseValidation.TaxAmountRangeWarning_ForTestOnly);
			}
		}

