		public void TestPreventDueDateRecalculationOnOverrideInvoiceReference()
		{
			ZDateTime prevDueDate = InvoicingBase.AH_DueDate;
			ZDateTime currentDate = ZDateTime.Now;
			InvoicingBase.AH_InvoiceTerm = Constants.InvoiceTerms.FromInvoiceDate;
			InvoicingBase.AH_InvoiceDate = currentDate.AddDays(1);
			AssertNotEquals("Due Date updated based on Invoice Terms rules", prevDueDate, InvoicingBase.AH_DueDate);

			InvoicingBase.Factory.SetContext(BusinessContext.OverrideInvoiceReference);

			prevDueDate = InvoicingBase.AH_DueDate;
			InvoicingBase.AH_InvoiceDate = currentDate.AddDays(2);
			AssertEquals("Due Date not updated on Override Invoice Reference Context", prevDueDate, InvoicingBase.AH_DueDate);
		}

