		public void TestIsPartiallyOrFullyPaid()
		{
			InvoicingBase.AH_LocalExTaxAmount = 0;
			InvoicingBase.AH_LocalTaxAmount = 0;
			InvoicingBase.AH_LocalOutstandingAmount = 0;
			AssertEquals(false, InvoicingBase.IsPartiallyOrFullyPaid);

			InvoicingBase.AH_LocalExTaxAmount = 100;
			InvoicingBase.AH_LocalTaxAmount = 10;
			InvoicingBase.AH_LocalOutstandingAmount = 110;
			AssertEquals(false, InvoicingBase.IsPartiallyOrFullyPaid);

			InvoicingBase.AH_LocalExTaxAmount = 100;
			InvoicingBase.AH_LocalTaxAmount = 0;
			InvoicingBase.AH_LocalOutstandingAmount = 100;
			AssertEquals(false, InvoicingBase.IsPartiallyOrFullyPaid);

			InvoicingBase.AH_LocalExTaxAmount = 100;
			InvoicingBase.AH_LocalTaxAmount = 0;
			InvoicingBase.AH_LocalOutstandingAmount = 10;
			AssertEquals(true, InvoicingBase.IsPartiallyOrFullyPaid);

			InvoicingBase.AH_LocalExTaxAmount = 100;
			InvoicingBase.AH_LocalTaxAmount = 0;
			InvoicingBase.AH_LocalOutstandingAmount = 0;
			AssertEquals(true, InvoicingBase.IsPartiallyOrFullyPaid);

			InvoicingBase.AH_LocalExTaxAmount = 100;
			InvoicingBase.AH_LocalTaxAmount = 0;
			InvoicingBase.AH_LocalTaxAmountOtherTaxes = 12 * InvoicingBase.Multiplier_ForTestOnly;
			InvoicingBase.AH_LocalOutstandingAmount = 0;
			AssertEquals(true, InvoicingBase.IsPartiallyOrFullyPaid);

			InvoicingBase.AH_LocalExTaxAmount = 100;
			InvoicingBase.AH_LocalTaxAmount = 0;
			InvoicingBase.AH_LocalTaxAmountOtherTaxes = 12 * InvoicingBase.Multiplier_ForTestOnly;
			InvoicingBase.AH_LocalOutstandingAmount = 112;
			AssertEquals(false, InvoicingBase.IsPartiallyOrFullyPaid);

			InvoicingBase.AH_LocalExTaxAmount = 100;
			InvoicingBase.AH_LocalTaxAmount = 0;
			InvoicingBase.AH_LocalTaxAmountOtherTaxes = 15 * InvoicingBase.Multiplier_ForTestOnly;
			InvoicingBase.AH_LocalOutstandingAmount = 112;
			AssertEquals(true, InvoicingBase.IsPartiallyOrFullyPaid);
		}

