		public void TestRemoveNotRequiredJobsAndChargesFromCostsAndLinesDoesNotDeleteChargesUsedForApportionment()
		{
			InvoicingBase invoice = (InvoicingBase)Factory.New(InvoicingBase.GetType());
			JobConsolCost cost = invoice.ConsolCosting.ConsolCosts.AddNew();

			Job job1, job2, job3;
			job1 = Factory.NewJobForTesting<Job>();
			job2 = Factory.NewJobForTesting<Job>();
			job3 = Factory.NewJobForTesting<Job>();
			job2.JH_JH_ParentJob = job1.PK;
			job3.JH_JH_ParentJob = job1.PK;

			cost.JobsWithMutexes.AddRange(new Job[] { job1, job2, job3 });
			Charge charge1 = job1.Charges.AddNew();
			Charge charge2 = job2.Charges.AddNew();
			Charge charge3 = job3.Charges.AddNew();

			charge1.JR_E6 = cost.PK;
			charge2.JR_E6 = cost.PK;
			charge3.JR_E6 = cost.PK;

			charge2.JR_OSCostAmt = 100m;

			InvoicingLineBase line = ((InvoicingLineBase)invoice.Lines.AddNew());
			line.AL_JH = job2.PK;

			job1.Charges.Add(charge2);
			job1.Charges.Add(charge3);

			invoice.RemoveNotRequiredJobsAndChargesFromCostsAndLines();
			AssertEquals(true, charge1.IsDeleted);
			AssertEquals(false, charge2.IsDeleted);
			AssertEquals(true, charge3.IsDeleted);
		}

