			Factory.Save();

			InvoicingBase invoice = (InvoicingBase)Factory.New(InvoicingBase.GetType());
			JobConsolCost cost = invoice.ConsolCosting.ConsolCosts.AddNew();

			Job job1, job2, job3;
			job1 = Factory.NewJobForTesting<Job>();
			job2 = Factory.NewJobForTesting<Job>();
			job3 = Factory.NewJobForTesting<Job>();

			Charge charge1 = job1.Charges.AddNew();
			Charge charge2 = job2.Charges.AddNew();
			Charge charge3 = job3.Charges.AddNew();
			Charge dbCharge = dbJob.Charges.AddNew();

			InvoicingLineBase line = ((InvoicingLineBase)invoice.Lines.AddNew());
			line.AL_JH = dbJob.PK;
			line.AL_JH = job1.PK;
			line.AL_JH = job2.PK;
			line.AL_JH = job3.PK;

			invoice.RemoveNotRequiredJobsAndChargesFromCostsAndLines();

			AssertEquals(false, dbJob.IsDeleted);
			AssertEquals(true, job1.IsDeleted);
			AssertEquals(true, job2.IsDeleted);
			AssertEquals(false, job3.IsDeleted);

			AssertEquals(false, dbCharge.IsDeleted);
			AssertEquals(true, charge1.IsDeleted);
			AssertEquals(true, charge2.IsDeleted);
			AssertEquals(false, charge3.IsDeleted);
		}

		public void TestRemoveNotRequiredJobsAndChargesFromCostsAndLines_ActivateJobs()
		{
			var shipment = TestObjectCreator.CreateShipment("S0001", true);
			var loader = new JobHeader.Loader(shipment);
			var job = loader.TryCreateWithMutex(GlbBranch.CurrentBranch);
			AssertNotNull(job);
			var jobMutex = JobHeader.GetMutex_ForTestOnly(shipment.PK);
			AssertNotNull(jobMutex);
			Factory.Save();

			job.MarkAsInactive();
			Factory.Save();

			job = loader.TryCreateWithMutex(GlbBranch.CurrentBranch);

			var invoice = (InvoicingBase)Factory.New(InvoicingBase.GetType());
			var cost = invoice.ConsolCosting.ConsolCosts.AddNew();
			cost.JobsWithMutexes.Add((Job)job);

			Assert(!job.IsCancelled);
			Assert(jobMutex.IsLocked);

			invoice.RemoveNotRequiredJobsAndChargesFromCostsAndLines();

			Assert(job.IsCancelled);
			Assert(!jobMutex.IsLocked);
		}

		public void TestRemoveJobsCreatedButNotRequiredDoesntDeletePostedChargesOnSubShipments()
		{
			ForwardingConsol consol = Factory.New<ForwardingConsol>();
			consol.JK_ConsolMode = "BCN";
			Factory.Save();
			ForwardingShipment shipment1 = TestObjectCreator.CreateShipment("SHIPMENT1", "AUSYD", "GBLON", consol);
			shipment1.ConsignorDocumentaryAddress.OrganisationPK = TestObjectCreator.ABIGAS.PK;
			TestObjectCreator.ABIGAS.CompanyData.OB_ARBuyersConsolInvoicingStyle = "MAS";

			//Set Consignor to be Organisation with Buyers Consol configuration as include sub jobs (OB_ARBuyersConsolInvoicingStyle = "MAS"

			ForwardingShipment shipment2 = TestObjectCreator.CreateShipment("SHIPMENT1", "AUSYD", "GBLON", consol);
			shipment1.JS_ShipmentType = Core.Constants.ShipmentTypes.AssemblyMaster;
			shipment1.JS_PackingMode = "BCN";
			shipment1.JS_UniqueConsignRef = "Master";
			shipment2.JS_JS_ColoadMasterShipment = shipment1.PK;
			Job subShipmentJob = TestObjectCreator.CreateJob(shipment2, false, true);
			subShipmentJob.JH_GB = GlbBranch.CurrentBranch.PK;
			Charge subShipmentCharge = subShipmentJob.Charges.AddNew();
			subShipmentCharge.JR_AC = TestObjectCreator.CC1.PK;
			subShipmentCharge.JR_GB = GlbBranch.CurrentBranch.PK;
			subShipmentCharge.JR_OH_SellAccount = TestObjectCreator.Debtor.PK;
			subShipmentCharge.JR_OSSellAmt = 100m;
			subShipmentCharge.JR_OSCostAmt = 0m;

			ARInvoice invoice = Factory.NewWithValidTestData<ARInvoice>();
			invoice.AH_OH = TestObjectCreator.Debtor.PK;
			ARInvoiceLine invoiceLine = (ARInvoiceLine)invoice.Lines.AddNew();
			invoiceLine.GenericCharge = TestObjectCreator.CC1.PK;
			invoiceLine.AL_OSExTaxAmount = 100m;
			subShipmentCharge.JR_AL_ARLine = invoiceLine.PK;

			Factory.Save();

			BusinessObjectFactory newFactory = new BusinessObjectFactory();
			try
			{
				InvoicingBase invoice1 = (InvoicingBase)newFactory.New(InvoicingBase.GetType());
				invoice1.AH_OH = TestObjectCreator.Creditor1.PK;
				invoice1.SubmittedFromInvoicingForm = true;
				if (invoice1 is APInvoice || invoice1 is APCreditNote)
				{
					JobConsolCost cost = invoice1.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
					cost.E6_ApportionToRelatedShipments = true;
					cost.E6_AC_ChargeCode = TestObjectCreator.CC1.PK;
					cost.E6_OSCostAmount = 10m;
					AssertEquals("Should have 2 shipments to apportion to", 2, cost.ShipmentsToApportion.Length);
					ApportionSplitCharge invoiceMasterShipmentCharge = cost.ApportionmentCharges[0].JR_JobNumber == shipment1.JS_UniqueConsignRef ? cost.ApportionmentCharges[0] : cost.ApportionmentCharges[1];
					ApportionSplitCharge invoiceSubShipmentCharge = cost.ApportionmentCharges[1].PK != invoiceMasterShipmentCharge.PK ? cost.ApportionmentCharges[1] : cost.ApportionmentCharges[0];

					invoiceMasterShipmentCharge.JR_IsUsedForApportionment = false;
					invoiceSubShipmentCharge.JR_IsUsedForApportionment = true;

					cost.E6_ApportionmentMethod = "SHP";

					invoiceMasterShipmentCharge.JR_OSCostAmt = 0m;
					invoiceSubShipmentCharge.JR_OSCostAmt = 10m;

					invoice1.ImportAllApportionmentsFromCosting();
					AssertEquals("Should be one line in the invoice", 1, invoice1.Lines.Count);
					AssertEquals("Invoice Line should be for sub-shipment", subShipmentJob.PK, invoice1.Lines[0].Job.PK);
					invoice1.AH_TransactionNum = "0000001";

					invoice1.Factory.Save();

					Assert("Invoice should have posted", invoice.IsInDatabase);
				}
				else
				{
					Assert(true);
				}
			}
			finally
			{
				ZQuery allFactoryJobs = new ZQuery();
				allFactoryJobs.FetchOnlyFromLocalCache = true;
				Job[] jobsThatNeedToBeDisposed = newFactory.Load<Job>(allFactoryJobs);
				foreach (Job job in jobsThatNeedToBeDisposed)
				{
					job.Dispose();
				}
			}
		}

