		public void TestHasDisbursementCharges()
		{
			AccChargeCode mRGChargeCode = Factory.New<AccChargeCode>();
			mRGChargeCode.AC_ChargeType = Constants.ChargeType.Margin;

			AccChargeCode rEVChargeCode = Factory.New<AccChargeCode>();
			rEVChargeCode.AC_ChargeType = Constants.ChargeType.Revenue;

			AccChargeCode dISChargeCode = Factory.New<AccChargeCode>();
			dISChargeCode.AC_ChargeType = Constants.ChargeType.Disbursement;

			InvoicingLineBase line1 = (InvoicingLineBase)InvoicingBase.Lines.AddNew();
			InvoicingLineBase line2 = (InvoicingLineBase)InvoicingBase.Lines.AddNew();
			InvoicingLineBase line3 = (InvoicingLineBase)InvoicingBase.Lines.AddNew();

			line1.AL_AC = mRGChargeCode.PK;
			AssertEquals("Has Disbursement Charges", false, InvoicingBase.HasDisbursementCharges(null));

			line2.AL_AC = rEVChargeCode.PK;
			AssertEquals("Has Disbursement Charges", false, InvoicingBase.HasDisbursementCharges(null));

			line3.AL_AC = dISChargeCode.PK;
			AssertEquals("Has Disbursement Charges", true, InvoicingBase.HasDisbursementCharges(null));

			InvoicingBase.Lines.RemoveAndDelete(line1);
			AssertEquals("Has Disbursement Charges", true, InvoicingBase.HasDisbursementCharges(null));

			InvoicingBase.Lines.RemoveAndDelete(line3);
			AssertEquals("Has Disbursement Charges", false, InvoicingBase.HasDisbursementCharges(null));
		}

