		public void TestFullyPayInvoiceWhenTotalIsZero()
		{
			InvoicingBase invoice = (InvoicingBase)Factory.New(GetExpectedBusinessObjectType());
			InvoicingLineBase line1 = (InvoicingLineBase)invoice.Lines.AddNew();
			InvoicingLineBase line2 = (InvoicingLineBase)invoice.Lines.AddNew();

			line1.AL_OSExTaxAmount = 20m;
			line2.AL_OSExTaxAmount = -20m;
			line1.AL_AG = TestObjectCreator.GLHeader1.PK;
			line2.AL_AG = TestObjectCreator.GLHeader1.PK;
			ZDateTime priorDate = PeriodManagementTestHelper.PreviousGLClosedPeriod.AM_EndDate;
			invoice.AH_InvoiceDate = priorDate;
			invoice.AH_TransactionNum = TestObjectCreator.GetRandomString(10);

			AssertEquals("Precondition - Total should be zero", 0m, invoice.AH_OSTotalAmount);
			AssertEquals("Precondition - Total should be zero", 0m, invoice.AH_InvoiceAmount);
			AssertEquals("Precondition - Total should be zero", 0m, invoice.AH_OSExTaxAmount);
			Assert("Precondition - Fully Paid Date should be empty", invoice.AH_FullyPaidDate.IsEmpty);

			Factory.Save();

			AssertEquals("Fully Paid Date should be filled on saving to the date of the invoice when", priorDate, invoice.AH_FullyPaidDate);
		}

		public void TestFullyPayInvoiceWhenTotalIsZeroFullyPaidDateIsNotEmpty()
		{
			InvoicingBase invoice = (InvoicingBase)Factory.New(GetExpectedBusinessObjectType());
			InvoicingLineBase line1 = (InvoicingLineBase)invoice.Lines.AddNew();
			InvoicingLineBase line2 = (InvoicingLineBase)invoice.Lines.AddNew();

			line1.AL_OSExTaxAmount = 20m;
			line2.AL_OSExTaxAmount = -20m;
			line1.AL_AG = TestObjectCreator.GLHeader1.PK;
			line2.AL_AG = TestObjectCreator.GLHeader1.PK;
			ZDateTime priorDate = PeriodManagementTestHelper.PreviousGLClosedPeriod.AM_EndDate;
			invoice.AH_InvoiceDate = ZDateTime.Today;
			invoice.AH_TransactionNum = TestObjectCreator.GetRandomString(10);
			invoice.AH_FullyPaidDate = priorDate;

			AssertEquals("Precondition - Total should be zero", 0m, invoice.AH_OSTotalAmount);
			AssertEquals("Precondition - Total should be zero", 0m, invoice.AH_InvoiceAmount);
			AssertEquals("Precondition - Total should be zero", 0m, invoice.AH_OSExTaxAmount);
			AssertEquals("Precondition - Fully Paid Date should not be empty", priorDate, invoice.AH_FullyPaidDate);
			AssertNotEquals("Precondition - Fully Paid Date should not be equal Invoice Date", invoice.AH_InvoiceDate, invoice.AH_FullyPaidDate);

			Factory.Save();

			AssertEquals("Fully Paid Date should be unchanged on saving.", priorDate, invoice.AH_FullyPaidDate);
		}

		public void TestFullyPayInvoiceWhenTotalIsNonZero()
		{
			InvoicingBase invoice = (InvoicingBase)Factory.New(GetExpectedBusinessObjectType());
			InvoicingLineBase line1 = (InvoicingLineBase)invoice.Lines.AddNew();
			InvoicingLineBase line2 = (InvoicingLineBase)invoice.Lines.AddNew();

			line1.AL_OSExTaxAmount = 20m;
			line2.AL_OSExTaxAmount = -10m;
			line1.AL_AG = TestObjectCreator.GLHeader1.PK;
			line2.AL_AG = TestObjectCreator.GLHeader1.PK;
			ZDateTime priorDate = PeriodManagementTestHelper.PreviousGLClosedPeriod.AM_EndDate;
			invoice.AH_InvoiceDate = priorDate;
			invoice.AH_TransactionNum = TestObjectCreator.GetRandomString(10);

			Assert("Precondition - Total should not be zero", invoice.AH_OSTotalAmount != 0m);
			Assert("Precondition - Total should not be zero", invoice.AH_InvoiceAmount != 0m);
			Assert("Precondition - Fully Paid Date should be empty", invoice.AH_FullyPaidDate.IsEmpty);
			Assert("Precondition - InvoiceDate should not be empty", !invoice.AH_InvoiceDate.IsEmpty);

			Factory.Save();

			Assert("Fully Paid Date should be empty since this is a newly created invoice with non-zero value", invoice.AH_FullyPaidDate.IsEmpty);
		}

