		public void TestIsPostedToCASS()
		{
			InvoicingBase invoice1 = (InvoicingBase)Factory.New(GetExpectedBusinessObjectType());
			InvoicingBase invoice2 = (InvoicingBase)Factory.New(GetExpectedBusinessObjectType());
			invoice1.FillWithValidTestData();
			invoice2.FillWithValidTestData();

			invoice1.IsPostedToCASSOrSaved = true;
			AssertEquals("IsPostedToCASS should be false", true, invoice1.IsPostedToCASSOrSaved);

			invoice1.IsPostedToCASSOrSaved = false;
			AssertEquals("IsPostedToCASS should be true", false, invoice1.IsPostedToCASSOrSaved);

			Factory.Save();
			AssertEquals("should be in database", true, invoice2.IsInDatabase);
			AssertEquals("if in database, IsPostedToCASS should default to true", true, invoice2.IsPostedToCASSOrSaved);
		}

		public void TestSetWHTReadOnlyState()
		{
			InvoicingBaseWith3Lines.SetWHTReadOnlyState();
			foreach (InvoicingLineBase line in InvoicingBaseWith3Lines.Lines)
			{
				Assert(line.AL_AWInfo.ReadOnly);
			}

			OrgHeader orgHeader = Factory.NewWithValidTestData<OrgHeader>();
			OrgMiscServ orgMiscServ = Factory.New<OrgMiscServ>();
			orgMiscServ.OM_OH = orgHeader.PK;
			GlbCompany.CurrentCompany.GC_IsWHTRegistered = true;

			if (InvoicingBaseWith3Lines.AH_Ledger == LedgerTypes.AccountsReceivable)
			{
				orgHeader.MiscServ.OM_ARWHTApplicable = true;
				AccountingConfigurationRegistry.Instance.ReceivableAllowUserToModifyWHTId.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, true);
			}
			else
			{
				orgHeader.MiscServ.OM_APWHTApplicable = true;
				AccountingConfigurationRegistry.Instance.PayableAllowUserToModifyWHTId.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, true);
			}
			InvoicingBaseWith3Lines.AH_OH = orgHeader.PK;
			InvoicingBaseWith3Lines.SetWHTReadOnlyState();
			foreach (InvoicingLineBase line in InvoicingBaseWith3Lines.Lines)
			{
				Assert(!line.AL_AWInfo.ReadOnly);
			}
		}

		public void TestWHTTax_Calculation()
		{
			if (InvoicingBase.GetType() != typeof(TransactionPendingAllocation))
			{
				GlbCompany.CurrentCompany.GC_IsReciprocal = true;
				InvoicingBase.Lines.RemoveAll();

				InvoicingBase.AH_RX_NKTransactionCurrency = "USD";
				InvoicingBase.AH_ExchangeRate = 566.33M;

				var withholdingTax = TestObjectCreator.WHT1;
				withholdingTax.AW_Rate = 8.5;

				var line = (InvoicingLineBase)InvoicingBase.Lines.AddNew();
				line.AL_AG = TestObjectCreator.GLHeader1.PK;
				line.AL_OSExTaxAmount = 100.01M;
				line.AL_AW = withholdingTax.PK;

				AssertEquals("Precondition:", 56638.66M, line.AL_LocalExTaxAmount);
				AssertEquals("Local Withholding amount calculated from applying WHT rate on local ex tax amount", 4814.29M, line.AL_LocalWHTAmount);
				AssertEquals("OS withholding amount calculated from applying exchange rate on local WHT amount", 8.50M, line.AL_OSWHTAmount);
			}
			else
			{
				Assert("Not applicable", true);
			}
		}

		public void TestWHTTax_LocalCurrencyInvoice()
		{
			if (InvoicingBase.GetType() != typeof(TransactionPendingAllocation))
			{
				InvoicingBase invoice = InvoicingBase;

				var line1 = (InvoicingLineBase)invoice.Lines.AddNew();
				line1.AL_AG = TestObjectCreator.GLHeader1.PK;
				line1.AL_OSExTaxAmount = 100M;
				line1.AL_AW = TestObjectCreator.WHT1.PK; //OS ex tax amount set first then WHT rate is set

				AssertEquals("line1 WHT OS amount", 5M, line1.AL_OSWHTAmount);
				AssertEquals("line1 WHT Local amount", 5M, line1.AL_LocalWHTAmount);

				AssertEquals("Header WHT OS amount with 1 line", 5M, invoice.AH_OSWHTAmount);
				AssertEquals("Header WHT Local amount with 1 line", 5M, invoice.AH_LocalWHTAmount);

				var line2 = (InvoicingLineBase)invoice.Lines.AddNew();
				line2.AL_AG = TestObjectCreator.GLHeader1.PK;
				line2.AL_AW = TestObjectCreator.WHT1.PK;
				line2.AL_OSExTaxAmount = 200M; //WHT rate is set first then OS ex tax amount is set

				AssertEquals("line2 WHT OS amount", 10M, line2.AL_OSWHTAmount);
				AssertEquals("line2 WHT Local amount", 10M, line2.AL_LocalWHTAmount);

				AssertEquals("Header WHT OS amount with 2 lines", 15M, invoice.AH_OSWHTAmount);
				AssertEquals("Header WHT Local amount with 2 lines", 15M, invoice.AH_LocalWHTAmount);

				line2.AL_RX_NKTransactionCurrency = "USD";
				line2.AL_ExchangeRate = 2M;

				AssertEquals("line2 WHT OS amount", 10M, line2.AL_OSWHTAmount);
				AssertEquals("line2 WHT Local amount", 5M, line2.AL_LocalWHTAmount);

				AssertEquals("Header WHT Local amount with 2 lines", 10M, invoice.AH_LocalWHTAmount);
			}
			else
			{
				Assert("Not applicable", true);
			}
		}

		public void TestWHTTax_ForeignCurrencyInvoice()
		{
			var type = GetExpectedBusinessObjectType();
			if (type != typeof(TransactionPendingAllocation))
			{
				var factory1 = new BusinessObjectFactory();
				InvoicingBase invoice = (InvoicingBase)factory1.NewWithValidTestData(type);
				invoice.AH_RX_NKTransactionCurrency = "USD";
				invoice.AH_ExchangeRate = 0.5M;

				var line1 = (InvoicingLineBase)invoice.Lines.AddNew();
				line1.AL_AG = TestObjectCreator.GLHeader1.PK;
				line1.AL_OSExTaxAmount = 100M;
				line1.AL_AW = TestObjectCreator.WHT1.PK; //OS ex tax amount set first then WHT rate is set

				AssertEquals("line1 WHT OS amount", 5M, line1.AL_OSWHTAmount);
				AssertEquals("line1 WHT Local amount", 10M, line1.AL_LocalWHTAmount);

				AssertEquals("Header WHT OS amount with 1 line", 5M, invoice.AH_OSWHTAmount);
				AssertEquals("Header WHT Local amount with 1 line", 10M, invoice.AH_LocalWHTAmount);

				var line2 = (InvoicingLineBase)invoice.Lines.AddNew();
				line2.AL_AG = TestObjectCreator.GLHeader1.PK;
				line2.AL_AW = TestObjectCreator.WHT1.PK;
				line2.AL_OSExTaxAmount = 200M; //WHT rate is set first then OS ex tax amount is set

				AssertEquals("line2 WHT OS amount", 10M, line2.AL_OSWHTAmount);
				AssertEquals("line2 WHT Local amount", 20M, line2.AL_LocalWHTAmount);

				AssertEquals("Header WHT OS amount with 2 lines", 15M, invoice.AH_OSWHTAmount);
				AssertEquals("Header WHT Local amount with 2 lines", 30M, invoice.AH_LocalWHTAmount);

				factory1.Save();

				var factory2 = new BusinessObjectFactory();
				var invoiceInFactory2 = factory2.Load<InvoicingBase>(invoice.PK);

				AssertEquals("line1 WHT OS amount - calculated correctly", 5M, invoiceInFactory2.Lines[0].AL_OSWHTAmount);
				AssertEquals("line2 WHT OS amount - calculated correctly", 10M, invoiceInFactory2.Lines[1].AL_OSWHTAmount);

				AssertEquals("Header WHT OS amount with 2 lines", 15M, invoiceInFactory2.AH_OSWHTAmount);
				AssertEquals("Header WHT Local amount with 2 lines", 30M, invoiceInFactory2.AH_LocalWHTAmount);
			}
			else
			{
				Assert("Not applicable", true);
			}
		}

		public void TestReleaseMutexWhenPosted()
		{
			var forwardingShipment = TestObjectCreator.CreateShipment("S00001234");
			Factory.Save();

			var aPInvoice = Factory.NewWithValidTestData(typeof(APInvoice)) as APInvoice;
			using (var job = TestObjectCreator.CreateJob(forwardingShipment))
			{
				aPInvoice.Lines.AddNew();
				aPInvoice.Lines[0].AL_JH = job.PK;
				aPInvoice.Lines[0].AL_AG = TestObjectCreator.GLHeader1.PK;
				TestObjectCreator.CreateJobCharge(aPInvoice.Lines[0], job, TestObjectCreator.CC1, TestObjectCreator.AUD);

				using (var mutex = new ZGlobalMutex(MutexIDs.JobBeingCreatedForShipment, (forwardingShipment.PK + "_" + GlbCompany.CurrentCompany.GC_Code)))
				{
					Assert(mutex.IsLocked);
					Factory.Save();
					Assert(!mutex.IsLocked);
				}
			}
		}

		public override void TestGenerateReverseTransaction()
		{
			int reverseTransactionMultiplier = InvoicingBase.InvertSignsOfOriginalTransactionOnReversing_ForTestOnly ? -1 : 1;
			InvoicingBase.AH_RX_NKTransactionCurrency = ForeignCurrency.RX_Code;
			InvoicingBase.AH_ExchangeRate = 0.4M;
			InvoicingBase.Lines.RemoveAll();

			InvoicingLineBase line1 = (InvoicingLineBase)InvoicingBase.Lines.AddNew();
			line1.AL_AT = TestObjectCreator.GST1WithDates.PK;
			line1.AL_TaxDate = TestObjectCreator.GST1WithDates_DateWithNoRate;
			line1.AL_TaxRateNumerator = 4;
			line1.AL_TaxRateDenominator = 7;
			line1.AL_TaxExtraRateNumerator = 14;
			line1.AL_TaxExtraRateDenominator = 17;
			line1.AL_ExchangeRate = 0.4M;
			line1.AL_OSExTaxAmount = 22M;
			line1.AL_OSTaxAmount = 2M;
			line1.AL_LocalExTaxAmount = 54M;    //	should be 55
			line1.AL_LocalTaxAmount = 4M;       // should be 5
			line1.AL_GovtChargeCode = "S009X";

			InvoicingLineBase line2 = (InvoicingLineBase)InvoicingBase.Lines.AddNew();
			line2.AL_AT = TestObjectCreator.GST1.PK;
			line2.AL_TaxDate = ZDate.Empty;
			line2.AL_TaxRateNumerator = 41;
			line2.AL_TaxRateDenominator = 71;
			line2.AL_TaxExtraRateNumerator = 141;
			line2.AL_TaxExtraRateDenominator = 171;
			line2.AL_ExchangeRate = 0.4M;
			line2.AL_OSExTaxAmount = 30M;
			line2.AL_OSTaxAmount = 3M;
			line2.AL_LocalExTaxAmount = 74M;    // Should be 75
			line2.AL_LocalTaxAmount = 7M;       // Should be 7.5
			line2.AL_GovtChargeCode = "S0010X";

			InvoicingBase.AH_OSTaxAmountOtherTaxes = 17M * InvoicingBase.Multiplier_ForTestOnly; //Tax Transactions calculated and so these fields are set only after invoice is fully populated. That's why in this test they are set after lines added.
			InvoicingBase.AH_LocalTaxAmountOtherTaxes = 14M * InvoicingBase.Multiplier_ForTestOnly;

			AssertEquals("Precondition: Invoice header AH_ExchangeRate", 0.483660M, InvoicingBase.AH_ExchangeRate);
			AssertEquals("Precondition: Invoice header AH_OSExTaxAmount", 52M, InvoicingBase.AH_OSExTaxAmount);
			AssertEquals("Precondition: Invoice header AH_LocalExTaxAmount", 128M, InvoicingBase.AH_LocalExTaxAmount);
			AssertEquals("Precondition: Invoice header AH_OSTaxAmount", 5M, InvoicingBase.AH_OSTaxAmount);
			AssertEquals("Precondition: Invoice header AH_LocalTaxAmount", 11M, InvoicingBase.AH_LocalTaxAmount);
			AssertEquals("Precondition: Invoice header AH_OSTaxAmountOtherTaxes_ForDisplay", 17M, InvoicingBase.AH_OSTaxAmountOtherTaxes_ForDisplay);
			AssertEquals("Precondition: Invoice header AH_LocalTaxAmountOtherTaxes_ForDisplay", 14M, InvoicingBase.AH_LocalTaxAmountOtherTaxes_ForDisplay);

			InvoicingBase.GenerateReverseTransaction(true);

			InvoicingBase.ReverseInvoice.AH_IsCancelled = true;
			AssertType("Precondition: Reverse validation is used on lines", typeof(TransactionLineEmptyValidation), InvoicingBase.ReverseInvoice.Lines[0].Validation);
			InvoicingBase.ReverseInvoice.RunPreSaveValidation();

			AssertEquals("MustTransform", true, InvoicingBase.MustTransform_ForTestOnly);
			AssertEquals("Reversing Invoice AH_ExchangeRate", 0.483660M, InvoicingBase.ReverseInvoice.AH_ExchangeRate);
			AssertEquals("Reversing invoice AH_OSExTaxAmount", 52M * reverseTransactionMultiplier, InvoicingBase.ReverseInvoice.AH_OSExTaxAmount);
			AssertEquals("Reversing invoice AH_LocalExTaxAmount", 128M * reverseTransactionMultiplier, InvoicingBase.ReverseInvoice.AH_LocalExTaxAmount);
			AssertEquals("Reversing invoice AH_OSTaxAmount", 5M * reverseTransactionMultiplier, InvoicingBase.ReverseInvoice.AH_OSTaxAmount);
			AssertEquals("Reversing invoice AH_LocalTaxAmount", 11M * reverseTransactionMultiplier, InvoicingBase.ReverseInvoice.AH_LocalTaxAmount);
			AssertEquals("Reversing invoice AH_OSTaxAmountOtherTaxes_ForDisplay", 17M * reverseTransactionMultiplier, InvoicingBase.ReverseInvoice.AH_OSTaxAmountOtherTaxes_ForDisplay);
			AssertEquals("Reversing invoice AH_LocalTaxAmountOtherTaxes_ForDisplay", 14M * reverseTransactionMultiplier, InvoicingBase.ReverseInvoice.AH_LocalTaxAmountOtherTaxes_ForDisplay);

			int index = 0;
			AssertEquals("Reversing AL_GovtChargeCode", "S009X", InvoicingBase.ReverseInvoice.Lines[index].AL_GovtChargeCode);
			AssertEquals("Reversing AL_AT", TestObjectCreator.GST1WithDates.PK, InvoicingBase.ReverseInvoice.Lines[index].AL_AT);
			AssertEquals("Reversing AL_TaxDate", TestObjectCreator.GST1WithDates_DateWithNoRate, InvoicingBase.ReverseInvoice.Lines[index].AL_TaxDate);
			AssertHasError("Original AL_TaxDateInfo", InvoicingBase.Lines[index].AL_TaxDateInfo, "No rate found for selected date.");
			AssertNoErrors("Reversing AL_TaxDateInfo", InvoicingBase.ReverseInvoice.Lines[index].AL_TaxDateInfo);
			AssertEquals("Reversing AL_TaxRateNumerator", 4, InvoicingBase.ReverseInvoice.Lines[index].AL_TaxRateNumerator);
			AssertEquals("Reversing AL_TaxRateDenominator", 7, InvoicingBase.ReverseInvoice.Lines[index].AL_TaxRateDenominator);
			AssertEquals("Reversing AL_TaxExtraRateNumerator", 14, InvoicingBase.ReverseInvoice.Lines[index].AL_TaxExtraRateNumerator);
			AssertEquals("Reversing AL_TaxExtraRateDenominator", 17, InvoicingBase.ReverseInvoice.Lines[index].AL_TaxExtraRateDenominator);
			AssertEquals("Reversing AL_ExchangeRate", 0.4M, InvoicingBase.ReverseInvoice.Lines[index].AL_ExchangeRate);

			index++;
			AssertEquals("Reversing AL_GovtChargeCode", "S0010X", InvoicingBase.ReverseInvoice.Lines[index].AL_GovtChargeCode);
			AssertEquals("Reversing AL_AT", TestObjectCreator.GST1.PK, InvoicingBase.ReverseInvoice.Lines[index].AL_AT);
			AssertEquals("Reversing AL_TaxDate", ZDate.Empty, InvoicingBase.ReverseInvoice.Lines[index].AL_TaxDate);
			AssertHasError("Original AL_TaxDateInfo", InvoicingBase.Lines[index].AL_TaxDateInfo, "Please enter a Tax Date.");
			AssertNoErrors("Reversing AL_TaxDateInfo", InvoicingBase.ReverseInvoice.Lines[index].AL_TaxDateInfo);
			AssertEquals("Reversing AL_TaxRateNumerator", 41, InvoicingBase.ReverseInvoice.Lines[index].AL_TaxRateNumerator);
			AssertEquals("Reversing AL_TaxRateDenominator", 71, InvoicingBase.ReverseInvoice.Lines[index].AL_TaxRateDenominator);
			AssertEquals("Reversing AL_TaxExtraRateNumerator", 141, InvoicingBase.ReverseInvoice.Lines[index].AL_TaxExtraRateNumerator);
			AssertEquals("Reversing AL_TaxExtraRateDenominator", 171, InvoicingBase.ReverseInvoice.Lines[index].AL_TaxExtraRateDenominator);
			AssertEquals("Reversing AL_ExchangeRate", 0.4M, InvoicingBase.ReverseInvoice.Lines[index].AL_ExchangeRate);
		}

		public virtual void TestGenerateReverseTransaction_CopyCharges()
		{
			InvoicingBase.Lines.RemoveAndDeleteAll();

			var line1 = (InvoicingLineBase)InvoicingBase.Lines.AddNew();
			line1.GenericCharge = TestObjectCreator.CC1.PK;
			line1.AL_Desc = "Desc 1";
			line1.AL_InputGSTVATRecoverable = 0.55m;

			var line2 = (InvoicingLineBase)InvoicingBase.Lines.AddNew();
			line2.GenericCharge = TestObjectCreator.CC2.PK;
			line2.AL_Desc = "Desc 2";
			line2.AL_InputGSTVATRecoverable = 0.44m;

			Assert("Precondition: line 1 should have charge code", !line1.AL_AC.IsEmpty);
			Assert("Precondition: line 1 should have gl account", !line1.AL_AG.IsEmpty);
			Assert("Precondition: line 2 should have charge code", !line2.AL_AC.IsEmpty);
			Assert("Precondition: line 2 should have gl account", !line2.AL_AG.IsEmpty);

			var expectedAL_AC1 = line1.AL_AC;
			var expectedAL_AG1 = line1.AL_AG;
			var expectedAL_AC2 = line2.AL_AC;
			var expectedAL_AG2 = line2.AL_AG;

			InvoicingBase.GenerateReverseTransaction(true);

			AssertEquals("Reversing line 1 AL_AC", expectedAL_AC1, InvoicingBase.ReverseInvoice.Lines[0].AL_AC);
			AssertEquals("Reversing line 1 AL_AG", expectedAL_AG1, InvoicingBase.ReverseInvoice.Lines[0].AL_AG);
			AssertEquals("Reversing line 1 AL_Desc", "Desc 1", InvoicingBase.ReverseInvoice.Lines[0].AL_Desc);
			AssertEquals("Reversing line 1 AL_InputGSTVATRecoverable", 0.55m, InvoicingBase.ReverseInvoice.Lines[0].AL_InputGSTVATRecoverable);
			AssertEquals("Reversing line 2 AL_AC", expectedAL_AC2, InvoicingBase.ReverseInvoice.Lines[1].AL_AC);
			AssertEquals("Reversing line 2 AL_AG", expectedAL_AG2, InvoicingBase.ReverseInvoice.Lines[1].AL_AG);
			AssertEquals("Reversing line 2 AL_Desc", "Desc 2", InvoicingBase.ReverseInvoice.Lines[1].AL_Desc);
			AssertEquals("Reversing line 2 AL_InputGSTVATRecoverable", 0.44m, InvoicingBase.ReverseInvoice.Lines[1].AL_InputGSTVATRecoverable);
		}

