		public void TestGenerateReverseTransactionWithDifferentCurrencyLines()
		{
			InvoicingBase.Lines.RemoveAndDeleteAll();
			int reverseTransactionMultiplier = InvoicingBase.InvertSignsOfOriginalTransactionOnReversing_ForTestOnly ? -1 : 1;
			InvoicingBase.AH_ExchangeRate = 0.4M;

			InvoicingLineBase line1 = (InvoicingLineBase)InvoicingBase.Lines.AddNew();
			line1.AL_RX_NKTransactionCurrency = ForeignCurrency.RX_Code;
			line1.AL_ExchangeRate = 0.4M;
			line1.AL_OSExTaxAmount = 22M;
			line1.AL_OSTaxAmount = 2M;
			line1.AL_LocalExTaxAmount = 54M;    //	should be 55
			line1.AL_LocalTaxAmount = 4M;       // should be 5
			line1.AL_AG = TestObjectCreator.GLHeader1.PK;

			InvoicingLineBase line2 = (InvoicingLineBase)InvoicingBase.Lines.AddNew();
			line2.AL_RX_NKTransactionCurrency = InvoicingBase.AH_RX_NKTransactionCurrency;
			line2.AL_ExchangeRate = 0.4M;
			line2.AL_OSExTaxAmount = 30M;
			line2.AL_OSTaxAmount = 3M;
			line2.AL_LocalExTaxAmount = 74M;    // Should be 75
			line2.AL_LocalTaxAmount = 7M;       // Should be 7.5
			line2.AL_AG = TestObjectCreator.GLHeader1.PK;

			AssertEquals("Invoice header should have exchange rate 0.4", 0.4M, InvoicingBase.AH_ExchangeRate);
			AssertEquals("Invoice header should have OSExTax amount 128", 128M, InvoicingBase.AH_OSExTaxAmount);
			AssertEquals("Invoice header should have LocalExTax amount 320", 320M, InvoicingBase.AH_LocalExTaxAmount);
			AssertEquals("Invoice header should have OSTax amount 11", 11M, InvoicingBase.AH_OSTaxAmount);
			AssertEquals("Invoice header should have LocalTax amount 27.5", 27.5M, InvoicingBase.AH_LocalTaxAmount);

			InvoicingBase.GenerateReverseTransaction(true);

			AssertEquals("Reversing Invoice should have exchange rate 0.4", 0.4M, InvoicingBase.ReverseInvoice.AH_ExchangeRate);
			AssertEquals("Reversing invoice header should have OSExTax 128", 128M * reverseTransactionMultiplier, InvoicingBase.ReverseInvoice.AH_OSExTaxAmount);
			AssertEquals("Reversing invoice header should have LocalExTax 320", 320M * reverseTransactionMultiplier, InvoicingBase.ReverseInvoice.AH_LocalExTaxAmount);
			AssertEquals("Reversing invoice header should have OSTax 11", 11M * reverseTransactionMultiplier, InvoicingBase.ReverseInvoice.AH_OSTaxAmount);
			AssertEquals("Reversing invoice header should have LocalTax 27.5", 27.5M * reverseTransactionMultiplier, InvoicingBase.ReverseInvoice.AH_LocalTaxAmount);
			AssertEquals("Reversing invoice header should have correct currency", ForeignCurrency.RX_Code, InvoicingBase.ReverseInvoice.Lines[0].AL_RX_NKTransactionCurrency);
			AssertEquals("Reversing invoice header should have correct currency", InvoicingBase.AH_RX_NKTransactionCurrency, InvoicingBase.ReverseInvoice.Lines[1].AL_RX_NKTransactionCurrency);
		}

