		public void TestReceiptBankAccount()
		{
			SetupOrganisations();

			AccBankAccount bank1 = Factory.NewWithValidTestData<AccBankAccount>();
			bank1.AB_RX_NKAccountCurrency = GlbCompany.CurrentCompany.GC_RX_NKLocalCurrency;
			bank1.AB_Code = "Bank1";
			bank1.AB_IsDefaultReceiptBankAccount = true;

			AccBankAccount bank2 = Factory.NewWithValidTestData<AccBankAccount>();
			bank2.AB_RX_NKAccountCurrency = GlbCompany.CurrentCompany.GC_RX_NKLocalCurrency;
			bank2.AB_Code = "Bank2";

			AccBankAccount bank3 = Factory.NewWithValidTestData<AccBankAccount>();
			bank3.AB_RX_NKAccountCurrency = GlbCompany.CurrentCompany.GC_RX_NKLocalCurrency;
			bank3.AB_Code = "Bank3";

			OrgDebtorGroup group = Factory.New<OrgDebtorGroup>();
			group.OJ_Code = "XXX";
			group.OJ_Desc = "XXX";
			Organisation.CompanyData.OB_OJ_ARDebtorGroup = group.PK;

			Factory.Save();

			InvoicingBase invoice = (InvoicingBase)Factory.New(GetExpectedBusinessObjectType());
			invoice.AH_OH = Organisation.PK;
			AssertEquals("No 'Bank To' Bank Accounts not specified: Invoice receipt bank should be the default bank ", bank1.AB_Code, invoice.ReceiptBankAccount.AB_Code);

