			else
			{
				//Check AH_TranactionRes if Empty
				Factory.Save();

				testInvoicingBase.GenerateReverseTransaction(true);
				InvoicingBase reversedInvoice = testInvoicingBase.ReverseInvoice;
				Factory.Save();

				Assert("AP Ledger Transaction Reference No should be empty.", reversedInvoice.AH_TransactionReference.IsEmpty);
