		public void TestJobInvoiceNumbers()
		{
			GlbCompany anotherCompany = Factory.NewWithValidTestData<GlbCompany>();
			Factory.Save();

			GlbBranch branch = anotherCompany.Branches.AddNew();

			ARInvoice aRInvoice = Factory.New<ARInvoice>();
			aRInvoice.AH_TransactionNum = "1234";
			aRInvoice.AH_GB = branch.PK;
			ARCreditNote aRCreditNote = Factory.New<ARCreditNote>();
			aRCreditNote.AH_TransactionNum = "1234";
			aRCreditNote.AH_GB = branch.PK;
			APCreditNote aPCreditNote = Factory.New<APCreditNote>();
			aPCreditNote.AH_TransactionNum = "1234";
			aPCreditNote.AH_GB = branch.PK;

			AccountingConfigurationRegistry.Instance.UseJobNumberBasedInvoiceNumbers.SetValue(anotherCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);
			AccountingConfigurationRegistry.Instance.UseJobNumberBasedInvoiceNumbers.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, false); //making sure code doesn't depend on current company
			AssertEquals("AH_ConsolidatedInvoiceRef", ZString.Empty, aRInvoice.AH_ConsolidatedInvoiceRef);
			AssertInvoiceNumbers("Consolidated invoice ref is empty, so job number can't be used despite the registry setting", anotherCompany, aRInvoice, true, false, ZString.Empty, "ABC", "1234", "1234");
			AssertInvoiceNumbers("Consolidated invoice ref is empty, so job number can't be used despite the registry setting", anotherCompany, aRInvoice, true, false, "ABC", ZString.Empty, "1234", "ABC1234");
			AssertEquals("AH_ConsolidatedInvoiceRef", ZString.Empty, aRCreditNote.AH_ConsolidatedInvoiceRef);
			AssertInvoiceNumbers("Consolidated invoice ref is empty, so job number can't be used despite the registry setting", anotherCompany, aRCreditNote, true, false, ZString.Empty, "ABC", "1234", "1234");
			AssertInvoiceNumbers("Consolidated invoice ref is empty, so job number can't be used despite the registry setting", anotherCompany, aRCreditNote, true, false, "ABC", ZString.Empty, "1234", "ABC1234");

			AssertInvoiceNumbers("Should always be transaction number (and use prefix if set and is a self billing invoice)", anotherCompany, aPCreditNote, true, false, ZString.Empty, "ABC", "1234", "1234");
			AssertInvoiceNumbers("Should always be transaction number (and use prefix if set and is a self billing invoice)", anotherCompany, aPCreditNote, true, false, "ABC", ZString.Empty, "1234", "1234");
			aPCreditNote.AH_TransactionCategory = Core.Constants.TransactionCategory.Codes.SelfBilling;
			AssertInvoiceNumbers("Should always be transaction number (and use prefix if set and is a self billing invoice)", anotherCompany, aPCreditNote, true, false, "ABC", ZString.Empty, "1234", "ABC1234");
			aPCreditNote.AH_TransactionCategory = ZString.Empty;

			aRInvoice.AH_ConsolidatedInvoiceRef = "S12345";
			aRCreditNote.AH_ConsolidatedInvoiceRef = "S12345";
			aPCreditNote.AH_ConsolidatedInvoiceRef = "S12345";

			AssertInvoiceNumbers("Should be equal to Consolidated invoice ref and not use prefix", anotherCompany, aRInvoice, true, false, ZString.Empty, "ABC", "S12345", "S12345");
			AssertInvoiceNumbers("Should be equal to Consolidated invoice ref and not use prefix", anotherCompany, aRInvoice, true, false, "ABC", ZString.Empty, "S12345", "S12345");
			AssertInvoiceNumbers("Should be equal to Consolidated invoice ref and not use prefix", anotherCompany, aRCreditNote, true, false, ZString.Empty, "ABC", "S12345", "S12345");
			AssertInvoiceNumbers("Should be equal to Consolidated invoice ref and not use prefix", anotherCompany, aRCreditNote, true, false, "ABC", ZString.Empty, "S12345", "S12345");

			AssertInvoiceNumbers("Should always be transaction number (and use prefix if set and is a self billing invoice)", anotherCompany, aPCreditNote, true, false, ZString.Empty, "ABC", "1234", "1234");
			AssertInvoiceNumbers("Should always be transaction number (and use prefix if set and is a self billing invoice)", anotherCompany, aPCreditNote, true, false, "ABC", ZString.Empty, "1234", "1234");
			aPCreditNote.AH_TransactionCategory = Core.Constants.TransactionCategory.Codes.SelfBilling;
			AssertInvoiceNumbers("Should always be transaction number (and use prefix if set and is a self billing invoice)", anotherCompany, aPCreditNote, true, false, "ABC", ZString.Empty, "1234", "ABC1234");
			aPCreditNote.AH_TransactionCategory = ZString.Empty;

			AssertInvoiceNumbers("Should be equal to Transaction Number and use prefix if set", anotherCompany, aRInvoice, false, true, ZString.Empty, "ABC", "1234", "1234");
			AssertInvoiceNumbers("Should be equal to Transaction Number and use prefix if set", anotherCompany, aRInvoice, false, true, "ABC", ZString.Empty, "1234", "ABC1234");
			AssertInvoiceNumbers("Should be equal to Transaction Number and use prefix if set", anotherCompany, aRCreditNote, false, true, ZString.Empty, "ABC", "1234", "1234");
			AssertInvoiceNumbers("Should be equal to Transaction Number and use prefix if set", anotherCompany, aRCreditNote, false, true, "ABC", ZString.Empty, "1234", "ABC1234");

			AssertInvoiceNumbers("Should always be transaction number (and use prefix if set and is a self billing invoice)", anotherCompany, aPCreditNote, false, true, ZString.Empty, "ABC", "1234", "1234");
			AssertInvoiceNumbers("Should always be transaction number (and use prefix if set and is a self billing invoice)", anotherCompany, aPCreditNote, false, true, "ABC", ZString.Empty, "1234", "1234");
			aPCreditNote.AH_TransactionCategory = Core.Constants.TransactionCategory.Codes.SelfBilling;
			AssertInvoiceNumbers("Should always be transaction number (and use prefix if set and is a self billing invoice)", anotherCompany, aPCreditNote, false, true, "ABC", ZString.Empty, "1234", "ABC1234");
		}

		void AssertInvoiceNumbers(string remark, GlbCompany anotherCompany, InvoicingBase transaction, bool anotherCompanyUseJobNumberBasedInvoiceNumbers, bool ourCompanyUseJobNumberBasedInvoiceNumbers, ZString anotherCompanyInvoiceTransactionNumberPrefix, ZString ourCompanyInvoiceTransactionNumberPrefix, ZString expectedInvoiceNumber, ZString expectedInvoiceNumberPrefixed)
		{
			AccountingConfigurationRegistry.Instance.UseJobNumberBasedInvoiceNumbers.SetValue(anotherCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, anotherCompanyUseJobNumberBasedInvoiceNumbers);
			AccountingConfigurationRegistry.Instance.InvoiceTransactionNumberPrefix.SetValue(anotherCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, anotherCompanyInvoiceTransactionNumberPrefix);
			AccountingConfigurationRegistry.Instance.SelfBillingInvoiceTransactionNumberPrefix.SetValue(anotherCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, anotherCompanyInvoiceTransactionNumberPrefix);
			//making sure code doesn't depend on current company
			AccountingConfigurationRegistry.Instance.UseJobNumberBasedInvoiceNumbers.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, ourCompanyUseJobNumberBasedInvoiceNumbers);
			AccountingConfigurationRegistry.Instance.InvoiceTransactionNumberPrefix.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, ourCompanyInvoiceTransactionNumberPrefix);
			AccountingConfigurationRegistry.Instance.SelfBillingInvoiceTransactionNumberPrefix.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, ourCompanyInvoiceTransactionNumberPrefix);

			AssertEquals(remark, expectedInvoiceNumber, transaction.InvoiceNumber);
			AssertEquals(remark, expectedInvoiceNumberPrefixed, transaction.InvoiceNumberPrefixed);
		}

