		public void TestInvoiceJobRevenueRecognitionDate_FactoryIndependent()
		{
			RevenueRecognitionCollection valuesForTest = new RevenueRecognitionCollection();
			RevenueRecognition setting1 = valuesForTest.AddNew();
			setting1.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			setting1.DirectionCode = Constants.FreightShipmentDirection.Code.All;
			setting1.Mode = Core.Constants.TransportModes.Air;
			setting1.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.PickupDate;

			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);

			ForwardingShipment shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_TransportMode = Core.Constants.TransportModes.Air;
			ZDateTime expectedDate = ZDateTime.Today.AddDays(2);
			shipment.DocsAndCartage.JP_PickupCartageCompleted = expectedDate;

			Job job = new Job.Loader(shipment).TryLoadOrCreateWithoutMutexForTestOnly();
			Factory.Save();

			AssertNotEquals("Precondition", expectedDate, job.GetRevenueRecognitionDate(job.GetRevenueRecognitionType(TestObjectCreator.CC1)));

			BusinessObjectFactory newFactory = new BusinessObjectFactory();
			Header = newFactory.New(GetExpectedBusinessObjectType()) as InvoicingBase;
			InvoicingBase.AH_TransactionNum = "INV1";
			InvoicingBase.Lines.AddNew();
			InvoicingBase.Lines.AddNew();
			InvoicingBase.AH_Desc = "Changed Desc";

			AccChargeCode chargeCode = newFactory.LoadTop1<AccChargeCode>(new ZQuery());
			TestObjectCreator testObjectCreatorInNewFactory = new TestObjectCreator(newFactory);
			foreach (InvoicingLineBase line in InvoicingBase.Lines)
			{
				line.AL_AC = TestObjectCreator.CC1.PK;
				line.AL_JH = job.PK;
				testObjectCreatorInNewFactory.CreateJobCharge(line, newFactory.Load<Job>(job.PK), chargeCode, TestObjectCreator.AUD);
			}

			newFactory.Save();

			AssertEquals("Revenue Recognition Date should be filled.", expectedDate, job.GetRevenueRecognitionDate(job.GetRevenueRecognitionType(TestObjectCreator.CC1)));

			shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_TransportMode = Core.Constants.TransportModes.Air;
			shipment.DocsAndCartage.JP_PickupCartageCompleted = expectedDate;

			job = new Job.Loader(shipment).TryLoadOrCreateWithoutMutexForTestOnly();
			Factory.Save();

			AssertNotEquals("Precondition", expectedDate, job.GetRevenueRecognitionDate(job.GetRevenueRecognitionType(TestObjectCreator.CC1)));

			newFactory = new BusinessObjectFactory();
			chargeCode = newFactory.LoadTop1<AccChargeCode>(new ZQuery());
			testObjectCreatorInNewFactory = new TestObjectCreator(newFactory);
			Header = newFactory.New(GetExpectedBusinessObjectType()) as InvoicingBase;
			InvoicingBase.AH_TransactionNum = "INV2";
			InvoicingBase.AH_Desc = "Changed Desc";
			InvoicingBase.AH_JH = job.PK;
			InvoicingBase.Lines.AddNew();
			foreach (InvoicingLineBase line in InvoicingBase.Lines)
			{
				line.AL_AC = TestObjectCreator.CC1.PK;
				line.AL_JH = job.PK;
				testObjectCreatorInNewFactory.CreateJobCharge(line, newFactory.Load<Job>(job.PK), chargeCode, TestObjectCreator.AUD);
			}

			newFactory.Save();

			AssertEquals("Revenue Recognition Date should be filled.", expectedDate, job.GetRevenueRecognitionDate(job.GetRevenueRecognitionType(TestObjectCreator.CC1)));
		}

		public void TestInvoiceJobRevenueRecognitionDate_WithCurrentDateRegistryOn()
		{
			RevenueRecognitionCollection valuesForTest = new RevenueRecognitionCollection();
			RevenueRecognition setting1 = valuesForTest.AddNew();
			setting1.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			setting1.DirectionCode = Constants.FreightShipmentDirection.Code.All;
			setting1.Mode = Core.Constants.TransportModes.Air;
			setting1.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.PickupDate;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);

			Factory.Save();

			using (AccountingConfigurationRegistry.Instance.RecognizeRevenueUsingCurrentDateWhenRevenueRecognitionDateInFuture.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, false))
			{
				AssertInvoiceJobRevenueRecognitionDate("S0001", ZDateTime.Today.AddDays(2), ZDateTime.Today.AddDays(2), true);
				AssertInvoiceJobRevenueRecognitionDate("S0002", ZDateTime.Today.AddDays(2), ZDateTime.Today.AddDays(2), false);
				AssertInvoiceJobRevenueRecognitionDate("S0003", ZDateTime.Today.AddDays(-2), ZDateTime.Today.AddDays(-2), true);
				AssertInvoiceJobRevenueRecognitionDate("S0004", ZDateTime.Today.AddDays(-2), ZDateTime.Today.AddDays(-2), false);
			}

			using (AccountingConfigurationRegistry.Instance.RecognizeRevenueUsingCurrentDateWhenRevenueRecognitionDateInFuture.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true))
			{
				AssertInvoiceJobRevenueRecognitionDate("S0011", ZDateTime.Today.AddDays(2), ZDateTime.Now, true);
				AssertInvoiceJobRevenueRecognitionDate("S0012", ZDateTime.Today.AddDays(2), ZDateTime.Now, false);
				AssertInvoiceJobRevenueRecognitionDate("S0013", ZDateTime.Today.AddDays(-2), ZDateTime.Today.AddDays(-2), true);
				AssertInvoiceJobRevenueRecognitionDate("S0014", ZDateTime.Today.AddDays(-2), ZDateTime.Today.AddDays(-2), false);
			}

			void AssertInvoiceJobRevenueRecognitionDate(string shipmentNum, ZDateTime pickDate, ZDateTime expectedDate, bool invoiceHasJobHeader)
			{
				var newFactory = new BusinessObjectFactory();
				var testObjectCreator = new TestObjectCreator(newFactory);

				var shipment = testObjectCreator.CreateShipment(shipmentNum);
				shipment.JS_TransportMode = Core.Constants.TransportModes.Air;
				shipment.DocsAndCartage.JP_PickupCartageCompleted = pickDate;
				var job = new Job.Loader(shipment).TryLoadOrCreateWithoutMutexForTestOnly();

				newFactory.Save();
				AssertNotEquals("Precondition", expectedDate.Date, job.GetRevenueRecognitionDate(job.GetRevenueRecognitionType(testObjectCreator.CC1)).Date);

				AssertInvoiceJobRevenueRecognitionDateInSameJob("Revenue Recognition Date should be filled.", 1, testObjectCreator, job, expectedDate, invoiceHasJobHeader);

				using (AccountingConfigurationRegistry.Instance.RecognizeRevenueUsingCurrentDateWhenRevenueRecognitionDateInFuture.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true))
				{
					AssertInvoiceJobRevenueRecognitionDateInSameJob("Same Recognition Type will use first Recognition Date although the registry is on", 2, testObjectCreator, job, expectedDate, invoiceHasJobHeader);
				}
			}

			void AssertInvoiceJobRevenueRecognitionDateInSameJob(string comment, int seq, TestObjectCreator testObjectCreator, Job job, ZDateTime expectedDate, bool invoiceHasJobHeader)
			{
				var invoice = testObjectCreator.Factory.New(GetExpectedBusinessObjectType()) as InvoicingBase;
				invoice.AH_TransactionNum = $"{job.JH_JobNum}_INV{seq}";
				invoice.AH_Desc = "Changed Desc";

				if (invoiceHasJobHeader)
				{
					invoice.AH_JH = job.PK;
				}

				for (var i = 0; i < 2; i++)
				{
					var line = invoice.Lines.AddNew() as InvoicingLineBase;
					line.AL_AC = testObjectCreator.CC1.PK;
					line.AL_JH = job.PK;
					testObjectCreator.CreateJobCharge(line, job, testObjectCreator.CC1, testObjectCreator.AUD);
				}

				testObjectCreator.Factory.Save();
				AssertEquals(comment, expectedDate.Date, invoice.Lines[0].AL_ReverseDate.Date);
			}
		}

