		public void TestReversingErroneousTransaction()
		{
			SetupHeaderForReversing(200.00m, 20.00m);

			Header.AH_InvoiceAmount = -Header.AH_InvoiceAmount;
			Header.AH_GSTAmount = -Header.AH_GSTAmount;
			Header.AH_OSTotal = -Header.AH_OSTotal;

			ZQuery findLinesForHeaderQuery = new ZQuery(AccTransactionLinesSchema.AL_AH, Header.PK);
			findLinesForHeaderQuery.AddToFilter(AccTransactionLinesSchema.AL_GC, Header.AH_GC);
			AccTransactionLinesCollection lines = new AccTransactionLinesCollection(Factory, findLinesForHeaderQuery);
			lines.Load();

			foreach (AccTransactionLines line in lines)
			{
				line.AL_LineAmount = -line.AL_LineAmount;
				line.AL_GSTVAT = -line.AL_GSTVAT;
				line.AL_OSAmount = -line.AL_OSAmount;
			}

			Header.AH_OH = ZGuid.Empty;
			Header.Validation.ValidateAll();

			((IReversing)Header).GenerateReverseTransaction(true);

			TransactionHeader reversingHeader = ((IReversing)Header).ReverseTransaction as TransactionHeader;
			AssertNotNull("Reversing Transaction should always be a transactionheader at this level", reversingHeader);
			AssertEquals("IsReverseTransaction should be set to false for Header", false, Header.IsReverseTransaction);
			AssertEquals("IsReverseTransaction should be set to true for ReversingHeader", true, reversingHeader.IsReverseTransaction);

			if (Header.AH_Ledger == ZArchitecture.Core.LedgerTypes.AccountsPayable)
			{
				reversingHeader.AH_TransactionNum = "12345678";
			}

			reversingHeader.Validation.ValidateAll();
			AssertEquals("ReversingHeader should have errors", false, reversingHeader.HasErrors);
		}

		public virtual void TestReversingErroneousTransactionLine()
		{
			SetupHeaderForReversing(200.00m, -20.00m); // this creates an erroneous transaction line

			Header.RunPreSaveValidation();
			Header.Validation.ValidateAll();
			var validationClass = ((InvoicingBase)Header).Lines[0].Validation;
			AssertEquals("Check validation class is", true, validationClass is InvoicingLineBaseValidation);
			AssertHasErrors("Invoicing Line should have errors", ((InvoicingBase)Header).Lines[0].AL_OSTaxAmountInfo);

			var reversingBase = new ReversingBase(Header);
			reversingBase.Reverse();
			var reversingHeader = reversingBase.ReverseTransaction as TransactionHeader;

			if (Header.AH_Ledger == ZArchitecture.Core.LedgerTypes.AccountsPayable)
			{
				reversingHeader.AH_TransactionNum = "12345678";
			}

			reversingHeader.RunPreSaveValidation();
			reversingHeader.Validation.ValidateAll();
			validationClass = ((InvoicingBase)reversingHeader).Lines[0].Validation;
			AssertEquals("Check validation class is", true, validationClass is TransactionLineEmptyValidation);
			AssertNoErrors("Reversing Line should have no errors", ((InvoicingBase)reversingHeader).Lines[0].AL_OSTaxAmountInfo);
		}

