				TestObjectCreator.CreateJobChargeRevRecognition(charge.InvoicingJob, RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate, ZDateTime.Now);
				Factory.Save();

				AssertEquals("WIPAccrualCreationDate", ZDateTime.Now, charge.WIPAccrualCreationDate);

