		public void TestPopulateSellGovtChargeCode()
		{
			if ((InvoicingBase is APInvoice || InvoicingBase is APCreditNote) && InvoicingBase.AH_Ledger == LedgerTypes.AccountsPayable)
			{
				AccountingMasterFilesRegistry.Instance.EnableGovernmentChargeCode.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);

				var chargeCode = TestObjectCreator.CC1;

				ForwardingConsol consol = TestObjectCreator.CreateConsol("AUSYD", "USLAX", "C3412443");
				consol.Shipments.AddNew();
				Factory.Save();

				Job job = TestObjectCreator.CreateJob("S00001325", TestObjectCreator.LocalClient, 0m, TestObjectCreator.Agent, 0m);

				Header = (InvoicingBase)GetNewBusinessObject();
				InvoicingBase.SubmittedFromInvoicingForm = true;
				InvoicingBase.AH_Ledger = LedgerTypes.AccountsPayable;
				InvoicingBase.AH_OH = TestObjectCreator.AALSHI.PK;
				InvoicingBase.AH_InvoiceDate = ZDateTime.Now.AddDays(-5);
				InvoicingBase.AH_DueDate = ZDateTime.Now.AddDays(10);

				InvoicingBase.Lines.RemoveAndDeleteAll();

				JobConsolCost cost = InvoicingBase.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
				cost.E6_AC_ChargeCode = chargeCode.PK;
				cost.E6_SellGovtChargeCode = "666";
				cost.E6_OSCostAmount = 100m;
				InvoicingBase.ImportAllApportionmentsFromCosting();

				AssertEquals("should be 1 line", 1, InvoicingBase.Lines.Count);

				var line1 = InvoicingBase.Lines[0];
				InvoicingBase.IsImportingConsolApportionment_ForTestOnly = true;
				line1.AL_GovtChargeCode = "555";

				Factory.Save();

				ReleaseFactory();

				Charge charge1 = Factory.LoadTop1<Charge>(new ZQuery(JobChargeSchema.JR_AL_APLine, line1.PK));
				AssertEquals("Cost govt charge code overridden in invoice", "555", charge1.JR_CostGovtChargeCode);
				AssertEquals("Sell govt charge code overridden in consol", "666", charge1.JR_SellGovtChargeCode);
			}
			else
			{
				Assert(true);
			}
		}

		public void TestPopulateChargeAndConsolCostInvoiceDetails()
		{
			if ((InvoicingBase is APInvoice || InvoicingBase is APCreditNote) && InvoicingBase.AH_Ledger == LedgerTypes.AccountsPayable)
			{
				OrgHeader selfBillingCreditor = TestObjectCreator.Creditor1;
				selfBillingCreditor.CompanyData.OB_APCostsSelfBilled = true;

				ZGuid chargeCode1 = TestObjectCreator.CC1.PK;
				ZGuid chargeCode2 = TestObjectCreator.CC2.PK;
				Factory.Save();

				ForwardingConsol consol = TestObjectCreator.CreateConsol("AUSYD", "USLAX", "C3412443");
				consol.Shipments.AddNew();
				Factory.Save();

				Job job = TestObjectCreator.CreateJob("S00001325", TestObjectCreator.LocalClient, 0m, TestObjectCreator.Agent, 0m);

				Header = (InvoicingBase)GetNewBusinessObject();
				InvoicingBase.SubmittedFromInvoicingForm = true;
				InvoicingBase.AH_Ledger = LedgerTypes.AccountsPayable;
				InvoicingBase.AH_OH = selfBillingCreditor.PK;
				InvoicingBase.AH_InvoiceDate = ZDateTime.Now.AddDays(-5);
				InvoicingBase.AH_DocumentReceivedDate = ZDateTime.Now.AddDays(-6);
				InvoicingBase.AH_DueDate = ZDateTime.Now.AddDays(10);
				InvoicingLineBase line1 = (InvoicingLineBase)InvoicingBase.Lines.AddNew();
				line1.GenericCharge = chargeCode1;
				line1.AL_JH = job.PK;
				line1.AL_OSExTaxAmount = 100m;
				InvoicingLineBase line2 = (InvoicingLineBase)InvoicingBase.Lines.AddNew();
				line2.GenericCharge = chargeCode2;
				line2.AL_JH = job.PK;
				line2.AL_OSExTaxAmount = 200m;
				JobConsolCost cost = InvoicingBase.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
				cost.E6_AC_ChargeCode = chargeCode1;
				cost.E6_OSCostAmount = 100m;
				InvoicingBase.ImportAllApportionmentsFromCosting();
				AssertEquals("should be 3 lines", 3, InvoicingBase.Lines.Count);

				Factory.Save();

				Charge charge1 = Factory.LoadTop1<Charge>(new ZQuery(JobChargeSchema.JR_AL_APLine, line1.PK));
				Charge charge2 = Factory.LoadTop1<Charge>(new ZQuery(JobChargeSchema.JR_AL_APLine, line2.PK));
				Charge charge3 = Factory.LoadTop1<Charge>(new ZQuery(JobChargeSchema.JR_AL_APLine, InvoicingBase.Lines[2].PK));

				AssertEquals("invoice number", InvoicingBase.AH_TransactionNum, charge1.JR_APInvoiceNum);
				AssertEquals("invoice date", InvoicingBase.AH_InvoiceDate, charge1.JR_APInvoiceDate);
				AssertEquals("document received date", InvoicingBase.AH_DocumentReceivedDate, charge1.JR_APDocumentReceivedDate);
