				AssertEquals("Cost Document Received date", InvoicingBase.AH_DocumentReceivedDate, cost.E6_DocumentReceivedDate);
				AssertEquals("Cost due date", InvoicingBase.AH_DueDate, cost.E6_PaymentDate);

				AssertEquals("invoice number", InvoicingBase.AH_TransactionNum, charge3.JR_APInvoiceNum);
				AssertEquals("invoice date", InvoicingBase.AH_InvoiceDate, charge3.JR_APInvoiceDate);
				AssertEquals("due date", InvoicingBase.AH_DueDate, charge3.JR_PaymentDate);
