				AssertEquals("Charge supplier cost ref.", InvoicingBase.AH_ChequeOrReference, charge1.JR_CostReference);

				AssertEquals("Charge invoice number", InvoicingBase.AH_TransactionNum, charge2.JR_APInvoiceNum);
				AssertEquals("Charge invoice date", InvoicingBase.AH_InvoiceDate, charge2.JR_APInvoiceDate);
				AssertEquals("Charge supplier cost ref.", InvoicingBase.AH_ChequeOrReference, charge2.JR_CostReference);

				AssertEquals("Cost Invoice number", InvoicingBase.AH_TransactionNum, consCost.E6_InvoiceNum);
				AssertEquals("Cost Invoice date", InvoicingBase.AH_InvoiceDate, consCost.E6_InvoiceDate);
				AssertEquals("Charge supplier cost ref.", InvoicingBase.AH_ChequeOrReference, consCost.E6_CostReference);

				InvoicingBase.SetContext(BusinessContext.OverrideTransactionAgreedPaymentMethod);
				InvoicingBase.AH_DueDate = now.AddDays(15);
				Factory.Save();
				InvoicingBase.RemoveContext(BusinessContext.OverrideTransactionAgreedPaymentMethod);

				charge1 = Factory.LoadTop1<Charge>(new ZQuery(JobChargeSchema.JR_AL_APLine, line1.PK));
				charge2 = Factory.LoadTop1<Charge>(new ZQuery(JobChargeSchema.JR_AL_APLine, line2.PK));
				consCost = Factory.LoadTop1<JobConsolCost>(new ZQuery(JobConsolCostSchema.E6_AH_APInvoice, InvoicingBase.PK));

				AssertEquals("Charge due date", InvoicingBase.AH_DueDate, charge1.JR_PaymentDate);
				AssertEquals("Charge due date", InvoicingBase.AH_DueDate, charge2.JR_PaymentDate);
				AssertEquals("Cost due date", InvoicingBase.AH_DueDate, consCost.E6_PaymentDate);
