		public void TestBalancingLIneTaxAMountWhenCurrentCountryAndCurrencyIsIcelandic()
		{
			if (IsUnApprovedTransaction)
			{
				Assert(true);
			}
			else
			{
				bool originalIsGSTRegistered = GlbCompany.CurrentCompany.GC_IsGSTRegistered;
				string currentCountry = GlbCompany.CurrentCompany.GC_RN_NKCountryCode;

				GlbCompany.CurrentCompany.GC_IsGSTRegistered = true;
				TestObjectCreator.GST1.SetRateNumerator_ForTestOnly(10);
				RefCurrency iSK = RefCurrency.LoadFromCurrencyCode(Factory, Core.Constants.CurrencyCodes.Iceland);

				AccountingConfigurationRegistry.Instance.CalculateTaxAtHeaderLevel.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, false);

				try
				{
					InvoicingBase.AH_Ledger = LedgerTypes.AccountsReceivable;
					AssertEquals("Calc tax at header level is still false", false, AccountingConfigurationRegistry.Instance.CalculateTaxAtHeaderLevel.Value);
					AssertNotEquals("Current currency is not ISK", Core.Constants.CurrencyCodes.Iceland, GlbCompany.CurrentCompany.GC_RX_NKLocalCurrency);
					AssertEquals("Should not expect calculation of tax at header level because registry is false", false, InvoicingBase.ShouldFixTaxAmountOnHeader);

					SetCurrentCountryToCode(Core.Constants.CountryCodes.Iceland);
					AssertEquals("Should still not expect calculation of tax at header level because registry is false, country is Iceland but currency is not", false, InvoicingBase.ShouldFixTaxAmountOnHeader);

					InvoicingBase.AH_RX_NKTransactionCurrency = iSK.RX_Code;
					AssertEquals("Should expect calculation of tax at header level despite registry being false because country is Iceland and currency is ISK ", true, InvoicingBase.ShouldFixTaxAmountOnHeader);

					Header = (InvoicingBase)Factory.New(GetExpectedBusinessObjectType());
					AssertEquals("Precondition: Should have no lines", 0, InvoicingBase.Lines.Count);

					TestObjectCreator.GST1.SetRateNumerator_ForTestOnly(10);
					InvoicingBase.AH_Ledger = LedgerTypes.AccountsReceivable;
					InvoicingBase.AH_RX_NKTransactionCurrency = iSK.RX_Code;

					AssertEquals("Precondition: CurrentCompany.LocalCurrency.Decimals", 2, GlbCompany.CurrentCompany.LocalCurrency.Decimals);
					AssertEquals("Precondition: Invoice.TransactionCurrency.Decimals", 0, InvoicingBase.TransactionCurrency.Decimals);
					AssertEquals("Precondition: CalculateTaxAtHeaderLevel", true, InvoicingBase.ShouldFixTaxAmountOnHeader);

					var testLedger = InvoicingBase.AH_Ledger;
					var testLedger_ForTestOnly2 = InvoicingBase.Ledger_ForTestOnly;

					InvoicingLineBase line1 = AddNewLine(InvoicingBase, 203m);
					AssertLineAmounts(line1, 203m, 20m);
					AssertHeaderAmounts(InvoicingBase, 203m, 20m);

					InvoicingLineBase line2 = AddNewLine(InvoicingBase, 102m);
					AssertLineAmounts(line1, 203m, 21m);
					AssertLineAmounts(line2, 102, 10m);
					AssertHeaderAmounts(InvoicingBase, 305, 31m);

					InvoicingLineBase line3 = AddNewLine(InvoicingBase, 11m);
					AssertLineAmounts(line1, 203m, 21m);
					AssertLineAmounts(line2, 102, 10m);
					AssertLineAmounts(line3, 11m, 1m);
					AssertHeaderAmounts(InvoicingBase, 316m, 32m);

					InvoicingBase.Lines.RemoveAll();

					SetCurrentCountryToCode(currentCountry);
					AssertNotEquals("Current Branch Country is no longer IS", Core.Constants.CurrencyCodes.Iceland, GlbBranch.CurrentBranch.Country.RN_Code);
					AssertEquals("Should not expect calculation of tax at header level because registry is false, Currency is ISK but country is not IS", false, InvoicingBase.ShouldFixTaxAmountOnHeader);

					Header = (InvoicingBase)Factory.New(GetExpectedBusinessObjectType());
					AssertEquals("Precondition: Should have no lines", 0, InvoicingBase.Lines.Count);
					InvoicingBase.AH_RX_NKTransactionCurrency = iSK.RX_Code;
					TestObjectCreator.GST1.SetRateNumerator_ForTestOnly(10);
					InvoicingBase.AH_Ledger = LedgerTypes.AccountsReceivable;

					AssertEquals("Precondition: CurrentCompany.LocalCurrency.Decimals", 2, GlbCompany.CurrentCompany.LocalCurrency.Decimals);
					AssertEquals("Precondition: Invoice.TransactionCurrency.Decimals", 0, InvoicingBase.TransactionCurrency.Decimals);
					AssertEquals("Precondition: CalculateTaxAtHeaderLevel", false, InvoicingBase.ShouldFixTaxAmountOnHeader);

					InvoicingLineBase line1_2 = AddNewLine(InvoicingBase, 203m);
					AssertLineAmounts(line1_2, 203m, 20m);
					AssertHeaderAmounts(InvoicingBase, 203m, 20m);

					InvoicingLineBase line2_2 = AddNewLine(InvoicingBase, 102m);
					AssertLineAmounts(line1_2, 203m, 20m);
					AssertLineAmounts(line2_2, 102, 10m);
					AssertHeaderAmounts(InvoicingBase, 305, 30m);

					InvoicingLineBase line3_2 = AddNewLine(InvoicingBase, 11m);
					AssertLineAmounts(line1_2, 203m, 20m);
					AssertLineAmounts(line2_2, 102, 10m);
					AssertLineAmounts(line3_2, 11m, 1m);
					AssertHeaderAmounts(InvoicingBase, 316m, 31m);
				}
				finally
				{
					GlbCompany.CurrentCompany.GC_IsGSTRegistered = originalIsGSTRegistered;
					SetCurrentCountryToCode(currentCountry);
				}
			}
		}

