		public void TestBalancingLineTaxAmountWhenTaxCalculatedAtHeaderLevel()
		{
			bool expectAdjustment = ShouldSupportCalculatingTaxAtHeaderLevel;

			ZInt originalSubUnitRatio = GlbCompany.CurrentCompany.LocalCurrency.RX_SubUnitRatio;
			bool originalIsGSTRegistered = GlbCompany.CurrentCompany.GC_IsGSTRegistered;

			GlbCompany.CurrentCompany.LocalCurrency.RX_SubUnitRatio = 0;
			GlbCompany.CurrentCompany.GC_IsGSTRegistered = true;
			TestObjectCreator.GST1.SetRateNumerator_ForTestOnly(5);
			AccountingConfigurationRegistry.Instance.CalculateTaxAtHeaderLevel.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, true);

			try
			{
				RefCurrency tWD = RefCurrency.LoadFromCurrencyCode(Factory, Core.Constants.CurrencyCodes.Taiwan);
				Header = (InvoicingBase)Factory.New(GetExpectedBusinessObjectType());
				AssertEquals("Precondition: CalculateTaxAtHeaderLevel", expectAdjustment, InvoicingBase.ShouldFixTaxAmountOnHeader);
				AssertEquals("Precondition: Should have no lines", 0, InvoicingBase.Lines.Count);
				InvoicingBase.AH_RX_NKTransactionCurrency = tWD.RX_Code;
				TestObjectCreator.GST1.SetRateNumerator_ForTestOnly(5);

				AssertEquals("Precondition: CurrentCompany.LocalCurrency.Decimals", 0, GlbCompany.CurrentCompany.LocalCurrency.Decimals);
				AssertEquals("Precondition: Invoice.TransactionCurrency.Decimals", 0, InvoicingBase.TransactionCurrency.Decimals);

				InvoicingLineBase line1 = AddNewLine(InvoicingBase, 90m);
				AssertLineAmounts(line1, 90m, 5m);
				AssertHeaderAmounts(InvoicingBase, 90m, 5m); // 90 * 5% = 4.5 (Rounded to 5)

				InvoicingLineBase line2 = AddNewLine(InvoicingBase, 110m);
				AssertLineAmounts(line1, 90m, 5m);
				AssertLineAmounts(line2, 110m, expectAdjustment ? 5m : 6m);
				AssertHeaderAmounts(InvoicingBase, 200m, expectAdjustment ? 10m : 11m); // 200 * 5% = 10
																						// Normally would be 6, but the biggest line is adjusted against the headers GST Amount

				InvoicingLineBase line3 = AddNewLine(InvoicingBase, 130m);
				AssertLineAmounts(line1, 90m, 5m);
				AssertLineAmounts(line2, 110m, 6m);
				AssertLineAmounts(line3, 130m, expectAdjustment ? 6m : 7m); // 330 * 5% = 16.5 (Rounded to 17)
				AssertHeaderAmounts(InvoicingBase, 330m, expectAdjustment ? 17m : 18m);
				// Normally would be 7, but the biggest line is adjusted against the headers GST Amount

				InvoicingBase.Lines.Remove(line3);
				AssertLineAmounts(line1, 90m, 5m);
				AssertLineAmounts(line2, 110m, expectAdjustment ? 5m : 6m);
				AssertHeaderAmounts(InvoicingBase, 200m, expectAdjustment ? 10m : 11m); // 200 * 5% = 10
			}
			finally
			{
				GlbCompany.CurrentCompany.LocalCurrency.RX_SubUnitRatio = originalSubUnitRatio;
				GlbCompany.CurrentCompany.GC_IsGSTRegistered = originalIsGSTRegistered;
			}
		}

		public void TestBalancingLineTaxAmountWhenTaxCalculatedAtLineLevel()
		{
			ZInt originalSubUnitRatio = GlbCompany.CurrentCompany.LocalCurrency.RX_SubUnitRatio;
			bool originalIsGSTRegistered = GlbCompany.CurrentCompany.GC_IsGSTRegistered;

			GlbCompany.CurrentCompany.LocalCurrency.RX_SubUnitRatio = 100;
