				InvoicingBase.Lines.Remove(line3);
				AssertLineAmounts(line1, 90m, 5m);
				AssertLineAmounts(line2, 110m, 6m);
				AssertHeaderAmounts(InvoicingBase, 200m, 11m);
			}
			finally
			{
				GlbCompany.CurrentCompany.LocalCurrency.RX_SubUnitRatio = originalSubUnitRatio;
				GlbCompany.CurrentCompany.GC_IsGSTRegistered = originalIsGSTRegistered;
			}
		}

		public void TestRecalculateHeaderAmounts()
		{
			InvoicingLineBase line1 = AddNewLine(InvoicingBase, 203m);
			AssertHeaderAmounts(InvoicingBase, 203m, 203m, 20.3m);

			InvoicingBase.AH_InvoiceAmount = 0m;
			InvoicingBase.AH_LocalExTaxAmount = 0m;
			InvoicingBase.AH_LocalTaxAmount = 0m;
			AssertHeaderAmounts(InvoicingBase, 0m, 0m, 0m);
			InvoicingBase.RecalculateHeaderAmounts_ForTestOnly();

			if (ShouldSupportHeaderAmountRecalculationFromLinesAmounts)
			{
				AssertHeaderAmounts(InvoicingBase, 203m, 203m, 20.3m);
				Factory.Save();

				BusinessObjectFactory newFactory = new BusinessObjectFactory();
				newFactory.RefreshEnabled = false;
				InvoicingBase headerInNewFactory = newFactory.Load<InvoicingBase>(InvoicingBase.PK);
				AssertHeaderAmounts(headerInNewFactory, 203m, 203m, 20.3m);

				line1.AL_OSExTaxAmount = 100m;
				TestObjectCreator.AttachChargeToAPLine(line1);
				headerInNewFactory.RecalculateHeaderAmounts_ForTestOnly();
				AssertHeaderAmounts(headerInNewFactory, 203m, 203m, 20.3m);

				AssertHeaderAmounts(InvoicingBase, 100m, 100m, 10m);
				line1.AL_OSExTaxAmount = 200;
				InvoicingBase.RecalculateHeaderAmounts_ForTestOnly();
				TestObjectCreator.AttachChargeToAPLine(line1);
				AssertHeaderAmounts(InvoicingBase, 200m, 200m, 20m);
			}
			else
			{
				AssertHeaderAmounts(InvoicingBase, 0m, 0m, 0m); // Header Amount should not be recalculated
			}
		}

		InvoicingLineBase AddNewLine(InvoicingBase invoicingBase, decimal oSExTaxAmount)
		{
			InvoicingLineBase line = (InvoicingLineBase)invoicingBase.Lines.AddNew();
			line.GenericCharge = TestObjectCreator.CC1.PK;
			TestObjectCreator.AttachJobToAPLine(line);
			line.AL_AT = TestObjectCreator.GST1.PK;
			AssertEquals("Line.TaxRate", TestObjectCreator.GST1.AT_Code, line.TaxRate.AT_Code);
			line.AL_OSExTaxAmount = oSExTaxAmount;
			TestObjectCreator.AttachChargeToAPLine(line);
			line.AL_AG = TestObjectCreator.GLHeader1.PK;
			return line;
		}

		void AssertLineAmounts(InvoicingLineBase line, decimal oSExTaxAmount, decimal oSTaxAmount)
		{
			AssertEquals("Line.AL_OSExTaxAmount", oSExTaxAmount, line.AL_OSExTaxAmount);
			AssertEquals("Line.AL_OSTaxAmount", oSTaxAmount, line.AL_OSTaxAmount);
			AssertEquals("Line.AL_OverseasTotal", oSExTaxAmount + oSTaxAmount, line.AL_OverseasTotal);
		}

		void AssertHeaderAmounts(InvoicingBase header, decimal oSExTaxAmount, decimal oSTaxAmount)
		{
			AssertEquals("Header.AH_OSExTaxAmount", oSExTaxAmount, header.AH_OSExTaxAmount);
			AssertEquals("Header.AH_OSTaxAmount", oSTaxAmount, header.AH_OSTaxAmount);
			AssertEquals("Header.AH_OSTotalAmount", oSExTaxAmount + oSTaxAmount, header.AH_OSTotalAmount);
		}

		void AssertHeaderAmounts(InvoicingBase header, decimal invoiceAmount, decimal localExTaxAmount, decimal localTaxAmount)
		{
			AssertEquals("Header.AH_InvoiceAmount", invoiceAmount * header.Multiplier_ForTestOnly, header.AH_InvoiceAmount);
			AssertEquals("Header.AH_LocalExTaxAmount", localExTaxAmount, header.AH_LocalExTaxAmount);
			AssertEquals("Header.AH_LocalTaxAmount", localTaxAmount, header.AH_LocalTaxAmount);
			AssertEquals("Header.AH_OSTotalAmount", localExTaxAmount + localTaxAmount, header.AH_LocalTotalAmount);
		}

