			var testInvoicingBase = Factory.NewWithValidTestData(GetExpectedBusinessObjectType()) as InvoicingBase;
			testInvoicingBase.AH_OH = newOrganisation.PK;
			testInvoicingBase.AH_Ledger = LedgerTypes.AccountsPayable;

			try
			{
				var cost = testInvoicingBase.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
				cost.E6_AC_ChargeCode = TestObjectCreator.CC1.PK;
				cost.E6_ApportionmentMethod = "SHP";
				cost.E6_OSCostAmount = 30m;
				cost.ApportionmentCharges[0].JR_OSCostAmt = 30m;
				cost.ApportionmentCharges[1].JR_OSCostAmt = 0m;

				testInvoicingBase.GSTInclusiveAmounts = false;
				var testInvoicingLineBase = (InvoicingLineBase)testInvoicingBase.Lines.AddNew();
				testInvoicingBase.ImportSingleCost(cost, testInvoicingLineBase);
				Assert(!testInvoicingBase.GSTInclusiveAmountNeedUpdate);

				AssertEquals("The GSTInclusiveAmount should be the same as AL_OverseasTotal", testInvoicingBase.Lines[0].AL_OverseasTotal, testInvoicingBase.Lines[0].GSTInclusiveAmount);

				testInvoicingBase.GSTInclusiveAmounts = true;
				testInvoicingLineBase = (InvoicingLineBase)testInvoicingBase.Lines.AddNew();
				testInvoicingBase.ImportSingleCost(cost, testInvoicingLineBase);
				Assert(!testInvoicingBase.GSTInclusiveAmountNeedUpdate);

				AssertEquals("The GSTInclusiveAmount should be the same as AL_OverseasTotal", testInvoicingBase.Lines[1].AL_OverseasTotal, testInvoicingBase.Lines[1].GSTInclusiveAmount);
			}
			finally
			{
				testInvoicingBase.ClearApportionmentJobMutexes();
			}
		}

		public void TestIsDisbursementOrFinal()
		{
			InvoicingBase testInvoicingBase = Factory.NewWithValidTestData(GetExpectedBusinessObjectType()) as InvoicingBase;

			testInvoicingBase.IsDisbursementOrFinal = false;
			AssertEquals("AH_TransactionCategory should be 'FIN'.", "FIN", testInvoicingBase.AH_TransactionCategory);

			testInvoicingBase.IsDisbursementOrFinal = true;
			AssertEquals("AH_TransactionCategory should be 'DBT'.", "DBT", testInvoicingBase.AH_TransactionCategory);

			testInvoicingBase.AH_TransactionCategory = "CUR";
			AssertEquals("IsDisbursementOrFinal should be false.", false, testInvoicingBase.IsDisbursementOrFinal);

			testInvoicingBase.AH_TransactionCategory = "";
			AssertEquals("IsDisbursementOrFinal should be false.", false, testInvoicingBase.IsDisbursementOrFinal);

			testInvoicingBase.AH_TransactionCategory = "DBT";
			AssertEquals("IsDisbursementOrFinal should be true.", true, testInvoicingBase.IsDisbursementOrFinal);
		}

		public void TestAH_TransactionCategoryWhenIsDisbursementOrFinal_IsSet()
		{
			var invoicingBase = Factory.NewWithValidTestData(GetExpectedBusinessObjectType()) as InvoicingBase;
			if (invoicingBase.AH_Ledger == LedgerTypes.AccountsReceivable)
			{
				invoicingBase.AH_RX_NKTransactionCurrency = GlbCompany.CurrentCompany.LocalCurrency.RX_Code;

				Assert("Precondition: invoice is a local currency one", invoicingBase.IsLocalCurrencyTransaction_ForTestOnly);

				invoicingBase.IsDisbursementOrFinal = false;
				AssertEquals(InvoiceTypesList.Codes.FinalInvoice, invoicingBase.AH_TransactionCategory);

				invoicingBase.IsDisbursementOrFinal = true;
				AssertEquals(InvoiceTypesList.Codes.DisbursementInvoice, invoicingBase.AH_TransactionCategory);

				invoicingBase.AH_RX_NKTransactionCurrency = TestObjectCreator.USD.RX_Code;

				Assert("Precondition: invoice is a foreign currency one", !invoicingBase.IsLocalCurrencyTransaction_ForTestOnly);

				invoicingBase.IsDisbursementOrFinal = false;
				AssertEquals(InvoiceTypesList.Codes.ForeignCurrencyInvoice, invoicingBase.AH_TransactionCategory);

				invoicingBase.IsDisbursementOrFinal = true;
				AssertEquals(InvoiceTypesList.Codes.DisbursementInForeignCurrency, invoicingBase.AH_TransactionCategory);
			}
			else
			{
				Assert("IsDisbursementOrFinal flag is only available to Misc AR invoice", true);
			}
		}

		public void TestAH_TransactionCategoryWhenAH_RX_NKTransactionCurrency_IsSet()
		{
			var invoicingBase = Factory.NewWithValidTestData(GetExpectedBusinessObjectType()) as InvoicingBase;
			if (invoicingBase.AH_Ledger == LedgerTypes.AccountsReceivable)
			{
				invoicingBase.IsDisbursementOrFinal = false;

				invoicingBase.AH_RX_NKTransactionCurrency = GlbCompany.CurrentCompany.LocalCurrency.RX_Code;
				AssertEquals(InvoiceTypesList.Codes.FinalInvoice, invoicingBase.AH_TransactionCategory);

				invoicingBase.AH_RX_NKTransactionCurrency = TestObjectCreator.USD.RX_Code;
				AssertEquals(InvoiceTypesList.Codes.ForeignCurrencyInvoice, invoicingBase.AH_TransactionCategory);

				invoicingBase.IsDisbursementOrFinal = true;

				invoicingBase.AH_RX_NKTransactionCurrency = GlbCompany.CurrentCompany.LocalCurrency.RX_Code;
				AssertEquals(InvoiceTypesList.Codes.DisbursementInvoice, invoicingBase.AH_TransactionCategory);

				invoicingBase.AH_RX_NKTransactionCurrency = TestObjectCreator.USD.RX_Code;
				AssertEquals(InvoiceTypesList.Codes.DisbursementInForeignCurrency, invoicingBase.AH_TransactionCategory);
			}
			else
			{
				Assert("IsDisbursementOrFinal flag is only available to Misc AR invoice", true);
			}
		}

		public void TestAH_TransactionCategory_ForJobRelatedInvoices()
		{
			var invoicingBase = Factory.NewWithValidTestData(GetExpectedBusinessObjectType()) as InvoicingBase;
			invoicingBase.AH_TransactionCategory = InvoiceTypesList.Codes.FreightInvoice;
			invoicingBase.AH_JH = ZGuid.NewZGuid();
			invoicingBase.AH_RX_NKTransactionCurrency = TestObjectCreator.USD.RX_Code;
			AssertEquals("Transaction Category has not changed since the invoice is job related", InvoiceTypesList.Codes.FreightInvoice, invoicingBase.AH_TransactionCategory);

			if (invoicingBase.AH_Ledger == LedgerTypes.AccountsReceivable)
			{
				invoicingBase.AH_JH = ZGuid.Empty;
				invoicingBase.AH_RX_NKTransactionCurrency = GlbCompany.CurrentCompany.LocalCurrency.RX_Code;
				AssertEquals("Transaction Category should be set to FIN according to logic for AR misc non disbursement Invoice", InvoiceTypesList.Codes.FinalInvoice, invoicingBase.AH_TransactionCategory);

				invoicingBase.AH_RX_NKTransactionCurrency = TestObjectCreator.USD.RX_Code;
				AssertEquals("Transaction Category should be set to CUR according to logic for AR misc non disbursement Invoice", InvoiceTypesList.Codes.ForeignCurrencyInvoice, invoicingBase.AH_TransactionCategory);
			}
			else
			{
				Assert("Only applicable for AR Misc invoices", true);
			}
		}
		#region Test Invoicing Levels

		public virtual void TestLevelAuthorization()
		{
			bool isLevelsApplicable = InvoicingBase.AH_Ledger == LedgerTypes.AccountsReceivable &&
				(InvoicingBase.AH_TransactionType == TransactionTypes.CreditNote ||
				InvoicingBase.AH_TransactionType == TransactionTypes.AdjustmentNote);

			bool isApplicableAdjustmentNote = isLevelsApplicable && InvoicingBase.AH_TransactionType == TransactionTypes.AdjustmentNote;

			Env.Security.CreditAdjustmentNotePostingApprovalFirstLevelApproval.IsAllowed = false;
			Env.Security.CreditAdjustmentNotePostingApprovalSecondLevelApproval.IsAllowed = false;
			if (isApplicableAdjustmentNote)
			{
				AssertCorrectAuthorisationRequired(500, false, false, null, false, false);
				AssertCorrectAuthorisationRequired(-500, false, false, null, false, true);
			}
			else
			{
				AssertCorrectAuthorisationRequired(500, false, false, null, false, isLevelsApplicable);
			}

			Env.Security.CreditAdjustmentNotePostingApprovalFirstLevelApproval.IsAllowed = false;
			Env.Security.CreditAdjustmentNotePostingApprovalSecondLevelApproval.IsAllowed = true;
			if (isApplicableAdjustmentNote)
			{
				AssertCorrectAuthorisationRequired(1500, false, false, null, false, false);
				AssertCorrectAuthorisationRequired(-1500, false, false, null, false, true);
			}
			else
			{
				AssertCorrectAuthorisationRequired(1500, false, false, null, false, isLevelsApplicable);
			}

			Env.Security.CreditAdjustmentNotePostingApprovalFirstLevelApproval.IsAllowed = true;
			Env.Security.CreditAdjustmentNotePostingApprovalSecondLevelApproval.IsAllowed = false;
			if (isApplicableAdjustmentNote)
			{
				AssertCorrectAuthorisationRequired(5000, false, false, null, false, false);
				AssertCorrectAuthorisationRequired(-5000, false, false, null, false, true);
			}
			else
			{
				AssertCorrectAuthorisationRequired(5000, false, false, null, false, isLevelsApplicable);
			}

			Env.Security.CreditAdjustmentNotePostingApprovalFirstLevelApproval.IsAllowed = true;
			Env.Security.CreditAdjustmentNotePostingApprovalSecondLevelApproval.IsAllowed = true;
			if (isApplicableAdjustmentNote)
			{
				AssertCorrectAuthorisationRequired(15000, false, false, null, false, false);
				AssertCorrectAuthorisationRequired(-15000, false, false, null, false, true);
			}
			else
			{
				AssertCorrectAuthorisationRequired(15000, false, false, null, false, isLevelsApplicable);
			}

			var setting = new AuthorizationModeAndSettings();
			var valuesForTest = setting.AuthorisationSettings;
			var upTo1000 = valuesForTest.AddNew();
			upTo1000.Amount = 1000;
			upTo1000.AuthorisationRequirement = AuthorisationCodes.NoApprovalRequired;
			upTo1000.Range = RangeCodes.UpTo;
			var upTo2000 = valuesForTest.AddNew();
			upTo2000.Amount = 2000;
			upTo2000.AuthorisationRequirement = AuthorisationCodes.FirstApprovalRequiredOnly;
			upTo2000.Range = RangeCodes.UpTo;
			var above2000 = valuesForTest.AddNew();
			above2000.Amount = 2000;
			above2000.AuthorisationRequirement = AuthorisationCodes.SecondApprovalRequiredOnly;
			above2000.Range = RangeCodes.Above;

			AccountingConfigurationRegistry.Instance.ReceivableAuthorizationModeAndSettings.SetValue(Guid.Empty, GlbBranch.CurrentBranch.PK.ToGuid(), GlbDepartment.CurrentDepartment.PK.ToGuid(), setting);

			Env.Security.CreditAdjustmentNotePostingApprovalFirstLevelApproval.IsAllowed = false;
			Env.Security.CreditAdjustmentNotePostingApprovalSecondLevelApproval.IsAllowed = false;
			if (isApplicableAdjustmentNote)
			{
				AssertCorrectAuthorisationRequired(500, false, false, upTo1000, false, false);
				AssertCorrectAuthorisationRequired(1000, false, false, upTo1000, false, false);

				AssertCorrectAuthorisationRequired(1500, true, false, upTo2000, true, false);
				AssertCorrectAuthorisationRequired(2000, true, false, upTo2000, true, false);

				AssertCorrectAuthorisationRequired(2001, false, true, above2000, true, false);
				AssertCorrectAuthorisationRequired(7000, false, true, above2000, true, false);

				AssertCorrectAuthorisationRequired(-500, false, false, upTo1000, false, true);
				AssertCorrectAuthorisationRequired(-1000, false, false, upTo1000, false, true);

				AssertCorrectAuthorisationRequired(-1500, true, false, upTo2000, true, true);
				AssertCorrectAuthorisationRequired(-2000, true, false, upTo2000, true, true);

				AssertCorrectAuthorisationRequired(-2001, false, true, above2000, true, true);
				AssertCorrectAuthorisationRequired(-7000, false, true, above2000, true, true);
			}
			else
			{
				AssertCorrectAuthorisationRequired(500, false, false, upTo1000, false, isLevelsApplicable);
				AssertCorrectAuthorisationRequired(1000, false, false, upTo1000, false, isLevelsApplicable);

				//using (EnvProxy.Instance.CurrentUser.SetIsControllerOverrideForTesting(false))
				//{
				//	AssertCorrectAuthorisationRequired(1500, true, false, UpTo2000, true, IsLevelsApplicable);
				//}

				AssertCorrectAuthorisationRequired(1500, true, false, upTo2000, true, isLevelsApplicable);

				AssertCorrectAuthorisationRequired(2000, true, false, upTo2000, true, isLevelsApplicable);

				AssertCorrectAuthorisationRequired(2001, false, true, above2000, true, isLevelsApplicable);
				AssertCorrectAuthorisationRequired(7000, false, true, above2000, true, isLevelsApplicable);
			}

			Env.Security.CreditAdjustmentNotePostingApprovalFirstLevelApproval.IsAllowed = false;
			Env.Security.CreditAdjustmentNotePostingApprovalSecondLevelApproval.IsAllowed = true;
			if (isApplicableAdjustmentNote)
			{
				AssertCorrectAuthorisationRequired(500, false, false, upTo1000, false, false);
				AssertCorrectAuthorisationRequired(1000, false, false, upTo1000, false, false);

				AssertCorrectAuthorisationRequired(1500, true, false, upTo2000, true, false);
				AssertCorrectAuthorisationRequired(2000, true, false, upTo2000, true, false);

				AssertCorrectAuthorisationRequired(2001, false, true, above2000, false, false);
				AssertCorrectAuthorisationRequired(7000, false, true, above2000, false, false);

				AssertCorrectAuthorisationRequired(-500, false, false, upTo1000, false, true);
				AssertCorrectAuthorisationRequired(-1000, false, false, upTo1000, false, true);

				AssertCorrectAuthorisationRequired(-1500, true, false, upTo2000, true, true);
				AssertCorrectAuthorisationRequired(-2000, true, false, upTo2000, true, true);

				AssertCorrectAuthorisationRequired(-2001, false, true, above2000, false, true);
				AssertCorrectAuthorisationRequired(-7000, false, true, above2000, false, true);
			}
			else
			{
				AssertCorrectAuthorisationRequired(500, false, false, upTo1000, false, isLevelsApplicable);
				AssertCorrectAuthorisationRequired(1000, false, false, upTo1000, false, isLevelsApplicable);

				AssertCorrectAuthorisationRequired(1500, true, false, upTo2000, true, isLevelsApplicable);
				AssertCorrectAuthorisationRequired(2000, true, false, upTo2000, true, isLevelsApplicable);

				AssertCorrectAuthorisationRequired(2001, false, true, above2000, false, isLevelsApplicable);
				AssertCorrectAuthorisationRequired(7000, false, true, above2000, false, isLevelsApplicable);
			}

			Env.Security.CreditAdjustmentNotePostingApprovalFirstLevelApproval.IsAllowed = true;
			Env.Security.CreditAdjustmentNotePostingApprovalSecondLevelApproval.IsAllowed = false;
			if (isApplicableAdjustmentNote)
			{
				AssertCorrectAuthorisationRequired(500, false, false, upTo1000, false, false);
				AssertCorrectAuthorisationRequired(1000, false, false, upTo1000, false, false);

				AssertCorrectAuthorisationRequired(1500, true, false, upTo2000, false, false);
				AssertCorrectAuthorisationRequired(2000, true, false, upTo2000, false, false);

				AssertCorrectAuthorisationRequired(2001, false, true, above2000, true, false);
				AssertCorrectAuthorisationRequired(7000, false, true, above2000, true, false);

				AssertCorrectAuthorisationRequired(-500, false, false, upTo1000, false, true);
				AssertCorrectAuthorisationRequired(-1000, false, false, upTo1000, false, true);

				AssertCorrectAuthorisationRequired(-1500, true, false, upTo2000, false, true);
				AssertCorrectAuthorisationRequired(-2000, true, false, upTo2000, false, true);

				AssertCorrectAuthorisationRequired(-2001, false, true, above2000, true, true);
				AssertCorrectAuthorisationRequired(-7000, false, true, above2000, true, true);
			}
			else
			{
				AssertCorrectAuthorisationRequired(500, false, false, upTo1000, false, isLevelsApplicable);
				AssertCorrectAuthorisationRequired(1000, false, false, upTo1000, false, isLevelsApplicable);

				AssertCorrectAuthorisationRequired(1500, true, false, upTo2000, false, isLevelsApplicable);
				AssertCorrectAuthorisationRequired(2000, true, false, upTo2000, false, isLevelsApplicable);

				AssertCorrectAuthorisationRequired(2001, false, true, above2000, true, isLevelsApplicable);
				AssertCorrectAuthorisationRequired(7000, false, true, above2000, true, isLevelsApplicable);
			}

			Env.Security.CreditAdjustmentNotePostingApprovalFirstLevelApproval.IsAllowed = true;
			Env.Security.CreditAdjustmentNotePostingApprovalSecondLevelApproval.IsAllowed = true;
			if (isApplicableAdjustmentNote)
			{
				AssertCorrectAuthorisationRequired(500, false, false, upTo1000, false, false);
				AssertCorrectAuthorisationRequired(1000, false, false, upTo1000, false, false);

				AssertCorrectAuthorisationRequired(1500, true, false, upTo2000, false, false);
				AssertCorrectAuthorisationRequired(2000, true, false, upTo2000, false, false);

				AssertCorrectAuthorisationRequired(2001, false, true, above2000, false, false);
				AssertCorrectAuthorisationRequired(7000, false, true, above2000, false, false);

				AssertCorrectAuthorisationRequired(-500, false, false, upTo1000, false, true);
				AssertCorrectAuthorisationRequired(-1000, false, false, upTo1000, false, true);

				AssertCorrectAuthorisationRequired(-1500, true, false, upTo2000, false, true);
				AssertCorrectAuthorisationRequired(-2000, true, false, upTo2000, false, true);

				AssertCorrectAuthorisationRequired(-2001, false, true, above2000, false, true);
				AssertCorrectAuthorisationRequired(-7000, false, true, above2000, false, true);
			}
			else
			{
				AssertCorrectAuthorisationRequired(500, false, false, upTo1000, false, isLevelsApplicable);
				AssertCorrectAuthorisationRequired(1000, false, false, upTo1000, false, isLevelsApplicable);

				AssertCorrectAuthorisationRequired(1500, true, false, upTo2000, false, isLevelsApplicable);
				AssertCorrectAuthorisationRequired(2000, true, false, upTo2000, false, isLevelsApplicable);

				AssertCorrectAuthorisationRequired(2001, false, true, above2000, false, isLevelsApplicable);
				AssertCorrectAuthorisationRequired(7000, false, true, above2000, false, isLevelsApplicable);
			}
		}

