		public void TestImportJobChargesIntoInvoiceValidatesOriginalLineAfterImport()
		{
			TestObjectCreator creator = new TestObjectCreator(Factory);

			Charge charge = creator.Job1.Charges.AddNew();
			charge.JR_AC = creator.CC1.PK;
			charge.JR_OSCostAmt = 50m;

			Factory.Save();

			APInvoice invoice = Factory.New<APInvoice>();
			APInvoiceLine line1 = (APInvoiceLine)invoice.Lines.AddNew();
			line1.Validation.ValidateAll();
			AssertHasErrors("Should have an error on Charge", line1.AL_ACInfo);

			invoice.ImportJobChargesIntoInvoice(creator.Job1.Charges.ToArray<Charge>(), line1, false);
			AssertNoErrors("Should have no errors on Charge", line1.AL_ACInfo);
		}

		public void TestImportJobChargesIntoInvoiceGSTAmountSignAndTaxDate()
		{
			TestObjectCreator creator = new TestObjectCreator(Factory);

			Charge charge = creator.Job1.Charges.AddNew();
			charge.JR_OH_CostAccount = creator.AALSHI.PK;
			charge.JR_AC = creator.CC1.PK;
			charge.JR_OSCostAmt = -50m;
			charge.JR_AT_CostGSTRate = creator.GST1.PK;
			Factory.Save();

			AssertEquals("Prerequisite: charge's tax amount", -5m, charge.JR_OSCostGSTAmt_Calc);

			APCreditNote creditNote = Factory.New<APCreditNote>();
			creditNote.AH_OH = creator.AALSHI.PK;
			APCreditNoteLine line1 = (APCreditNoteLine)creditNote.Lines.AddNew();

			creditNote.ImportJobChargesIntoInvoice(creator.Job1.Charges.ToArray<Charge>(), line1, false);

			AssertEquals("Line's tax amount", 5m, line1.AL_OSTaxAmount);
			AssertEquals("AL_AT", creator.GST1.PK, line1.AL_AT);
			AssertEquals("AL_TaxDate", ZDate.Today, line1.AL_TaxDate);

			var expectedDate = ZDate.Today.AddDays(3);
			charge.JR_CostTaxDate = expectedDate;
			creditNote.ImportJobChargesIntoInvoice(creator.Job1.Charges.ToArray<Charge>(), line1, false);

			AssertEquals("Line's tax amount", 5m, line1.AL_OSTaxAmount);
			AssertEquals("AL_AT", creator.GST1.PK, line1.AL_AT);
			AssertEquals("AL_TaxDate", expectedDate, line1.AL_TaxDate);
		}

		public void TestCostReferenceAppendOperationWhenJobChargeImported()
		{
			TestObjectCreator creator = new TestObjectCreator(Factory);

			Charge charge = creator.Job1.Charges.AddNew();
			charge.JR_OH_CostAccount = creator.AALSHI.PK;
			charge.JR_AC = creator.CC1.PK;
			charge.JR_OSCostAmt = -50m;
			charge.JR_CostReference = "Test Ref #1";
			charge.JR_AT_CostGSTRate = creator.GST1.PK;

			Charge charge2 = creator.Job1.Charges.AddNew();
			charge2.JR_OH_CostAccount = creator.AALSHI.PK;
			charge2.JR_AC = creator.CC2.PK;
			charge2.JR_OSCostAmt = -50m;
			charge2.JR_CostReference = "";
			charge2.JR_AT_CostGSTRate = creator.GST1.PK;

			Charge charge3 = creator.Job1.Charges.AddNew();
			charge3.JR_OH_CostAccount = creator.AALSHI.PK;
			charge3.JR_AC = creator.CC2.PK;
			charge3.JR_OSCostAmt = -150m;
			charge3.JR_CostReference = "Test Ref #3";
			charge3.JR_AT_CostGSTRate = creator.GST1.PK;
			Factory.Save();

			Factory.Save();

			ZQuery filter = new ZQuery(ViewGenericChargeSchema.PK, creator.CC1.PK);
			var genericTransactionCharge = Factory.LoadTop1<AccGenericCharge>(filter);
			var description1 = genericTransactionCharge.VC_Description;

			filter = new ZQuery(ViewGenericChargeSchema.PK, creator.CC2.PK);
			genericTransactionCharge = Factory.LoadTop1<AccGenericCharge>(filter);
			var description2 = genericTransactionCharge.VC_Description;

			AssertEquals("Prerequisite: charge's tax amount", -5m, charge.JR_OSCostGSTAmt_Calc);

			APCreditNote creditNote = Factory.New<APCreditNote>();
			creditNote.AH_OH = creator.AALSHI.PK;

			APCreditNoteLine line1 = (APCreditNoteLine)creditNote.Lines.AddNew();
			creditNote.ImportJobChargesIntoInvoice(creator.Job1.Charges.ToArray<Charge>(), line1, false);
			AssertEquals("Line's tax amount", description1 + " {Test Ref #1}", line1.AL_Desc);

			APCreditNoteLine line2 = (APCreditNoteLine)creditNote.Lines[1];
			AssertEquals("Line's tax amount", description2, line2.AL_Desc);

			APCreditNoteLine line3 = (APCreditNoteLine)creditNote.Lines[2];
			AssertEquals("Line's tax amount", description2 + " {Test Ref #3}", line3.AL_Desc);
		}

		public void TestFixedPlaceOfSupplyWhenJobChargeImported_NonEmpty()
		{
			using (PlaceOfSupplyHelper.SetPOSTypesEnabled_ForTestOnly(PlaceOfSupplyTypes.State.Code, PlaceOfSupplyTypes.PredefinedRule.Code))
			using (GlbCompany.CurrentCompany.TemporarilySetCountry(Core.Constants.CountryCodes.India))
			using (TestObjectCreator.TemporarilyCustomiseTransactionNumberGenerator(GlbCompany.CurrentCompany, TestObjectCreator.CreateTestPrefixAndSequenceNumberCustomisation()))
			{
				var fposList = PlaceOfSupplyListProvider.GetPlaceOfSupplyList(GlbCompany.CurrentCompany);
				var fposCode1 = fposList[0].Code;
				var fposCodeType1 = PlaceOfSupplyListProvider.GetPlaceTypeFromPlaceCode(GlbCompany.CurrentCompany, fposCode1);

				var creator = new TestObjectCreator(Factory);

				//Non Empty Place of Supply
				var charge = creator.Job1.Charges.AddNew();
				charge.JR_OH_CostAccount = creator.AALSHI.PK;
				charge.JR_AC = creator.CC1.PK;
				charge.JR_OSCostAmt = -50m;
				charge.JR_CostPlaceOfSupply = fposCode1;
				charge.JR_AT_CostGSTRate = creator.GST1.PK;

				var charge2 = creator.Job1.Charges.AddNew();
				charge2.JR_OH_CostAccount = creator.AALSHI.PK;
				charge2.JR_AC = creator.CC2.PK;
				charge2.JR_OSCostAmt = -50m;
				charge2.JR_CostPlaceOfSupply = fposCode1;
				charge2.JR_AT_CostGSTRate = creator.GST1.PK;

				Factory.Save();

				AssertEquals("charge place of supply", fposCode1, charge.JR_CostPlaceOfSupply);
				AssertEquals("charge place of supply Type", fposCodeType1, charge.JR_CostPlaceOfSupplyType);
				AssertEquals("charge place of supply", fposCode1, charge2.JR_CostPlaceOfSupply);
				AssertEquals("charge place of supply Type", fposCodeType1, charge.JR_CostPlaceOfSupplyType);

				var creditNote = Factory.New<APCreditNote>();
				creditNote.AH_OH = creator.AALSHI.PK;

				var line1 = (APCreditNoteLine)creditNote.Lines.AddNew();
				creditNote.ImportJobChargesIntoInvoice(creator.Job1.Charges.ToArray<Charge>(), line1, false);
				AssertEquals("line place of supply", fposCode1, creditNote.Lines[0].AL_PlaceOfSupply);
				AssertEquals("line place of supply Type", fposCodeType1, creditNote.Lines[0].AL_PlaceOfSupplyType);
				AssertEquals("line place of supply", fposCode1, creditNote.Lines[1].AL_PlaceOfSupply);
				AssertEquals("line place of supply Type", fposCodeType1, creditNote.Lines[1].AL_PlaceOfSupplyType);
			}
		}

