		public void TestImportJobChargesIntoInvoice_WithCreditorInvoicedExchangeRateProvider()
		{
			if (!TryPrepareCreditorInvoicedExchangeRateTestData(out Charge sourceCharge, out InvoicingBase invoicingBase, out AccDraftInvoiceHeader draftInvoice))
			{
				Assert("Not Applicable", true);
				return;
			}

			var targetLine = invoicingBase.Lines[0];

			Factory.ServiceContainer.AddService(new CreditorInvoicedExchangeRateProvider(draftInvoice));

			invoicingBase.ImportJobChargesIntoInvoice(new [] { sourceCharge }, targetLine);

			AssertEquals(TestObjectCreator.USD.Code, targetLine.AL_RX_NKTransactionCurrency);
			AssertEquals(5m, targetLine.AL_ExchangeRate);
			AssertEquals(-200m * targetLine.Multiplier_ForTestOnly, targetLine.AL_OSExTaxAmount);
			AssertEquals(-40m * targetLine.Multiplier_ForTestOnly, targetLine.AL_LocalExTaxAmount);
		}

		public void TestImportJobChargesIntoInvoice_WithoutCreditorInvoicedExchangeRateProvider()
		{
			if (!TryPrepareCreditorInvoicedExchangeRateTestData(out Charge sourceCharge, out InvoicingBase invoicingBase, out AccDraftInvoiceHeader draftInvoice))
			{
				Assert("Not Applicable", true);
				return;
			}

			var targetLine = invoicingBase.Lines[0];

			invoicingBase.ImportJobChargesIntoInvoice(new[] { sourceCharge, sourceCharge }, targetLine);

			AssertEquals(TestObjectCreator.USD.Code, targetLine.AL_RX_NKTransactionCurrency);
			AssertEquals(2m, targetLine.AL_ExchangeRate);
			AssertEquals(-200m * targetLine.Multiplier_ForTestOnly, targetLine.AL_OSExTaxAmount);
			AssertEquals(-100m * targetLine.Multiplier_ForTestOnly, targetLine.AL_LocalExTaxAmount);
		}

		bool TryPrepareCreditorInvoicedExchangeRateTestData(out Charge sourceCharge, out InvoicingBase invoicingBase, out AccDraftInvoiceHeader draftInvoice)
		{
			invoicingBase = Factory.NewWithValidTestData(GetExpectedBusinessObjectType()) as InvoicingBase;
			invoicingBase.AH_RX_NKTransactionCurrency = CurrencyCodes.Australia;
			invoicingBase.AH_OSExTaxAmount = 200m;
			invoicingBase.AH_LocalExTaxAmount = 200m;
			invoicingBase.AH_ExchangeRate = 1m;
			invoicingBase.AH_OH = TestObjectCreator.AALSHI.PK;

			if (!CreditorInvoicedExchangeRateProvider.IsCreditorInvoicedExchangeRateApplicable(invoicingBase))
			{
				sourceCharge = null;
				draftInvoice = null;
				return false;
			}

			var targetLine = (InvoicingLineBase)invoicingBase.Lines.AddNew();
			targetLine.AL_RX_NKTransactionCurrency = CurrencyCodes.Australia;
			targetLine.AL_ExchangeRate = 1m;
			targetLine.AL_OSExTaxAmount = 200m;
			targetLine.AL_OSTaxAmount = 200m;
			targetLine.AL_OH = TestObjectCreator.AALSHI.PK;

			var shipment = TestObjectCreator.CreateShipment("S00001001");
			var job = TestObjectCreator.CreateJob(shipment, createWithMutex: false);
			sourceCharge = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "Charge 1", TestObjectCreator.USD, 200m, TestObjectCreator.AALSHI);
			sourceCharge.JR_OSCostExRate = 2m;

			draftInvoice = TestObjectCreator.CreateDraftInvoice("00001001", "R00001001", TestObjectCreator.AALSHI.PK, 100m, 0m, TestObjectCreator.AUD.Code);
			TestObjectCreator.AddDraftInvocieExchangeRate(draftInvoice, TestObjectCreator.USD, 5m);
			TestObjectCreator.AddDraftInvocieExchangeRate(draftInvoice, TestObjectCreator.GBP, 10m);

			return true;
		}

		[ExpectNoExceptions()]
		public void TestImportAllApportionmentsFromCosting()
		{
			APInvoice invoice = Factory.New<APInvoice>();

			JobConsolCost cost1 = Factory.NewWithValidTestData<JobConsolCost>();
			ApportionSplitCharge charge1 = cost1.ApportionmentCharges.AddNew();
			charge1.JR_OSCostAmt = 50m;

			JobConsolCost cost2 = Factory.NewWithValidTestData<JobConsolCost>();
			ApportionSplitCharge charge2 = cost2.ApportionmentCharges.AddNew();
			charge2.JR_OSCostAmt = 150m;

			invoice.ConsolCosting.ConsolCosts.Add(cost1);
			invoice.ConsolCosting.ConsolCosts.Add(cost2);

			invoice.ImportAllApportionmentsFromCosting();

			invoice.ConsolCosting.ConsolCosts.Remove(cost1);
			invoice.ImportAllApportionmentsFromCosting();
			invoice.ConsolCosting.ConsolCosts.Remove(cost2);
			invoice.ImportAllApportionmentsFromCosting();

			AssertEquals("No remaining invoice lines for the last deleted Consol cost", 0, invoice.Lines.Count);
		}

		[ExpectNoExceptions()]
		public void TestImportAllApportionmentsFromCostingDoesNotThrowStackOverFlowException()
		{
			APInvoice invoice = Factory.New<APInvoice>();
			try
			{
				var consol1 = TestObjectCreator.CreateConsol(consolNum: "C0001");
				consol1.Shipments.AddNew();

				var consol2 = TestObjectCreator.CreateConsol(consolNum: "C0002");
				consol2.Shipments.AddNew();

				var consolCost = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol1);
				consolCost.E6_AC_ChargeCode = TestObjectCreator.CC1.PK;
				consolCost.E6_OSCostAmount = 15M;

				var oldApportionmentCharge = consolCost.ApportionmentCharges[0];

				invoice.ImportAllApportionmentsFromCosting();
				AssertEquals("There should be one invoice line", 1, invoice.Lines.Count);
				var oldInvoiceLine = invoice.Lines[0];
				AssertEquals(oldApportionmentCharge.PK, oldInvoiceLine.ApportionmentChargeImportedFrom.PK);
				AssertEquals(consolCost.PK, oldInvoiceLine.ImportedApportionmentID);

				AssertEquals(consolCost.Consol.JK_UniqueConsignRef, consol1.JK_UniqueConsignRef);
				Assert(!oldApportionmentCharge.IsDeleted);

				consolCost.SetE6_ParentIDAndE6_ParentTableCodeTogether(consol2.PK, JobConsolSchema.Constants.Prefix);

				AssertEquals("Consol number is changed", consolCost.Consol.JK_UniqueConsignRef, consol2.JK_UniqueConsignRef);
				Assert(oldApportionmentCharge.IsDeleted);

				invoice.ImportAllApportionmentsFromCosting();
				Assert(oldInvoiceLine.IsDeleted);
				AssertEquals("There should be one invoice line", 1, invoice.Lines.Count);
				var newInvoiceLine = invoice.Lines[0];
				AssertEquals(consolCost.ApportionmentCharges[0].PK, newInvoiceLine.ApportionmentChargeImportedFrom.PK);
				AssertEquals(consolCost.PK, newInvoiceLine.ImportedApportionmentID);
			}
			finally
			{
				invoice.ReleaseAllMutexOnInvoice();
			}
		}

		public void TestImportChargesIntoInvoiceWithRemoveFirstCharge()
		{
			var jobCharges = new List<Charge>();
			jobCharges.Add(Factory.New<Charge>());
			jobCharges.Add(Factory.New<Charge>());

			jobCharges[0].JR_OSCostAmt = 222M;
			jobCharges[0].JR_LocalCostAmt = 333M;
			jobCharges[0].JR_JH = ZGuid.NewZGuid();
			jobCharges[1].JR_JH = ZGuid.NewZGuid();

			APInvoice invoice = Factory.New<APInvoice>();
			APInvoiceLine line1 = (APInvoiceLine)invoice.Lines.AddNew();
			invoice.ImportJobChargesIntoInvoice(jobCharges.ToArray<Charge>(), line1);

			AssertEquals("One charge should be deleted", 2, invoice.Lines.Count);
			AssertNotEquals("AL_JH must not be set for the first line", jobCharges[0].JR_JH, invoice.Lines[0].AL_JH);
			AssertEquals("AL_JH must be set for the next lines", jobCharges[1].JR_JH, invoice.Lines[1].AL_JH);
			AssertEquals("AL_OSExTaxAmount must be equal JR_LocalCostAmt", 333M, line1.AL_OSExTaxAmount);

			invoice = Factory.New<APInvoice>();
			line1 = (APInvoiceLine)invoice.Lines.AddNew();
			invoice.ImportJobChargesIntoInvoice(jobCharges.ToArray<Charge>(), line1, false);

			AssertEquals("One charge should be deleted", 2, invoice.Lines.Count);
			AssertEquals("AL_JH must not be set for the first line", jobCharges[0].JR_JH, invoice.Lines[0].AL_JH);
			AssertEquals("AL_JH must be set for the next lines", jobCharges[1].JR_JH, invoice.Lines[1].AL_JH);
			AssertEquals("AL_OSExTaxAmount must be equal JR_LocalCostAmt", 333M, line1.AL_OSExTaxAmount);
		}

