			jobCharges[0].JR_JH = ZGuid.NewZGuid();
			jobCharges[0].JR_AT_CostGSTRate = TestObjectCreator.GST1.PK;
			jobCharges[0].JR_OSCostAmt = 100M;
			jobCharges[0].JR_OSCostExRate = 2M;

			AssertEquals("AUD", invoice.AH_RX_NKTransactionCurrency);
			AssertEquals(1M, invoice.AH_ExchangeRate);

			AssertEquals("USD", jobCharges[0].JR_RX_NKCostCurrency);
