			Assert(!invoice.AH_PostedToEFT);

			invoice.ImportJobChargesIntoInvoice(jobCharges.ToArray<Charge>(), line);

			AssertEquals("InvoiceLine's Tax nust be equals charge's Tax", 10M, line.AL_OSTaxAmount);
		}

		public void TestImportChargesIntoInvoiceWithDifferentCashAdvanceCurrencyNotEqualsToInvoiceCurrency()
		{
			var errorMessage = @"The related job charge has a paid Cash Advance in a different currency to the currency of the invoice being posted. Unable to apply Cash Advance to the invoice. Please correct the currency of the Invoice, or cancel and re-create the Cash Advance to post this charge.
Invoice currency is USD | Cash advance currency of FRT | International Freight is EUR";

			AssertExceptionThrown<CannotGenerateCashAdvanceJournalException>(errorMessage, () =>
			{
				AccountingConfigurationRegistry.Instance.EnablePayablesCashAdvanceFunctionality.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, true);

				var job = TestObjectCreator.CreateJob(TestObjectCreator.LocalClient, 1.0M, TestObjectCreator.Agent, 1.0M);
				var jobCharge = job.Charges.AddNew();

				var jobCharges = new List<Charge>();
				jobCharges.Add(jobCharge);
				jobCharge.JR_AC = TestObjectCreator.FRT.PK;
				jobCharge.JR_RX_NKCostCurrency = "USD";
				jobCharge.JR_OH_CostAccount = TestObjectCreator.Creditor1.PK;
				jobCharge.JR_AT_CostGSTRate = TestObjectCreator.GST1.PK;
				jobCharge.JR_OSCostAmt = 100M;
				jobCharge.JR_OSCostExRate = 1M;
				jobCharge.JR_IsAPCashAdvance = true;

				var cah = TestObjectCreator.CreateCashAdvanceRequestHeader(job, TestObjectCreator.Creditor1, LedgerTypes.AccountsPayable, 100M, 100M, "EUR", CashAdvanceStatusCodes.RequestHeader.Paid);
				var cal = TestObjectCreator.CreateCashAdvanceRequestLine(cah.PK, 100M, 100M, CashAdvanceStatusCodes.RequestLine.Paid);
				jobCharge.JR_CAL_APLine = cal.PK;

				var invoice = TestObjectCreator.CreateAPInvoice<APInvoice>("AP0001", TestObjectCreator.USD, 1.0M, oSExTaxAmount: 100M, oSTaxAmount: 0M, oSExtraTaxAmount: 0M, localExTaxAmount: 100M, localTaxAmount: 0M, localExtraTaxAmount: 0M, TestObjectCreator.Creditor1);
				invoice.ImportJobChargesIntoInvoice(jobCharges.ToArray<Charge>(), invoice.Lines[0]);
			});
		}

		public void TestPreImportJobChargesValidation()
		{
			AccountingConfigurationRegistry.Instance.EnablePayablesCashAdvanceFunctionality.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, true);

			var job = TestObjectCreator.CreateJob(TestObjectCreator.LocalClient, 1.0M, TestObjectCreator.Agent, 1.0M);
			var jobCharge = job.Charges.AddNew();

			var jobCharges = new List<Charge>();
			jobCharges.Add(jobCharge);
			jobCharge.JR_AC = TestObjectCreator.FRT.PK;
			jobCharge.JR_RX_NKCostCurrency = "USD";
			jobCharge.JR_OH_CostAccount = TestObjectCreator.Creditor1.PK;
			jobCharge.JR_AT_CostGSTRate = TestObjectCreator.GST1.PK;
			jobCharge.JR_OSCostAmt = 100M;
			jobCharge.JR_OSCostExRate = 1M;
			jobCharge.JR_IsAPCashAdvance = true;

			var cashRequestHeader = TestObjectCreator.CreateCashAdvanceRequestHeader(job, TestObjectCreator.Creditor1, LedgerTypes.AccountsPayable, 100M, 100M, "EUR", CashAdvanceStatusCodes.RequestHeader.Paid);
			var cashRequestLine = TestObjectCreator.CreateCashAdvanceRequestLine(cashRequestHeader.PK, 100M, 100M, CashAdvanceStatusCodes.RequestLine.Paid);
			jobCharge.JR_CAL_APLine = cashRequestLine.PK;

			var invoice = TestObjectCreator.CreateAPInvoice<APInvoice>("AP0001", TestObjectCreator.USD, 1M, 100M, 0M, 0M, 100M, 0M, 0M, TestObjectCreator.Creditor1);
			var errorMessage = @"The related job charge has a paid Cash Advance in a different currency to the currency of the invoice being posted. Unable to apply Cash Advance to the invoice. Please correct the currency of the Invoice, or cancel and re-create the Cash Advance to post this charge.
Invoice currency is USD | Cash advance currency of FRT | International Freight is EUR";

			AssertExceptionThrown<CannotGenerateCashAdvanceJournalException>(errorMessage, () => invoice.PreImportJobChargesValidation(jobCharges.ToArray<Charge>()));
		}

