		void AssertImportAccrualsIntoInvoicePreLoadsChargesAndShipments(int count, int expectedDbHits)
		{
			AccrualCollection accruals = new AccrualCollection(Factory);

			for (int i = 0; i < count; i++)
			{
				CommonShipment shipment = Factory.NewWithValidTestData<CommonShipment>();
				Charge charge = Factory.NewWithValidTestData<Charge>();
				charge.ChargeCode.FillWithValidTestData();
				charge.Job.JH_ParentID = shipment.PK;
				charge.Job.JH_ParentTableCode = JobShipmentSchema.Constants.Prefix;
				Accrual accrual = accruals.AddNew();
				charge.JR_AL_APLine = accrual.PK;
				accrual.AL_AC = charge.JR_AC;
				accrual.AL_JH = charge.Job.PK;
				accrual.AL_GE = charge.JR_GE;
				accrual.AL_GB = charge.JR_GB;
				accrual.AL_AG = TestObjectCreator.GLHeader1.PK;
			}

			Factory.Save();

			BusinessObjectFactory newFactory = new BusinessObjectFactory();

			APInvoice invoice = newFactory.New<APInvoice>();
			APInvoiceLine line1 = (APInvoiceLine)invoice.Lines.AddNew();

			int chargeHitsBefore = newFactory.GetTableHitCount(JobChargeSchema.Constants.TableName);
			int shipmentHitsBefore = newFactory.GetTableHitCount(JobShipmentSchema.Constants.TableName);

			invoice.ImportAccrualsIntoInvoice(accruals.ToArray<Accrual>(), line1);

			int chargeHitsAfter = newFactory.GetTableHitCount(JobChargeSchema.Constants.TableName);
			int shipmentHitsAfter = newFactory.GetTableHitCount(JobShipmentSchema.Constants.TableName);

			int expectedChargeDbHits = expectedDbHits;
			AssertEquals(string.Format("Expected {0} charge hit(s) with test batch size 5 and FetchHintManagerAdding more hits", expectedChargeDbHits), expectedChargeDbHits, chargeHitsAfter - chargeHitsBefore);
			AssertEquals(string.Format("Expected {0} shipment hit(s) with test batch size 5", expectedDbHits), expectedDbHits, shipmentHitsAfter - shipmentHitsBefore);
		}

		public void TestSetIncludeInTheBatch()
		{
			var invoicingBase1 = Factory.NewWithValidTestData(GetExpectedBusinessObjectType()) as InvoicingBase;
			invoicingBase1.AH_OutstandingAmount = 30;
			invoicingBase1.AH_GSTAmount = 7;
			invoicingBase1.AH_OSTotal = 79;
			invoicingBase1.AH_InvoiceAmount = 70;
			invoicingBase1.AH_WithholdingTax = 2;
			Assert(!invoicingBase1.IncludeInTheBatch);

			var batchHeader1 = Factory.NewWithValidTestData<InvoiceBatchHeader>();
			var collection1 = batchHeader1.Line;
			collection1.Add(invoicingBase1);

			Assert(invoicingBase1.IncludeInTheBatch);
			AssertInvoiceBatchAmountsWithInvoiceAmounts(batchHeader1, new List<InvoicingBase>() { invoicingBase1 });

			var invoicingBase2 = Factory.NewWithValidTestData(GetExpectedBusinessObjectType()) as InvoicingBase;
			invoicingBase2.AH_OutstandingAmount = 120;
			invoicingBase2.AH_GSTAmount = 10;
			invoicingBase2.AH_OSTotal = 120;
			invoicingBase2.AH_InvoiceAmount = 100;
			invoicingBase2.AH_WithholdingTax = 0;

			collection1.Add(invoicingBase2);
			AssertInvoiceBatchAmountsWithInvoiceAmounts(batchHeader1, new List<InvoicingBase>() { invoicingBase1, invoicingBase2 });

			invoicingBase1.IncludeInTheBatch = false;
			AssertInvoiceBatchAmountsWithInvoiceAmounts(batchHeader1, new List<InvoicingBase>() { invoicingBase2 });

			invoicingBase1.IncludeInTheBatch = true;
			AssertInvoiceBatchAmountsWithInvoiceAmounts(batchHeader1, new List<InvoicingBase>() { invoicingBase1, invoicingBase2 });
		}

		void AssertInvoiceBatchAmountsWithInvoiceAmounts(InvoiceBatchHeader batch, IEnumerable<InvoicingBase> invoices)
		{
			AssertEquals(invoices.Sum(x => x.AH_OutstandingAmount), batch.AH_OutstandingAmount);
			AssertEquals(invoices.Sum(x => x.AH_GSTAmount), batch.AH_GSTAmount);
			AssertEquals(invoices.Sum(x => x.AH_OSTotal), batch.AH_OSTotal);
			AssertEquals(invoices.Sum(x => x.AH_InvoiceAmount), batch.AH_InvoiceAmount);
			AssertEquals(invoices.Sum(x => x.AH_WithholdingTax), batch.AH_WithholdingTax);
		}

