		public void TestHeaderLevelCalculationWithoutUsingLocalTaxAmountAppliedToOSExtraTaxCorrectly_Reversed_forItaly()
		{
			if (InvoicingBase.AH_Ledger == LedgerTypes.AccountsReceivable)
			{
				var registry = AccountingConfigurationRegistry.Instance;
				using (GlbCompany.CurrentCompany.TemporarilySetCountry(CountryCodes.Italy))
				using (registry.CalculateTaxAtHeaderLevel.SetTemporaryValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, true))
				using (registry.UseLocalExTaxAmountWhileCalculatingLocalTaxAmount.SetTemporaryValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, false))
				{
					var currency = TestObjectCreator.EUR;
					var spvTax = TestObjectCreator.VATSPV;

					var originalTransaction = TestObjectCreator.CreateInvoice(GetExpectedBusinessObjectType(), currency, 1M, TestObjectCreator.ABIGAS);
					var originalTransactionMultiplier = originalTransaction.Multiplier_ForTestOnly;

					var line = TestObjectCreator.CreateInvoiceLine(originalTransaction, 300.89M, currency, 1M, null, false);
					line.AL_AT = spvTax.PK;
					AssertInvoiceAmounts("After adding line 1:", originalTransaction, 300.89M, 0M, -66.20M);

					line = TestObjectCreator.CreateInvoiceLine(originalTransaction, 397.48M, currency, 1M, null, false);
					line.AL_AT = spvTax.PK;
					AssertInvoiceAmounts("After adding line 2:", originalTransaction, 698.37M, 0M, -153.64M);

					line = TestObjectCreator.CreateInvoiceLine(originalTransaction, 398.16M, currency, 1M, null, false);
					line.AL_AT = spvTax.PK;
					AssertInvoiceAmounts("After adding line 3:", originalTransaction, 1096.53M, 0M, -241.24M);

					Factory.Save();

					originalTransaction.GenerateReverseTransactionCore_ForTestOnly(false);

					var reverseTransaction = (InvoicingBase)originalTransaction.ReverseTransaction;
					var reverseTransactionMultiplier = reverseTransaction.Multiplier_ForTestOnly;

					var multiplier = 1;
					if (originalTransaction.GetType() == reverseTransaction.GetType())
					{
						multiplier = -1;
					}
					AssertInvoiceAmounts("After adding line 3:", reverseTransaction, 1096.53M * multiplier, 0M, -241.24M * multiplier);

					for (int i = 0; i < originalTransaction.Lines.Count; i++)
					{
						AssertEquals(originalTransaction.Lines[0].AL_GSTVATExtra * originalTransactionMultiplier, reverseTransaction.Lines[0].AL_GSTVATExtra * reverseTransactionMultiplier * multiplier);
					}
				}
			}
			else
			{
				Assert("Not applicable", true);
			}
		}

