		public void TestHeaderLevelCalculationUsingLocalTaxAmountAppliedToOSAndLocalExtraTaxCorrectly()
		{
			InvoicingLineBase[] lines = null;
			if (InvoicingBase.AH_Ledger == LedgerTypes.AccountsReceivable)
			{
				var registry = AccountingConfigurationRegistry.Instance;
				using (registry.CalculateTaxAtHeaderLevel.SetTemporaryValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, true))
				using (registry.UseLocalExTaxAmountWhileCalculatingLocalTaxAmount.SetTemporaryValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, true))
				{
					var currency = TestObjectCreator.EUR;
					var invoice = TestObjectCreator.CreateInvoice(GetExpectedBusinessObjectType(), currency, 1M, TestObjectCreator.ABIGAS);
					lines = new InvoicingLineBase[6];

					lines[0] = TestObjectCreator.CreateInvoiceLine(invoice, 77.72M, currency, 1M, null, false);
					lines[1] = TestObjectCreator.CreateInvoiceLine(invoice, 23.76M, currency, 1M, null, false);
					lines[2] = TestObjectCreator.CreateInvoiceLine(invoice, 11.98M, currency, 1M, null, false);
					lines[3] = TestObjectCreator.CreateInvoiceLine(invoice, 11.98M, currency, 1M, null, false);
					lines[4] = TestObjectCreator.CreateInvoiceLine(invoice, 26.98M, currency, 1M, null, false);
					lines[5] = TestObjectCreator.CreateInvoiceLine(invoice, 16.92M, currency, 1M, null, false);

					lines.ForEach(l => l.AL_AT = TestObjectCreator.VATSPV.PK);

					AssertInvoiceLineAmounts(0, 77.72M, 0, 17.08M, -17.08M);
					AssertInvoiceLineLocalAmounts(0, 77.72M, 0, 17.08M, -17.08M);
					AssertInvoiceLineAmounts(1, 23.76M, 0, 5.23M, -5.23M);
					AssertInvoiceLineLocalAmounts(1, 23.76M, 0, 5.23M, -5.23M);
					AssertInvoiceLineAmounts(2, 11.98M, 0, 2.64M, -2.64M);
					AssertInvoiceLineLocalAmounts(2, 11.98M, 0, 2.64M, -2.64M);
					AssertInvoiceLineAmounts(3, 11.98M, 0, 2.64M, -2.64M);
					AssertInvoiceLineLocalAmounts(3, 11.98M, 0, 2.64M, -2.64M);
					AssertInvoiceLineAmounts(4, 26.98M, 0, 5.94M, -5.94M);
					AssertInvoiceLineLocalAmounts(4, 26.98M, 0, 5.94M, -5.94M);
					AssertInvoiceLineAmounts(5, 16.92M, 0, 3.72M, -3.72M);
					AssertInvoiceLineLocalAmounts(5, 16.92M, 0, 3.72M, -3.72M);

					AssertInvoiceAmounts(null, invoice, 169.34M, 0M, -37.25M);
					AssertInvoiceLocalAmounts(invoice, 169.34M, 0M, -37.25M);

					currency = TestObjectCreator.USD;
					var exchange = 1.0722M;
					invoice = TestObjectCreator.CreateInvoice(GetExpectedBusinessObjectType(), currency, exchange, TestObjectCreator.ABIGAS);
					lines = new InvoicingLineBase[11];

					for (int i = 0; i < 11; ++i)
					{
						lines[i] = TestObjectCreator.CreateInvoiceLine(invoice, 45M, currency, exchange, null, false);
						lines[i].AL_AT = TestObjectCreator.VATSPV.PK;
					}

					for (int i = 0; i < 10; ++i)
					{
						AssertInvoiceLineAmounts(i, 45M, 0, 9.90M, -9.90M);
						AssertInvoiceLineLocalAmounts(i, 41.97M, 0, 9.23M, -9.23M);
					}
					AssertInvoiceLineAmounts(10, 45M, 0, 9.90M, -9.90M);
					AssertInvoiceLineLocalAmounts(10, 41.97M, 0, 9.27M, -9.27M);

					AssertInvoiceAmounts(null, invoice, 495M, 0M, -108.90M);
					AssertInvoiceLocalAmounts(invoice, 461.67M, 0M, -101.57M);
				}
			}
			else
			{
				Assert("Not applicable", true);
			}

			void AssertInvoiceLineAmounts(int lineNr, ZDecimal expectedOSExTaxAmount, ZDecimal expectedOSTaxAmount, ZDecimal expectedOSGSTAmount, ZDecimal expectedOSExtraTaxAmount)
			{
				AssertEquals($"After adding line {lineNr}: InvoiceLine OS amount", expectedOSExTaxAmount, lines[lineNr].AL_OSExTaxAmount);
				AssertEquals($"After adding line {lineNr}: InvoiceLine OS TAX amount", expectedOSTaxAmount, lines[lineNr].AL_OSTaxAmount);
				AssertEquals($"After adding line {lineNr}: InvoiceLine OS VAT amount", expectedOSGSTAmount, lines[lineNr].AL_OSGSTAmount);
				AssertEquals($"After adding line {lineNr}: InvoiceLine OS SPV tax amount", expectedOSExtraTaxAmount, lines[lineNr].AL_OSExtraTaxAmount);
			}

			void AssertInvoiceLineLocalAmounts(int lineNr, ZDecimal expectedOSExTaxAmount, ZDecimal expectedOSTaxAmount, ZDecimal expectedOSGSTAmount, ZDecimal expectedOSExtraTaxAmount)
			{
				AssertEquals($"After adding line {lineNr}: InvoiceLine Local amount", expectedOSExTaxAmount, lines[lineNr].AL_LocalExTaxAmount);
				AssertEquals($"After adding line {lineNr}: InvoiceLine Local TAX amount", expectedOSTaxAmount, lines[lineNr].AL_LocalTaxAmount);
				AssertEquals($"After adding line {lineNr}: InvoiceLine Local VAT amount", expectedOSGSTAmount, lines[lineNr].AL_LocalGSTAmount);
				AssertEquals($"After adding line {lineNr}: InvoiceLine Local SPV tax amount", expectedOSExtraTaxAmount, lines[lineNr].AL_LocalExtraTaxAmount);
			}
		}

