		public void TestAH_OSTaxAmountIsUpdatedWhenHeaderCurrencyIsChanged()
		{
			var header = (InvoicingBase)Factory.NewWithValidTestData(GetExpectedBusinessObjectType());

			if (header is TransactionPendingAllocation)
			{
				Assert("N/a", true);
				return;
			}

			AssertEquals("header currency was initialized with AUD value", TestObjectCreator.AUD.RX_Code, header.AH_RX_NKTransactionCurrency);
			AssertEquals("Only UpdateAH_OSExTaxAmount is called", 1, header.GetSumOfLinesCallAmount_ForTestOnly);

			var line = (InvoicingLineBase)header.Lines.AddNew();
			line.AL_AT = TaxRate2.PK;
			line.AL_AG = TestObjectCreator.GLHeader1.PK;
			line.AL_RX_NKTransactionCurrency = TestObjectCreator.USD.RX_Code;
			line.AL_ExchangeRate = 2m;
			line.AL_OSExTaxAmount = 100m;

			AssertEquals("PreCondition", TestObjectCreator.AUD.RX_Code, header.AH_RX_NKTransactionCurrency);
			AssertEquals("PreCondition", TestObjectCreator.AUD.RX_Code, header.Company.GC_RX_NKLocalCurrency);
			AssertEquals("PreCondition", TestObjectCreator.USD.RX_Code, line.AL_RX_NKTransactionCurrency);
			AssertEquals("PreCondition", 10m, line.AL_OSTaxAmount);
			AssertEquals("PreCondition", 5m, header.AH_OSTaxAmount);

			var nbGetSumOfLinesCallAmount_ForTestOnly = header.GetSumOfLinesCallAmount_ForTestOnly;
			header.AH_RX_NKTransactionCurrency = TestObjectCreator.USD.RX_Code;
			AssertNoErrors(header.AH_OSTotalAmountInfo);
			AssertEquals("AH_OSTaxAmount should be updated", 10m, header.AH_OSTaxAmount);
			AssertEquals(@"we expect 4 calls: UpdateAH_LocalExTaxAmount and UpdateAH_LocalTaxAmount are called because the line exchange rate is updated.
UpdateAH_OSExTaxAmount and UpdateAH_OSTaxAmount are called because the currency is updated.",
				nbGetSumOfLinesCallAmount_ForTestOnly + 4, header.GetSumOfLinesCallAmount_ForTestOnly);

			nbGetSumOfLinesCallAmount_ForTestOnly = header.GetSumOfLinesCallAmount_ForTestOnly;
			header.AH_RX_NKTransactionCurrency = TestObjectCreator.USD.RX_Code;
			AssertEquals("If value is not changed, only UpdateAH_OSExTaxAmount is called.", nbGetSumOfLinesCallAmount_ForTestOnly + 1, header.GetSumOfLinesCallAmount_ForTestOnly);
		}

		public void TestHeaderAmountsGetRecalculatedOnSaving()
		{
			if (ShouldSupportHeaderAmountRecalculationFromLinesAmounts)
			{
				InvoicingBase header = (InvoicingBase)Factory.NewWithValidTestData(GetExpectedBusinessObjectType());
				InvoicingLineBase line = (InvoicingLineBase)Factory.NewWithValidTestData(GetExpectedBusinessObjectLineType());
				line.AL_AT = TaxRate2.PK;
				line.AL_OSExTaxAmount = line.AL_LocalExTaxAmount = 100m;
				line.AL_LocalTaxAmount = 10m;
				line.AL_AG = TestObjectCreator.GLHeader1.PK;
				header.Lines.Add(line);

				header.AH_OSTotal = 44M;

				AssertEquals("Precondition: AH_OSTotal should be wrong for now", 44m, header.AH_OSTotal);

				Factory.Save();
				AssertEquals("AH_InvoiceAmount should be adjusted now", 100m, header.AH_InvoiceAmount * header.Multiplier_ForTestOnly);
				AssertEquals("AH_GSTAmount should be adjusted now", 10m, header.AH_GSTAmount * header.Multiplier_ForTestOnly);
				AssertEquals("AH_OSTotal should be adjusted now", 110m, header.AH_OSTotal * header.Multiplier_ForTestOnly);
			}
			else
			{
				Assert("Should run only for specific transaction types", true);
			}
		}

