		public void TestValidateAndFixConsolCostsMarkedAsImported()
		{
			var consol = TestObjectCreator.CreateConsol("C001");
			var shipment1 = TestObjectCreator.CreateShipment("S001", consol);
			var shipment2 = TestObjectCreator.CreateShipment("S002", consol);
			var job1 = TestObjectCreator.CreateJob(shipment1);
			var job2 = TestObjectCreator.CreateJob(shipment2);
			var consolCost1 = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC1, 100);
			var consolCost2 = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC2, 200);
			var consolCost3 = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC3, 300);
			var consolCost4 = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC4, 400);
			Factory.Save();

			var invoice = TestObjectCreator.CreateInvoice(typeof(APInvoice), TestObjectCreator.AUD, 1);
			var invoiceConsolCost1 = TestObjectCreator.CreateConsolCost(invoice, consol, TestObjectCreator.CC1, 100);
			invoiceConsolCost1.RelatedConsolCostPK = consolCost1.PK;

			var invoiceConsolCost2 = TestObjectCreator.CreateConsolCost(invoice, consol, TestObjectCreator.CC2, 200);
			invoiceConsolCost2.RelatedConsolCostPK = consolCost2.PK;

			var invoiceConsolCost3 = TestObjectCreator.CreateConsolCost(invoice, consol, TestObjectCreator.CC3, 300);
			invoiceConsolCost3.RelatedConsolCostPK = consolCost3.PK;
			invoice.ImportAllApportionmentsFromCosting();

			var invoiceConsolCost4 = TestObjectCreator.CreateConsolCost(invoice, consol, TestObjectCreator.CC4, 400);
			invoiceConsolCost4.RelatedConsolCostPK = consolCost4.PK;
			invoice.ImportAllApportionmentsFromCosting();

			AssertEquals(8, invoice.Lines.Count);
			foreach (InvoicingLineBase line in invoice.Lines)
			{
				AssertNotNull(line.OriginalJobCharge);
			}

			AssertEquals(4, invoice.ConsolCosting.ConsolCosts.Count);
			foreach (JobConsolCost consolCost in invoice.ConsolCosting.ConsolCosts)
			{
				Assert(consolCost.RelatedConsolCostPK.IsValid);
				AssertEquals(2, consolCost.ApportionmentCharges.Count);
				AssertNotNull(consolCost.ApportionmentCharges[0].RelatedApportionChargeFromDB);
				AssertNotNull(consolCost.ApportionmentCharges[1].RelatedApportionChargeFromDB);
			}

			//consol cost has no related cost
			invoiceConsolCost1.RelatedConsolCostPK = ZGuid.Empty;

			//consol cost has one apportion charge with null RelatedApportionChargeFromDB
			var importLine = invoice.Lines.Cast<InvoicingLineBase>().FirstOrDefault(x => x.OriginalJobCharge.PK == invoiceConsolCost2.ApportionmentCharges[0].RelatedApportionChargeFromDB.PK);
			importLine.OriginalJobCharge = null;
			invoiceConsolCost2.ApportionmentCharges[0].RelatedApportionChargeFromDB = null;

			//related consol cost apportion charges count is different
			consolCost3.ApportionmentCharges.AddNew();

			//consol cost has one apportion charge, whose RelatedApportionChargeFromDB is unlink with consol cost
			invoiceConsolCost4.ApportionmentCharges[0].RelatedApportionChargeFromDB.JR_E6 = ZGuid.Empty;
			foreach (JobConsolCost consolCost in invoice.ConsolCosting.ConsolCosts)
			{
				invoice.ValidateAndFixConsolCostsMarkedAsImported(consolCost);
			}

			AssertEquals(8, invoice.Lines.Count);
			foreach (InvoicingLineBase line in invoice.Lines)
			{
				AssertNull(line.OriginalJobCharge);
			}

			AssertEquals(4, invoice.ConsolCosting.ConsolCosts.Count);
			foreach (JobConsolCost consolCost in invoice.ConsolCosting.ConsolCosts)
			{
				Assert(!consolCost.RelatedConsolCostPK.IsValid);
				AssertEquals(2, consolCost.ApportionmentCharges.Count);
				AssertNull(consolCost.ApportionmentCharges[0].RelatedApportionChargeFromDB);
				AssertNull(consolCost.ApportionmentCharges[1].RelatedApportionChargeFromDB);
			}
		}

		public void TestValidateAndFixConsolCostsMarkedAsImportedWithNotUsedApportionCharge()
		{
			var consol = TestObjectCreator.CreateConsol("C001");
			var shipment1 = TestObjectCreator.CreateShipment("S001", consol);
			var shipment2 = TestObjectCreator.CreateShipment("S002", consol);
