			TestObjectCreator.CreateJob(shipment2);
			var consolCost = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC1, 100);
			Factory.Save();

			AssertEquals(2, consolCost.ApportionmentCharges.Count);
			consolCost.ApportionmentCharges[0].JR_IsUsedForApportionment = false;
			consolCost.ApportionmentCharges[1].JR_IsUsedForApportionment = true;
			Factory.Save();

			var invoice = TestObjectCreator.CreateInvoice(typeof(APInvoice), TestObjectCreator.AUD, 1);
			var invoiceConsolCost = TestObjectCreator.CreateConsolCost(invoice, consol, TestObjectCreator.CC1, 100);
			invoiceConsolCost.RelatedConsolCostPK = consolCost.PK;
			invoiceConsolCost.ApportionmentCharges[0].JR_IsUsedForApportionment = false;
			invoiceConsolCost.ApportionmentCharges[1].JR_IsUsedForApportionment = true;

			invoice.ImportAllApportionmentsFromCosting();

			AssertEquals(1, invoice.Lines.Count);
			AssertNotNull(invoice.Lines[0].OriginalJobCharge);

			AssertEquals(2, invoiceConsolCost.ApportionmentCharges.Count);
			AssertNull(invoiceConsolCost.ApportionmentCharges[0].RelatedApportionChargeFromDB);
			AssertNotNull(invoiceConsolCost.ApportionmentCharges[1].RelatedApportionChargeFromDB);

			invoice.ValidateAndFixConsolCostsMarkedAsImported(invoiceConsolCost);

			AssertEquals(1, invoice.Lines.Count);
			AssertNotNull(invoice.Lines[0].OriginalJobCharge);

			AssertEquals(2, invoiceConsolCost.ApportionmentCharges.Count);
			AssertNull(invoiceConsolCost.ApportionmentCharges[0].RelatedApportionChargeFromDB);
			AssertNotNull(invoiceConsolCost.ApportionmentCharges[1].RelatedApportionChargeFromDB);
		}

		public void TestValidateAndFixConsolCostsMarkedAsImportedWithDeletedRelatedConsolCost()
		{
			var consol = TestObjectCreator.CreateConsol("C001");
			var shipment = TestObjectCreator.CreateShipment("S001", consol);
			TestObjectCreator.CreateJob(shipment);
			var consolCost = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC1, 100);
			consolCost.ApportionmentCharges[0].JR_IsUsedForApportionment = true;
			Factory.Save();

			var invoice = TestObjectCreator.CreateInvoice(typeof(APInvoice), TestObjectCreator.AUD, 1);
			var invoiceConsolCost = TestObjectCreator.CreateConsolCost(invoice, consol, TestObjectCreator.CC1, 100);
			invoiceConsolCost.RelatedConsolCostPK = consolCost.PK;
			invoiceConsolCost.ApportionmentCharges[0].JR_IsUsedForApportionment = true;

			invoice.ImportAllApportionmentsFromCosting();

			AssertEquals(1, invoice.Lines.Count);
			AssertNotNull(invoice.Lines[0].OriginalJobCharge);

			AssertEquals(1, invoiceConsolCost.ApportionmentCharges.Count);
			AssertNotNull(invoiceConsolCost.ApportionmentCharges[0].RelatedApportionChargeFromDB);

			var newFactory = new BusinessObjectFactory();
			var newCharge = newFactory.Load<ApportionSplitCharge>(consolCost.ApportionmentCharges[0].PK);
			var newConsolCost = newFactory.Load<JobConsolCost>(consolCost.PK);
			newCharge.Delete();
			newConsolCost.Delete();
			newFactory.Save();

			invoice.ValidateAndFixConsolCostsMarkedAsImported(invoiceConsolCost);

			AssertEquals(1, invoice.Lines.Count);
			AssertNull(invoice.Lines[0].OriginalJobCharge);

			AssertEquals(1, invoiceConsolCost.ApportionmentCharges.Count);
			AssertNull(invoiceConsolCost.ApportionmentCharges[0].RelatedApportionChargeFromDB);
		}

		public void TestIsInvoiceApproving()
		{
			if (InvoicingBase.Ledger_ForTestOnly == LedgerTypes.UnapprovedPayableTransactions)
			{
				InvoicingBase.Lines.AddNew();
				foreach (InvoicingLineBase line in InvoicingBase.Lines)
				{
					line.AL_OSExTaxAmount = 1m;
					line.AL_AC = TestObjectCreator.CC1.PK;
					line.AL_JH = TestObjectCreator.Job1.PK;
					TestObjectCreator.CreateCharge(line);
				}
				UnapprovedTransactionConverter converter = new UnapprovedTransactionConverter(Factory);
				Factory.Save();
				AssertEquals("Before conversion", false, InvoicingBase.IsInvoiceApproving);
				Header = converter.ConvertToAP(InvoicingBase, false);
				AssertEquals("After conversion", true, InvoicingBase.IsInvoiceApproving);
			}
			else
			{
				AssertEquals("For not UA transaction", false, InvoicingBase.IsInvoiceApproving);
			}
		}

		public void TestIsSelfBillingInvoice()
		{
			var selfBillingCreditor = TestObjectCreator.Creditor1;
			selfBillingCreditor.CompanyData.OB_APCostsSelfBilled = true;

			var standardCreditor = TestObjectCreator.Creditor2;
			standardCreditor.CompanyData.OB_APCostsSelfBilled = false;

			Factory.Save();

			Header = (InvoicingBase)GetNewBusinessObject();

			if (InvoicingBase.AH_Ledger == LedgerTypes.AccountsReceivable)
			{
				Assert(InvoicingBase.AH_TransactionNumInfo.ReadOnly);
				AssertEquals("AH_ConsolidatedInvoiceRef should be ReadOnly for AP only", false, InvoicingBase.AH_ConsolidatedInvoiceRefInfo.ReadOnly);

				InvoicingBase.AH_TransactionCategory = InvoiceTypesList.Codes.SelfBillingInvoice;
				Assert("Should be a Self Billing Invoice (even in AR)", InvoicingBase.IsSelfBillingInvoice);
			}
			else if (InvoicingBase.AH_Ledger == LedgerTypes.AccountsPayable || InvoicingBase.AH_Ledger == LedgerTypes.UnapprovedPayableTransactions)
			{
				InvoicingBase.RefreshBinding();
				Assert(!InvoicingBase.AH_TransactionNumInfo.ReadOnly);
				InvoicingBase.AH_TransactionNum = "INVOICENUM";
				AssertEquals("AH_ConsolidatedInvoiceRef should be ReadOnly for AP only", true, InvoicingBase.AH_ConsolidatedInvoiceRefInfo.ReadOnly);

				InvoicingBase.AH_OH = selfBillingCreditor.PK;
				Assert(InvoicingBase.IsSelfBillingInvoice);
				AssertEquals("transactioncategory should be 'self billed costs'", Core.Constants.TransactionCategory.Codes.SelfBilling, InvoicingBase.AH_TransactionCategory);
				Assert("TRANSACTION number should be readonly when self billing - set by number fountain on saving", InvoicingBase.AH_TransactionNumInfo.ReadOnly);
				Assert("should set transactionnum to empty when self billing", InvoicingBase.AH_TransactionNum.IsEmpty);
				AssertEquals("AH_ConsolidatedInvoiceRef should be ReadOnly for AP only", true, InvoicingBase.AH_ConsolidatedInvoiceRefInfo.ReadOnly);

				InvoicingBase.IsSelfBillingInvoice = false;
				AssertEquals("transaction category should be 'Standard'", Core.Constants.TransactionCategory.Codes.Standard, InvoicingBase.AH_TransactionCategory);
				Assert("transaction number should be writable when not a self billing invoice", !InvoicingBase.AH_TransactionNumInfo.ReadOnly);
				InvoicingBase.AH_TransactionNum = "invoicenum";
				AssertEquals("AH_ConsolidatedInvoiceRef should be ReadOnly for AP only", true, InvoicingBase.AH_ConsolidatedInvoiceRefInfo.ReadOnly);

				InvoicingBase.IsSelfBillingInvoice = true;
				AssertEquals("transactioncategory should be 'self billed costs'", Core.Constants.TransactionCategory.Codes.SelfBilling, InvoicingBase.AH_TransactionCategory);
				Assert("TRANSACTION number should be readonly when self billing - set by number fountain on saving", InvoicingBase.AH_TransactionNumInfo.ReadOnly);
				Assert("should set transactionnum to empty when self billing", InvoicingBase.AH_TransactionNum.IsEmpty);
				AssertEquals("AH_ConsolidatedInvoiceRef should be ReadOnly for AP only", true, InvoicingBase.AH_ConsolidatedInvoiceRefInfo.ReadOnly);

				InvoicingBase.AH_OH = standardCreditor.PK;
				Assert("self billing invoice should default to false", !InvoicingBase.IsSelfBillingInvoice);
				AssertEquals("transactioncategory should be 'standard'", Core.Constants.TransactionCategory.Codes.Standard, InvoicingBase.AH_TransactionCategory);
				Assert("TRANSACTION number should be writable", !InvoicingBase.AH_TransactionNumInfo.ReadOnly);
				AssertEquals("AH_ConsolidatedInvoiceRef should be ReadOnly for AP only", true, InvoicingBase.AH_ConsolidatedInvoiceRefInfo.ReadOnly);

				InvoicingBase.AH_OH = selfBillingCreditor.PK;
				ZString nextSelfBillingInvoiceNumber = InvoicingBase.NumberFountainForSelfBillingInvoice_ForTestOnly.PeekPreliminary(InvoicingBase.Factory);
				InvoicingBase.Factory.Save();

				AssertEquals(nextSelfBillingInvoiceNumber, InvoicingBase.AH_TransactionNum);

				if (!InvoicingBase.AH_TransactionType.StartsWith(LedgerTypes.UnapprovedPayableTransactions))
				{
					Header = (InvoicingBase)GetNewBusinessObject();
					InvoicingBase.RefreshBinding();
					InvoicingBase.AH_TransactionNum = "invoicenum";
					InvoicingBase.IsSelfBillingInvoice = true;
					InvoicingBase.AH_OH = selfBillingCreditor.PK;
					InvoicingBase.SaveAsIncomplete();
					Assert("Transaction number should be readonly when self billing - also on incomplete invoices", InvoicingBase.AH_TransactionNumInfo.ReadOnly);
					AssertEquals("AH_ConsolidatedInvoiceRef should be ReadOnly for AP only", true, InvoicingBase.AH_ConsolidatedInvoiceRefInfo.ReadOnly);
				}
			}
		}

		public void TestAH_ConsolidatedInvoiceReadOnly()
		{
			if (InvoicingBase.AH_Ledger == LedgerTypes.AccountsPayable)
			{
				AssertEquals("AH_ConsolidatedInvoiceRef should be ReadOnly for AP transactions.", true, InvoicingBase.AH_ConsolidatedInvoiceRefInfo.ReadOnly);

				SetupForSaveAsIncomplete();
				InvoicingBase.SaveAsIncomplete();
				InvoicingBase incompleteInvoice = new BusinessObjectFactory().Load<InvoicingBase>(InvoicingBase.PK);
				incompleteInvoice.RestoreSavedData();
				AssertEquals("AH_ConsolidatedInvoiceRef should be ReadOnly for Incomplete transactions.", true, incompleteInvoice.AH_ConsolidatedInvoiceRefInfo.ReadOnly);
			}
			else if (InvoicingBase.AH_Ledger == LedgerTypes.UnapprovedPayableTransactions)
			{
				AssertEquals("AH_ConsolidatedInvoiceRef should not be ReadOnly for non AP transactions.", true, InvoicingBase.AH_ConsolidatedInvoiceRefInfo.ReadOnly);
			}
			else
			{
				AssertEquals("AH_ConsolidatedInvoiceRef should not be ReadOnly for non AP transactions.", false, InvoicingBase.AH_ConsolidatedInvoiceRefInfo.ReadOnly);
			}
		}

