			InvoicingBase.AH_InvoiceTerm = Core.Constants.InvoiceTerms.CashOnDelivery;
			InvoicingBase.AH_InvoiceTermDays = 0;
			InvoicingBase.AH_InvoiceDate = currentDate.AddDays(-1);
