		public void TestSetExchangeRateForInvoicePostingExchangeRateOption_EIT_NoProperExRateOption()
		{
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, ExchangeRateTypes.Code.BuyRate, 0.5m, ZDateTime.Today, ZDateTime.Today);
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, ExchangeRateTypes.Code.SellRate, 0.5m, ZDateTime.Today, ZDateTime.Today);

			InvoicingBase.AH_RX_NKTransactionCurrency = Core.Constants.CurrencyCodes.UnitedStates;
			InvoicingBase.AH_ExchangeRate = 0.3m;
			var line1 = InvoicingBase.Lines[0];
			var line2 = InvoicingBase.Lines[1];
			line1.FillWithValidTestData();
			line2.FillWithValidTestData();
			line1.AL_RX_NKTransactionCurrency = Core.Constants.CurrencyCodes.UnitedStates;
			line1.AL_ExchangeRate = 0.1m;
			line2.AL_RX_NKTransactionCurrency = GlbCompany.CurrentCompany.GC_RX_NKLocalCurrency;
			line2.AL_ExchangeRate = 0.2m;

			AssertNotEquals("Transaction header is with foreign currency", InvoicingBase.AH_RX_NKTransactionCurrency, GlbCompany.CurrentCompany.GC_RX_NKLocalCurrency);
			AssertEquals(0.3m, InvoicingBase.AH_ExchangeRate);
			AssertEquals(0.1m, line1.AL_ExchangeRate);
			AssertEquals(0.2m, line2.AL_ExchangeRate);

			InvoicingBase.SetExchangeRateForInvoicePostingExchangeRateOption(ExRateOption.EarliestOfInvoiceOrTaxDate.Code);

			AssertEquals(0.3m, InvoicingBase.AH_ExchangeRate);
			AssertEquals(0.1m, line1.AL_ExchangeRate);
			AssertEquals(0.2m, line2.AL_ExchangeRate);
		}

