		public void TestSetExchangeRateForInvoicePostingExchangeRateOption_EIT_LocalCurrency()
		{
			PrepareTestDataForSetExchangeRateForInvoicePostingExchangeRateOptionEIT();

			var line1 = InvoicingBase.Lines[0];
			var line2 = InvoicingBase.Lines[1];
			line1.FillWithValidTestData();
			line2.FillWithValidTestData();
			line1.AL_RX_NKTransactionCurrency = Core.Constants.CurrencyCodes.UnitedStates;
			line1.AL_ExchangeRate = 0.1m;
			line2.AL_RX_NKTransactionCurrency = Core.Constants.CurrencyCodes.Japan;
			line2.AL_ExchangeRate = 0.2m;

			AssertEquals("Transaction header is with local currency", InvoicingBase.AH_RX_NKTransactionCurrency, GlbCompany.CurrentCompany.GC_RX_NKLocalCurrency);
			AssertEquals(1m, InvoicingBase.AH_ExchangeRate);
			AssertEquals(0.1m, line1.AL_ExchangeRate);
			AssertEquals(0.2m, line2.AL_ExchangeRate);

			InvoicingBase.SetExchangeRateForInvoicePostingExchangeRateOption(ExRateOption.EarliestOfInvoiceOrTaxDate.Code);

