			AssertEquals(0.2m, line2.AL_ExchangeRate);

			InvoicingBase.SetExchangeRateForInvoicePostingExchangeRateOption(true, ExRateOption.EarliestOfInvoiceOrTaxDate.Code);

			AssertEquals(0.3m, InvoicingBase.AH_ExchangeRate);
