		public void TestRecalculateAH_JH()
		{
			Job job1 = Factory.NewJobWithValidTestDataForTesting<Job>();
			Job job2 = Factory.NewJobWithValidTestDataForTesting<Job>();

			InvoicingLineBase line1 = InvoicingBase.Lines[0];
			InvoicingLineBase line2 = InvoicingBase.Lines[1];
			line1.FillWithValidTestData();
			line2.FillWithValidTestData();
			line1.AL_AG = TestObjectCreator.GLHeader1.PK;
			line2.AL_AG = TestObjectCreator.GLHeader1.PK;
			line1.AL_JH = job1.PK;
			line2.AL_JH = job2.PK;
			InvoicingBase.AH_JH = job1.PK;
			TestObjectCreator.CreateJobCharge(line1, job1, TestObjectCreator.CC1, TestObjectCreator.AUD);
			TestObjectCreator.CreateJobCharge(line2, job2, TestObjectCreator.CC1, TestObjectCreator.AUD);
			Factory.Save();
			AssertEquals("Should become empty on save if the transaction is either AP INV or AP CRD, otherwise should be left intact.", ShouldRecalculateAH_JHOnSaving ? ZGuid.Empty : job1.PK, InvoicingBase.AH_JH);

			InvoicingBase header = (InvoicingBase)Factory.NewWithValidTestData(GetExpectedBusinessObjectType());
			header.Lines.AddNew();
			header.Lines.AddNew();

			header.Lines[0].AL_JH = job2.PK;
			header.Lines[1].AL_JH = job2.PK;
			header.Lines[0].AL_AG = TestObjectCreator.GLHeader1.PK;
			header.Lines[1].AL_AG = TestObjectCreator.GLHeader1.PK;
			TestObjectCreator.CreateJobCharge(header.Lines[0], job2, TestObjectCreator.CC1, TestObjectCreator.AUD);
			TestObjectCreator.CreateJobCharge(header.Lines[1], job2, TestObjectCreator.CC1, TestObjectCreator.AUD);
			Factory.Save();
			AssertEquals("Should be job2's PK since all lines are attached to the same job and the transaction is either AP INV or AP CRD, otherwise should be left intact.", ShouldRecalculateAH_JHOnSaving ? job2.PK : ZGuid.Empty, header.AH_JH);
		}

