		public void TestRecalculateAH_JH_LogWithPAToAPTransactionLineMonitor()
		{
			if (!InvoicingBase.IsAPInvoiceOrCreditNote)
			{
				Assert("Source InvoicingBase is not valid for this test.", true);
				return;
			}

			var job = Factory.NewJobWithValidTestDataForTesting<Job>();
			var line = InvoicingBase.Lines[0];
			line.FillWithValidTestData();

			var monitor = new PAToAPTransactionLineMonitor(InvoicingBase);
			Factory.ServiceContainer.AddService(monitor);

			AssertContains("Precondition",
@"Last 10 counts of lines:
N/A", monitor.GetInfo().Trim());

			InvoicingBase.AH_JH = job.PK;
			Factory.Save();

			AssertContains(
@"Last 10 counts of lines:
RecalculateAH_JH: 2", monitor.GetInfo().Trim());
		}

