		void TestSaveAsIncompleteSavesEDocsFactory(bool inDB)
		{
			InvoicingBase.AH_PostDate = ZDateTime.Now;
			if (InvoicingBase.AH_Ledger == LedgerTypes.AccountsPayable)
			{
				if (inDB)
				{
					SetupForSaveasIncompleteAlreadyInDB();
				}
				else
				{
					SetupForSaveasIncompleteNotInDB();
				}

				AssertEquals("Pre-condition: no eDocs", 0, InvoicingBase.DocManagerInfo.AllEDocs.Count);
				InvoicingBase.DocManagerInfo.AddFileOrDocument(new byte[] { 0, 1, 2, 3 }, "test", "TXT");
				AssertEquals("One eDoc just added", 1, InvoicingBase.DocManagerInfo.AllEDocs.Count);

				var unrelatedBizOInInvoiceFactory = InvoicingBase.Factory.NewJobWithValidTestDataForTesting<JobHeader>();

				InvoicingBase.SaveAsIncomplete();

				BusinessObjectFactory newFactory = new BusinessObjectFactory();
				InvoicingBase savedInvoicingBase = newFactory.Load<InvoicingBase>(InvoicingBase.PK);
				AssertEquals("eDoc should be saved", 1, savedInvoicingBase.DocManagerInfo.AllEDocs.Count);
				AssertNull("An unrelated Business Object in the Invoice Factory should not be saved when SaveAsIncomplete", newFactory.Load<JobHeader>(unrelatedBizOInInvoiceFactory.PK));

				savedInvoicingBase.DocManagerInfo.AddFileOrDocument(new byte[] { 1, 2, 3, 4 }, "test2", "TXT");
				AssertEquals("Second eDoc just added", 2, savedInvoicingBase.DocManagerInfo.AllEDocs.Count);

				savedInvoicingBase.SaveAsIncomplete();

				newFactory = new BusinessObjectFactory();
				savedInvoicingBase = newFactory.Load<InvoicingBase>(InvoicingBase.PK);
				AssertEquals("eDocs should be saved", 2, savedInvoicingBase.DocManagerInfo.AllEDocs.Count);
				AssertNull("An unrelated Business Object in the Invoice Factory should not be saved when SaveAsIncomplete", newFactory.Load<JobHeader>(unrelatedBizOInInvoiceFactory.PK));

				((BusinessObject)savedInvoicingBase.DocManagerInfo.Files[0]).Delete();
				AssertEquals("eDoc should be removed", 1, savedInvoicingBase.DocManagerInfo.AllEDocs.Count);
				savedInvoicingBase.SaveAsIncomplete();

				newFactory = new BusinessObjectFactory();
				savedInvoicingBase = newFactory.Load<InvoicingBase>(InvoicingBase.PK);
				AssertEquals("eDoc should be removed", 1, savedInvoicingBase.DocManagerInfo.AllEDocs.Count);
				AssertNull("An unrelated Business Object in the Invoice Factory should not be saved when SaveAsIncomplete", newFactory.Load<JobHeader>(unrelatedBizOInInvoiceFactory.PK));

				newFactory.Save();
				newFactory = new BusinessObjectFactory();
				savedInvoicingBase = newFactory.Load<InvoicingBase>(InvoicingBase.PK);
				AssertEquals("eDoc should be in posted Invoice", 1, savedInvoicingBase.DocManagerInfo.AllEDocs.Count);
			}
			else
			{
				Assert("Not for this transaction type.", true);
			}
		}

		public void TestSaveAsIncompleteDoesNotSaveRelatedAccruals()
		{
			if (InvoicingBase.AH_Ledger == LedgerTypes.AccountsPayable)
			{
				ForwardingConsol consol = Factory.NewWithValidTestData<ForwardingConsol>();
				ForwardingShipment shipment1 = consol.Shipments.AddNew();
				ForwardingShipment shipment2 = consol.Shipments.AddNew();
				Job job1 = TestObjectCreator.CreateJob(shipment1);
				Job job2 = TestObjectCreator.CreateJob(shipment2);

				ZGuid taxRateToUseOnConsol = GetTaxRateForConsolBeforeFactorySaveToEnsureItExsitsWhenReloading();
				ZGuid chargeCodeToUseOnConsol = GetChargeCodeForConsoBeforeFactorySaveToEnsureItExistsWhenReloading();
				InvoicingBase.Delete();
				Factory.Save();

				AssertEquals("Should be no AccTransactoinHeader records", 0, GetTableCount(AccTransactionHeaderSchema.Constants.TableName));
				AssertEquals("Should be no AccTransactoinLines records", 0, GetTableCount(AccTransactionLinesSchema.Constants.TableName));
				InvoicingBase invoice = (InvoicingBase)Factory.NewWithValidTestData(GetExpectedBusinessObjectType());

				AssertEquals("Pre-condition: no eDocs", 0, invoice.DocManagerInfo.AllEDocs.Count);
				invoice.DocManagerInfo.AddFileOrDocument(new byte[] { 0, 1, 2, 3 }, "test", "TXT");
				AssertEquals("One eDoc just added", 1, invoice.DocManagerInfo.AllEDocs.Count);
				BusinessObjectFactory docFactory = (BusinessObjectFactory)invoice.DocManagerInfo.MasterFactory;
				// Added the following code to mock the eDocs plugin behaviour where it adds BizO factory as a child to DocumentFactory
				if (!docFactory.ChildFactories.Contains(Factory))
				{
					docFactory.ChildFactories.Add(Factory);
				}

				var unrelatedBizOInInvoiceFactory = InvoicingBase.Factory.NewWithValidTestData<JobConsolCost>();

				JobConsolCost cost = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
				cost.E6_AC_ChargeCode = chargeCodeToUseOnConsol;
				cost.E6_OSCostAmount = 100m;
				cost.E6_ApportionmentMethod = "CHG";
				cost.E6_AT_TaxRate = taxRateToUseOnConsol;
				cost.ApportionmentCharges[0].JR_OSCostAmt = 75m;
				cost.ApportionmentCharges[1].JR_OSCostAmt = 25m;

				invoice.ImportAllApportionmentsFromCosting();
				AssertEquals("invoice: Count of lines", 2, invoice.Lines.Count);

				invoice.SaveAsIncomplete();

				AssertEquals("Should be one AccTransactoinHeader record", 1, GetTableCount(AccTransactionHeaderSchema.Constants.TableName));
				AssertEquals("Should be no AccTransactoinLines records", 0, GetTableCount(AccTransactionLinesSchema.Constants.TableName));

				BusinessObjectFactory newFactory = new BusinessObjectFactory();
				InvoicingBase invoiceInNewFactory = newFactory.Load<InvoicingBase>(invoice.PK);
				AssertEquals("eDocs should be saved", 1, invoiceInNewFactory.DocManagerInfo.AllEDocs.Count);
				AssertNull("An unrelated Business Object in the Invoice Factory should not be saved when SaveAsIncomplete", newFactory.Load<JobConsolCost>(unrelatedBizOInInvoiceFactory.PK));
			}
			else
			{
				Assert("Not for this ledger type.", true);
			}
		}

