		#region Implementation - Save as Incomplete only updates Header, notes and Log

		void AssertOnlyAccTransactionheaderAndStmNoteModifiedOnSaveAsIncomplete(bool inDB)
		{
			DateTime highWaterMark = ZDateTime.UtcNow.ToDateTime();
			StmALog[] logsBeforeSave = GetEDTStmALogAfterSL_PostedTime(highWaterMark);
			int jobChargeCountBefore = GetTableCount("JobCharge");
			int accTransactionLinesCountBefore = GetTableCount("AccTransactionLines");
			int accTransactionHeaderCountBefore = GetTableCount("AccTransactionHeader");
			int stmNoteCountBefore = GetTableCount("StmNote");
			InvoicingBase.SaveAsIncomplete();
			StmALog[] logsAfterSave = GetEDTStmALogAfterSL_PostedTime(highWaterMark);
			int jobChargeCountAfter = GetTableCount("JobCharge");
			int accTransactionLinesCountAfter = GetTableCount("AccTransactionLines");
			int accTransactionHeaderCountAfter = GetTableCount("AccTransactionHeader");
			int stmNoteCountAfter = GetTableCount("StmNote");

			if (inDB)
			{
				AssertEquals("There should be 1 logs added", 1, logsAfterSave.Length - logsBeforeSave.Length);
				var stmALogAccTransactionHeader = GetLogByTable(logsAfterSave, "AccTransactionHeader");
				AssertEquals("There should be 1 acctransactionheader edit log", 1, stmALogAccTransactionHeader.Length);
				AssertEquals("AccTransactionHeader should be edited", "EDT", stmALogAccTransactionHeader[0].SL_SE_NKEvent);
				var stmALogStmNote = GetLogByTable(logsAfterSave, "StmNote");
				AssertEquals("There should be 0 StmNote edit log", 0, stmALogStmNote.Length);
			}
			else
			{
				AssertEquals("1 AcctransactionHeader should have been added", 1, accTransactionHeaderCountAfter - accTransactionHeaderCountBefore);
				AssertEquals("1 stmNote should have been added", 1, stmNoteCountAfter - stmNoteCountBefore);
			}
			AssertEquals("No JobCharges should have been added", 0, jobChargeCountAfter - jobChargeCountBefore);
			AssertEquals("No AccTransactionLines should have been added", 0, accTransactionLinesCountAfter - accTransactionLinesCountBefore);
		}

		protected StmALog[] GetLogByTable(StmALog[] logs, string table)
		{
			var logsByTable = (from log in logs
							   where log.SL_Table == table
							   select log).ToArray();

			return logsByTable.ToArray();
		}

		int GetTableCount(string table)
		{
			DbCommand cmd = Db.Connection.Command(string.Format("SELECT COUNT(*) FROM {0}", table));
			return (int)cmd.ExecuteScalar();
		}

