			{
				SetupForSave();
				var dummyBizoToProofFactoryIsNotSaved = Factory.New<DummyBusinessObject>();
				InvoicingBase.MakeAsIncomplete(out var subTypeMessage);
				AssertNullOrEmpty(subTypeMessage);
				AssertEquals("Ledger", LedgerTypes.IncompleteTransactions, InvoicingBase.AH_Ledger);
				AssertEquals("Transaction Type", ExpectedTransactionTypeForIncomplete, InvoicingBase.AH_TransactionType);
				Assert("invoice should not be saved until another factory is saved", !InvoicingBase.IsInDatabase);
				Assert("invoice is still not saved as incomplete here", !InvoicingBase.IsIncompleteInvoice);

				Factory.Save();
				Assert("invoice should be marked as saved when another factory is saved", InvoicingBase.IsInDatabase);
				Assert("invoice is saved and incomplete now", InvoicingBase.IsIncompleteInvoice);
				Assert("however invoice factory show not be saved to avoid saving objects other than required for incomplete invoice.", !dummyBizoToProofFactoryIsNotSaved.IsInDatabase);
			}
			else
			{
				Assert("Not for this ledger type.", true);
			}
		}

		public void TestMakeAsIncomplete_ComplianceNrByPostDate()
		{
			if (InvoicingBase.AH_Ledger == LedgerTypes.AccountsPayable)
			{
				var guid_GC = GlbCompany.CurrentCompany.PK.ToGuid();
				var registry = AccountingMasterFilesRegistry.Instance.ComplianceNumberAllocationDate_AP;

				using (registry.SetTemporaryValue(guid_GC, Guid.Empty, Guid.Empty, AccountingMasterFilesConstants.ComplianceNumberAllocationDateOptions.PostDate.Code))
				{
					SetupForSave();
					InvoicingBase.AH_ComplianceSubType = "TXI";
					InvoicingBase.MakeAsIncomplete(out var result);

					if (InvoicingBase.IsAPTransaction)
					{
						AssertEquals("extra msg.", @"Note: Incomplete Invoice is saved without Compliance Sub Type, because it must be set only when Compliance Number is allocated",
							result);
						AssertNullOrEmpty(InvoicingBase.AH_ComplianceSubType);
					}
					else
					{
						AssertNullOrEmpty(result);
						AssertNotNullOrEmpty(InvoicingBase.AH_ComplianceSubType);
					}

					InvoicingBase.AH_ComplianceSubType = ZString.Empty;
					InvoicingBase.MakeAsIncomplete(out result);
					AssertNullOrEmpty(result);
					AssertNullOrEmpty(InvoicingBase.AH_ComplianceSubType);
				}

				using (registry.SetTemporaryValue(guid_GC, Guid.Empty, Guid.Empty, AccountingMasterFilesConstants.ComplianceNumberAllocationDateOptions.NoControl.Code))
				{
					SetupForSave();
					InvoicingBase.MakeAsIncomplete(out var result);
					AssertNullOrEmpty(result);
				}
			}
			else
			{
				Assert("Not for this ledger type.", true);
			}
		}

