				var shipment2 = consol.Shipments.AddNew();
				var job1 = TestObjectCreator.CreateJob(shipment1);
				var job2 = TestObjectCreator.CreateJob(shipment2);

				var taxRateToUseOnConsol = GetTaxRateForConsolBeforeFactorySaveToEnsureItExsitsWhenReloading();
				var chargeCodeToUseOnConsol = GetChargeCodeForConsoBeforeFactorySaveToEnsureItExistsWhenReloading();
				Factory.Save();

				var invoice = (InvoicingBase)Factory.NewWithValidTestData(GetExpectedBusinessObjectType());
				invoice.AH_OH = TestObjectCreator.Creditor1.PK;

				var cost = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
				cost.E6_AC_ChargeCode = chargeCodeToUseOnConsol;
				cost.E6_OSCostAmount = 100m;
				cost.E6_ApportionmentMethod = "CHG";
				cost.E6_AT_TaxRate = taxRateToUseOnConsol;
				cost.ApportionmentCharges[0].JR_OSCostAmt = 75m;
				cost.ApportionmentCharges[1].JR_OSCostAmt = 25m;

				invoice.ImportAllApportionmentsFromCosting();
				AssertEquals("invoice: Count of lines", 2, invoice.Lines.Count);

				invoice.SaveAsIncomplete();

				Assert("Precondition", !invoice.AH_GB_TaxBranch.IsEmpty);
				Assert("Precondition", !invoice.Lines[0].AL_GB_TaxBranch.IsEmpty);

				invoice.SaveAsIncomplete();

				AssertTaxBranchAfterRestoreSavedData(invoice, true, true, true);
				AssertTaxBranchAfterRestoreSavedData(invoice, false, true, true);
				AssertTaxBranchAfterRestoreSavedData(invoice, false, true, false);
				AssertTaxBranchAfterRestoreSavedData(invoice, false, false, true);
				AssertTaxBranchAfterRestoreSavedData(invoice, false, false, false);
				AssertTaxBranchAfterRestoreSavedData(invoice, true, false, true);
				AssertTaxBranchAfterRestoreSavedData(invoice, true, false, false);
				AssertTaxBranchAfterRestoreSavedData(invoice, true, true, false);
			}
			else
			{
				Assert("Not for this ledger type.", true);
			}
		}

		void AssertTaxBranchAfterRestoreSavedData(InvoicingBase invoice, bool isCompanyTaxRegistered, bool isEnabledTaxBranchReporting, bool isTaxApplicable)
		{
			AccountingMasterFilesRegistry.Instance.EnableTaxBranchReporting.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, isEnabledTaxBranchReporting);
			GlbCompany.CurrentCompany.GC_IsGSTRegistered = isCompanyTaxRegistered;

			var newFactory = new BusinessObjectFactory();
			var loadedCreditor = newFactory.Load<OrgHeader>(TestObjectCreator.Creditor1.PK);
			loadedCreditor.CompanyData.OB_APVATConfig = isTaxApplicable
						? AccountingMasterFilesConstants.OrganisationTaxConfiguartionTypes.Default.Code
						: AccountingMasterFilesConstants.OrganisationTaxConfiguartionTypes.NotApplicable.Code;

			newFactory.Save();

			var invoicingBaseInNewFactory = (InvoicingBase)newFactory.Load(GetExpectedBusinessObjectType(), invoice.PK);

			AssertEquals("Original invoice should have unsaved lines", 2, invoice.Lines.Count);
			AssertEquals("Loaded invoice shouldn't have any lines", 0, invoicingBaseInNewFactory.Lines.Count);

			invoicingBaseInNewFactory.RestoreSavedData();

			AssertEquals("Loaded invoice now has lines", 2, invoicingBaseInNewFactory.Lines.Count);

			var taxBranchShouldBeCleared = !(isCompanyTaxRegistered && isEnabledTaxBranchReporting && isTaxApplicable);

			AssertEquals(taxBranchShouldBeCleared, invoicingBaseInNewFactory.AH_GB_TaxBranch.IsEmpty);
			AssertEquals(taxBranchShouldBeCleared, invoicingBaseInNewFactory.Lines[0].AL_GB_TaxBranch.IsEmpty);
		}

