		public void TestMutexErrorWhenRestoringSavedData()
		{
			if (InvoicingBase.AH_Ledger == LedgerTypes.AccountsPayable)
			{
				var anotherFactory = new BusinessObjectFactory();
				var creator = new TestObjectCreator(anotherFactory);
				var consol = creator.CreateConsol("KRSEL", "AUSYD", "C1");
				var shipment1 = creator.CreateShipment("S1", consol);
				var job1 = creator.CreateJob(shipment1, false);
				anotherFactory.Save();

				SetupForSave();
				var cost = InvoicingBase.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
				cost.E6_AC_ChargeCode = creator.CC1.PK;
				cost.E6_OSCostAmount = 200m;
				cost.E6_ApportionmentMethod = "SHP";
				cost.SetIsUsedForApportionment();
				InvoicingBase.ImportAllApportionmentsFromCosting();
				InvoicingBase.SaveAsIncomplete();

				var shipment2 = creator.CreateShipment("S2", consol);
				anotherFactory.Save();

				var lockingFactory = new BusinessObjectFactory();
				var loader = new Job.Loader(lockingFactory, lockingFactory.Load<ForwardingShipment>(shipment2.PK));
				using (loader.TryCreateWithMutex())
				{
					var invoicingBaseInNewFactory = (InvoicingBase)new BusinessObjectFactory().Load(GetExpectedBusinessObjectType(), InvoicingBase.PK);
					invoicingBaseInNewFactory.RestoreSavedData();

					var result = invoicingBaseInNewFactory.RestoreSavedData();
					AssertEquals("Result type", InvoicingBase.RestoreSavedDataResult.ResultType.Failed, result.Result);
					AssertEquals("Error message", @"You have created the job S2 on another form, but haven't saved it yet.
Please close or save other forms that use job S2 to continue.", result.Error);
				}
			}
			else
			{
				Assert("Not for this ledger type.", true);
			}
		}

