		public void TestNoCriticalValidationBecauseOfLocalAmountsIsLost()
		{
			var consol = TestObjectCreator.CreateConsol("AUSYD", "NZAKL", "C0001");
			var shipment1 = TestObjectCreator.CreateShipment("S0001", consol);
			var shipment2 = TestObjectCreator.CreateShipment("S0002", consol);
			var job1 = TestObjectCreator.CreateJob(shipment1, false, false);
			var job2 = TestObjectCreator.CreateJob(shipment2, false, false);
			Factory.Save();

			var invoice = TestObjectCreator.CreateInvoice(typeof(APInvoice), "INV1", TestObjectCreator.USD, 0.77m, TestObjectCreator.Creditor1);

			var cost = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			cost.E6_AC_ChargeCode = TestObjectCreator.CC1.PK;
			cost.E6_OSCostAmount = 2205.9;
			invoice.ImportAllApportionmentsFromCosting();
			AssertEquals("Precondition: invoice should have lines created for consol cost", 2, invoice.Lines.Count);
			AssertEquals("Precondition: AL_OSExTaxAmount line 1", 1102.95m, invoice.Lines[0].AL_OSExTaxAmount);
			AssertEquals("Precondition: AL_OSExTaxAmount line 2", 1102.95m, invoice.Lines[1].AL_OSExTaxAmount);
			AssertEquals("Precondition: AL_LocalExTaxAmount line 1 (1 extra cent allocated here)", 1432.41m, invoice.Lines[0].AL_LocalExTaxAmount);
			AssertEquals("Precondition: AL_LocalExTaxAmount line 2", 1432.40m, invoice.Lines[1].AL_LocalExTaxAmount);
			AssertEquals("Precondition: AH_OSExTaxAmount", 2205.9m, invoice.AH_OSExTaxAmount);
			AssertEquals("Precondition: AH_LocalExTaxAmount", 2864.81m, invoice.AH_LocalExTaxAmount);

			invoice.RunPreSaveValidation();
			AssertNoErrors("Precondition for successful saving", invoice);

			invoice.SaveAsIncomplete();
			AssertEquals("Precondition: invoice should be saved.", true, invoice.IsInDatabase);

			var newFactory = new BusinessObjectFactory();
			var invoiceInNewFactory = newFactory.Load<InvoicingBase>(invoice.PK);
			invoiceInNewFactory.RestoreSavedData();
			invoiceInNewFactory.MoveFromIncompleteToPayableLedger();

			AssertEquals("Precondition: AH_Ledger", LedgerTypes.AccountsPayable, invoiceInNewFactory.AH_Ledger);

			AssertEquals("Restored data: invoice should have lines created for consol cost", 2, invoiceInNewFactory.Lines.Count);
			AssertEquals("Restored data: AL_OSExTaxAmount line 1", 1102.95m, invoiceInNewFactory.Lines[0].AL_OSExTaxAmount);
			AssertEquals("Restored data: AL_OSExTaxAmount line 2", 1102.95m, invoiceInNewFactory.Lines[1].AL_OSExTaxAmount);
			AssertEquals("Restored data: AL_LocalExTaxAmount line 1 (1 extra cent allocated here)", 1432.41m, invoiceInNewFactory.Lines[0].AL_LocalExTaxAmount);
			AssertEquals("Restored data: AL_LocalExTaxAmount line 2", 1432.40m, invoiceInNewFactory.Lines[1].AL_LocalExTaxAmount);
			AssertEquals("Restored data: AH_OSExTaxAmount", 2205.9m, invoiceInNewFactory.AH_OSExTaxAmount);
			AssertEquals("Restored data: AH_LocalExTaxAmount", 2864.81m, invoiceInNewFactory.AH_LocalExTaxAmount);
			AssertNoExceptionThrown("Saving should be done without any Critical Validation exception.", () => newFactory.Save());
		}

