		public void TestIncludeInThePeriodicInvoiceRaiseCollectionEvent()
		{
			Factory.Save();
			PeriodicInvoiceMiscInvoiceCollection collection = new PeriodicInvoiceMiscInvoiceCollection(Factory);
			collection.Add(InvoicingBase);
			collection.OnIncludingInThePeriodicInvoiceChanged += new EventHandler<ChangedBizoEventArgs>(collection_OnIncludingInThePeriodicInvoiceChanged);

			Assert("Precondition: IncludeInThePeriodicInvoice should be True after adding in a PeriodicInvoiceMiscInvoiceCollection.", InvoicingBase.IncludeInThePeriodicInvoice);

			IsOnIncludingInThePeriodicInvoiceChangedRaised = false;
			InvoicingBase.IncludeInThePeriodicInvoice = false;
			Assert("OnIncludingInThePeriodicInvoiceChanged event should be raised.", IsOnIncludingInThePeriodicInvoiceChangedRaised);

			IsOnIncludingInThePeriodicInvoiceChangedRaised = false;
			InvoicingBase.IncludeInThePeriodicInvoice = true;
			Assert("OnIncludingInThePeriodicInvoiceChanged event should be raised.", IsOnIncludingInThePeriodicInvoiceChangedRaised);

			IsOnIncludingInThePeriodicInvoiceChangedRaised = false;
			InvoicingBase.IncludeInThePeriodicInvoice = true;
			Assert("OnIncludingInThePeriodicInvoiceChanged event should not be raised if value is not changed.", !IsOnIncludingInThePeriodicInvoiceChangedRaised);
		}

