		public void TestCorrespondingReversedTransaction()
		{
			ARInvoice invoice = Factory.NewWithValidTestData<ARInvoice>();

			InvoicingLineBase line = (InvoicingLineBase)invoice.Lines.AddNew();
			line.AL_OSExTaxAmount = 100;
			line.AL_AG = TestObjectCreator.GLHeader1.PK;
			line.AL_AG = TestObjectCreator.GLHeader1.PK;
			Factory.Save();

			InvoicingBaseReversing reverser = new ARInvoiceReversing(invoice);
			reverser.Reverse();
			Factory.Save();

			IReversing reversedInvoice = invoice.ReverseTransaction;

			InvoicingBase reversedInvoiceBizO = Factory.Load<ARCreditNote>(reversedInvoice.PK);

			AssertEquals("the PK of the reversed invoice must equal the PK of the reverse of the invoice", reversedInvoiceBizO.PK, invoice.CorrespondingReversedTransaction.PK);
			AssertEquals("the PK of the reversed invoice must equal the PK of the reverse of the invoice", invoice.PK, reversedInvoiceBizO.CorrespondingReversedTransaction.PK);

			ARCreditNote credit = Factory.NewWithValidTestData<ARCreditNote>();

			line = (InvoicingLineBase)credit.Lines.AddNew();
			line.AL_AG = TestObjectCreator.GLHeader1.PK;
			line.AL_LocalExTaxAmount = -100;
			Factory.Save();

			reverser = new InvoicingBaseReversing(credit);
			reverser.Reverse();
			Factory.Save();

			IReversing reversedCreditNote = credit.ReverseTransaction;

			InvoicingBase reversedCreditNoteBizO = Factory.Load<ARInvoice>(reversedCreditNote.PK);
			AssertEquals("the PK of the reversed credit note must equal the PK of the reverse of itself", reversedCreditNoteBizO.PK, credit.CorrespondingReversedTransaction.PK);
			AssertEquals("the PK of the reversed credit note must equal the PK of the reverse of itself", credit.PK, reversedCreditNoteBizO.CorrespondingReversedTransaction.PK);

			InvoicingBase posAdj = Factory.NewWithValidTestData<ARAdjustmentNote>();

			line = (InvoicingLineBase)posAdj.Lines.AddNew();
			line.AL_LocalExTaxAmount = -100;
			line.AL_AG = TestObjectCreator.GLHeader1.PK;
			Factory.Save();

			reverser = new InvoicingBaseReversing(posAdj);
			reverser.Reverse();
			Factory.Save();

			IReversing negAdj = posAdj.ReverseTransaction;

			InvoicingBase negAdjBizO = Factory.Load<ARAdjustmentNote>(negAdj.PK);
			AssertEquals("the PK of the negative adjustment note must equal the PK of the reverse of itself", negAdjBizO.PK, posAdj.CorrespondingReversedTransaction.PK);
			AssertEquals("the PK of the negative adjustment note must equal the PK of the reverse of itself", posAdj.PK, negAdjBizO.CorrespondingReversedTransaction.PK);
		}

		public void TestLogDescriptionChange()
		{
			InvoicingBase.AH_Desc = "Original Desc";
			Factory.Save();

			ZQuery filter = new ZQuery(StmALogSchema.SL_SE_NKEvent, Events.EditedARecord.Code);
			string expectedReference = "Description Edited. New Description: ";
			filter.AddToFilter(StmALogSchema.SL_Reference, SQLComparisonOperator.StartsWith, expectedReference);
			StmALog[] logs = InvoicingBase.Logs.Find(filter);
			AssertEquals("Description edited log shouldn't be added.", 0, logs.Length);

			InvoicingBase.AH_Desc = "New Desc";
			Factory.Save();

			logs = InvoicingBase.Logs.Find(filter);
			if (InvoicingBase.IsReceivableOrPayable_ForTestOnly)
			{
				AssertEquals("Description edited log should be added.", 1, logs.Length);
				AssertEquals("Description edited log should be added.", expectedReference + "'New Desc'", logs[0].SL_Reference);
			}
			else
			{
				AssertEquals("Description edited log shouldn't be added.", 0, logs.Length);
			}
		}

