		protected void SetupStampDutyCalculationTaxIDsAndRegistry(TestObjectCreator creator, out AccTaxRate taxRate, out AccTaxRate taxRate2, out AccChargeCode chargeCode, out AccInvMsg taxInvMsg1, out AccInvMsg taxInvMsg2)
		{
			taxInvMsg1 = Factory.NewWithValidTestData<AccInvMsg>();
			taxInvMsg1.A9_Code = "AAA";
			taxInvMsg1.A9_EnglishMsg = "English AAA";
			taxInvMsg1.A9_LocalMsg = "Local AAA";
			taxInvMsg1.A9_RN_NKCountryCode = Core.Constants.CountryCodes.Italy;

			taxRate = AccTaxRate.FindExistingTaxRate(Factory, "ART7", AccTaxRate.Types.Rated, Constants.CountryCodes.Italy);

			taxInvMsg2 = Factory.NewWithValidTestData<AccInvMsg>();
			taxInvMsg2.A9_Code = "BBB";
			taxInvMsg2.A9_EnglishMsg = "English BBB";
			taxInvMsg2.A9_LocalMsg = "Local BBB";
			taxInvMsg2.A9_RN_NKCountryCode = Core.Constants.CountryCodes.Italy;

			taxRate2 = AccTaxRate.FindExistingTaxRate(Factory, "ART2", AccTaxRate.Types.Rated, Constants.CountryCodes.Italy);

			var taxRateExempt = AccTaxRate.FindExistingTaxRate(Factory, "EXEMPT", AccTaxRate.Types.Exempt, Constants.CountryCodes.Italy);

			Factory.Save();

			string value = taxRate.PK.ToString() + "," + taxRate2.PK.ToString();
			AccountingConfigurationRegistry.Instance.TaxIDsAttractingStampDuty.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, value);
			AccountingConfigurationRegistry.Instance.StampDutyFixedAmount.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, 1.81m);
			AccountingConfigurationRegistry.Instance.StampDutyThreshold.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, 77.47m);

			chargeCode = creator.CreateChargeCode("BOLLO", "Stamp Duty", "MRG", 1m, taxRateExempt, creator.WHTFREE1);
			AccountingConfigurationRegistry.Instance.StampDutyChargeCode.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, chargeCode.PK.ToGuid());
			AccountingConfigurationRegistry.Instance.StampDutyInvoiceTaxMessage.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, taxInvMsg2.PK.ToGuid());

			Factory.Save();
		}

		protected void AssertStampDutyCalculation(decimal line1LocalExTaxAmount, decimal line2LocalExTaxAmount, bool shouldAddEvent, bool shouldCreateStampDutyCharge, AccTaxRate taxRate, AccTaxRate taxRate2, AccChargeCode chargeCode, AccGLHeader glHeader, AccInvMsg taxInvMsg)
		{
			var invoice = (InvoicingBase)Factory.New(GetExpectedBusinessObjectType());
			OrgHeader orgHeader = Factory.NewWithValidTestData<OrgHeader>();
			orgHeader.OH_RL_NKClosestPort = "ITROM";

			if (!shouldCreateStampDutyCharge && shouldAddEvent)
			{
				orgHeader.CustomsCodes.AddNew(ItalyOrgCusCodeInfo.OrgCusCodes.NBO, Core.Constants.CountryCodes.Italy);
			}
			invoice.AH_OH = orgHeader.PK;
			InvoicingLineBase line = (InvoicingLineBase)invoice.Lines.AddNew();
			line.AL_AG = glHeader.PK;
			line.AL_LocalExTaxAmount = line1LocalExTaxAmount;
			line.AL_AT = taxRate.PK;
			InvoicingLineBase line2 = (InvoicingLineBase)invoice.Lines.AddNew();
			line2.AL_AG = glHeader.PK;
			line2.AL_LocalExTaxAmount = line2LocalExTaxAmount;
			line2.AL_AT = taxRate2.PK;

			Factory.Save();

			if (shouldCreateStampDutyCharge)
			{
				AssertEquals("Invoice Line Count", 3, invoice.Lines.Count);

				InvoicingLineBase line3 = invoice.Lines[invoice.Lines.Count - 1];

				AssertEquals("Stamp Duty Line", line3.AL_AC, chargeCode.PK);
				AssertEquals("Stamp Duty Line", line3.AL_LineAmount, 1.81m);
				AssertEquals("Stamp Duty Line", line3.ChargeCode.AC_Code, "ZZBOLLO");
				AssertEquals("Stamp Duty Line", line3.AL_A9_VATClass, taxInvMsg.PK);
				AssertStampDutyLiabilityEvent(invoice, true);
			}
			else
			{
				AssertEquals("Invoice Line Count", 2, invoice.Lines.Count);
				AssertStampDutyLiabilityEvent(invoice, shouldAddEvent);
			}
		}

