		[TestDate(2012, 03, 01)]
		public virtual void TestAH_InvoiceDate()
		{
			var consol = TestObjectCreator.CreateConsol("AUSYD", "NZAKL", "test001");
			var shipment = TestObjectCreator.CreateShipment("S0001", consol);
			TestObjectCreator.CreateJob(shipment);
			Factory.Save();
			var cost = InvoicingBase.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);

			var today = ZDateTime.Today;
			InvoicingBase.AH_InvoiceTerm = InvoiceTerms.FromInvoiceDate;
			InvoicingBase.AH_InvoiceTermDays = 7;
			Assert("Precondition: AH_OriginalReferenceStartDate empty", InvoicingBase.AH_OriginalReferenceStartDate.IsEmpty);
			Assert("Precondition: AH_OriginalReferenceEndDate empty", InvoicingBase.AH_OriginalReferenceEndDate.IsEmpty);

			InvoicingBase.AH_InvoiceDate = today.AddDays(3);
			AssertEquals("AH_DueDate", today.AddDays(10), InvoicingBase.AH_DueDate);
			AssertEquals("E6_InvoiceDate", InvoicingBase.AH_InvoiceDate, cost.E6_InvoiceDate);
			Assert("AH_OriginalReferenceStartDate still empty", InvoicingBase.AH_OriginalReferenceStartDate.IsEmpty);
			Assert("AH_OriginalReferenceEndDate still empty", InvoicingBase.AH_OriginalReferenceEndDate.IsEmpty);

			CodePairRegistryItem registry = null;
			string regValue = null;
			switch (InvoicingBase.AH_Ledger)
			{
				case LedgerTypes.AccountsReceivable:
					registry = AccountingConfigurationRegistry.Instance.AllowARReversalDueDateCalculation;
					regValue = AccountingConstants.ReversalDueDateCalculation.DebtorsTerms;
					break;
				case LedgerTypes.AccountsPayable:
					registry = AccountingConfigurationRegistry.Instance.AllowAPReversalDueDateCalculation;
					regValue = AccountingConstants.ReversalDueDateCalculation.CreditorsTerms;
					break;
			}
			if (registry != null)
			{
				InvoicingBase.GenerateReverseTransaction(true);
				var reverseInvoice = InvoicingBase.ReverseInvoice;
				InvoicingBase.AH_DueDate = today.AddDays(5);

				registry.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, AccountingConstants.ReversalDueDateCalculation.OriginalInvoiceDueDate);
				reverseInvoice.AH_InvoiceDate = today.AddDays(6);
				AssertEquals("AH_DueDate", today.AddDays(5), reverseInvoice.AH_DueDate);
				AssertEquals("E6_InvoiceDate", InvoicingBase.AH_InvoiceDate, cost.E6_InvoiceDate);
				Assert("AH_OriginalReferenceStartDate empty", reverseInvoice.AH_OriginalReferenceStartDate.IsEmpty);
				Assert("AH_OriginalReferenceEndDate empty", reverseInvoice.AH_OriginalReferenceEndDate.IsEmpty);

				registry.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, regValue);
				reverseInvoice.AH_InvoiceDate = today.AddDays(7);
				AssertEquals("AH_DueDate", today.AddDays(14), reverseInvoice.AH_DueDate);
				AssertEquals("E6_InvoiceDate", InvoicingBase.AH_InvoiceDate, cost.E6_InvoiceDate);
				Assert("AH_OriginalReferenceStartDate empty", reverseInvoice.AH_OriginalReferenceStartDate.IsEmpty);
				Assert("AH_OriginalReferenceEndDate empty", reverseInvoice.AH_OriginalReferenceEndDate.IsEmpty);
			}
		}

		public void TestAH_InvoiceDate_SetExchangeRate_AmountEditableWithLedger()
		{
			var invoice = (InvoicingBase)GetNewBusinessObject();

			if (invoice is TransactionPendingAllocation)
			{
				Assert(true);
			}
			else
			{
				PostingExRateRegistry.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, ExRateOption.ExchangeRateBasedOnInvoiceDate.Code);

				TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, ExchangeRateTypes.Code.BuyRate, 5m, ZDateTime.Today, ZDateTime.Today);
				TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, ExchangeRateTypes.Code.BuyRate, 6m, ZDateTime.Today.AddDays(1), ZDateTime.Today.AddDays(1));
				TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, ExchangeRateTypes.Code.SellRate, 5m, ZDateTime.Today, ZDateTime.Today);
				TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, ExchangeRateTypes.Code.SellRate, 6m, ZDateTime.Today.AddDays(1), ZDateTime.Today.AddDays(1));
				ExchangeRateReader.GetReaderInstance().ClearCache();

				invoice.FillWithValidTestData();
				invoice.AH_RX_NKTransactionCurrency = TestObjectCreator.USD.Code;

				var line = (InvoicingLineBase)invoice.Lines.AddNew();
				line.AL_AG = TestObjectCreator.GLHeader1.PK;
				line.AL_RX_NKTransactionCurrency = TestObjectCreator.USD.Code;
				invoice.AH_InvoiceDate = ZDateTime.Today;

				AssertEquals(5m, line.AL_ExchangeRate);
				AssertEquals(false, invoice.IsInDatabase);

				invoice.AH_InvoiceDate = ZDateTime.Today.AddDays(1);
				AssertEquals("Exchange Rate will be change when invoice date change if transaction is not in database.", 6m, line.AL_ExchangeRate);

				Factory.Save();
				Assert(invoice.IsInDatabase);

				invoice.AH_InvoiceDate = ZDateTime.Today;

				var amountEditableWithLedgerList = new List<string>()
				{
					LedgerTypes.IncompleteTransactions,
					LedgerTypes.UnapprovedPayableTransactions,
					LedgerTypes.TransactionsPendingAllocation,
				};

				if (amountEditableWithLedgerList.Contains(invoice.AH_Ledger))
				{
					AssertEquals(5m, line.AL_ExchangeRate);
				}
				else
				{
					AssertNotEquals("Exchange Rate will not be change when invoice date change if transaction is in database.", 5m, line.AL_ExchangeRate);
				}
			}
		}

