		public void TestSetInvoiceDateWillUpdatePostDateInReverseDateFormContext()
		{
			BackDateInvoicesConfiguration configuration = new BackDateInvoicesConfiguration();
			configuration.InvoiceDateConfigurationCollection.RemoveAll();
			TestObjectCreator.AddInvoiceDateConfiguration(configuration, "SHP", "ALL", "ALL", "ALL",
				InvoiceDateConfigurationLookups.SignificantDateCodes.InvoiceAddDate,
				InvoiceDateConfigurationLookups.SignificantDatePeriodCodes.SignificantDate,
				InvoiceDateConfigurationLookups.SignificantDatePeriodCodes.SignificantDate,
				InvoiceDateConfigurationLookups.SignificantDatePeriodCodes.EndOfPriorMonth,
				InvoiceDateConfigurationLookups.SignificantDatePeriodCodes.InvoiceAddDate,
				false, false);
			configuration.OverridePostDate = false;
			configuration.DefaultPostDateFromInvoiceDate = true;
			AccountingConfigurationRegistry.Instance.BackDateInvoicesConfiguration.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, configuration);

			ZDate date1 = new ZDate(2013, 6, 8);
			ZDate date2 = new ZDate(2013, 5, 12);
			ZDate date3 = new ZDate(2013, 5, 13);
			InvoicingBase.AH_PostDate = date1;
			InvoicingBase.AH_InvoiceDate = date2;
			Assert(!InvoicingBase.Factory.HasContext(BusinessContext.ReverseDateForm));
			AssertEquals("PostDate should not be changed", date1, InvoicingBase.AH_PostDate);

			InvoicingBase.Factory.SetContext(BusinessContext.ReverseDateForm);
			InvoicingBase.AH_InvoiceDate = date3;
			AssertEquals("PostDate should be as same as the invoice date because it's in ReverseDateForm context", date3, InvoicingBase.AH_PostDate);
			InvoicingBase.Factory.RemoveContext(BusinessContext.ReverseDateForm);
		}

