		public void TestIsTaxed()
		{
			var invoice = (InvoicingBase)GetNewBusinessObject();

			if (invoice is TransactionPendingAllocation)
			{
				Assert("N/a", true);
				return;
			}

			invoice.FillWithValidTestData();

			var line1 = (InvoicingLineBase)invoice.Lines.AddNew();
			var line2 = (InvoicingLineBase)invoice.Lines.AddNew();
			line1.AL_AG = TestObjectCreator.GLHeader1.PK;
			line2.AL_AG = TestObjectCreator.GLHeader1.PK;
			Assert(!invoice.IsInDatabase);

			Factory.ClearCachedValue<ZBool>("IsTaxed:" + invoice.PK.ToStringKey());
			Factory.GetCachedValue("IsTaxed:" + invoice.PK.ToStringKey(), () => ZBool.True);

			AssertEquals("IsTaxed should be false as it ignores cached value and calclates based on lines when invoice is NOT in database", false, invoice.IsTaxed);

			Factory.ClearCachedValue<ZBool>("IsTaxed:" + invoice.PK.ToStringKey());
			Factory.GetCachedValue("IsTaxed:" + invoice.PK.ToStringKey(), () => ZBool.False);

			line1.AL_AT = Factory.NewWithValidTestData<AccTaxRate>().PK;
			AssertEquals("IsTaxed should be true as it ignores cached value and calclates based on lines when invoice is NOT in database", true, invoice.IsTaxed);

			Factory.ClearCachedValue<ZBool>("IsTaxed:" + invoice.PK.ToStringKey());
			Factory.GetCachedValue("IsTaxed:" + invoice.PK.ToStringKey(), () => ZBool.True);

			line1.AL_AT = ZGuid.Empty;
			AssertEquals("IsTaxed should be false as it ignores cached value and calclates based on lines when invoice is NOT in database", false, invoice.IsTaxed);

			Factory.Save();
			Assert(invoice.IsInDatabase);

			Factory.ClearCachedValue<ZBool>("IsTaxed:" + invoice.PK.ToStringKey());
			Factory.GetCachedValue("IsTaxed:" + invoice.PK.ToStringKey(), () => ZBool.True);

			Assert("Expect lines contain no tax", !invoice.LinesContainTax_ForTestOnly);
			if (invoice.IsPosted)
			{
				AssertEquals("IsTaxed should be true as it reads from the cached value when invoice is in database and posted", true, invoice.IsTaxed);
			}
			else
			{
				AssertEquals("IsTaxed should be false as it calculates base on lines when invoice is in database but NOT posted", false, invoice.IsTaxed);
			}
		}

