		public void TestPostingWithOriginalTransaction()
		{
			var originalInvoice = TestObjectCreator.CreateARInvoice<ARInvoice>("110212", TestObjectCreator.AUD, 1, TestObjectCreator.ABIGAS);
			var originalInvoiceLine = (InvoicingLineBase)originalInvoice.Lines.AddNew();
			originalInvoiceLine.AL_AG = TestObjectCreator.GLHeader1.PK;
			originalInvoiceLine.AL_LocalExTaxAmount = 3000m;
			originalInvoiceLine.AL_ExchangeRate = 1m;
			originalInvoiceLine.AL_RX_NKTransactionCurrency = "AUD";
			originalInvoiceLine.AL_GovtChargeCode = "GOVT1.1";
			Factory.Save();

			var creditNote = Factory.NewWithValidTestData<ARCreditNote>();
			creditNote.AH_OH = TestObjectCreator.ABIGAS.PK;
			var line1 = (InvoicingLineBase)creditNote.Lines.AddNew();
			var line2 = (InvoicingLineBase)creditNote.Lines.AddNew();
			line1.AL_AG = TestObjectCreator.GLHeader2.PK;
			line1.AL_LocalExTaxAmount = 1000m;
			line2.AL_AG = TestObjectCreator.GLHeader2.PK;
			line2.AL_LocalExTaxAmount = 2000m;

			AssertEquals("Precondition: Should have two line", 2, creditNote.Lines.Count);
			AssertEquals("Precondition: Should have one line", 1, originalInvoice.Lines.Count);

			creditNote.OriginalTransactionReference = originalInvoice.PK;
			Assert("Existing lines of credit note are deleted", line1.IsDeleted);
			Assert("Existing lines of credit note are deleted", line2.IsDeleted);
			creditNote.SubmittedFromInvoicingForm = true;
			AssertNoExceptionThrown("Posting invoice should not throw exception", () => Factory.Save());

			Assert("Invoice should be posted", creditNote.IsPosted);
			AssertEquals("Job should be copied from original transaction", originalInvoice.AH_JH, creditNote.AH_JH);
			AssertEquals("Existing lines are deleted and lines are copied from original transaction", 1, creditNote.Lines.Count);
			AssertEquals("Existing lines are deleted and lines are copied from original transaction", originalInvoice.Lines[0].AL_AC, creditNote.Lines[0].AL_AC);
			AssertEquals("Existing lines are deleted and lines are copied from original transaction", -originalInvoice.Lines[0].AL_LineAmount, creditNote.Lines[0].AL_LineAmount);
			AssertEquals("Existing lines are deleted and lines are copied from original transaction", originalInvoice.Lines[0].AL_GovtChargeCode, creditNote.Lines[0].AL_GovtChargeCode);
		}

