		#region IAmendingTest

		public void TestPopulateFromOriginalTransaction_AmendingTransactionCopyExchangeRateFromOriginalTransactionRegistry()
		{
			if (InvoicingBase.IsReceivableOrPayable_ForTestOnly)
			{
				var originalTransaction = GetNewBusinessObject() as InvoicingBase;
				originalTransaction.AH_RX_NKTransactionCurrency = CurrencyCodes.UnitedStates;
				originalTransaction.AH_ExchangeRate = 0.4m;
				var originalTransactionLine = (InvoicingLineBase)originalTransaction.Lines.AddNew();
				originalTransactionLine.AL_AG = TestObjectCreator.GLHeader1.PK;
				originalTransactionLine.AL_LocalExTaxAmount = 100m;
				originalTransactionLine.AL_ExchangeRate = 0.4m;
				originalTransactionLine.AL_RX_NKTransactionCurrency = CurrencyCodes.UnitedStates;
				Factory.Save();

				TestObjectCreator.USD.ExchangeRates.DeleteAll();
				var exchangeRateType = ZArchitecture.Environment.ExchangeRate.GetExchangeRateType(InvoicingBase.RateType);
				TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, exchangeRateType, 1.25m, ZDateTime.Today.AddDays(-5), ZDateTime.Today.AddDays(5));
				Factory.Save();

				AssertEquals("Precondition", CurrencyCodes.UnitedStates, originalTransaction.AH_RX_NKTransactionCurrency);
				AssertEquals("Precondition", 0.4m, originalTransaction.AH_ExchangeRate);
				AssertEquals("Precondition", CurrencyCodes.UnitedStates, originalTransaction.Lines[0].AL_RX_NKTransactionCurrency);
				AssertEquals("Precondition", 0.4m, originalTransaction.Lines[0].AL_ExchangeRate.Round(2));

				using (TestObjectCreator.SetupAmendingTransactionCopyExchangeRateRegistry(InvoicingBase.AH_Ledger, InvoicingBase.AH_GC, false))
				{
					InvoicingBase.PopulateFromOriginalTransaction(originalTransaction);
					AssertEquals(CurrencyCodes.UnitedStates, InvoicingBase.AH_RX_NKTransactionCurrency);
					AssertEquals("Should not copy header excange rate from original transaction", 1.25m, InvoicingBase.AH_ExchangeRate);
					AssertEquals(CurrencyCodes.UnitedStates, InvoicingBase.Lines[0].AL_RX_NKTransactionCurrency);
					AssertEquals("Should not copy line excange rate from original transaction line", 1.25m, InvoicingBase.Lines[0].AL_ExchangeRate);
				}

				using (TestObjectCreator.SetupAmendingTransactionCopyExchangeRateRegistry(InvoicingBase.AH_Ledger, InvoicingBase.AH_GC, true))
				{
					InvoicingBase.PopulateFromOriginalTransaction(originalTransaction);
					AssertEquals(CurrencyCodes.UnitedStates, InvoicingBase.AH_RX_NKTransactionCurrency);
					AssertEquals("Should copy header excange rate from original transaction", 0.4m, InvoicingBase.AH_ExchangeRate);
					AssertEquals(CurrencyCodes.UnitedStates, InvoicingBase.Lines[0].AL_RX_NKTransactionCurrency);
					AssertEquals("Should copy line excange rate from original transaction line", 0.4m, InvoicingBase.Lines[0].AL_ExchangeRate);
				}
			}
			else
			{
				Assert("Not Applicable for this Transaction", true);
			}
		}

