		[SuspendCriticalValidation]
		public void TestChargeCreatorIsUsedForAmendedTransaction_WithTaxRecoveryLines()
		{
			if (InvoicingBase is IAmending && InvoicingBase.HasImplementedGenerateAmendingTransaction)
			{
				var creator = new TestObjectCreator(Factory);
				var original = InvoicingBase as IAmending;
				InvoicingBase.AH_RX_NKTransactionCurrency = "USD";
				InvoicingBase.AH_ExchangeRate = 0.9m;
				AmendingTestHelper.PopulateOriginalTransaction(InvoicingBase, creator);
				Factory.Save();
				InvoicingBase.AH_ConsolidatedInvoiceRef = InvoiceLiteralNumberGenerator.GetNextAndUpdateUniqueJobARInvoiceNumber(InvoicingBase, (IPostingJob)InvoicingBase.Job);

				var transactionType = InvoicingBase is APInvoice ? TransactionTypes.CreditNote : (string)InvoicingBase.AH_TransactionType;

				IAmending amending = original.GenerateAmendingTransaction(transactionType);
				AssertNotNull("Should generate Amending transaction", amending);

				if (InvoicingBase is APInvoice)
				{
					amending.TransactionNumber = "ABC12345";
					AssertEquals("Should generate Amending transaction AP CRD for AP INV", TransactionTypes.CreditNote, (string)amending.TransactionType);
				}
				else
				{
					AssertEquals(string.Format("Should generate Amending transaction of the same Transaction Type as the original {0}", original.HumanReadableName), original.TransactionType, amending.TransactionType);
				}
				AssertEquals(string.Format("Should generate Amending transaction of the same Ledger as the original {0}", original.HumanReadableName), original.Ledger, amending.Ledger);
				AssertEquals("Should be referring as the OriginalTransaction", original.PK, amending.OriginalTransaction.PK);

				var chargeCreatorForOriginalTransactionMock = new Mock<IChargeCreator>();
				InvoicingBase.SubstituteChargeCreator_ForTestOnly(chargeCreatorForOriginalTransactionMock.Object);

				var chargeCreatorForAmendedTransactionMock = new Mock<IChargeCreator>();
				var passedLines = new HashSet<InvoicingLineBase>();
				var passedInvoices = new HashSet<InvoicingBase>();
				chargeCreatorForAmendedTransactionMock.Setup(x => x.CreateChargeFromJobRelatedRevenueLine(It.IsAny<InvoicingLineBase>(), It.IsAny<InvoicingBase>(), It.IsAny<bool>())).Callback((InvoicingLineBase line, InvoicingBase invoice, bool isTaxRecoveryLine) =>
				{
					passedLines.Add(line);
					passedInvoices.Add(invoice);
				});
				((InvoicingBase)amending).SubstituteChargeCreator_ForTestOnly(chargeCreatorForAmendedTransactionMock.Object);
				var taxParentAmending = TaxFrameworkObjectFactory.GetInvoicingBaseTaxRecordParent((InvoicingBase)amending);
				taxParentAmending.SubstituteChargeCreator_ForTestOnly(chargeCreatorForAmendedTransactionMock.Object);
				Assert("Precondition: job must be set", !InvoicingBase.Lines[0].AL_JH.IsEmpty);
				((ITaxRecordParent)taxParentAmending).AddTaxRecoveryLine(TestObjectCreator.CC1.PK, InvoicingBase.Lines[0].AL_JH, InvoicingBase.AH_GB, InvoicingBase.AH_GE, InvoicingBase.AH_RX_NKTransactionCurrency, 1, ZDate.Today, ZGuid.Empty, ZString.Empty);
				((ITaxRecordParent)taxParentAmending).AddTaxRecoveryLine(TestObjectCreator.CC1.PK, InvoicingBase.Lines[0].AL_JH, InvoicingBase.AH_GB, InvoicingBase.AH_GE, InvoicingBase.AH_RX_NKTransactionCurrency, 2, ZDate.Today, ZGuid.Empty, ZString.Empty);

				Factory.Save();

				var createCharges = InvoicingBase.Ledger_ForTestOnly == LedgerTypes.AccountsReceivable;
				chargeCreatorForOriginalTransactionMock.Verify(x => x.CreateChargeFromJobRelatedRevenueLine(It.IsAny<InvoicingLineBase>(), It.IsAny<InvoicingBase>(), It.IsAny<bool>()), Times.Never);
				chargeCreatorForAmendedTransactionMock.Verify(x => x.CreateChargeFromJobRelatedRevenueLine(It.IsAny<InvoicingLineBase>(), It.IsAny<InvoicingBase>(), It.IsAny<bool>()), Times.Exactly(createCharges ? 4 : 2));
				if (createCharges)
				{
					AssertContainsExactElementsInAnyOrder(nameof(passedLines), ((InvoicingBase)amending).Lines.Cast<InvoicingLineBase>(), passedLines);
					AssertContainsExactElementsInAnyOrder(nameof(passedInvoices), new[] { ((InvoicingBase)amending) }, passedInvoices);
				}
			}
			else
			{
				Assert("Not Applicable for this Transaction", true);
			}
		}

