		public void TestOriginalTransactionJobPKs()
		{
			if (InvoicingBase is IAmending && InvoicingBase.HasImplementedGenerateAmendingTransaction && !(InvoicingBase is APInvoice))
			{
				IAmending original = InvoicingBase as IAmending;

				InvoicingLineBase line1 = (InvoicingLineBase)InvoicingBase.Lines.AddNew();
				JobHeader job1 = Factory.NewJobWithValidTestDataForTesting<JobHeader>();
				line1.AL_JH = job1.PK;

				InvoicingLineBase line2 = (InvoicingLineBase)InvoicingBase.Lines.AddNew();
				JobHeader job2 = Factory.NewJobWithValidTestDataForTesting<JobHeader>();
				line2.AL_JH = job2.PK;

				// Have to add the third line to cause recalculating Jobs
				InvoicingBase.Lines.RemoveAndDelete(InvoicingBase.Lines.AddNew());

				AssertEquals(string.Format("Original {0} should have two Jobs", original.HumanReadableName), 2, InvoicingBase.InvoiceDependentJobs.Count);

				IAmending amending = original.GenerateAmendingTransaction(InvoicingBase.AH_TransactionType);
				AssertNotNull("Should generate Amending transaction", amending);

				AssertEquals(string.Format("Should generate Amending transaction of the same Transaction Type as the original {0}", original.HumanReadableName), original.TransactionType, amending.TransactionType);
				AssertEquals(string.Format("Should generate Amending transaction of the same Ledger as the original {0}", original.HumanReadableName), original.Ledger, amending.Ledger);
				AssertEquals("Should be referring as the OriginalTransaction", original.PK, amending.OriginalTransaction.PK);

				AssertEquals("OriginalTransactionJobPKs should contain two Job PKs", 2, amending.GetOriginalTransactionJobPKs().Length);
				Assert("Job1.PK should be in OriginalTransactionJobPKs", amending.GetOriginalTransactionJobPKs().Contains(job1.PK));
				Assert("Job2.PK should be in OriginalTransactionJobPKs", amending.GetOriginalTransactionJobPKs().Contains(job2.PK));
