		void AssertAmendingTransactionPopulatesAmountsToCharges(ZString currency, ZDecimal exchangeRate, bool isReciprocal)
		{
			var backup = GlbCompany.CurrentCompany.GC_IsReciprocal;
			GlbCompany.CurrentCompany.GC_IsReciprocal = isReciprocal;
			try
			{
				SetupForSave();
				InvoicingBase.AH_RX_NKTransactionCurrency = currency;
				InvoicingBase.AH_ExchangeRate = exchangeRate;
				foreach (InvoicingLineBase line in InvoicingBase.Lines)
				{
					line.Company.GC_IsReciprocal = isReciprocal;
					line.AL_JH = TestObjectCreator.CreateJob(InvoicingBase.Header, 0m, TestObjectCreator.Agent, 0m).PK;
					line.AL_AC = TestObjectCreator.CC1.PK;
					line.AL_Desc += " DSC";
					line.AL_RX_NKTransactionCurrency = currency;
					line.AL_ExchangeRate = exchangeRate;
					line.AL_OSExTaxAmount = 10m;
					line.AL_AT = TestObjectCreator.GST1.PK;
					line.AL_AW = TestObjectCreator.WHTFREE1.PK;
					var charge = TestObjectCreator.CreateCharge(line);
				}
				Factory.Save();

				var originalLineExchangeRate = InvoicingBase.Lines[0].AL_ExchangeRate;
				var newFactory = new BusinessObjectFactory();

				var original = newFactory.Load(typeof(InvoicingBase), InvoicingBase.PK) as IAmending;
				Assert("Should not be AmendingTransaction", !original.IsAmendingTransaction);

				IAmending amending;
				if (original is APInvoice)
				{
					amending = original.GenerateAmendingTransaction(TransactionTypes.CreditNote);
					amending.TransactionNumber = "ABC12345";
					AssertNotNull("Should generate Amending transaction", amending);
					AssertNotEquals(string.Format("Should generate Amending transaction of the different Transaction Type as the original {0}", original.HumanReadableName), original.TransactionType, amending.TransactionType);
				}
				else
				{
					amending = original.GenerateAmendingTransaction(InvoicingBase.AH_TransactionType);
					AssertNotNull("Should generate Amending transaction", amending);
					AssertEquals(string.Format("Should generate Amending transaction of the same Transaction Type as the original {0}", original.HumanReadableName), original.TransactionType, amending.TransactionType);
				}

				var populateAmountFromLine = original.TransactionType != amending.TransactionType;
				AssertEquals(string.Format("Should generate Amending transaction of the same Ledger as the original {0}", original.HumanReadableName), original.Ledger, amending.Ledger);
				AssertEquals("Should be referring as the OriginalTransaction", original.PK, amending.OriginalTransaction.PK);
				Assert("Should be AmendingTransaction", amending.IsAmendingTransaction);

				var amendingTransaction = amending as InvoicingBase;
				AssertNotNull(amendingTransaction);
				foreach (InvoicingLineBase amendingLine in amendingTransaction.Lines)
				{
					amendingLine.Company.GC_IsReciprocal = isReciprocal;
					AssertEquals("AL_RX_NKTransactionCurrency", currency, amendingLine.AL_RX_NKTransactionCurrency);
					AssertEquals("AL_ExchangeRate", populateAmountFromLine ? originalLineExchangeRate : exchangeRate, amendingLine.AL_ExchangeRate);
					amendingLine.AL_OSExTaxAmount = 15m;
				}

				try
				{
					newFactory.Save();
				}
				catch (OnSavingCriticalCheckException e)
				{
					Fail("Should not be any Critical Validation exception but was: " + e.Message);
				}

				foreach (InvoicingLineBase amendingLine in amendingTransaction.Lines)
				{
					var charges = newFactory.Load<Charge>(new ZQuery(JobChargeSchema.JR_JH, amendingLine.InvoicingJob.PK));
					AssertNotNull("InvoicingJob", amendingLine.InvoicingJob);
					var matchingCharge = (from Charge charge in charges
										  where amendingTransaction.AH_Ledger == LedgerTypes.AccountsReceivable ? charge.JR_AL_ARLine == amendingLine.PK : charge.JR_AL_APLine == amendingLine.PK
										  select charge).FirstOrDefault();
					AssertNotNull("Matching Charge should be created", matchingCharge);
					if (amendingTransaction.AH_Ledger == LedgerTypes.AccountsReceivable)
					{
						AssertEquals("OSAmount", amendingLine.AL_OSAmount, matchingCharge.JR_OSSellAmt + matchingCharge.JR_OSSellGSTAmt_Calc);
						AssertEquals("LocalAmount", amendingLine.AL_LineAmount, matchingCharge.JR_LocalSellAmt);
						//Round because 'AL_ExchangeRate' should store high precision exchange rate but 'JR_OSCostExRate' should only store 4 or 6 digits
						//so we need to round 'AL_ExchangeRate' to be able to compare it with 'JR_OSCostExRate'
						var expectedExchangeRate = Utilities.Round(amendingLine.AL_ExchangeRate, GlbCompany.CurrentCompany.ExchangeRateDecimalPlaces);
						AssertEquals("OSSellExRate", expectedExchangeRate, matchingCharge.JR_OSSellExRate);
						AssertEquals("GST", amendingLine.AL_AT, matchingCharge.JR_AT_SellGSTRate);
						AssertEquals("WHT", amendingLine.AL_AW, matchingCharge.JR_AW_SellWHTRate);
					}
					else if (amendingTransaction.AH_Ledger == LedgerTypes.AccountsPayable)
					{
						AssertEquals("OSAmount", -amendingLine.AL_OSAmount, matchingCharge.JR_OSCostAmt + matchingCharge.JR_OSCostGSTAmt_Calc);
						AssertEquals("LocalAmount", -amendingLine.AL_LineAmount, matchingCharge.JR_LocalCostAmt);

						//Round because 'AL_ExchangeRate' because AL_ExchangeRates gets recalculated with high precision on save
						var expectedExchangeRate = Utilities.Round(amendingTransaction.AH_ExchangeRate, 2);
						var actualExchangeRate = Utilities.Round(matchingCharge.JR_OSCostExRate, 2);

						AssertEquals("OSCostExRate", expectedExchangeRate, actualExchangeRate);
						AssertEquals("GST", amendingLine.AL_AT, matchingCharge.JR_AT_CostGSTRate);
						AssertEquals("WHT", amendingLine.AL_AW, matchingCharge.JR_AW_CostWHTRate);
					}
					AssertEquals("Description", amendingLine.AL_Desc, matchingCharge.JR_Desc);
				}
			}
			finally
			{
				GlbCompany.CurrentCompany.GC_IsReciprocal = backup;
			}
		}

