		void AssertCorrectAuthorisationRequired(ZDecimal amount, bool firstRequired, bool secondRequired,
			PaymentSixLevelAuthorisationSettings setting, bool levelAuthorizationRequired, bool isLevelsApplicable)
		{
			InvoicingBase.AH_LocalExTaxAmount = amount;
			InvoicingBase.AH_OSTotalAmount = InvoicingBase.AH_LocalExTaxAmount * 2;
			ZString description = "OSTotal Amount = $" + InvoicingBase.AH_OSTotalAmount;

			AssertEquals(description + " (First Authorisation Required)", isLevelsApplicable && firstRequired, InvoicingBase.Level1AuthorisationRequired_ForTestOnly(InvoicingBase.AuthorisationRequired));
			AssertEquals(description + " (Second Authorisation Required)", isLevelsApplicable && secondRequired, InvoicingBase.Level2AuthorisationRequired_ForTestOnly(InvoicingBase.AuthorisationRequired));

			if (setting != null && isLevelsApplicable)
			{
				AssertEquals(description + " (Authorisation Requirement)", setting.AuthorisationRequirement,
					InvoicingBase.AuthorisationRequired.AuthorisationRequirement);
			}

			AssertEquals(description + " (Level Authorization Required)", isLevelsApplicable && levelAuthorizationRequired, InvoicingBase.LevelAuthorizationRequired);
			AssertEquals(description + " (Check Level Security Rights)", !isLevelsApplicable || !levelAuthorizationRequired, InvoicingBase.CheckLevelSecurityRights());
		}

