		public void TestCreateTasksAndMilestonesFromTemplateWhenReversing()
		{
			if (ShouldSupportWorkflow)
			{
				var factory = new BusinessObjectFactory();
				var creator = new TestObjectCreator(factory);
				var template = factory.NewWithValidTestData<ProcessTaskTemplate>();

				if (InvoicingBase.AH_Ledger == LedgerTypes.AccountsReceivable)
				{
					template.P0_ProcessType = WorkflowDescriptors.ARInvoiceCode;
				}

				else
				{
					template.P0_ProcessType = WorkflowDescriptors.APInvoiceCode;
				}

				var task = template.WorkflowItems.AddNew();
				var milestone = template.WorkflowItems.Milestones.AddNew();
				factory.Save();

				var invoice = creator.CreateInvoice(InvoicingBase.GetType(), "Inv1", creator.AUD, 1m);
				var line = (InvoicingLineBase)invoice.Lines.AddNew();
				line.AL_ExchangeRate = 1m;
				line.AL_OSExTaxAmount = 100m;
				line.AL_LocalExTaxAmount = 100m;
				line.AL_AG = creator.GLHeader1.PK;
				factory.Save();

				var workflowProvider = (IWorkflowProvider)invoice;
				AssertEquals("Invoice should create workflow", 2, workflowProvider.WorkflowItems.Count);
				AssertEquals("Invoice should create milestone", 1, workflowProvider.WorkflowItems.Where(x => x.IsMilestone).Count());

				var reversingFactory = new ReversingFactory();
				var reversing = reversingFactory.NewReversing(invoice);
				reversing.Reverse();
				((InvoicingBase)invoice.ReverseTransaction).AH_TransactionNum = "0000001";
				factory.Save();

				var reversedInvoice = invoice.ReverseInvoice;
				AssertNotNull("Reversed Invoice", reversedInvoice);
				workflowProvider = reversedInvoice;
				AssertEquals("Reversed Invoice should create workflow", 2, workflowProvider.WorkflowItems.Count);
				AssertEquals("Milestone should be created", 1, workflowProvider.WorkflowItems.Where(x => x.IsMilestone).Count());
			}
			else
			{
				Assert(true);
			}
		}

		public void TestApplyWorkFlowTemplateAfterBOFieldsAreSetWhenReversing()
		{
			if (ShouldSupportWorkflow)
			{
				var factory = new BusinessObjectFactory();
				var creator = new TestObjectCreator(factory);
				var template = factory.NewWithValidTestData<ProcessTaskTemplate>();

				if (InvoicingBase.AH_Ledger == LedgerTypes.AccountsReceivable)
				{
					template.P0_ProcessType = WorkflowDescriptors.ARInvoiceCode;
				}

				else
				{
					template.P0_ProcessType = WorkflowDescriptors.APInvoiceCode;
				}

				var task = template.WorkflowItems.AddNew();
				var milestone = template.WorkflowItems.Milestones.AddNew();
				milestone.P9_Description = "milestone test 1";
				milestone.TriggerConditions.TriggerEventCode = "ADD";
				milestone.TemplateConditions.TemplateCondition2 = "UDF";
				milestone.TemplateConditions.TemplateCondition2Value = "\"<AH_Desc>\" != \"\"";
				factory.Save();

				var invoice = creator.CreateInvoice(InvoicingBase.GetType(), "Inv1", creator.AUD, 1m);
				invoice.AH_JH = creator.JobHeader1.PK;
				invoice.AH_ConsolidatedInvoiceRef = "S0001001";
				var line = (InvoicingLineBase)invoice.Lines.AddNew();
				line.AL_ExchangeRate = 1m;
				line.AL_OSExTaxAmount = 100m;
				line.AL_LocalExTaxAmount = 100m;
				line.AL_AG = creator.GLHeader1.PK;
				factory.Save();

				var workflowProvider = (IWorkflowProvider)invoice;
				AssertEquals("Invoice should create workflow", 2, workflowProvider.WorkflowItems.Count);
				AssertEquals("Invoice should create milestone", 1, workflowProvider.WorkflowItems.Where(x => x.IsMilestone).Count());

				var reversingFactory = new ReversingFactory();
				var reversing = reversingFactory.NewReversing(invoice);
				reversing.Reverse();
				var reversedInvoice = invoice.ReverseInvoice;
				reversedInvoice.AH_TransactionNum = "0000001";
				AssertNotNull("Reversed Invoice", reversedInvoice);
				Assert(!reversedInvoice.AH_Desc.IsEmpty);
				workflowProvider = reversedInvoice;
				AssertEquals("Reversed Invoice should create workflow", 2, workflowProvider.WorkflowItems.Count);
				AssertEquals("Milestone should be created", 1, workflowProvider.WorkflowItems.Where(x => x.IsMilestone).Count());
				factory.Save();
				AssertEquals("Save should not create more workflow since it's cancelled", 2, workflowProvider.WorkflowItems.Count);
				AssertEquals("Save should not create more workflow since it's cancelled", 1, workflowProvider.WorkflowItems.Where(x => x.IsMilestone).Count());
			}
			else
			{
				Assert(true);
			}
		}

