		public void TestAH_ConsolidatedInvoiceRef_ReadOnly()
		{
			var invoicingBase = TestObjectCreator.CreateInvoice(InvoicingBase.GetType(), "INV1", TestObjectCreator.AUD, 1M);

			invoicingBase.AH_Ledger = LedgerTypes.AccountsPayable;
			Assert(invoicingBase.AH_ConsolidatedInvoiceRef_ReadOnly_ForTestOnly);

			invoicingBase.AH_Ledger = LedgerTypes.UnapprovedPayableTransactions;
			Assert(invoicingBase.AH_ConsolidatedInvoiceRef_ReadOnly_ForTestOnly);

			invoicingBase.AH_Ledger = LedgerTypes.IncompleteTransactions;
			Assert(invoicingBase.AH_ConsolidatedInvoiceRef_ReadOnly_ForTestOnly);

			invoicingBase.AH_Ledger = LedgerTypes.AccountsReceivable;
			Assert(!invoicingBase.AH_ConsolidatedInvoiceRef_ReadOnly_ForTestOnly);

			invoicingBase.AH_Ledger = LedgerTypes.CashBook;
			Assert(!invoicingBase.AH_ConsolidatedInvoiceRef_ReadOnly_ForTestOnly);

			invoicingBase.AH_Ledger = LedgerTypes.General;
			Assert(!invoicingBase.AH_ConsolidatedInvoiceRef_ReadOnly_ForTestOnly);

			invoicingBase.AH_Ledger = LedgerTypes.JobCosting;
			Assert(!invoicingBase.AH_ConsolidatedInvoiceRef_ReadOnly_ForTestOnly);

			invoicingBase.AH_Ledger = LedgerTypes.TransactionsPendingAllocation;
			Assert(!invoicingBase.AH_ConsolidatedInvoiceRef_ReadOnly_ForTestOnly);
		}

