		public void TestTransactionNumberWasSetFrom2NumberFountainsErrorReport()
		{
			var invoice = TestObjectCreator.CreateInvoiceWithLine(typeof(APInvoice), "", TestObjectCreator.AUD, 1, 10, 0, 10, 0);
			invoice.IsSelfBillingInvoice = true;
			AssertEquals("Precondition: IsSelfBillingInvoice", true, invoice.IsSelfBillingInvoice);
			AccountingIServices.FactoryCountForNumberFountainUsage.SetDataRowRelatedValue(invoice, "FactorySaveCountUsedToGenerateTransactionNumberFromTransactionHeaderName", Factory.SaveCount + 1);
			Factory.Save();

			AssertEquals("TransactionNumberWasSetFrom2NumberFountains", ErrorReporter.LastKeyReported);
			string expectedMessage = string.Format(
@"Transaction Number got numbers from 2 number fountains (NumberFountain and SelfBillingInvoiceNumberFountain) in the same time. Transaction details:
Header: PK = {0}, Ledger = AP, Transaction Type = INV, Invoice Date = 12-Dec-12 00:00:00, Post Date = 12-Dec-12 00:00:00, Invoice Amount = -10, GST Amount = 0, OS Total = -10, Exchange Rate = 1, Currency = AUD, Outstanding Amount = -10, Fully Paid Date =  , Is Canceled = No, Is Aggregated = N, Transaction Number = SB00001000, Job PK = 00000000-0000-0000-0000-000000000000, Organization = , Is In DB = No, Is Deleted = No, Has Changes = Yes, Business Contexts = None.
Line Details:
Line: PK = {1}, Charge Code = , GL Account = {2}, Type = CST, OS Amount = -10, Local Amount = -10, GST = 0, Tax Rate = , Tax Class = , Exchange Rate = 1, Currency = AUD, Post Date = 12-Dec-12 00:00:00, Reverse Date = 12-Dec-12 00:00:00, Post To GL = N, Reverse To GL = N, Header PK = {0}, Job PK = 00000000-0000-0000-0000-000000000000, Organization = , Revenue Recognition Type = IMM, Is In DB = No, Is Final = No, Sub Accounts = , Has Changes = Yes.
",
			invoice.PK, invoice.Lines[0].PK, invoice.Lines[0].GLHeader.AccountNum);
			AssertMultilineASCIIEquals("LastMessageReported", expectedMessage, ErrorReporter.LastMessageReported);
			ErrorReporter.Clear();
		}

