		public void TestInvoiceRemittanceReference()
		{
			SetupInvoiceRemittanceConfiguration();

			var org = TestObjectCreator.CreateOrgHeader("TST", true, true, GlbBranch.CurrentBranch.GB_RL_NKHomePort);
			var invoice = (InvoicingBase)GetNewBusinessObject();
			invoice.AH_TransactionNum = "INV001";
			invoice.AH_OH = org.PK;

			if (invoice.Ledger_ForTestOnly == LedgerTypes.AccountsPayable)
			{
				invoice.InvoiceRemittanceReference = "test001"; //invoice remittance reference is entered manually for AP
				Assert(!invoice.TransactionHeaderReferenceIRR_ForTestOnly.IsNull);
			}
			Factory.Save();

			invoice = new BusinessObjectFactory().Load<InvoicingBase>(invoice.PK);
			if (invoice.SupportHeaderReference_ForTestOnly)
			{
				if (invoice.Ledger_ForTestOnly == LedgerTypes.AccountsReceivable)
				{
					AssertEquals("AH_InvoicePaymentReferenceCode", "BBB", invoice.AH_InvoicePaymentReferenceCode);
					AssertEquals("InvoiceRemittanceReference", "XX123456", invoice.InvoiceRemittanceReference);
				}
				else if (invoice.Ledger_ForTestOnly == LedgerTypes.AccountsPayable)
				{
					AssertEquals("AH_InvoicePaymentReferenceCode", "", invoice.AH_InvoicePaymentReferenceCode);
					AssertEquals("InvoiceRemittanceReference", "test001", invoice.InvoiceRemittanceReference);
				}
			}
			else
			{
				AssertNullOrEmpty(string.Format("transaction type {0} doesn't have payment reference code", invoice.TransactionType_ForTestOnly), invoice.AH_InvoicePaymentReferenceCode);
				AssertNullOrEmpty(string.Format("transaction type {0} doesn't have Invoice Remittance Reference", invoice.TransactionType_ForTestOnly), invoice.InvoiceRemittanceReference);
			}
		}

