		public void TestInvoiceRemittanceReference_ExceedMaxLength()
		{
			Factory.Save();

			var configurationCollection = InvoiceRemittanceConfigurationCollectionTest.GetConfigurationCollectionnWithExceedMaxLengthElementForTest(Factory);
			AccountingMasterFilesRegistry.Instance.InvoiceRemittanceConfiguration.SetValue(Env.CurrentCompanyPK, Guid.Empty, Guid.Empty, configurationCollection);

			var org = TestObjectCreator.CreateOrgHeader("TST", true, true, GlbBranch.CurrentBranch.GB_RL_NKHomePort);
			var invoice = (InvoicingBase)GetNewBusinessObject();
			invoice.AH_TransactionNum = "INV001";
			invoice.AH_OH = org.PK;

			if (invoice.Ledger_ForTestOnly == LedgerTypes.AccountsReceivable && invoice.SupportHeaderReference_ForTestOnly)
			{
				try
				{
					Factory.Save();
					Fail("Critical Validation should prevent saving");
				}
				catch (OnSavingCriticalCheckException ex)
				{
					var expectedErrorMessage = $"Transaction Remittance Reference '{new string('A', 121)}' exceed max length 120.\r\nPlease check registry settings: Accounting > Receivable Defaults > Default Settings > Invoice Remittance Configuration.";
					AssertContains("Critical Validation Error", expectedErrorMessage, ex.Message);
				}
			}
			else
			{
				Assert(true);
			}
		}

