		public void TestOverrideInvoiceRemittanceTypeLogs()
		{
			var org = TestObjectCreator.CreateOrgHeader("TST", true, true, GlbBranch.CurrentBranch.GB_RL_NKHomePort);
			var invoice = (InvoicingBase)GetNewBusinessObject();
			invoice.AH_TransactionNum = "INV001";
			invoice.AH_OH = org.PK;
			Factory.Save();

			SetupInvoiceRemittanceConfiguration();

			invoice.AH_InvoicePaymentReferenceCode = "BBB";
			invoice.SetContext(BusinessContext.OverrideInvoiceRemittanceType);
			Factory.Save();

			if (invoice.Ledger_ForTestOnly == LedgerTypes.AccountsReceivable && invoice.SupportHeaderReference_ForTestOnly)
			{
				var expectedReference = "Invoice Remittance Type changed from";
				var query = new ZQuery(StmALogSchema.SL_SE_NKEvent, Events.EditedARecord.Code);
				query.AddToFilter(StmALogSchema.SL_Reference, SQLComparisonOperator.Contains, expectedReference);

				Assert("Logs are created when invoice payment reference code is overridden", invoice.Logs.HasLogWith(query));

				expectedReference = "Invoice Remittance Reference changed from";
				query = new ZQuery(StmALogSchema.SL_SE_NKEvent, Events.EditedARecord.Code);
				query.AddToFilter(StmALogSchema.SL_Reference, SQLComparisonOperator.Contains, expectedReference);

				Assert("Logs are created when Invoice Remittance Reference is overridden", invoice.Logs.HasLogWith(query));
			}
			else
			{
				Assert(true);
			}
		}

