		public void TestOverrideDueDateLogs()
		{
			var org = TestObjectCreator.CreateOrgHeader("TST", true, true, GlbBranch.CurrentBranch.GB_RL_NKHomePort);
			var invoice = (InvoicingBase)GetNewBusinessObject();
			invoice.AH_TransactionNum = "INV001";
			invoice.AH_OH = org.PK;
			var originalDate = ZDateTime.Today.AddDays(30);
			invoice.AH_DueDate = originalDate;
			Factory.Save();

			invoice.SetContext(BusinessContext.OverrideTransactionAgreedPaymentMethod);
			var newDate = originalDate.AddDays(30);
			invoice.AH_DueDate = newDate;
			Factory.Save();

			if ((invoice.Ledger_ForTestOnly == LedgerTypes.AccountsPayable || invoice.Ledger_ForTestOnly == LedgerTypes.AccountsReceivable)
				&& invoice.SupportHeaderReference_ForTestOnly)
			{
				var expectedReference = string.Format(CultureInfo.InvariantCulture, "Due Date changed from '{0}' to '{1}'", originalDate, newDate);
				var query = new ZQuery(StmALogSchema.SL_SE_NKEvent, Events.EditedARecord.Code);
				query.AddToFilter(StmALogSchema.SL_Reference, SQLComparisonOperator.Contains, expectedReference);

				Assert("Logs are created when Due Date is overridden", invoice.Logs.HasLogWith(query));
			}
			else
			{
				Assert(true);
			}
		}

