		#region Cash Basis VAT

		public void TestSetLinesAL_GSTVATBasis()
		{
			var currentCompany = new BusinessObjectFactory().Load<GlbCompany>(GlbCompany.CurrentCompany.PK);
			currentCompany.GC_IsGSTCashBasis = true;
			currentCompany.Factory.Save();

			var serviceChargeCode = TestObjectCreator.CreateChargeCode("SRV", "Desc", Constants.ChargeType.Margin, 100, TestObjectCreator.GST1, null);
			serviceChargeCode.AC_GoodsServiceType = GoodServiceTypes.Codes.SRV;
			var goodsChargeCode = TestObjectCreator.CreateChargeCode("GDS", "Desc", Constants.ChargeType.Margin, 100, TestObjectCreator.GST1, null);
			goodsChargeCode.AC_GoodsServiceType = GoodServiceTypes.Codes.GDS;
			var organisation = TestObjectCreator.CreateOrgHeader("TST", true, true, true, false, true, false);
			Factory.Save();

			var taxRecognitionConfig = new TaxRecognitionDefaultingRules();
			taxRecognitionConfig.APInputGoods = TaxRecognitionDefaultingRules.RecognitionTypesCashCode;
			taxRecognitionConfig.AROutputServices = TaxRecognitionDefaultingRules.RecognitionTypesCashCode;
			AccountingConfigurationRegistry.Instance.TaxRecognitionDefaultingRules.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, taxRecognitionConfig);

			var invoice = (InvoicingBase)GetNewBusinessObject();
			invoice.FillWithValidTestData();
			invoice.AH_OH = organisation.PK;
			var lineForGoods = (InvoicingLineBase)invoice.Lines.AddNew();
			var lineForService = (InvoicingLineBase)invoice.Lines.AddNew();
			lineForGoods.GenericCharge = goodsChargeCode.PK;
			lineForService.GenericCharge = serviceChargeCode.PK;
			AssertNotNull("Precondition: line1.TaxRate", lineForGoods.TaxRate);
			AssertNotNull("Precondition: line2.TaxRate", lineForService.TaxRate);
			AssertNotNull("Precondition: line1.GLHeader", lineForGoods.GLHeader);
			AssertNotNull("Precondition: line2.GLHeader", lineForService.GLHeader);
			Assert("Precondition: Current company is GST Cash Basis", GlbCompany.CurrentCompany.GC_IsGSTCashBasis);

			bool isAP = InvoicingBase.Ledger_ForTestOnly == LedgerTypes.AccountsPayable;
			bool isAR = InvoicingBase.Ledger_ForTestOnly == LedgerTypes.AccountsReceivable;

			var expectedValueForGoods = isAP ? AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Cash.Code : AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code;
			var expectedValueForService = isAR ? AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Cash.Code : AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code;
			AssertEquals("lineForGoods.AL_GSTVATBasis", expectedValueForGoods, lineForGoods.AL_GSTVATBasis);
			AssertEquals("lineForService.AL_GSTVATBasis", expectedValueForService, lineForService.AL_GSTVATBasis);

			var originalLedger = invoice.AH_Ledger;

			invoice.AH_Ledger = LedgerTypes.UnapprovedPayableTransactions;
			AssertEquals("lineForGoods.AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, lineForGoods.AL_GSTVATBasis);
			AssertEquals("lineForService.AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, lineForService.AL_GSTVATBasis);

			invoice.AH_Ledger = LedgerTypes.IncompleteTransactions;
			AssertEquals("lineForGoods.AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Cash.Code, lineForGoods.AL_GSTVATBasis);
			AssertEquals("lineForService.AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, lineForService.AL_GSTVATBasis);

			invoice.AH_Ledger = originalLedger;
			AssertEquals("lineForGoods.AL_GSTVATBasis", expectedValueForGoods, lineForGoods.AL_GSTVATBasis);
			AssertEquals("lineForService.AL_GSTVATBasis", expectedValueForService, lineForService.AL_GSTVATBasis);

			lineForGoods.AL_AG = ZGuid.Empty;
			lineForService.AL_AG = ZGuid.Empty;
			AssertEquals("lineForGoods.AL_GSTVATBasis", expectedValueForGoods, lineForGoods.AL_GSTVATBasis);
			AssertEquals("lineForService.AL_GSTVATBasis", expectedValueForService, lineForService.AL_GSTVATBasis);

			lineForGoods.AL_AC = goodsChargeCode.PK;
			lineForService.AL_AC = serviceChargeCode.PK;
			AssertNotNull("Precondition: line1.ChargeCode", lineForGoods.ChargeCode);
			AssertNotNull("Precondition: line2.ChargeCode", lineForService.ChargeCode);
			AssertNotNull("Precondition: line1.TaxRate", lineForGoods.TaxRate);
			AssertNotNull("Precondition: line2.TaxRate", lineForService.TaxRate);
			AssertNotNull("Precondition: line1.GLHeader", lineForGoods.GLHeader);
			AssertNotNull("Precondition: line2.GLHeader", lineForService.GLHeader);
			AssertEquals("lineForGoods.AL_GSTVATBasis", expectedValueForGoods, lineForGoods.AL_GSTVATBasis);
			AssertEquals("lineForService.AL_GSTVATBasis", expectedValueForService, lineForService.AL_GSTVATBasis);

			lineForGoods.AL_AT = ZGuid.Empty;
			AssertEquals("lineForGoods.AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, lineForGoods.AL_GSTVATBasis);
			AssertEquals("lineForService.AL_GSTVATBasis", expectedValueForService, lineForService.AL_GSTVATBasis);

			lineForService.AL_AC = ZGuid.Empty;
			AssertEquals("lineForGoods.AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, lineForGoods.AL_GSTVATBasis);
			AssertEquals("lineForService.AL_GSTVATBasis", expectedValueForService, lineForService.AL_GSTVATBasis);

			lineForService.AL_AG = ZGuid.Empty;
			AssertEquals("lineForGoods.AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, lineForGoods.AL_GSTVATBasis);
			AssertEquals("lineForService.AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, lineForService.AL_GSTVATBasis);

			using (invoice.Lines.SuspendListChanged())
			{
				lineForGoods.AL_AT = TestObjectCreator.GST1.PK;
				lineForService.AL_AC = serviceChargeCode.PK;
				AssertNotNull("Precondition: line1.ChargeCode", lineForGoods.ChargeCode);
				AssertNotNull("Precondition: line2.ChargeCode", lineForService.ChargeCode);
				AssertNotNull("Precondition: line1.TaxRate", lineForGoods.TaxRate);
				AssertNotNull("Precondition: line2.TaxRate", lineForService.TaxRate);
				AssertNotNull("Precondition: line1.GLHeader", lineForGoods.GLHeader);
				AssertNotNull("Precondition: line2.GLHeader", lineForService.GLHeader);
				AssertEquals("lineForGoods.AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, lineForGoods.AL_GSTVATBasis);
				AssertEquals("lineForService.AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, lineForService.AL_GSTVATBasis);
			}
			AssertEquals("lineForGoods.AL_GSTVATBasis", expectedValueForGoods, lineForGoods.AL_GSTVATBasis);
			AssertEquals("lineForService.AL_GSTVATBasis", expectedValueForService, lineForService.AL_GSTVATBasis);

			lineForGoods.AL_AC = ZGuid.Empty;
			AssertEquals("lineForGoods.AL_GSTVATBasis", expectedValueForService, lineForGoods.AL_GSTVATBasis);
			AssertEquals("lineForService.AL_GSTVATBasis", expectedValueForService, lineForService.AL_GSTVATBasis);

			lineForGoods.AL_AG = ZGuid.Empty;
			AssertEquals("lineForGoods.AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, lineForGoods.AL_GSTVATBasis);
			AssertEquals("lineForService.AL_GSTVATBasis", expectedValueForService, lineForService.AL_GSTVATBasis);

			lineForGoods.AL_AC = goodsChargeCode.PK;
			AssertNotNull("Precondition: line1.ChargeCode", lineForGoods.ChargeCode);
			AssertNotNull("Precondition: line1.TaxRate", lineForGoods.TaxRate);
			AssertNotNull("Precondition: line1.GLHeader", lineForGoods.GLHeader);
			AssertEquals("lineForGoods.AL_GSTVATBasis", expectedValueForGoods, lineForGoods.AL_GSTVATBasis);
			AssertEquals("lineForService.AL_GSTVATBasis", expectedValueForService, lineForService.AL_GSTVATBasis);

			organisation.CompanyData.OB_APVATConfig = AccountingMasterFilesConstants.OrganisationTaxConfiguartionTypes.CashBasis.Code;
			organisation.CompanyData.OB_ARVATConfig = AccountingMasterFilesConstants.OrganisationTaxConfiguartionTypes.AccrualBasis.Code;

			invoice.AH_Ledger = LedgerTypes.IncompleteTransactions;
			AssertEquals("lineForGoods.AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Cash.Code, lineForGoods.AL_GSTVATBasis);
			AssertEquals("lineForService.AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Cash.Code, lineForService.AL_GSTVATBasis);

			invoice.AH_Ledger = LedgerTypes.UnapprovedPayableTransactions;
			AssertEquals("lineForGoods.AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, lineForGoods.AL_GSTVATBasis);
			AssertEquals("lineForService.AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, lineForService.AL_GSTVATBasis);

			invoice.AH_Ledger = originalLedger;
			var expectedValueForBoth = isAP ? AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Cash.Code : AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code;
			AssertEquals("lineForGoods.AL_GSTVATBasis", expectedValueForBoth, lineForGoods.AL_GSTVATBasis);
			AssertEquals("lineForService.AL_GSTVATBasis", expectedValueForBoth, lineForService.AL_GSTVATBasis);

			lineForGoods.AL_AC = ZGuid.Empty;
			lineForService.AL_AC = ZGuid.Empty;
			AssertEquals("lineForGoods.AL_GSTVATBasis", expectedValueForBoth, lineForGoods.AL_GSTVATBasis);
			AssertEquals("lineForService.AL_GSTVATBasis", expectedValueForBoth, lineForService.AL_GSTVATBasis);

			lineForGoods.AL_AC = goodsChargeCode.PK;
			lineForService.AL_AC = serviceChargeCode.PK;
			AssertNotNull("Precondition: line1.ChargeCode", lineForGoods.ChargeCode);
			AssertNotNull("Precondition: line2.ChargeCode", lineForService.ChargeCode);
			AssertNotNull("Precondition: line1.TaxRate", lineForGoods.TaxRate);
			AssertNotNull("Precondition: line2.TaxRate", lineForService.TaxRate);
			AssertNotNull("Precondition: line1.GLHeader", lineForGoods.GLHeader);
			AssertNotNull("Precondition: line2.GLHeader", lineForService.GLHeader);
			AssertEquals("lineForGoods.AL_GSTVATBasis", expectedValueForBoth, lineForGoods.AL_GSTVATBasis);
			AssertEquals("lineForService.AL_GSTVATBasis", expectedValueForBoth, lineForService.AL_GSTVATBasis);

			invoice.AH_OH = ZGuid.Empty;
			AssertEquals("lineForGoods.AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, lineForGoods.AL_GSTVATBasis);
			AssertEquals("lineForService.AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, lineForService.AL_GSTVATBasis);

			organisation.CompanyData.OB_APVATConfig = AccountingMasterFilesConstants.OrganisationTaxConfiguartionTypes.NotApplicable.Code;
			organisation.CompanyData.OB_ARVATConfig = AccountingMasterFilesConstants.OrganisationTaxConfiguartionTypes.Default.Code;
			invoice.AH_OH = organisation.PK;
			AssertEquals("lineForGoods.AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, lineForGoods.AL_GSTVATBasis);
			AssertEquals("lineForService.AL_GSTVATBasis", expectedValueForService, lineForService.AL_GSTVATBasis);

			lineForGoods.AL_AC = ZGuid.Empty;
			lineForService.AL_AC = ZGuid.Empty;
			AssertEquals("lineForGoods.AL_GSTVATBasis", expectedValueForService, lineForGoods.AL_GSTVATBasis);
			AssertEquals("lineForService.AL_GSTVATBasis", expectedValueForService, lineForService.AL_GSTVATBasis);

			lineForGoods.AL_AC = goodsChargeCode.PK;
			lineForGoods.AL_AT = TestObjectCreator.GST1.PK;
			lineForService.AL_AC = serviceChargeCode.PK;
			lineForService.AL_AT = TestObjectCreator.GST1.PK;
			AssertNotNull("Precondition: line1.ChargeCode", lineForGoods.ChargeCode);
			AssertNotNull("Precondition: line2.ChargeCode", lineForService.ChargeCode);
			AssertNotNull("Precondition: line1.TaxRate", lineForGoods.TaxRate);
			AssertNotNull("Precondition: line2.TaxRate", lineForService.TaxRate);
			AssertNotNull("Precondition: line1.GLHeader", lineForGoods.GLHeader);
			AssertNotNull("Precondition: line2.GLHeader", lineForService.GLHeader);
			AssertEquals("lineForGoods.AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, lineForGoods.AL_GSTVATBasis);
			AssertEquals("lineForService.AL_GSTVATBasis", expectedValueForService, lineForService.AL_GSTVATBasis);

			currentCompany.GC_IsGSTCashBasis = false;
			currentCompany.Factory.Save();
			AssertEquals("lineForGoods.AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, lineForGoods.AL_GSTVATBasis);
			AssertEquals("lineForService.AL_GSTVATBasis", expectedValueForService, lineForService.AL_GSTVATBasis);

			using (invoice.Lines.SuspendListChanged())
			{
				lineForGoods.AL_OSExTaxAmount = 10;
			}
			AssertEquals("lineForGoods.AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, lineForGoods.AL_GSTVATBasis);
			AssertEquals("lineForService.AL_GSTVATBasis", expectedValueForService, lineForService.AL_GSTVATBasis);

			using (invoice.Lines.SuspendListChanged())
			{
				invoice.SetLinesAL_GSTVATBasis();
				AssertEquals("lineForGoods.AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, lineForGoods.AL_GSTVATBasis);
				AssertEquals("lineForService.AL_GSTVATBasis", expectedValueForService, lineForService.AL_GSTVATBasis);
			}
			AssertEquals("lineForGoods.AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, lineForGoods.AL_GSTVATBasis);
			AssertEquals("lineForService.AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, lineForService.AL_GSTVATBasis);

			currentCompany.GC_IsGSTCashBasis = true;
			currentCompany.Factory.Save();
			AssertEquals("lineForGoods.AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, lineForGoods.AL_GSTVATBasis);
			AssertEquals("lineForService.AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, lineForService.AL_GSTVATBasis);

			invoice.SetLinesAL_GSTVATBasis();
			AssertEquals("lineForGoods.AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, lineForGoods.AL_GSTVATBasis);
			AssertEquals("lineForService.AL_GSTVATBasis", expectedValueForService, lineForService.AL_GSTVATBasis);
		}

		public void TestAH_FullyPaidDateSetAndCashBasisVATCreatedForIncompleteInvoiceWithCashVATLines()
		{
			var currentCompany = new BusinessObjectFactory().Load<GlbCompany>(GlbCompany.CurrentCompany.PK);
			currentCompany.GC_IsGSTCashBasis = true;
			currentCompany.Factory.Save();

			var chargeCode = TestObjectCreator.CC1;
			AssertEquals("Precondition: AC_GoodsServiceType", GoodServiceTypes.Codes.SRV, chargeCode.AC_GoodsServiceType);
			var taxRecognitionDefaultingRules = new TaxRecognitionDefaultingRules() { APInputServices = TaxRecognitionDefaultingRules.RecognitionTypesCashCode };
			AccountingConfigurationRegistry.Instance.TaxRecognitionDefaultingRules.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, taxRecognitionDefaultingRules);

			var job = TestObjectCreator.CreateAndSaveTestShipmentJob(JobHeaderStatus.Working.Code, false);
			var incompleteInvoice = TestObjectCreator.CreateInvoiceWithLine(typeof(APInvoice), "00001", TestObjectCreator.AUD, 1, 100, 10, 100, 10);
			incompleteInvoice.AH_OH = TestObjectCreator.Creditor1.PK;
			var line = incompleteInvoice.Lines[0];
			line.GenericCharge = TestObjectCreator.CC1.PK;
			line.AL_JH = job.PK;
			TestObjectCreator.CreateCharge(line);
			AssertNotNull("Precondition: invoice Tax Rate", incompleteInvoice.Lines[0].TaxRate);
			TestObjectCreator.CreateInvoiceLine(incompleteInvoice, TestObjectCreator.AUD, 1, -100, -10, 0, -100, -10, 0);
			AssertEquals("Precondition: invoice total must be zero", 0m, incompleteInvoice.AH_LocalTotalAmount);
			incompleteInvoice.SaveAsIncomplete();

			AssertEquals("AL_GSTVATBasis must not be set to Cash as ledger is not AP or AR", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Cash.Code, incompleteInvoice.Lines[0].AL_GSTVATBasis);
			var cashBasisVATs = new BusinessObjectFactory().Load<AccCashBasisVAT>(new ZQuery());
			AssertEquals("CashBasisVAT record must not be created for the Incomplete Invoice even with Cash basis tax line.", 0, cashBasisVATs.Length);

			var newFactory = new BusinessObjectFactory();
			var apInvoice = newFactory.Load<APInvoice>(incompleteInvoice.PK);
			apInvoice.RestoreSavedData();
			apInvoice.MoveFromIncompleteToPayableLedger();

			AssertEquals("Precondition: Outstanding Amount is zero", 0m, apInvoice.AH_OutstandingAmount);
			AssertEquals("Precondition: Invoice Fully Paid Date should not be set even though the Outstanding Amount is zero", ZDateTime.Empty, apInvoice.AH_FullyPaidDate);
			AssertEquals("Precondition: AH_Ledger must be changed", LedgerTypes.AccountsPayable, apInvoice.AH_Ledger);

			newFactory.Save();

			AssertEquals("Invoice Fully Paid Date should be set because the Incomplete Invoice transitioned to an AP Invoice", apInvoice.AH_InvoiceDate, apInvoice.AH_FullyPaidDate);
			AssertEquals("AL_GSTVATBasis must be set to Cash as ledger is AP now.", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Cash.Code, apInvoice.Lines[0].AL_GSTVATBasis);
			AssertEquals("AL_GSTVATBasis must not be set to Cash as line is not setup for Cash Basis VAT.", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, apInvoice.Lines[1].AL_GSTVATBasis);
			cashBasisVATs = new BusinessObjectFactory().Load<AccCashBasisVAT>(new ZQuery(AccCashBasisVATSchema.YC_AL_TransactionLine, apInvoice.Lines[0].PK));
			AssertEquals("CashBasisVAT record must be created for the invoice line with Cash basis tax..", 1, cashBasisVATs.Length);
			var cashBasisVAT = cashBasisVATs[0];
			AssertEquals("YC_MatchGroupNum", "", cashBasisVAT.YC_MatchGroupNum);
			AssertEquals("YC_PostDate", apInvoice.AH_FullyPaidDate, cashBasisVAT.YC_PostDate);
			AssertEquals("YC_TaxBaseAmount", apInvoice.Lines[0].AL_LineAmount, cashBasisVAT.YC_TaxBaseAmount);
			AssertEquals("YC_TaxAmount", apInvoice.Lines[0].AL_GSTVAT, cashBasisVAT.YC_TaxAmount);

			cashBasisVATs = new BusinessObjectFactory().Load<AccCashBasisVAT>(new ZQuery(AccCashBasisVATSchema.YC_AL_TransactionLine, apInvoice.Lines[1].PK));
			AssertEquals("CashBasisVAT record must not be created for the invoice line with Accrual basis tax.", 0, cashBasisVATs.Length);
		}

		public void TestAH_FullyPaidDateSetAndCashBasisVATCreatedForUnapprovedInvoiceWithCashVATLines()
		{
			var currentCompany = new BusinessObjectFactory().Load<GlbCompany>(GlbCompany.CurrentCompany.PK);
			currentCompany.GC_IsGSTCashBasis = true;
			currentCompany.Factory.Save();

			var chargeCode = TestObjectCreator.CC1;
			AssertEquals("Precondition: AC_GoodsServiceType", GoodServiceTypes.Codes.SRV, chargeCode.AC_GoodsServiceType);
			var taxRecognitionDefaultingRules = new TaxRecognitionDefaultingRules() { APInputServices = TaxRecognitionDefaultingRules.RecognitionTypesCashCode };
			AccountingConfigurationRegistry.Instance.TaxRecognitionDefaultingRules.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, taxRecognitionDefaultingRules);

			var job = TestObjectCreator.CreateAndSaveTestShipmentJob(JobHeaderStatus.Working.Code, false);
			var uaInvoice = TestObjectCreator.CreateInvoiceWithLine(typeof(UAInvoice), "00001", TestObjectCreator.AUD, 1, 100, 10, 100, 10);
			var expectedFullyPaidDate = ZDateTime.Today.AddDays(-5);
			uaInvoice.AH_InvoiceDate = expectedFullyPaidDate;
			uaInvoice.AH_OH = TestObjectCreator.Creditor1.PK;
			var line = uaInvoice.Lines[0];
			line.GenericCharge = TestObjectCreator.CC1.PK;
			line.AL_JH = job.PK;
			TestObjectCreator.CreateCharge(line);
			AssertNotNull("Precondition: invoice Tax Rate", uaInvoice.Lines[0].TaxRate);
			TestObjectCreator.CreateInvoiceLine(uaInvoice, TestObjectCreator.AUD, 1, -100, -10, 0, -100, -10, 0);
			AssertEquals("Precondition: invoice total must be zero", 0m, uaInvoice.AH_LocalTotalAmount);
			Factory.Save();

			AssertEquals("Precondition: Outstanding Amount is zero", 0m, uaInvoice.AH_OutstandingAmount);
			AssertEquals("Precondition: Invoice Fully Paid Date should be set as Outstanding Amount is zero", expectedFullyPaidDate, uaInvoice.AH_FullyPaidDate);
			AssertEquals("AL_GSTVATBasis must not be set to Cash as ledger is not AP or AR", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, uaInvoice.Lines[0].AL_GSTVATBasis);
			var cashBasisVATs = new BusinessObjectFactory().Load<AccCashBasisVAT>(new ZQuery());
			AssertEquals("CashBasisVAT record must not be created for the invoice line with Accrual basis tax.", 0, cashBasisVATs.Length);

			var newFactory = new BusinessObjectFactory();
			var apInvoice = new UnapprovedTransactionConverter(newFactory).ConvertToAP(newFactory.Load<UAInvoice>(uaInvoice.PK), false);
			apInvoice.AH_InvoiceDate = expectedFullyPaidDate.AddDays(2);

			AssertEquals("Precondition: Outstanding Amount is zero", 0m, apInvoice.AH_OutstandingAmount);
			AssertEquals("Precondition: Invoice Fully Paid Date should be unchanged", expectedFullyPaidDate, apInvoice.AH_FullyPaidDate);
			AssertEquals("Precondition: AH_Ledger must be changed", LedgerTypes.AccountsPayable, apInvoice.AH_Ledger);

			var invalidInvoiceInSavingFactory = new TestObjectCreator(apInvoice.Factory).CreateInvoice(typeof(APInvoice), "INV", TestObjectCreator.AUD, 1, TestObjectCreator.Creditor1);
			apInvoice.Factory.Saving += FactorySavingWithException;
			try
			{
				apInvoice.Factory.Save();
				Fail("Exception should be thrown to test unsuccessful saving.");
			}
			catch (NotImplementedException)
			{
			}
			finally
			{
				apInvoice.Factory.Saving -= FactorySavingWithException;
			}

			invalidInvoiceInSavingFactory.Delete();
			apInvoice.Factory.Save();

			AssertEquals("Invoice Fully Paid Date should be unchanged", expectedFullyPaidDate, apInvoice.AH_FullyPaidDate);
			AssertEquals("AL_GSTVATBasis must be set to Cash as ledger is AP now.", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Cash.Code, apInvoice.Lines[0].AL_GSTVATBasis);
			AssertEquals("AL_GSTVATBasis must not be set to Cash as line is not setup for Cash Basis VAT.", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, apInvoice.Lines[1].AL_GSTVATBasis);
			cashBasisVATs = new BusinessObjectFactory().Load<AccCashBasisVAT>(new ZQuery(AccCashBasisVATSchema.YC_AL_TransactionLine, apInvoice.Lines[0].PK));
			AssertEquals("CashBasisVAT record must be created for the invoice line with Cash basis tax..", 1, cashBasisVATs.Length);
			var cashBasisVAT = cashBasisVATs[0];
			AssertEquals("YC_MatchGroupNum", "", cashBasisVAT.YC_MatchGroupNum);
			AssertEquals("YC_PostDate", apInvoice.AH_FullyPaidDate, cashBasisVAT.YC_PostDate);
			AssertEquals("YC_TaxBaseAmount", apInvoice.Lines[0].AL_LineAmount, cashBasisVAT.YC_TaxBaseAmount);
			AssertEquals("YC_TaxAmount", apInvoice.Lines[0].AL_GSTVAT, cashBasisVAT.YC_TaxAmount);

			cashBasisVATs = new BusinessObjectFactory().Load<AccCashBasisVAT>(new ZQuery(AccCashBasisVATSchema.YC_AL_TransactionLine, apInvoice.Lines[1].PK));
			AssertEquals("CashBasisVAT record must not be created for the invoice line with Accrual basis tax.", 0, cashBasisVATs.Length);
		}

