				AssertEquals("YC_TaxAmount", line1.AL_GSTVAT, cashBasisVAT.YC_TaxAmount);
			}
			else
			{
				AssertEquals("AL_GSTVATBasis must not be set to Cash as ledger is not for Cash Basis VAT.", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, line1.AL_GSTVATBasis);
				var cashBasisVATs = new BusinessObjectFactory().Load<AccCashBasisVAT>(new ZQuery(AccCashBasisVATSchema.YC_AL_TransactionLine, line1.PK));
				AssertEquals("CashBasisVAT record must not be created for the invoice line with Accrual basis tax.", 0, cashBasisVATs.Length);
