			AssertEquals("CashBasisVAT record must not be created for the invoice line with Accrual basis tax.", 0, cashBasisVATs2.Length);
		}

		[SuspendGLAccountAndChargeCodeCriticalValidation]
		public void TestReverseFullyPayInvoiceAndCreateCashBasisVATWhenTotalIsZero()
		{
			var currentCompany = new BusinessObjectFactory().Load<GlbCompany>(GlbCompany.CurrentCompany.PK);
			currentCompany.GC_IsGSTCashBasis = true;
			currentCompany.Factory.Save();

			var chargeCode = TestObjectCreator.CC1;
			AssertEquals("Precondition: AC_GoodsServiceType", GoodServiceTypes.Codes.SRV, chargeCode.AC_GoodsServiceType);
			var taxRecognitionDefaultingRules = new TaxRecognitionDefaultingRules()
			{
				APInputServices = TaxRecognitionDefaultingRules.RecognitionTypesCashCode,
				AROutputServices = TaxRecognitionDefaultingRules.RecognitionTypesCashCode
			};
			AccountingConfigurationRegistry.Instance.TaxRecognitionDefaultingRules.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, taxRecognitionDefaultingRules);

			var job = TestObjectCreator.CreateAndSaveTestShipmentJob(JobHeaderStatus.Working.Code, false);
			var invoice = (InvoicingBase)Factory.New(GetExpectedBusinessObjectType());
			invoice.AH_OH = TestObjectCreator.Creditor1.PK;
			TestObjectCreator.Creditor1.OH_IsDebtor = true;
			var line1 = (InvoicingLineBase)invoice.Lines.AddNew();
			line1.GenericCharge = TestObjectCreator.CC1.PK;
			line1.AL_JH = job.PK;
			AssertNotNull("Precondition: invoice Tax Rate", line1.TaxRate);
			var line2 = (InvoicingLineBase)invoice.Lines.AddNew();
			line2.AL_AT = line1.AL_AT;

			line1.AL_OSExTaxAmount = 20m;
			line2.AL_OSExTaxAmount = -20m;
			TestObjectCreator.CreateCharge(line1);
			ZDateTime priorDate = PeriodManagementTestHelper.PreviousGLClosedPeriod.AM_EndDate;
			invoice.AH_InvoiceDate = priorDate;
			invoice.AH_PostDate = priorDate.AddDays(1);
			invoice.AH_TransactionNum = TestObjectCreator.GetRandomString(10);

			AssertEquals("Precondition - Total should be zero", 0m, invoice.AH_OSTotalAmount);
			AssertEquals("Precondition - Total should be zero", 0m, invoice.AH_InvoiceAmount);
			AssertEquals("Precondition - Total should be zero", 0m, invoice.AH_OSExTaxAmount);
			Assert("Precondition - Fully Paid Date should be empty", invoice.AH_FullyPaidDate.IsEmpty);

			Factory.Save();

			AssertEquals("Precondition: Fully Paid Date should be filled on saving to the date of the invoice when", priorDate, invoice.AH_FullyPaidDate);

			bool isCashBasisVATApplicable = invoice.IsReceivableOrPayable_ForTestOnly;

			if (isCashBasisVATApplicable)
			{
				AssertEquals("Precondition: AL_GSTVATBasis must be set to Cash as ledger is AP now.", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Cash.Code, line1.AL_GSTVATBasis);
				var cashBasisVATs = new BusinessObjectFactory().Load<AccCashBasisVAT>(new ZQuery(AccCashBasisVATSchema.YC_AL_TransactionLine, line1.PK));
				AssertEquals("Precondition: CashBasisVAT record must be created for the invoice line with Cash basis tax.", 1, cashBasisVATs.Length);
				var cashBasisVAT = cashBasisVATs[0];
				AssertEquals("Precondition: YC_MatchGroupNum", "", cashBasisVAT.YC_MatchGroupNum);
				AssertEquals("Precondition: YC_PostDate", invoice.AH_FullyPaidDate, cashBasisVAT.YC_PostDate);
				AssertEquals("Precondition: YC_TaxBaseAmount", line1.AL_LineAmount, cashBasisVAT.YC_TaxBaseAmount);
				AssertEquals("Precondition: YC_TaxAmount", line1.AL_GSTVAT, cashBasisVAT.YC_TaxAmount);
			}
			else
			{
				AssertEquals("Precondition: AL_GSTVATBasis must not be set to Cash as ledger is not for Cash Basis VAT.", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, line1.AL_GSTVATBasis);
				var cashBasisVATs = new BusinessObjectFactory().Load<AccCashBasisVAT>(new ZQuery(AccCashBasisVATSchema.YC_AL_TransactionLine, line1.PK));
				AssertEquals("Precondition: CashBasisVAT record must not be created for the invoice line with Accrual basis tax.", 0, cashBasisVATs.Length);
			}
			AssertEquals("Precondition: AL_GSTVATBasis must not be set to Cash as line is not setup for Cash Basis VAT.", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, line2.AL_GSTVATBasis);
			var cashBasisVATs2 = new BusinessObjectFactory().Load<AccCashBasisVAT>(new ZQuery(AccCashBasisVATSchema.YC_AL_TransactionLine, line2.PK));
			AssertEquals("Precondition: CashBasisVAT record must not be created for the invoice line with Accrual basis tax.", 0, cashBasisVATs2.Length);

			var previousFullyPaidDate = invoice.AH_FullyPaidDate;
			string cantReverseReason;
			var reversedTransaction = (InvoicingBase)TestObjectCreator.ReverseTransaction(invoice, out cantReverseReason);
			Assert("Precondition: invoice must be valid for reversing.", string.IsNullOrEmpty(cantReverseReason));
			var isUnapprovedPayableTransactions = invoice.AH_Ledger == LedgerTypes.UnapprovedPayableTransactions;
			var line1PK = line1.PK;
			var line2PK = line2.PK;
			if (isUnapprovedPayableTransactions)
			{
				reversedTransaction = invoice;
				invoice.Delete(); //That makes it identical to what happens functionally on the Unapproved Transactions module.
			}
			AssertNotNull("Precondition: Reversed transaction should be created.", reversedTransaction);
			reversedTransaction.AH_PostDate = invoice.AH_PostDate.AddDays(1);
			reversedTransaction.AH_TransactionNum = "0000002";
			Factory.Save();

			Assert("Precondition: invoice.AH_IsCancelled", invoice.AH_IsCancelled);
			Assert("Precondition: reversedTransaction.AH_IsCancelled", reversedTransaction.AH_IsCancelled);

			TransactionMatchLink expectedReversingMatchLink = null;
			if (isCashBasisVATApplicable)
			{
				var expectedReversingMatchLinks = Factory.Load<TransactionMatchLink>(new ZQuery(AccTransactionMatchLinkSchema.AP_AH, invoice.PK));
				AssertEquals("Precondition: Reversing matchlinks count", 1, expectedReversingMatchLinks.Length);
				expectedReversingMatchLink = expectedReversingMatchLinks[0];
				AssertNotEquals("Precondition: reverse date is not equal previous invoice fully paid date.", previousFullyPaidDate, expectedReversingMatchLink.AP_MatchDate);
				AssertEquals("Precondition: reverse date is equal invoice fully paid date.", reversedTransaction.AH_PostDate, expectedReversingMatchLink.AP_MatchDate);

				var cashBasisVATsReversed = new BusinessObjectFactory().Load<AccCashBasisVAT>(new ZQuery(AccCashBasisVATSchema.YC_AL_TransactionLine, line1.PK));
				AssertEquals("CashBasisVAT record must be created for the invoice line with Cash basis tax.", 3, cashBasisVATsReversed.Length);
				var cashBasisVATOriginal = cashBasisVATsReversed.Where(item => item.YC_MatchGroupNum == "" && item.YC_TaxBaseAmount == line1.AL_LineAmount).First();
				var cashBasisVATOriginalReversed = cashBasisVATsReversed.Where(item => item.YC_MatchGroupNum == "" && item.YC_TaxBaseAmount == -line1.AL_LineAmount).First();
				var cashBasisVATReversed = cashBasisVATsReversed.Where(item => item.YC_MatchGroupNum != "").First();
				AssertEquals("YC_MatchGroupNum", "", cashBasisVATOriginal.YC_MatchGroupNum);
				AssertEquals("YC_PostDate", previousFullyPaidDate, cashBasisVATOriginal.YC_PostDate);
				AssertEquals("YC_TaxBaseAmount", line1.AL_LineAmount, cashBasisVATOriginal.YC_TaxBaseAmount);
				AssertEquals("YC_TaxAmount", line1.AL_GSTVAT, cashBasisVATOriginal.YC_TaxAmount);

				AssertEquals("YC_MatchGroupNum", "", cashBasisVATOriginalReversed.YC_MatchGroupNum);
				AssertEquals("YC_PostDate", expectedReversingMatchLink.AP_MatchDate, cashBasisVATOriginalReversed.YC_PostDate);
				AssertEquals("YC_TaxBaseAmount", -line1.AL_LineAmount, cashBasisVATOriginalReversed.YC_TaxBaseAmount);
				AssertEquals("YC_TaxAmount", -line1.AL_GSTVAT, cashBasisVATOriginalReversed.YC_TaxAmount);

				AssertEquals("YC_MatchGroupNum", expectedReversingMatchLink.AP_MatchGroupNum, cashBasisVATReversed.YC_MatchGroupNum);
				AssertEquals("YC_PostDate", expectedReversingMatchLink.AP_MatchDate, cashBasisVATReversed.YC_PostDate);
				AssertEquals("YC_TaxBaseAmount", line1.AL_LineAmount, cashBasisVATReversed.YC_TaxBaseAmount);
				AssertEquals("YC_TaxAmount", line1.AL_GSTVAT, cashBasisVATReversed.YC_TaxAmount);
			}
			else
			{
				if (isUnapprovedPayableTransactions)
				{
					AssertEquals(true, line1.IsDeleted);
				}
				else
				{
					AssertEquals("Precondition: AL_GSTVATBasis must not be set to Cash as ledger is not for Cash Basis VAT.", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, line1.AL_GSTVATBasis);
				}

				var cashBasisVATs = new BusinessObjectFactory().Load<AccCashBasisVAT>(new ZQuery(AccCashBasisVATSchema.YC_AL_TransactionLine, line1PK));
				AssertEquals("Precondition: CashBasisVAT record must not be created for the invoice line with Accrual basis tax.", 0, cashBasisVATs.Length);
			}

			if (isUnapprovedPayableTransactions)
			{
				AssertEquals(true, line2.IsDeleted);
			}
			else
			{
				AssertEquals("AL_GSTVATBasis must not be set to Cash as line is not setup for Cash Basis VAT.", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, line2.AL_GSTVATBasis);
			}
			var cashBasisVATsReversed2 = new BusinessObjectFactory().Load<AccCashBasisVAT>(new ZQuery(AccCashBasisVATSchema.YC_AL_TransactionLine, line2PK));
			AssertEquals("CashBasisVAT record must not be created for the invoice line with Accrual basis tax.", 0, cashBasisVATsReversed2.Length);

			if (!isUnapprovedPayableTransactions)
			{
				AssertEquals("reversedTransaction.Lines.Count", 2, reversedTransaction.Lines.Count);
				var reversedLine1 = reversedTransaction.Lines.Cast<InvoicingLineBase>().First(item => item.AL_LineAmount == -line1.AL_LineAmount);
				var reversedLine2 = reversedTransaction.Lines.Cast<InvoicingLineBase>().First(item => item.AL_LineAmount == -line2.AL_LineAmount);
				if (isCashBasisVATApplicable)
				{
					var expectedReversingMatchLinks = Factory.Load<TransactionMatchLink>(new ZQuery(AccTransactionMatchLinkSchema.AP_AH, reversedTransaction.PK));
					AssertEquals("Precondition: Reversing matchlinks count", 1, expectedReversingMatchLinks.Length);
					expectedReversingMatchLink = expectedReversingMatchLinks[0];
					AssertEquals("Precondition: reverse date is equal invoice fully paid date.", reversedTransaction.AH_PostDate, expectedReversingMatchLink.AP_MatchDate);

					AssertEquals("AL_GSTVATBasis must be set to Cash.", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Cash.Code, reversedLine1.AL_GSTVATBasis);
					var cashBasisVATsReversed = new BusinessObjectFactory().Load<AccCashBasisVAT>(new ZQuery(AccCashBasisVATSchema.YC_AL_TransactionLine, reversedLine1.PK));
					AssertEquals("CashBasisVAT record must be created for the invoice line with Cash basis tax.", 1, cashBasisVATsReversed.Length);
					var cashBasisVATReversed = cashBasisVATsReversed[0];
					AssertEquals("YC_MatchGroupNum", expectedReversingMatchLink.AP_MatchGroupNum, cashBasisVATReversed.YC_MatchGroupNum);
					AssertEquals("YC_PostDate", expectedReversingMatchLink.AP_MatchDate, cashBasisVATReversed.YC_PostDate);
					AssertEquals("YC_TaxBaseAmount", -line1.AL_LineAmount, cashBasisVATReversed.YC_TaxBaseAmount);
					AssertEquals("YC_TaxAmount", -line1.AL_GSTVAT, cashBasisVATReversed.YC_TaxAmount);
				}
				else
				{
					AssertEquals("Precondition: AL_GSTVATBasis must not be set to Cash as ledger is not for Cash Basis VAT.", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, reversedLine1.AL_GSTVATBasis);
					var cashBasisVATs = new BusinessObjectFactory().Load<AccCashBasisVAT>(new ZQuery(AccCashBasisVATSchema.YC_AL_TransactionLine, reversedLine1.PK));
					AssertEquals("Precondition: CashBasisVAT record must not be created for the invoice line with Accrual basis tax.", 0, cashBasisVATs.Length);
				}

				AssertEquals("AL_GSTVATBasis must not be set to Cash as line is not setup for Cash Basis VAT.", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, reversedLine2.AL_GSTVATBasis);
				cashBasisVATsReversed2 = new BusinessObjectFactory().Load<AccCashBasisVAT>(new ZQuery(AccCashBasisVATSchema.YC_AL_TransactionLine, line2.PK));
				AssertEquals("CashBasisVAT record must not be created for the invoice line with Accrual basis tax.", 0, cashBasisVATsReversed2.Length);
			}
			else
			{
				AssertEquals("reversedTransaction.Lines.Count", 0, reversedTransaction.Lines.Count);
			}
		}

		[SuspendGLAccountAndChargeCodeCriticalValidation]
		public void TestWriteOffFullyPayInvoiceAndCreateCashBasisVATWhenTotalIsZero()
		{
			// Test DB will not have the StmData base data, which contains the default value for bad debt for the registry.
			// So add bad debt into the registry for this test
			AccGLHeader badDebtAccount = Factory.LoadTop1<AccGLHeader>(new ZQuery(AccGLHeaderSchema.AG_AccountNum, "3980.00.00"));
			AccountingConfigurationRegistry.Instance.BadDebtWriteOffAccount.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, badDebtAccount.PK.ToGuid());

			var currentCompany = new BusinessObjectFactory().Load<GlbCompany>(GlbCompany.CurrentCompany.PK);
			currentCompany.GC_IsGSTCashBasis = true;
			currentCompany.Factory.Save();

			var chargeCode = TestObjectCreator.CC1;
			AssertEquals("Precondition: AC_GoodsServiceType", GoodServiceTypes.Codes.SRV, chargeCode.AC_GoodsServiceType);
			var taxRecognitionDefaultingRules = new TaxRecognitionDefaultingRules()
			{
				APInputServices = TaxRecognitionDefaultingRules.RecognitionTypesCashCode,
				AROutputServices = TaxRecognitionDefaultingRules.RecognitionTypesCashCode
			};
			AccountingConfigurationRegistry.Instance.TaxRecognitionDefaultingRules.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, taxRecognitionDefaultingRules);

			var job = TestObjectCreator.CreateAndSaveTestShipmentJob(JobHeaderStatus.Working.Code, false);
			var invoice = (InvoicingBase)Factory.New(GetExpectedBusinessObjectType());
			if (!(invoice is IBadDebtWritingOff))
			{
				Assert("This test is only for transactions supported Bad Debt Writing Off (AR Invoice/CreditNote).", true);
				return;
			}

			invoice.AH_OH = TestObjectCreator.Creditor1.PK;
			TestObjectCreator.Creditor1.OH_IsDebtor = true;
			var line1 = (InvoicingLineBase)invoice.Lines.AddNew();
			line1.GenericCharge = TestObjectCreator.CC1.PK;
			line1.AL_JH = job.PK;
			AssertNotNull("Precondition: invoice Tax Rate", line1.TaxRate);
			var line2 = (InvoicingLineBase)invoice.Lines.AddNew();
			line2.AL_AT = line1.AL_AT;

			line1.AL_OSExTaxAmount = 20m;
			line2.AL_OSExTaxAmount = -20m;
			TestObjectCreator.CreateCharge(line1);
			ZDateTime priorDate = PeriodManagementTestHelper.PreviousGLClosedPeriod.AM_EndDate;
			invoice.AH_InvoiceDate = priorDate;
			invoice.AH_PostDate = priorDate.AddDays(1);
			invoice.AH_TransactionNum = TestObjectCreator.GetRandomString(10);

			AssertEquals("Precondition - Total should be zero", 0m, invoice.AH_OSTotalAmount);
			AssertEquals("Precondition - Total should be zero", 0m, invoice.AH_InvoiceAmount);
			AssertEquals("Precondition - Total should be zero", 0m, invoice.AH_OSExTaxAmount);
			Assert("Precondition - Fully Paid Date should be empty", invoice.AH_FullyPaidDate.IsEmpty);

			Factory.Save();

			AssertEquals("Precondition: Fully Paid Date should be filled on saving to the date of the invoice when", priorDate, invoice.AH_FullyPaidDate);

			AssertEquals("Precondition: AL_GSTVATBasis must be set to Cash as ledger is AP now.", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Cash.Code, line1.AL_GSTVATBasis);
			var cashBasisVATs = new BusinessObjectFactory().Load<AccCashBasisVAT>(new ZQuery(AccCashBasisVATSchema.YC_AL_TransactionLine, line1.PK));
			AssertEquals("Precondition: CashBasisVAT record must be created for the invoice line with Cash basis tax.", 1, cashBasisVATs.Length);
			var cashBasisVAT = cashBasisVATs[0];
			AssertEquals("Precondition: YC_MatchGroupNum", "", cashBasisVAT.YC_MatchGroupNum);
			AssertEquals("Precondition: YC_PostDate", invoice.AH_FullyPaidDate, cashBasisVAT.YC_PostDate);
			AssertEquals("Precondition: YC_TaxBaseAmount", line1.AL_LineAmount, cashBasisVAT.YC_TaxBaseAmount);
			AssertEquals("Precondition: YC_TaxAmount", line1.AL_GSTVAT, cashBasisVAT.YC_TaxAmount);

			AssertEquals("Precondition: AL_GSTVATBasis must not be set to Cash as line is not setup for Cash Basis VAT.", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, line2.AL_GSTVATBasis);
			var cashBasisVATs2 = new BusinessObjectFactory().Load<AccCashBasisVAT>(new ZQuery(AccCashBasisVATSchema.YC_AL_TransactionLine, line2.PK));
			AssertEquals("Precondition: CashBasisVAT record must not be created for the invoice line with Accrual basis tax.", 0, cashBasisVATs2.Length);

			var previousFullyPaidDate = invoice.AH_FullyPaidDate;
			string cantWriteOffReason;
			var writtenOffTransaction = (InvoicingBase)TestObjectCreator.WriteOffBadDebt(invoice as IBadDebtWritingOff, out cantWriteOffReason);
			Assert("Precondition: invoice must be valid for Writing Off.", string.IsNullOrEmpty(cantWriteOffReason));
			if (invoice.AH_Ledger == LedgerTypes.UnapprovedPayableTransactions)
			{
				writtenOffTransaction = invoice;
			}
			AssertNotNull("Precondition: Written Off transaction should be created.", writtenOffTransaction);
			writtenOffTransaction.AH_PostDate = invoice.AH_PostDate.AddDays(1);
			Factory.Save();

			Assert("Precondition: invoice.AH_IsCancelled", !invoice.AH_IsCancelled);
			Assert("Precondition: writtenOffTransaction.AH_IsCancelled", !writtenOffTransaction.AH_IsCancelled);

			TransactionMatchLink expectedWrittenOffMatchLink = null;
			var expectedWrittenOffMatchLinks = Factory.Load<TransactionMatchLink>(new ZQuery(AccTransactionMatchLinkSchema.AP_AH, invoice.PK));
			AssertEquals("Precondition: WrittenOff matchlinks count", 1, expectedWrittenOffMatchLinks.Length);
			expectedWrittenOffMatchLink = expectedWrittenOffMatchLinks[0];
			AssertNotEquals("Precondition: WrittenOff date is not equal previous invoice fully paid date.", previousFullyPaidDate, expectedWrittenOffMatchLink.AP_MatchDate);
			AssertEquals("Precondition: WrittenOff date is equal invoice fully paid date.", writtenOffTransaction.AH_PostDate, expectedWrittenOffMatchLink.AP_MatchDate);

			var cashBasisVATsWrittenOff = new BusinessObjectFactory().Load<AccCashBasisVAT>(new ZQuery(AccCashBasisVATSchema.YC_AL_TransactionLine, line1.PK));
			AssertEquals("CashBasisVAT record must be created for the invoice line with Cash basis tax.", 3, cashBasisVATsWrittenOff.Length);
			var cashBasisVATOriginal = cashBasisVATsWrittenOff.Where(item => item.YC_MatchGroupNum == "" && item.YC_TaxBaseAmount == line1.AL_LineAmount).First();
			var cashBasisVATOriginalWrittenOff = cashBasisVATsWrittenOff.Where(item => item.YC_MatchGroupNum == "" && item.YC_TaxBaseAmount == -line1.AL_LineAmount).First();
			var cashBasisVATWrittenOff = cashBasisVATsWrittenOff.Where(item => item.YC_MatchGroupNum != "").First();
			AssertEquals("YC_MatchGroupNum", "", cashBasisVATOriginal.YC_MatchGroupNum);
			AssertEquals("YC_PostDate", previousFullyPaidDate, cashBasisVATOriginal.YC_PostDate);
			AssertEquals("YC_TaxBaseAmount", line1.AL_LineAmount, cashBasisVATOriginal.YC_TaxBaseAmount);
			AssertEquals("YC_TaxAmount", line1.AL_GSTVAT, cashBasisVATOriginal.YC_TaxAmount);

			AssertEquals("YC_MatchGroupNum", "", cashBasisVATOriginalWrittenOff.YC_MatchGroupNum);
			AssertEquals("YC_PostDate", expectedWrittenOffMatchLink.AP_MatchDate, cashBasisVATOriginalWrittenOff.YC_PostDate);
			AssertEquals("YC_TaxBaseAmount", -line1.AL_LineAmount, cashBasisVATOriginalWrittenOff.YC_TaxBaseAmount);
			AssertEquals("YC_TaxAmount", -line1.AL_GSTVAT, cashBasisVATOriginalWrittenOff.YC_TaxAmount);

			AssertEquals("YC_MatchGroupNum", expectedWrittenOffMatchLink.AP_MatchGroupNum, cashBasisVATWrittenOff.YC_MatchGroupNum);
			AssertEquals("YC_PostDate", expectedWrittenOffMatchLink.AP_MatchDate, cashBasisVATWrittenOff.YC_PostDate);
			AssertEquals("YC_TaxBaseAmount", line1.AL_LineAmount, cashBasisVATWrittenOff.YC_TaxBaseAmount);
			AssertEquals("YC_TaxAmount", line1.AL_GSTVAT, cashBasisVATWrittenOff.YC_TaxAmount);

			AssertEquals("AL_GSTVATBasis must not be set to Cash as line is not setup for Cash Basis VAT.", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, line2.AL_GSTVATBasis);
			var cashBasisVATsWrittenOff2 = new BusinessObjectFactory().Load<AccCashBasisVAT>(new ZQuery(AccCashBasisVATSchema.YC_AL_TransactionLine, line2.PK));
			AssertEquals("CashBasisVAT record must not be created for the invoice line with Accrual basis tax.", 0, cashBasisVATsWrittenOff2.Length);

			AssertEquals("WrittenOffTransaction.Lines.Count", 2, writtenOffTransaction.Lines.Count);
			var writtenOffLine1 = writtenOffTransaction.Lines.Cast<InvoicingLineBase>().First(item => item.AL_LineAmount == -line1.AL_LineAmount);
			var writtenOffLine2 = writtenOffTransaction.Lines.Cast<InvoicingLineBase>().First(item => item.AL_LineAmount == -line2.AL_LineAmount);
			AssertEquals("AL_GSTVATBasis must be set to Cash as gl account treated as service.", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Cash.Code, writtenOffLine1.AL_GSTVATBasis);
			cashBasisVATsWrittenOff = new BusinessObjectFactory().Load<AccCashBasisVAT>(new ZQuery(AccCashBasisVATSchema.YC_AL_TransactionLine, writtenOffLine1.PK));
			AssertEquals("CashBasisVAT record must not be created for the invoice line with Accrual basis tax.", 1, cashBasisVATs.Length);
			cashBasisVATWrittenOff = cashBasisVATsWrittenOff[0];
			AssertEquals("YC_MatchGroupNum", expectedWrittenOffMatchLink.AP_MatchGroupNum, cashBasisVATWrittenOff.YC_MatchGroupNum);
			AssertEquals("YC_PostDate", expectedWrittenOffMatchLink.AP_MatchDate, cashBasisVATWrittenOff.YC_PostDate);
			AssertEquals("YC_TaxBaseAmount", writtenOffLine1.AL_LineAmount, cashBasisVATWrittenOff.YC_TaxBaseAmount);
			AssertEquals("YC_TaxAmount", writtenOffLine1.AL_GSTVAT, cashBasisVATWrittenOff.YC_TaxAmount);

			AssertEquals("AL_GSTVATBasis must be set to Cash as gl account treated as service.", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Cash.Code, writtenOffLine2.AL_GSTVATBasis);
			cashBasisVATsWrittenOff2 = new BusinessObjectFactory().Load<AccCashBasisVAT>(new ZQuery(AccCashBasisVATSchema.YC_AL_TransactionLine, writtenOffLine2.PK));
			AssertEquals("CashBasisVAT record must not be created for the invoice line with Accrual basis tax.", 1, cashBasisVATsWrittenOff2.Length);
			var cashBasisVATWrittenOff2 = cashBasisVATsWrittenOff2[0];
			AssertEquals("YC_MatchGroupNum", expectedWrittenOffMatchLink.AP_MatchGroupNum, cashBasisVATWrittenOff2.YC_MatchGroupNum);
			AssertEquals("YC_PostDate", expectedWrittenOffMatchLink.AP_MatchDate, cashBasisVATWrittenOff2.YC_PostDate);
			AssertEquals("YC_TaxBaseAmount", writtenOffLine2.AL_LineAmount, cashBasisVATWrittenOff2.YC_TaxBaseAmount);
			AssertEquals("YC_TaxAmount", writtenOffLine2.AL_GSTVAT, cashBasisVATWrittenOff2.YC_TaxAmount);
		}

