		#region TestRealizeOtherTaxesWhenTotalIsZero

		public void TestRealizeOtherTaxesWhenTotalIsZero_NotInDB_NotZero()
		{
			AssertFullyPayInvoiceAndRealizeOtherTaxesWhenTotalIsZero(false, false);
		}

		public void TestRealizeOtherTaxesWhenTotalIsZero_NotInDB_Zero()
		{
			AssertFullyPayInvoiceAndRealizeOtherTaxesWhenTotalIsZero(false, true);
		}

		public void TestRealizeOtherTaxesWhenTotalIsZero_InDB_NotZero()
		{
			AssertFullyPayInvoiceAndRealizeOtherTaxesWhenTotalIsZero(true, false);
		}

		public void TestRealizeOtherTaxesWhenTotalIsZero_InDB_Zero()
		{
			AssertFullyPayInvoiceAndRealizeOtherTaxesWhenTotalIsZero(true, true);
		}

		void AssertFullyPayInvoiceAndRealizeOtherTaxesWhenTotalIsZero(bool isInDb, bool isZeroValued)
		{
			if (GetExpectedBusinessObjectType().FullName == ClientSWLARINvoiceTypeThatNeedToBeRemoved)
			{
				Assert("This invoice will be refactored and removed. It should not be inherited from AR Invoice and just replaced with set of extension methods. After that change this IF can be removed.", true);
				return;
			}

			Header.Delete();

			var invoice = (InvoicingBase)Factory.New(GetExpectedBusinessObjectType());
			if (invoice.AH_Ledger != LedgerTypes.AccountsPayable && invoice.AH_Ledger != LedgerTypes.AccountsReceivable)
			{
				Assert("Test is only for AR/ AP transactions", true);
				return;
			}
			if (isInDb && invoice.AH_Ledger != LedgerTypes.AccountsPayable)
			{
				Assert("Test is only for AP transactions", true);
				return;
			}

			invoice.AH_OH = TestObjectCreator.TestOrganisation.PK;
			var line1 = (InvoicingLineBase)invoice.Lines.AddNew();
			var line2 = (InvoicingLineBase)invoice.Lines.AddNew();
			line1.GenericCharge = TestObjectCreator.OverheadChargeCode.PK;
			line2.GenericCharge = line1.GenericCharge;
			line1.AL_OSExTaxAmount = isZeroValued ? 20m : 30m;
			line2.AL_OSExTaxAmount = -20m;
			var expectedInvoiceDate = ZDateTime.Today.AddDays(-7);
			invoice.AH_InvoiceDate = expectedInvoiceDate;
			var expectedPostDate = ZDateTime.Now.AddDays(-3);
			invoice.AH_PostDate = expectedPostDate;
			invoice.AH_TransactionNum = TestObjectCreator.GetRandomString(10);

			if (isInDb)
			{
				invoice.SaveAsIncomplete();
				invoice.MoveFromIncompleteToPayableLedger();
			}

			if (isZeroValued)
			{
				AssertEquals("Precondition: AH_OSTotalAmount", 0m, invoice.AH_OSTotalAmount);
			}
			else
			{
				AssertNotEquals("Precondition: AH_OSTotalAmount", 0m, invoice.AH_OSTotalAmount);
			}
			Assert("Precondition: Fully Paid Date ", invoice.AH_FullyPaidDate.IsEmpty);
			AssertEquals("Precondition: IsInDatabase", isInDb, invoice.IsInDatabase);

			var taxProcessorMock = new Mock<ITaxProcessor>();
			ObjectFactory.Substitute(taxProcessorMock.Object);

			Factory.Save();

			AssertEquals("Postcondition: Fully Paid Date should be filled on saving to the date of the invoice when", isZeroValued ? expectedInvoiceDate : ZDateTime.Empty, invoice.AH_FullyPaidDate);
			taxProcessorMock.Verify(x => x.ProcessTaxesOnMatching(TaxFrameworkObjectFactory.GetInvoicingBaseTaxRecordParent(invoice), expectedPostDate.Date), isZeroValued ? Times.Once() : Times.Never());
		}

		const string ClientSWLARINvoiceTypeThatNeedToBeRemoved = "Enterprise.Client.SWL.Business.ShipnetARInvoice";

		public void TestRealizeOtherTaxesIsCalledBeforeBeforeGLMovementProcessorWhenTotalIsZero()
		{
			if (GetExpectedBusinessObjectType().FullName == ClientSWLARINvoiceTypeThatNeedToBeRemoved)
			{
				Assert("This invoice will be refactored and removed. It should not be inherited from AR Invoice and just replaced with set of extension methods. After that change this IF can be removed.", true);
				return;
			}

			Header.Delete();

			var invoice = (InvoicingBase)Factory.New(GetExpectedBusinessObjectType());
			if (invoice.AH_Ledger != LedgerTypes.AccountsPayable && invoice.AH_Ledger != LedgerTypes.AccountsReceivable)
			{
				Assert("Test is only for AR/ AP transactions", true);
				return;
			}

			invoice.AH_OH = TestObjectCreator.TestOrganisation.PK;
			var line1 = (InvoicingLineBase)invoice.Lines.AddNew();
			var line2 = (InvoicingLineBase)invoice.Lines.AddNew();
			line1.GenericCharge = TestObjectCreator.OverheadChargeCode.PK;
			line2.GenericCharge = line1.GenericCharge;
			line1.AL_OSExTaxAmount = 20m;
			line2.AL_OSExTaxAmount = -20m;
			invoice.AH_TransactionNum = TestObjectCreator.GetRandomString(10);

			var taxTransactionsParams = new CreateTaxTransactionParameters
			{
				TransactionHeader = invoice,
				OsTaxAmount = 10,
				LocalTaxAmount = 10,
				AffectsSourceTransactionTotal = false,
			};
			var taxTransaction = TFObjectCreator.CreateTaxTransaction(taxTransactionsParams);
			TFObjectCreator.CreateTaxTransactionLinePivot(taxTransaction.PK, TaxFrameworkObjectFactory.GetInvoicingLineBaseTaxable(line1));

			AssertEquals("Precondition: AH_OSTotalAmount", 0m, invoice.AH_OSTotalAmount);
			Assert("Precondition: Fully Paid Date ", invoice.AH_FullyPaidDate.IsEmpty);

			var sequence = new MockSequence();

			var taxProcessorMock = new Mock<ITaxProcessor>(MockBehavior.Strict);
			taxProcessorMock.InSequence(sequence).Setup(x => x.ProcessTaxesOnMatching(It.IsAny<ITaxRecordParent>(), It.IsAny<ZDate>()));
			ObjectFactory.Substitute(taxProcessorMock.Object);
			var glMovementProcessor = new Mock<IGLMovementProcessor>(MockBehavior.Strict);
			taxTransaction.SubstituteGLMovementProcessor_ForTestOnly(glMovementProcessor.Object);
			glMovementProcessor.InSequence(sequence).Setup(x => x.CreateGLMovements(It.IsAny<AccTaxTransaction>()));
			var tfDependencyFactory = new Mock<ITaxFrameworkDependencyFactory>();
			var emptyValidatorMock = new Mock<IAccTaxTransactionCriticalValidator>();
			tfDependencyFactory.Setup(x => x.GetAccTaxTransactionCriticalValidator(taxTransaction)).Returns(emptyValidatorMock.Object);
			ObjectFactory.Substitute(tfDependencyFactory.Object);

			Factory.Save();

			Assert("Postcondition: Fully Paid Date is set", !invoice.AH_FullyPaidDate.IsEmpty);
			taxProcessorMock.Verify(x => x.ProcessTaxesOnMatching(TaxFrameworkObjectFactory.GetInvoicingBaseTaxRecordParent(invoice), It.IsAny<ZDate>()), Times.Once);
			glMovementProcessor.Verify(x => x.CreateGLMovements(It.IsAny<AccTaxTransaction>()), Times.Once);
		}

