		#region Test Helpers

		public static void SetupForTestingNOTREPORTMessagesDisplay(InvoicingBase invoice)
		{
			TestObjectCreator testObjectCreator = new TestObjectCreator(invoice.Factory);
			ForwardingShipment euShipment = invoice.Factory.NewWithValidTestData<ForwardingShipment>();
			euShipment.JS_RL_NKOrigin = "ZABAR";
			euShipment.JS_RL_NKDestination = "JPTYO";
			Job job1 = invoice.Factory.NewJobWithValidTestDataForTesting<Job>();
			job1.JH_ParentID = euShipment.PK;
			job1.JH_ParentTableCode = "JS";
			ForwardingShipment nonEUShipment = invoice.Factory.NewWithValidTestData<ForwardingShipment>();
			nonEUShipment.JS_RL_NKOrigin = "SGSIN";
			nonEUShipment.JS_RL_NKDestination = "AUSYD";
			Job job2 = invoice.Factory.NewJobWithValidTestDataForTesting<Job>();
			job2.JH_ParentID = nonEUShipment.PK;
			job2.JH_ParentTableCode = "JS";

			AccTaxRate notReport = invoice.Factory.LoadTop1<AccTaxRate>(new ZQuery(AccTaxRateSchema.AT_Code, "NOTREPORT"));
			AccInvMsg message = invoice.Factory.NewWithValidTestData<AccInvMsg>();
			message.A9_EnglishMsg = "NOTREPORT ENGLISH MESSAGE";
			message.A9_LocalMsg = "NOTREPORT LOCAL MESSAGE";
			notReport.AT_A9_DefaultVatClass = message.PK;

			InvoicingLineBase line = (InvoicingLineBase)invoice.Lines.AddNew();
			line.AL_AG = testObjectCreator.GLHeader1.PK;
			line.AL_OSExTaxAmount = 500m;
			line.AL_AT = notReport.PK;
			line.AL_JH = job1.PK;
			testObjectCreator.CreateJobCharge(line, job1, testObjectCreator.CC1, testObjectCreator.AUD);

