		public void TestOrganisationAddressWithContact()
		{
			var orgContact = TestObjectCreator.AALSHI.Contacts.AddNew();
			orgContact.OC_ContactName = "Fred";
			orgContact = TestObjectCreator.ABIGAS.Contacts.AddNew();
			orgContact.OC_ContactName = "Fred";
