			AssertEquals("Address PK is fed through", TestObjectCreator.AALSHI.Addresses[0].PK, oaWithContact.AddressFK);
			AssertEquals("Org PK is fed through", TestObjectCreator.AALSHI.PK, oaWithContact.OrgPK);
			AssertEquals("Contact PK is fed through", TestObjectCreator.AALSHI.Contacts[0].PK, oaWithContact.ContactFK);
			oaWithContact.AddressFK = TestObjectCreator.ABIGAS.Addresses[0].PK;
			oaWithContact.ContactFK = TestObjectCreator.ABIGAS.Contacts[0].PK;
			AssertEquals("Address PK is fed back", InvoicingBase.DisplayInvoiceAddressOverrideForAddressControl, TestObjectCreator.ABIGAS.Addresses[0].PK);
			AssertEquals("Address PK is fed back", InvoicingBase.AH_OA_InvoiceAddressOverride, TestObjectCreator.ABIGAS.Addresses[0].PK);
			AssertEquals("Org PK is fed back", InvoicingBase.AH_OH, TestObjectCreator.ABIGAS.PK);
			AssertEquals("Contact PK is fed back", InvoicingBase.DisplayInvoiceContactOverride, TestObjectCreator.ABIGAS.Contacts[0].PK);
			AssertEquals("Contact PK is fed back", InvoicingBase.AH_OC_InvoiceContactOverride, TestObjectCreator.ABIGAS.Contacts[0].PK);
		}

		public void TestUseJobExchangeRateDefault()
		{
			if (InvoicingBase.IsUseJobExchangeRateApplicable_ForTestOnly)
			{
				AssertEquals("Precondition, local currency AUD", TestObjectCreator.AUD.RX_Code, Env.CurrentCompany.LocalCurrency.Code);
				AccountingConfigurationRegistry.Instance.UseJobExchangeRateDefault.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, true);
				var invoice = (InvoicingBase)base.GetNewBusinessObject();
				AssertEquals("Precondition, invoice should default to local currency", TestObjectCreator.AUD.RX_Code, invoice.AH_RX_NKTransactionCurrency);
				AssertEquals("Local currency, so not checked", false, invoice.UseJobExchangeRate);
				invoice.AH_RX_NKTransactionCurrency = TestObjectCreator.USD.RX_Code;
				AssertEquals("Local to foreign currency, with registry set, so now checked", true, invoice.UseJobExchangeRate);
				invoice.AH_RX_NKTransactionCurrency = TestObjectCreator.GBP.RX_Code;
				AssertEquals("Foreign to foreign currency, so remains checked", true, invoice.UseJobExchangeRate);
				invoice.UseJobExchangeRate = false;
				invoice.AH_RX_NKTransactionCurrency = TestObjectCreator.USD.RX_Code;
				AssertEquals("Foreign to foreign currency, so remains unchecked", false, invoice.UseJobExchangeRate);
				AssertEquals(false, invoice.UseJobExchangeRate);
				invoice.UseJobExchangeRate = true;
				invoice.AH_RX_NKTransactionCurrency = TestObjectCreator.AUD.RX_Code;
				AssertEquals("Foreign to local currency, so is unchecked", false, invoice.UseJobExchangeRate);

				AssertEquals("Precondition, local currency AUD", TestObjectCreator.AUD.RX_Code, Env.CurrentCompany.LocalCurrency.Code);
				AccountingConfigurationRegistry.Instance.UseJobExchangeRateDefault.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, false);
				invoice = (InvoicingBase)base.GetNewBusinessObject();
				AssertEquals("Precondition, invoice should default to local currency", TestObjectCreator.AUD.RX_Code, invoice.AH_RX_NKTransactionCurrency);
				AssertEquals("Local currency, so not checked", false, invoice.UseJobExchangeRate);
				invoice.AH_RX_NKTransactionCurrency = TestObjectCreator.USD.RX_Code;
				AssertEquals("Local to foreign currency, with registry not set, so not checked", false, invoice.UseJobExchangeRate);
				invoice.AH_RX_NKTransactionCurrency = TestObjectCreator.GBP.RX_Code;
				AssertEquals("Foreign to foreign currency, so remains unchecked", false, invoice.UseJobExchangeRate);
				invoice.AH_RX_NKTransactionCurrency = TestObjectCreator.AUD.RX_Code;
				AssertEquals("Foreign to local currency, so is unchecked", false, invoice.UseJobExchangeRate);
			}
			else
			{
				Assert(true);
			}
		}

		public void TestUseJobExchangeRate()
		{
			var postingExRateRegistry = PostingExRateRegistryAP;
			var consolExchangeRate1 = 1.5m;
			var consolExchangeRate2 = 1.2m;
			var avgExchangeRate = 1.312484m;
			var shipmentExchangeRate = 1.3m;
			var newInvoiceExchangeRate = 2.0m;
			var todRate = 2.6m;
			var invoiceDate = ZDateTime.Today;

			var consol = TestObjectCreator.CreateConsol();
			var forwardingShipment = TestObjectCreator.CreateShipment("S00002000", consol);
			var shipmentJob = TestObjectCreator.CreateJob(forwardingShipment, false);
			TestObjectCreator.SetExchangeRate(shipmentJob, TestObjectCreator.USD, shipmentExchangeRate);

			var consolCost1 = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC1, TestObjectCreator.USD, consolExchangeRate1, 150m, TestObjectCreator.AALSHI);
			var consolCost2 = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC2, TestObjectCreator.USD, consolExchangeRate2, 200m, TestObjectCreator.AALSHI);

			Factory.Save();

			var invoice = TestObjectCreator.CreateInvoice(typeof(APInvoice), invoiceDate: invoiceDate);
			var originatingCost = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			var newFactory = new BusinessObjectFactory();
			var importer = new InvoicingBaseConsolCostImporter(newFactory, originatingCost, invoice);

			importer.ImportCostsIntoCosting(new BusinessObject[] { consolCost1, consolCost2 });
			AssertEquals(2, invoice.ConsolCosting.ConsolCosts.Count);
			AssertEquals(consolExchangeRate1, invoice.ConsolCosting.ConsolCosts[0].E6_ExchangeRate);
			AssertEquals(consolExchangeRate2, invoice.ConsolCosting.ConsolCosts[1].E6_ExchangeRate);

			invoice.ImportAllApportionmentsFromCosting();
			AssertNotNull(invoice.Lines[0].TransactionJob);
			AssertNotNull(invoice.Lines[1].TransactionJob);
			Assert(invoice.Lines[0].IsPopulatedFromImportedApportionment);
			Assert(invoice.Lines[1].IsPopulatedFromImportedApportionment);

			Assert(!invoice.UseJobExchangeRate);

			AssertEquals("Precondition: Initial Header Exchange Rate", consolExchangeRate1, invoice.Lines[0].ExchangeRate.Rate);
			AssertEquals("Precondition: Initial Header Exchange Rate", consolExchangeRate2, invoice.Lines[1].ExchangeRate.Rate);

			invoice.AH_ExchangeRate = newInvoiceExchangeRate;
			AssertEquals("Precondition: Set Header Exchange Rate", newInvoiceExchangeRate, invoice.Lines[0].ExchangeRate.Rate);
			AssertEquals("Precondition: Set Header Exchange Rate", newInvoiceExchangeRate, invoice.Lines[1].ExchangeRate.Rate);

			AccountingConfigurationRegistry.Instance.UseJobExchangeRateDefault.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, true);
			invoice.ExchangeRate.Currency = TestObjectCreator.USD.RX_Code;
			Assert(invoice.UseJobExchangeRate);

			AssertEquals("Precondition: Job Header Exchange Rate", consolExchangeRate1, invoice.Lines[0].ExchangeRate.Rate);
			AssertEquals("Precondition: Job Header Exchange Rate", consolExchangeRate2, invoice.Lines[1].ExchangeRate.Rate);

			Untick();

			Tick();
			Untick();

			Tick();
			UntickWithConditions(isReverseTransaction: true);

			ResetConditions();

			Tick();
			UntickWithConditions(isSettingAH_ExchangeRate: true);

			ResetConditions();

			Tick();
			UntickWithConditions(isSetContext: true);

			ResetConditions();

			Tick();
			UntickWithConditions(isSetExchangeRateSuspender: true);

			ResetConditions();
			ExchangeRateReader.GetReaderInstance().ClearCache();
			AccountingConfigurationRegistry.Instance.UseJobExchangeRateDefault.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, false);

			TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, "BUY", todRate);
			postingExRateRegistry.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, "TOD");

			Assert(ExchangeRateCalculator.IsExRateOptionApplicable(invoice.GetExRateLedger(), invoice.IsLocalCurrencyTransaction, invoice.AH_GC));

			Tick();

			var header = Factory.Load<AccTransactionHeader>(invoice.PK);
			header.AH_ExchangeRate = todRate;
			AssertNotEquals("Precondition: Line 1 exchangeRate should not be updated", todRate, invoice.Lines[0].ExchangeRate.Rate);
			AssertNotEquals("Precondition: Line 2 exchangeRate should not be updated", todRate, invoice.Lines[1].ExchangeRate.Rate);

			invoice.UseJobExchangeRate = false;
			AssertEquals("Line 1 exchangeRate should be updated", todRate, invoice.Lines[0].ExchangeRate.Rate);
			AssertEquals("Line 2 exchangeRate should be updated", todRate, invoice.Lines[1].ExchangeRate.Rate);

			void Tick()
			{
				invoice.UseJobExchangeRate = true;
				AssertEquals("Precondition: Job Header Exchange Rate", consolExchangeRate1, invoice.Lines[0].ExchangeRate.Rate);
				AssertEquals("Precondition: Job Header Exchange Rate", consolExchangeRate2, invoice.Lines[1].ExchangeRate.Rate);
			}

			void Untick()
			{
				invoice.UseJobExchangeRate = false;
				AssertEquals("Line1 new Exchange Rate", avgExchangeRate, invoice.Lines[0].ExchangeRate.Rate);
				AssertEquals("Line2 new Exchange Rate", avgExchangeRate, invoice.Lines[1].ExchangeRate.Rate);
			}

			void UntickWithConditions(bool isReverseTransaction = false, bool isSettingAH_ExchangeRate = false, bool isSetContext = false, bool isSetExchangeRateSuspender = false)
			{
				invoice.IsReverseTransaction = isReverseTransaction;
				invoice.IsSettingAH_ExchangeRate_ForTestOnly = isSettingAH_ExchangeRate;
				if (isSetContext)
				{
					Factory.SetContext(BusinessContext.IncompleteInvoiceDataAdapter);
				}
				if (isSetExchangeRateSuspender)
				{
					using (invoice.SetExchangeRateSuspender.GetSuspender())
					{
						invoice.UseJobExchangeRate = false;
					}
				}
				else
				{
					invoice.UseJobExchangeRate = false;
				}
				AssertNotEquals("Line1 Exchange Rate not updated", avgExchangeRate, invoice.Lines[0].ExchangeRate.Rate);
				AssertNotEquals("Line2 Exchange Rate not updated", avgExchangeRate, invoice.Lines[1].ExchangeRate.Rate);
			}

			void ResetConditions(bool isReverseTransaction = false, bool isSettingAH_ExchangeRate = false, bool isSetContext = false)
			{
				invoice.IsReverseTransaction = isReverseTransaction;
				invoice.IsSettingAH_ExchangeRate_ForTestOnly = isSettingAH_ExchangeRate;
				if (!isSetContext)
				{
					Factory.RemoveContext(BusinessContext.IncompleteInvoiceDataAdapter);
				}
			}
		}

		public void TestExchangeRateForJobChargeLine()
		{
			//Setup
			var shipmentExchangeRate = 0.830128m;
			var todRate = 3.1m;
			var localCurrencyExchangeRate = 1m;

			var forwardingShipment = TestObjectCreator.CreateShipment("S00004000");
			var shipmentJob = TestObjectCreator.CreateJob(forwardingShipment, false);
			var chargeCode = TestObjectCreator.CC1;
			TestObjectCreator.SetExchangeRate(shipmentJob, TestObjectCreator.USD, shipmentExchangeRate);
			var importJobCharge = TestObjectCreator.CreateCharge(shipmentJob, chargeCode, "charge1", TestObjectCreator.USD, 82M, null, null, 0M, null);
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, "BUY", todRate);
			AccountingConfigurationRegistry.Instance.UseJobExchangeRateDefault.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, true);

			Factory.Save();

			var invoice = TestObjectCreator.CreateInvoice(typeof(APInvoice));
			var jobCharges = new List<Charge>();
			jobCharges.Add(importJobCharge);

			var lineFromImportShipment = (InvoicingLineBase)invoice.Lines.AddNew();
			invoice.ImportJobChargesIntoInvoice(jobCharges, lineFromImportShipment);
			lineFromImportShipment.AL_JH = shipmentJob.PK;

			AssertEquals("Precondition: AUD", "AUD", invoice.ExchangeRate.Currency);
			Assert("Precondition: Use Job Exchange Rate", !invoice.UseJobExchangeRate);
			AssertEquals("Precondition: local Exchange Rate", localCurrencyExchangeRate, invoice.ExchangeRate.Rate);
			AssertEquals("Precondition: Today's Rate", todRate, invoice.Lines[0].ExchangeRate.Rate);

			//Execution - Set Currency to USD
			invoice.ExchangeRate.Currency = TestObjectCreator.USD.RX_Code;

			AssertNotNull(invoice.Lines[0].TransactionJob);
			Assert(!invoice.Lines[0].IsPopulatedFromImportedApportionment);
			Assert(invoice.UseJobExchangeRate);

			//Assert
			var invoiceExchangeRate = invoice.ExchangeRate.Rate;
			var lineExchangeRate = invoice.Lines[0].ExchangeRate.Rate;

			AssertNotEquals(localCurrencyExchangeRate, invoiceExchangeRate);
			AssertNotEquals(todRate, invoiceExchangeRate);
			AssertNotEquals(todRate, lineExchangeRate);
			AssertEquals(shipmentExchangeRate, invoiceExchangeRate);
			AssertEquals(shipmentExchangeRate, lineExchangeRate);
		}

		public void TestExchangeRateForLinePopulatedFromImportedApportionment()
		{
			//Setup
			var consolExchangeRate1 = 1.8m;
			var consolExchangeRate2 = 1.9m;
			var shipmentExchangeRate = 0.4m;
			var todRate = 0.7m;
			var localCurrencyExchangeRate = 1m;

			var consol = TestObjectCreator.CreateConsol();
			var forwardingShipment = TestObjectCreator.CreateShipment("S00008000", consol);
			var shipmentJob = TestObjectCreator.CreateJob(forwardingShipment, false);
			var consolCost1 = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC1, TestObjectCreator.USD, consolExchangeRate1, 250m, TestObjectCreator.AALSHI);
			TestObjectCreator.SetExchangeRate(shipmentJob, TestObjectCreator.USD, shipmentExchangeRate);
			var consolCost2 = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC2, TestObjectCreator.USD, consolExchangeRate2, 300m, TestObjectCreator.AALSHI);
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, "BUY", todRate);

			Factory.Save();

			//Setup - invoice with UseJobExchangeRateDefault disabled
			var invoice1 = TestObjectCreator.CreateInvoice(typeof(APInvoice));
			var originatingCost1 = invoice1.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			var importer1 = new InvoicingBaseConsolCostImporter(new BusinessObjectFactory(), originatingCost1, invoice1);
			importer1.ImportCostsIntoCosting(new BusinessObject[] { consolCost1, consolCost2 });
			AssertEquals(2, invoice1.ConsolCosting.ConsolCosts.Count);
			invoice1.ImportAllApportionmentsFromCosting();

			AssertEquals("Precondition: AUD", "AUD", invoice1.ExchangeRate.Currency);
			Assert("Precondition: Use Job Exchange Rate disabled", !invoice1.UseJobExchangeRate);
			AssertEquals("Precondition: Local Currency Exchange Rate", localCurrencyExchangeRate, invoice1.ExchangeRate.Rate);
			AssertEquals("Precondition: Job Exchange Rate", consolExchangeRate1, invoice1.Lines[0].ExchangeRate.Rate);
			AssertEquals("Precondition: Job Exchange Rate", consolExchangeRate2, invoice1.Lines[1].ExchangeRate.Rate);

			//Execution - Set Currency to USD
			invoice1.ExchangeRate.Currency = TestObjectCreator.USD.RX_Code;
			Assert(!invoice1.UseJobExchangeRate);

			//Assert
			var invoiceExchangeRate = invoice1.ExchangeRate.Rate;
			var exchangeRateLine1 = invoice1.Lines[0].ExchangeRate.Rate;
			var exchangeRateLine2 = invoice1.Lines[1].ExchangeRate.Rate;

			AssertEquals(todRate, invoiceExchangeRate);
			AssertEquals(todRate, exchangeRateLine1);
			AssertEquals(todRate, exchangeRateLine2);

			//Enable UseJobExchangeRateDefault
			AccountingConfigurationRegistry.Instance.UseJobExchangeRateDefault.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, true);

			//Setup - new invoice with UseJobExchangeRateDefault enabled
			var invoice2 = TestObjectCreator.CreateInvoice(typeof(APInvoice));
			var originatingCost2 = invoice2.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			var importer2 = new InvoicingBaseConsolCostImporter(new BusinessObjectFactory(), originatingCost2, invoice2);
			importer2.ImportCostsIntoCosting(new BusinessObject[] { consolCost1, consolCost2 });
			AssertEquals(2, invoice2.ConsolCosting.ConsolCosts.Count);
			invoice2.ImportAllApportionmentsFromCosting();

			AssertEquals("Precondition: AUD", "AUD", invoice2.ExchangeRate.Currency);
			Assert("Precondition: Use Job Exchange Rate disabled", !invoice2.UseJobExchangeRate);
			AssertEquals("Precondition: Local Currency Exchange Rate", localCurrencyExchangeRate, invoice2.ExchangeRate.Rate);
			AssertEquals("Precondition: Job Exchange Rate", consolExchangeRate1, invoice2.Lines[0].ExchangeRate.Rate);
			AssertEquals("Precondition: Job Exchange Rate", consolExchangeRate2, invoice2.Lines[1].ExchangeRate.Rate);

			//Execution - Set Currency to USD
			invoice2.ExchangeRate.Currency = TestObjectCreator.USD.RX_Code;
			Assert(invoice2.UseJobExchangeRate);

			//Assert
			invoiceExchangeRate = invoice2.ExchangeRate.Rate;
			exchangeRateLine1 = invoice2.Lines[0].ExchangeRate.Rate;
			exchangeRateLine2 = invoice2.Lines[1].ExchangeRate.Rate;

			AssertNotEquals(todRate, invoiceExchangeRate);
			AssertNotEquals(todRate, exchangeRateLine1);
			AssertNotEquals(todRate, exchangeRateLine2);
			AssertEquals(consolExchangeRate1, exchangeRateLine1);
			AssertEquals(consolExchangeRate2, exchangeRateLine2);
		}

