		[TestDate(2020, 2, 2)]
		[DisableZeroExchangeRateOverriding]
		public void TestExchangeRateDefaultingUsesExchangeRateConfiguration_Job_TodayOption() => AssertExchangeRateDefaultingUsesExchangeRateConfiguration(AccountingConstants.InvoicePostingExchangeRateOption.TodayExchangeRate.Code);

		void AssertExchangeRateDefaultingUsesExchangeRateConfiguration(ZString exRateOption)
		{
			var postingExRateRegistry = PostingExRateRegistry;
			var isOverrideDefault = exRateOption == AccountingConstants.InvoicePostingExchangeRateOption.Default.Code;
			var overrideDateIsToday = isOverrideDefault || exRateOption == AccountingConstants.InvoicePostingExchangeRateOption.TodayExchangeRate.Code;

			var nonConfigTodayRate = 5m;
			var nonConfigOverrideRate = 6m;
			var configTodayRate = 15m;
			var configOverrideRate = 16m;

			var expectedConfigRate = overrideDateIsToday ? configTodayRate : configOverrideRate;
			var expectedNonConfigRate = overrideDateIsToday ? nonConfigTodayRate : nonConfigOverrideRate;

			TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, ExchangeRateTypes.Code.BuyRate, nonConfigTodayRate, ZDateTime.Today, ZDateTime.Today);
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, ExchangeRateTypes.Code.BuyRate, nonConfigOverrideRate, ZDateTime.Today.AddDays(1), ZDateTime.Today.AddDays(1));
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, ExchangeRateTypes.Code.SellRate, nonConfigTodayRate, ZDateTime.Today, ZDateTime.Today);
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, ExchangeRateTypes.Code.SellRate, nonConfigOverrideRate, ZDateTime.Today.AddDays(1), ZDateTime.Today.AddDays(1));
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, ExchangeRateTypes.Code.C01Rate, configTodayRate, ZDateTime.Today, ZDateTime.Today);
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, ExchangeRateTypes.Code.C01Rate, configOverrideRate, ZDateTime.Today.AddDays(1), ZDateTime.Today.AddDays(1));
			ExchangeRateReader.GetReaderInstance().ClearCache();

			GlbCompany.CurrentCompany.AccExchangeRateConfigurations.SetExRate(JobInvoicingConsumerTypes.ShipmentCode, "ALL", "ALL", ExchangeRateTypes.Code.C01Rate);
			GlbCompany.CurrentCompany.AccExchangeRateConfigurations.SetExRate(AccountingMasterFilesConstants.JobTypes.NonJobRelated, "ALL", "ALL", ExchangeRateTypes.Code.C01Rate);
			GlbCompany.CurrentCompany.Factory.Save();

			postingExRateRegistry.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, exRateOption);
			AccountingConfigurationRegistry.Instance.UseJobExchangeRateDefault.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, false);

			var invoice = GetNewBusinessObject() as InvoicingBase;
			var invoiceWithLine = GetNewBusinessObject() as InvoicingBase;
			var jobInvoice = GetNewBusinessObject() as InvoicingBase;
			var jobInvoiceWithLine = GetNewBusinessObject() as InvoicingBase;
			var invoices = new[] { invoice, invoiceWithLine, jobInvoice, jobInvoiceWithLine };
			SetValuesOnInvoices();

			var shouldTestLines = invoice.Lines.AllowNew;
			var isLedgerAR = invoice.Ledger_ForTestOnly == LedgerTypes.AccountsReceivable;
			var shouldTestUseJobExchangeRate = invoice.IsUseJobExchangeRateApplicable_ForTestOnly;

			InvoicingLineBase line = null;
			InvoicingLineBase jobLine = null;

			var shipment = TestObjectCreator.CreateShipment("S001");
			var job = TestObjectCreator.CreateJob(shipment, false);
			jobInvoice.AH_JH = job.PK;
			jobInvoiceWithLine.AH_JH = job.PK;

			if (shouldTestLines)
			{
				line = invoiceWithLine.Lines.AddNew() as InvoicingLineBase;
				line.AL_OSExTaxAmount = 100;
				jobLine = jobLine = jobInvoiceWithLine.Lines.AddNew() as InvoicingLineBase;
				jobLine.AL_OSExTaxAmount = 100;
				jobLine.AL_JH = job.PK;
			}

			var expectedNonJobRate = isLedgerAR ? expectedConfigRate : expectedNonConfigRate;

			invoices.ForEach(x => x.ExchangeRate.Currency = TestObjectCreator.USD.Code);
			Assert("Expect UseJobExchangeRate should be false", invoices.All(x => !x.UseJobExchangeRate));
			AssertEquals("When UseJobExchangeRate is false, non job transactions should use config if AR", expectedNonJobRate, invoice.AH_ExchangeRate);

			if (isLedgerAR)
			{
				AssertEquals("When AR, UseJobExchangeRate is irrelevant because transaction lines belong to same job, as opposed to multiple when AP - should use config", expectedConfigRate, jobInvoice.AH_ExchangeRate);

				if (shouldTestLines)
				{
					AssertEquals("When UseJobExchangeRate is false, non job transactions should use config if AR", expectedNonJobRate, invoiceWithLine.AH_ExchangeRate);
					AssertEquals("When UseJobExchangeRate is false, non job transactions should use config if AR", expectedNonJobRate, line.AL_ExchangeRate);
					AssertEquals("When UseJobExchangeRate is false, job transactions should use config", expectedConfigRate, jobInvoiceWithLine.AH_ExchangeRate);
					AssertEquals("When UseJobExchangeRate is false, job transactions should use config", expectedConfigRate, jobLine.AL_ExchangeRate);
				}
			}
			else
			{
				AssertEquals("When UseJobExchangeRate is false, job transactions should not use config", expectedNonConfigRate, jobInvoice.AH_ExchangeRate);

				if (shouldTestLines)
				{
					AssertEquals("When UseJobExchangeRate is false, non job transactions should use config if AR", expectedNonJobRate, invoiceWithLine.AH_ExchangeRate);
					AssertEquals("When UseJobExchangeRate is false, non job transactions should use config if AR", expectedNonJobRate, line.AL_ExchangeRate);
					AssertEquals("When UseJobExchangeRate is false, job transactions should not use config", expectedNonConfigRate, jobInvoiceWithLine.AH_ExchangeRate);
					AssertEquals("When UseJobExchangeRate is false, job transactions should not use config", expectedNonConfigRate, jobLine.AL_ExchangeRate);
				}
			}

			if (shouldTestUseJobExchangeRate)
			{
				invoices.ForEach(x => x.UseJobExchangeRate = true);
				AssertEquals("After setting UseJobExchangeRate to true, Amounts and exchange rate are calculated from lines", 1m, invoice.AH_ExchangeRate);
				AssertEquals("After setting UseJobExchangeRate to true, Amounts and exchange rate are calculated from lines", 1m, jobInvoice.AH_ExchangeRate);
				if (shouldTestLines)
				{
					AssertEquals("After setting UseJobExchangeRate to true, Amounts and exchange rate are calculated from lines", expectedConfigRate, invoiceWithLine.AH_ExchangeRate.Round(0));
					AssertEquals("After setting UseJobExchangeRate to true, Amounts and exchange rate are calculated from lines", expectedConfigRate, line.AL_ExchangeRate.Round(0));
					AssertEquals("After setting UseJobExchangeRate to true, Amounts and exchange rate are calculated from lines", expectedConfigRate, jobInvoiceWithLine.AH_ExchangeRate.Round(0));
					AssertEquals("After setting UseJobExchangeRate to true, Amounts and exchange rate are calculated from lines", expectedConfigRate, jobLine.AL_ExchangeRate.Round(0));
				}
			}

			invoices.ForEach(x => x.ExchangeRate.Currency = TestObjectCreator.AUD.Code);
			if (shouldTestUseJobExchangeRate)
			{
				Assert("UseJobExchangeRate should be set to false if currency is set to local", invoices.All(x => !x.UseJobExchangeRate));
			}
			AssertEquals("Exchange rate set to 1 when currency is local", 1m, invoice.AH_ExchangeRate);
			AssertEquals("Exchange rate set to 1 when currency is local", 1m, jobInvoice.AH_ExchangeRate);
			if (shouldTestLines)
			{
				AssertEquals("Exchange rate set to 1 when currency is local", 1m, invoiceWithLine.AH_ExchangeRate);
				AssertEquals("Exchange rate set to 1 when currency is local", 1m, line.AL_ExchangeRate);
				AssertEquals("Exchange rate set to 1 when currency is local", 1m, jobInvoiceWithLine.AH_ExchangeRate);
				AssertEquals("Exchange rate set to 1 when currency is local", 1m, jobLine.AL_ExchangeRate);
			}

			if (shouldTestUseJobExchangeRate)
			{
				AccountingConfigurationRegistry.Instance.UseJobExchangeRateDefault.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, true);

				invoices.ForEach(x => x.ExchangeRate.Currency = TestObjectCreator.USD.Code);
				Assert("When setting currency from local to foreign, UseJobExchangeRate is set based on registry default", invoices.All(x => x.UseJobExchangeRate));

				// below two lines are a defect, ideal functionality would be to set to config rate as it would on a line
				AssertEquals("When UseJobExchangeRate is true, Lines should use Config rate, then recalculate header with line values", nonConfigTodayRate, invoice.AH_ExchangeRate);
				AssertEquals("When UseJobExchangeRate is true, Lines should use Config rate, then recalculate header with line values", nonConfigTodayRate, jobInvoice.AH_ExchangeRate);
				//
				if (shouldTestLines)
				{
					AssertEquals("When UseJobExchangeRate is true, Lines should use Config rate, then recalculate header with line values", expectedConfigRate, invoiceWithLine.AH_ExchangeRate.Round(0));
					AssertEquals("When UseJobExchangeRate is true, Lines should use Config rate, then recalculate header with line values", expectedConfigRate, line.AL_ExchangeRate.Round(0));
					AssertEquals("When UseJobExchangeRate is true, Lines should use Config rate, then recalculate header with line values", expectedConfigRate, jobInvoiceWithLine.AH_ExchangeRate.Round(0));
					AssertEquals("When UseJobExchangeRate is true, Lines should use Config rate, then recalculate header with line values", expectedConfigRate, jobLine.AL_ExchangeRate.Round(0));
				}
			}

			void SetValuesOnInvoices()
			{
				foreach (var invoiceToSet in invoices)
				{
					invoiceToSet.AH_OH = TestObjectCreator.ABIGAS.PK;
					var overrideDate = overrideDateIsToday ? ZDateTime.Today : ZDateTime.Today.AddDays(1);
					invoiceToSet.AH_PostDate = overrideDate;
					invoiceToSet.AH_InvoiceDate = overrideDate;
				}
			}
		}

		[DisableZeroExchangeRateOverriding]
		public void TestGetExchangeRateFromJob()
		{
			var postingExRateRegistry = PostingExRateRegistryAP;
			var jobExchangeRate = 2m;
			var rate = 3m;
			var todayRate = 3.5m;
			var otherCurrencyRate = 2.7m;
			var otherCurrencyTodayRate = 2.3m;
			var creditor = TestObjectCreator.ABIGAS;
			var chargeCode = TestObjectCreator.CC1;
			var osCurrency = TestObjectCreator.USD;
			var otherCurrency = TestObjectCreator.EUR;

			TestObjectCreator.CreateExchangeRate(osCurrency, ExchangeRateTypes.Code.SellRate, todayRate);
			TestObjectCreator.CreateExchangeRate(osCurrency, ExchangeRateTypes.Code.SellRate, rate, ZDateTime.Today.AddDays(-3), ZDateTime.Today.AddDays(-2));
			TestObjectCreator.CreateExchangeRate(otherCurrency, ExchangeRateTypes.Code.SellRate, otherCurrencyTodayRate);
			TestObjectCreator.CreateExchangeRate(otherCurrency, ExchangeRateTypes.Code.SellRate, otherCurrencyRate, ZDateTime.Today.AddDays(-3), ZDateTime.Today.AddDays(-2));

			var shipment = TestObjectCreator.CreateShipment("S00001100");
			var job = TestObjectCreator.CreateJob(shipment, false);
			TestObjectCreator.SetExchangeRate(job, osCurrency, jobExchangeRate);

			creditor.CompanyData.AccARExchangeRateConfigurations.SetExRate(ledgerCode: LedgerTypes.AccountsPayable, jobType: "SHP", transportMode: "ALL", serviceDirection: "ALL", exRateType: Constants.ExchangeRateTypes.Code.SellRate);

			Factory.Save();

			var invoice = TestObjectCreator.CreateInvoice(typeof(APInvoice));
			invoice.AH_OH = creditor.PK;
			invoice.AH_InvoiceDate = ZDateTime.Today.AddDays(-2);
			invoice.AH_RX_NKTransactionCurrency = osCurrency.Code;
			var line = TestObjectCreator.CreateInvoiceLine(invoice, 100m, osCurrency);
			line.AL_JH = job.PK;
			Assert(!invoice.UseJobExchangeRate);

			AssertEquals("Expect today Ex Rate", todayRate, invoice.GetExchangeRateFromJobExRateConfig(job));

			invoice.UseJobExchangeRate = true;

			AssertEquals("Expect Job Ex Rate", jobExchangeRate, invoice.GetExchangeRateFromJobExRateConfig(job));

			using (postingExRateRegistry.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, AccountingConstants.InvoicePostingExchangeRateOption.ExchangeRateBasedOnInvoiceDate.Code))
			{
				AssertEquals("Expect ex Rate from debtor configuration", rate, invoice.GetExchangeRateFromJobExRateConfig(job));
			}

			invoice.AH_RX_NKTransactionCurrency = otherCurrency.Code;

			AssertEquals("Expect other Currency today Ex Rate", otherCurrencyTodayRate, invoice.GetExchangeRateFromJobExRateConfig(job));

			using (postingExRateRegistry.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, AccountingConstants.InvoicePostingExchangeRateOption.ExchangeRateBasedOnInvoiceDate.Code))
			{
				AssertEquals("Expect ex Rate from debtor configuration", otherCurrencyRate, invoice.GetExchangeRateFromJobExRateConfig(job));
			}

			invoice.AH_RX_NKTransactionCurrency = "RUR";
			invoice.UseJobExchangeRate = false;
			invoice.AH_ExchangeRate = 0.99m;

			AssertEquals("Expect Invoice Ex Rate when there is no source for Ex Rate", invoice.AH_ExchangeRate, invoice.GetExchangeRateFromJobExRateConfig(job));
		}

		public void TestChangeCurrencyWithUseJobExchangeRateAndConsolCosts()
		{
			var consolExchangeRate1 = 1.2m;
			var consolExchangeRate2 = 1.8m;
			var todRate1 = 1.6m;
			var todRate2 = 3.1m;
			var localCurrencyExchangeRate = 1m;
			var invoiceDate = ZDateTime.Today;

			var consol = TestObjectCreator.CreateConsol();
			var forwardingShipment = TestObjectCreator.CreateShipment("S00002000", consol);
			var shipmentJob = TestObjectCreator.CreateJob(forwardingShipment, false);
			TestObjectCreator.SetExchangeRate(shipmentJob, TestObjectCreator.USD, 1.3m);
			TestObjectCreator.SetExchangeRate(shipmentJob, TestObjectCreator.GBP, 1.9m);
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, "BUY", todRate1);
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.GBP, "BUY", todRate2);

			var consolCost1 = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC1, TestObjectCreator.USD, consolExchangeRate1, 150m, TestObjectCreator.AALSHI);
			var consolCost2 = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC2, TestObjectCreator.GBP, consolExchangeRate2, 200m, TestObjectCreator.AALSHI);
			AccountingConfigurationRegistry.Instance.UseJobExchangeRateDefault.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, true);

			Factory.Save();

			var invoice = TestObjectCreator.CreateInvoice(typeof(APInvoice), invoiceDate: invoiceDate);
			var originatingCost = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			var newFactory = new BusinessObjectFactory();
			var importer = new InvoicingBaseConsolCostImporter(newFactory, originatingCost, invoice);

			importer.ImportCostsIntoCosting(new BusinessObject[] { consolCost1, consolCost2 });
			AssertEquals(2, invoice.ConsolCosting.ConsolCosts.Count);
			AssertEquals(consolExchangeRate1, invoice.ConsolCosting.ConsolCosts[0].E6_ExchangeRate);
			AssertEquals(consolExchangeRate2, invoice.ConsolCosting.ConsolCosts[1].E6_ExchangeRate);

			invoice.ImportAllApportionmentsFromCosting();
			AssertNotNull(invoice.Lines[0].TransactionJob);
			AssertNotNull(invoice.Lines[1].TransactionJob);
			Assert(invoice.Lines[0].IsPopulatedFromImportedApportionment);
			Assert(invoice.Lines[1].IsPopulatedFromImportedApportionment);

			AssertEquals("Precondition: Currency", "AUD", invoice.ExchangeRate.Currency);
			AssertEquals("Precondition: Local Currency Exchange Rate", localCurrencyExchangeRate, invoice.ExchangeRate.Rate);

			Assert("Precondition: Initial use Job ExchangeRate check box", !invoice.UseJobExchangeRate);
			AssertEquals("Precondition: Initial Job Exchange Rate", consolExchangeRate1, invoice.Lines[0].ExchangeRate.Rate);
			AssertEquals("Precondition: Initial Job Exchange Rate", consolExchangeRate2, invoice.Lines[1].ExchangeRate.Rate);

			UpdateCurrency(TestObjectCreator.USD.RX_Code, consolExchangeRate1, todRate1);
			UpdateCurrency(TestObjectCreator.GBP.RX_Code, todRate2, consolExchangeRate2);

			void UpdateCurrency(ZString currency, ZDecimal firstLineExpectation, ZDecimal secondLineExpectation)
			{
				invoice.ExchangeRate.Currency = currency;
				AssertEquals("Currency updated", currency, invoice.ExchangeRate.Currency);
				Assert("ExchangeRate check box changed", invoice.UseJobExchangeRate);

				AssertEquals("Line1 new Exchange Rate", firstLineExpectation, invoice.Lines[0].ExchangeRate.Rate);
				AssertEquals("Line2 new Exchange Rate", secondLineExpectation, invoice.Lines[1].ExchangeRate.Rate);
			}
		}

