		public void TestRecreationLinesUseJobExchangeRateTicked()
		{
			var consol = TestObjectCreator.CreateConsol();
			var forwardingShipment = TestObjectCreator.CreateShipment("S00003000", consol);
			var shipmentJob = TestObjectCreator.CreateJob(forwardingShipment, false);
			TestObjectCreator.SetExchangeRate(shipmentJob, TestObjectCreator.USD, 1.3m);
			var consolCost1 = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC1, TestObjectCreator.USD, 1.5m, 150m, TestObjectCreator.AALSHI);
			var consolCost2 = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC2, TestObjectCreator.USD, 1.2m, 200m, TestObjectCreator.AALSHI);
			Factory.Save();

			var invoice = TestObjectCreator.CreateInvoice(typeof(APInvoice));
			var originatingCost = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			var newFactory = new BusinessObjectFactory();
			var importer = new InvoicingBaseConsolCostImporter(newFactory, originatingCost, invoice);

			importer.ImportCostsIntoCosting(new BusinessObject[] { consolCost1, consolCost2 });
			AssertEquals(2, invoice.ConsolCosting.ConsolCosts.Count);

			invoice.ImportAllApportionmentsFromCosting();
			Assert(!invoice.UseJobExchangeRate);

			invoice.AH_ExchangeRate = 1.2m;

			var previousLinePK1 = invoice.Lines[0].PK;
			var previousLinePK2 = invoice.Lines[1].PK;

			invoice.UseJobExchangeRate = true;

			var currentLinePK1 = invoice.Lines[0].PK;
			var currentLinePK2 = invoice.Lines[1].PK;

			AssertNotEquals(previousLinePK1, currentLinePK1);
			AssertNotEquals(previousLinePK2, currentLinePK2);

			invoice.UseJobExchangeRate = false;
			consolCost2.E6_ExchangeRate = 1.5m;
			invoice.AH_ExchangeRate = 1.5m;

			previousLinePK1 = invoice.Lines[0].PK;
			previousLinePK2 = invoice.Lines[1].PK;

			invoice.UseJobExchangeRate = true;

			currentLinePK1 = invoice.Lines[0].PK;
			currentLinePK2 = invoice.Lines[1].PK;

			AssertEquals(previousLinePK1, currentLinePK1);
			AssertEquals(previousLinePK2, currentLinePK2);
		}

