		public void TestIncompleteInvoiceClearsStmdata()
		{
			if (GetExpectedBusinessObjectType() == typeof(APInvoice))
			{
				var incompleteInvoice = TestObjectCreator.CreateInvoiceWithLine(typeof(APInvoice), "00001", TestObjectCreator.AUD, 1, 100, 10, 100, 10);
				incompleteInvoice.AH_OH = TestObjectCreator.Creditor1.PK;

				incompleteInvoice.SaveAsIncomplete();

				var newFactory = new BusinessObjectFactory();
				var apInvoice = newFactory.Load<APInvoice>(incompleteInvoice.PK);
				apInvoice.RestoreSavedData();
				apInvoice.MoveFromIncompleteToPayableLedger();

				Assert(" Precondition: Invoice must be completing ", apInvoice.IsCompletingInvoice);
				AssertEquals(" Precondition: Must have a line ", 1, apInvoice.Lines.Count);
				AssertNotNull(" Precondition: Stmnote should be found ", apInvoice.GetDetailsNoteIfItExists_ForTestOnly(new BusinessObjectFactory()));

				var originalBranchPK = apInvoice.AH_GB;
				apInvoice.AH_GB = ZGuid.NewZGuid();
				try
				{
					newFactory.Save();
					Fail("Exception must be thrown on saving");
				}
				catch { }
				AssertNotNull(" On failed save Stmnote should NOT be deleted ", apInvoice.GetDetailsNoteIfItExists_ForTestOnly(new BusinessObjectFactory()));

				apInvoice.AH_GB = originalBranchPK;
				apInvoice.SaveAsIncomplete();
				apInvoice.AH_Desc = "force haschanges"; //for test only. in real life it is unreal situation
				newFactory.Save();

				AssertNotNull(" After failed saving again again keeps the note ", apInvoice.GetDetailsNoteIfItExists_ForTestOnly(new BusinessObjectFactory()));

				apInvoice.RestoreSavedData();
				apInvoice.MoveFromIncompleteToPayableLedger();
				newFactory.Save();

				newFactory = new BusinessObjectFactory();
				apInvoice = newFactory.Load<APInvoice>(incompleteInvoice.PK);
				AssertNull(" No stmnote should be found ", apInvoice.GetDetailsNoteIfItExists_ForTestOnly(new BusinessObjectFactory()));
			}
			else
			{
				Assert(true);
			}
		}

		public void TestRestoreSavedData_ShowAnyWarningsOnInvoiceHeader()
		{
			var invoice = TestObjectCreator.CreateInvoiceWithLine(typeof(APInvoice), "00001", TestObjectCreator.AUD, 1m, 0m, 0m, 0m, 0m);
			invoice.AH_OH = TestObjectCreator.AALSHI.PK;
			invoice.ValidateExpectedInvoiceTotal = true;
			invoice.ExpectedInvoiceExclTaxTotal = 900m;

			//The test verifies that, on restoring an incomplete invoice, warnings on the invoice, if any, are shown. So, a random warning has been used to test here.
			//The below warning is when invoice.ExpectedInvoiceTotal != invoice.ExpectedInvoiceExclTaxTotal + invoice.ExpectedInvoiceTaxTotal i.e. 0 != 900
			var expectedMessage = "The Expected Total Incl. Tax should equal the Expected Total Tax plus the Expected Total Excl. Tax.";
			AssertHasWarning("Precondition:", invoice.ExpectedInvoiceTotalInfo, expectedMessage);

			invoice.SaveAsIncomplete();
			var newFactory = new BusinessObjectFactory();
			var apInvoice = newFactory.Load<APInvoice>(invoice.PK);

			apInvoice.RestoreSavedData();
			AssertHasWarning(apInvoice.ExpectedInvoiceTotalInfo, expectedMessage);
		}

