				incompleteInvoice.AH_OH = TestObjectCreator.Creditor1.PK;

				incompleteInvoice.SaveAsIncomplete();

				Assert(" Precondition: Invoice must be incomplete ", incompleteInvoice.IsIncompleteInvoice);
				AssertEquals(" Precondition: Must have a line ", 1, incompleteInvoice.Lines.Count);
				AssertNotNull(" Precondition: Stmnote should be found ", incompleteInvoice.GetDetailsNoteIfItExists_ForTestOnly(new BusinessObjectFactory()));

				incompleteInvoice.Delete();

				AssertNull("Stmnote should be deleted", incompleteInvoice.GetDetailsNoteIfItExists_ForTestOnly());
				AssertNotNull("Stmnote should be deleted only in memory", incompleteInvoice.GetDetailsNoteIfItExists_ForTestOnly(new BusinessObjectFactory()));

				Factory.Save();
				AssertNull("Stmnote should be deleted from db", incompleteInvoice.GetDetailsNoteIfItExists_ForTestOnly(new BusinessObjectFactory()));
