		public void TestARAPInvoicePostingExchangeRateOptionWhenAH_PostedToEFTUnticked()
		{
			var postingExRateRegistry = PostingExRateRegistry;
			InvoicingBase invoice = (InvoicingBase)Factory.New(GetExpectedBusinessObjectType());

			if (invoice is TransactionPendingAllocation)
			{
				Assert("N/a", true);
				return;
			}

			invoice.AH_RX_NKTransactionCurrency = TestObjectCreator.USD.RX_Code;
			AssertEquals("ExchangeRate by default should be 1", 1m, invoice.AH_ExchangeRate);

			invoice.AH_PostedToEFT = true;
			invoice.AH_OSExTaxAmount = 100m;
			invoice.AH_LocalExTaxAmount = 200m;

			AssertEquals("PreCondition: Factory should allow multiple BizObjects around a row", true, Factory.AllowMultipleBusinessObjectsAroundOneRow);
			AccTransactionHeader header = Factory.Load<AccTransactionHeader>(invoice.PK);
			AssertEquals("ExchangeRate should be as expected", 0.5m, header.AH_ExchangeRate);

			TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, "BUY", 2m, new DateTime(2000, 1, 1), new DateTime(2070, 1, 1));
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, "SEL", 2m, new DateTime(2000, 1, 1), new DateTime(2070, 1, 1));

			PostingExRateRegistry.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, "INV");
			invoice.AH_PostedToEFT = false;
			header = Factory.Load<AccTransactionHeader>(invoice.PK);
			AssertEquals("ExchangeRate should be set back", 2m, header.AH_ExchangeRate);

			ExchangeRateReader.GetReaderInstance().ClearCache();
		}

