		[SuspendGLAccountAndChargeCodeCriticalValidation]
		public void TestResetNumberFountainForProperties()
		{
			GlbCompany.CurrentCompany.SetCountry(Constants.CountryCodes.Mexico);
			SetupComplianceRuleRegistry();

			ZGuid menuPK = Factory.LoadTop1<StmMenuItem>(new ZQuery(StmMenuItemSchema.SU_MenuName, "ARInvoice PE Factura")).PK;
			AccComplianceSequence sequence = TestObjectCreator.CreateNewComplianceSequence(menuPK, "TXI", 1, 100, 25);
			sequence.XD_Prefix = "01.02-";
			sequence.XD_GB_BranchOwner = GlbBranch.CurrentBranch.PK;
			sequence.XD_GC_Company = GlbCompany.CurrentCompany.PK;
			Factory.Save();
			AssertEquals(25m, sequence.XD_NextNumber);
			var shouldThrowCriticalValidation = false;
			AssertResetNumberFountainForProperties();
			shouldThrowCriticalValidation = true;
			AssertResetNumberFountainForProperties();

			void AssertResetNumberFountainForProperties()
			{
				var invoice = Factory.NewWithValidTestData<ARInvoice>();
				invoice.AH_Desc = "test";
				invoice.AH_TransactionReference = "";
				invoice.AH_ComplianceSubType = "TXI";
				var line = (InvoicingLineBase)invoice.Lines.AddNew();
				line.AL_AT = TaxRate.PK;
				var invoice1 = TestObjectCreator.CreateInvoiceWithLine(typeof(APInvoiceForBulkPoster), shouldThrowCriticalValidation ? "INV003" : "INV001", TestObjectCreator.AUD, 1, 10, 0, 10, 0);
				invoice1.AH_TransactionCategory = Constants.TransactionCategory.Codes.SelfBilling;
				Factory.Save();

				Assert(!invoice.AH_TransactionReference.IsEmpty);
				Assert(!invoice1.AH_ConsolidatedInvoiceRef.IsEmpty);
				Assert(!invoice1.AH_TransactionNum.IsEmpty);

				invoice = Factory.NewWithValidTestData<ARInvoice>();
				invoice.AH_Desc = "test";
				invoice.AH_TransactionReference = "";
				invoice.AH_ComplianceSubType = "TXI";
				line = (InvoicingLineBase)invoice.Lines.AddNew();
				line.AL_AT = TaxRate.PK;
				invoice1 = TestObjectCreator.CreateInvoiceWithLine(typeof(APInvoiceForBulkPoster), shouldThrowCriticalValidation ? "INV004" : "INV002", TestObjectCreator.AUD, 1, 10, 0, 10, 0);
				invoice1.AH_TransactionCategory = Constants.TransactionCategory.Codes.SelfBilling;

				if (shouldThrowCriticalValidation)
				{
					Factory.ForceCriticalValidationErrorForTestOnly(CriticalValidationErrorType.TransactionHeaderIncorrectOutstandingAmount_12);
				}

				try
				{
					Factory.Save();
				}
				catch (OnSavingCriticalCheckException)
				{
					Assert(shouldThrowCriticalValidation);
				}
				finally
				{
					Factory.ForceCriticalValidationErrorForTestOnly(CriticalValidationErrorType.NoError);
				}

				AssertEquals("Is empty", shouldThrowCriticalValidation, string.Empty == invoice.AH_TransactionReference);
				AssertEquals("Is empty", shouldThrowCriticalValidation, string.Empty == invoice1.AH_ConsolidatedInvoiceRef);
				AssertEquals("Is empty", shouldThrowCriticalValidation, string.Empty == invoice1.AH_TransactionNum);

				ExceptionReporterTestListener.Instance.Clear();
			}
		}

