		public void TestGetConsolReturnsSameConsolWithOrWithoutInvoicingLineBase()
		{
			var consol = TestObjectCreator.CreateConsol("AUSYD", "NZAKL", "C001");
			var shipment = TestObjectCreator.CreateShipment("S001", consol);
			var job = TestObjectCreator.CreateJob(shipment);
			Factory.Save();

			var consolCost = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC1, 10);
			var invoice = TestObjectCreator.CreateInvoice(typeof(ARInvoice), TestObjectCreator.AUD, 1);
			invoice.AH_ConsolidatedInvoiceRef = consol.JK_UniqueConsignRef;

			var line = TestObjectCreator.CreateARInvoiceLine((ARInvoice)invoice, job, TestObjectCreator.CC1, TestObjectCreator.AUD, 1, string.Empty, 10);

			AssertNull(line.GetConsolID());
			AssertEquals("Consol should be found without parent table code", invoice.Consol.PK, consol.PK);

			invoice.ImportSingleCost(consolCost, line);

			var consolId = line.GetConsolID();
			AssertNotNull(consolId);
			AssertEquals(consol.PK, consolId.Item1);
			AssertEquals(consol.Prefix, consolId.Item2);
			AssertEquals("Consol should be found with parent table code", invoice.Consol.PK, consol.PK);
		}

