		void AssertSavingWithDuplicateInvoiceNumber(string allowDuplicateInvoiceNumberRule, ZDateTime invoiceDate, ZDateTime invoiceDate2, string expErrorMessage)
		{
			using (AccountingMasterFilesRegistry.Instance.AllowDuplicateInvoiceNumberDefaultingRule.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, allowDuplicateInvoiceNumberRule))
			{
				var transaction = TestObjectCreator.CreateAPInvoice<APInvoice>("TSTTRNSC", TestObjectCreator.AUD, 1.0m, 200m, 0m, 0m, 500m, 0m, 0m, TestObjectCreator.Creditor1);
				transaction.AH_InvoiceDate = invoiceDate;
				transaction.AH_TransactionCount = 1;
				Factory.Save();

				APInvoice transaction2;
				using (new DisposableAction(() => Factory.SuspendValidation(), () => Factory.ResumeValidation()))
				{
					transaction2 = TestObjectCreator.CreateAPInvoice<APInvoice>("TSTTRNSC", TestObjectCreator.AUD, 1.0m, 200m, 0m, 0m, 500m, 0m, 0m, TestObjectCreator.Creditor1);
				}

				try
				{
					Factory.Save();
					Fail("Exception should be thrown to test unsuccessful saving.");
				}
				catch (Exception e)
				{
					var msg = e.Message;

					string expectedErrorMessage = $@"
** Error Saving Record **

ServerName: {Db.ServerName}
DatabaseName: {Db.DatabaseName}
Tablename: AccTransactionHeader";

					AssertContains("Precondition: Invoice should fail to save if validation is not run.", expectedErrorMessage, msg);
				}

				transaction2.AH_InvoiceDate = transaction.AH_InvoiceDate;
				transaction2.Validation.ValidateAH_TransactionNum();

				try
				{
					Factory.Save();
					Fail("Exception should be thrown to test unsuccessful saving.");
				}
				catch (Exception e)
				{
					var msg = e.Message;

					string expectedErrorMessage = $@"
** Error Saving Record **

ServerName: {Db.ServerName}
DatabaseName: {Db.DatabaseName}
Tablename: AccTransactionHeader";

					AssertContains("Invoice should fail to save if validation is run and error is returned in the validation.", expectedErrorMessage, msg);
				}

				transaction2.AH_InvoiceDate = invoiceDate2;
				transaction2.Validation.ValidateAH_TransactionNum();

				var duplicateTransactionNumberDetails = transaction2.GetPreviousSameNumberTransactionDetails();
				Assert(duplicateTransactionNumberDetails.HasValue);
				AssertEquals(transaction.AH_TransactionCount, duplicateTransactionNumberDetails.Value.PreviousTransactionCount);
				AssertEquals(transaction.AH_InvoiceDate.Date, duplicateTransactionNumberDetails.Value.PreviousInvoiceDate);

				Factory.Save();
				var invoiceADDLog = transaction2.Logs.GetAllLogs().Cast<StmALog>().FirstOrDefault(x => x.SL_SE_NKEvent == Events.AddedARecordToTheSystem.Code);
				AssertEquals(expErrorMessage, invoiceADDLog.SL_Reference);
			}
		}

		[TestDate(2020, 3, 2, 00, 00, 0)]
		public void TestPreviousSameNumberTransactionDetails()
		{
			var transaction = TestObjectCreator.CreateAPInvoice<APInvoice>("TSTTRNSC", TestObjectCreator.AUD, 1.0m, 200m, 0m, 0m, 500m, 0m, 0m, TestObjectCreator.Creditor1);
			transaction.AH_InvoiceDate = ZDate.Today;
			transaction.AH_TransactionCount = 1;
			Factory.Save();

			var transaction2 = TestObjectCreator.CreateAPInvoice<APInvoice>("TSTTRNSC", TestObjectCreator.AUD, 1.0m, 200m, 0m, 0m, 500m, 0m, 0m, TestObjectCreator.Creditor1);
			transaction2.AH_InvoiceDate = transaction.AH_InvoiceDate.AddMonths(AccountingUtils.DuplicateInvoiceNumberPeriodMonths);
			transaction2.Validation.ValidateAH_TransactionNum();

			var duplicateTransactionNumberDetails = transaction2.GetPreviousSameNumberTransactionDetails();
			Assert(duplicateTransactionNumberDetails.HasValue);
			AssertEquals(transaction.AH_TransactionCount, duplicateTransactionNumberDetails.Value.PreviousTransactionCount);
			AssertEquals(transaction.AH_InvoiceDate.Date, duplicateTransactionNumberDetails.Value.PreviousInvoiceDate);

			transaction2.AH_TransactionNum = "ABC123";
			duplicateTransactionNumberDetails = transaction2.GetPreviousSameNumberTransactionDetails();
			AssertEquals("PreviousSameNumberTransactionDetails reset after transaction number update", false, duplicateTransactionNumberDetails.HasValue);

			transaction2.AH_TransactionNum = "TSTTRNSC";
			transaction2.Validation.ValidateAH_TransactionNum();
			duplicateTransactionNumberDetails = transaction2.GetPreviousSameNumberTransactionDetails();
			Assert(duplicateTransactionNumberDetails.HasValue);

			transaction2.AH_InvoiceDate = ZDateTime.Today;
			duplicateTransactionNumberDetails = transaction2.GetPreviousSameNumberTransactionDetails();
			AssertEquals("PreviousSameNumberTransactionDetails reset after invoice date update", false, duplicateTransactionNumberDetails.HasValue);

			transaction2.Validation.ValidateAH_TransactionNum();
			duplicateTransactionNumberDetails = transaction2.GetPreviousSameNumberTransactionDetails();
			AssertEquals("Duplicate not allowed, PreviousSameNumberTransactionDetails is empty.", false, duplicateTransactionNumberDetails.HasValue);

			transaction2.AH_InvoiceDate = transaction.AH_InvoiceDate.AddMonths(AccountingUtils.DuplicateInvoiceNumberPeriodMonths);
			transaction2.Validation.ValidateAH_TransactionNum();
			duplicateTransactionNumberDetails = transaction2.GetPreviousSameNumberTransactionDetails();
			Assert(duplicateTransactionNumberDetails.HasValue);

			transaction2.AH_OH = ZGuid.Empty;
			duplicateTransactionNumberDetails = transaction2.GetPreviousSameNumberTransactionDetails();
			AssertEquals("PreviousSameNumberTransactionDetails reset after creditor update", false, duplicateTransactionNumberDetails.HasValue);
		}

		[SuspendCriticalValidation]
		public void TestAutoCreatedLogReferenceWhenPost()
		{
			var expected = ZString.Format("{1}{0}{2}{0}", AccountingConstants.InvoiceAdditionalReference.Separator, InvoicingBase.AH_Ledger, InvoicingBase.AH_TransactionType);

			if (InvoicingBase.IsReceivableOrPayable_ForTestOnly
				&& InvoicingBase.IsInvoiceOrCreditNoteOrAdjustmentNote_ForTestOnly)
			{
				InvoicingBase.Factory.Save();
				AssertEquals(expected + AccountingConstants.InvoiceAdditionalReference.Posted, InvoicingBase.Logs.AutoCreatedLog.SL_Reference);
			}
			else if (InvoicingBase.AH_Ledger == LedgerTypes.TransactionsPendingAllocation)
			{
				InvoicingBase.Factory.Save();
				AssertEquals(expected + "Created", InvoicingBase.Logs.AutoCreatedLog.SL_Reference);
			}
			else
			{
				InvoicingBase.Factory.Save();
				AssertEquals(ZString.Empty, InvoicingBase.Logs.AutoCreatedLog.SL_Reference);
			}

			//Incomplete Invoice / Credit Note -> Empty
			if (GetExpectedBusinessObjectType() == typeof(APInvoice) || GetExpectedBusinessObjectType() == typeof(APCreditNote))
			{
				var incompleteInvoice = Factory.NewWithValidTestData(GetExpectedBusinessObjectType()) as InvoicingBase;
				incompleteInvoice.SaveAsIncomplete();
				expected = ZString.Format("{1}{0}{2}{0}", AccountingConstants.InvoiceAdditionalReference.Separator, incompleteInvoice.AH_Ledger, incompleteInvoice.AH_TransactionType);
				AssertEquals("Should be marked as saving as incomplete invoice", expected + "Saved as Incomplete", incompleteInvoice.Logs.AutoCreatedLog.SL_Reference);
			}

			//UA Invoice / Credit Note	-> AP|INV|Posted
			if (GetExpectedBusinessObjectType() == typeof(UAInvoice) || GetExpectedBusinessObjectType() == typeof(UACreditNote))
			{
				expected = ZString.Format("{1}{0}{2}{0}", AccountingConstants.InvoiceAdditionalReference.Separator, LedgerTypes.AccountsPayable, GetExpectedBusinessObjectType() == typeof(UAInvoice) ? TransactionTypes.Invoice : TransactionTypes.CreditNote);
				var convertedInvoice = new UnapprovedTransactionConverter(Factory).ConvertToAP(InvoicingBase, false);
				convertedInvoice.Factory.Save();
				AssertEquals(expected + AccountingConstants.InvoiceAdditionalReference.Posted, convertedInvoice.Logs.AutoCreatedLog.SL_Reference);
			}

			//Transaction Pending Allocation	-> AP|INV|Posted
			if (GetExpectedBusinessObjectType() == typeof(TransactionPendingAllocation))
			{
				expected = ZString.Format("{1}{0}{2}{0}", AccountingConstants.InvoiceAdditionalReference.Separator, LedgerTypes.AccountsPayable, TransactionTypes.Invoice);
				var newAPInvoice = TransactionAllocationConverter.ConvertUnallocatedToAP(InvoicingBase as TransactionPendingAllocation).Invoice;
				newAPInvoice.Factory.Save();
				AssertEquals(expected + AccountingConstants.InvoiceAdditionalReference.Posted, newAPInvoice.Logs.AutoCreatedLog.SL_Reference);
			}
		}

		[SuspendCriticalValidation]
		public void TestAutoCreatedLogReferenceWhenFullyMatch()
		{
			var expected = ZString.Format("{1}{0}{2}{0}", AccountingConstants.InvoiceAdditionalReference.Separator, InvoicingBase.AH_Ledger, InvoicingBase.AH_TransactionType);

			if (InvoicingBase.IsReceivableOrPayable_ForTestOnly
				&& InvoicingBase.IsInvoiceOrCreditNoteOrAdjustmentNote_ForTestOnly)
			{
				using (InvoicingBase.SuspendHeaderAmountsRecalculation())
				{
					InvoicingBase.AH_OSExTaxAmount = 200m;
					InvoicingBase.AH_OutstandingAmount = 200.00m;
					InvoicingBase.Factory.Save();
					AssertEquals(expected + AccountingConstants.InvoiceAdditionalReference.Posted, InvoicingBase.Logs.AutoCreatedLog.SL_Reference);

					//Fully Match
					((IMatching)InvoicingBase).FullyPay(ZDateTime.BrettsBirthday);
					InvoicingBase.Factory.Save();
					AssertEquals("Fully Paid date on Invoice", ZDateTime.BrettsBirthday, InvoicingBase.AH_FullyPaidDate);
					AssertEquals("Outstanding Amount on Invoice", 0m, InvoicingBase.AH_OutstandingAmount);
					AssertEquals(expected + AccountingConstants.InvoiceAdditionalReference.FullyMatched, InvoicingBase.Logs.AutoCreatedLog.SL_Reference);

					//Undo Fully Match
					InvoicingBase.AH_OutstandingAmount = 200.00m;
					InvoicingBase.AH_FullyPaidDate = ZDateTime.Empty;
					InvoicingBase.Factory.Save();
					AssertEquals(expected + AccountingConstants.InvoiceAdditionalReference.UndoFullyMatched, InvoicingBase.Logs.AutoCreatedLog.SL_Reference);
				}
			}
			else if (InvoicingBase.AH_Ledger == LedgerTypes.TransactionsPendingAllocation)
			{
				InvoicingBase.Factory.Save();
				AssertEquals(expected + "Created", InvoicingBase.Logs.AutoCreatedLog.SL_Reference);
			}
			else
			{
				InvoicingBase.Factory.Save();
				AssertEquals(ZString.Empty, InvoicingBase.Logs.AutoCreatedLog.SL_Reference);
			}
		}

