		public void TestShouldNotAutoCreateComplianceDocumentWhenWritingOff()
		{
			var invoicingBase = HeaderWithLines as InvoicingBase;
			if (invoicingBase.AH_Ledger != LedgerTypes.AccountsReceivable || !invoicingBase.HasSupportedTransactionTypes)
			{
				Assert("Only Receivable transaction which support compliance document and writing off feature should run the UT.", true);
				return;
			}

			AccGLHeader badDebtAccount = Factory.LoadTop1<AccGLHeader>(new ZQuery(AccGLHeaderSchema.AG_AccountNum, "3980.00.00"));

			AccountingMasterFilesRegistry.Instance.EnableComplianceDocumentModule.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);
			AccountingConfigurationRegistry.Instance.BadDebtWriteOffAccount.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, badDebtAccount.PK.ToGuid());
			Env.Security.CreateReceivablesComplianceDocuments.IsAllowed = true;

			var testObjectCreatorWithNewFactory = new TestObjectCreator(Factory.CreateNewFactory());
			testObjectCreatorWithNewFactory.AALSHI.CompanyData.OB_ARCreateVATComplianceDocumentOnPosting = Constants.OrganisationCreateComplianceDocumentOnPostingTypes.RollupByCharge;
			testObjectCreatorWithNewFactory.Factory.Save();

			TestObjectCreator.InitializeInvoicingBase(invoicingBase, "TEST001", TestObjectCreator.AALSHI, TestObjectCreator.OverheadChargeCode, TestObjectCreator.GST1);

			string cantWriteOffReason;
			var writtenOffTransaction = (InvoicingBase)TestObjectCreator.WriteOffBadDebt(invoicingBase as IBadDebtWritingOff, out cantWriteOffReason);
			Assert("Precondition: invoice must be valid for Writing Off.", string.IsNullOrEmpty(cantWriteOffReason));

			Factory.Save();

			var complianceDocument = writtenOffTransaction.GetTransactionGeneratedComplianceDocument();
			AssertNull("compliance document should not be created.", complianceDocument);
		}

