		void AssertCreateARCRDComplianceDocumentWhenCreditNoteComplianceDocumentConfigurationIsOn()
		{
			// Document number is empty
			AccountingMasterFilesRegistry.Instance.ComplianceDocumentNumberAllocation_Receivables.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, AccComplianceSequenceLookups.ComplianceDocumentNumberAllocationSettingCodes.Print);
			var newFactory = new BusinessObjectFactory();
			var sequence = newFactory.LoadTop1<AccComplianceSequence>(new ZQuery(AccComplianceSequenceSchema.XD_Code, "AA"));
			sequence.XD_IsActive = false;
			newFactory.Save();

			var arInvoice = TestObjectCreator.CreateARInvoice<ARInvoice>("INV0001", TestObjectCreator.AUD, 1m, TestObjectCreator.AALSHI);
			TestObjectCreator.CreateARInvoiceLine(arInvoice, null, TestObjectCreator.FRT, TestObjectCreator.AUD, 1m, "desc", 0m);
			Factory.Save();

			new ComplianceDocumentCreator(new[] { arInvoice }, OrganisationCreateComplianceDocumentOnPostingTypes.NotRollup).CreateComplianceDocumentRecords();
			Factory.Save();
			var header = arInvoice.GetTransactionGeneratedComplianceDocument();
			AssertNullOrEmpty("Document number should be empty.", header.ADH_DocumentNumber);

			TestObjectCreator.GLHeader1.AG_Description = "Test GlAccount";
			var arCreditNote = TestObjectCreator.CreateInvoice(GetExpectedBusinessObjectType(), "CRD0001", TestObjectCreator.AUD, 1M, TestObjectCreator.AALSHI);
			TestObjectCreator.CreateARCreditNoteLine(arCreditNote as ARCreditNote, null, TestObjectCreator.FRT, 2000.00m, GlbCompany.CurrentCompany.LocalCurrency, 1.0m, "Test");

			arCreditNote.OriginalTransactionReference = arInvoice.PK;
			arCreditNote.AH_Desc = "set line tax id";
			arCreditNote.Lines[0].AL_AT = TestObjectCreator.GSTFREE1.PK;
			TransactionMatchLink matchLink = ((IMatching)arCreditNote).CurrentMatchGroup.AddNew(); // to pass IsCancelled check
			matchLink.AP_AH = arCreditNote.PK;
			TestObjectCreator.SetupMatchLinkMatchDate(matchLink);
			arCreditNote.AH_IsCancelled = false;
			Factory.Save();

			header = arCreditNote.GetTransactionGeneratedComplianceDocument();
			AssertNull("CRD compliance document should not be created.", header);

			//Document number is not empty
			AccountingMasterFilesRegistry.Instance.ComplianceDocumentNumberAllocation_Receivables.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, AccComplianceSequenceLookups.ComplianceDocumentNumberAllocationSettingCodes.Post);
			sequence.Reload();
			sequence.XD_IsActive = true;
			newFactory.Save();

			var arInvoice1 = TestObjectCreator.CreateARInvoice<ARInvoice>("INV0002", TestObjectCreator.AUD, 1m, TestObjectCreator.AALSHI);
			TestObjectCreator.CreateARInvoiceLine(arInvoice1, null, TestObjectCreator.FRT, TestObjectCreator.AUD, 1m, "desc", 0m);
			Factory.Save();

			new ComplianceDocumentCreator(new[] { arInvoice1 }, OrganisationCreateComplianceDocumentOnPostingTypes.NotRollup).CreateComplianceDocumentRecords();
			Factory.Save();
			header = arInvoice1.GetTransactionGeneratedComplianceDocument();
			AssertNotNullOrEmpty("Document number should not be empty.", header.ADH_DocumentNumber);

			TestObjectCreator.GLHeader1.AG_Description = "Test GlAccount";
			var arCreditNote1 = TestObjectCreator.CreateInvoice(GetExpectedBusinessObjectType(), "CRD0002", TestObjectCreator.AUD, 1M, TestObjectCreator.AALSHI);
			TestObjectCreator.CreateARCreditNoteLine(arCreditNote1 as ARCreditNote, null, TestObjectCreator.FRT, 2000.00m, GlbCompany.CurrentCompany.LocalCurrency, 1.0m, "Test");

			arCreditNote1.OriginalTransactionReference = arInvoice1.PK;
			arCreditNote1.AH_Desc = "set line tax id";
			arCreditNote1.Lines[0].AL_AT = TestObjectCreator.GSTFREE1.PK;
			matchLink = ((IMatching)arCreditNote1).CurrentMatchGroup.AddNew(); // to pass IsCancelled check
			matchLink.AP_AH = arCreditNote1.PK;
			TestObjectCreator.SetupMatchLinkMatchDate(matchLink);
			arCreditNote1.AH_IsCancelled = false;
			Factory.Save();

			header = arCreditNote1.GetTransactionGeneratedComplianceDocument();
			AssertNotNull("CRD compliance document should be created", header);
			Assert(!header.ADH_XD_ComplianceBook.IsValid);

			// Without Origianl Ref
			var arInvoice2 = TestObjectCreator.CreateARInvoice<ARInvoice>("INV0003", TestObjectCreator.AUD, 1m, TestObjectCreator.AALSHI);
			new ComplianceDocumentCreator(new[] { arInvoice2 }, OrganisationCreateComplianceDocumentOnPostingTypes.NotRollup).CreateComplianceDocumentRecords();
			Factory.Save();

			var arCreditNote2 = TestObjectCreator.CreateInvoice(GetExpectedBusinessObjectType(), "CRD0003", TestObjectCreator.AUD, 1M, TestObjectCreator.AALSHI);
			TestObjectCreator.CreateARCreditNoteLine(arCreditNote2 as ARCreditNote, null, TestObjectCreator.FRT, 2000.00m, GlbCompany.CurrentCompany.LocalCurrency, 1.0m, "Test");
			Factory.Save();

			arCreditNote2.AH_Desc = "set line tax id";
			arCreditNote2.Lines[0].AL_AT = TestObjectCreator.GSTFREE1.PK;
			matchLink = ((IMatching)arCreditNote2).CurrentMatchGroup.AddNew(); // to pass IsCancelled check
			matchLink.AP_AH = arCreditNote2.PK;
			TestObjectCreator.SetupMatchLinkMatchDate(matchLink);
			arCreditNote2.AH_IsCancelled = false;
			Factory.Save();

			header = arCreditNote2.GetTransactionGeneratedComplianceDocument();
			if (TestObjectCreator.AALSHI.CompanyData.OB_ARCreateVATComplianceDocumentOnPosting == "NON")
			{
				AssertNull("CRD compliance document should not be created", header);
			}
			else
			{
				AssertNotNull("CRD compliance document should be created", header);
			}
		}

