		public void TestShouldReopenJobWithAmendingTransaction()
		{
			var original = (InvoicingBase)Factory.New(GetExpectedBusinessObjectType());
			if (original is IAmending && original.HasImplementedGenerateAmendingTransaction)
			{
				var invoice = (original as IAmending).GenerateAmendingTransaction(GetExpectedBusinessObjectType());
				if (original is APInvoice)
				{
					original.AH_TransactionNum = "ABC12345";
					invoice.AH_TransactionNum = "XYZ67890";
				}
				Factory.Save();
				AssertEquals("Precondition", true, invoice.IsInDatabase);
				AssertEquals("Precondition", false, invoice.IsApprovingInvoice);
				AssertEquals("Precondition", false, invoice.IsCompletingInvoice);
				AssertEquals("Precondition", false, invoice.IsAllocatingInvoice);
				AssertEquals("Precondition", true, (invoice as IAmending).IsAmendingTransaction);

				AssertEquals("Should Reopen Job", true, invoice.ShouldReopenJob);
			}
			else
			{
				Assert("Not applicable for this class because it does not implement IAmending", true);
			}
		}

		public void TestHasZeroLocalButNonZeroOSTaxAmount()
		{
			var expectType = GetExpectedBusinessObjectType();
			if (expectType == typeof(ARInvoice) || expectType == typeof(ARCreditNote))
			{
				var invoice = (InvoicingBase)Factory.New(expectType);
				invoice.AH_RX_NKTransactionCurrency = "USD";
				Assert(!invoice.HasZeroLocalButNonZeroOSTaxAmount);

				var line1 = invoice.Lines.AddNew() as InvoicingLineBase;
				line1.AL_OSTaxAmount = 10m;
				Assert(!invoice.HasZeroLocalButNonZeroOSTaxAmount);

				using (line1.GetOSAmountCalculationSuspender())
				{
					line1.AL_LocalTaxAmount = 0m;
					AssertEquals(10m, line1.AL_OSTaxAmount);
					Assert(invoice.HasZeroLocalButNonZeroOSTaxAmount);
				}

				using (invoice.Lines.SuspendListChanged())
				{
					line1.AL_LocalTaxAmount = 10m;

					AssertEquals(10m, invoice.AH_OSTaxAmount);
					AssertEquals(0m, invoice.AH_LocalTaxAmount);
					Assert(invoice.HasZeroLocalButNonZeroOSTaxAmount);
				}

				Assert(!invoice.HasZeroLocalButNonZeroOSTaxAmount);
			}
			else
			{
				Assert(true);
			}
		}

		public void TestShouldNotReportZeroLocalButNonZeroOSTaxAmountWhenFactoryHasNoContext()
		{
			var expectType = GetExpectedBusinessObjectType();
			if (expectType == typeof(ARInvoice) || expectType == typeof(ARCreditNote))
			{
				foreach (var setContext in new bool[] { false, true })
				{
					var invoice = (InvoicingBase)Factory.New(expectType);
					invoice.AH_RX_NKTransactionCurrency = "USD";
					invoice.AH_ExchangeRate = 100;
					var line = invoice.Lines.AddNew() as InvoicingLineBase;
					line.AL_AT = TestObjectCreator.GST1.PK;
					line.AL_OSExTaxAmount = 1;
					line.AL_AG = TestObjectCreator.GLHeader1.PK;

					AssertEquals(0.1m, line.AL_OSTaxAmount);
					AssertEquals(0m, line.AL_LocalTaxAmount);
					AssertEquals(0, ErrorReporter.TotalErrorCount);

					if (setContext)
					{
						Factory.SetContext(BusinessContext.PostingReceivableChargesForTaxCalculation);
					}

					Factory.Save();
					AssertEquals(setContext ? 1 : 0, ErrorReporter.TotalErrorCount);
					ErrorReporter.Clear();

					if (setContext)
					{
						Factory.RemoveContext(BusinessContext.PostingReceivableChargesForTaxCalculation);
					}
				}
			}
			else
			{
				Assert(true);
			}
		}

