		public void TestInvoiceHasZeroLocalButNonZeroOSTaxAmountShouldReportExpectErrorWhenSaved()
		{
			var expectType = GetExpectedBusinessObjectType();
			if (expectType == typeof(ARInvoice) || expectType == typeof(ARCreditNote))
			{
				var shipment = TestObjectCreator.CreateShipment("S00001100");
				var job = CreateJob("Z00001011", TestObjectCreator.AALSHI, 0m, TestObjectCreator.ABIGAS, 0m);
				job.JH_ParentID = shipment.PK;
				job.JH_ParentTableCode = JobShipmentSchema.Constants.Prefix;
				Factory.Save();
				var usdCurrency = Factory.LoadTop1<RefCurrency>(new ZQuery(RefCurrencySchema.RX_Code, "USD"));
				CreateExchangeRate(job, usdCurrency, 10m, false);
				var charge = Factory.New<TestCharge>();
				charge.JR_JH = job.PK;
				charge.JR_AC = TestObjectCreator.FRT.PK;
				charge.JR_Desc = "Test";
				charge.JR_RX_NKCostCurrency = TestObjectCreator.AUD.RX_Code;
				charge.JR_OH_SellAccount = TestObjectCreator.AALSHI.PK;
				charge.JR_RX_NKSellCurrency = usdCurrency.RX_Code;
				charge.JR_OSSellAmt = 10m;
				charge.JR_InvoiceType = InvoiceTypesList.Codes.ForeignCurrencyInvoice;
				TestObjectCreator.GST1.SetExtraRate_ForTestOnly(1, 1);
				charge.JR_AT_SellGSTRate = TestObjectCreator.GST1.PK;

				var invoice = new ChargePoster(Factory).Post(charge);

				Factory.Save();
				AssertEquals(1, ErrorReporter.TotalErrorCount);

				var expectError = $@"OS Tax Amount is NOT Zero while Local Tax Amount is Zero
UseLocalExTaxAmountToCalculateLocalTax: False
ShouldFixTaxAmountOnHeader: False
HasWarehousePeriodicBillingJob: False
Invoice tax amount details before adjustment

OSTaxAmountIsNotZeroWhileLocalTaxAmoutIsZero:
Header: OSTaxAmount = 0, LocalTaxAmount = 0
Lines:
OSExTaxAmount = 10, LocalExTaxAmount = 1, OSTaxAmount = 0.01, LocalTaxAmount = 0.00, Charge JR_OSSellGSTAmt_Calc = 0, Charge JR_Sell_LocalGSTAmount = 0.00

Invoice tax amount details after adjustment
Header: OSTaxAmount = 0.01, LocalTaxAmount = 0
Lines:
OSExTaxAmount = 10, LocalExTaxAmount = 1, OSTaxAmount = 0.01, LocalTaxAmount = 0.00, Charge JR_OSSellGSTAmt_Calc = 0, Charge JR_Sell_LocalGSTAmount = 0.00";

				AssertContains(expectError, ErrorReporter.LastMessageReported);
				//AssertMultilineASCIIEquals(expectError, ErrorReporter.LastMessageReported);
				Assert(Regex.IsMatch(ErrorReporter.LastMessageReported, "^Invoice details\r\nHeader: PK =.*\r\nLine Details:\r\nLine: PK = .*", RegexOptions.Multiline));
				ErrorReporter.Clear();
			}
			else
			{
				Assert(true);
			}
		}

