		public void TestAH_AgreedPaymentMethodOverride_SetTransactionCategoryAndSetIsDisbursementOrFinal()
		{
			var testOrg = TestObjectCreator.CreateOrgHeader("Test1", true, true);
			var newFactory = new BusinessObjectFactory();
			var testOrgInNewFactory = newFactory.Load<OrgHeader>(testOrg.PK);
			var term1 = testOrgInNewFactory.CompanyData.ARTerms[0];
			TestObjectCreator.SetupTermsInfo(term1, "ALL", ZGuid.Empty, ZGuid.Empty, "ALL", "ALL", "ALL", "MTH", 10, "DBC");

			var term2 = testOrgInNewFactory.CompanyData.ARTerms.AddNew();

			TestObjectCreator.SetupTermsInfo(term2, "ALL", ZGuid.Empty, ZGuid.Empty, "ALL", "ALL", "DSB", "INV", 0, "CHK");

			newFactory.Save();

			ARInvoice invoice = TestObjectCreator.CreateARInvoice<ARInvoice>("ARInv1", TestObjectCreator.AUD, 1m, TestObjectCreator.AALSHI);

			invoice.AH_OH = testOrg.PK;

			AssertEquals("MTH", invoice.AH_InvoiceTerm);
			AssertEquals((ZByte)10, invoice.AH_InvoiceTermDays);
			AssertEquals("DBC", invoice.AH_AgreedPaymentMethodOverride);

			invoice.AH_TransactionCategory = "DSB";

			AssertEquals("INV", invoice.AH_InvoiceTerm);
			AssertEquals((ZByte)0, invoice.AH_InvoiceTermDays);
			AssertEquals("CHK", invoice.AH_AgreedPaymentMethodOverride);

			invoice.AH_AgreedPaymentMethodOverride = "XXX";

			AssertEquals("XXX", invoice.AH_AgreedPaymentMethodOverride);

			invoice.IsDisbursementOrFinal = true;

			AssertEquals("DBT", invoice.AH_TransactionCategory);
			AssertEquals("CHK", invoice.AH_AgreedPaymentMethodOverride);
		}

