			arInvoiceLine1.AL_AT = TestObjectCreator.CAP.PK;
			arInvoiceLine1.ComplianceDocumentNumber = "123";
			arInvoiceLine1.ComplianceDocumentVATRegistrationNum = "234";
			arInvoiceLine1.ComplianceDocumentReportingPeriod = 201803;
			arInvoiceLine1.CreateComplianceDocumentRecordOnPosting = true;
			arInvoiceLine1.ComplianceDocumentDate = ZDateTime.Today;
			arInvoiceLine1.ComplianceDocumentSupportingReason = "AAA";
			arInvoiceLine1.ComplianceSupportingDocumentType = "AAA";
			arInvoiceLine1.ComplianceSupportingDocumentNumber = "456";
			var orgHeader2 = TestObjectCreator.CreateOrgHeader("YYY", true, true);
			var arInvoiceLine2 = TestObjectCreator.CreateARInvoiceLine(arInvoice, null, TestObjectCreator.FRT, TestObjectCreator.LocalCurrency, 2, "test 2", 0);
			arInvoiceLine2.AL_AT = TestObjectCreator.CAP.PK;
			arInvoiceLine2.ComplianceDocumentNumber = "456";
			arInvoiceLine2.ComplianceDocumentVATRegistrationNum = "234";
			arInvoiceLine2.CreateComplianceDocumentRecordOnPosting = true;
			arInvoiceLine2.ComplianceDocumentDate = ZDateTime.Today;
			arInvoiceLine2.ComplianceDocumentSupportingReason = "AAA";
			arInvoiceLine2.ComplianceSupportingDocumentType = "AAA";
			arInvoiceLine2.ComplianceSupportingDocumentNumber = "456";
			arInvoiceLine2.ComplianceDocumentReportingPeriod = 201803;

			new ComplianceDocumentCreator(new[] { arInvoice }, OrganisationCreateComplianceDocumentOnPostingTypes.RollupByCharge).CreateComplianceDocumentRecords();
			Factory.Save();

			var complianceDocuments = arInvoice.GetAllTransactionGeneratedComplianceDocument();
			AssertNotNull("invoice has generated compliance document", complianceDocuments);
			AssertEquals("invoice has two compliance document headers", 2, complianceDocuments.Length);

			var arComplianceDocuments = Factory.Load<ARComplianceDocumentHeader>(complianceDocuments[0].PK);
			arComplianceDocuments.Void();
			Factory.Save();

			complianceDocuments = arInvoice.GetAllTransactionGeneratedComplianceDocument();
			AssertNotNull("invoice has generated compliance document", complianceDocuments);
			AssertEquals("invoice has two compliance documents", 1, complianceDocuments.Length);
		}

		void TestOSTaxAmtEqualsLocalTaxAmtWhenAdjustLocalRoundedValuesCore(string currency, decimal exchangeRate, decimal osGSTAmountCals, decimal expectedLocalTaxAmount)
		{
			if (InvoicingBase is APInvoice || InvoicingBase is APCreditNote)
			{
				var consol = TestObjectCreator.CreateConsol();
				var shipment = TestObjectCreator.CreateShipment("SHP001", consol);
				TestObjectCreator.CreateJob(shipment, false);
				Factory.Save();

				var invoice = (InvoicingBase)Factory.New(GetExpectedBusinessObjectType());
				var line = (InvoicingLineBase)invoice.Lines.AddNew();
				line.AL_RX_NKTransactionCurrency = currency;
				line.AL_ExchangeRate = exchangeRate;
				line.AL_OSTaxAmount = 5144m;
				using (line.GetOSAmountCalculationSuspender())
				{
					line.AL_LocalTaxAmount = line.AL_LocalTaxAmount + 0.1m;
				}

				var invoiceCost = TestObjectCreator.CreateConsolCost(invoice, consol, TestObjectCreator.CC1, 28581m);
				invoiceCost.E6_RX_NKCurrency = currency;
				invoiceCost.E6_ExchangeRate = exchangeRate;
				invoiceCost.E6_AT_TaxRate = TestObjectCreator.IntegratedGST.PK;
				invoiceCost.E6_OSGSTAmount_Calc = osGSTAmountCals;

				AssertEquals("Pre-condition", 1, invoiceCost.ApportionmentCharges.Count);
				line.ApportionmentChargeImportedFrom = invoiceCost.ApportionmentCharges[0];

				invoice.AdjustLocalRoundedValuesForImportedConsolCosts_ForTestOnly();
				AssertEquals("os tax amount on line", 5144m, line.AL_OSTaxAmount);
				AssertEquals("local tax amount on line", expectedLocalTaxAmount, line.AL_LocalTaxAmount);
			}
			else
			{
				Assert(true);
			}
		}

