					var consolCost = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC1, GlbCompany.CurrentCompany.LocalCurrency, 1m, 50000m, TestObjectCreator.Creditor1);
					consolCost.E6_ApportionmentMethod = "SHP";
					consolCost.E6_IsTaxAmountOverridden = true;
					consolCost.E6_AT_TaxRate = TestObjectCreator.CAP.PK;
					Factory.Save();

					AssertEquals("Pre-condition", 9000m, consolCost.E6_OSGSTAmount);

					var invoice = Factory.NewWithValidTestData(GetExpectedBusinessObjectType()) as InvoicingBase;
					invoice.AH_OH = TestObjectCreator.Creditor1.PK;
					var newConsolCost = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
					var importer = new InvoicingBaseConsolCostImporter(Factory, newConsolCost, invoice);
					importer.ImportCostsIntoCosting(new BusinessObject[] { consolCost });
					invoice.ImportAllApportionmentsFromCosting();
					invoice.SetContext(BusinessContext.ImportMultipleInvoicesWithSameTransformer);

					var invertSigns = (invoice is APCreditNote) ? -1 : 1;
					AssertEquals("Pre-condition", 5, invoice.Lines.Count);
					AssertEquals("os tax amount on line 1", 1800m * invertSigns, invoice.Lines[0].AL_OSTaxAmount);
					AssertEquals("local tax amount on line 1", 1800m * invertSigns, invoice.Lines[0].AL_LocalTaxAmount);
					AssertEquals("os tax amount on line 2", 1800m * invertSigns, invoice.Lines[1].AL_OSTaxAmount);
					AssertEquals("local tax amount on line 2", 1800m * invertSigns, invoice.Lines[1].AL_LocalTaxAmount);
					AssertEquals("os tax amount on line 3", 1800m * invertSigns, invoice.Lines[2].AL_OSTaxAmount);
					AssertEquals("local tax amount on line 3", 1800m * invertSigns, invoice.Lines[2].AL_LocalTaxAmount);
					AssertEquals("os tax amount on line 4", 1800m * invertSigns, invoice.Lines[3].AL_OSTaxAmount);
					AssertEquals("local tax amount on line 4", 1800m * invertSigns, invoice.Lines[3].AL_LocalTaxAmount);
					AssertEquals("os tax amount on line 5", 1800m * invertSigns, invoice.Lines[4].AL_OSTaxAmount);
					AssertEquals("local tax amount on line 5", 1800m * invertSigns, invoice.Lines[4].AL_LocalTaxAmount);
				}
			}
			else
			{
				Assert(true);
			}
		}

