		public void TestAddTransactionNumLog()
		{
			if (!InvoicingBase.CanUpdateTransactionNumber())
			{
				Assert("Not applicable.", true);
				return;
			}

			Factory.SetContext(BusinessContext.OverrideInvoiceReference);

			InvoicingBase.AH_TransactionNum = "0001";
			Factory.Save();

			ZQuery filter = new ZQuery(StmALogSchema.SL_SE_NKEvent, Events.EditedARecord.Code);
			string expectedReference = "Invoice Transaction Number changed from '0001' to '0002'";
			filter.AddToFilter(StmALogSchema.SL_Reference, SQLComparisonOperator.StartsWith, expectedReference);
			StmALog[] logs = InvoicingBase.Logs.Find(filter);
			AssertEquals("Transaction num edited log shouldn't be added.", 0, logs.Length);

			InvoicingBase.AH_TransactionNum = "0002";
			Factory.Save();

			logs = InvoicingBase.Logs.Find(filter);
			if (InvoicingBase.AH_Ledger == LedgerTypes.AccountsPayable)
			{
				AssertEquals("Log contains one record.", 1, logs.Length);
				AssertEquals("Transaction num edited log should be added.", expectedReference, logs[0].SL_Reference);
			}
			else
			{
				AssertEquals("Transaction num edited log shouldn't be added.", 0, logs.Length);
			}
		}

