		public void TestAdjustLocalRoundedValuesForImportedConsolCostsSuspender()
		{
			if (GetExpectedBusinessObjectType() == typeof(TransactionPendingAllocation))
			{
				Assert("TransactionPendingAllocation does not allow adding Lines", true);
				return;
			}

			var consol = Factory.NewWithValidTestData<ForwardingConsol>();
			Factory.Save();
			consol.Shipments.AddNew();
			consol.Shipments.AddNew();

			var invoice = (InvoicingBase)Factory.New(GetExpectedBusinessObjectType());
			var testLineCollection = invoice.Lines;

			try
			{
				var cost1 = CreateConsolCostForSuspenderTest(10m);
				InvoicingBase.CallsToAdjustLocalRoundedValuesForImportedConsolCosts_TestOnly = 0;
				invoice.ImportSingleCost(cost1, (InvoicingLineBase)testLineCollection.AddNew());
				AssertEquals("AdjustLocalRoundedValuesForImportedConsolCosts() is called when suspended is not active.", 1, InvoicingBase.CallsToAdjustLocalRoundedValuesForImportedConsolCosts_TestOnly);

				var cost2 = CreateConsolCostForSuspenderTest(20m);
				InvoicingBase.CallsToAdjustLocalRoundedValuesForImportedConsolCosts_TestOnly = 0;
				using (invoice.BeginImportingManyConsoleCosts())
				{
					invoice.ImportSingleCost(cost2, (InvoicingLineBase)testLineCollection.AddNew());
					AssertEquals("AdjustLocalRoundedValuesForImportedConsolCosts() is not called when suspended is active.", 0, InvoicingBase.CallsToAdjustLocalRoundedValuesForImportedConsolCosts_TestOnly);
				}
				AssertEquals("AdjustLocalRoundedValuesForImportedConsolCosts() is called when suspender completes.", 1, InvoicingBase.CallsToAdjustLocalRoundedValuesForImportedConsolCosts_TestOnly);

				var cost3 = CreateConsolCostForSuspenderTest(30m);
				var cost4 = CreateConsolCostForSuspenderTest(40m);
				var cost5 = CreateConsolCostForSuspenderTest(50m);
				InvoicingBase.CallsToAdjustLocalRoundedValuesForImportedConsolCosts_TestOnly = 0;
				using (invoice.BeginImportingManyConsoleCosts())
				{
					using (invoice.BeginImportingManyConsoleCosts())
					{
						invoice.ImportSingleCost(cost3, (InvoicingLineBase)testLineCollection.AddNew());
						AssertEquals("AdjustLocalRoundedValuesForImportedConsolCosts() is not called when suspender is active and nested.", 0, InvoicingBase.CallsToAdjustLocalRoundedValuesForImportedConsolCosts_TestOnly);
					}

					invoice.ImportSingleCost(cost4, (InvoicingLineBase)testLineCollection.AddNew());
					invoice.ImportSingleCost(cost5, (InvoicingLineBase)testLineCollection.AddNew());
					AssertEquals("AdjustLocalRoundedValuesForImportedConsolCosts() is not called when suspender is active and multiple ImportSingleCost() calls.", 0, InvoicingBase.CallsToAdjustLocalRoundedValuesForImportedConsolCosts_TestOnly);
				}
				AssertEquals("AdjustLocalRoundedValuesForImportedConsolCosts() is called when suspender completes.", 1, InvoicingBase.CallsToAdjustLocalRoundedValuesForImportedConsolCosts_TestOnly);
			}
			finally
			{
				invoice.ClearApportionmentJobMutexes();
			}

			JobConsolCost CreateConsolCostForSuspenderTest(decimal amount)
			{
				var cost = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
				cost.E6_AC_ChargeCode = TestObjectCreator.CC1.PK;
				cost.E6_OSCostAmount = amount;
				cost.E6_ApportionmentMethod = "SHP";
				cost.SetIsUsedForApportionment();
				return cost;
			}
		}

