		public void TestPopulateFromOriginalTransaction_IsRoundingLine()
		{
			if (InvoicingBase.Ledger_ForTestOnly == LedgerTypes.AccountsReceivable &&
				(InvoicingBase.TransactionType_ForTestOnly == TransactionTypes.Invoice || InvoicingBase.TransactionType_ForTestOnly == TransactionTypes.CreditNote))
			{
				var originalTransaction = GetNewBusinessObject() as InvoicingBase;
				originalTransaction.Lines.AddNew();

				var invoiceRoundingLineCreator = new Mock<IInvoiceRoundingLineCreator>(MockBehavior.Strict);
				invoiceRoundingLineCreator.Setup(x => x.IsRoundingLine(It.IsAny<InvoicingLineBase>())).Returns(true);
				InvoicingBase.SubstituteInvoiceRoundingLineCreator_ForTestOnly(invoiceRoundingLineCreator.Object);

				InvoicingBase.PopulateFromOriginalTransaction(originalTransaction);
				invoiceRoundingLineCreator.Verify(x => x.IsRoundingLine(It.IsAny<InvoicingLineBase>()), Times.Once);
				AssertEquals(0, InvoicingBase.Lines.Count);

				invoiceRoundingLineCreator.Reset();
				invoiceRoundingLineCreator.Setup(x => x.IsRoundingLine(It.IsAny<InvoicingLineBase>())).Returns(false);

				InvoicingBase.PopulateFromOriginalTransaction(originalTransaction);
				invoiceRoundingLineCreator.Verify(x => x.IsRoundingLine(It.IsAny<InvoicingLineBase>()), Times.Once);
				AssertEquals(1, InvoicingBase.Lines.Count);
			}
			else
			{
				Assert("Not Applicable", true);
			}
		}

		[TestDate(2020, 12, 21)]
		public void TestSetConsolCostBasedOnSelfBilling()
		{
			var consol = TestObjectCreator.CreateConsol();
			var forwardingShipment = TestObjectCreator.CreateShipment("S00003000", consol);
			var shipmentJob = TestObjectCreator.CreateJob(forwardingShipment, false);
			TestObjectCreator.SetExchangeRate(shipmentJob, TestObjectCreator.USD, 1.3m);
			var consolCost1 = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC1, TestObjectCreator.USD, 1.5m, 150m, TestObjectCreator.AALSHI);
			Factory.Save();

			var invoice = TestObjectCreator.CreateInvoice(typeof(APInvoice));
			invoice.IsSelfBillingInvoice = true;

			var today = ZDateTime.Now;
			invoice.AH_InvoiceDate = today;
			invoice.AH_DocumentReceivedDate = today;
			invoice.AH_DueDate = today;
			var originatingCost = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			var newFactory = new BusinessObjectFactory();
			var importer = new InvoicingBaseConsolCostImporter(newFactory, originatingCost, invoice);

			importer.ImportCostsIntoCosting(new BusinessObject[] { consolCost1 });
			AssertEquals(1, invoice.ConsolCosting.ConsolCosts.Count);

			foreach (JobConsolCost consolCost in invoice.ConsolCosting.ConsolCosts)
			{
				consolCost.E6_InvoiceNum = string.Empty;
				consolCost.E6_InvoiceDate = ZDateTime.Empty;
				consolCost.E6_DocumentReceivedDate = ZDateTime.Empty;
				consolCost.E6_PaymentDate = ZDateTime.Empty;
			}

			AssertEquals(1, invoice.ConsolCosting.ConsolCosts.Count);
			foreach (JobConsolCost consolCost in invoice.ConsolCosting.ConsolCosts)
			{
				AssertEquals(string.Empty, consolCost.E6_InvoiceNum);
				AssertEquals(ZDateTime.Empty, consolCost.E6_InvoiceDate);
				AssertEquals(ZDateTime.Empty, consolCost.E6_DocumentReceivedDate);
				AssertEquals(ZDateTime.Empty, consolCost.E6_PaymentDate);
			}

			invoice.IsSelfBillingInvoice = false;

			foreach (JobConsolCost consolCost in invoice.ConsolCosting.ConsolCosts)
			{
				AssertEquals(invoice.AH_TransactionNum, consolCost.E6_InvoiceNum);
				AssertEquals(today.ToDateTime(), consolCost.E6_InvoiceDate);
				AssertEquals(today.ToDateTime(), consolCost.E6_DocumentReceivedDate);
				AssertEquals(today.ToDateTime(), consolCost.E6_PaymentDate);
			}

			foreach (JobConsolCost consolCost in invoice.ConsolCosting.ConsolCosts)
			{
				consolCost.E6_InvoiceNum = string.Empty;
				consolCost.E6_InvoiceDate = ZDateTime.Empty;
				consolCost.E6_DocumentReceivedDate = ZDateTime.Empty;
				consolCost.E6_PaymentDate = ZDateTime.Empty;
			}

			invoice.IsSelfBillingInvoice = true;

			foreach (JobConsolCost consolCost in invoice.ConsolCosting.ConsolCosts)
			{
				AssertEquals(string.Empty, consolCost.E6_InvoiceNum);
				AssertEquals(ZDateTime.Empty, consolCost.E6_InvoiceDate);
				AssertEquals(ZDateTime.Empty, consolCost.E6_DocumentReceivedDate);
				AssertEquals(ZDateTime.Empty, consolCost.E6_PaymentDate);
			}
		}

