		public void TestGenerateReverseTransactionCore_SetTaxBranch()
		{
			if (GetExpectedBusinessObjectType().IsAssignableFrom(typeof(TransactionHeaderWithLines)))
			{
				var branch = TestObjectCreator.CreateBranch("TST", GlbCompany.CurrentCompany);
				var branch1 = TestObjectCreator.CreateBranch("TS1", GlbCompany.CurrentCompany);
				var branch2 = TestObjectCreator.CreateBranch("TS2", GlbCompany.CurrentCompany);
				var originalTransaction = TestObjectCreator.CreateInvoice(GetExpectedBusinessObjectType(), TestObjectCreator.AUD, 1M, TestObjectCreator.ABIGAS);

				originalTransaction.AH_GB_TaxBranch = branch.PK;

				var line = TestObjectCreator.CreateInvoiceLine(originalTransaction, 300.89M, TestObjectCreator.AUD, 1M, null, false);
				line.AL_AT = TaxRate.PK;
				line.AL_TaxDate = new ZDate(2017, 05, 05);
				line.AL_GB_TaxBranch = branch1.PK;

				var line2 = TestObjectCreator.CreateInvoiceLine(originalTransaction, 397.48M, TestObjectCreator.AUD, 1M, null, false);
				line2.AL_AT = TaxRate.PK;
				line2.AL_TaxDate = new ZDate(2017, 05, 05);
				line2.AL_GB_TaxBranch = branch2.PK;

				Factory.Save();

				originalTransaction.GenerateReverseTransactionCore_ForTestOnly(false);

				var reverseTransaction = (InvoicingBase)originalTransaction.ReverseTransaction;

				AssertEquals("AH_GB_TaxBranch", branch.PK, reverseTransaction.AH_GB_TaxBranch);
				AssertEquals("line 1 AL_GB_TaxBranch", branch1.PK, reverseTransaction.Lines[0].AL_GB_TaxBranch);
				AssertEquals("line 2 AL_GB_TaxBranch", branch2.PK, reverseTransaction.Lines[1].AL_GB_TaxBranch);
			}
			else
			{
				Assert(true);
			}
		}

		public void TestCopyTransactionLineWithTaxCodeChange()
		{
			var taxRateIva = TestObjectCreator.CreateTaxRate("IVA", "Standard Rate", "RAT", 13, "", 0, 1);
			var taxRateIvaexon = TestObjectCreator.CreateTaxRate("IVAEXON", "Standard Rate", "RAT", 13, "SPV", 0, 1);

			var accFactory = new BusinessObjectFactory();
			var chargeCode = accFactory.NewWithValidTestData<AccChargeCode>();
			chargeCode.AC_AT_GSTRate = taxRateIva.PK;

			var fromInvoice = (InvoicingBase)Factory.New(typeof(APInvoice));
			fromInvoice.GSTInclusiveAmounts = false;
			var fromInvoiceLine = (InvoicingLineBase)fromInvoice.Lines.AddNew();
			fromInvoiceLine.AL_RX_NKTransactionCurrency = TestObjectCreator.AUD.RX_Code;
			fromInvoiceLine.AL_AC = chargeCode.PK;
			fromInvoiceLine.AL_OSExTaxAmount = 100m;

			fromInvoiceLine.AL_AT = taxRateIvaexon.PK;

			AssertEquals(100m, fromInvoice.AH_OSExTaxAmount);
			AssertEquals(0m, fromInvoice.AH_OSTaxAmount);
			AssertEquals(100m, fromInvoice.AH_OSTotalAmount);
			AssertEquals(-13m, fromInvoice.AH_OSExtraTaxAmount);

			var toInvoice = (InvoicingBase)Factory.New(typeof(APInvoice));
			var toInvoiceLine = (InvoicingLineBase)toInvoice.Lines.AddNew();
			fromInvoice.CopyTransactionLine_ForTestOnly(fromInvoiceLine, toInvoiceLine);

			AssertEquals(100m, toInvoice.AH_OSExTaxAmount);
			AssertEquals(0m, toInvoice.AH_OSTaxAmount);
			AssertEquals(100m, toInvoice.AH_OSTotalAmount);
			AssertEquals(-13m, toInvoice.AH_OSExtraTaxAmount);
		}

		public void TestCopyTransactionLineWithChargeTaxCodeChangedAndTaxBranchEnabled()
		{
			using (GlbCompany.CurrentCompany.TemporarilySetCountry(CountryCodes.Australia))
			using (AccountingMasterFilesRegistry.Instance.EnableBranchLevelTaxOverrideRuleConfigurations.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true))
			using (AccountingMasterFilesRegistry.Instance.EnableTaxBranchReporting.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true))
			{
				Assert("Pre-condition: Company is GST registered", GlbCompany.CurrentCompany.GC_IsGSTRegistered);
				Assert("Pre-condition: Tax branch should be applicable", AccountingMasterFilesUtils.IsTaxBranchApplicable);

				var taxRateIva = TestObjectCreator.CreateTaxRate("IVA", "Standard Rate", "RAT", 13, "", 0, 1);
				var taxRateIvaexon = TestObjectCreator.CreateTaxRate("IVAEXON", "Standard Rate", "RAT", 26, "SPV", 0, 1);

				var accFactory = new BusinessObjectFactory();
				var chargeCode = accFactory.NewWithValidTestData<AccChargeCode>();
				chargeCode.AC_AT_GSTRate = taxRateIva.PK;
				accFactory.Save();

				var fromInvoice = TestObjectCreator.CreateInvoiceWithLine(typeof(APInvoice), "AP001", TestObjectCreator.AUD, 0m, 0m, 0m, 0m, 0m, TestObjectCreator.Creditor1, chargeCode.PK, ZDateTime.Today, postToGL: true);
				var fromInvoiceLine = fromInvoice.Lines[0];

				chargeCode.AC_AT_GSTRate = taxRateIvaexon.PK;
				accFactory.Save();

				var toInvoice = TestObjectCreator.CreateInvoice(typeof(APInvoice), "AP002", organisation: TestObjectCreator.Creditor2);
				var toInvoideLine = TestObjectCreator.CreateInvoiceLine(toInvoice, TestObjectCreator.AUD, exchangeRate: 0m, 0m);

				Assert("Pre-condition: New invoice line should be GST mandatory", toInvoideLine.IsGSTMandatory);
				chargeCode.ClearGSTRateCacheForTesting();
				fromInvoice.CopyTransactionLine_ForTestOnly(fromInvoiceLine, toInvoideLine);

				Assert("GST Tax ID on copied invoice line should be the same as it on the origin", toInvoideLine.AL_AT == fromInvoiceLine.AL_AT);
			}
		}

