		protected void AssertAH_Calc_AmendStatusCode(Func<InvoicingBase> getNewBusinessObjectCore, string expectedAmendStatusCodeFromDB = "01", string expectedAmendStatusCodeFromBizO = "02")
		{
			AssertAH_Calc_AmendStatusCode_ReferenceDeletedWithInvoice(getNewBusinessObjectCore());
			AssertAH_Calc_AmendStatusCode_ReferenceNotCreatedWhenEmptyValue(getNewBusinessObjectCore());
			AssertAH_Calc_AmendStatusCode_ReferenceCreated(getNewBusinessObjectCore());

			void AssertAH_Calc_AmendStatusCode_ReferenceDeletedWithInvoice(InvoicingBase invoicingBase)
			{
				AssertNull("PreCondition", GetAmendStatusCodeReference(Factory, invoicingBase));

				invoicingBase.AH_Calc_AmendStatusCode = "01";
				var amendStatusCodeReference = GetAmendStatusCodeReference(Factory, invoicingBase);
				AssertEquals("We use Reference to store AH_Calc_AmendStatusCode setting value.", expectedAmendStatusCodeFromDB, amendStatusCodeReference?.AH1_Reference ?? ZString.Empty);

				if (amendStatusCodeReference != null)
				{
					amendStatusCodeReference.AH1_Reference = "02";
				}
				AssertEquals("We use Reference to store AH_Calc_AmendStatusCode setting value.", expectedAmendStatusCodeFromBizO, invoicingBase.AH_Calc_AmendStatusCode);

				invoicingBase.Delete();
				Factory.Save();
				AssertNull("Reference should be cleared after being deleted", GetAmendStatusCodeReference(new BusinessObjectFactory(), invoicingBase));
			}

			void AssertAH_Calc_AmendStatusCode_ReferenceNotCreatedWhenEmptyValue(InvoicingBase invoicingBase)
			{
				AssertNull("PreCondition", GetAmendStatusCodeReference(Factory, invoicingBase));

				invoicingBase.AH_Calc_AmendStatusCode = "01";
				var amendStatusCodeReference = GetAmendStatusCodeReference(Factory, invoicingBase);
				AssertEquals("We use Reference to store AH_Calc_AmendStatusCode setting value.", expectedAmendStatusCodeFromDB, amendStatusCodeReference?.AH1_Reference ?? ZString.Empty);

				invoicingBase.AH_Calc_AmendStatusCode = ZString.Empty;
				Factory.Save();
				AssertNull("Reference should not be created when AH_Calc_AmendStatusCode is empty", GetAmendStatusCodeReference(new BusinessObjectFactory(), invoicingBase));
			}

			void AssertAH_Calc_AmendStatusCode_ReferenceCreated(InvoicingBase invoicingBase)
			{
				AssertNull("PreCondition", GetAmendStatusCodeReference(Factory, invoicingBase));

				invoicingBase.AH_Calc_AmendStatusCode = "01";
				var amendStatusCodeReference = GetAmendStatusCodeReference(Factory, invoicingBase);
				AssertEquals("We use Reference to store AH_Calc_AmendStatusCode setting value.", expectedAmendStatusCodeFromDB, amendStatusCodeReference?.AH1_Reference ?? ZString.Empty);

				if (amendStatusCodeReference != null)
				{
					amendStatusCodeReference.AH1_Reference = "02";
				}
				AssertEquals("We use Reference to store AH_Calc_AmendStatusCode setting value.", expectedAmendStatusCodeFromBizO, invoicingBase.AH_Calc_AmendStatusCode);

				Factory.Save();
				if (expectedAmendStatusCodeFromDB.IsNullOrEmpty())
				{
					AssertNull("Reference should not be created when AH_Calc_AmendStatusCode is not supported", GetAmendStatusCodeReference(new BusinessObjectFactory(), invoicingBase));
				}
				else
				{
					AssertNotNull("Reference should be created when AH_Calc_AmendStatusCode is not empty", GetAmendStatusCodeReference(new BusinessObjectFactory(), invoicingBase));
				}
			}
		}

		protected AccTransactionHeaderReference GetAmendStatusCodeReference(BusinessObjectFactory factory, InvoicingBase invoicingBase)
		{
			var amendStatusCodeInstanceProvider = ObjectFactory.Get<IGlobalAccountingCountryFactory>().GetCountryFactory(GlbCompany.CurrentCompany.Country.Code) as IInstanceProvider<IAmendStatusCodeProvider>;
			var amendStatusCodeProvider = amendStatusCodeInstanceProvider?.Get();
			return factory.LoadTop1<AccTransactionHeaderReference>(
				new ZQuery(AccTransactionHeaderReferenceSchema.AH1_AH, invoicingBase.PK)
				.AddToFilter(AccTransactionHeaderReferenceSchema.AH1_Type, amendStatusCodeProvider?.AmendStatusCodeReferenceType ?? ZString.Empty)
			);
		}

