		[SuspendCriticalValidation]
		protected virtual void ComplianceWarning(ZString country,
			bool supressWarningWhenThereIsNoComplianceBookSetups,
			bool isComplianceSequenceFailedToAssign,
			short expectedEventCount, string prefix)
		{
			using (GlbCompany.CurrentCompany.TemporarilySetCountry(country))
			{
				AccountingConfigurationRegistry.Instance.
					SuppressWarningWhenThereIsNoComplianceBookSetups.
					SetTemporaryValue(Env.CurrentCompanyPK,
						Guid.Empty,
						Guid.Empty,
						supressWarningWhenThereIsNoComplianceBookSetups);

				var type = GetExpectedBusinessObjectType();
				var invoice = TestObjectCreator.CreateInvoiceWithLine(type, "Inv" + prefix, TestObjectCreator.AUD, 1, 100, 10, 100, 10);
				invoice.IsComplianceSequenceFailedToAssign_ForTestOnly = isComplianceSequenceFailedToAssign;

				var invoiceLine = invoice.Lines[0];
				invoiceLine.AL_AT = TestObjectCreator.GST1.PK;
				invoiceLine.AL_OSAmount = 100;
				invoiceLine.AL_GovtChargeCode = "random text";

				short eventRaised = 0;
				invoice.OnComplianceSequenceFailedToAssign += delegate
				{
					eventRaised++;
				};

				Env.Instance.Registry.ShowSaveProgressBox = false;

				Factory.Save();

				var expectWarning = supressWarningWhenThereIsNoComplianceBookSetups ? " " : " not ";
				AssertEquals($"Compliance Warning Dialog Box{expectWarning}" +
									$"Expected when invoice of type {type.FullName} is saved for {country}",
									expectedEventCount, eventRaised);
			}
		}

		public void TestHookComplianceDocumentRelatedProperties()
		{
			if ((InvoicingBase.AH_Ledger == LedgerTypes.AccountsReceivable || InvoicingBase.AH_Ledger == LedgerTypes.AccountsPayable)
				&& (InvoicingBase.AH_TransactionType == TransactionTypes.Invoice || InvoicingBase.AH_TransactionType == TransactionTypes.CreditNote))
			{
				using (AccountingMasterFilesRegistry.Instance.EnableComplianceDocumentModule.SetTemporaryValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, true))
				{
					InvoicingBase.AH_OH = TestObjectCreator.ActiveOrg.PK;
					InvoicingBase.Header.CompanyData.OB_ARCreateVATComplianceDocumentOnPosting = OrganisationCreateComplianceDocumentOnPostingTypes.RollupByCharge;
					InvoicingBase.Header.CompanyData.OB_APCreateVATComplianceDocumentOnPosting = OrganisationCreateComplianceDocumentOnPostingTypes.RollupByCharge;
					InvoicingBase.Lines.Cast<InvoicingLineBase>().ForEach(x => x.AL_AT = TestObjectCreator.GST1.PK);

					InvoicingBase.OnFactorySavingBeforeTransactionCore_ForTestOnly();

					var callStack = @"
Call stack:
   at System.Environment.GetStackTrace(Exception e, Boolean needFileInfo)";

					var oldAH_Desc = InvoicingBase.AH_Desc;
					InvoicingBase.AH_Desc = "123";
					Assert(ExceptionReporterTestListener.Instance[0].InnerException.Message.Contains($"AH_Desc changed from {oldAH_Desc} to 123.{callStack}"));
					ExceptionReporterTestListener.Instance.Clear();

					var oldAH_Ledger = InvoicingBase.AH_Ledger;
					InvoicingBase.AH_Ledger = "CB";
					Assert(ExceptionReporterTestListener.Instance[0].InnerException.Message.Contains($"AH_Ledger changed from {oldAH_Ledger} to CB.{callStack}"));
					ExceptionReporterTestListener.Instance.Clear();

					var oldTransactionType = InvoicingBase.AH_TransactionType;
					InvoicingBase.AH_TransactionType = "ORC";
					Assert(ExceptionReporterTestListener.Instance[0].InnerException.Message.Contains($"AH_TransactionType changed from {oldTransactionType} to ORC.{callStack}"));
					ExceptionReporterTestListener.Instance.Clear();

					var oldAH_GC = InvoicingBase.AH_GC;
					InvoicingBase.AH_GC = TestObjectCreator.NonCurrentCompany.PK;
					Assert(ExceptionReporterTestListener.Instance[0].InnerException.Message.Contains($"AH_GC changed from {oldAH_GC} to {TestObjectCreator.NonCurrentCompany.PK}.{callStack}"));
					ExceptionReporterTestListener.Instance.Clear();

					var oldAH_OH = InvoicingBase.AH_OH;
					InvoicingBase.AH_OH = TestObjectCreator.Debtor.PK;
					Assert(ExceptionReporterTestListener.Instance[0].InnerException.Message.Contains($"AH_OH changed from {oldAH_OH} to {TestObjectCreator.Debtor.PK}.{callStack}"));
					ExceptionReporterTestListener.Instance.Clear();

					var oldAH_OA_InvoiceAddressOverride = InvoicingBase.AH_OA_InvoiceAddressOverride;
					InvoicingBase.AH_OA_InvoiceAddressOverride = TestObjectCreator.Debtor.Addresses[0].PK;
					Assert(ExceptionReporterTestListener.Instance[0].InnerException.Message.Contains($"AH_OA_InvoiceAddressOverride changed from {oldAH_OA_InvoiceAddressOverride} to {TestObjectCreator.Debtor.Addresses[0].PK}.{callStack}"));
					ExceptionReporterTestListener.Instance.Clear();

					var oldAL_Desc = InvoicingBase.Lines[0].AL_Desc;
					InvoicingBase.Lines[0].AL_Desc = "123";
					Assert(ExceptionReporterTestListener.Instance[0].InnerException.Message.Contains($"AL_Desc changed from {oldAL_Desc} to 123.{callStack}"));
					ExceptionReporterTestListener.Instance.Clear();

					var oldAL_AG = InvoicingBase.Lines[0].AL_AG;
					InvoicingBase.Lines[0].AL_AG = TestObjectCreator.CashAtBankAccount.PK;
					Assert(ExceptionReporterTestListener.Instance[0].InnerException.Message.Contains($"AL_AG changed from {oldAL_AG} to {TestObjectCreator.CashAtBankAccount.PK}.{callStack}"));
					ExceptionReporterTestListener.Instance.Clear();

					var oldAL_AC = InvoicingBase.Lines[0].AL_AC;
					InvoicingBase.Lines[0].AL_AC = TestObjectCreator.FRT.PK;
					Assert(ExceptionReporterTestListener.Instance[0].InnerException.Message.Contains($"AL_AC changed from {oldAL_AC} to {TestObjectCreator.FRT.PK}.{callStack}"));
					ExceptionReporterTestListener.Instance.Clear();
				}
			}
			else
			{
				Assert(true);
			}
		}

