		public void TestInvoiceTaxDate()
		{
			var creator = new TestObjectCreator(Factory);
			var taxRate = Factory.NewWithValidTestData<AccTaxRate>();
			var taxRateExempt = AccTaxRate.FindExistingTaxRate(Factory, "EXEMPT", AccTaxRate.Types.Exempt, Constants.CountryCodes.SaudiArabia);

			var invoice = (InvoicingBase)Factory.New(GetExpectedBusinessObjectType());
			var orgHeader = Factory.NewWithValidTestData<OrgHeader>();
			orgHeader.OH_RL_NKClosestPort = "ITROM";
			invoice.AH_OH = orgHeader.PK;
			invoice.AH_InvoiceDate = new ZDateTime(2022, 8, 30);

			Assert(invoice.InvoiceTaxDate.IsEmpty);

			if (invoice.Lines.AllowNew)
			{
				var line1 = invoice.Lines.AddNew();
				line1.AL_AG = creator.GLHeader1.PK;
				var chargeCode1 = creator.CreateChargeCode("BOLLO", "Stamp Duty", Constants.ChargeType.Revenue, 1m, taxRateExempt, creator.WHTFREE1);
				line1.AL_AC = chargeCode1.PK;
				line1.AL_AT = taxRate.PK;
				line1.AL_TaxDate = new ZDate(2022, 9, 2);

				AssertEquals(new ZDate(2022, 9, 2), invoice.InvoiceTaxDate);

				var line2 = invoice.Lines.AddNew();
				line2.AL_AG = creator.GLHeader1.PK;
				var chargeCode2 = creator.CreateChargeCode("CMT", "Stamp Duty", Constants.ChargeType.Comment, 1m, taxRateExempt, creator.WHTFREE1);
				line2.AL_AC = chargeCode2.PK;
				line2.AL_AT = taxRate.PK;
				line2.AL_TaxDate = new ZDate(2022, 9, 1);

				AssertEquals(new ZDate(2022, 9, 2), invoice.InvoiceTaxDate);

				var line3 = invoice.Lines.AddNew();
				line3.AL_AG = creator.GLHeader1.PK;
				var chargeCode3 = creator.CreateChargeCode("MGR100", "Stamp Duty", Constants.ChargeType.Margin, 100m, taxRateExempt, creator.WHTFREE1);
				line3.AL_AC = chargeCode3.PK;
				line3.AL_AT = taxRate.PK;
				line3.AL_TaxDate = new ZDate(2022, 8, 31);

				AssertEquals(new ZDate(2022, 8, 31), invoice.InvoiceTaxDate);
			}
		}

		public void TestCreateJobDocAddress()
		{
			using (GlbCompany.CurrentCompany.TemporarilySetCountry(CountryCodes.Portugal))
			{
				AccountingConfigurationRegistry.Instance.PrintBranchAddressInFooter.SetValue(Guid.Empty, GlbBranch.CurrentBranch.PK.ToGuid(), Guid.Empty, true);
				AccountingConfigurationRegistry.Instance.ARStoreAndUseInvoiceIssuerAndRecepientInformationDuringPostWhenPrinting.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, true);

				var invoice = TestObjectCreator.CreateARInvoice<ARInvoice>("AR001", TestObjectCreator.AUD, 1m, TestObjectCreator.Debtor);

				var branchAddressForSendingARDocuments = TestObjectCreator.ABIGAS.Addresses.AddNew(OrgAddressType.Receivables, true);
