		public void TestRateType_WithCurrencyCriteria()
		{
			TestCaseHelper.ClearTable(AccJobConfigPivotSchema.Constants.TableName);
			TestCaseHelper.ClearTable(AccExchangeRateConfigurationViewSchema.Constants.TableName);
			var masterTestObjectCreator = new MasterFiles.Business.Testing.Accounting.Helpers.AccountingTestObjectCreator(Factory);

			var config_AllCur = masterTestObjectCreator.CreateAccExchangeRateConfiguration(AccExRateConfigurationLevelEnum.System, ZGuid.Empty, "AR", "ALL", "ALL", "ALL", currencyCodes: null);
			config_AllCur.GetCurrencyConfig(ZString.Empty, ZDate.Empty).JCT_ExRateType = Constants.ExchangeRateTypes.Code.C01Rate;
			var config_USD = masterTestObjectCreator.CreateAccExchangeRateConfiguration(AccExRateConfigurationLevelEnum.System, ZGuid.Empty, string.Empty, "ALL", "ALL", "ALL", currencyCodes: new string[] { Constants.CurrencyCodes.UnitedStates });
			config_USD.GetCurrencyConfig(Constants.CurrencyCodes.UnitedStates, ZDate.Empty).JCT_ExRateType = Constants.ExchangeRateTypes.Code.C02Rate;
			Factory.Save();

			var invoice = TestObjectCreator.CreateARInvoice<ARInvoice>("AR001", TestObjectCreator.AUD, 1m, TestObjectCreator.Debtor);

			invoice.AH_RX_NKTransactionCurrency = TestObjectCreator.EUR.RX_Code;
			AssertEquals("Should get rate type from config_AllCur.", ExchangeRateType.C01, invoice.RateType);

			invoice.AH_RX_NKTransactionCurrency = TestObjectCreator.USD.RX_Code;
			AssertEquals("Should get rate type from config_USD, even the ledger is not specified.", ExchangeRateType.C02, invoice.RateType);
		}

