		public void TestUSSalesTax_WhenShouldSetSalesTaxOnPost_WithErrorFromCalculate()
		{
			var mockCalculator = new Mock<IUSSalesTaxCalculator>();
			mockCalculator.Setup(x => x.IsEnabled(It.IsAny<GlbBranch>())).Returns(true);
			mockCalculator.Setup(x => x.ShouldSetSalesTaxOnPost(It.IsAny<InvoicingBase>())).Returns(true);
			mockCalculator.Setup(x => x.GetTransactionDetailsForIssueManager(It.IsAny<InvoicingBase>())).Returns("Additional details to identify the transaction and assist troubleshooting.");
			var calculationResult = new USSalesTax.CalculationResult(5m);
			var calculationError = new ApplicationException("Error. Nope. Fail.");
			mockCalculator.Setup(x => x.CalculateSalesTax(It.IsAny<InvoicingBase>())).Returns((calculationResult, calculationError));
			using (ObjectFactory.Substitute(mockCalculator.Object))
			{
				ErrorReporter.Clear();
				SetupForSave();
				Factory.Save();

				mockCalculator.Verify(x => x.CalculateSalesTax(It.IsAny<InvoicingBase>()), Times.Once(), "When invoice is eligible for US Sales Tax, CalculateSalesTax() should be called");
				mockCalculator.Verify(x => x.SetSalesTaxLineItem(It.IsAny<InvoicingBase>(), It.IsAny<decimal>()), Times.Never(), "When error, SetSalesTaxLineItem() should not be called");
				mockCalculator.Verify(x => x.SubmitSalesTax(It.IsAny<InvoicingBase>()), Times.Never(), "When error, SubmitSalesTax() should not be called");

				CombineAssertions("Errors are reported until a future work item", () =>
				{
					AssertSame(calculationError, ErrorReporter.LastExceptionReported);
					AssertEquals("USSalesTaxCalculation.OnPosting", ErrorReporter.LastKeyReported);
					AssertEquals(@"Error when calculating US Sales Tax.
Additional details to identify the transaction and assist troubleshooting.", ErrorReporter.LastMessageReported);
					AssertEquals(1, ErrorReporter.TotalErrorCount);
				});
				ErrorReporter.Clear();
			}
		}

