		public void TestUSSalesTax_ExternalCalculatorObject_IsNotDisposedAfterPost()
		{
			var mockCalculator = new Mock<IUSSalesTaxCalculator>();
			mockCalculator.Setup(x => x.IsEnabled(It.IsAny<GlbBranch>())).Returns(true);
			mockCalculator.Setup(x => x.ShouldSetSalesTaxOnPost(It.IsAny<InvoicingBase>())).Returns(true);
			var calculationResult = new USSalesTax.CalculationResult(5m);
			mockCalculator.Setup(x => x.CalculateSalesTax(It.IsAny<InvoicingBase>())).Returns((calculationResult, null));
			mockCalculator.Setup(x => x.SubmitSalesTax(It.IsAny<InvoicingBase>())).Returns((calculationResult, null));

			var mockCalculatorExternal = new Mock<IUSSalesTaxCalculator>();
			mockCalculatorExternal.Setup(x => x.IsEnabled(It.IsAny<GlbBranch>())).Returns(true);
			mockCalculatorExternal.Setup(x => x.ShouldSetSalesTaxOnPost(It.IsAny<InvoicingBase>())).Returns(true);
			mockCalculatorExternal.Setup(x => x.CalculateSalesTax(It.IsAny<InvoicingBase>())).Returns((calculationResult, null));
			mockCalculatorExternal.Setup(x => x.SubmitSalesTax(It.IsAny<InvoicingBase>())).Returns((calculationResult, null));

			using (ObjectFactory.Substitute(mockCalculator.Object))
			{
				InvoicingBase.USSalesTaxCalculator = mockCalculatorExternal.Object;

				SetupForSave();
				Factory.Save();

				AssertSame("When an external object is used, it should not be overwritten", mockCalculatorExternal.Object, InvoicingBase.USSalesTaxCalculator);
				mockCalculatorExternal.Verify(x => x.Dispose(), Times.Never(), "Calculator object passed externally should not be disposed after post");

				mockCalculator.Verify(x => x.IsEnabled(It.IsAny<GlbBranch>()), Times.Never(), "ObjectFactory object should not be used when external object is passed");
				mockCalculator.Verify(x => x.ShouldSetSalesTaxOnPost(It.IsAny<InvoicingBase>()), Times.Never(), "ObjectFactory object should not be used when external object is passed");
				mockCalculator.Verify(x => x.CalculateSalesTax(It.IsAny<InvoicingBase>()), Times.Never(), "ObjectFactory object should not be used when external object is passed");
				mockCalculator.Verify(x => x.SubmitSalesTax(It.IsAny<InvoicingBase>()), Times.Never(), "ObjectFactory object should not be used when external object is passed");
			}
		}

