		public void TestIsExpectedTaxTotalVisible_IsTrue_OnlyWhenOrganizationIsAPTaxApplicableAndCompanyIsGSTRegistered()
		{
			var orgHeader = TestObjectCreator.CreateOrgHeader("BORG", true, false);
			var apInvoice = Factory.New<APInvoice>();
			apInvoice.AH_OH = orgHeader.PK;

			orgHeader.CompanyData.SetAPTaxApplicable(true);
			apInvoice.Company.GC_IsGSTRegistered = false;
			Assert("Precondition - Organisation is AP tax applicable", orgHeader.CompanyData.IsAPTaxApplicable);
			Assert("Precondition - GST not enabled on invoice company", !apInvoice.Company.GC_IsGSTRegistered);
			Assert("IsExpectedTaxTotalVisible should be false", !apInvoice.IsExpectedTaxTotalVisible);

			orgHeader.CompanyData.SetAPTaxApplicable(false);
			apInvoice.Company.GC_IsGSTRegistered = true;
			Assert("Precondition - Organisation is not AP tax applicable", !orgHeader.CompanyData.IsAPTaxApplicable);
			Assert("Precondition - GST enabled on invoice company", apInvoice.Company.GC_IsGSTRegistered);
			Assert("IsExpectedTaxTotalVisible should be false", !apInvoice.IsExpectedTaxTotalVisible);

			orgHeader.CompanyData.SetAPTaxApplicable(false);
			apInvoice.Company.GC_IsGSTRegistered = false;
			Assert("Precondition - Organisation is not AP tax applicable", !orgHeader.CompanyData.IsAPTaxApplicable);
			Assert("Precondition - GST not enabled on invoice company", !apInvoice.Company.GC_IsGSTRegistered);
			Assert("IsExpectedTaxTotalVisible should be false", !apInvoice.IsExpectedTaxTotalVisible);

			orgHeader.CompanyData.SetAPTaxApplicable(true);
			apInvoice.Company.GC_IsGSTRegistered = true;
			Assert("Precondition - Organisation is AP tax applicable", orgHeader.CompanyData.IsAPTaxApplicable);
			Assert("Precondition - GST enabled on invoice company", apInvoice.Company.GC_IsGSTRegistered);
			Assert("IsExpectedTaxTotalVisible should be true", apInvoice.IsExpectedTaxTotalVisible);
		}

		protected override void CreateAndAssertInvoiceTaxDate()
		{
			var invoice = PrepareTransactionHeaderForTest() as InvoicingBase;
			var taxDate = ZDate.Today;
			var invoiceDate = new ZDate(2024, 9, 1);
			invoice.AH_InvoiceDate = invoiceDate;
			var line1 = invoice.Lines.AddNew();
			line1.AL_AC = TestObjectCreator.CC1.PK;
			line1.AL_AT = TestObjectCreator.GST1.PK;
			line1.AL_TaxDate = taxDate;
			AssertEquals(taxDate, invoice.InvoiceTaxDate);

			var taxDate2 = new ZDate(2024, 8, 31);
			var line2 = invoice.Lines.AddNew() as InvoicingLineBase;
			line2.AL_AC = TestObjectCreator.CC1.PK;
			line2.AL_AT = TestObjectCreator.GST1.PK;
			line2.AL_TaxDate = taxDate2;
			line2.AL_AH = ZGuid.Empty;
			AssertEquals(taxDate2, invoice.InvoiceTaxDate);
		}

