		void PrepareTestDataForSetExchangeRateForInvoicePostingExchangeRateOptionEIT()
		{
			var postingExRateRegistry = InvoicingBase.GetExRateLedger() == ExchangeRateValidLedgerEnum.AR
			  ? AccountingConfigurationRegistry.Instance.InvoicePostingExchangeRateOptionAR
			  : AccountingConfigurationRegistry.Instance.InvoicePostingExchangeRateOptionAP;
			var collection = new InvoicePostingExRateOptionCollection();
			collection.Add(new InvoicePostingExRateOption(Core.Constants.InvoicePostingExchangeRateCurrencyType.Code.Foreign, ExRateOption.EarliestOfInvoiceOrTaxDate.Code, 0));
			collection.Add(new InvoicePostingExRateOption(Core.Constants.InvoicePostingExchangeRateCurrencyType.Code.Local, ExRateOption.EarliestOfInvoiceOrTaxDate.Code, 0));
			postingExRateRegistry.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, collection);

			TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, ExchangeRateTypes.Code.BuyRate, 0.5m, ZDateTime.Today.AddDays(-5), ZDateTime.Today.AddDays(5));
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.USD, ExchangeRateTypes.Code.SellRate, 0.5m, ZDateTime.Today.AddDays(-5), ZDateTime.Today.AddDays(5));
			TestObjectCreator.CreateExchangeRate(GlbCompany.CurrentCompany.LocalCurrency, ExchangeRateTypes.Code.BuyRate, 1m, ZDateTime.Today.AddDays(-5), ZDateTime.Today.AddDays(5));
			TestObjectCreator.CreateExchangeRate(GlbCompany.CurrentCompany.LocalCurrency, ExchangeRateTypes.Code.SellRate, 1m, ZDateTime.Today.AddDays(-5), ZDateTime.Today.AddDays(5));
		}

		public void TestSetAH_XD_ComplianceBookEmptyError()
		{
			var aUCompanyAndBranch = TestObjectCreator.CreateCompanyAndBranch(CountryCodes.Australia, null);
			var vNCompanyAndBranch = TestObjectCreator.CreateCompanyAndBranch(CountryCodes.VietNam, null);
			Factory.Save();

			AccountingMasterFilesRegistry.Instance.EnableEInvoicingFunctionality.SetValue(vNCompanyAndBranch.Company.PK.ToGuid(), Guid.Empty, Guid.Empty, true);
			AccountingMasterFilesRegistry.Instance.EnableEInvoicingFunctionality.SetValue(aUCompanyAndBranch.Company.PK.ToGuid(), Guid.Empty, Guid.Empty, true);

			var periodicInvoice = TestObjectCreator.CreateARInvoice<ARInvoice>("002", TestObjectCreator.AUD, 1.0m, TestObjectCreator.Debtor);
			InvoicingBase.AH_Ledger = LedgerTypes.AccountsReceivable;
			InvoicingBase.AH_TransactionCategory = InvoiceTypesList.Codes.FinalInvoice_Batching;
			InvoicingBase.AH_GC = vNCompanyAndBranch.Company.PK;
			InvoicingBase.AH_GB = vNCompanyAndBranch.Branch.PK;
			InvoicingBase.AH_TransactionReference = "TEST";

			ErrorReporter.Clear();
			InvoicingBase.AH_XD_ComplianceBook = ZGuid.Empty;
			AssertContains("Set AH_XD_ComplianceBook to empty for VN AR Periodic Invoice which EnableEInvoicingFunctionality is Yes and AH_TransactionReference is not empty.", ErrorReporter.LastMessageReported);

			ErrorReporter.Clear();
			InvoicingBase.AH_GC = aUCompanyAndBranch.Company.PK;
			InvoicingBase.AH_GB = aUCompanyAndBranch.Branch.PK;
			InvoicingBase.AH_XD_ComplianceBook = ZGuid.Empty;
			AssertEquals("Not report error for non VN company.", string.Empty, ErrorReporter.LastMessageReported);

			InvoicingBase.AH_GC = vNCompanyAndBranch.Company.PK;
			InvoicingBase.AH_GB = vNCompanyAndBranch.Branch.PK;
			InvoicingBase.AH_TransactionReference = string.Empty;
			InvoicingBase.AH_XD_ComplianceBook = ZGuid.Empty;
			AssertEquals("Not report error when AH_TransactionReference is empty.", string.Empty, ErrorReporter.LastMessageReported);

			InvoicingBase.AH_TransactionReference = "TEST";
			InvoicingBase.AH_TransactionCategory = InvoiceTypesList.Codes.FinalInvoice;
			InvoicingBase.AH_XD_ComplianceBook = ZGuid.Empty;
			AssertEquals("Not report error when is not periodic invoice.", string.Empty, ErrorReporter.LastMessageReported);

			InvoicingBase.AH_TransactionCategory = InvoiceTypesList.Codes.FinalInvoice_Batching;
			InvoicingBase.AH_Ledger = LedgerTypes.AccountsPayable;
			InvoicingBase.AH_XD_ComplianceBook = ZGuid.Empty;
			AssertEquals("Not report error when is not AR.", string.Empty, ErrorReporter.LastMessageReported);

			InvoicingBase.AH_Ledger = LedgerTypes.AccountsReceivable;
			AccountingMasterFilesRegistry.Instance.EnableEInvoicingFunctionality.SetValue(vNCompanyAndBranch.Company.PK.ToGuid(), Guid.Empty, Guid.Empty, false);
			InvoicingBase.AH_XD_ComplianceBook = ZGuid.Empty;
			AssertEquals("Not report error when EnableEInvoicingFunctionality is false.", string.Empty, ErrorReporter.LastMessageReported);
		}

