		{
			var relatedInvoice = (InvoicingBase)GetNewBusinessObject();
			relatedInvoice.AH_TransactionNum = "INV001";

			var invoice = (InvoicingBase)GetNewBusinessObject();
			invoice.AH_TransactionNum = "INV002";
			invoice.ReceivableDisbursementInvoicePK = relatedInvoice.PK;
			Factory.Save();

			if (invoice.Ledger_ForTestOnly == LedgerTypes.AccountsReceivable && invoice.TransactionType_ForTestOnly == TransactionTypes.Invoice)
			{
				var newFactory = new BusinessObjectFactory();
				var reference = newFactory.LoadTop1<AccTransactionHeaderReference>(new ZQuery(AccTransactionHeaderReferenceSchema.AH1_Type, AccountingMasterFilesConstants.AccTransactionHeaderReferenceTypes.ReceivableDisbursementInvoice));

				AssertNotNull("Reference", reference);
				AssertEquals("Disbursement Invoice PK", invoice.ReceivableDisbursementInvoicePK, reference.AH1_AH);
				AssertEquals("Reference Number", invoice.AH_TransactionNum, reference.AH1_Reference);
			}
			else
			{
				Assert(true);
			}
		}

		TaxFrameworkTestObjectCreator TaxFrameworkObjectCreator => taxFrameworkObjectCreator ?? (taxFrameworkObjectCreator = new TaxFrameworkTestObjectCreator(Factory));
		TaxFrameworkTestObjectCreator taxFrameworkObjectCreator;

		InvoicingBase HeaderAsInvoicingBase => (InvoicingBase)Header;
	}
}
